-- ============================================================================
-- 208 — اصلاح عيوب النص الناتجة عن استخراج PDF فى 1202 مادة من 64 وثيقة (قوانين وقرارات ولوائح) بلا فقدان
-- ----------------------------------------------------------------------------
-- العيوب المعالَجة (كلها تغيير فى الشكل لا فى الحرف أو الرقم):
--   1) أرقام عربية-هندية/فارسية → لاتينية، "٪" → "%"، والياء/الكاف الفارسية → العربية.
--   2) حذف رموز منطقة الاستخدام الخاص (علامة مائية/مزخرفات خط قديم) وفاصل الصفحة \f.
--   3) فصل التنوين والحركات عن حرفها (يلصقها) وحذف التطويل (ـ) بين الحروف.
--   4) حذف ترويسات صفحات الوقائع المصرية الدخيلة وسط المتن وأرقام الصفحات الملتصقة بها.
--   5) عكس ترقيم البنود ("-1" → "1-") وإعادة الأقواس المبعثرة ") (1" → "(1)" مع ترتيب الأرقام المعكوسة.
--   6) رقم لاصق بكلمة ("15لسنة") → رقم ثم مسافة، وطى الأسطر الفارغة المتتالية.
--
-- الطريقة: لكل مادة نص نهائى مُعدّ ومُختبَر سلفاً، ولا يُطبَّق إلا إذا كان md5 النص الحالى مطابقاً للنص المتوقع قبل الإصلاح
-- (فلا تُمس مادة تغيّر نصها بعد القياس). التحقق خارج الهجرة قبل توليدها: لكل مادة الحروف العربية/اللاتينية متطابقة حرفاً بحرف
-- (بعد استبعاد الترويسات الدخيلة) ومجموعة الأعداد متطابقة — أى لا يضيع رقم ولا حرف.
-- النص القديم يُحفظ فى جدول migration_208_backup للتراجع. نصوص article_versions المطابقة للمادة تُحدَّث معها.
-- embeddings لا تُمس (المعنى لم يتغير). قابلة لإعادة التشغيل: ما أُصلح سابقاً يُتخطى.
-- لا تُفشل الهجرة النشر إذا اختلف نص مادة عن المتوقع؛ تُتخطى وتُسجَّل فى NOTICE. الإخفاق يقع فقط عند خرق سلامة (عدد المواد/النسخ، أو md5 النتيجة).
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_208_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_208_backup_art ON migration_208_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_208_backup_ver ON migration_208_backup (version_id) WHERE version_id IS NOT NULL;

CREATE TEMP TABLE m208_fix (
  kind text NOT NULL, law_no int NOT NULL, law_year int NOT NULL, article_no int NOT NULL, suffix int NOT NULL,
  old_md5 text NOT NULL, new_md5 text NOT NULL, new_body text NOT NULL
) ON COMMIT DROP;

