 مؤشرات خاصة بأنشطة الأوراق المالية :<<CR>>
 1- عمليات تغذية الحساب بمبالغ كبيرة ثم سحبها دون إتمام أية عمليات ودون<<CR>>
 وجود مبرر واضح من العميل .<<CR>>
 2- العمليات التى تتم بمبالغ كبيرة بما لا يتناسب مع نشاط العميل أو مستوى دخله .<<CR>>
 3- اتجاه العميل نحو العمليات أو الصفقات التى تشير إلى افتقاره للحس<<CR>>
