 4- العملاء الذين يبدون لا مبالاة تجاه المخاطر أو العمولات أو غيرها من<<CR>>
 تكاليف العمليات على الأوراق المالية .<<CR>>
 5- تكرار طلبات تحويل مبالغ من حساب العميل إلى حسابات أخرى بالشركة<<CR>>
 دون مبرر واضح .<<CR>>
 6- العمليات المتكررة التى لا يتناسب مجموعها خلال فترة زمنية معينة مع<<CR>>
