 7- عدم اهتمام العميل فى معظم الأحيان بما تقدمه الشركة من نصائح استثمارية .<<CR>>
 8- العمليات التى يتم تمويلها عن طريق شيكات مصرفية أو أية أدوات مالية<<CR>>
