 3- شراء وثائق تأمين أو طلب زيادة قيمتها بمبالغ كبيرة بما لا يتناسب مع نشاط العميل .<<CR>>
 4- تكرار شراء وثائق تأمين بمبالغ لا يتناسب مجموعها خلال فترة زمنية معينة<<CR>>
 مع نشاط العميل .<<CR>>
 5- طلب العميل تغطية تأمينية خارج نطاق النشاط المعتاد له .<<CR>>
 6- توافر معلومات تفيد قيام طالب التأمين بالحصول على وثائق تأمينية من عدة<<CR>>
 شركات لذات التغطية التأمينية .<<CR>>
 7- التعاقد على وثيقة بقسط وحيد أو بمبلغ كبير بما يخالف نمط التعاملات<<CR>>
 السابقة للعميل .<<CR>>
 8- طلب العميل زيادة قيمة وثيقة التأمين بمبلغ كبير يسدد على دفعة واحدة .<<CR>>
 9- التعاقد على وثائق بمبالغ كبيرة وطلب استردادها أو تغيير المستفيد بعد فترة<<CR>>
 قصيرة من التعاقد دون مبرر واضح .<<CR>>
 10- طلب العميل اقتراض الحد الأقصى من قيمة وثيقة ذات قسط وحيد بعد فترة<<CR>>
 قصيرة من التعاقد وسداد قيمتها دون مبرر واضح .<<CR>>
 11- سداد قيمة أو أقساط وثيقة التأمين بواسطة تحويلات من أطراف أجنبية<<CR>>
