 4- الإيداعات النقدية الكبيرة أو المتكررة التى تودعها جهات مختلفة لحساب أحد<<CR>>
 العملاء دون أن يكون هناك ثمة علاقة بين هذه الجهات والعميل .<<CR>>

 مؤشرات خاصة بالتخصيم :<<CR>>
 1- عدم مبالاة العميل بتكلفة التمويل .<<CR>>
