يتعين على المخاطبين بأحكام هذا القرار الالتزام بما تضمنته الإرشادات<<CR>>
التفصيلية الصادرة عن الوحدة بشأن تنفيذ قرارات مجلس الأمن الخاصة بالعقوبات<<CR>>
المالية المستهدفة ذات الصلة بالإرهاب وتمويله وتمويل انتشار أسلحة الدمار الشامل،<<CR>>
وعلى وجه الأخص فيما يتعلق بقوائم عقوبات مجلس الأمن المتعلقة بالإرهاب وتمويله<<CR>>
وتمويل أسلحة الدمار الشامل وقائمتى الكيانات الإرهابية والإرهابيين بما فى ذلك<<CR>>
 الواردة بالملحق رقم (1) المرفق بهذا القرار ،وذلك على النحو الآتى:<<CR>>
 1- أن تتضمن السياسة الداخلية أو إجراءات عمل الجهة ،أهمية تطبيق العقوبات<<CR>>
المالية المستهدفة دون تأخير وما يتبع ذلك من إجراءات وهى التجميد أو رفع التجميد<<CR>>
 الفورى ،وكذا ما يفيد إخطار الوحدة والهيئة بذلك.<<CR>>

 2- أن تتضمن سياسة إدارة المخاطر وقبول العملاء المطبقة بالجهة ،المخاطر<<CR>>
المتعلقة بالأشخاص والجهات المدرجين على القوائم السلبية وتحديد الإجراءات<<CR>>
 المناسبة للتعامل معها ،على أن يتم مراجعة وتحديث هذا التصنيف بشكل دورى.<<CR>>
 3- تعميم الإرشادات الصادرة عن الوحدة على كافة فروع الجهات المخاطبة بهذا<<CR>>
 القرار ،والفهم الجيد لتلك الإرشادات لدى العاملين بها.<<CR>>
 4- تعميم إجراءات العناية الواجبة بالعملاء على كافة فروع الجهات المخاطبة<<CR>>
