 ) المادة الحادية والعشرون (<<CR>>
 التزامات المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
 يلتزم المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب بالمهام الآتية:<<CR>>
 1- فحص العمليات غير العادية التى تستخرج من الأنظمة الداخلية للمؤسسات<<CR>>
المالية ،والعمليات الواردة بتقارير الاشتباه الداخلية ،والعمليات التى أثير الاشتباه فيها<<CR>>
 بناء على معلومات وردت من أية جهة أخرى أو معلومات نمت إلى عمله.<<CR>>
 2- إخطار الوحدة بالعمليات التى يشتبه فى أنها تشكل متحصلات أو تتضمن<<CR>>
غسل أموال أو تمويل إرهاب ،بما فى ذلك محاولات إجراء هذه العمليات ،بغض<<CR>>
 النظر عن قيمتها وبالشكل الذى يكفل الحفاظ على سرية المعلومات بها.<<CR>>
 3- اتخاذ القرارات بشأن حفظ العمليات التى تم فحصها وتبين له عدم وجود أية<<CR>>
 شبهة بشأنها على أن يتضمن القرار الأسباب التى استند إليها فى الحفظ.<<CR>>
 4- اقتراح ما يراه لازما من تطوير وتحديث للسياسة المتبعة فى الجهة التى<<CR>>
يعمل بها بشأن مجال مكافحة غسل الأموال وتمويل الإرهاب وكذا النظم والإجراءات<<CR>>
المتبعة بها فى هذا المجال وذلك بهدف زيادة فاعليتها وكفاءتها ومواكبتها المستجدات<<CR>>
 المحلية والعالمية.<<CR>>

 5- الإشراف العام مكتبيا وميدانيا ،بنفسه أو من خلال الاستعانة بالإدارات<<CR>>
بالجهة التى يعمل بها للتأكد من مدى التزام المركز الرئيسى لها وفروعها بتطبيق<<CR>>
أحكام القانون ولائحته التنفيذية والقواعد والضوابط الرقابية ذات الصلة بمكافحة غسل<<CR>>
 الأموال وتمويل الإرهاب والنظم والإجراءات الداخلية الموضوعة فى هذا الشأن .<<CR>>
 6- التعاون والتنسيق مع الإدارات المعينة بالجهة التى يعمل بها فى شأن وضع<<CR>>
خطط التدريب الداخلية والخارجية فى مجال مكافحة غسل الأموال وتمويل الإرهاب<<CR>>
 للعاملين بها ،واقتراح البرامج التدريبية اللازمة لتنفيذ هذه الخطط ،ومتابعة التنفيذ.<<CR>>
 7- التسجيل على موقع الوحدة لاستلام التحديثات الخاصة بالتعديلات على قوائم<<CR>>
 مجلس الأمن وقائمتى الكيانات الإرهابية والإرهابيين المحلية.<<CR>>
