 6- بيان عدد الاشتراكات الجديدة وقيمتها وعدد المشتركين الذين توقفوا خلال<<CR>>
 العام وقيمة اشتراكاتهم وفقًا للنموذج التى تعده الهيئة فى هذا الشأن .<<CR>>
 7- بيان بعدد المطالبات التى قدمت للصندوق خلال العام وقيمتها ومقدار المزايا<<CR>>
 التأمينية التى تمت سدادها خلال العام وتلك التى ما تزال تحت التسوية .<<CR>>
