 للسلوك المهنى .<<CR>>
 5- يلتزم المسئول عن المراجعة الداخلية بإعداد تقريرا ربع سنويا -يتم تقديمه<<CR>>
للمدير التنفيذى للصندوق أو لجنة المراجعة بحسب الأحوال -عن نشاط وملاحظات<<CR>>
