('board_decision',236,2024,51,0,'796b8e2236971c19ef9c9f18b86cead5','e8846fc892db79f5884031cbe53f4343',replace($m208$يجوز بقرار من الهيئة الترخيص للصندوق بناء على طلبه الاندماج أو تحويل<<CR>>
