('board_decision',236,2024,53,0,'95b4903bc1e4dd73f12aa00e11a2ff66','08e74ff959b7bb83737fed56251a242a',replace($m208$تصدر الهيئة قرار تصفية الصندوق فى الحالات الآتية :<<CR>>
