وفى الحالات الثلاث الأخيرة ينذر الصندوق بالمخالفات ويمنح مهلة ثلاثين يوما<<CR>>
 لإبداء دفاعه وفى حالة عدم تصحيح وضعه يصفى الصندوق .<<CR>>

