 من شئون الصندوق إلا بأمر كتابى منها .$m208$,'<<CR>>',chr(13))),
('board_decision',236,2024,54,0,'2e82e74396f9624f1e981a0138391a3c','aaabdebad00f78bec29b13f1be348736',replace($m208$يشطب قيد الصندوق فى الأحوال الآتية :<<CR>>
 1- إذا توقف الصندوق عن مباشرة أعماله .<<CR>>
 2- إذا اندمج الصندوق فى صندوق آخر أو تم تحويله إلى وثيقة تأمين جماعية<<CR>>
 بذات الأعضاء .<<CR>>
 3- بعد انتهاء إجراءات تصفية الصندوق .<<CR>>
على أن تؤول صافى أموال الصندوق إلى الأعضاء فى تاريخ التصفية ويوزع<<CR>>
عليهم ناتج التصفية وفقًا لتقرير الخبير الإكتوارى واعتماد الهيئة ،وتعامل مساهمة<<CR>>
