('board_decision',236,2024,57,0,'01d8aa4bd856c5daa2ae96fe3f19045f','1200abf52f6cc5667dab53374c2ffa0b',replace($m208$على القائمين على إدارة الصندوق أن يضعوا تحت تصرف أعضائه جميع<<CR>>
البيانات الواجب تقديمها إلى الهيئة وفقا لأحكام المادتين (73 ، 74) من قانون التأمين<<CR>>
الموحد والقرارات الصادرة تنفيذًا له وأن تسلم نسخة منها إلى من يطلبها من الأعضاء<<CR>>
