 وفقًا للشروط والأوضاع التى يضعها مجلس إدارة الهيئة .$m208$,'<<CR>>',chr(13))),
('board_decision',237,2024,2,0,'a6ab5e027916e8cdf89657f3f9d55970','ad8c384d0cc8f3b9e9df636471c7a654',replace($m208$ضوابط تسجيل صناديق التأمين الخاصة لدى الهيئة<<CR>>
يقدم المفوض من مؤسسى صندوق التأمين الخاص طلب تسجيل الصندوق لدى<<CR>>
 الهيئة على النموذج المعد منها لهذا الغرض مرفقًا به المستندات الآتية :<<CR>>
 1- نسختان معتمدتان من النظام الأساسى للصندوق .<<CR>>
 2- الدراسة الإكتوارية المعدة من أحد الخبراء الإكتواريين المسجلين لدى الهيئة<<CR>>
 وفقًا للشروط والضوابط والقواعد التى يحددها مجلس إدارة الهيئة .<<CR>>
 3- بيان بأسماء وصفة وعناوين الأشخاص القائمين على إدارة الصندوق .<<CR>>

 4- البيانات والمستندات التى ترى الهيئة ضرورة تقديمها للتحقق من أن إيرادات<<CR>>
 الصندوق تكفى لتغطية التزاماته .<<CR>>
 5- ما يفيد سداد الرسم المقرر لقيد الصندوق لدى الهيئة ،وكذا سداد قيمة<<CR>>
 مصروفات النشر .<<CR>>
 6- تقديم ما يثبت وجود مقر رئيسى دائم للصندوق مع الإقرار بأنه فى حال تغيير<<CR>>
 هذا المقر يتم موافاة الهيئة بالمقر الجديد .<<CR>>
 7- أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها .<<CR>>
وتقوم الهيئة بدراسة طلب قيد الصندوق لديها وتبت فيه خلال ثلاثين يوما<<CR>>
من تاريخ استيفاء الاشتراطات المتطلبة فى هذا الشأن ،وفى حال الموافقة على طلب<<CR>>
القيد يصدر رئيس الهيئة أو من يفوضه قرار قيد الصندوق وتدون بياناته فى السجل<<CR>>
المنشأ لهذا الغرض على أن يتضمن قرار القيد تحديد أغراض الصندوق واشتراكاته<<CR>>
والمزايا التى يقررها لأعضائه ،وينشر هذا القرار على الموقع الإلكترونى الذى<<CR>>
تخصصه الهيئة لهذا الغرض على نفقة الصندوق وعلى الموقع الإلكترونى للصندوق ،<<CR>>
وفى حال رفض طلب قيد الصندوق يتم إخطار المفوض من المؤسسين بأسباب<<CR>>
الرفض كتابة بموجب كتاب مسجل مصحوب بعلم الوصول أو إخطاره بالاستيفاءات<<CR>>
 المطلوبة فى هذا الشأن وذلك خلال خمسة عشر يوما من تاريخ صدور قرار الرفض .<<CR>>
وفى جميع الأحوال ،لا يجوز للصندوق مزاولة نشاطه إلا بعد تمام القيد<<CR>>
 فى سجل الهيئة ويعد ذلك ترخيصا بمزاولة النشاط .$m208$,'<<CR>>',chr(13))),
('board_decision',237,2024,3,0,'cf213dfe79189465662abc6beccd2bec','c5fb90c72f79f132423b3a18f9294958',replace($m208$الشروط الواجب توافرها فى النظام الأساسى لصناديق التأمين الخاصة<<CR>>
يجب أن يكون النظام الأساسى لصندوق التأمين الخاص وفقًا للنموذج الصادر<<CR>>
 عن مجلس إدارة الهيئة فى هذا الشأن ،على أن يتضمن على وجه الأخص ما يلى :<<CR>>
 1- اسم الصندوق وعنوان مركزه الرئيسى ،والغرض من إنشائه .<<CR>>
 2- تاريخ تأسيس الصندوق ،وتاريخ احتساب المزايا وتحصيل الاشتراكات ،<<CR>>
 وتاريخ التسجيل .<<CR>>

 3- تعريف وتحديد أجر الاشتراك بالنسبة لتحصيل الاشتراكات وصرف<<CR>>
 المزايا التأمينية .<<CR>>
 4- شروط الانضمام لعضوية الصندوق وتحديد رسم الانضمام والحد الأقصى<<CR>>
 لسن الانضمام ،وتحديد قيمة الاشتراكات ورسوم العضوية .<<CR>>
 5- تعريف العضو المؤسس .<<CR>>
 6- الأحوال التى تزول فيها صفة العضوية ومنها :<<CR>>
 )أ( بلوغ سن التقاعد .<<CR>>
 )ب( الوفاة .<<CR>>
 )ج( العجز المنهى للخدمة )جزئى /كلي( .<<CR>>
 )د( النقل )إجبارى /اختياري( .<<CR>>
 )ه( الاستقالة من الخدمة .<<CR>>
 )و( الفصل من الخدمة .<<CR>>
 )ز( المعاش المبكر .<<CR>>
 )ح( الاستقالة أو الانسحاب من الصندوق .<<CR>>
 )ط( الفصل من الصندوق .<<CR>>
 )ي( أى أسباب أخرى يقترحها الصندوق وتوافق عليها الهيئة .<<CR>>
 7- معالجة حالات الأعضاء الذين تنتهى خدمتهم بالعجز الجزئى المنهى للخدمة ،<<CR>>
والذين ينقلون إجباريا إلى جهات عمل أخرى ،وحالات الإعارة أو الندب<<CR>>
 أو الإجازات بدون مرتب .<<CR>>
 8- معالجة الحالات التى تسترد فيها العضوية ،وبيان حقوق والتزامات<<CR>>
 الأعضاء فى هذه الحالات .<<CR>>
 9- بيان القواعد والإجراءات التى تنظم حالات الخروج الجماعى ،أيا كان سببه<<CR>>
وعلى سبيل المثال :الخروج الجماعى الاختيارى أو بسبب الانسحابات أو الاستقالات<<CR>>
 الجماعية أو بسبب العجز الصحى .<<CR>>
 10- تحديد الجزاءات المترتبة على مخالفة العضو لأحكام النظام الأساسى<<CR>>
للصندوق ؛ وعلى الأخص فيما يتعلق بالتأخير عن سداد الاشتراكات والتوقف<<CR>>
 عن سدادها .<<CR>>

 11- جداول الاشتراكات ومواعيد استحقاقها .<<CR>>
 12- المزايا المالية والتعويضات والمعاشات المحددة التى يلتزم الصندوق<<CR>>
 بسدادها ومواعيد استحقاقها .<<CR>>
 13- تحديد الموارد المالية للصندوق ،والتى تبنى عليها الدراسات الإكتوارية .<<CR>>
 14- قواعد استثمار أموال الصندوق .<<CR>>
 15- الحد الأقصى للنسبة المئوية التى تخصص من موارد الصندوق<<CR>>
 للمصروفات الإدارية .<<CR>>
 16- القواعد الخاصة بتشكيل مجلس الإدارة واختصاصاته .<<CR>>
