يقبلها المشترك وغيرها من البيانات والمؤشرات التى تحدد استثمارات الصندوق ،وذلك<<CR>>
مع عدم الإخلال بالأسس الاكتوارية للصندوق -إن وجدت -وتقدير الاستثمارات والعائد<<CR>>
 المتوقع منها وتناسبها مع التزامات الصندوق بحسب الأحوال .<<CR>>
 3- أن يضع القواعد لقيام المشترك باختيار الأوعية الاستثمارية أو الادخارية<<CR>>
