('board_decision',276,2024,2,0,'4476bee5cd98882e6789460e0b15b116','7dd49a9d084dc03c161f3fdfba686252',replace($m208$يجب أن تتضمن القوائم المالية الدورية لصناديق التأمين الخاصة المشار إليها<<CR>>
 بالمادة السابقة ما يلى :<<CR>>
 1- قائمة المركز المالى ،على أن تعد على أساس مجمع فى تاريخ نهاية الفترة<<CR>>
 المعد عنها القوائم مقارنة بتاريخ نهاية السنة المالية السابقة مباشرة .<<CR>>

 2- قائمة الدخل عن الفترة المعد عنها القوائم ،على أن تُعد على أساس مجمع<<CR>>
من بداية السنة المالية حتى تاريخ إعداد قائمة الدخل مع قوائم الدخل المقارنة عن<<CR>>
 الفترات الدورية المقابلة خلال السنة السابقة مباشرة .<<CR>>
 3- نموذج حركة العضوية .<<CR>>
 4- تقرير مجلس الإدارة عن نشاط الصندوق لتلك الفترة .<<CR>>
 5- الإيضاحات المتممة متضمنة أهم السياسات المحاسبية وأية مذكرات<<CR>>
