('board_decision',278,2024,2,0,'07e5bb21e5bd7452a05bdd5daa08db7c','3dbd802051899a5227cf8f75057b77d1',replace($m208$يشترط أن يتوافر فى العضوين المرشحين من ذوى الخبرة بمجالس إدارة<<CR>>
 صناديق التأمين الخاصة ما يلى :<<CR>>
 1- أن يكون محمود السيرة حسن السمعة .<<CR>>
 2- أن يكون لديهم خبرة لا تقل عن سبع سنوات فى مجال التأمين أو الاستثمار<<CR>>
أو القانون ،على أن يكون أحدهما على الأقل لديه خبرة فى مجال التأمين<<CR>>
 أو الاستثمار .<<CR>>

 3- عدم الجمع بين عضوية مجلس إدارة الصندوق والعمل به .<<CR>>
 4- التعهد بإخطار مجلس الإدارة عن كافة المعلومات والبيانات التى تتعلق<<CR>>
بوجود أى من حالات تعارض المصالح مع الصندوق ،وكذا الإفصاح عن أية مصالح<<CR>>
مادية أو تعاملات أو أمور تخصهم يكون من شأنها التأثير على الصندوق وأوجه<<CR>>
استثمارات أمواله ،مع عدم اشتراك العضو المعنى الذى تتعلق حالة تعارض المصالح<<CR>>
 به فى حضور الاجتماع والتصويت على القرار .<<CR>>
 5- ألا يكون قد سبق الحكم عليه بحكم نهائى بعقوبة جنائية ،أو بعقوبة جنحة فى<<CR>>
جريمة ماسة للشرف أو الأمانة أو فى إحدى الجرائم الجسيمة المنصوص عليها<<CR>>
بالقوانين المنظمة للأنشطة المالية غير المصرفية أو المنصوص عليها فى قانون البنك<<CR>>
المركزى والجهاز المصرفى أو قانون مكافحة غسل الأموال أو حكم بإشهار إفلاسه<<CR>>
 خلال الخمس سنوات السابقة على ترشيحه ،وذلك ما لم يكن رد إليه اعتباره .<<CR>>
 6- ألا تكون الهيئة قد أصدرت ضده أو ضد الصندوق أو إحدى الشركات<<CR>>
العاملة فى مجال الأنشطة المالية غير المصرفية التى كان يشغل عضوية مجلس<<CR>>
إدارتها أو يعمل لديها أى تدبير -باستثناء التنبيه -خلال الثلاث سنوات السابقة على<<CR>>
 ترشيحه وكان ذلك بسبب إخلاله بواجباته أو مسئولياته .<<CR>>
 7- التعهد بالالتزام بمراعاة كافة التشريعات المنظمة لعمل صناديق التأمين<<CR>>
الخاصة وكذا النظام الأساسى للصندوق ،وبذل عناية الرجل الحريص فى مباشرته<<CR>>
لجميع الأعمال المتعلقة بالصندوق ؛ وعلى وجه الأخص تخصيص وقت كافٍ<<CR>>
للاضطلاع بمسئولياته بما فى ذلك التحضير المسبق لاجتماعات مجلس الإدارة ولجانه<<CR>>
 وحضور تلك الاجتماعات .<<CR>>
وتزول صفة العضوية عن عضو مجلس الإدارة من ذوى الخبرة بمجلس إدارة<<CR>>
الصندوق حال فقده لأى من الشروط أو إخلاله بأى من التعهدات المشار إليها بهذه المادة .<<CR>>

