('board_decision',298,2024,2,0,'f546bb877b1f721cf44483956669778c','dae6a817719951cd57cb1aebc4f32b08',replace($m208$شروط القيد لدى الهيئة<<CR>>
 يشترط لقيد المتدرب بالسجل المعد لذلك لدى الهيئة استيفاء المتطلبات الآتية :<<CR>>
 1- أن يكون محمود السيرة ،حسن السمعة .<<CR>>
 2- أن يكون متمتعا بالأهلية القانونية .<<CR>>

 3- أن يكون حاصلاً على مؤهل عال ،أو مؤهل فوق المتوسط أو متوسط<<CR>>
 تخصص تأمين من إحدى الجهات التى تقبلها الهيئة .<<CR>>
 4- ألا يكون قد سبق فصله من عمله بحكم أو بقرار تأديبى نهائى أو صدر قرار<<CR>>
بشطب اسمه من سجل المهن التى تنظمها قوانين أو لوائح خاصة أو منعه تأديبيا من<<CR>>
مزاولة المهنة فى مجال الأنشطة المالية غير المصرفية أو أى مهنة حرة ،خلال<<CR>>
 الثلاث سنوات السابقة على تاريخ تقديم طلب القيد .<<CR>>
 5- ألا يكون قد صدر ضده حكم نهائى بعقوبة جناية ،أو بعقوبة جنحة فى جريمة<<CR>>
ماسة بالشرف أو الأمانة أو فى إحدى الجرائم المنصوص عليها بالقوانين المنظمة<<CR>>
للأنشطة المالية غير المصرفية ،خلال الثلاث سنوات السابقة على تاريخ تقديم طلب<<CR>>
 القيد ما لم يكن قد رد إليه اعتباره .<<CR>>
 6- اجتياز الدورة التدريبية التى تحددها الهيئة ،ويجوز للهيئة قيد المتدرب لديها<<CR>>
 على أن يتعهد بالحصول على الدورة التدريبية عند تحديدها من الهيئة .$m208$,'<<CR>>',chr(13))),
('board_decision',298,2024,3,0,'4c91915ad5edfa5e29447f2f32567c24','804c7537533d21239204f8f53dc0cba3',replace($m208$التزامات الشركة الراغبة فى التعاقد مع المتدرب<<CR>>
