 بما يلى :<<CR>>
 1- إبرام عقد ينظم الحقوق والالتزامات بين الطرفين وبما يتوافق مع أحكام<<CR>>
قانون التأمين الموحد والقرارات الصادرة من الهيئة لتنظيم ممارسة نشاط الوساطة<<CR>>
