الهيئة للقيام بأعمال الوساطة فى التأمين أو إعادة التأمين ومقيد فى السجل المعد لذلك ،<<CR>>
ويتوسط بأى صورة كانت فى عقد عمليات تأمين أو إعادة تأمين لأى من شركات<<CR>>
