أعضاء الجهاز الإنتاجى :هم الوسطاء الذين يعملون أو يلتحقون بالعمل بقطاع<<CR>>
البيع لدى أى من شركات التأمين أو إعادة التأمين ،ويتولون أعمال الوساطة باسم<<CR>>
 ولحساب شركات التأمين أو إعادة التأمين .<<CR>>
وسيط بشركة الوساطة :هو الوسيط الذى يعمل لدى أى من شركات الوساطة فى<<CR>>
 التأمين أو إعادة التأمين ويتولى أعمال الوساطة لحساب شركة الوساطة التى يعمل لديها .<<CR>>
وسيط التأمين الحر :هو الشخص الطبيعى الذى يتولى أعمال الوساطة باسمه<<CR>>
 ولحسابه الشخصى ،ولا يعمل لدى أى من شركات التأمين أو الوساطة فى التأمين .<<CR>>
سجل وسطاء التأمين وإعادة التأمين :هو سجل لقيد الأشخاص<<CR>>
