 الشروط الآتية :<<CR>>
 1- ألا يكون قد صدر ضده تدابير إدارية من الهيئة -باستثناء الإنذار -خلال<<CR>>
 السنة السابقة على تقديم طلب القيد .<<CR>>
 2- ألا يكون قد حكم عليه خلال الخمس سنوات السابقة على تقديم طلب القيد<<CR>>
بعقوبة جناية أو بعقوبة جنحة فى جريمة مخلة بالشرف أو الأمانة ،أو فى إحدى<<CR>>
الجرائم المنصوص عليها فى أى من قوانين التجارة أو الشركات أو إحدى القوانين<<CR>>
المنظمة للأنشطة المالية غير المصرفية أو حكم بإشهار إفلاسه ما لم يكن قد رد إليه<<CR>>
 اعتباره .<<CR>>
 3- ألا يقوم به عارض من عوارض الأهلية .<<CR>>
 4- ألا يكون قد فصل من عمله بحكم أو بقرار تأديبى نهائى أو صدر قرار<<CR>>
بشطب اسمه من أى من سجل المهن التى تنظمها القوانين لأمور تمس الأمانة<<CR>>
 أو الشرف ما لم يمض على صدور الحكم أو القرار ثلاث سنوات .<<CR>>
 5- أن يكون حاصلاً على مؤهل عال من إحدى الجامعات المصرية أو الأجنبية<<CR>>
