على مؤهل متوسط من الجهات التى تعتمدها الهيئة أو فوق متوسط تخصص تأمين<<CR>>
شريطة اجتياز الدورات التدريبية و/أو البرامج و/أو الاختبارات التى تحددها الهيئة<<CR>>
 فى هذا الشأن .<<CR>>
ويستثنى من هذا الشرط من سبق قيده كوسيط تأمين أو إعادة تأمين قبل العمل<<CR>>
 بأحكام هذا القرار .<<CR>>
 6- اجتياز البرنامج التدريبى المعد فى هذا الشأن من إحدى الجهات المعتمدة<<CR>>
 من الهيئة .<<CR>>
 7- اجتياز الاختبار الذى تعقده الهيئة فى هذا الشأن .<<CR>>

 8- ألا يكون من العاملين بإحدى شركات التأمين أو إعادة التأمين -عدا أعضاء<<CR>>
 الجهاز الإنتاجى -إلا بعد مرور عام على الأقل من تاريخ انتهاء عمله بالشركة .<<CR>>
 9- التسجيل على المنصة الإلكترونية للمهنيين .<<CR>>
