 أن يقرر دعوة الجمعية العامة كلما دعت الضرورة إلى ذلك .<<CR>>
ويجب على مراقب الحسابات أن يدعو الجمعية العامة للانعقاد فى الأحوال التى<<CR>>
يتراخى فيها رئيس مجلس الإدارة عن دعوة الجمعية العامة للانعقاد خاصة خلال<<CR>>
 الثلاثة أشهر التالية لنهاية السنة المالية للشركة .<<CR>>
وتلتزم الشركة أن تقدم إلى الهيئة صورة من محضر اجتماع الجمعية العامة<<CR>>
 فى موعد أقصاه ثلاثين يوما من تاريخ انعقاد الجمعية لاعتماده .<<CR>>
وتلتزم الشركة بإدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية<<CR>>
العامة للشركة ،وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة فى حالة عدم<<CR>>
 حضور ممثل عن الهيئة .<<CR>>

