بشأنها من أحد مراقبى الحسابات المقيدين بالقسم الأول من سجل مراقبى الحسابات<<CR>>
المنظم بقرار مجلس إدارة الهيئة رقم 244 لسنة 2023 المشار إليه ،وتقرير مجلس<<CR>>
الإدارة عن نشاط الشركة ،وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ،<<CR>>
 وجميع المستندات التى تقدم للمساهمين أو من فى حكمهم عن أعمال الشركة .<<CR>>
وللهيئة إبداء ملاحظاتها على القوائم المالية ،وكذا على أى من البيانات<<CR>>
