('board_decision',69,2025,28,0,'575bf0caed27719c8ebd64603a11724f','01e77e26b09d4ea76cb456f05deaefb1',replace($m208$يجب على الوسيط مراعاة مبادئ النزاهة والاستقامة والأمانة والعدالة وحسن<<CR>>
التصرف وبذل عناية الرجل الحريص فى جميع أعماله وتصرفاته والامتناع عن القيام<<CR>>
بأى فعل ينطوى على إساءة إلى غيره من الوسطاء أو إلى مهنة الوساطة فى التأمين<<CR>>
 أو إعادة التأمين بوجه عام .<<CR>>
ويلتزم الوسيط بمباشرة أعمال الوساطة فى التأمين أو إعادة التأمين وفقًا لأحكام<<CR>>
قانون التأمين الموحد والقرارات الصادرة تنفيذًا له ،وذلك مع الالتزام -بحد أدنى -<<CR>>
 بالضوابط الآتية :<<CR>>
 1- الإشارة إلى صفته "وسيط تأمين" أو "وسيط إعادة تأمين" بحسب الأحوال<<CR>>
فى جميع أعماله ،وإقران اسمه برقم قيده فى سجل الهيئة بجميع المكاتبات والشهادات<<CR>>
والتقارير الصادرة عنه وإطلاع العميل على رقم القيد والترخيص الصادر له بمزاولة<<CR>>
 نشاط الوساطة قبل بدء التفاوض .<<CR>>

 2- أن يكون على علم ووعى بالتشريعات التأمينية والقواعد المنظمة للسوق<<CR>>
وكذا القرارات الصادرة عن الهيئة ،ومتابعة ما يطرأ عليها من تعديلات ،والعمل<<CR>>
 على تطبيقها بدقة ،وعدم مخالفتها .<<CR>>
 3- أن يكون على مستوى عال من المصداقية فى ممارسته لمهامه مع العملاء<<CR>>
وشركات التأمين وإعادة التأمين ،وخاصة عدم التوسط فى إصدار أو إلغاء وثائق<<CR>>
 التأمين دون الحصول على موافقة مسبقة من العميل .<<CR>>
 4- الامتناع عن تكليف وسطاء تأمين أو إعادة تأمين آخرين للقيام بأعمال<<CR>>
 الوساطة الخاصة به ،إلا بعد الحصول على موافقة كتابية من العميل .<<CR>>
 5- الالتزام بضوابط مكافحة غسل الأموال وتمويل الإرهاب وانتشار التسلح ،<<CR>>
والقوانين والقرارات ذات الصلة وفقًا لأحكام القانون رقم 80 لسنة 2002 بشأن<<CR>>
مكافحة غسل الأموال ولائحته التنفيذية ،والضوابط الصادرة عن الهيئة ووحدة<<CR>>
 مكافحة غسل الأموال وتمويل الإرهاب .<<CR>>
 6- الالتزام بكافة القرارات والضوابط الصادرة عن الهيئة فى حال إنشاء موقع<<CR>>
إلكترونى ،أو استخدام خطوط الربط الإلكترونى مع شركات التأمين ،أو استخدام<<CR>>
 التسويق الإلكترونى فى مزاولة نشاط الوساطة .<<CR>>
 7- الالتزام بضوابط إعلانات وسطاء التأمين والأنشطة الترويجية الأخرى<<CR>>
المتعلقة بنشاط الوساطة التأمينية ،وفقًا للقرارات الصادرة عن الهيئة بما يكفل للعميل<<CR>>
الحق فى الحصول على معلومات غير مضللة ،ويضمن حمايته من أى ممارسات<<CR>>
 تنطوى على غش أو تدليس .<<CR>>
 8- الاحتفاظ بجميع المستندات وعقود التأمين الخاصة بالعمليات التى يتم التوسط<<CR>>
فيها ،سواء بصورة إلكترونية أو ورقية ،مع عدم الإخلال بضوابط مكافحة غسل<<CR>>
 الأموال ذات الصلة .<<CR>>
 9- الامتناع عن القيام بأى أعمال تنطوى على تعارض مصالح بينه وبين<<CR>>
عملائه أو بين العملاء مع الالتزام بالإفصاح الفورى للهيئة حال وجود أى من تلك<<CR>>
الحالات ،واتخاذ الإجراءات الكافية لمنع حدوث تعارض المصالح ،وعلى الأخص<<CR>>
فى حال وجود تعارض بين مصلحته ومصلحة أحد عملائه فعليه تغليب مصلحة<<CR>>
 العميل أو الانسحاب من تقديم الخدمة مع إخطار العميل بذلك كتابة .<<CR>>

