('board_decision',69,2025,29,0,'53521fcaf7265b6dd70c05d2c8bee184','4604bc68139627bf27989482338b6e81',replace($m208$يحظر على الوسيط القيام بأى عمل من شأنه تضليل أو الإضرار بأى من<<CR>>
المتعاملين معه أو العاملين بقطاع التأمين أو الإخلال بحقوقهم ،ويحظر عليه على<<CR>>
 وجه الخصوص القيام بأى مما يلى :<<CR>>
