أو تسوية أى تعويضات ،أو أن تتضمن المستندات الصادرة عنه أو وسائل الدعاية<<CR>>
 والإعلان الخاصة به ما يشير إلى قيامه بأى من ذلك .<<CR>>
 2- إجراء أى كشط أو شطب أو تعديل أو تصحيح أو إضافة على طلب التأمين<<CR>>
أو على الوثيقة الصادرة عن الشركة المؤمن لديها ،كما يحظر عليه التوقيع نيابة<<CR>>
 عن العميل .<<CR>>
 3- نسخ عروض التأمين أو إعادة التأمين أو اقتباس أى من بياناتها من<<CR>>
مطبوعات شركة التأمين أو إعادة التأمين ،وإعادة كتابتها على مطبوعاته الخاصة<<CR>>
 أو التعامل بها بين طرفى التعاقد .<<CR>>
 4- الحصول على أى امتيازات مالية أو عينية غير معلنة من شركات التأمين<<CR>>
 أو إعادة التأمين ،يكون من شأنها التأثير على اختياره لشركة بعينها .<<CR>>
 5- تحصيل رسوم أو أقساط التأمين أو غيرها من المبالغ من العملاء بأى وسيلة<<CR>>
ينتج عنها إضافة تلك المبالغ إلى حساباته الخاصة ،ويلتزم بتحصيلها من خلال<<CR>>
ماكينات نقاط الدفع المسلّمة إليه من شركة التأمين أو إعادة التأمين ،أو من خلال أى<<CR>>
وسيلة دفع غير نقدى خاصة بها ،أو بموجب شيكات صادرة من العملاء لصالح<<CR>>
شركة التأمين أو إعادة التأمين ،أو عن طريق توجيه العملاء إلى السداد مباشرة إلى<<CR>>
 فروع الشركة المؤمن لديها أو حساباتها البنكية .<<CR>>
 6- الجمع بين أعمال الوساطة فى التأمين وأى وظيفة أو عمل لدى أى من<<CR>>
 الشركات الأخرى العاملة فى قطاع التأمين سواء كان بشكل دائم أو مؤقت .<<CR>>
 7- عمل توكيلات أو تفويضات لأى من وسطاء التأمين أو إعادة التأمين أو أى<<CR>>
شخص آخر – أيا كانت صلة القرابة أو العلاقة به – للقيام نيابة عنه بأى من أعمال<<CR>>
 الوساطة أو أى من الأنشطة المرتبطة بها .<<CR>>

كما يحظر على القائمين على الإدارة التنفيذية والوسطاء بشركة الوساطة<<CR>>
 فى التأمين أو إعادة التأمين ،وكذلك أعضاء الجهاز الإنتاجى ،القيام بأى مما يلى :<<CR>>
