 أو إدارة الأعمال أو تكنولوجيا المعلومات ،وذلك بحسب طبيعة الوظيفة المرشح لها .<<CR>>
 3- ألا يكون عاملاً بأى وجه وبأى صفة فى شركة أو جهة أخرى على نحو<<CR>>
 يخل بمهام وظيفته بالشركة .<<CR>>
 4- اجتياز المقابلة الشخصية التى تعقدها الهيئة مع المرشحين لتولى مسئولية<<CR>>
الأنشطة أو الإدارات الآتية :الاكتتاب ،الاستثمار ،التعويضات ،إعادة التأمين ،<<CR>>
الخبرة الاكتوارية ،الالتزام ،المراجعة الداخلية ،الإدارة المالية ،المخاطر ،التعامل<<CR>>
 مع شكاوى العملاء ،وتكنولوجيا المعلومات والتحول الرقمى .<<CR>>

ويجوز للهيئة إجراء مقابلة شخصية مع المرشحين لتولى مهام الأنشطة<<CR>>
أو الإدارات الآتية :اكتتاب فروع التأمين المختلفة ،وتعويضات فروع التأمين<<CR>>
 المختلفة ،والإدارة القانونية ،والموارد البشرية .<<CR>>
وتسرى فى شأن مسئول مكافحة غسل الأموال وتمويل الإرهاب الأحكام<<CR>>
 المنصوص عليها بقرار مجلس إدارة الهيئة رقم 161 لسنة 2024 المشار إليه .$m208$,'<<CR>>',chr(13))),
('board_decision',89,2025,7,0,'064042dd6a00ebfb786b09b18639d3ba','e7c08c54589c2f7e1f88421685324043',replace($m208$إجراءات تعيين القائمين على الإدارة التنفيذية المسئولين عن<<CR>>
 الأعمال والوظائف الفنية<<CR>>
تلتزم شركات التأمين أو إعادة التأمين بموافاة الهيئة بأسماء المرشحين لشغل أى<<CR>>
 من الوظائف المشار إليها بالمادة الخامسة من هذا القرار ،مرفقًا به المستندات الآتية :<<CR>>
 1- صورة بطاقة الرقم القومى للمرشح .<<CR>>
 2- سيرة ذاتية تفصيلية للمرشح .<<CR>>
 3- بيان حالة تفصيلى للمرشح .<<CR>>
 4- صورة من المؤهل الدراسى ،والشهادات المهنية والدورات الحاصل<<CR>>
 عليها المرشح .<<CR>>
 5- الإفصاح على النموذج المعد لذلك عن مدى وجود صلة قرابة حتى الدرجة<<CR>>
 الرابعة مع أى من أعضاء مجلس إدارة الشركة أو العاملين بها .<<CR>>
 6- تعهد بالانضمام للمنصة الإلكترونية للمهنيين المنشأة لدى الهيئة فور إتاحتها بها .<<CR>>
 7- أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها .<<CR>>
وفى جميع الأحوال ،تلتزم الشركات المشار إليها بالاطلاع على القائمة المعدة<<CR>>
لدى الهيئة بشأن المخالفين للتشريعات المنظمة للأنشطة المالية غير المصرفية قبل<<CR>>
 موافاة الهيئة بأسماء المرشحين لشغل أى من الوظائف المشار إليها .<<CR>>

