يقدم طلب تجديد الموافقة خلال الثلاثة أشهر السابقة على انتهاء مدة الموافقة على<<CR>>
النموذج الذى تعده الهيئة لهذا الغرض ،مرفقًا به المستندات الدالة على استيفاء شروط<<CR>>
تجديد الموافقة ،وللهيئة أن تخطر مقدم الطلب بضرورة تقديم أية معلومات<<CR>>
 أو مستندات إضافية للتأكد من استمرار توافر شروط الموافقة .<<CR>>
ويجوز للهيئة أن تطلب اجتياز طالب التجديد للاختبارات و/أو الدورات التدريبية<<CR>>
التى تحددها ،كما يجوز أن يقترن قرار التجديد إلزام الشخص المعنى بمتطلبات<<CR>>
التعليم المهنى المستمر والمتمثلة فى الحصول على عدد ساعات للتعليم المهنى المستمر<<CR>>
 فى المجالات والتخصصات وفقًا لما تحدده الهيئة .<<CR>>

$m208$,'<<CR>>',chr(13))),
('board_decision',89,2025,10,0,'b14205c906f05ca5073b711d3b161441','58b9f4790edd0df3a028e6f3a28fffd4',replace($m208$خطة التعاقب الوظيفى<<CR>>
تلتزم الشركات المخاطبة بأحكام هذا القرار بوضع خطة تعاقب وظيفى للوظائف<<CR>>
المشار إليها بهذا القرار معتمدة من مجلس إدارتها وموافاة الهيئة بها بشكل سنوى<<CR>>
أو فور إجراء تعديل عليها ،على أن تتضمن بيان الإجراءات الواجب اتباعها لشغل<<CR>>
تلك الوظائف فى حال خلو من يشغلها ،وكذا برامج تدريب وتأهيل العناصر البشرية<<CR>>
 المؤهلة لشغل تلك الوظائف .<<CR>>
 )المادة الحادية عشرة(<<CR>>
 إمساك الشركة لسجل القائمين على الإدارة التنفيذية بها<<CR>>
تلتزم الشركات المخاطبة بأحكام هذا القرار بإمساك سجل ورقى و/أو إلكترونى<<CR>>
تقيد به أسماء القائمين على الإدارة التنفيذية بالشركة وفقًا لأحكام هذا القرار ،<<CR>>
وعناوينهم ،وتاريخ الحصول على موافقة الهيئة لشغل هذه الوظائف وتاريخ تجديدها ،<<CR>>
وتاريخ شغلهم وإنهائهم للعمل لديها ،وما إذا كان هناك أى إجراءات اتخذتها الشركة<<CR>>
بشأنهم أو صدور أحكام جنائية ضدهم ،وما إذا كان هناك صلة قرابة حتى الدرجة<<CR>>
الرابعة بينهم وبين أحد أعضاء مجلس إدارة الشركة أو العاملين بها ومدى وجود<<CR>>
 أى حالة من الحالات التى قد ينشأ معها تعارض فى المصالح .<<CR>>
وعلى تلك الشركات موافاة الهيئة خلال شهر يناير من كل عام بأسماء شاغلى<<CR>>
الوظائف المشار إليها بهذا القرار ،ومسمياتهم الوظيفية ،وكذا أى تعديلات تطرأ على<<CR>>
 تلك البيانات خلال خمسة عشر يوما من حدوثها .<<CR>>
كما تلتزم الشركات المشار إليها بالاحتفاظ بكافة المستندات المؤيدة للبيانات<<CR>>
المذكورة بهذه المادة بشكل ورقى و/أو إلكترونى لمدة لا تقل عن خمس سنوات<<CR>>
من تاريخ انتهاء علاقة العمل ،وعليها موافاة الهيئة بأى من هذه المستندات حال<<CR>>
 طلبها منها .<<CR>>

 )المادة الثانية عشرة(<<CR>>
 خلو شغل أحد وظائف القائمين على الإدارة التنفيذية<<CR>>
تلتزم الشركات المخاطبة بأحكام هذا القرار حال خلو أى من وظائف القائمين<<CR>>
على الإدارة التنفيذية الواجب شغلها لديها وفقًا لأحكام هذا القرار ،أن تعين بديلاً<<CR>>
خلال مدة أقصاها ثلاثة أشهر على الأكثر من تاريخ خلو الوظيفة ما لم تقدم الشركة<<CR>>
مبررات تقبلها الهيئة ،على أن يكلف رئيس مجلس الإدارة أو العضو المنتدب أحد<<CR>>
العاملين بالشركة ممن تتوافق طبيعة عملهم أو خبراتهم مع الوظيفة الشاغرة بمباشرة<<CR>>
 تلك المهام لحين شغلها .<<CR>>
وفى جميع الأحوال ،تلتزم الشركة بإخطار الهيئة فى حالة خلو الوظيفة خلال<<CR>>
 عشرة أيام من تاريخ حدوثها وكذا الإجراءات التى ستتخذها لاختيار البديل .<<CR>>
 )المادة الثالثة عشرة(<<CR>>
 إنهاء خدمة أو استقالة شاغلى الوظائف الرقابية والاكتوارية بالشركة<<CR>>
على الشركات المخاطبة بأحكام هذا القرار الحصول على عدم ممانعة من الهيئة<<CR>>
قبل إنهاء خدمة أى من المسئولين عن أى من الإدارات الآتية :الالتزام ،المراجعة<<CR>>
الداخلية ،المخاطر ،الإدارة الاكتوارية ،إدارة مكافحة غسل الأموال وتمويل<<CR>>
 الإرهاب ،وبعد موافاة الهيئة بأسباب إنهاء الخدمة .<<CR>>
كما يجب على الشركة إخطار الهيئة عند قبول استقالة أى من المسئولين عن<<CR>>
الأنشطة أو الإدارات المشار إليها بهذا القرار ،وذلك على النموذج الذى تعده الهيئة<<CR>>
 لهذا الغرض خلال يومى عمل من تاريخ قبول الاستقالة .<<CR>>
وفى جميع الأحوال ،للهيئة إجراء مقابلة مع الشخص الذى تم إنهاء خدمته<<CR>>
 أو قبول استقالته .<<CR>>

 )المادة الرابعة عشرة(<<CR>>
 التدابير الإدارية<<CR>>
للهيئة حال مخالفة أى من القائمين على الإدارة التنفيذية المسئولين عن أى من<<CR>>
الأعمال والوظائف الفنية بشركات التأمين أو إعادة التأمين ،لأحكام هذا القرار<<CR>>
أو التشريعات الحاكمة لنشاط التأمين أو القرارات الصادرة تنفيذًا له ،أو فى حال<<CR>>
ثبوت عدم صحة البيانات أو المستندات المقدمة رفق طلب الحصول على موافقة الهيئة<<CR>>
 لشغل تلك الوظائف ،اتخاذ أى تدبير من التدابير الآتية :<<CR>>
 1- التنبيه .<<CR>>
 2- الإنذار .<<CR>>
ولمجلس إدارة الهيئة حال تحقق أى من المخالفات المشار إليها بهذه المادة ،<<CR>>
 اتخاذ أى تدبير من التدابير الآتية وفقًا لجسامة المخالفة :<<CR>>
 1- إلغاء الموافقة الصادرة مع عدم جواز الحصول عليها مرة أخرى إلا بعد<<CR>>
 مرور مدة لا تجاوز سنة .<<CR>>
 2- إلغاء الموافقة الصادرة مع عدم جواز الحصول عليها مرة أخرى إلا بعد<<CR>>
 مرور مدة لا تقل عن سنة ولا تجاوز خمس سنوات .<<CR>>
ويجوز أن يقترن القرار الصادر بتوقيع أى من التدابير المشار إليها ،وجوب<<CR>>
 اجتياز الشخص للدورات التدريبية التى تحددها الهيئة فى هذا الشأن .<<CR>>
 )المادة الخامسة عشرة(<<CR>>
 توفيق الأوضاع<<CR>>
تسرى الشروط الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين وإعادة<<CR>>
التأمين على النحو المنصوص عليه بهذا القرار اعتبا را من أول انتخابات قادمة لمجلس<<CR>>
إدارة الشركة ،على أن تسرى تلك الشروط اعتبارا من تاريخ العمل بهذا القرار حال<<CR>>
 انضمام مرشحين جدد لعضوية مجلس إدارة الشركة فى دورته الحالية .<<CR>>

كما تلتزم الشركات المشار إليها بتوفيق أوضاعها بشغل الوظائف المتطلبة وفقًا<<CR>>
لهذا القرار ،بهيكلها الوظيفى خلال (18) شهرا من تاريخ العمل به ،على أن تستمر<<CR>>
سريان الموافقة الممنوحة لشغل الوظائف المشار إليها بعد صدور قانون التأمين الموحد<<CR>>
وذلك لحين انتهاء مدتها ،ويشترط لتجديد الموافقة استيفاء متطلبات التجديد على النحو<<CR>>
 الوارد بهذا القرار .<<CR>>
كما يلتزم الأعضاء المنتدبون بمجالس إدارة الشركات المذكورة بالإفصاح للهيئة<<CR>>
عن الشركات التى يشغلون عضوية مجالس إدارتها ،وذلك خلال شهر من تاريخ<<CR>>
 العمل بهذا القرار .<<CR>>
 )المادة السادسة عشرة(<<CR>>
ينشر هذا القرار فى الوقائع المصرية وعلى الموقع الإلكترونى للهيئة ،ويعمل به<<CR>>
 من اليوم التالى لتاريخ نشره بالوقائع المصرية .<<CR>>
 رئيس مجلس إدارة<<CR>>
الهيئة العامة للرقابة المالية<<CR>>
