 الرعاية الصحية على ترخيص مؤقت بمزاولة النشاط ،استيفاء الشروط الآتية :<<CR>>
 1- أن تتخذ الشركة شكل شركة مساهمة ،وأن يكون رأس مالها المصدر<<CR>>
مدفوعا بالكامل ،وألا تقل حقوق الملكية عن رأس المال المصدر والمدفوع ،<<CR>>
وبالنسبة لشركات التأمين الطبى المتخصصة ألا يقل رأس المال عن عشرة ملايين<<CR>>
 جنيه وقت التقدم للحصول على الترخيص المؤقت .<<CR>>
 2- أن يكون لدى الشركة عقود تمتد لثلاث سنوات قبل صدور قانون<<CR>>
 التأمين الموحد .<<CR>>
 3- ألا تقل محافظ شركات التأمين الطبى المتخصصة السارية عن مائة مليون<<CR>>
 جنيه وقت تقديم الطلب .<<CR>>
 4- أن يتوافر لدى الشركة الحد الأدنى من التجهيزات والبنية التكنولوجية وأنظمة<<CR>>
 المعلومات اللازمة لمباشرة النشاط ،وفقًا لما تحدده الهيئة فى هذا الشأن .<<CR>>
 5- أن يتضمن الهيكل الإدارى للشركة المديرين المسئولين عن مزاولة النشاط ،<<CR>>
 وذلك على النحو الآتى :<<CR>>
 ) أ ( شركات التأمين الطبى المتخصصة :<<CR>>
 العضو المنتدب .<<CR>>
 مسئول الاكتتاب .<<CR>>
 مسئول التعويضات .<<CR>>
 )ب( شركات إدارة برامج الرعاية الصحية :<<CR>>
