 مسئول المطالبات .<<CR>>
 مسئول الموافقات الطبية .<<CR>>
 6- اجتياز المديرين المسئولين بالشركة للاختبارات التى تحددها الهيئة .<<CR>>
 7- أن يكون مراقب حسابات شركات التأمين الطبى المتخصصة من مراقبى<<CR>>
