الأعضاء لا تقل نسبته عن ) (%30 ممن لهم حق الحضور .وفى حالة استقالة مجلس<<CR>>
إدارة الاتحاد أو حله بناء على حكم قضائى أو إسقاط عضوية كل أعضاء مجلس<<CR>>
