لا تجاوز سبعة أيام عمل من تاريخ استقالة المجلس أو حله أو إسقاط العضوية عنه<<CR>>
وذلك لانتخاب مجلس إدارة جديد للاتحاد ويعتبر المجلس مستقيلا إذا تقدم أكثر<<CR>>
 من نصف أعضائه باستقالاتهم فى وقت واحد .<<CR>>
