('board_decision',127,2025,18,0,'9a602f644238f88603183675d152a6ee','c706de990bfe8ea73ca7e3c41143d939',replace($m208$يكون للاتحاد مجلس إدارة يشكل من رئيس ونائب للرئيس وأحد عشر عضوا يتم<<CR>>
اختيارهم كممثلين للشركات الأعضاء لمدة أربع سنوات قابلة للتجديد لمرة واحدة<<CR>>
 متصلة وذلك على النحو التالى :<<CR>>
أولاً -رئيس مجلس الإدارة ،ونائب للرئيس على أن يكون أحدهما من شركة<<CR>>
تأمين تزاول تأمينات الأشخاص وعمليات تكوين الأموال ،ويكون الآخر من شركة<<CR>>
 تأمين تزاول تأمينات الممتلكات والمسئوليات .<<CR>>

ثانيا -عنصران نسائيان من بين رؤساء مجالس الإدارات أو نوابهم أو الأعضاء<<CR>>
المنتدبين للشركات أعضاء الاتحاد ،وفى حالة ترشح أكثر من عضو نسائى تفوز<<CR>>
 بالعضوية من تحصل منهن على أكثر الأصوات .<<CR>>
وفى حالة عدم ترشح عنصر نسائى أو ترشح عنصر واحد يضاف المقعدان<<CR>>
أو المقعد المتبقى -حسب الأحوال – إلى المقاعد التسعة المنصوص عليها فى البند<<CR>>
 ثالثًا من هذه المادة .<<CR>>
ثالثًا -تسعة أعضاء من الذكور أو الإناث من بين رؤساء مجالس الإدارات<<CR>>
أو النواب أو الأعضاء المنتدبين لشركات التأمين وإعادة التأمين أعضاء الاتحاد على<<CR>>
أن يراعى التوزان النسبى بين ممثلى الشركات التى تزاول التأمين وإعادة التأمين أيا<<CR>>
 كان نوع نشاطها .$m208$,'<<CR>>',chr(13))),
('board_decision',127,2025,19,0,'c2a18fb4706a3fac6db27b095879caa0','879ce6c3d1451cd2c7ae1600413bfa3f',replace($m208$يشترط فيمن يرشح ممثلاً بعضوية مجلس إدارة الاتحاد ما يلى :<<CR>>
 1- أن يكون محمود السيرة حسن السمعة .<<CR>>
 2- ألا يكون قد سبق الحكم عليه بعقوبة جناية أو بعقوبة جنحة مقيدة للحرية<<CR>>
فى جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية فى إحدى الجرائم<<CR>>
المنصوص عليها فى قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية<<CR>>
غير المصرفية لأسباب تتعلق بنشاط الشركة ،أو حكم بإشهار إفلاسه ،ما لم يكن<<CR>>
 قد رد إليه اعتباره .<<CR>>
 3- أن يكون متمتعا بحقوقه المدنية كاملة .<<CR>>
 4- ألا يقوم به عارض من عوارض الأهلية .<<CR>>
 5- ألا يكون قد سبق فصله من وظيفة شغلها بحكم أو قرار تأديبى أو صدر<<CR>>
قرار بشطب اسمه من سجل إحدى المهن التى تنظمها القوانين أو اللوائح لأمور تمس<<CR>>
 الأمانة أو الشرف ما لم يمض على صدور الحكم أو القرار ثلاثة أعوام على الأقل .<<CR>>

 6- ألا يكون قد سبق توقيع تدبير عليه من مجلس إدارة الهيئة العامة للرقابة<<CR>>
 المالية لخطأ جسيم تسبب فيه ما لم يمض على ذلك ثلاثة أعوام على الأقل .<<CR>>
 7- أن تتوافر لديه خبرة تأمينية لا تقل عن عشر سنوات .<<CR>>
 8- أن يكون مضى على شغله لوظيفة رئيس مجلس إدارة أو نائب الرئيس<<CR>>
 أو عضو منتدب مدة لا تقل عن سنة .$m208$,'<<CR>>',chr(13))),
('board_decision',127,2025,20,0,'205ad96c89f250f00f6993092edd2df0','aeda4ee1d4c623f9f5780ee54ccea34e',replace($m208$يقرر مجلس إدارة الاتحاد فتح باب الترشح لعضوية المجلس قبل ستين يوما<<CR>>
 على الأقل من نهاية دورته ،ولمدة خمسة عشر يوما .<<CR>>
وعلى الشركة التى ترغب فى ترشيح ممثل لها بالمجلس أن تكون قد أوفت بكافة<<CR>>
الالتزامات المالية المستحقة عليها عن آخر سنة مالية ،وأن تتقدم إلى الأمانة العامة<<CR>>
للاتحاد خلال المدة المحددة فى الفقرة السابقة بطلب الترشح على النموذج المعد لذلك<<CR>>
 بالاتحاد مرفقًا به الأوراق التالية :<<CR>>
 1- بيانًا بالحالة الوظيفية للمرشح ومدة خبرته التأمينية والمناصب التى<<CR>>
 سبق له شغلها .<<CR>>
 2- إقرارا موقعا من المرشح بعدم وجود تعارض فى المصالح بين عضويته<<CR>>
بمجلس إدارة الاتحاد -فى حالة فوزه فى الانتخابات -وبين أى من المناصب<<CR>>
 التى يشغلها .<<CR>>
 3- إقرارا موقعا من المرشح بتعهده بإخطار مجلس إدارة الاتحاد -فى حالة<<CR>>
 فوزه فى الانتخابات -بأى منصب قد يشغله فى تاريخ تالٍ لإعلان نتيجة الانتخاب .<<CR>>
 على أن يختم هذا النموذج بعد استيفاء بياناته بخاتم الشركة .$m208$,'<<CR>>',chr(13))),
('board_decision',127,2025,21,0,'e2fc69dde6a8fc0c5b2e4a90c74c5b6b','1db94f6adc4ed1fb5e67090189d16c2a',replace($m208$تعرض طلبات الترشح فى نهاية المدة المقررة لتقديمها على لجنة تشكل من :<<CR>>
