ويتبع في إصدار التدابير المشار إليها بالفقرة الأولى من هذه المادة ، والتظلم منها أحكام المواد من 208 مكرراً (أ) إلى 208 مكرراً (هـ) من قانون الإجراءات الجنائية .$m208$,'<<CR>>',chr(13))),
('law',10,2003,63,0,'89dbd8cc8f728e8b19d40ff44292c1b6','d237d30cee5f7f7980dbb1fc7289a8cf',replace($m208$يجوز بقرار من مجلس الوزراء أن يطرح للبيع أسهم بقيمة جزء من رأس مال الشركة على أن تظل الأغلبية فى رأس المال للدولة ، ويكون للعاملين فى الشركة أولوية فى شراء الأسهم المطروحة للبيع فى حدود (5%) .$m208$,'<<CR>>',chr(13))),
('law',141,2014,2,0,'dd2be4f49fa7889efcb8c7175d2fa5a3','6af0e9b12d4e56da264366254b4a17e5',replace($m208$فى تطبيق أحكام هذا القانون يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:

1 - تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر: كل تمويل لأغراض اقتصادية إنتاجية أو خدمية أو تجارية للمشروعات المتوسطة والصغيرة ومتناهية الصغر المبينة بقانون تنمية المشروعات المتوسطة والصغيرة ومتناهية الصغر المشار إليه، على ألا يجاوز قيمة تمويل المشروع متناهي الصغر عن مائتي ألف جنيه مصري، وذلك للمشروع الواحد.
ويجوز لمجلس إدارة الهيئة زيادة الحد الأقصى لتمويل المشروع متناهي الصغر للمشروع الواحد أو الشخص الطبيعي الواحد بما لا يجاوز (10%) سنويا وفقا للظروف الاقتصادية.

2 - الهيئة: الهيئة العامة للرقابة المالية.

3 - الشركة: الشركة المرخص لها بتمويل أي من المشروعات المتوسطة أو الصغيرة أو متناهية الصغر وفقا لأحكام هذا القانون.

4 - الجمعية أو المؤسسة الأهلية: الجمعية أو المؤسسة الأهلية المرخص لها بتمويل أي من المشروعات المتوسطة أو الصغيرة أو متناهية الصغر وفقا لأحكام هذا القانون.

5 - الوساطة فى منح أو تحصيل التمويل: نشاط يزاوله شخص اعتبارى يقوم بإعداد وتجهيز ملف العميل لتقديمه للشركة أو الجمعية أو المؤسسة الأهلية للحصول على التمويل، وتعريفه بمخاطر التمويل، وتقديم المشورة الفنية له، أو تحصيل أقساط التمويل وسدادها لجهة التمويل.

6 - الكفالة بأجر: عقد بمقتضاه يكفل شخص الوفاء بالتزام عميل تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر بأن يتعهد للشركة أو الجمعية أو المؤسسة الأهلية بأن يفي بهذا الالتزام إذا لم يف به العميل نفسه، وذلك نظير أجر.

* معدلة بموجب قانون رقم 201 لسنة 2020، نص المادة قبل التعديل:
فى تطبيق أحكام هذا القانون يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:

التمويل متناهي الصغر: كل تمويل لأغراض اقتصادية إنتاجية أو خدمية أو تجارية في المجالات وبالقيمة التي يحددها مجلس إدارة الهيئة بما لا يجاوز مائة ألف جنيه، ويجوز بقرار من رئيس مجلس الوزراء بناءً على اقتراح مجلس إدارة الهيئة وفقاً للظروف الاقتصادية ومتطلبات السوق زيادة الحد الأقصى بما لا يجاوز (5%) سنوياً.

الهيئة: الهيئة العامة للرقابة المالية.

الشركة: الشركات المرخص لها بمزاولة نشاط التمويل متناهي الصغر وفقاً لأحكام هذا القانون.

* البندان (5، 6) مضافان بموجب قانون رقم 155 لسنة 2022.$m208$,'<<CR>>',chr(13))),
('law',141,2014,5,0,'f63c838b9e0b180873785108a59fb229','429165c3acd2cfd180812b7339125921',replace($m208$يجب أن تتوفر في الشركات التي ترغب في مزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر الشروط الآتية:

1- أن تتخذ شكل شركة مساهمة مصرية.

2- أن يقتصر نشاطها على مزاولة تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر.

3- ألا يقل رأسمالها المصدر والمدفوع عن الحد الذي يقرره مجلس إدارة الهيئة وبما لا يقل عن عشرين مليون جنيه لشركات تمويل المشروعات المتوسطة والصغيرة، وخمسة ملايين جنيه لشركات تمويل المشروعات متناهية الصغر.
وعلى الشركات الراغبة في مزاولة نشاطي تمويل المشروعات المتوسطة والصغيرة وتمويل المشروعات متناهية الصغر معاً أن تستوفي الحد الأدنى لرأس المال المصدر والمدفوع الذي يقرره مجلس إدارة الهيئة لكل من النشاطين المشار إليهما على النحو المشار إليه بهذا البند.

4- أن تتوفر لديها الإمكانات الفنية وأنظمة المعلومات وإدارة المخاطر وتحصيل الأموال ومتابعة عمليات التمويل ونظام فحص شكاوى العملاء وفقاً للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة.

5- أن تتوفر الخبرة المناسبة وحسن السمعة في كل من رئيس وأعضاء مجلس الإدارة والعضو المنتدب والمديرين المسئولين عن التمويل والمخاطر وذلك وفقاً للضوابط التي يحددها مجلس إدارة الهيئة.

* معدلة بموجب قانون رقم 201 لسنة 2020، نص المادة قبل التعديل:
يجب أن تتوفر في الشركات التي ترغب في مزاولة نشاط التمويل متناهي الصغر الشروط الآتية:

1- أن تتخذ شكل شركة مساهمة مصرية.

2- أن يقتصر نشاطها على مزاولة نشاط التمويل متناهي الصغر.

3- ألا يقل رأسمالها المصدر والمدفوع عن الحد الذي يقرره مجلس إدارة الهيئة وبما لا يقل عن خمسة ملايين جنيه.

4- أن تتوفر لديها الإمكانات الفنية وأنظمة المعلومات وإدارة المخاطر وتحصيل الأموال ومتابعة عمليات التمويل ونظام فحص شكاوى العملاء وفقاً للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة.

5- أن تتوفر الخبرة المناسبة وحسن السمعة في كل من رئيس وأعضاء مجلس الإدارة والعضو المنتدب والمديرين المسئولين عن التمويل والمخاطر وذلك وفقاً للضوابط التي يحددها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',141,2014,10,0,'bccc8c43d18eb4e28b431a499366d04d','d367a0795c8d626a4ed0c8ca90b95411',replace($m208$تعد من التكاليف واجبة الخصم عند تحديد صافي الدخل الخاضع للضريبة وفقاً لأحكام قانون الضريبة على الدخل المشار إليه ما يأتي:

1- العوائد المدينة التي تدفعها الشركة على القروض وغيرها من وسائل التمويل.

2- المخصصات التي تحتسبها الشركة على التمويل المشكوك في تحصيله وفقاً للمعايير التي تضعها الهيئة ولما يقر به مراقب حسابات الشركة.

3- الديون التي يقرر مجلس إدارة الشركة إعدامها بناء على تقرير مراقب الحسابات وتزيد على المخصصات المشار إليها، وذلك بعد اتخاذ الإجراءات الجادة لاستيفائها وفقاً للضوابط والإجراءات التي يضعها مجلس إدارة الهيئة.

وتعفى من ضريبة الدمغة وغيرها من الضرائب والرسوم أرصدة القروض وأي صورة من صور التمويل التي تقدمها الشركة لعملائها وفقاً لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',141,2014,11,0,'ce9d2150b4badb612aec63c07d7bdf3e','48fdd24ba3a8f16e3a195bb6df0fda08',replace($m208$يجوز لمجلس إدارة الهيئة تحقيقاً لاستقرار السوق أو حماية لحقوق المتعاملين مع الشركة أو في حالة تعرض الشركة لأوضاع مالية تؤثر على مركزها المالي إلزام الشركة بزيادة رأسمالها المدفوع أو الأموال المخصصة لمزاولة النشاط أو معدل ملاءتها المالية وفقاً لجدول زمني محدد. وللمجلس أيضاً في حالة مخالفة الشركة أحكام هذا القانون أو القرارات الصادرة تنفيذاً له أو إذا فقدت شرطاً من شروط الترخيص أو إذا قامت بما من شأنه تهديد استقرار السوق أو مصالح المساهمين فيها أو أعضائها أو المتعاملين معها أن تتخذ تدبيراً أو أكثر من التدابير الآتية:

1- توجيه تنبيه إلى الشركة بإزالة المخالفة خلال المدة وبالشروط المحددة في التنبيه.

2- مطالبة رئيس مجلس إدارتها بدعوة المجلس أو الجمعية العامة للنظر في أمر المخالفات المنسوبة إليها واتخاذ اللازم نحو إزالتها.

3- المنع من مزاولة كل أو بعض الأنشطة المرخص بمزاولتها لفترة محددة أو منع التعامل مع عملاء جدد.

4- حل مجلس إدارة الشركة وتعيين مفوض لإدارتها لحين تعيين مجلس جديد بالأداة القانونية المقررة.

5- إصدار قرار بدمج الشركة في شركة أخرى بشرط موافقة الشركة المندمج فيها.

6- إلغاء ترخيص مزاولة بعض أو كل الأنشطة المرخص بمزاولتها.

ويجوز أن يتخذ التدبيرين المنصوص عليهما بالبندين (2،1) من رئيس الهيئة، كما يجوز له اتخاذ أي من التدابير المنصوص عليها في البند (3) من هذه المادة إذا كان التهديد المشار إليه من شأنه أن يترتب عليه ضرر يتعذر تداركه وذلك لمدة أقصاها شهر أو إلى حين العرض على مجلس إدارة الهيئة أيهما أقرب.

ولا يخل اتخاذ الهيئة لأي من التدابير السابقة باستمرار الشركة في تحصيل مستحقاتها أو حوالة محفظتها لأحد البنوك أو الجهات المرخص لها من الهيئة بمزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر وفقا للقواعد المقررة.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',141,2014,13,0,'47147730e031932ecc06a54cda7d50ec','201e40f834b609571723f4e81c1480c6',replace($m208$تختص الوحدة بتنظيم ورقابة ومتابعة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر، ولها في سبيل ذلك وعلى الأخص ما يلي:

1- وضع شروط الحصول على ترخيص بمزاولة نشاط تمويل المشروعات المتوسطة والصغيرة، وشروط الحصول على ترخيص بمزاولة نشاط تمويل المشروعات متناهية الصغر، وشروط حصول الجمعيات والمؤسسات الأهلية على تلك التراخيص.

2- وضع القواعد والمعايير اللازمة لمزاولة الجمعيات والمؤسسات الأهلية لنشاط تمويل المشروعات المتوسطة والصغيرة وإدارة المخاطر المرتبطة به والقواعد والمعايير اللازمة لمزاولتها نشاط تمويل المشروعات متناهية الصغر وإدارة المخاطر المرتبطة به أو القواعد والمعايير اللازمة لمزاولة نشاطي تمويل المشروعات المتوسطة والصغيرة وتمويل المشروعات متناهية الصغر وإدارة المخاطر المرتبطة به.

3- الحصول على البيانات والمعلومات عن ذلك النشاط الذي تزاوله الجمعيات والمؤسسات الأهلية، وإعداد الدراسات المرتبطة به وإصدار التقارير والإحصاءات الخاصة به.

4- متابعة أداء الجمعيات والمؤسسات الأهلية الممارسة لهذا النشاط، واتخاذ الإجراءات اللازمة للتحقق من التزاماتهم بأحكام هذا القانون وبالقواعد والمعايير التي تضعها الوحدة.

5- وضع قواعد التفتيش والرقابة على الجمعيات والمؤسسات الأهلية في مجال مزاولتها لنشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر.

6- عرض تقارير المتابعة على رئيس الهيئة متضمنة التوصيات اللازمة بشأن الجمعيات والمؤسسات الأهلية المخالفة لأحكام هذا القانون أو التي لا تلتزم بقواعد ومعايير مزاولة النشاط.

7- التنسيق مع الجهات المعنية بما يسهم في تطوير نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر وإدارة المخاطر المرتبطة به والعمل على تماثل قواعد وضوابط ممارسة النشاط بين الشركات والجمعيات والمؤسسات الأهلية الممارسة للنشاط.

* معدلة بموجب قانون رقم 201 لسنة 2020، نص المادة قبل التعديل:
تختص الوحدة بتنظيم ورقابة ومتابعة نشاط التمويل متناهي الصغر، ولها في سبيل ذلك وعلى الأخص ما يلي:

1- وضع شروط الحصول على ترخيص بمزاولة نشاط التمويل متناهي الصغر للجمعيات والمؤسسات الأهلية.

2- وضع القواعد والمعايير اللازمة لمزاولة الجمعيات والمؤسسات الأهلية للنشاط المشار إليه وإدارة المخاطر المرتبطة به.

3- وضع ضوابط مساهمة الجمعيات الأهلية في الشركات التي تعمل في مجال التمويل متناهي الصغر.

4- الحصول على البيانات والمعلومات عن ذلك النشاط الذي تزاوله الجمعيات والمؤسسات الأهلية، وإعداد الدراسات المرتبطة به وإصدار التقارير والإحصاءات الخاصة به.

5- متابعة أداء الجمعيات والمؤسسات الأهلية الممارسة لهذا النشاط، واتخاذ الإجراءات اللازمة للتحقق من التزاماتهم بأحكام هذا القانون وبالقواعد والمعايير التي تضعها الوحدة.

6- وضع قواعد التفتيش والرقابة على الجمعيات والمؤسسات الأهلية في مجال مزاولتها لنشاط التمويل متناهي الصغر.

7- عرض تقارير المتابعة على رئيس الهيئة متضمنة التوصيات اللازمة بشأن الجمعيات والمؤسسات الأهلية المخالفة لأحكام هذا القانون أو التي لا تلتزم بقواعد ومعايير مزاولة النشاط.

8- التنسيق مع الجهات المعنية بما يسهم في تطوير نشاط التمويل متناهي الصغر وإدارة المخاطر المرتبطة به والعمل على تماثل قواعد وضوابط ممارسة النشاط بين الشركات والجمعيات والمؤسسات الأهلية الممارسة للنشاط.$m208$,'<<CR>>',chr(13))),
('law',141,2014,13,1,'a39449b18296f3417392edf83644ed73','86a4863bb43e71436730ab6b8d359642',replace($m208$لا يجوز للجمعية أو المؤسسة الأهلية المرخص لها بمزاولة أي من نشاط تمويل المشروعات المتوسطة والصغيرة أو تمويل المشروعات متناهية الصغر أن تقدم تمويلاً أو أياً من الخدمات والأنشطة المرتبطة به إلى أعضاء مجلس الإدارة أو مجلس الأمناء أو القائمين على إدارتها أو العاملين بها أو أقاربهم حتى الدرجة الثانية إلا وفقا للضوابط الآتية:

1- ألا يتجاوز إجمالي التمويل الممنوح لمجموع هذه الفئات (5%) من محفظة التمويل بصورة مستمرة.

2- أن يتم منح التمويل والخدمات والأنشطة المرتبطة به وفقا لذات ضوابط منح التمويل المعمول بها مع باقي عملاء الجمعية أو المؤسسة الأهلية.

3- الإفصاح في الإيضاحات المتممة للقوائم المالية سواء السنوية أو ربع السنوية عن إجمالي حجم التمويل الممنوح للفئات المشار إليها وإجمالي المتأخرات المرتبطة بها.

ويصدر بقرار من مجلس إدارة الهيئة ضوابط النظام المقترح لمنح التمويل والخدمات المرخص بها لهذه الفئات، وذلك بعد أخذ رأي الوحدة.

*مضافة بموجب قانون رقم 201 لسنة 2020.$m208$,'<<CR>>',chr(13))),
('law',141,2014,13,2,'e7d3dd3fcc942a7fa6ae91b6cc2903cb','abac0c218d1e28f376fc1a4afe4007a3',replace($m208$مع عدم الإخلال بالحالات التي تستلزم استصدار حكم قضائي، يجوز لمجلس إدارة الهيئة في حالة مخالفة الجمعية أو المؤسسة الأهلية المرخص لها بمزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر لأحكام هذا القانون أو القرارات الصادرة تنفيذاً له، أو إذا فقدت شرطاً من شروط الترخيص، أو قامت بما من شأنه تهديد استقرار السوق أو مصالح أعضائها أو المتعاملين معها أن تتخذ تدبيراً أو أكثر من التدابير الآتية:

1- توجيه تنبيه إلى الجمعية أو المؤسسة الأهلية بإزالة المخالفة خلال المدة وبالشروط المحددة في التنبيه.

2- المنع من مزاولة كل أو بعض الأنشطة المرخص بمزاولتها لفترة محددة، أو منع التعامل مع عملاء جدد.

3- إلغاء ترخيص مزاولة كل أو بعض الأنشطة المرخص بمزاولتها.

ويجوز لرئيس الهيئة أن يتخذ التدبير المنصوص عليه بالبند (1) من هذه المادة، كما يجوز لمجلس إدارة الهيئة اتخاذ أي من التدابير المنصوص عليها في البند (2) من هذه المادة، إذا كان التهديد المشار إليه من شأنه أن يترتب عليه ضرر يتعذر تداركه وذلك لمدة أقصاها شهر أو إلى حين العرض على مجلس إدارة الهيئة أيهما أقرب.

ولا يخل اتخاذ الهيئة لأي من التدابير السابقة باستمرار الجمعية أو المؤسسة الأهلية في تحصيل مستحقاتها أو حوالة محفظتها لأحد البنوك أو الجهات المرخص لها من الهيئة بمزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر وفقا للقواعد المقررة.

*مضافة بموجب قانون رقم 201 لسنة 2020.$m208$,'<<CR>>',chr(13))),
('law',141,2014,21,1,'24747a7de58acc5d7fcf3eb1a95e5dde','3bf75b9fae911fdae579f5d8986a46ca',replace($m208$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على ضعفي المتبقي من قيمة التمويل محل عقد التمويل، أو بإحدى هاتين العقوبتين، كل من استخدم الغش أو التدليس توصلاً إلى أي من الحالات الآتية:

1- الحصول على تمويل من إحدى جهات تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر المرخص لها وفقًا لأحكام هذا القانون.

2- الامتناع عن تنفيذ كل أو بعض التزاماته المالية المقررة بموجب عقد التمويل المبرم وفقًا لأحكام هذا القانون، أو كان هذا الامتناع نتيجة استخدام التمويل في غير الغرض المخصص له.

وتستثنى الجرائم المبينة في هذه المادة من الأحكام المشار إليها بالفقرة الثانية من المادة (24) من هذا القانون.

ويجوز الصلح في هذه الجرائم سواء أمام النيابة العامة أو المحكمة المختصة، بحسب الأحوال، وذلك في أية حالة تكون عليها الدعوى، ويترتب على الصلح انقضاء الدعوى الجنائية بالنسبة للجريمة التي تم الصلح بشأنها، وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتًا.

*مضافة بموجب قانون رقم 155 لسنة 2022.$m208$,'<<CR>>',chr(13))),
('law',81,2016,1,-2,'24543b43876dd87e3ca10db6db576eed','83e834ecc7f8e069cf2965c78080fbc1',replace($m208$جدول رقم (1): الوظائف التخصصية
المستوى الوظيفى | الدرجة المالية المعادلة | المدد البينية اللازمة للترقية إلى المستوى | نسبة الترقية بالاختيار إلى المستوى | الأجر الوظيفى الشهرى (جنيه)
الممتازة | الممتازة | تحددها شروط شغل الوظيفة | مسابقة | 2065
العالية | العالية | تحددها شروط شغل الوظيفة | مسابقة | 1415
مدير عام | مدير عام | تحددها شروط شغل الوظيفة | مسابقة | 1335
الأولى (أ) | الأولى، أقدمية أكثر من سنة | سنة | 100% | 1195
الأولى (ب) | الأولى، أقدمية حتى سنة | ثلاث سنوات | 75% | 1175
الثانية (أ) | الثانية، أقدمية أكثر من 3 سنوات | ثلاث سنوات | 50% | 1035
الثانية (ب) | الثانية، أقدمية حتى 3 سنوات | ثلاث سنوات | 40% | 1020
الثالثة (أ) | الثالثة، أقدمية أكثر من 6 سنوات | ثلاث سنوات | 30% | 910
الثالثة (ب) | الثالثة، أقدمية أكثر من 3 سنوات وحتى 6 سنوات | ثلاث سنوات | 25% | 895
الثالثة (ج) | الثالثة، أقدمية حتى 3 سنوات | — | — | 880$m208$,'<<CR>>',chr(13))),
('law',81,2016,27,0,'d1bda524ce88ca9d14b40eb621a3c190','d632c8e3f8ed2beeb103592d09cb1c5a',replace($m208$يُعرض أمر الموظف الذى يُقدم عنه تقريران سنويان متتاليان بمرتبة ضعيف على لجنة الموارد البشرية، لنقله لوظيفة أخرى ملائمة فى ذات مستوى وظيفته لمدة سنة.
وإذا تبين للجنة بعد انقضاء المدة المشار إليها فى الفقرة السابقة أنه غير صالح للعمل بها بطريقة مرضية، اقترحت خصم (50%) من الأجر المكمل لمدة ستة أشهر.
وإذا تبين بعدها أنه غير صالح للعمل، اقترحت اللجنة إنهاء خدمته لعدم الصلاحية للوظيفة مع حفظ حقوقه التأمينية.
وفى جميع الأحوال ترفع اللجنة تقريرها للسلطة المختصة للاعتماد.$m208$,'<<CR>>',chr(13))),
('law',81,2016,31,0,'82a1c86064ccf652805447e0f020febc','9156a256652983ceda8eb2f76c1d41ba',replace($m208$يصدر قرار الترقية من السلطة المختصة، وتعتبر الترقية نافذة من تاريخ صدور القرار بها.
ويستحق الموظف اعتبارًا من هذا التاريخ الأجر الوظيفى المقرر للوظيفة المرقى إليها أو أجره السابق مضافًا إليه علاوة ترقية بنسبة (5%) من هذا الأجر الوظيفى أيهما أكبر.$m208$,'<<CR>>',chr(13))),
('law',81,2016,37,0,'645b91957ab933025a329e8ef7507abc','89176f13dcefb5ac76fa7cd78f54bc0b',replace($m208$يستحق الموظف علاوة دورية سنوية فى الأول من يوليو التالى لانقضاء سنة من تاريخ شغل الوظيفة أو من تاريخ استحقاق العلاوة الدورية السابقة بنسبة (7%) من الأجر الوظيفى، على أن يُعاد النظر فى هذه النسبة بصفة دورية منتظمة.$m208$,'<<CR>>',chr(13))),
('law',81,2016,38,0,'7466d1c6ed4e4b71a0ee9d1d503bade6','72119de63a893a450baff2d3c2fab331',replace($m208$يجوز للسلطة المختصة منح الموظف علاوة تشجيعية بنسبة (5%) من أجره الوظيفى، وذلك طبقًا للشروط الآتية:
1 - أن تكون كفاية الموظف قد حُددت بمرتبة كفء على الأقل عن العامين الأخيرين.
2 - ألا يمنح الموظف هذه العلاوة أكثر من مرة كل ثلاثة أعوام.
3 - ألا يزيد عدد الموظفين الذين يُمنحون هذه العلاوة فى سنة واحدة على (10%) من عدد الموظفين فى وظائف كل مستوى من كل مجموعة نوعية على حدة، فإذا كان عدد الموظفين فى تلك الوظائف أقل من عشرة تُمنح العلاوة لواحد منهم.$m208$,'<<CR>>',chr(13))),
('law',81,2016,39,0,'4a4476c9c17626b9c4668bb8d212fc59','d61e17161f2caa33d781fa8304e4e334',replace($m208$يستحق الموظف الذى يحصل على مؤهل أعلى أثناء الخدمة حافز تميز علمى.
ويمنح الموظف هذا الحافز إذا حصل على دبلومة مدتها سنتان دراسيتان على الأقل، أو على درجة الماجستير أو ما يعادلها أو دبلومتين من دبلومات الدراسات العليا مدة كل منهما سنة دراسية على الأقل، كما يمنح الموظف حافز تميز آخر إذا حصل على درجة الدكتوراة أو ما يعادلها.
ويكون حافز التميز العلمى المشار إليه بنسبة (7%) من الأجر الوظيفى، أو الفئات المالية التالية أيهما أكبر:
25- جنيهًا شهريًا لمن يحصل على مؤهل متوسط أو فوق المتوسط.
50- جنيهًا شهريًا لمن يحصل على مؤهل عالٍ.
75- جنيهًا شهريًا لمن يحصل على دبلومة مدتها سنتان دراسيتان على الأقل.
100- جنيه شهريًا لمن يحصل على درجة الماجستير أو ما يعادلها أو دبلومتين من دبلومات الدراسات العليا مدة كل منها سنة دراسية على الأقل.
200- جنيه شهريًا لمن يحصل على درجة الدكتوراة أو ما يعادلها.
وتحدد اللائحة التنفيذية شروط وضوابط منح حافز التميز، على ألا يجوز منح هذا الحافز أكثر من مرة عن ذات المستوى العلمى.$m208$,'<<CR>>',chr(13))),
('law',81,2016,51,0,'566ab857ecc8a13396d09773acf1d335','78d525d8e6a5fef2d8deb135d3eab784',replace($m208$يستحق الموظف إجازة مرضية عن كل ثلاث سنوات تقضى فى الخدمة، وتُمنح بقرار من المجلس الطبى المختص فى الحدود الآتية:
1 - الثلاثة أشهر الأولى بأجر كامل.
2 - الثلاثة أشهر التالية بأجر يعادل (75%) من الأجر الوظيفى.
3 - الستة أشهر التالية بأجر يعادل (50%) من الأجر الوظيفى، (75%) من أجره الوظيفى لمن يجاوز سن الخمسين.
ويحق للموظف طلب مد الإجازة المرضية بدون أجر للمدة التى يحددها المجلس الطبى المختص إذا قرر احتمال شفائه.
ويحق للموظف أن يطلب تحويل الإجازة المرضية إلى إجازة اعتيادية، إذا كان له رصيد منها، وعلى الموظف المريض أن يخطر جهة عمله عن مرضه خلال أربع وعشرين ساعة من انقطاعه عن العمل للمرض إلا إذا تعذر عليه ذلك لأسباب قهرية. وتضع السلطة المختصة الإجراءات المنظمة لحصول الموظف على الإجازة المرضية، ويعتبر التمارض إخلالاً بواجبات الوظيفة.
ويمنح الموظف المريض بأحد الأمراض المزمنة التى يصدر بتحديدها قرار من وزير الصحة بناءً على موافقة المجلس الطبى المختص إجازة استثنائية بأجر كامل إلى أن يُشفى أو تستقر حالته استقرارًا يمكنه من العودة إلى العمل أو يتبين عجزه عجزًا كاملاً، وفى هذه الحالة الأخيرة يظل الموظف فى إجازة مرضية بذات الأجر حتى بلوغه سن الإحالة للمعاش.
وإذا رغب الموظف المريض فى إنهاء إجازته والعودة إلى عمله، وجب عليه أن يقدم طلبًا كتابيًا بذلك، وأن يوافق المجلس الطبى المختص على عودته.$m208$,'<<CR>>',chr(13))),
('law',18,2020,7,-1,'3b30e70b823e7f82592e017c2cdf170a','270ca2b5d2c117a670812a0d7a43146d',replace($m208$ينشر هذا القانون فى الجريدة الرسمية، ويعمل به من اليوم التالى لتاريخ نشره.

يبصم هذا القانون بختم الدولة، وينفذ كقانون من قوانينها.

صدر برئاسة الجمهورية فى 21 رجب سنة 1441 هـ (الموافق 16 مارس سنة 2020 م).

عبد الفتاح السيسى$m208$,'<<CR>>',chr(13))),
('law',206,2020,6,-1,'8800ce069a0f40d4b77b791e3ff5c984','ac96840ee68d29cbef49e5d33d2a20ae',replace($m208$يُنشر هذا القانون فى الجريدة الرسمية، ويُعمل به من اليوم التالى لتاريخ نشره.
يُبصم هذا القانون بخاتم الدولة، ويُنفذ كقانون من قوانينها.
صدر برئاسة الجمهورية فى 2 ربيع الأول سنة 1442 هـ (الموافق 19 أكتوبر سنة 2020 م).
عبد الفتاح السيسى$m208$,'<<CR>>',chr(13))),
('law',155,2024,1,0,'8436e67aedec9f6c54f054c29db8c136','8d2630a82872deec535726f9722cd056',replace($m208$تعريفات: في تطبيق أحكام هذا القانون،يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها: الهيئة:الهيئة العامة للرقابة المالية. عقد التأمين:عقد يلتزم المؤمن بمقتضاه أن يؤدى إلى المؤمن له أو إلى المستفيد الذي اشترط التأمين لصالحه مبلغًا من المال أو إيرادا مرتبا أو أى عوض مالى آخر في حالة وقوع الحادث أو تحقق الخطر المبين بالعقد وذلك نظير قسط أو أقساط دورية أو أية دفعات مالية أخرى يؤديها المؤمن له للمؤمن،ويشار إليه بلا وثيقة. عقد إعادة التأمين:عقد يلتزم بمقتضاه معيد التأمين بأن يعوض الطرف الثاني المؤمن وهو شركة التأمين عن كل أو جزء من الخسارة التي يتحملها بموجب عقد التأمين الأصلي،وذلك في مقابل التزام الطرف الثاني بسداد قسط إعادة التأمين إلى معيد التأمين. عقد التأمين التكافلي:عقد يهدف إلى تحقيق التعاون بين مجموعة من المشتركين يتعرضون لخطر واحد أو أخطار معينة،حيث يقوم كل منهم بدفع مبلغ مالى على سبيل التبرع يسمى الاشتراك بما يؤدى إلى تكوين صندوق يسمى صندوق المشتركين يتم من خلاله دفع التعويض لمن يستحقه،ويكون هذا الصندوق منفصلاً بشكل تام عن حسابات شركة التأمين التكافلي المتضمنة حسابات المساهمين. الفائض التأميني في مجال التأمين التكافلي:ما تبقى من صافى أقساط المشتركين المؤمن لهم وعوائدها والإيرادات الأخرى المتعلقة بوثائق التأمين بعد خصم جميع المصروفات وصافى التعويضات المدفوعة والمخصصات الفنية خلال السنة.<<CR>>
تأمينات الحياة:جميع عمليات التأمين التي يكون فيها الخطر المؤمن ضده يتعلق بحياة الأشخاص،ويكون الغرض منها دفع مبالغ بسبب وفاة شخص معين أو عجزه عجزا كليا أو جزئيا دائما أو مؤقتًا أو بلوغه سنًا معينة أو ضمان معاش يدفع له أو للمستفيدين منه مدى الحياة أو خلال فترة محددة،كما يشمل أيضا ذات التأمينات التي ترتبط المزايا الخاصة بها باستثمارات في الأوراق والأدوات المالية. تأمينات الحوادث الشخصية طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،والتي يكون فيها الخطر المؤمن ضده متعلقًا بالشخص وناتجا عن حادث وترتب عنه الوفاة أو العجز. تأمينات العلاج الطبي طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،ويكون الغرض منها صرف مزايا نقدية للأشخاص المؤمن عليهم في حالات العجز الناتج عن المرض،وكذا تغطية تكاليف العلاج الطبي. نشاط شركات إدارة برامج الرعاية الصحية:النشاط الذى تتولى من خلاله الشركة مسئولية جميع الأعمال الإدارية المرتبطة بوثائق التأمين الطبي التي تصدرها شركات التأمين،وذلك كطرف ثالث بين شركة التأمين والعميل،وذلك على النحو الذي تحدده الهيئة. عمليات تكوين الأموال:العمليات التي يكون الغرض منها تكوين مال من مشتركين يصرف فى تاريخ محدد مقابل قسط أو أقساط دورية،دون أن يرتبط ذلك باحتمالات الحياة أو الوفاة. الأطراف المرتبطة:الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات الخاضعة لأحكام هذا القانون،سواء كان هذا الاتفاق مكتوبا أو غير مكتوب. ويعد من الأطراف المرتبطة الأشخاص الطبيعيون وأى من أزواجهم وأقاربهم حتى الدرجة الثانية،والأشخاص الاعتبارية والكيانات والاتحادات والروابط والتجمعات المالية المكونة من شخصين أو أكثر والتي تكون غالبية أسهم أو حصص إحداها مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو يكون مالكها شخصا واحدا،كما يعد من الأطراف المرتبطة الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر.<<CR>>
صندوق التأمين الخاص:كل نظام بين مجموعة من الأفراد تربطهم مهنة أو عمل واحد أو أي صلة اجتماعية أخرى ويتألف بغير رأسمال،ويكون الغرض منه أن يؤدى إلى أعضائه أو المستفيدين منه تعويضات أو مزايا تأمينية أو اجتماعية أو معاشات دورية وفقًا لنظامه الأساسي المعتمد من الهيئة والضوابط أو المعايير التي يصدرها مجلس إدارة الهيئة. صناديق التأمين الحكومية:الصناديق التي تتولى عمليات التأمين ضد الأخطار التى لا تقبلها عادة شركات التأمين أو تلك التي ترى الحكومة مزاولتها بنفسها لهدف قومي أو اجتماعي. نظام المزايا المحددة:النظام الذي تحدد فيه الميزة التأمينية سلفًا من خلال دراسة اكتوارية للمركز المالي للصندوق بما يكفل تحقيق التوازن بين المزايا والموارد. نظام الاشتراكات المحددة:النظام الذي تحدد فيه حقوق المشترك بالرصيد التراكمي المتجمع في حسابه عند الاستحقاق،ولا تكون فيه المزايا محددة مسبقًا. النظام المختلط:النظام الذي يجمع بين نظامي المزايا المحددة والاشتراكات المحددة. الحوسبة السحابية:النموذج الذي يمكن من الوصول الشبكي من أي مكان وبشكل مناسب وعند الطلب إلى مجموعة مشتركة من المصادر المادية أو الافتراضية كالشبكات والخوادم ووسائط التخزين والتطبيقات والخدمات التي يمكن توفيرها بسرعة واستخدامها بأقل جهد أو السداد الإلكتروني أو الأنشطة والإعلانات الإلكترونية الخاصة بأى من المنشآت أو الأفراد الخاضعين لإشراف ورقابة الهيئة بما في ذلك آليات ضمان حماية بيانات العملاء وسهولة استرجاعها وقواعد وضوابط الرقابة عليها من الهيئة. مجمعة التأمين:كيانات تؤسسها مجموعة من شركات التأمين أو إعادة التأمين بهدف الاكتتاب في أخطار معينة. الكيان:أى شركة أو منشأة أو مؤسسة أيا كان شكلها القانوني،مصرية أو أجنبية،تسيطر أو تستحوذ بشكل مباشر أو غير مباشر على نسبة ) (%10 أو أكثر من حجم نشاط التأمين بالسوق،أو يمثل نشاط التأمين بالنسبة لها وما يرتبط به من خدمات نسبة تزيد على ) (%50 من ملكية شركاتها التابعة داخل جمهورية مصر العربية التي تعمل في تلك الأنشطة أو الخدمات.$m208$,'<<CR>>',chr(13))),
('law',155,2024,2,0,'b45fc9b736a2143e9148d02f4a731ac7','c26acd39b51964150e6a4da3a5c124cf',replace($m208$تكون مزاولة نشاط التأمين في جمهورية مصر العربية طبقًا للأنواع والفروع التالية:ً أولا -تأمينات الأشخاص وعمليات تكوين الأموال،وتتمثل في الفروع الآتية:<<CR>>
1- تأمينات الحياة.<<CR>>
2- تأمينات الحوادث الشخصية طويلة الأجل.<<CR>>
3- تأمينات العلاج الطبي طويل الأجل.<<CR>>
4- تأمين دفعات التقاعد.<<CR>>
5- عمليات تكوين الأموال.ً ثانيا -تأمينات الممتلكات والمسئوليات،وتتمثل في الفروع الآتية:<<CR>>
1- التأمين ضد أخطار الحريق والأخطار المرتبطة به.<<CR>>
2- التأمين ضد أخطار النقل بأنواعه البرى والنهرى والبحرى والجوى وتأمينات المسئوليات المتعلقة بها.<<CR>>
3- التأمين على أجسام السفن وآلاتها ومهماتها وتأمينات المسئوليات المتعلقة بها.<<CR>>
4- التأمين على أجسام الطائرات وآلاتها ومهماتها وتأمينات المسئوليات المتعلقة بها.<<CR>>
5- التأمين التكميلى على المركبات والمسئوليات المتعلقة بها.<<CR>>
6- التأمين الإلزامي ضد المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع.<<CR>>
7- التأمين ضد الأخطار الهندسية وتأمينات المسئوليات المتعلقة بها.<<CR>>
8- تأمينات البترول والمسئوليات المتعلقة بها.<<CR>>
9- تأمينات الطاقة والمسئوليات المتعلقة بها.<<CR>>
10- التأمينات الزراعية والمسئوليات والأخطار المرتبطة بها.<<CR>>
11- التأمين ضد أخطار الحوادث المتنوعة والمسئوليات.<<CR>>
12- التأمين ضد مخاطر عدم السداد.<<CR>>
13- تأمينات العلاج الطبي قصير الأجل.<<CR>>
14- التأمين ضد المخاطر الإلكترونية.ً ثالثا -التأمين الطبي المتخصص بنوعيه طويل وقصير الأجل وما يرتبط بهما من خدمات وأنشطة.ً رابعا -التأمين متناهى الصغر: وللهيئة أن ترخص بممارسة أى من الأنواع السابقة بأسلوب التأمين التكافلي، وذلك وفقًا للأحكام الواردة في هذا القانون. ويجوز لها أن ترخص بإنشاء شركات تأمين متخصصة في أحد فروع التأمين، وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة على ألا يقل رأسمالها عن الحد المقرر بالنسبة لشركات التأمين الطبي المتخصصة. ويصدر عن مجلس إدارة الهيئة قرار بتحديد ماهية كل من التأمين الطبي وتأمينات الحوادث الشخصية طويلة وقصيرة الأجل،كما يكون للمجلس أن يصدر قرارا بتحديد أنواع تأمينات أخرى وفروع لها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,3,0,'15fbea93ddc43d0a7179bdececd9e962','5c740d533a760566ab637d6e97f942a4',replace($m208$يتكون هيكل قطاع التأمين من:ً أولا -المنشآت التي تزاول التأمين وإعادة التأمين،وهي:<<CR>>
1- شركات التأمين وشركات إعادة التأمين.<<CR>>
2- شركات التأمين التكافلي وإعادة التأمين التكافلي.<<CR>>
3- شركات التأمين الطبي المتخصصة.<<CR>>
4- شركات التأمين متناهى الصغر.<<CR>>
5- مجمعات التأمين.<<CR>>
6- صناديق التأمين الحكومية.<<CR>>
7- صناديق التأمين الخاصة.ً ثانيا -المهن والأنشطة المرتبطة بالتأمين،وهي:<<CR>>
1- الخبراء الاكتواريون.<<CR>>
2- خبراء التأمين الاستشاريون.<<CR>>
3- خبراء تقييم الأخطار.<<CR>>
4- خبراء معاينة وتقدير الأضرار.<<CR>>
5- وسطاء التأمين.<<CR>>
6- وسطاء إعادة التأمين.<<CR>>
7- شركات إدارة برامج التأمين الطبي.ً ثالثا -الاتحادات والأجهزة المعاونة ومكاتب التمثيل،وهي:<<CR>>
1- اتحاد شركات التأمين.<<CR>>
2- اتحادات المهن والأنشطة المرتبطة بالتأمين.<<CR>>
3- الأجهزة المعاونة التى تنشأ وفقًا لحكم المادة (122) من هذا القانون.<<CR>>
4- مكاتب تمثيل منشآت التأمين أو إعادة التأمين أو الأنشطة المرتبطة بهما. ولمجلس إدارة الهيئة الموافقة على الترخيص بأى أنشطة أو خدمات تأمين أخرى وفقًا لمتطلبات السوق،وذلك كله وفقًا للمعايير والقواعد التي يقررها،وعلى ألا يقل رأسمالها المصدر والمدفوع عن الحد المقرر بالنسبة لشركات التأمين الطبي المتخصصة. ) الفصل الثاني ( نشاط التأمين$m208$,'<<CR>>',chr(13))),
('law',155,2024,4,0,'5273b9c3bed802343360dd6ce53e43fc','45efac34171f7ababe3f20f079afd92d',replace($m208$يكون محلاً للتأمين كل مصلحة اقتصادية مشروعة تعود على الشخص من عدم وقوع خطر معين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,5,0,'99eeb1ace9b176c1c69b85b1e4449fe1','7c7e4f11cbf9705a6f474b9f1917857d',replace($m208$يقع باطلاً ما يرد في وثيقة التأمين من الشروط الآتية:<<CR>>
1- الشرط الذي يقضى بسقوط الحق في التأمين بسبب مخالفة القوانين واللوائح، إلا إذا انطوت هذه المخالفة على جناية أو جنحة عمدية أو غش أو تدليس.<<CR>>
2- الشرط الذى يقضى بسقوط حق المؤمن له بسبب تأخره فى إعلان الحادث المؤمن ضده إلى السلطات أو فى تقديم المستندات،إذا تبين من الظروف أن التأخر كان لعذر مقبول ولم يؤد إلى إحداث تغيير جوهرى بمعالم الحادث أو تفاقم الضرر الناتج عنه.<<CR>>
3- كل شرط مطبوع لم يبرز بشكل ظاهر وكان متعلقًا بحالة من الأحوال التي تؤدى إلى البطلان أو السقوط.<<CR>>
4- كل شرط تعسفى آخر يتبين أنه لم يكن لمخالفته أثر في وقوع الحادث المؤمن ضده.$m208$,'<<CR>>',chr(13))),
('law',155,2024,7,0,'6a7f481c6c2df6a165dd7e34eed3dadb','3e6a9dc5522118b829623441a0399c14',replace($m208$يقع باطلاً كل اتفاق يخالف أحكام تنظيم عقد التأمين الواردة بهذا القانون،إلا أن يكون ذلك لمصلحة المؤمن له أو لمصلحة المستفيد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,9,0,'c211ad6562cd7583700026f57028b301','2cc6ae85b3bc435fb037c939ff3afb2f',replace($m208$لا يجوز للشركات التي تزاول تأمينات الأشخاص وعمليات تكوين الأموال أن تميز بين وثيقة وأخرى من وثائق النوع الواحد إلا في الأحوال التي يجيزها مجلس إدارة الهيئة،ويصدر مجلس إدارة الهيئة قرارا بالأحكام والقواعد والضوابط المنظمة لذلك.$m208$,'<<CR>>',chr(13))),
('law',155,2024,10,0,'f380adbdee7d48b3c47b8f4d1aaf6d1f','2ea8b347566dd27c9a414f5ea85cc235',replace($m208$لا يجوز للشركات المنصوص عليها فى المادة (9) من هذا القانون أن تقتطع بصفة مباشرة أو غير مباشرة أى جزء من أموالها المقابلة لتعهداتها الناشئة عن وثائق التأمين التي أصدرتها لتوزيعها بصفة ربح على المساهمين أو حملة الوثائق أو لأداء أى مبلغ يخرج عن التزاماتها.<<CR>>
ولا يجوز توزيع أرباح على المساهمين إلا بمقدار المال الزائد الذي يحدده الخبير الاكتواري في تقريره بعد إجراء الفحص المشار إليه فى المادة (174) من هذا القانون، ويتم التوزيع وفقًا للقواعد التي يحددها مجلس إدارة الهيئة في هذا الشأن. وفي تطبيق هذه المادة يجوز اعتبار أموال الشركة فى جمهورية مصر العربية وفى الخارج وحدة واحدة وذلك بعد موافقة مجلس إدارة الهيئة ودون الإخلال بأحكام المادة (175) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,11,0,'454118c9072901c72c2ab9386375eb23','d5749725f01526b44aae1ad898766042',replace($m208$يجوز للهيئة الترخيص لشركات التأمين المنصوص عليها في المادة (9) من هذا القانون بعمل سحب يانصيب وذلك وفقًا للأحكام والضوابط الصادرة عن مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,12,0,'9d9ce1a409bb0c111c42e868d3d4948b','1f4fa63a4285b8a729c9d331adb54150',replace($m208$في حالة إفلاس أو تصفية إحدى الشركات التي تزاول تأمينات الأشخاص وعمليات تكوين الأموال يتم تقدير المبالغ المستحقة لكل حامل وثيقة لم تنته مدتها بما يعادل الاحتياطى الحسابي الخاص بها يوم الحكم بالإفلاس أو صدور قرار بالتصفية. ويتم تقدير الاحتياطى الحسابى المشار إليه بالفقرة الأولى من هذه المادة آخر المدة بمعرفة خبير اكتوارى لمقابلة التزامات الشركة قبل حملة الوثائق في نهاية السنة المالية،وذلك وفقًا للقواعد والأسس الفنية التي يعتمدها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,14,0,'05987f02818fb33e9084fcaa300aad54','e1b606e560c5a1c465c43bc932b512ec',replace($m208$تبرأ ذمة شركة التأمين من التزاماتها بدفع مبلغ التأمين إذا انتحر الشخص المؤمن على حياته،ومع ذلك تلتزم الشركة بأن تدفع لمن يئول إليهم الحق مبلغًا يساوى نصيبه في قيمة الاحتياطي الحسابي للتأمين.<<CR>>
فإذا كان سبب الانتحار مرضا أفقد المريض إرادته بقى التزام شركة التأمين قائما بأكمله،وعلى الشركة المؤمنة أن تثبت أن المؤمن على حياته مات منتحرا، وعلى المستفيد أن يثبت أن المؤمن على حياته كان وقت انتحاره فاقد الإرادة. وإذا اشتملت وثيقة التأمين على شرط يلزم شركة التأمين بدفع مبلغ التأمين ولو كان انتحار الشخص عن اختيار وإدراك،فلا يكون هذا الشرط نافذًا إلا إذا وقع الانتحار بعد سنتين من تاريخ العقد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,15,0,'76fd8bd445de930cf5cd09a49ca7d5e2','34d7668d06c59a78ab19c7d55f021ba5',replace($m208$إذا كان التأمين على حياة شخص غير المؤمن له برئت ذمة شركة التأمين من التزاماتها متى تسبب المؤمن له عمدا في وفاة ذلك الشخص أو وقعت الوفاة بناء على تحريض منه. وإذا كان التأمين على الحياة لصالح شخص غير المؤمن له فلا يستفيد هذا الشخص من التأمين إذا تسبب عمدا في وفاة الشخص المؤمن على حياته،أو وقعت الوفاة بناء على تحريض منه. فإذا كان ما وقع من هذا الشخص مجرد شروع فى إحداث الوفاة،كان للمؤمن له الحق في أن يستبدل بالمستفيد شخصا آخر،ولو كان المستفيد قد قبل ما اشترط لمصلحته من تأمين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,16,0,'02117e466ff369ac0e6fbda189e6bb48','2d883e14409499e637ecf0ce7be0cbdf',replace($m208$يجوز في التأمين على الحياة الاتفاق على أن يدفع مبلغ التأمين،إما إلى أشخاص معينين،وإما إلى أشخاص يعينهم المؤمن له فيما بعد. ويعتبر التأمين معقودا لمصلحة مستفيدين معينين إذا ذكر المؤمن له في الوثيقة أن التأمين معقود لمصلحة زوجه أو أولاده أو فروعه من ولد منهم ومن لم يولد، أو لورثته دون ذكر أسمائهم.فإذا كان التأمين لصالح الورثة دون ذكر أسمائهم كان لهؤلاء الحق فى مبلغ التأمين كل بنسبة نصيبه فى الميراث،ويثبت لهم هذا الحق ولو نزلوا عن الإرث. ويقصد بالزوج الشخص الذى تثبت له هذه الصفة وقت وفاة المؤمن له،ويقصد بالأولاد الفروع الذين يثبت لهم فى ذلك الوقت حق الإرث.$m208$,'<<CR>>',chr(13))),
('law',155,2024,18,0,'a3006b413afd7e10262c31f79b0578eb','72eba0ef0752f74c1f522ecf30297a5c',replace($m208$يجوز للمؤمن له أن يستبدل بالوثيقة الأصلية وثيقة مدفوعة في مقابل تخفيض في قيمة مبلغ التأمين،ولو اتفق على غير ذلك،شريطة أن يكون الحادث المؤمن ضده محقق الوقوع،وذلك في الحالتين الآتيتين:<<CR>>
1- في العقود المبرمة مدى الحياة دون اشتراط بقاء المؤمن على حياته مدة معينة.<<CR>>
2- في جميع العقود المشترط فيها دفع مبلغ التأمين بعد عدد معين من السنين. ولا يكون قابلاً للتخفيض التأمين على الحياة إذا كان مؤقتًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,19,0,'74d97f5cebf010c41b21c608c157556b','9c49e733a3b59928ba348a835ad8502a',replace($m208$إذا خفض التأمين فلا يجوز أن ينزل عن الحدود الآتية:<<CR>>
1- في العقود المبرمة مدى الحياة لا يجوز أن يقل مبلغ التأمين المخفض عن القيمة التي كان يستحقها المؤمن له لو كان قد دفع ما يعادل الاحتياطى الحسابي في تاريخ التخفيض مخصوما منه ) (%1 من مبلغ التأمين الأصلي،باعتبار أن هذا المبلغ هو مقابل التأمين الذى يجب دفعه مرة واحدة في تأمين من ذات النوع وطبقًا لتعريفة التأمين التي كانت مرعية في عقد التأمين الأصلي.<<CR>>
2- في العقود المتفق فيها على أداء مبلغ التأمين بعد عدد معين من السنين، لا يجوز أن يقل مبلغ التأمين المخفض عن جزء من مبلغ التأمين الأصلى بنسبة ما دفع من أقساط.$m208$,'<<CR>>',chr(13))),
('law',155,2024,20,0,'087c2c8370e5cd27fbd468943bed7eaf','9c1147b86001967bf1391e46561ec3d6',replace($m208$يجوز للمؤمن له،متى كان قد دفع ثلاثة أقساط سنوية على الأقل،أن يصفى التأمين بشرط أن يكون الحادث المؤمن منه محقق الوقوع. كما تكون قابلة للتصفية عقود التأمين المؤقتة بقسط وحيد مسدد بالكامل في بداية سريان التأمين. ولا يكون قابلاً للتصفية،التأمين على الحياة إذا كان مؤقتًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,21,0,'7993b8234268fc3937e81fde3997df15','41cdc66bc98f4fec00587ae2a2548e08',replace($m208$تعتبر شروط التخفيض والتصفية جزءا من الشروط العامة للتأمين ويجب أن تذكر في وثيقة التأمين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,24,0,'61a0e59869bb1c7833af4bacd4b0a7b3','35a24da131ab76d35c5dfa42361ed4c4',replace($m208$يقع باطلاً التأمين على حياة الغير ما لم يوافق الغير عليه كتابة قبل إبرام العقد، فإذا كان هذا الغير لا تتوافر فيه الأهلية فلا يكون العقد صحيحا إلا بموافقة من يمثله قانونًا. وتكون هذه الموافقة لازمة لصحة حوالة الحق في الاستفادة من التأمين أو لصحة رهن هذا الحق.<<CR>>
التأمين ضد أخطار الحريق$m208$,'<<CR>>',chr(13))),
('law',155,2024,25,0,'bfe3d90f95156d2cd36c0fc2390827e3','d6f48471bbdaaaf28dcb1d6d089e9d11',replace($m208$في التأمين ضد أخطار الحريق تكون شركة التأمين مسئولة عن جميع الأضرار الناشئة عن حريق،أو عن بداية حريق يمكن أن تصبح حريقًا كاملاً،أو عن خطر حريق يمكن أن يتحقق. ولا يقتصر التزام الشركة على الأضرار الناشئة مباشرة عن الحريق،بل يتناول أيضا الأضرار التي تكون نتيجة حتمية لذلك،وبالأخص ما يلحق الأشياء المؤمن عليها من ضرر بسبب اتخاذ وسائل الإنقاذ أو منع امتداد الحريق. وتكون الشركة مسئولة عن ضياع الأشياء المؤمن عليها واختفائها أثناء الحريق ما لم يثبت أن ذلك كان نتيجة سرقة،ولو تم الاتفاق على غير ذلك.$m208$,'<<CR>>',chr(13))),
('law',155,2024,27,0,'7e9d2393a65ad8db13b90159dbd4d020','7fb103b75b96efa2edc3339cb41e2526',replace($m208$تكون شركة التأمين مسئولة عن الأضرار الناشئة عن خطأ المؤمن له غير المتعمد،وكذلك تكون مسئولة عن الأضرار الناجمة عن حادث مفاجئ أو قوة قاهرة. أما الخسائر والأضرار التي يحدثها المؤمن له عمدا أو غشًا،فلا تكون شركة التأمين مسئولة عنها ولو اتفق على غير ذلك.$m208$,'<<CR>>',chr(13))),
('law',155,2024,28,0,'9bee0b17c45254132820d9b8e72ac024','dcc2c99df2a2ff82b53a6a95d8a51ee4',replace($m208$تساءل شركة التأمين عن الأضرار التي تسبب فيها الأشخاص الذين يكون المؤمن له مسئولاً عنهم،أيا كان نوع خطئهم ومداه ما لم يكن للمؤمن له دور في تحقق تلك الأضرار.$m208$,'<<CR>>',chr(13))),
('law',155,2024,29,0,'ddfa6c70fa304d3e7a14a92588f8b919','a18c1fcb56a7b778866368804884e34c',replace($m208$إذا كان الشيء المؤمن عليه مثقلاً برهن حيازى أو إشهار الرهن في سجل الضمانات المنقولة أو رهن تأمينى أو غير ذلك من التأمينات العينية،انتقلت هذه الحقوق إلى التأمين المستحق للمدين بمقتضى عقد التأمين.<<CR>>
فإذا شهرت هذه الحقوق أو أعلنت إلى شركة التأمين ولو بكتاب موصى عليه، فلا يجوز لها أن تدفع ما فى ذمتها للمؤمن له إلا برضاء الدائنين. فإذا حجز على الشيء المؤمن عليه أو وضع هذا الشيء تحت الحراسة، فلا يجوز لشركة التأمين إذا أعلنت بذلك على الوجه المبين فى الفقرة الثانية من هذه المادة أن تدفع للمؤمن له شيئًا مما في ذمتها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,30,0,'264a224d49f5fc46cb47472e219c430b','54a850e843aa49560cd2f418387471e3',replace($m208$تحل شركة التأمين قانونًا بما دفعته من تعويض عن الأضرار المغطاة في الدعاوى التي تكون للمؤمن له قبل من تسبب بفعله فى الضرر الذى نجمت عنه مسئولية شركة التأمين،ما لم يكن من أحدث الضرر قريبا أو صهرا للمؤمن له ممن يكونون معه في معيشة واحدة،أو شخصا يكون المؤمن له مسئولاً عن أفعاله. نشاط التأمين الطبي المتخصص وما يرتبط به من خدمات$m208$,'<<CR>>',chr(13))),
('law',155,2024,31,0,'0ab45716aef00f19b49bbeae2ce4a737','ba68bb443f0209c888536ea48b1437b3',replace($m208$للهيئة الترخيص بإنشاء شركات تأمين متخصصة يقتصر غرضها على مزاولة التأمين الطبي بنوعيه قصير وطويل الأجل. ويكون تأسيس تلك الشركات وقيدها والترخيص لها بمزاولة النشاط من الهيئة وفقًا للشروط والقواعد والإجراءات الواردة بأحكام هذا القانون والقرارات الصادرة تنفيذًا له. ويحدد مجلس إدارة الهيئة الحد الأدنى لرأس المال المصدر والمدفوع بالكامل لتلك الشركات بما لا يقل عن ستين مليون جنيه أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.$m208$,'<<CR>>',chr(13))),
('law',155,2024,32,0,'c2b097e8b7d7a202dbb5a85c81b09c39','1d88a887e1666eee8a4e672cc4f22c36',replace($m208$لا يجوز لأى شركة مزاولة نشاط إدارة برامج الرعاية الصحية إلا بعد الحصول على ترخيص بذلك من الهيئة والقيد لديها في سجل يعد لهذا الغرض. ويقتصر غرض الشركة على مزاولة نشاط إدارة برامج الرعاية الصحية. ويكون تأسيس تلك الشركات وقيدها والترخيص لها بمزاولة النشاط من الهيئة وفقًا للشروط والقواعد والإجراءات الواردة بأحكام هذا القانون والقرارات الصادرة تنفيذًا له.$m208$,'<<CR>>',chr(13))),
('law',155,2024,35,0,'0d53fbdff79b49e69ba55507fffb9892','8937884a7df5579233b83179d95977e5',replace($m208$يجوز بترخيص من الهيئة تأسيس شركات تأمين يقتصر غرضها الوحيد على مزاولة التأمين التكافلي أو إعادة التأمين التكافلي. ويكون تأسيس تلك الشركات وقيدها والترخيص لها بمزاولة النشاط وفقًا للشروط والقواعد والإجراءات الواردة بهذا القانون والقرارات الصادرة تنفيذًا له.$m208$,'<<CR>>',chr(13))),
('law',155,2024,36,0,'5ec3f957ba7a7aa01e6168ca4aa7528e','f36f42f4a23896d8dea2cba5fa5c8896',replace($m208$لا يجوز أن تجمع شركة التأمين التكافلي بين مزاولة فروع التأمين الواردة في البند أولاً من الفقرة الأولى من المادة (2) من هذا القانون ومزاولة الفروع الواردة بالبند ثانيا من ذات المادة. كما لا يجوز الجمع بين ممارسة صيغة التأمين التكافلي أو إعادة التأمين التكافلي، وغيرها من صيغ التأمين وإعادة التأمين. نشاط التأمين متناهى الصغر$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',155,2024,37,0,'c061ae36d233c0877e056d30613dfd03','897cf9d4683db7d2f9ac3cfdde78a96e',replace($m208$يعد تأمينًا متناهى الصغر كل تأمين يستهدف ذوى الدخول المنخفضة في مجالات تأمين الممتلكات والأشخاص لحمايتهم من أخطار قد يتعرضون لها وبحد أقصى للتغطية مبلغ مائتي ألف جنيه،ويجوز لمجلس إدارة الهيئة زيادته سنويا بنسبة لا تزيد على ) (%25 وذلك في الفروع المنصوص عليها بالمادة (2) من هذا القانون.<<CR>>
وتحدد قرارات مجلس إدارة الهيئة أنواع هذا التأمين والحد الأقصى لمبالغ التأمين وأسس الاكتتاب والشروط والقواعد الخاصة بهذا النوع من التأمين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,38,0,'0d230c9c08cb666b82a8a4f4a47c9b92','8855c448fae02e4bfe9e230f384b81e6',replace($m208$تعفى أقساط وثائق التأمين متناهى الصغر من الرسوم المقررة بالمادة (208) من هذا القانون،وذلك وفقًا للقواعد التي يصدرها مجلس إدارة الهيئة. نشاط التأمين الإلزامى$m208$,'<<CR>>',chr(13))),
('law',155,2024,39,0,'d023cc1646234bae5eaa3d2900786181','0a43297b770f0f2c5e0e8981624f8e6d',replace($m208$لمجلس إدارة الهيئة اقتراح مجموعة من التأمينات الإلزامية المناسبة للسوق المصرية وفقًا لما يعده من دراسات فنية متخصصة لكل نوع من أنواع التأمين الإلزامي ويصدر بها قرار من مجلس الوزراء يوضح الفئات والشروط والضوابط والأسعار الخاصة بكل منها على حدة لإنفاذها،على أن تكون من بينها التأمينات الآتية:<<CR>>
1- تأمينات المسئوليات المهنية بجميع أنواعها كشرط من شروط الترخيص بمزاولة النشاط أو المهنة.<<CR>>
2- التأمين ضد حوادث الطرق السريعة المتميزة ذات الرسوم.<<CR>>
3- التأمين ضد حوادث السكك الحديدية ومترو الأنفاق.<<CR>>
4- التأمين على طلاب المدارس والمعاهد الأزهرية والمعاهد والجامعات بما في ذلك طلاب جامعة الأزهر والمعاهد التابعة لها.<<CR>>
5- تغطيات التأمين ضد المخاطر الإلكترونية لجميع المنشآت العاملة بالقطاعات المالية غير المصرفية.<<CR>>
6- التأمين ضد المخاطر التي قد تتعرض لها المرافق العامة والأصول المملوكة للدولة.<<CR>>
7- التأمين ضد مخاطر حالات الطلاق.<<CR>>
8- التأمين متناهى الصغر ضد حالتى الوفاة والعجز الكلى المستديم.<<CR>>
9- التأمين ضد المخاطر التي يتعرض لها المصريون في الخارج.<<CR>>
التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع داخل جمهورية مصر العربية$m208$,'<<CR>>',chr(13))),
('law',155,2024,40,0,'2ad048e9402ead777775b197149ade04','a399842a6dfa20a19ae492f5b8ecd76e',replace($m208$يجب التأمين عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع المرخص في تسييرها طبقًا لأحكام قانون المرور الصادر بالقانون رقم 66 لسنة 1973 ويشمل التأمين حالات الوفاة والإصابة البدنية التي ينتج عنها عجز،وكذا الأضرار المادية التي تلحق بممتلكات الغير عدا تلفيات المركبات،وذلك وفقًا لأحكام وثيقة التأمين الصادرة في هذا الشأن.$m208$,'<<CR>>',chr(13))),
('law',155,2024,41,0,'08d98bb195bfa406b0d7531bab9508b7','77c2067c7b5fdc90b184de706907d183',replace($m208$تقبل في نطاق تطبيق أحكام هذا القانون بطاقات التأمين الموحدة عن سير المركبات عبر البلاد العربية أو وثائق أو بطاقات أو شهادات التأمين الصادرة طبقًا للاتفاقيات الدولية النافذة فى جمهورية مصر العربية،بشرط أن يكون التأمين بموجب هذه البطاقات أو الوثائق أو الشهادات ساريا طوال مدة بقاء المركبة في جمهورية مصر العربية وشاملاً أوجه المسئولية المدنية المنصوص عليها فى المادة (40) من هذا القانون،وأن تبين البطاقة أو الشهادة أو الوثيقة مجمعة التأمين المصرية التي تعهدت بتسوية التعويضات المترتبة على ذلك.$m208$,'<<CR>>',chr(13))),
('law',155,2024,42,0,'f95895e8232ff202ac3f883e5554dfc6','43b9cd84e3110ad2619aed3357774bcd',replace($m208$يلتزم مالك المركبة أو من يقوم مقامه قانونًا بالتأمين الإلزامي على المركبة، وذلك عند ترخيص المركبة أو عند تجديد الترخيص بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',155,2024,43,0,'010754e992a1db269cdfc93449bd3df8','5ca852e9650172f2aa9c561b0b27f90d',replace($m208$مع مراعاة حكم المادة (42) من هذا القانون يتم التأمين لدى إحدى شركات التأمين المسجلة لدى الهيئة والمرخص لها بمزاولة فرع التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع طبقًا لأحكام هذا القانون.<<CR>>
وتكون مزاولة هذا التأمين من خلال مجمعة تنشأ بين تلك الشركات لإدارة التأمين الإلزامى عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع بجمهورية مصر العربية،وذلك وفقًا للنظام الأساسي للمجمعة المعتمد من الهيئة ويمتنع على أى شركة تأمين مزاولة هذا النشاط خارج المجمعة،ولا يجوز حل مجمعة التأمين أو تصفيتها إلا بقرار من مجلس إدارة الهيئة وتلتزم هذه الشركات بقبول التأمين المشار إليه وبإصدار الوثائق الخاصة به.$m208$,'<<CR>>',chr(13))),
('law',155,2024,45,0,'a3ce477ccd4ebdf81157c8cbe561930f','46238e49b38f8924b0af7d647f545364',replace($m208$يسري مفعول التغطية التأمينية طوال مدة الترخيص بتسيير المركبة،وخلال المهلة المسموح فيها بتجديد الترخيص طبقًا لأحكام قانون المرور المشار إليه، ويسرى مفعول تجديد التغطية التأمينية من اليوم التالى لانتهاء مدة الترخيص حتى نهاية المهلة المسموح خلالها بتجديده.$m208$,'<<CR>>',chr(13))),
('law',155,2024,46,0,'75e1a9d2ac6104954cc5c2b48e316e30','f5dd2a51136d02b0cca921805f31ecb9',replace($m208$يصدر بتحديد أسعار التأمين المنصوص عليه بالمادة (40) من هذا القانون وما يرتبط به من مصروفات إصدار وتحصيل قرار من مجلس إدارة الهيئة،وذلك استنادا إلى الدراسات الفنية والاكتوارية التي تعد في هذا الشأن. ولمجلس إدارة الهيئة بعد أخذ رأى وزارة الداخلية وموافقة رئيس مجلس الوزراء، تحديد أسعار إضافية لهذا التأمين فى الحالات التي تزيد فيها المخاطر التأمينية. وعلى مجمعة التأمين المعنية الالتزام بهذه الأسعار في الوثائق التي تصدرها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,47,0,'2b022159daf7b13da3e778f7345d9eba','26597096f0511316c0e3dec5348d8750',replace($m208$تؤدى مجمعة التأمين المعنية مبلغ التأمين المحدد عن الحوادث المشار إليها في المادة (40) من هذا القانون إلى المستحق أو ورثته وذلك دون الحاجة إلى اللجوء للقضاء في هذا الخصوص.<<CR>>
ويكون مبلغ التأمين الذي تؤديه مجمعة التأمين المعنية مائة ألف جنيه في حالات الوفاة أو العجز الكلى المستديم ويحدد مقدار مبلغ التأمين في حالات العجز الجزئي المستديم بمقدار نسبة العجز كما يحدد التعويض عن الأضرار التي تلحق بممتلكات الغير بحد أقصى عشرون ألف جنيه. ولمجلس إدارة الهيئة،استنادا إلى الدراسات الفنية والاكتوارية التي تعد في هذا الشأن،زيادة مبالغ التأمين المذكورة وبما لا يزيد على ) (%50 منها في كل حالة، وذلك بعد أخذ رأى وزارة الداخلية وموافقة رئيس مجلس الوزراء. ويحدد مجلس إدارة الهيئة كيفية وشروط أداء مبلغ التأمين للمستحقين في كل من الحالات المشار إليها،على أن يصرف مبلغ التأمين في مدة لا تجاوز ثلاثين يوما من تاريخ إبلاغ شركة التأمين أو الصندوق المشار إليه بالمادة (61) من هذا القانون بوقوع الحادث واستيفاء المستندات اللازمة لفحص الطلب.$m208$,'<<CR>>',chr(13))),
('law',155,2024,48,0,'9dce8a7e8dd4904ed1dce0807714224a','6e0e360b53517e656541ed49fe9f5522',replace($m208$للمضرور أو ورثته اتخاذ الإجراءات القضائية قبل المتسبب عن الحادث والمسئول عن الحقوق المدنية،لمطالبته بما يجاوز مبلغ التأمين المنصوص عليه وفقًا لأحكام وثيقة التأمين الصادرة وفقًا لهذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,49,0,'cbc41f9ea17aa68a6c6bd31a25cba9d0','bdf5acde513391025163a23c2460aa79',replace($m208$لا يجوز لمجمعة التأمين المعنية أداء مبلغ التأمين إلى وكيل المضرور أو وكيل ورثته إلا بمقتضى توكيل خاص مصدق عليه صادر بعد تحديد مبلغ التأمين وفقًا لنص المادة (47) من هذا القانون. ويجب أن يتضمن التوكيل قيمة مبلغ التأمين وبما يخول للوكيل حق استلامه من مجمعة التأمين المعنية أو الصندوق المشار إليه بالمادة (61) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,50,0,'f198ef09200e5270dd8f0592e0ada66a','b96d59161f151e3e6d53b45a9d617bc0',replace($m208$في حالة تلقى النيابة العامة بلاغًا أو محضر استدلال محررا من مأمور الضبط القضائى فى واقعة حادث موجب للتعويض وفقًا لأحكام التأمين الإلزامي عن المسئولية الناشئة عن حوادث مركبات النقل السريع،يستعلم من إدارة المرور المختصة عن اسم المؤمن له،ويثبت ذلك بمحضر التحقيق وعليها إخطار مجمعة التأمين المعنية بوقوع الحادث،وكذلك الصندوق في الحالات التي يختص بها وفقًا لأحكام المادة (61) من هذا القانون بالنموذج الصادر فى هذا الشأن عن النيابة العامة محددا به بيانات المركبة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,51,0,'0b72c00018578ce1f60a00e16074c93d','d0d739d49f7855d5b74594e9f01e4ba3',replace($m208$يلتزم المؤمن له أو من ينوب عنه قانونًا بإبلاغ مجمعة التأمين المعنية بالحادث الذي تسببت فيه المركبة،والموجب للتعويض وفقًا لهذا القانون،خلال خمسة عشر يوما من تاريخ وقوعه،وعليه أن يتخذ جميع الاحتياطات والإجراءات اللازمة لتجنب تفاقم الأضرار الناجمة عنه. كما يلتزم بأن يقدم إلى مجمعة التأمين المعنية جميع الأوراق والمستندات المتعلقة بالحادث حال تسليمها له. وإذا أخل المؤمن له بأى من التزاماته المنصوص عليها في الفقرتين الأولى والثانية من هذه المادة فإن لمجمعة التأمين الرجوع عليه بالأضرار التي تصيبها نتيجة ذلك،ما لم يكن التأخير مبررا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,52,0,'b251d6e5f465f7d2973ed33d093fb945','4c7e2cc4d83f29141e29e4a3559907b6',replace($m208$إذا كانت المسئولية عن حادث موجب لاستحقاق مبلغ التأمين وفقًا للتأمين الإلزامي عن المسئولية الناشئة عن حوادث مركبات النقل السريع مشتركة بين مركبتين أو أكثر،يحق للمضرور أو ورثته الحصول على مبلغ التأمين المنصوص عليه في المادة (47) من هذا القانون من أى من مؤمنى المركبات المتسببة في الحادث والصندوق المشار إليه فى المادة (61) من هذا القانون،بحسب الأحوال. وتكون تسوية مبلغ التأمين بين مجمعة التأمين المعنية والصندوق،بحسب الأحوال،بالتساوى بينهما.$m208$,'<<CR>>',chr(13))),
('law',155,2024,53,0,'d03dec8f64f96e15c6a48d33848f2fec','1c03e5b043344216facae127742c9fae',replace($m208$إذا توفى المصاب أو لحق به عجز كلى مستديم من جراء الحادث خلال سنة من تاريخ وقوعه وثبت بشهادة طبية معتمدة أن الوفاة أو العجز الكلى المستديم كانا نتيجة الحادث،وجب على مجمعة التأمين المعنية أن تؤدى إلى الورثة أو المضرورين مبلغ التأمين المنصوص عليه فى المادة (47) من هذا القانون،أو أن تكمل مبلغ التأمين الذي سبق أن دفعته ليصل إلى هذا الحد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,56,0,'781fdc45ed0542ffa3a54e15e21bb9e0','40d0d8a037f22fd7b031c29693539aa9',replace($m208$يجوز لمجمعة التأمين المعنية أن ترجع على المؤمن له بقيمة ما تكون قد أدته من مبلغ التأمين إذا ثبت أن التأمين قد عقد بناء على إدلاء المؤمن له ببيانات كاذبة أو إخفائه وقائع جوهرية تؤثر فى حكم مجمعة التأمين المعنية على قبولها تغطية الخطر أو أن المركبة استخدمت في أغراض لا يخولها الترخيص.$m208$,'<<CR>>',chr(13))),
('law',155,2024,57,0,'4dc252d91d6bdbe8e0bd8155f8b8f988','4ed9e2cc56204d8ccbf054444681db80',replace($m208$لا يترتب على حق الرجوع المقرر لمجمعة التأمين المعنية وفقًا لأحكام المادتين (55، 56) من هذا القانون الإخلال بحق المضرور فى الرجوع على المسئول عن الحقوق المدنية. ) الفصل الرابع ( نشاط مجمعات التأمين$m208$,'<<CR>>',chr(13))),
('law',155,2024,58,0,'68d7ca83775c8757bfe4133e72d39596','22e2587d0f35475c4a8e0f50902d740c',replace($m208$يجوز لشركات التأمين الخاضعة لأحكام هذا القانون أن تنشئ فيما بينها مجمعة أو أكثر لإدارة خطر أو عملية بذاتها وفقًا للنظام الأساسي لكل مجمعة تأمين، وذلك في حالة توافر أى من الأخطار الآتية:<<CR>>
1- الأخطار ذات الطبيعة القومية التي يصعب فيها الحصول على ترتيبات إعادة التأمين.<<CR>>
2- الأخطار النمطية التي لا تحتاج إلى عمليات اكتتاب فنية.<<CR>>
3- الأخطار الطبيعية.<<CR>>
4- الحالات الأخرى التي يقررها مجلس إدارة الهيئة ووفقًا للضوابط والمعايير التي يقررها. ويكون لمجمعة التأمين الحق فى إصدار الوثائق التي تغطى هذه الأخطار وفى هذه الحالة تخضع لذات الضوابط المقررة على شركات التأمين في هذا الشأن ومنها تلك المتعلقة بالمخصصات الفنية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,59,0,'ed824277c68df6da26f76c7143cf1f34','01a5c970fb91304af1c4b63c16d23434',replace($m208$يضع الأعضاء المؤسسون للمجمعة النظام الأساسي لها،ويصدر بإنشاء مجمعة التأمين والتصديق على نظامها قرار من مجلس إدارة الهيئة. وتسجل المجمعة في سجل خاص لدى الهيئة بعد أداء رسم مقداره مائة ألف جنيه، يسدد وفقًا لطرق السداد المقررة قانونا وتكتسب الشخصية الاعتبارية الخاصة من تاريخ نشر قرار التسجيل في الوقائع المصرية. ويجب إخطار الهيئة بأية تعديلات تطرأ على النظام الأساسي وبمبررات هذا التعديل،ولا يجوز العمل بهذه التعديلات إلا بعد اعتمادها من مجلس إدارة الهيئة ونشرها بالوقائع المصرية. ) الفصل الخامس ( نشاط صناديق التأمين الحكومية$m208$,'<<CR>>',chr(13))),
('law',155,2024,60,0,'930c54f3c6aae909e2674757bf434c6c','a10844b9545dd6c4be46a9e8a36fd8a6',replace($m208$يكون إنشاء صندوق التأمين الحكومى بقرار من رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة،ويكون له الشخصية الاعتبارية الخاصة من تاريخ نشر هذا القرار بالوقائع المصرية. ويصدر بتحديد شروط وأسعار عمليات التأمين المشار إليها قرار من مجلس إدارة الهيئة. ويتم تسجيل تلك الصناديق بالسجل المعد لذلك بالهيئة فى مقابل رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا. ويصدر مجلس إدارة الهيئة قرارا بالأحكام المنظمة لأوجه رقابة الهيئة على هذه الصناديق.$m208$,'<<CR>>',chr(13))),
('law',155,2024,61,0,'23f70a515f393f6c14785a9ec9420854','b462c207b202d2a7d183d183c6af0203',replace($m208$يقوم الصندوق الحكومي لتغطية الأضرار الناتجة عن حوادث مركبات النقل السريع بتغطية الأضرار الناشئة عن الحوادث المشار إليها في الحالات الآتية:<<CR>>
1- عدم معرفة المركبة المسئولة عن الحادث.<<CR>>
2- عدم وجود تأمين على المركبة لصالح الغير.<<CR>>
3- حوادث المركبات المعفاة من بعض إجراءات الترخيص.<<CR>>
4- حالات إعسار شركة التأمين كليا أو جزئيا.<<CR>>
5- الحالات الأخرى التى يصدر بها قرار من مجلس إدارة الهيئة. ويؤدى الصندوق مبلغ التأمين للمستحقين طبقًا لأحكام المادة (47) من هذا القانون،ويحق له فى الحالة المنصوص عليها في البندين (2، 3) من الفقرة الأولى من هذه المادة الرجوع على مالك السيارة أو المركبة المتسببة فى الضرر بقيمة التأمين الذي أداه. ويجب على المتضرر تقديم طلب التعويض للصندوق مصحوبا بالمستندات التي يصدر بتحديدها قرار من مجلس إدارة الهيئة،ويتولى الصندوق البت في الطلب خلال شهر من تاريخ تقديمه. ولا يجوز للمتضرر اتخاذ أية إجراءات قضائية ضد الصندوق قبل تقديم الطلب ومرور المدة المشار إليها بالفقرة الثالثة من هذه المادة،ولا تقبل الدعاوى المرفوعة دون مراعاة تقديم الطلب المشار إليه. ويختص رئيس مجلس الوزراء بتعديل نظام الصندوق. وتتولى مجمعة التأمين المعنية تمويل الصندوق بنسبة من متحصلات الأقساط، ويصدر بتحديد هذه النسبة قرار من مجلس إدارة الهيئة بناء على تقرير فني تعده الهيئة عن هذه المتحصلات. كما تلتزم شركات التأمين أعضاء مجمعة التأمين المعنية المرخص لها بمزاولة نشاط التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع داخل جمهورية مصر العربية بسداد أى عجز مالي يواجه الصندوق.$m208$,'<<CR>>',chr(13))),
('law',155,2024,62,0,'613046015539587c821af89f82ca211f','7d0780874e85ecc6252d4355e6aa35c8',replace($m208$يصدر رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة قرارا بتصفية الصندوق الحكومي في الحالات التالية:<<CR>>
1- إذا تبين من نتيجة فحص المركز المالي للصندوق أن أمواله لا تكفى للوفاء بالتزاماته.<<CR>>
2- إذا ثبت أن الصندوق لا يسير وفقًا لأحكام هذا القانون أو القرارات المنفذة له أو لنظامها الأساسي بحسب الأحوال. وينذر الصندوق بالمخالفات ويمنح مهلة ثلاثين يوما لإبداء دفاعه وفى حالة عدم تصحيح وضعه يصفى الصندوق. ويحدد القرار قواعد وإجراءات التصفية والجهة التي تئول إليها هذه الأموال، ويكون لها ما للصندوق من حقوق وتتحمل بالتزاماته.<<CR>>
) الفصل السادس ( نشاط صناديق التأمين الخاصة أحكام عامة$m208$,'<<CR>>',chr(13))),
('law',155,2024,64,0,'fb895d4f60181deb3ca8226760005251','2ddcb7b766335f4cd9b1e5af1f6cf67a',replace($m208$يجب أن تسجل صناديق التأمين الخاصة بمجرد إنشائها في السجل المعد لذلك بالهيئة وذلك وفقًا للقواعد والإجراءات المنصوص عليها في هذا الباب. وتضع الهيئة الشروط الواجب توافرها في النظم الأساسية للصناديق الخاضعة لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,67,0,'6bf50d817937916a6d5b16e30d1a0974','abbb53e6aff2aa6499cc60069486cfc4',replace($m208$على صناديق التأمين الخاصة المسجلة بسجلات الهيئة والتي يبلغ حجم أموالها عشرة ملايين جنيه على الأقل أن تنشئ لها موقعا إلكترونيا لتمكين أعضائها من الاطلاع على جميع البيانات والأحكام الخاصة بالصندوق،ومنها أغراضه ومزاياه واشتراكاته والقرارات الصادرة عن إدارته وذلك وفقًا للضوابط التي تضعها الهيئة.<<CR>>
تسجيل الصناديق وتعديل أنظمتها الأساسية$m208$,'<<CR>>',chr(13))),
('law',155,2024,68,0,'266b2096a6968f789aae95b037d24cc6','a0c330017afe8c0c4283c99df8feac0e',replace($m208$يقدم طلب قيد الصندوق إلى الهيئة مرفقًا به النظام الأساسي للصندوق وفقًا للنموذج المعتمد من مجلس إدارة الهيئة،وبعد استيفاء البيانات والمستندات التي تحددها الهيئة. وتصدر الهيئة قرار إنشاء الصندوق واعتماد نظامه الأساسى وقيده بسجلات الهيئة وفقًا لأحد الأنظمة الواردة بالمادة (63) من هذا القانون وما تضعه الهيئة من ضوابط. ولا يجوز للصندوق مزاولة نشاطه إلا بعد تمام القيد فى سجل الهيئة ويعد ذلك ترخيصا بمزاولة النشاط،ويكتسب الصندوق الشخصية الاعتبارية الخاصة بمجرد القيد،وبعد سداد رسوم قيد لا تتجاوز خمسة آلاف جنيه تسدد وفقًا لطرق السداد المقررة قانونًا. وينشر قرار القيد والنظام الأساسى على الموقع الإلكتروني للصندوق وكذا الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض.$m208$,'<<CR>>',chr(13))),
('law',155,2024,69,0,'8fabab1e3180d223510a6c57a3b6ad56','db5284c4dc49a24652709ad7a15f327a',replace($m208$يجب أن يرفق بطلب قيد الصندوق دراسة اكتوارية من أحد الخبراء الاكتواريين المسجلين لدى الهيئة،وذلك وفقًا للشروط والضوابط والقواعد التي يحددها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,70,0,'7051405e861a3cbea94e86d7a58c587f','812e5c26180a53db5f65e11a6cda3fd3',replace($m208$يلتزم الصندوق بإخطار الهيئة بكل تعديل أو تغيير يطرأ على نظامه الأساسي، ويرفق الصندوق المستندات المؤيدة له،ويتم الإخطار وفقًا للضوابط والمعايير التي يحددها مجلس إدارة الهيئة،ولا يجوز العمل بهذا التعديل إلا بعد اعتماده من الهيئة. وينشر قرار التعديل على الموقع الإلكترونى للصندوق وكذا الموقع الإلكتروني الذي تخصصه الهيئة لهذا الغرض.<<CR>>
النظام المالي للصندوق$m208$,'<<CR>>',chr(13))),
('law',155,2024,71,0,'ba72a194f5762a515cccdaba0dccd1b7','99584b23b0db987d81b8241e24524365',replace($m208$تتكون موارد الصندوق مما يأتي:<<CR>>
1- اشتراكات الأعضاء.<<CR>>
2- مساهمة الجهة المنشأ بها الصندوق )إن وجدت(.<<CR>>
3- عائد استثمار أموال الصندوق.<<CR>>
4- أية موارد أخرى يوافق عليها مجلس إدارة الصندوق وتقرها الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,72,0,'8f85c6a48ec05c0821412b42cb7c697f','e1d5148d963d5c9971b951770352bcc1',replace($m208$يلتزم كل صندوق بتخصيص جميع أمواله لمقابلة التزاماته قبل أعضائه، ويصدر عن مجلس إدارة الهيئة قرار بتحديد قواعد وضوابط ونسب استثمار الأموال الواجب تخصيصها طبقًا لأحكام هذا القانون،وكذلك تقويمها واستبدال غيرها والتصرف فيها. وللهيئة حق الاطلاع على حسابات الصندوق والحصول على جميع البيانات التي تطلبها عن أمواله المودعة بالبنك المختص أو لدى أمين حفظ الأوراق المالية،وعلى الصندوق أن يقدم إذنًا كتابيا بذلك للبنك المختص أو أمين حفظ الأوراق المالية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,73,0,'e0dfa8d41e29767f3768013337d2d2d6','c9c3a25608227b242f58da0f8899c447',replace($m208$يكون لكل صندوق قوائم مالية سنوية يتم إعدادها وفقًا لدليل تطبيق معايير المحاسبة المصرية على صناديق التأمين الخاصة التي تصدرها الهيئة، وعلى المسئولين عن إدارة الصندوق أن يمسكوا حسابات منتظمة تتناول إيرادات الصندوق ومصروفاته وعناصر مركزه المالي. وتبدأ السنة المالية للصندوق فى أول يناير وتنتهى فى 31 ديسمبر من كل سنة، ويلتزم الصندوق بأن يقدم للهيئة قبل ثلاثين يوما من التاريخ المحدد لانعقاد الجمعية العامة تقريرا عن نشاطه مرفقًا به قائمة بمركزه المالي وقائمة بحساب إيراداته ومصروفاته وتقرير مراقب الحسابات،وكذا بيان بمدد الاشتراكات الجديدة وقيمتها وعدد المشتركين الذين توقفوا خلال العام عن سداد اشتراكاتهم من خلال النموذج الذي تعده الهيئة لهذا الغرض،وذلك كله بما لا يخل بالتزام الصندوق بعقد الجمعية العامة في موعد أقصاه ثلاثة أشهر من انتهاء السنة المالية.<<CR>>
وتلتزم الصناديق التي يزيد حجم أموالها على الحد الأدنى الذي يحدده مجلس إدارة الهيئة بإعداد قوائم مالية دورية. ويتولى مراجعة حسابات الصندوق مراقب حسابات أو أكثر تختاره وتحدد أتعابه الجمعية العامة العادية للصندوق من بين المقيدين بسجل مراقبي الحسابات بالهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,74,0,'c416ad1eb62bc089c2c73d5efdbf857a','c028431a2eaebe245b86aeb471ee4924',replace($m208$يقدم الصندوق تقريرا اكتواريا إلى الهيئة بمركزه المالي يعده أحد الخبراء الاكتواريين كل خمس سنوات على الأكثر يوضح فيه مدى كفاية أموال الصندوق لمقابلة التزاماته وفقًا للأسس الفنية التي تعتمدها الهيئة في هذا الخصوص،ويتم إعداد هذا التقرير وفقًا للشروط والضوابط التي يصدرها مجلس إدارة الهيئة. ولمجلس إدارة الهيئة أن يطلب تقديم هذا التقرير فى أى وقت قبل مضى خمس سنوات بحيث لا تقل المدة عن سنة من تاريخ آخر تقرير. على أن ترسل صورة منه إلى الهيئة خلال ستة أشهر من انتهاء الفترة التي أعد عنها التقرير مصحوبة بشهادة من الخبير الاكتوارى تثبت أن المسئولين عن إدارة الصندوق قد وضعوا تحت تصرفه جميع البيانات والمعلومات التي طلبها ويراها ضرورية لأداء مهامه،ويلتزم الخبير بإخطار الهيئة بأى خطأ أو مخالفات قد تتكشف لديه أثناء إعداد التقرير الاكتواري. وللهيئة مد هذا الميعاد لفترة لا تزيد على ثلاثة أشهر. وإذا تبين للهيئة أن تقرير الخبير الاكتوارى لا يعبر عن حقيقة المركز المالي للصندوق فلها أن تأمر بإعادة إعداد التقرير بواسطة خبير اكتوارى آخر على نفقة الصندوق. ويلتزم الصندوق فى جميع الحالات بنفقات إعادة الفحص.$m208$,'<<CR>>',chr(13))),
('law',155,2024,75,0,'63a4dcf5b6459e6ac675f4a5e5c634db','703e944599661e05803bb1143cf5185f',replace($m208$تتمتع الصناديق المسجلة وفقًا لأحكام هذا القانون بالمزايا الآتية: ) أ ( الإعفاء من رسوم الشهر والتوثيق التى يقع عبء أدائها عليها في عقود الملكية والرهن والعقود الخاصة بالحقوق العينية الأخرى،وكذلك من رسوم التصديق على التوقيعات. )ب( الإعفاء من رسوم الدمغة المفروضة على جميع العقود والمحررات والمطبوعات والسجلات.<<CR>>
)ج( الإعفاء من الضريبة على العقارات المبنية المملوكة للصندوق،والمستخدمة في أداء الأنشطة الأساسية الخاصة به. )د( إعفاء عائد وناتج التعامل في الأوراق المالية من ضريبة الدخل فيما عدا أذون الخزانة والسندات الحكومية كما يعفى إيراد القروض والودائع بجميع أنواعها المخصصة للصناديق من هذه الضريبة. كما تعفى اشتراكات العاملين فى صناديق التأمين الخاصة،والتي تنشأ طبقًا لأحكام هذا القانون من الدخول فى وعاء الضريبة على الدخل المقررة عليهم.$m208$,'<<CR>>',chr(13))),
('law',155,2024,78,0,'bcf5efe48a74d18e3b062313a9eaccc7','a00ecb182fe19cec2b4cbc8fa9a6eeb7',replace($m208$تنعقد الجمعية العامة العادية للصندوق خلال الثلاثة أشهر التالية لانتهاء السنة المالية بدعوة من رئيس مجلس إدارة الصندوق،وتحدد الدعوة زمان ومكان الاجتماع وجدول الأعمال. كما يجوز لرئيس مجلس إدارة الصندوق أو لعدد من الأعضاء لا يقل عن الربع أو لرئيس مجلس إدارة الهيئة دعوة الجمعية العامة غير العادية في الحالات التي تستلزم ذلك وفقًا لأحكام هذا الباب والإجراءات والضوابط التي يحددها مجلس إدارة الهيئة والنظام الأساسي للصندوق.$m208$,'<<CR>>',chr(13))),
('law',155,2024,79,0,'11ca736edef7e194f9bee0579ad83512','7f61075ed91da2a1c54d9fe20d31d71c',replace($m208$تختص الجمعية العامة العادية للصندوق بما يأتي:<<CR>>
1- مناقشة تقرير مجلس الإدارة عن نشاط الصندوق.<<CR>>
2- مناقشة تقرير مجلس الإدارة عن أداء الاستثمار.<<CR>>
3- المصادقة على تقرير مراقب الحسابات.<<CR>>
4- اعتماد القوائم المالية للصندوق.<<CR>>
5- تحديد بدلات مشاركة أعضاء مجلس الإدارة فى اجتماعاته،وكذا مكافآتهم في حالة وجود فائض يظهره تقرير الخبير الاكتوارى وبشرط موافقة الهيئة.<<CR>>
6- تعيين مراقب الحسابات وتحديد أتعابه.<<CR>>
7- انتخاب أعضاء مجلس الإدارة.<<CR>>
8- النظر في الموضوعات الأخرى المحددة في إخطار الدعوة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,80,0,'35e55ff54f86072b17aef9af808f9094','89969519a1231979bc2613a8ec7d817a',replace($m208$تختص الجمعية العامة غير العادية للصندوق بما يأتي:<<CR>>
1- الموافقة على تعديل النظام الأساسي للصندوق.<<CR>>
2- الموافقة على عزل مجلس إدارة الصندوق،وتعيين مجلس إدارة مؤقت بما لا يجاوز عاما لحين انتخاب مجلس إدارة جديد.<<CR>>
3- تصفية الصندوق أو إدماجه أو تحويل أمواله إلى صندوق آخر أو إلى وثيقة تأمين جماعية لدى إحدى شركات التأمين العاملة في جمهورية مصر العربية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,81,0,'dddbcc016d3563cbc22b6ad9276844a7','dca865b9126fcfc0d8a1f56dc0c94209',replace($m208$يلتزم الصندوق بإبلاغ الهيئة والأعضاء بموعد ومكان اجتماع الجمعية العامة عن طريق البريد قبل انعقاده بخمسة عشر يوما على الأقل بموجب كتاب موصى عليه بعلم الوصول مرفق به صورة من الدعوة،وجدول الأعمال والأوراق المرفقة به.كما يتم الإعلان عن الدعوة بمقار وفروع الجهة التابع لها الصندوق في مكان واضح بذات البيانات المشار إليها،ويجوز بدلاً من إرسال الخطابات بالبريد نشر الدعوة في إحدى الصحف اليومية المصرية واسعة الانتشار الصادرة باللغة العربية أو أية وسائل اتصال أخرى توافق عليها الهيئة وذلك وفقًا للنموذج الذي تعده الهيئة لهذا الغرض.ويكون النشر أيضا على الموقع الإلكتروني للصندوق وكذا على الموقع الإلكتروني الذى تخصصه الهيئة لهذا الغرض وفقًا للقواعد والإجراءات التي يحددها مجلس إدارة الهيئة.<<CR>>
وعلى المختصين المعنيين بالصندوق أو من يكلفونه لهذا الغرض أن يضعوا تحت تصرف الأعضاء جميع مرفقات إخطار الدعوة. وإذا تضمن جدول أعمال الجمعية العامة انتخاب أعضاء مجلس الإدارة توجه الدعوة قبل الاجتماع بمدة لا تقل عن ثلاثين يوما،ويجب أن تتضمن الدعوة في هذه الحالة فتح باب الترشح لتلقى الطلبات خلال أسبوع يبدأ من اليوم التالي لتاريخ توجيه الدعوة ممن تتوافر لديهم شروط الترشح الموضحة بالنظام الأساسي للصندوق، وكذلك تتضمن الدعوة أسماء المقترح ترشيحهم من ذوى الخبرة وفقًا للضوابط والمعايير التي يحددها مجلس إدارة الهيئة. وللهيئة إيفاد ممثل لها لحضور الاجتماع ومراقبة صحة الإجراءات وإبداء ما تراه من ملاحظات.$m208$,'<<CR>>',chr(13))),
('law',155,2024,82,0,'c74a11d1f61436d89ad41464ac2b5752','22902d0f830588c457b5fa5da0b82442',replace($m208$يكون اجتماع الجمعية العامة العادية للصندوق صحيحا بحضور الأغلبية المطلقة لأعضائه،فإذا لم يكتمل العدد أجل الاجتماع إلى جلسة أخرى تعقد خلال مدة أقلها ساعة وأقصاها خمسة عشر يوما من تاريخ الاجتماع الأول،ويكون الانعقاد في هذه الحالة صحيحا إذا حضره بأنفسهم عدد لا يقل عن خمسمائة عضو أو عن ) (%10 من عدد الأعضاء أيهما أقل. وتصدر قرارات الجمعية العامة العادية بالأغلبية المطلقة للأعضاء الحاضرين. ويجوز لعضو الجمعية العامة أن ينيب عنه كتابة على النموذج المعد لهذا الغرض من الهيئة عضوا آخر يمثله فى حضور الجمعية العامة على أن يعتمد ذلك من مدير الصندوق وقبل انعقاد الجمعية العامة بحد أقصى اليوم السابق على انعقاد الجمعية، ولا يجوز أن ينوب العضو عن أكثر من عضو واحد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,83,0,'226d0eabaa4d008027b1d7660896264f','2e5ce08e7f737cb2099a3207719144c8',replace($m208$يكون اجتماع الجمعية العامة غير العادية صحيحا بحضور ثلثي عدد أعضاء الصندوق،فإذا لم يكتمل النصاب يؤجل الاجتماع إلى جلسة أخرى تعقد خلال مدة أقلها ساعة وأقصاها خمسة عشر يوما من تاريخ الاجتماع الأول،ويكون الانعقاد في هذه الحالة صحيحا إذا حضره بأنفسهم عدد لا يقل عن ألف عضو أو عن )(%25 من عدد الأعضاء أيهما أقل.<<CR>>
وتصدر قرارات الجمعية العامة غير العادية بأغلبية أصوات الأعضاء الحاضرين فيما عدا ما يتعلق بتصفية الصندوق أو إدماجه أو تحويل أمواله إلى صندوق آخر، فيشترط حضور ثلثي عدد أعضاء الصندوق أو ألف وخمسمائة عضو بأنفسهم أيهما أقل، ويصدر القرار بموافقة ثلاثة أرباع عدد أعضاء الصندوق الحاضرين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,84,0,'fb5cedb7cdeb91795314cd3f50bd610d','8070bc156ef16de51100217597707e6b',replace($m208$لا يكون اجتماع الجمعية العامة للصندوق صحيحا إلا بتوافر النصاب المنصوص عليه في هذا القانون،وبحضور مراقب الحسابات،وفى حالة تعذر حضور مراقب الحسابات بنفسه يمكن حضور من ينوب عنه على أن يوضح للجمعية العامة أسباب عدم حضوره. ويجوز أن ينص فى النظام الأساسى للصندوق بأن تنعقد الجمعية العامة للصندوق في ذات التوقيت وفى أكثر من مقر وفقًا للتوزيع الجغرافى وعدد أعضاء الصندوق. ولا يجوز للجمعية العامة للصندوق مناقشة أى موضوعات غير واردة بجدول الأعمال الصادر مع إخطار الدعوة للانعقاد،فيما عدا ما ترى الهيئة عرضه عليها. ويجب أن يعد محضر عن كل اجتماع للجمعية العامة للصندوق يتضمن عدد الحضور ومدى توافر النصاب والقرارات المتخذة ونتائج التصويت،ويوقع المحضر من رئيس الاجتماع ومراقب الحسابات وأمين سر الاجتماع. وتتم موافاة الهيئة بمحضر اجتماع الجمعية العامة للصندوق خلال خمسة عشر يوما من تاريخ الاجتماع ولا تعتبر قرارات الجمعية سارية إلا بعد التصديق عليها من الهيئة،وعلى الهيئة إصدار قرارها بالتصديق أو قرارها بالرفض مسببا خلال ثلاثين يوما من تاريخ تسليم الطلب بالتصديق على تلك القرارات.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',155,2024,86,0,'fb97ce99e0168e49dd586b1defa0dcf2','b5564e4f4129454a99d17c2f4468e740',replace($m208$يكون لكل صندوق مجلس إدارة يتكون من عدد فردى من الأعضاء لا يقل عن خمسة ولا يزيد على أحد عشر عضوا،على أن يكون من بينهم اثنان من ذوى الخبرة. ويحدد النظام الأساسي للصندوق اختصاصات مجلس الإدارة وشروط وكيفية انتخاب واختيار أعضائه،وإنهاء عضويتهم.$m208$,'<<CR>>',chr(13))),
('law',155,2024,88,0,'5daa9f4a57adac393fcbcd143d4f2243','79a9d9b0a2d7b2c29e39ba03ad0ba730',replace($m208$تكون مدة العضوية لعضو مجلس إدارة الصندوق ثلاث سنوات،ويجوز تجديدها لدورة واحدة أخرى متصلة. ولا يكون اجتماع المجلس صحيحا إلا بحضور ثلثى أعضائه،وتصدر قراراته بأغلبية أصوات أعضائه الحاضرين،وفى حالة تساوي الأصوات يرجح الجانب الذي منه الرئيس. ويمثل الصندوق أمام القضاء وفى مواجهة الغير رئيس مجلس إدارته.$m208$,'<<CR>>',chr(13))),
('law',155,2024,89,0,'386fdaa6b989a08e084875b062aabbe9','41e4e04f87612668e40b0134ebe1e6b3',replace($m208$ينعقد مجلس الإدارة مرة كل ثلاثة أشهر على الأقل للنظر في شئون الصندوق. ويعتبر مستقيلاً من المجلس كل عضو يتخلف عن الحضور في ثلاث جلسات متتالية أو أكثر من نصف جلسات المجلس خلال العام دون عذر مقبول. ولرئيس الهيئة دعوة مجلس إدارة الصندوق للانعقاد كلما رأى ضرورة للنظر في الموضوعات التى يرى عرضها على المجلس،ويجب على مجلس إدارة الصندوق أن يبت في هذه الموضوعات خلال شهر على الأكثر من تاريخ إبلاغه بها. وللهيئة أن توفد مندوبا عنها لحضور اجتماعات مجلس إدارة الصندوق كلما رأت ضرورة لذلك،ويكون له حق الاشتراك فى مناقشات المجلس دون أن يكون له حق التصويت.$m208$,'<<CR>>',chr(13))),
('law',155,2024,91,0,'47e90176b1feef764d30de135475c902','290f690c783b55fddd64f1da4fdcca79',replace($m208$يتولى إدارة شئون الصندوق مجلس إدارته،وله فى سبيل ذلك القيام بأي عمل يحقق أغراضه في حدود أحكام هذا القانون والنظام الأساسي للصندوق،وأن يتخذ ما يراه لازما من قرارات لمباشرة اختصاصات الصندوق وعلى الأخص ما يلى:<<CR>>
1- تعيين المدير التنفيذي والمالي للصندوق.<<CR>>
2- إقرار المراكز المالية ربع السنوية للصندوق والقوائم المالية والإيضاحات المتممة لها في نهاية كل سنة مالية.<<CR>>
3- إقرار الموازنات التقديرية للصندوق وتعرض على مجلس إدارة الصندوق قبل ثلاثة شهور على الأقل من بدء السنة المالية الخاصة بالموازنة.<<CR>>
4- نظر التقارير ربع السنوية والسنوية عن نشاط الصندوق.<<CR>>
5- تعيين مدير الاستثمار أو التعاقد مع شركة إدارة الاستثمار. ويقر مجلس إدارة الصندوق نظاما للرقابة الداخلية يهدف إلى:<<CR>>
1- التحقق من التزام الصندوق والعاملين به بتطبيق أحكام هذا القانون واللوائح والقرارات الصادرة تنفيذًا لها.<<CR>>
2- حماية أصول وموارد الصندوق من الضياع نتيجة سوء الاستخدام أو عدم الالتزام بالقوانين ذات الصلة.<<CR>>
3- وضع قواعد المساءلة والمحاسبة داخل الصندوق.$m208$,'<<CR>>',chr(13))),
('law',155,2024,92,0,'a1c70601a7e64765538d9a3cdac14fc2','d70b22f4d3856454325db98f002c92c1',replace($m208$يجوز للصناديق الخاصة المخاطبة بأحكام هذا القانون استخدام ما تراه من الأنظمة الإلكترونية لعرض بنود اجتماعات الجمعيات العامة العادية أو غير العادية والتصويت عليها عن بعد من قبل أعضائها الذين يحق لهم المشاركة والتصويت في الجمعية وذلك كله وفقًا للشروط والإجراءات التي يصدر بها قرار من مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,93,0,'665f3d0130ec000298afc14c8176611b','940865288faae9aeda2676b8c6593fb2',replace($m208$يكون للصندوق مدير تنفيذى متفرغ يصدر بتعيينه وتحديد معاملته المالية قرار من مجلس إدارة الصندوق،ويتولى المدير التنفيذى مباشرة الاختصاصات الآتية:<<CR>>
1- تنفيذ قرارات مجلس إدارة الصندوق.<<CR>>
2- الإشراف على النواحى الفنية والمالية والإدارية للصندوق.<<CR>>
3- الإشراف على أداء التزامات الصندوق تجاه المستحقين فى نطاق أحكام كل من القانون واللوائح والقرارات الصادرة بشأنه ولائحة الصندوق.<<CR>>
4- اتخاذ الإجراءات التي تكفل الحفاظ على أموال الصندوق وحقوقه قبل الغير وإخطار رئيس مجلس الإدارة أولاً بأول عن أية تجاوزات تقع من العاملين بالصندوق أو المتعاملين معه وعن أية تجاوزات يكون من شأنها الإضرار بمصلحة الصندوق أو إعاقته عن تحقيق أهدافه.<<CR>>
5- الإشراف على إعداد المراكز المالية ربع السنوية للصندوق وقائمة المركز المالي وحساباته الختامية فى نهاية كل سنة مالية وعرضها على مجلس الإدارة.<<CR>>
6- إعداد الموازنة التقديرية للصندوق وعرضها على مجلس إدارة الصندوق قبل ثلاثة أشهر على الأقل من بدء السنة المالية الخاصة بالموازنة بعد موافقة رئيس مجلس إدارة الصندوق عليها.<<CR>>
7- إعداد التقارير ربع السنوية والسنوية عن نشاط الصندوق للعرض على مجلس الإدارة للنظر في إقرارها.<<CR>>
8- ما يرى مجلس إدارة الصندوق إسناده إليه وتكليفه به من اختصاصات. ويكون المدير التنفيذي للصندوق مسئولاً مسئولية مباشرة أمام مجلس الإدارة ويكون له الحق فى حضور جلساته دون أن يكون له صوت معدود.$m208$,'<<CR>>',chr(13))),
('law',155,2024,94,0,'84a58dbddae57a3474a40c6a3e97b56e','e5e887ca19a2e45dae646cc386fbf51d',replace($m208$يكون للصندوق مدير مالى متفرغ يصدر بتعيينه وتحديد اختصاصاته ومعاملته المالية قرار من مجلس إدارة الصندوق،ويتولى على الأخص ما يلى:<<CR>>
1- إعداد السياسة الاستثمارية والمالية التي تساعد على تحقيق أهداف الصندوق ومتابعة تنفيذها.<<CR>>
2- الإشراف على إجراءات الجرد بالصندوق والتأكد من أن الجرد والتقييم قد تم وفقًا للإجراءات وفي المواعيد المحددة.<<CR>>
3- الإشراف على إعداد الحسابات الختامية وقائمة المركز المالي للصندوق والتقارير السنوية المرفقة بها في المواعيد القانونية.<<CR>>
4- الإشراف على الإجراءات الخاصة بتدبير الاعتمادات وتوفير السيولة النقدية اللازمة لتمكين الصندوق من مباشرة نشاطه.<<CR>>
5- تلقى تقارير جهات الرقابة فيما يتعلق بالنواحى المالية والإشراف على دراستها وإعداد الردود عليها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,95,0,'6be24c9b621624a7afcc2842577db3c2','f3ebed8c48a1933354d1284c9c780453',replace($m208$يلتزم الصندوق الذي يبلغ حجم أمواله المستثمرة خمسين مليون جنيه فأكثر بتعيين مدير استثمار متفرغ مسئول عن إدارة استثمار أموال الصندوق ترخص له الهيئة بذلك، أو أن يعهد بإدارة واستثمار أمواله إلى شركة أو أكثر من الشركات المرخص لها من الهيئة بإدارة صناديق الاستثمار. وذلك كله وفقًا للقواعد والضوابط التي يضعها مجلس إدارة الهيئة في هذا الشأن. الإشراف والرقابة$m208$,'<<CR>>',chr(13))),
('law',155,2024,96,0,'2e4244b4533aa1bfbf5a1aac0366b153','1082e94b128f90f86544710559daa251',replace($m208$تتولى الهيئة الإشراف والرقابة على صناديق التأمين الخاصة وفقًا لأحكام هذا القانون للوقوف على مدى سلامة مراكزها المالية،وقدرتها على الوفاء بالتزاماتها وحماية حقوق الأعضاء والمشتركين والمستفيدين والتأكد من الالتزام بأحكام هذا القانون والقرارات الصادرة عن الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,97,0,'b1268c7e3ff9854b4cec66d0eed2ef92','1b21fbbea267443feaceca04952dd6e0',replace($m208$للهيئة إذا تبين لها وجود مخالفات أو مؤشرات جدية على أن حقوق أعضاء الصندوق معرضة للضياع أو أن الصندوق خالف أى حكم من أحكام هذا القانون أو القرارات الصادرة تنفيذًا له،أن تتخذ ما تراه من التدابير المناسبة بعد إجراء التحقيقات والتثبت من المخالفات وفقًا لما يحدده مجلس إدارة الهيئة، ولها على وجه الخصوص:<<CR>>
1- تنبيه الصندوق بما هو منسوب إليه من مخالفات.<<CR>>
2- إنذار الصندوق بإزالة المخالفات المنسوبة إليه خلال ثلاثين يوما على الأكثر من تاريخ إبلاغه بها.<<CR>>
3- إلزام الصندوق بإعداد مركز مالي وحسابات ختامية على فترات أقل من سنة.<<CR>>
4- دعوة مجلس إدارة الصندوق إلى الاجتماع للنظر فى المخالفات المنسوبة إلى الصندوق واتخاذ اللازم نحو إزالتها،ويحضر اجتماع مجلس إدارة الصندوق في هذه الحالة ممثل أو أكثر عن الهيئة.<<CR>>
5- حظر الصرف من الحسابات الجارية للصندوق بالبنوك بصفة مؤقتة إلا في الأحوال التي تصرح بها الهيئة،ويكون الحظر لمدة ثلاثة أشهر قابلة للتجديد أو إلى أن تتم إزالة المخالفة المنسوبة للصندوق،أيهما أقرب،ويتعين على الجهات المختصة الالتزام بتنفيذ هذا القرار.<<CR>>
6- عزل المدير التنفيذي للصندوق.<<CR>>
7- تنحية واحد أو أكثر من مجلس إدارة الصندوق.$m208$,'<<CR>>',chr(13))),
('law',155,2024,99,0,'58bb9e3f5dcc58fb02c7e980c6273516','264f1775525ff21c7bf90117cd60b683',replace($m208$يجوز بقرار من الهيئة الترخيص لصندوق أو أكثر بناء على طلبه بالاندماج في صندوق آخر وذلك بعد موافقة الجمعية العامة غير العادية لكل صندوق، ويعتبر الصندوق المندمج فيه خلفًا للصندوق المندمج،ويحل محله حلولاً قانونيا فيما له من حقوق وما عليه من التزامات. ويتم الاندماج وفقًا للقواعد والإجراءات التي يحددها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,100,0,'5dd0f7ab94bcf98a46a8d3727a96c32c','4216472a9692cb26278db6bbcdd01f0c',replace($m208$مع عدم الإخلال بالتوازن المالي للصندوق يجوز لأى عضو من أعضاء الصندوق تحويل ما يخصه من حقوق والتزامات إلى صندوق آخر يوافق على هذا التحويل ويجب على عضو الصندوق طالب التحويل إلى صندوق آخر أن يحصل على موافقة الجمعية العامة لكل صندوق على حدة. ويتم التحويل وفقًا للقواعد والإجراءات التي يحددها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,101,0,'b7a5fab9d00b086a5bf63497b437d803','b6777caee067d1b04a3c91b744ec8857',replace($m208$تصدر الهيئة قرار تصفية الصندوق في الحالات التالية:<<CR>>
1- بناء على رغبة أعضائه بعد موافقة الجمعية العامة غير العادية.<<CR>>
2- إذا تبين من نتيجة الفحص الاكتوارى المنصوص عليه فى المادة (75) من هذا القانون أن أموال الصندوق لا تكفى للوفاء بالتزاماته.<<CR>>
3- إذا ثبت أن الصندوق لا يسير وفقًا لأحكام هذا القانون أو القرارات المنفذة لها أو لنظامه الأساسي.<<CR>>
4- إذا كانت إدارة الصندوق يشوبها غش أو تدليس. وفي الحالات الثلاث الأخيرة،ينذر الصندوق بالمخالفات ويمنح مهلة ثلاثين يوما لإبداء دفاعه،وفى حالة عدم تصحيح وضعه يصفى الصندوق. وفى جميع الحالات يتضمن قرار التصفية تشكيل لجنة للتصفية تكون مهمتها إنهاء إجراءات التصفية وتوزيع صافى أموال الصندوق على أعضائه وقت التصفية، وعلى القائمين على إدارة الصندوق تسليم جميع المستندات والسجلات والأموال الخاصة بالصندوق إلى اللجنة بمجرد طلبها ويحظر عليهم التصرف في أي شأن من شئون الصندوق إلا بأمر كتابي منها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,102,0,'438713991b5b7e3b6f2185369a2c0aea','47c54ec23c6603d7b0ed99c0e42aaba8',replace($m208$في حالة شطب الصندوق لتوقفه عن مباشرة أعماله أو لتصفيته يئول صافي أمواله إلى الأعضاء فى تاريخ التصفية ويوزع عليهم ناتج التصفية وفقًا لتقرير الخبير الاكتواري واعتماد الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,103,0,'f50555175c44b47e1f0e72a149237417','2eb0fa9dfb23dc8b209bac2c17999601',replace($m208$يجب على الهيئة شطب قيد الصندوق في الأحوال الآتية:<<CR>>
1- إذا توقف الصندوق عن مباشرة أعماله.<<CR>>
2- إذا اندمج الصندوق فى صندوق آخر أو تم تحويله إلى وثيقة تأمين جماعية بذات الأعضاء.<<CR>>
3- بعد انتهاء إجراءات تصفية الصندوق. ويتم نشر قرار الشطب على الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض.<<CR>>
أحكام ختامية$m208$,'<<CR>>',chr(13))),
('law',155,2024,104,0,'19fb2dd17f3baa22e75297c8a08f19e2','4fd896e0db997a09cc97acc6fef6cf96',replace($m208$أموال الصناديق الخاصة أموال خاصة،وتعد أمواله أموالاً عامة في تطبيق أحكام الباب الرابع من الكتاب الثاني من قانون العقوبات،ويعد القائمون على إدارته موظفين عموميين في تطبيق أحكام البابين الثالث والرابع من قانون العقوبات.$m208$,'<<CR>>',chr(13))),
('law',155,2024,105,0,'8e1c3e1efdd98fd2b1c0f8eff84c6e5e','30f3b7451935156ee6d92f9f851c8ebe',replace($m208$على القائمين على إدارة الصندوق أن يضعوا تحت تصرف أعضائه جميع البيانات الواجب تقديمها إلى الهيئة وفقًا لأحكام المادتين (73، 74) من هذا القانون والقرارات الصادرة تنفيذًا له وأن تسلم نسخة منها إلى من يطلبها من الأعضاء مقابل مبلغ لا يجاوز خمسين جنيها يتم تحصيله بالطرق المقررة قانونًا عن كل مستند وفقًا للشروط والأوضاع التي يضعها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,106,0,'3a97bc30a73f9b73e49154ffbadd7df3','e3380a5bccd88c095d276dbbdad9e1f9',replace($m208$تؤدى الصناديق رسما سنويا للهيئة يحدده مجلس إدارة الهيئة بما لا يجاوز واحدا ونصفًا في الألف من جملة الاشتراكات السنوية للصندوق مقابل فحص واعتماد أسس تحديد اشتراكات وتعويضات أعضائها بمراعاة الأسس الاكتوارية والفنية والتحقق من كفاية أموالها للوفاء بالتزاماتها وجمع وتصنيف وإتاحة البيانات والمعلومات ذات الصلة بعمل الصناديق،ودراسة شكاوى الصناديق وأعضائها وفقًا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,107,0,'d8530cdc8c6d9822f92b01a1e0c7cfc4','28c688297d81d6b8a3b73705a25b268d',replace($m208$للصناديق الخاضعة لأحكام هذا القانون أن تنشئ فيما بينها اتحادا أو أكثر أو جهازا معاونًا أو أكثر غير هادف للربح،وذلك بقصد الاتفاق على القيام بجمع وتحليل ونشر المعلومات أو القيام بأعمال منع وتقليل الخسائر أو غير ذلك من الأعمال التي تهم الأعضاء. ويتعين أن يتضمن النظام الأساسى للاتحاد أو الجهاز نصوصا حول طبيعة العلاقة بين أعضائه والتزاماتهم وجزاءات مخالفة أحكامه. ويصدر مجلس إدارة الهيئة قرارا باعتماد إنشاء الاتحاد أو الجهاز والتصديق على نظامه الأساسى ويقيد الاتحاد أو الجهاز فى سجل خاص لدى الهيئة بعد أداء رسم مقداره خمسة آلاف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا.<<CR>>
وينشر قرار الإنشاء والنظام الأساسى بالوقائع المصرية،وكذا على الموقع الإلكترونى للاتحاد أو الجهاز بحسب الأحوال،وكذا على الموقع الإلكتروني الذى تخصصه الهيئة لهذا الغرض. ويكون لكل منها الشخصية الاعتبارية الخاصة من تاريخ هذا النشر.$m208$,'<<CR>>',chr(13))),
('law',155,2024,109,0,'8aad33aca781618a5b51362560d02a35','c78c8fd8342d97267e8306c8a8c01432',replace($m208$اتحاد شركات التأمين،اتحاد غير هادف للربح يتكون من شركات التأمين وإعادة التأمين الخاضعة لهذا القانون أيا كان نوع النشاط الذي تزاوله،ويتمتع بشخصية اعتبارية مستقلة،ويعد من أشخاص القانون الخاص ويسجل فى سجل خاص بالهيئة، ويشار إليه في هذا القانون بالاتحاد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,110,0,'68e6e657a3b734826b3d4f4db003a4a3','1d8704c9d212bf9f36743910a910f296',replace($m208$يهدف الاتحاد إلى تحقيق الأغراض التالية:<<CR>>
1- العمل على رفع مستوى صناعة التأمين والمهن التأمينية المرتبطة بها وتحديثها وترسيخ مفاهيم وأعراف العمل التأميني الصحيح.<<CR>>
2- التنسيق مع الهيئة فى المسائل المشتركة وتجنب تعارض المصالح وتسوية المنازعات بين الأعضاء.<<CR>>
3- توثيق التعاون والتنسيق بين الاتحاد والهيئة بما يحقق صالح سوق التأمين والاقتصاد القومي.<<CR>>
4- توثيق الصلات بين الاتحاد والاتحادات الأخرى في مصر والخارج.$m208$,'<<CR>>',chr(13))),
('law',155,2024,111,0,'bb4b71d13d801c0930b2d00d8a9ade4d','d1de75d01b19776672cdea9899dd6caf',replace($m208$تعتبر كل شركة تأمين أو إعادة تأمين خاضعة لأحكام هذا القانون عضوا بالاتحاد بمجرد تسجيلها بالهيئة. وعلى الشركة موافاة الاتحاد خلال خمسة عشر يوما بصورة من قرار التسجيل وبأسماء أعضاء مجلس إدارتها،وتلتزم بأحكام نظامه الأساسي.$m208$,'<<CR>>',chr(13))),
('law',155,2024,112,0,'14a033041b87518810b427491d6b80dc','d9d599cb31f427ef45f04b88f7e23848',replace($m208$تتكون موارد الاتحاد من:<<CR>>
1- مقابل الانضمام لعضوية الاتحاد.<<CR>>
2- الاشتراكات السنوية التي يسددها الأعضاء.<<CR>>
3- عائد استثمار أموال الاتحاد.<<CR>>
4- أى موارد أخرى يوافق عليها مجلس إدارة الاتحاد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,113,0,'a21589f612f1330ea6f1eb0e11136679','eb8a04cd217a4af11f90f627c1202498',replace($m208$الجمعية العامة هي السلطة العليا للاتحاد،وتشكل من ممثل لكل عضو من أعضاء الاتحاد ويحضر اجتماعاتها ممثلو الأعضاء الذين أوفوا بالالتزامات المالية المستحقة عليهم وفقًا للنظام الأساسى للاتحاد حتى تاريخ انعقاد الجمعية. وتختص الجمعية العامة للاتحاد بما يأتي:<<CR>>
1- إقرار السياسات اللازمة لتحقيق أهداف الاتحاد.<<CR>>
2- اعتماد الهيكل التنظيمي للاتحاد.<<CR>>
3- انتخاب رئيس مجلس إدارة الاتحاد ونائبه وأعضاء المجلس.<<CR>>
4- الموافقة على النظام الأساسى للاتحاد وتعديلاته.<<CR>>
5- وضع قواعد السلوك المهنى التي يلتزم بها أعضاؤه من الشركات على أن تعتمد من الهيئة.<<CR>>
6- تحديد قيمة مقابل العضوية الذي يؤديه طالب الانضمام للاتحاد بما لا يجاوز خمسمائة ألف جنيه.<<CR>>
7- تحديد قيمة الاشتراك السنوى للأعضاء بما لا يجاوز خمسة ملايين جنيه.<<CR>>
8- اعتماد الموازنة التقديرية للاتحاد وكذا القوائم المالية وتقرير مراقب الحسابات والتقرير السنوى عن نشاط الاتحاد.<<CR>>
9- تعيين مراقب الحسابات من بين المقيدين بسجل مراقبي الحسابات بالهيئة، وتحديد أتعابه.<<CR>>
10- المسائل الأخرى التى يرى مجلس إدارة الاتحاد عرضها على الجمعية العامة وإدراجها في جدول الأعمال. ويحدد النظام الأساسي للاتحاد الاختصاصات الأخرى للجمعية العامة، وغيرها من الإجراءات والقواعد المتعلقة بنظام عملها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,114,0,'fefb44b223930c3f8654e54167512ace','7490a7f0dd13ddc4bf1f4095f4db84f0',replace($m208$يكون للاتحاد مجلس إدارة مكون من رئيس واثنى عشر عضوا،لمدة أربع سنوات قابلة للتجديد لمرة واحدة متصلة. ويحدد النظام الأساسي للاتحاد اختصاصات مجلس إدارة الاتحاد ورئيسه وقواعد ونظام عملهما،كما يحدد قواعد وإجراءات وضوابط وشروط انتخاب مجلس الإدارة. ولا يجوز حل مجلس إدارة الاتحاد إلا بناء على حكم قضائي.$m208$,'<<CR>>',chr(13))),
('law',155,2024,115,0,'6787c545220bfdc72a7b9a222e445d8e','0925ecb02b78c08855917bd2becd9567',replace($m208$يعتمد مجلس إدارة الهيئة النظام الأساسى للاتحاد بناء على عرض مجلس إدارة الاتحاد وبعد موافقة الجمعية العامة للاتحاد،وينشر بالوقائع المصرية وعلى الموقع الإلكتروني لكل من الاتحاد والهيئة. ويحدد النظام الأساسى للاتحاد أجهزته الأخرى المعاونة واختصاصاتها ونظام عملها،وكذا أحكام وقواعد وإجراءات مساءلة أعضاء الاتحاد والتدابير الإدارية الواجب اتخاذها حال مخالفة نظامه الأساسى أو قواعد السلوك المهني. اتحادات المهن والأنشطة التأمينية الأخرى$m208$,'<<CR>>',chr(13))),
('law',155,2024,116,0,'604d36d75d4e5cffacd872df1c1def7c','27eb6c463e31766ddec2460e6b4f9668',replace($m208$تنشأ اتحادات غير هادفة للربح للأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بالتأمين المسجلين بسجلات الهيئة،وتتمتع هذه الاتحادات بالشخصية الاعتبارية المستقلة،وتعد من أشخاص القانون الخاص، وتسجل في سجل خاص بالهيئة. ويجوز أن يضم الاتحاد أكثر من مهنة أو نشاط من الأنشطة المرتبطة بالتأمين، ولا يجوز إنشاء أكثر من اتحاد للمهنة أو النشاط الواحد.<<CR>>
ويكون تأسيس الاتحادات المشار إليها بالفقرة الأولى من هذه المادة من عدد لا يقل عن ) (%51 من الأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بها وفقًا لطبيعة نشاط الاتحاد شريطة ألا تقل حصتهم السوقية أو حجم أعمالهم عن ) (%51 من إجمالي حجم النشاط فى السوق المعنية، وتتولى الهيئة التأكد من توافر متطلبات التأسيس وقيام هؤلاء الأشخاص بتشكيل الجمعية التأسيسية لإعداد مشروع النظام الأساسي،وعرضه على الهيئة للنظر في اعتماده،ونشره بالوقائع المصرية وعلى الموقع الإلكتروني للهيئة. ويلتزم الأشخاص المرخص لهم من الهيئة بمزاولة المهن التأمينية أو الأنشطة المرتبطة بالتأمين المسجلون بسجلات الهيئة بالاشتراك في عضوية الاتحاد المعنى بالنشاط بمجرد تسجيله بالهيئة،ومراعاة نظامه الأساسي.$m208$,'<<CR>>',chr(13))),
('law',155,2024,117,0,'f81d4f568e51511f63f2c3069746c2f3','e312e4b99ead9ed3079c67beee224aea',replace($m208$تهدف الاتحادات المشار إليها فى المادة (116) من هذا القانون إلى تحقيق الأغراض الآتية:<<CR>>
1- العمل على تنمية مهارات العاملين فى المهن التأمينية والأنشطة التأمينية المرتبطة بها وفقًا لطبيعة نشاط الاتحاد.<<CR>>
2- التنسيق مع الهيئة فى المسائل المشتركة وتسوية المنازعات بين الأعضاء.<<CR>>
3- توثيق الصلة بين الاتحاد وغيره من الاتحادات الأخرى في الداخل والخارج.$m208$,'<<CR>>',chr(13))),
('law',155,2024,118,0,'3fa30acb3d009da81dc2db9b8e347a7c','af2bbec5476013a7aa792b1690326ade',replace($m208$تتكون موارد اتحادات المهن والأنشطة المرتبطة بها من الآتي:<<CR>>
1- مقابل الانضمام لعضوية الاتحاد.<<CR>>
2- الاشتراكات السنوية التي يسددها الأعضاء.<<CR>>
3- عائد استثمار أموال الاتحاد.<<CR>>
4- أى موارد أخرى يوافق عليها مجلس إدارة الاتحاد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,119,0,'e7a2c76b9b5a797386d1204941222e8b','008aba6fe687565830b00424c08b76af',replace($m208$يكون لكل اتحاد جمعية عامة تكون هى السلطة العليا له،وتشكل من ممثل لكل عضو من أعضاء الاتحاد ويحضر اجتماعاتها ممثلو الأعضاء الذين أوفوا بالالتزامات المالية المستحقة عليهم وفقًا للنظام الأساسي للاتحاد حتى تاريخ انعقاد الجمعية.<<CR>>
وتختص الجمعية العامة للاتحاد بالبنود (1،2،4،5،8،9،10) المنصوص عليها بالمادة (113) من هذا القانون بالإضافة إلى ما يأتي:<<CR>>
1- انتخاب مجلس إدارة الاتحاد وفقًا لقواعد التمثيل النسبي للمهن والأنشطة المرتبطة بالتأمين لأعضاء الاتحاد.<<CR>>
2- الموافقة على النظام الأساسى للاتحاد وتعديلاته على أن يتم اعتمادها من الهيئة.<<CR>>
3- تحديد قيمة مقابل العضوية الذي يؤديه طالب الانضمام للاتحاد بما لا يجاوز خمسين ألف جنيه للشخص الطبيعى ومائة ألف جنيه للشخص الاعتبارى.<<CR>>
4- تحديد قيمة الاشتراك السنوى للأعضاء بما لا يجاوز خمسين ألف جنيه للشخص الطبيعي ومائة ألف جنيه للشخص الاعتباري. ويجوز للجمعية العامة غير العادية زيادة قيمة مقابل العضوية والاشتراك السنوى أو أحدهما بما لا يجاوز الضعف سنويا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,120,0,'15dbd65985de4442405864225f3dde28','311d6e499a2161ff4d7a15b07bf657a8',replace($m208$يجب أن يتضمن النظام الأساسى للاتحاد على الأخص ما يلى:<<CR>>
1- اختصاصات كل من الجمعية العامة العادية وغير العادية ومجلس إدارة الاتحاد ورئيسه.<<CR>>
2- تشكيل مجلس إدارة الاتحاد ونسب تمثيل المهن والأنشطة المرتبطة بالتأمين في مجلس إدارته وفقًا لطبيعة نشاط الاتحاد.<<CR>>
3- قواعد وإجراءات وشروط انتخاب مجلس الإدارة.<<CR>>
4- قواعد ونظام العمل بمجلس الإدارة ولجانه وأجهزته المعاونة.<<CR>>
5- أحكام وقواعد وإجراءات مساءلة أعضاء الاتحاد والتدابير الإدارية الواجب اتخاذها حال مخالفة نظامه الأساسي أو قواعد السلوك المهني.$m208$,'<<CR>>',chr(13))),
('law',155,2024,122,0,'75a912d8f7a2bb84fda234fc3cd3dc5e','8b0129ea0eded1bfc12ea808f9ea7b12',replace($m208$يجوز بقرار من مجلس إدارة الهيئة إنشاء أجهزة معاونة لقطاع التأمين وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويسجل الجهاز فى سجل خاص لدى الهيئة بعد أداء رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا. وينشر قرار الإنشاء والنظام الأساسى بالوقائع المصرية وعلى الموقع الإلكتروني للجهاز وكذا الموقع الإلكترونى للهيئة،ويكتسب الجهاز الشخصية الاعتبارية المستقلة اعتبارا من تاريخ هذا النشر،ويعد من أشخاص القانون الخاص. ويعتبر من قبيل الأجهزة المعاونة فى حكم هذه المادة المعاهد التأمينية ومراكز التدريب ومراكز الحاسبات وتكنولوجيا المعلومات وتداول البيانات التي تنشئها شركات التأمين فيما بينها في مجال التأمين. مكاتب تمثيل منشآت التأمين أو إعادة التأمين أو الأنشطة المرتبطة بهما$m208$,'<<CR>>',chr(13))),
('law',155,2024,123,0,'f166f239dc235f419e9be9d2cedc6edb','f05049076798f6414cfeca34a0d0c59b',replace($m208$يجوز للهيئة الترخيص بإنشاء مكاتب تمثيل في جمهورية مصر العربية للشركات الأجنبية التى تعمل فى مجال التأمين أو إعادة التأمين أو الأنشطة والخدمات المرتبطة بهما وفقًا للشروط والضوابط التي يصدر بها قرار عن مجلس إدارة الهيئة،وذلك بعد أداء رسم تسجيل مقداره خمسة آلاف دولار أو ما يعادله بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانونًا. ويقتصر غرض عملها على دراسة سوق التأمين والعلاقات العامة والاتصالات، والقيام بدور حلقة اتصال مع المراكز الرئيسية فى الخارج والمساهمة في تذليل المشاكل والصعوبات وتقديم التسهيلات لشركات السوق المحلية. وتجدد تلك الموافقة سنويا مقابل رسم مقداره ألف دولار أو ما يعادله بالعملات الأجنبية الحرة التى يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانونًا.<<CR>>
وتخضع تلك المكاتب لإشراف ورقابة الهيئة،ويكون للهيئة حق الاطلاع في أي وقت على الدفاتر والسجلات الخاصة بها وطلب ما تراه من البيانات والمستندات التي تحقق أغراض الإشراف والرقابة عليها. ويجب على تلك المكاتب أن تخطر الهيئة بأى تعديلات تطرأ على بياناتها المسجلة لدى الهيئة. وفى حالة مخالفة أى من تلك المكاتب لأى من شروط وضوابط الهيئة يتم إنذارها بالمخالفة وطلب إزالتها خلال ثلاثين يوما من تاريخ إنذارها،فإذا لم تتم إزالتها يتم شطبها من السجل بقرار من مجلس إدارة الهيئة. وتلتزم تلك المكاتب بإخطار الهيئة عند إغلاقها المكتب سواء بصورة مؤقتة أو نهائية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,124,0,'9b827f8c66293d0ef6a29893702e5314','c18dd47ea226a05413c6aac59d524310',replace($m208$لا يجوز للخبير الاكتوارى من الأشخاص الطبيعيين أن يزاول أعماله إلا بعد الحصول على ترخيص بذلك من الهيئة ويسجل فى السجل المعد لذلك بالهيئة، ويتم قيد اسمه وفقًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة، والتي من بينها على وجه الخصوص ما يلى: أن يكون حاصلاً على إحدى الدرجات أو الدبلومات الآتية: ) أ ( درجة زميل أو رفيق من أحد المعاهد الآتية: معهد وكلية الخبراء الاكتواريون بالمملكة المتحدة. جمعية الخبراء الاكتواريون بالولايات المتحدة الأمريكية. )ب( درجة مهنية تالية لمرحلة الدراسة الجامعية الأولى فى العلوم الاكتوارية من إحدى جمعيات أو معاهد الخبراء الاكتواريين،معادلة للشهادات الواردة في البند )أ(، التي يعتمدها مجلس إدارة الهيئة.<<CR>>
ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويقدم طلب التجديد في سجل الخبراء الاكتواريين وفقًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة، على أن يتم اتخاذ إجراءات التجديد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفقًا لطرق السداد المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,125,0,'c1d6a1cad9e0d3b56c3237ca4f47521d','469d2f4ddc4c3037c9132e697a8c94fe',replace($m208$يجوز للهيئة الترخيص بمزاولة أعمال الخبرة الاكتوارية من خلال شركات يتم تأسيسها لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد في السجل المشار إليه في الفقرة الأولى من هذه المادة ضرورة توافر الآتي:<<CR>>
1- ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.<<CR>>
2- التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.<<CR>>
3- أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل الخبراء الاكتواريين بالهيئة وذلك وفقًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.<<CR>>
4- توافر جميع الشروط المتطلبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة الاكتوارية من خلال الشخص الاعتباري.<<CR>>
5- أن يقتصر غرض الشركة على مزاولة أعمال الخبرة الاكتوارية. وتؤدى الشركة طالبة القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه يسدد وفقًا لطرق السداد المقررة قانونًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقتًا أحد الخبراء الاكتواريين من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,126,0,'db895c9c0cd2f45f50a1eb2f794a911a','94d6737b79b2de230c26358fe44b57ad',replace($m208$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو عدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف قيد الخبير لمدة لا تجاوز ثلاث سنوات أو شطب قيده بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:<<CR>>
1- فقد أحد شروط القيد.<<CR>>
2- إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.<<CR>>
3- عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.<<CR>>
4- إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,127,0,'3d749d7699fa27579c3cdcbdf50f1111','d8424c3bb179fc34de828e3005045f8d',replace($m208$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حداها الأدنى والأقصى في ضوء حجم أعماله وفقًا للضوابط التي يصدر بها قرار من الهيئة. ويكتفى بالنسبة للخبراء الاكتواريين والقائم بمهام الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة اكتوارية واحدة فقط أن تتم تغطيتهم من خلال وثيقة شاملة عن أعمال شركتهم لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر الخبير الاكتوارى أعماله وفقًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. وفي جميع الأحوال،يلتزم الخبراء الاكتواريون الطبيعيون والاعتباريون في مباشرة أعمالهم بقواعد ومعايير الخبرة الاكتوارية المعتمدة من مجلس إدارة الهيئة.<<CR>>
خبراء التأمين الاستشاريون$m208$,'<<CR>>',chr(13))),
('law',155,2024,128,0,'a42f102f88f667374db9f5313121b1fb','3cc953c12f2c82ce39533f63882b0460',replace($m208$لا يجوز لخبير التأمين الاستشارى من الأشخاص الطبيعيين أن يمارس أعمال الخبرة الاستشارية إلا بعد قيد اسمه فى السجل المعد لذلك بالهيئة. ويتم القيد وفقًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,129,0,'ef2344b3db65368bf541280993da9ba7','3812ab3a63ea19655d9bf021d96cd50a',replace($m208$يسرى القيد لمدة خمس سنوات قابلة للتجديد ويتعين أن يتم اتخاذ إجراءات التجديد خلال الثلاثة أشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفقًا لطرق السداد المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,131,0,'f30806478131eea03c72d489234596e6','371b503a5d075ca1dd7965ca5a2c2153',replace($m208$يجوز للهيئة الترخيص بمزاولة أعمال خبراء التأمين الاستشاريين من خلال شركات تؤسس لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد في السجل المشار إليه فى الفقرة الأولى من هذه المادة ضرورة توافر الآتي:<<CR>>
1- ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.<<CR>>
2- التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.<<CR>>
3- أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل خبراء التأمين الاستشاريين بالهيئة وذلك وفقًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.<<CR>>
4- توافر جميع الشروط المطلوبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة الاستشارية في التأمين من خلال الشخص الاعتباري.<<CR>>
5- أن يقتصر غرض الشركة على مزاولة أعمال الخبرة الاستشارية في التأمين. وتؤدى الشركة طالبة القيد أو التجديد رس ما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقتًا أحد خبراء التأمين الاستشاريين من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13)));
