('law',155,2024,132,0,'976c54fc33f43f57cea620033d201c52','07f82fb39e6bf65ea7dda4c3d6e7dc71',replace($m208$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الخبير بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:<<CR>>
1- فقد أحد شروط القيد.<<CR>>
2- إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.<<CR>>
3- عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.<<CR>>
4- إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,133,0,'5431a8933bc07edbc0a2da1929d7d02f','b5eb94d013dc54880031a1517a8fba39',replace($m208$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حدها الأقصى وفقًا للضوابط الصادرة عن الهيئة. ويكتفى بالنسبة لخبراء التأمين الاستشاريين والقائم بأعمال الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة استشارية بأن يتم تغطيتهم من خلال وثيقة شاملة عن أعمال تلك الشركة لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر خبراء التأمين الاستشاريون أعمالهم وفقًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. خبراء تقييم الأخطار أو معاينة وتقدير الأضرار$m208$,'<<CR>>',chr(13))),
('law',155,2024,134,0,'1696c49f9282e8001809dd15d2368366','1bb9c686dc84ba5c07d8d9e4b14b4201',replace($m208$لا يجوز لأى شخص من الأشخاص الطبيعيين مزاولة مهنة تقييم الأخطار أو معاينة وتقدير الأضرار إلا بعد قيد اسمه في السجل المعد لذلك بالهيئة. وعلى طالب القيد فى هذا السجل أن يحدد فرعين على الأكثر من فروع تأمينات الممتلكات أو المسئوليات التي نص عليها بالمادة (2) من هذا القانون لممارسة تخصصه المهني سواء فى مجال تقييم الأخطار أو معاينة وتقدير الأضرار. ويتم القيد وفقًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,135,0,'524020d3363e62d05c9b05200c12536e','d6e9a1c788974b828ae15e5c2c7d98b2',replace($m208$يقدم طلب القيد أو التجديد فى سجل خبراء تقييم الأخطار أو معاينة وتقدير الأضرار وفقًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة،ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويتعين أن يتم اتخاذ إجراءات تجديد القيد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفقًا لطرق السداد المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,136,0,'2240d8bd3457c9b7400292106766729d','7bd1bf51a72ec9c697945fbc0f10df0e',replace($m208$يجوز للهيئة الترخيص بمزاولة أعمال خبراء تقييم الأخطار أو معاينة وتقدير الأضرار من خلال شركات تؤسس لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة.<<CR>>
ويشترط للقيد فى السجل المشار إليه فى الفقرة الأولى من هذه المادة ضرورة توافر الآتى:<<CR>>
1- ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.<<CR>>
2- التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.<<CR>>
3- أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل خبراء تقييم الأخطار ومعاينة وتقدير الأضرار بالهيئة،وذلك وفقًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.<<CR>>
4- توافر جميع الشروط المطلوبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة في تقييم الأخطار ومعاينة وتقدير الأضرار من المسجلين بالهيئة من خلال الشخص الاعتباري.<<CR>>
5- أن يقتصر غرض الشركة على مزاولة أعمال الخبرة في تقييم الأخطار ومعاينة وتقدير الأضرار. وتؤدى الشركة طالبة القيد أو التجديد رس ما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقتًا أحد خبراء تقييم الأخطار أو تقدير الأضرار من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,137,0,'a60de2772b085f15f1b6983bb78e4bd2','378aada7a509ab2cfdbe984210344393',replace($m208$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الخبير بقرار من مجلس إدارة الهيئة فى أى من الحالات التالية:<<CR>>
1- فقد أحد شروط القيد.<<CR>>
2- إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.<<CR>>
3- عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.<<CR>>
4- إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,138,0,'68a25a51e271392b08a477d36203ad2e','b7ece46c66445d2f2f5ac013e600ffa2',replace($m208$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حداها الأدنى والأقصى فى ضوء حجم أعماله وفقًا للضوابط التي يصدر بها قرار من الهيئة. ويكتفى بالنسبة لخبراء تقييم الأخطار ومعاينة وتقدير الأضرار والعضو المنتدب والقائم بأعمال الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة معاينة وتقدير الأضرار بأن يتم تغطيتهم من خلال وثيقة شاملة عن أعمال تلك الشركة لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر خبراء تقييم الأخطار ومعاينة وتقدير الأضرار أعمالهم وفقًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. وسطاء التأمين وإعادة التأمين$m208$,'<<CR>>',chr(13))),
('law',155,2024,139,0,'e9b784cc54a2cf12f531610a1bbff90e','94a3ada6bd01c64546cc5b7d46a9b9e8',replace($m208$لا يجوز لأى من الأشخاص الطبيعيين مزاولة أعمال الوساطة في التأمين في جمهورية مصر العربية إلا بعد قيد اسمه فى السجل المعد لذلك بالهيئة. ويتم القيد وفقًا للشروط والقواعد والإجراءات التي يصدر بها قرار من مجلس إدارة الهيئة. ولا يجوز مزاولة أعمال الوساطة في إعادة التأمين في جمهورية مصر العربية إلا من خلال أشخاص اعتبارية تؤسس لهذا الغرض وفقًا لأحكام هذا القانون والقرارات الصادرة تنفيذًا له على أن يقوم بمباشرة تلك الأعمال ممثلو الشخص الاعتباري من المقيدة أسماؤهم في السجل المعد لذلك بالهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,140,0,'c85f4c25c0927d9692d55dc9d4de7ab4','33806e3d366305c366464ac57f7bec1b',replace($m208$يسرى القيد في سجل وسطاء التأمين وإعادة التأمين للأشخاص الطبيعيين لمدة خمس سنوات قابلة للتجديد وفقًا للشروط والأوضاع التي يصدر بها قرار عن مجلس إدارة الهيئة،ويتعين أن يتم اتخاذ إجراءات التجديد قبل نهاية هذه المدة بثلاثة أشهر على الأقل. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعى،يسدد وفقًا لطرق السداد المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,141,0,'9714501ff628be6c7b52b845a67b0635','b5197d012bbd1bf8c1eea873a7d3ae15',replace($m208$مع عدم الإخلال بحكم المادة (139) من هذا القانون يجوز للهيئة الترخيص بمزاولة أعمال وساطة التأمين أو إعادة التأمين من خلال شركات تؤسس لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفقًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد فى السجل المشار إليه فى الفقرة الأولى من هذه المادة ما يلى:<<CR>>
1- ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن خمسة ملايين جنيه نقدا،أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.<<CR>>
2- التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.<<CR>>
3- أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل وسطاء التأمين أو إعادة التأمين،بحسب الأحوال،وذلك وفقًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.<<CR>>
4- توافر جميع الشروط المطلوبة لقيد الأشخاص الطبيعيين فى سجل الوسطاء لدى كل من يزاول أعمال الوساطة في التأمين أو إعادة التأمين من المسجلين بالهيئة من خلال الشخص الاعتباري.<<CR>>
5- أن يقتصر غرض الشركة على مزاولة أعمال الوساطة فى التأمين أو إعادة التأمين. وتؤدى الشركة طالبة القيد أو التجديد رس ما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفقًا لطرق السداد المقررة قانونًا.<<CR>>
وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله،يجوز لمجلس إدارة الشركة أن يكلف مؤقتًا أحد وسطاء التأمين أو إعادة التأمين،بحسب الأحوال،من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,142,0,'c9b64069d24e1d222f62c2ada21e9115','7eea22a0f36cfafa024b4fa4571a7054',replace($m208$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختيارى أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الوسيط بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:<<CR>>
1- فقد أحد شروط القيد.<<CR>>
2- إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.<<CR>>
3- عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.<<CR>>
4- إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على غش أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,143,0,'6ff3368831b6f1cfea0bec6d744e1790','6987a7f91f12f5a00c45fae5edbb7caf',replace($m208$لا يجوز لشركات التأمين وإعادة التأمين المسجلة وفقًا لأحكام هذا القانون أن تقبل عمليات تأمين محلية من وسطاء التأمين ما لم يكونوا مقيدين في السجل المعد لذلك بالهيئة،كما لا يجوز لها أن تسند أيا من عمليات إعادة التأمين لديها إلا لوسطاء إعادة التأمين المحليين أو وسطاء إعادة التأمين الأجانب المقيمين الذين يعملون باسم ولحساب شركة مرخص لها من الهيئة بذلك وفقًا لأحكام هذا القانون إلا من المقيدين بالسجل المشار إليه،وعلى شركات التأمين أو إعادة التأمين حال تعاملها مع وسطاء إعادة التأمين الأجانب غير المقيمين أن تلتزم بإدراجهم ضمن قائمة وسطاء إعادة التأمين الصادرة عن الهيئة سنويا وفقًا للشروط والمعايير الصادرة عن الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,144,0,'dfaa89262ee992bbab058f6f4366e3d1','507fbefb345a39cafa4d1ee26af16177',replace($m208$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حداها الأدنى والأقصى وفًقا للضوابط والأحكام الصادرة عن الهيئة. ويستثنى من ذلك أعضاء الجهاز الإنتاجى بشركات التأمين وإعادة التأمين شريطة أن تلتزم شركة التأمين التي يعمل لحسابها بتحمل المسئولية المدنية المقررة عن أخطائهم قبل حملة الوثائق أو المستفيدين منها أو الغير في تأمينات المسئوليات الصادرة عنها طالما تم إثبات الضرر بسبب تلك الفئات بناء على قرار من الهيئة. ويكتفى بالنسبة لوسطاء التأمين أو إعادة التأمين والقائم بأعمال الإدارة التنفيذية لهذه الشركات الذين يعملون باسم ولحساب شركات الوساطة في التأمين أو إعادة التأمين بأن يتم تغطيتهم من خلال وثيقة شاملة عن أعمال تلك الشركات لدى إحدى شركات التأمين المسجلة بالهيئة. ويقصد بالجهاز الإنتاجي لشركات التأمين مجموعة العاملين بقطاع البيع فى هذه الشركات.$m208$,'<<CR>>',chr(13))),
('law',155,2024,146,0,'905add7874a6456002d0d7580eb8b296','9d832fb618a878d8eb40b866180db4a7',replace($m208$يضع مجلس إدارة الهيئة الشروط والقواعد والضوابط التي تلتزم بها شركات التأمين لعمل المتدربين لديها بصفة مؤقتة بالجهاز الإنتاجى وتسجيلهم بالسجل المعد لهذا الغرض بالهيئة،ويحدد مجلس إدارة الهيئة الرسوم الواجب سدادها بهذا السجل بما لا يجاوز نصف الرسم المقرر بالنسبة لوسطاء التأمين،تسدد وفقًا لطرق السداد المقررة قانونًا.<<CR>>
) الفصل التاسع ( أحكام ختامية$m208$,'<<CR>>',chr(13))),
('law',155,2024,148,0,'dce1cc2db73a59d6bde009d7e913ccdf','6e4658e8926622089313b414f02625a1',replace($m208$يراعى بالنسبة للسجل المعد لقيد ذوي المهن التأمينية من الأشخاص الطبيعيين إفراد بيان بسجلاتهم يبين مدى مزاولتهم للنشاط من عدمه،وفي الحالة الأخيرة بيان سبب عدم المزاولة. ويعد شرطًا من شروط قيد أو تجديد قيد أو إعادة قيد أى من المهنيين الطبيعيين بالسجل المعد لذلك بالهيئة الالتزام بقواعد وضوابط التطوير المهني المستمر الصادرة عن الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,150,0,'96e775402ef91d8f338da139123adacd','eb5ae342399dc2343122bbac423179d9',replace($m208$يصدر عن مجلس إدارة الهيئة قواعد ومعايير ممارسة تلك المهن وفقًا لنوع النشاط أو التصنيف الصادر عن الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,151,0,'659b451270c0f673fd50f659bd024e0f','36995c9128d0122f0308fa908bf493db',replace($m208$تختص الهيئة،دون غيرها،بالإشراف والرقابة على نشاط التأمين وإعادة التأمين والخدمات والمهن والأنشطة المرتبطة بهما،ولها فى سبيل ذلك على وجه الخصوص:<<CR>>
1- الإشراف والرقابة على الأشخاص الطبيعية والاعتبارية التي تمارس نشاط التأمين والمهن والأنشطة المرتبطة به والاتحادات والأجهزة المعاونة ومكاتب التمثيل.<<CR>>
2- إصدار القواعد والقرارات التنفيذية المنظمة لأنشطة المخاطبين بأحكام هذا القانون،ومن بينها القواعد المنظمة لمنح التراخيص والتجديد والإلغاء والشطب وإعادة القيد وذلك فى ضوء القواعد والإجراءات والمعايير،ومن بينها معايير الملاءة المالية والتصنيف الائتمانى،التي يصدرها مجلس إدارة الهيئة.<<CR>>
3- وضع قواعد ومتطلبات الحوكمة،والإفصاحات المطلوبة وتوقيتاتها، ووضع قواعد ومعايير إلزام شركات التأمين بالحصول على تصنيف ائتماني من إحدى جهات التصنيف المقبولة من الهيئة.<<CR>>
4- وضع القواعد والمعايير اللازمة لممارسة نشاط التأمين والأنشطة المرتبطة به، ومنها أساليب تقييم وإدارة المخاطر وقواعد الملاءة المالية.<<CR>>
5- إصدار ضوابط فتح ونقل وغلق الفروع.<<CR>>
6- إصدار الضوابط التفصيلية لمكافحة غسل الأموال وتمويل الإرهاب في مجال التأمين وإعادة التأمين وما يرتبط به من أنشطة وخدمات،تتضمن الالتزام بالضوابط الصادرة من وحدة مكافحة غسل الأموال وتمويل الإرهاب وبعد التنسيق مع الجهات المعنية.<<CR>>
7- وضع الضوابط اللازمة لحماية المتعاملين،على أن تكون ملزمة لجميع الجهات والأشخاص الخاضعين لأحكام هذا القانون.<<CR>>
8- وضع قواعد وضوابط التحول الرقمى بالقطاع،بما فيها استخدام وسائل تكنولوجيا المعلومات في مجال انعقاد الجمعيات العامة ومجالس الإدارة والتصويت على القرارات الصادرة عنهما.<<CR>>
9- وضع القواعد المتعلقة بالإعلان عن الخدمات والمنتجات التأمينية وما يترتب على الإخلال بالالتزامات التي تنشئها.<<CR>>
10- وضع قواعد وضوابط استثمار أموال شركات التأمين وإعادة التأمين وصناديق التأمين.<<CR>>
11- تنظيم اعتماد نماذج وشروط وثائق التأمين.<<CR>>
12- فحص شكاوى المتعاملين مع الأشخاص الطبيعية والاعتبارية التي تمارس نشاط التأمين والمهن والخدمات المرتبطة به والفصل فيها وفقًا للضوابط والقواعد التي يضعها مجلس إدارة الهيئة.<<CR>>
13- اتخاذ ما تراه من إجراءات فى حالة حدوث تعثر مالى لأى من الجهات الخاضعة لأحكام هذا القانون،وذلك طبقًا للشروط والقواعد التي يحددها مجلس إدارة الهيئة.<<CR>>
14- إعداد ونشر البيانات الإحصائية والتقارير والدراسات عن نشاط سوق التأمين ووحداته.<<CR>>
15- اقتراح المخاطر التي يكون التأمين فيها إلزاميا.<<CR>>
16- المساهمة فى تعزيز مفهوم الشمول المالى والعمل على توسيع قاعدة المستفيدين من التأمين.<<CR>>
17- المشاركة في تنمية الوعى التأمينى ورفع مهارات العاملين في نشاط التأمين والأنشطة المرتبطة به.<<CR>>
18- وضع قواعد المشاركة في نظام الاستعلام الائتماني في مجال التأمين.<<CR>>
19- توثيق روابط التعاون والتكامل مع هيئات الإشراف والرقابة على التأمين على المستويين الإقليمي والدولي.<<CR>>
20- دعم الدراسات التأمينية والمساهمة فى تمويلها لخدمة سوق التأمين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,153,0,'66defa4062bde868b7bd7b1104386dd1','3d131392984ac33b64b0a4e7bb1e7c9f',replace($m208$يلتزم المخاطبون بأحكام هذا القانون كافة بالمحافظة على السرية التامة لبيانات عملائهم،وعدم إفشاء أى معلومات عنهم أو عن معاملاتهم إلى الغير دون موافقتهم الكتابية المسبقة وفى حدود هذه الموافقة،وذلك باستثناء الحالات التي يلزم فيها تقديم معلومات محددة وفقًا لما تفرضه القوانين لكل من الهيئة أو الجهات القضائية أو الجهات التأمينية أو شركات التصنيف أو الاستعلام الائتمانى،وعلى شركات التأمين أن تتخذ الإجراءات التي تكفل الالتزام بأحكام هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,155,0,'f720f330e4726a5a7d9d84973c53b3e6','c14c6cda2bbe3d8df3f5b70761fb692a',replace($m208$يشترط فيمن يؤسس شركة من الشركات الخاضعة لأحكام هذا القانون،توافر الشروط التي يضعها مجلس إدارة الهيئة،على أن تتضمن على وجه الخصوص: بالنسبة للأشخاص الطبيعيين:<<CR>>
1- ألا يكون قد سبق الحكم عليه أو على أحد مؤسسى الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال الخمس سنوات السابقة على تقديم طلب التأسيس، بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية في إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية لأسباب تتعلق بنشاط الشركة،أو حكم بإشهار إفلاسه ما لم يكن قدر رد إليه اعتباره.<<CR>>
2- ألا يقوم به عارض من عوارض الأهلية.<<CR>>
3- أن يتوافر لديه النزاهة وحسن السمعة.<<CR>>
4- أن يكون متمتعا بحقوقه المدنية كاملة.<<CR>>
وبالنسبة للأشخاص الاعتباريين:<<CR>>
1- وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائي والتأكد من مشروعية مصدر الأموال لطالب التأسيس وأطرافه المرتبطة.<<CR>>
2- توافر الملاءة المالية اللازمة لدى طالب التأسيس لدعم أعمال الشركة أو لزيادة رأسمالها إذا دعت الحاجة لذلك.<<CR>>
3- إذا كان الطالب شركة أو مؤسسة مالية أجنبية خاضعة لإشراف ورقابة جهة أجنبية مناظرة مختصة في الدولة التي يقع فيها مقرها الرئيسي،أن توافق تلك السلطة لها على العمل في جمهورية مصر العربية،وأن تطبق مبدأ الرقابة المجمعة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,156,0,'2424392e44a4a7d024a3dfe10e2f4326','9d88700c8431d3c5ea0f9152a08e4c00',replace($m208$تقدم طلبات تأسيس الشركات الواردة بأحكام هذا القانون إلى الهيئة على النموذج الذي تعده الهيئة مرفقًا بها الأوراق التي تحددها الهيئة. وتعد الهيئة سجلاً تدون به طلبات التأسيس وفقًا لتاريخ ورود كل منها،ويكون لكل طلب ملف خاص ورقى أو إلكترونى تودع فيه أوراق التأسيس وكل ما يتعلق بذلك من إجراءات. ويضع مجلس إدارة الهيئة إجراءات وأوضاع تأسيس تلك الشركات والتي من بينها تشكيل لجنة تضم عناصر فنية وقانونية ومالية لدراسة طلبات التأسيس على ضوء المستندات المقدمة،ومنها:<<CR>>
1- دراسة الجدوى الفنية والاقتصادية للشركة وأغراضها وفروع التأمين المزمع القيام بمزاولتها،والبيانات الإضافية اللازمة لدراسة الطلب.<<CR>>
2- سداد مبلغ يحدده مجلس إدارة الهيئة بما لا يجاوز مائتين وخمسين ألف جنيه مقابل مصروفات فحص الطلب بالنسبة لشركات التأمين أو إعادة التأمين،وبما لا يجاوز مائة ألف جنيه لغيرها من الشركات،ويتم السداد وفقًا للطرق المقررة قانونًا. وللهيئة أن ترفض طلب التأسيس أو إضافة الفرع التأميني أو النشاط بناء على دراستها في ضوء الآتي:<<CR>>
1- مدى حاجة السوق إلى شركة جديدة.<<CR>>
2- مدى مساهمة الشركة فى تلبية احتياجات السوق،سيما من خلال طرح منتجات تأمين جديدة أو التعديل على المنتجات القائمة أو إضافة آليات تسويق غير تقليدية أو التوسع في مناطق جديدة.<<CR>>
3- هيكل الملكية لمؤسسى الشركة وخبراتهم وملاءتهم المالية وفقًا للضوابط والمعايير التي يضعها مجلس إدارة الهيئة. 4- عدم اقتصار غرض الشركة على أحد الأنشطة التأمينية أو الخدمات أو المهن بحسب الأحوال،الواردة بأحكام هذا القانون. 5- عدم نص النظام الأساسي للشركة على وجوب استخدام أسلوب التصويت التراكمي في انتخاب أعضاء مجلس الإدارة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,157,0,'747bc8ef1face086c6ec5909f736a61f','1859de0cf975b0320aec7c106a7d4665',replace($m208$تصدر الهيئة قرارها بالبت في طلب الترخيص خلال ثلاثين يوما على الأكثر من تاريخ تقديم الأوراق مستوفاة إليها،ويقع باطلاً كل عقد تأمين يبرم قبل الترخيص ولا يحتج بهذا البطلان قِبل المؤمن لهم والمستفيدين إلا إذا ثبت سوء نيتهم. وفي حالة رفض طلب الترخيص يجب أن يكون القرار مسببا. وفى حالة عدم رد الهيئة خلال المدة المشار إليها بالفقرة الأولى من هذه المادة اعتبر ذلك بمثابة رفض الطلب،ويكون التظلم منه أمام لجنة التظلمات المنصوص عليها بالمادة (214) من هذا القانون. ويصدر عن مجلس إدارة الهيئة قرار بقواعد وإجراءات رسوم منح الترخيص بما لا يجاوز الرسوم الواردة بهذا القانون بحسب نوع الشركة وغرضها،تسدد وفقًا لطرق السداد المقررة قانونًا. وتضع الهيئة نموذج الترخيص وبيانات التسجيل.$m208$,'<<CR>>',chr(13))),
('law',155,2024,158,0,'a132420111072c1ba1ccb157cb4d5c5f','5d1f5f07c69c49f328816196b8a559c8',replace($m208$يشترط لإصدار الترخيص المنصوص عليه فى المادة (157) من هذا القانون توافر الشروط التي يضعها مجلس إدارة الهيئة،وعلى الأخص منها: 1- أن يكون طالب الترخيص شركة مساهمة مصرية،وألا يقل رأسمالها المصدر والمدفوع عن الحد الذي يقرره مجلس إدارة الهيئة،وبما لا يقل عن الحد الوارد بأحكام هذا القانون بحسب نوع الشركة وغرضها. 2- أن يتفق هيكل ملكية الشركة مع ضوابط هيكل ملكية الشركات الخاضعة لأحكام هذا القانون.<<CR>>
3- أن يتوافر فى القائمين على إدارة الشركة الخبرة والكفاءة اللازمة لعملها على النحو الذي ينص عليه هذا القانون وما يصدر به قرار عن مجلس إدارة الهيئة. 4- أن يتوافر لدى الشركة التجهيزات والبنية التكنولوجية وأنظمة المعلومات اللازمة لمباشرة النشاط وفقًا للمتطلبات التى تحددها الهيئة. شركة ة ال اطر وإدارة وحوكم ة والمخ ة الداخلي ط الرقاب اءة خط - 5 كف والاستراتيجية والسياسة التى ينوى اتباعها فى تصريف شئونه. 6- الالتزام ببدء العمل للنشاط خلال ستة أشهر على الأكثر من تاريخ الحصول على الترخيص،ويجوز بموافقة الهيئة مدها لمدة ستة أشهر أخرى،وذلك فى ضوء المبررات التى تقدمها الشركة وتقبلها الهيئة. وتلتزم شركات التأمين وإعادة التأمين،بالإضافة لما تقدم بموافاة الهيئة كالآتى: ) أ ( شهادة من أحد البنوك المسجلة لدى البنك المركزى المصرى تثبت أن الشركة قد أودعت لديه فى جمهورية مصر العربية أموالاً لا تقل قيمتها عن خمسمائة ألف جنيه عن كل فرع من فروع التأمين التى ترغب الشركة فى مزاولتها، وبحد أقصى ثلاثة ملايين جنيه لجميع هذه الفروع،ولا يجوز للشركة التصرف فى هذه الأموال إلا بموافقة الهيئة. )ب( نماذج الوثائق التى تصدرها الشركة عن كل فرع من فروع التأمين المطلوب الترخيص لها بمزاولته والمزايا والقيود والشروط والأسعار الخاصة بهذه الوثائق. فإذا كان نشاط الشركة مباشرة إحدى العمليات المنصوص عليها فى البند أولاً من الفقرة الأولى من المادة (2) من هذا القانون،فيجب أن يرفق بهذه الوثائق: شهادة من أحد الخبراء الاكتواريين المقيدين فى السجل المعد لذلك بالهيئة بأن أسس أسعار هذه العمليات والمزايا والقيود التى تخولها الوثائق سليمة وصالحة للتنفيذ. جدول يحدد قيمة الاسترداد أو التخفيض،ويجب أن ينص على هذا الجدول فى كل وثيقة من الوثائق المذكورة. ترتيبات إعادة التأمين وطبيعتها. أية مستندات أخرى يحددها مجلس إدارة الهيئة للترخيص لها بمزاولة النشاط.$m208$,'<<CR>>',chr(13))),
('law',155,2024,159,0,'e59ba6ce4090fdeb84fcfdfb6390ca3d','a1436ec41394410e4900ef64c41605a9',replace($m208$يتم تسجيل الشركات المرخص لها من الهيئة وفروعها الجغرافية ومنافذ تسويق وتوزيع وثائقها فى سجل خاص يعد لهذا الغرض بالهيئة،ويكون هذا التسجيل بعد أداء رسم للهيئة يحدده مجلس إدارتها،يسدد وفقًا لطرق السداد المقررة قانونًا، بما لا يجاوز القيم التالية،ووفقًا لما يصدر عنه من معايير: شركات التأمين أيا كان نوع أو صيغة مزاولة النشاط: مائتان وخمسون ألف جنيه عن المركز الرئيسي. خمسون ألف جنيه عن كل فرع. عشرة آلاف جنيه عن كل منفذ تسويق أو توزيع دائم لوثائق التأمين. شركات التأمين الطبي المتخصصة طويلة وقصيرة الأجل: مائة ألف جنيه عن المركز الرئيسي. خمسة وعشرون ألف جنيه عن كل فرع. خمسة آلاف جنيه عن كل منفذ تسويق أو توزيع دائم لوثائق التأمين. شركات إدارة برامج الرعاية الصحية: خمسون ألف جنيه عن المركز الرئيسي. خمسة وعشرون ألف جنيه عن كل فرع. خمسة آلاف جنيه عن كل منفذ تسويق أو توزيع. شركات التأمين متناهى الصغر: عشرون ألف جنيه عن المركز الرئيسي. عشرة آلاف جنيه عن كل فرع. خمسة آلاف جنيه عن كل منفذ تسويق أو توزيع وثائق. الشركات التي تزاول أيا من المهن التأمينية: خمسون ألف جنيه عن المركز الرئيسي. عشرة آلاف جنيه عن كل فرع. خمسة آلاف جنيه عن كل منفذ.<<CR>>
وفي جميع الأحوال،يتعين الحصول على موافقة الهيئة قبل بدء إنشاء كل فرع جغرافي أو منفذ توزيع دائم لوثائق التأمين وقبل الافتتاح للتعامل،على أن يكتفى بالإخطار للمراكز المؤقتة،وذلك كله وفقًا لما يصدر عن مجلس إدارة الهيئة من معايير.$m208$,'<<CR>>',chr(13))),
('law',155,2024,160,0,'ed0d854098b6f08a11fde8468376ae55','dcab35114244f08b3a7635299ce21931',replace($m208$يجوز لشركات التأمين أن تفتح فروعا أو تؤسس شركات لها في الخارج،وذلك وفقًا للشروط والقواعد والإجراءات التي يصدر بها قرار من مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,161,0,'589f6e1cfb7099b0679c3e32e183248a','1a1297a2ecda00d162c3743489ad464f',replace($m208$على الشركة أن تخطر الهيئة بكل تعديل أو تغيير يطرأ على بيانات طلب التسجيل والترخيص بالمزاولة أو الوثائق والمستندات المرافقة له وذلك خلال ثلاثين يوما من تاريخ إجراء هذا التعديل أو التغيير،ويقدم الإخطار بالشروط والأوضاع التي يقررها مجلس إدارة الهيئة،ويكون مصحوبا بالوثائق والمستندات الخاصة بالتعديل أو التغيير. ولا يجوز أن يعمل بهذه التعديلات أو التغييرات إلا بعد اعتمادها من الهيئة. وتصدر الهيئة قرارها بشأن تلك التعديلات خلال ثلاثين يوما من تاريخ استيفاء الشركة للمستندات والبيانات المطلوبة. وتنشر التعديلات المتعلقة ببيانات الترخيص على الموقع الإلكتروني للشركة وكذا الموقع الإلكتروني للهيئة. شركات التأمين وشركات إعادة التأمين$m208$,'<<CR>>',chr(13))),
('law',155,2024,162,0,'d4de4acab6c7ec1fd54378b8e980284c','b26edc21914685d3afff7147c0507d7e',replace($m208$يحدد مجلس إدارة الهيئة الحد الأدنى لرأس المال المصدر والمدفوع بالكامل لشركات التأمين وإعادة التأمين بما لا يقل عن المبالغ الآتية: 250 مليون جنيه نقدا،أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى بالنسبة لشركة تأمينات الأشخاص وعمليات تكوين الأموال. 250 مليون جنيه نقدا،أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى بالنسبة لشركة تأمينات الممتلكات والمسئوليات،على أن يزاد رأس المال بقيمة 50 مليون جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى فى حالة ممارسة أي من فروع البترول،أو الطيران،أو الطاقة.<<CR>>
مليار جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزي المصرى بالنسبة لشركة إعادة التأمين. ولا يجوز أن تجمع شركة التأمين بين مزاولة أى من فروع التأمين الواردة في البند أولاً من الفقرة الأولى من المادة (2) من هذا القانون ومزاولة أى من الفروع الواردة بالبند ثانيا من ذات المادة. شركات التأمين متناهى الصغر$m208$,'<<CR>>',chr(13))),
('law',155,2024,163,0,'5c6648b219c0311da8499132141ef533','a36c817df39f86885c2bb7feb6e625ec',replace($m208$تختص الهيئة بالترخيص بتأسيس شركات يقتصر غرضها الوحيد على مزاولة التأمين متناهى الصغر ولها أن تجمع بين فروع التأمين الواردة بالبند أولاً أو ثانيا من المادة (2) من هذا القانون. ويكون تأسيس تلك الشركات وقيدها والترخيص لها بمزاولة النشاط وفقًا للشروط والقواعد والإجراءات الواردة بأحكام هذا القانون وما يصدر عن الهيئة من قرارات تنفيذًا له. ويحدد مجلس إدارة الهيئة الحد الأدنى لرأس المال المصدر والمدفوع بالكامل لتلك الشركات بما لا يقل عن ثلاثين مليون جنيه أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى. ويجوز للهيئة الترخيص لشركات التأمين بمزاولة نشاط التأمين متناهى الصغر بما يتفق وفروع التأمين،المرخص لها بمزاولتها. قواعد التملك رءوس أموال شركات التأمين وإعادة التأمين$m208$,'<<CR>>',chr(13))),
('law',155,2024,164,0,'e07eb88e556d9959396ac53a500cab49','d892e1a471545b8a2720bd7e3355e437',replace($m208$على كل شخص طبيعي أو اعتبارى وأطرافه المرتبطة يتملك ما يزيد على )(%5 وأقل من ) (%10 من أسهم رأس المال المصدر أو من حقوق التصويت لأى شركة تأمين أو إعادة تأمين أن يخطر الهيئة بذلك خلال خمسة عشر يوما على الأكثر من تاريخ إتمام التملك طبقًا للنموذج الذي تعده الهيئة لهذا الغرض.$m208$,'<<CR>>',chr(13))),
('law',155,2024,165,0,'662e7a5603451499cb26b548b086ddfa','a8664713fb6e996af9a80c8c38a267dc',replace($m208$لا يجوز لأى شخص طبيعي أو اعتبارى وأطرافه المرتبطة أن يتملك بشكل مباشر أو غير مباشر الأسهم أو حقوق التصويت فى شركات التأمين وإعادة التأمين على نحو يؤدى إلى استحواذه أو تجاوزه لأى من النسب الواردة أدناه،وكذلك عند كل زيادة على النسبة المصرح بها إلا بعد الحصول على موافقة مسبقة من مجلس إدارة الهيئة. عشرة بالمائة من رأس المال المصدر أو حقوق التصويت. ربع رأس المال المصدر أو حقوق التصويت. ثلث رأس المال المصدر أو حقوق التصويت. نصف رأس المال المصدر أو حقوق التصويت. ثلثا رأس المال المصدر أو حقوق التصويت. ثلاثة أرباع رأس المال المصدر أو حقوق التصويت. تسعون بالمائة من رأس المال المصدر أو حقوق التصويت. وفى حالة مخالفة ذلك،توقف حقوق التصويت وتوزيعات الأرباح الخاصة بالأسهم الزائدة على النسبة المصرح بها،اعتبارا من تاريخ تملكها. ويتعين على المخالف التصرف فى النسبة الزائدة خلال ستة أشهر من تاريخ استحواذه عليها،وإلا كان للهيئة الأمر بتعيين إحدى شركات السمسرة لتتولى إجراءات بيع الأسهم المخالفة،وتئول حصيلة البيع للمساهم بعد خصم المصروفات، ويجوز مد المهلة لمدة أخرى مماثلة بقرار من مجلس إدارة الهيئة. ويصدر بتحديد قواعد الإفصاح للتعرف على المالك المستفيد لتلك الأسهم، وضوابط التصرف فى الأسهم الزائدة قرار من مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,166,0,'b4c1e0d13b028622252350f86158a461','f07465703c58e5fe9728a96b89e9858c',replace($m208$إذا تملك شخص وأطرافه المرتبطة بالميراث أو الوصية ) (%10 فأكثر من رأسمال الشركة المصدر أو من حقوق التصويت ولم يطلب استمرار تملكه طبقًا لحكم المادة (167) من هذا القانون،فلا يكون له الحق فى التصويت بالنسبة التي تجاوز العشرة في المائة،ويتعين عليه أن يوفق أوضاعه طبقًا للشروط والإجراءات التي تضعها الهيئة خلال مدة لا تجاوز سنتين من تاريخ أيلولة هذه الزيادة إليه،ويجوز للهيئة مدها لفترة مماثلة حال تعثر بيع الأسهم. ويسرى عليه حال عدم توفيق أوضاعه خلال هذه المدة حكم الفقرة الثالثة من المادة (165) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,167,0,'edc7a01d961a7ac62e64d869752423ac','4e28971d8168e2b623ecc9ca78b4ab9a',replace($m208$يجب أن يقدم طلب الموافقة على تملك نسبة ) (%10 أو ما يزيد على تلك النسبة من رأس المال المصدر للشركة أو من حقوق التصويت إلى الهيئة،قبل موعد إتمام التملك بستين يوما على الأقل،وذلك على النموذج المعتمد من الهيئة ويرفق بالطلب تقرير يبين ملاءته المالية وسبب الرغبة في تملك الأسهم والأهداف التي يرمى مقدم الطلب إلى تحقيقها منه وخططه فى إدارة الشركة والسياسة التي ينوي اتباعها في تصريف شئونها ونسبة مساهماته وأطرافه المرتبطة فى أى شركة أو منشأة أخرى. فإذا كان التملك بطريق الميراث أو الوصية أو نتيجة لتخصيص أسهم مطروحة في اكتتاب عام،يتعين تقديم طلب استمرار التملك خلال ثلاثين يوما من تاريخ علم الطالب بما آل إليه بطريق الميراث أو الوصية أو الاكتتاب العام. ويتم النشر عن الطلب المنصوص عليه فى الفقرتين الأولى والثانية من هذه المادة على الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض وذلك خلال ثلاثين يوما من تاريخ تقديمه على النموذج الذي تعده الهيئة لهذا الغرض. ولكل ذى مصلحة أن يتقدم إلى الهيئة باعتراض مسبب على الطلب خلال خمسة عشر يوما من تاريخ النشر.$m208$,'<<CR>>',chr(13))),
('law',155,2024,168,0,'822646a284864c1bc02fb7445edde146','c5501114e7c4070cd647dc267bcfb381',replace($m208$يشترط للموافقة على الطلب المنصوص عليه فى المادة (167) من هذا القانون ما يأتي: 1- وضوح هيكل الملكية لطالب التملك وأطرافه المرتبطة.<<CR>>
2- توافر الملاءة المالية اللازمة لدى طالب التملك لدعم أعمال الشركة أو لزيادة رأسمالها إذا دعت الحاجة لذلك. 3- التثبت من مصادر أموال طالب التملك.<<CR>>
4- ألا يترتب على قبول الطلب الحد من المنافسة بسوق التأمين أو اضطراب العمل بها.<<CR>>
5- إذا كان الطالب شركة تأمين أجنبية أو مؤسسة مالية أجنبية يتعين أن تكون خاضعة لإشراف ورقابة جهة فى الدولة التى يقع بها مقرها الرئيسي،وتلتزم بموافاة الهيئة بشهادة من تلك الجهة تفيد سلامة موقفها الرقابي قبل تقديم الطلب. 6- ألا يؤثر التملك سلبا على إدارة الشركة أو يضر بمصالح حملة الوثائق أو المستفيدين منها أو مصالح المساهمين الآخرين،وذلك فى ضوء الخطط والسياسة التي ينوى اتباعها. 7- ألا يكون قد سبق الحكم عليه أو على أحد مؤسسي الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال خمس السنوات السابقة على تقديم طلب التأسيس، بعقوبة جناية أو بعقوبة جنحة فى جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية فى إحدى الجرائم المنصوص عليها فى قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية لأسباب تتعلق بنشاط الشركة،أو حكم بإشهار إفلاسه ما لم يكن قد رد إليه اعتباره.$m208$,'<<CR>>',chr(13))),
('law',155,2024,169,0,'32007c8c4e8633f57ad03ae837fd2368','9bcee276b4530ad1fb84b8450598779c',replace($m208$يخطر صاحب الشأن بقرار قبول أو رفض الطلب المشار إليه في المادة (167) من هذا القانون خلال ستين يوما من تاريخ تقديمه،بكتاب موصى عليه مصحوب بعلم الوصول أو بأية وسيلة أخرى. وتكون الموافقة سارية لمدة ستة أشهر من تاريخ إبلاغ طالب التملك بها، وإلا اعتبرت كأن لم تكن،ويجوز لمجلس إدارة الهيئة مد هذه المهلة لفترة مماثلة. وفى حالة صدور قرار برفض استمرار تملك الطالب للنسبة التي آلت إليه بطريق الميراث أو الوصية أو نتيجة لتخصيص أسهم مطروحة في اكتتاب عام أو بأي وسيلة أخرى،تتم مطالبته من الهيئة بالتصرف فيها خلال سنتين من تاريخ إخطاره بقرار الرفض إذا كان التملك بالميراث أو الوصية وخلال ثلاثة أشهر إذا كان التملك عن طريق الاكتتاب العام. ويجوز للهيئة مد هذه المهلة لمدة أخرى مماثلة،ويسرى في شأنه حال عدم تصرفه فيها خلال هاتين المدتين حكم الفقرة الثالثة من المادة (165) من هذا القانون.<<CR>>
) الفصل الثالث ( الرقابة والإشراف شركات التأمين وإعادة التأمين إدارة وحوكمة الشركات$m208$,'<<CR>>',chr(13))),
('law',155,2024,170,0,'752222fa9bdb43be9dfc4d22041fa257','6b569773e51b368256a86a45733f3576',replace($m208$تلتزم الشركات التى تباشر نشاط التأمين أو إعادة التأمين بالقواعد والضوابط والمعايير التي يضعها مجلس إدارة الهيئة،والتي يجب أن تتضمن على الأخص ما يلى: 1- الضوابط الواجب توافرها فى نظم عمل الرقابة الداخلية والائتمان وإدارة المخاطر. 2- معايير الملاءة المالية. 3- ضوابط ومعايير حساب الاضمحلال والمخصصات للعمليات المشكوك في تحصيلها. 4- الضوابط والإمكانيات الواجب توافرها فى نظم معلومات وشبكة اتصالات الشركة ووسائل حمايتها وتأمينها. 5- ضوابط فتح ونقل وغلق فروع الشركة. 6- ضوابط مكافحة غسل الأموال وتمويل الإرهاب،بعد التنسيق مع الجهات المعنية ذات الصلة. 7- التقارير الدورية والإحصاءات التي يجب أن تقدمها الشركة للهيئة وتوقيتاتها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,172,0,'ba2a475b01e108744253bebf645f8e4e','474a9e84a8597dba8939e5a88c2a9bd5',replace($m208$يصدر مجلس إدارة الهيئة قواعد حوكمة شركات التأمين وإعادة التأمين بما فيها تشكيل مجلس إدارتها،ومدته. ويجب أن تتوافر في أعضاء مجلس الإدارة شروط الخبرة والكفاءة وحسن السمعة عند التعيين وطوال مدة عضويتهم بالمجلس. كما يشترط بالنسبة للقائمين على الإدارة التنفيذية المسئولين عن أي من الأعمال والوظائف الفنية بالشركة،سيما منها إدارات الاكتتاب والتعويضات وإعادة التأمين والاستثمار والمالية ومكافحة غسل الأموال وتمويل الإرهاب،أن يكونوا من ذوى الخبرة في مجال التأمين وإعادة التأمين والاستثمار والمالية ومتطلبات مكافحة غسل الأموال وتمويل الإرهاب،بحسب الأحوال،وذلك كله وفقًا للشروط والمعايير الصادرة عن مجلس إدارة الهيئة. وتلتزم الشركات الخاضعة لأحكام هذا الفصل أيا كان سند تأسيسها أو القانون الذي تأسست وفقًا لأحكامه بإخطار رئيس مجلس إدارة الهيئة بترشيح أو بتجديد ترشيح أعضاء مجلس الإدارة والقائمين بالإدارة التنفيذية وجميع البيانات المتعلقة بهم قبل العرض على الجمعية العامة للشركة لمراجعتها،ويتم الإخطار على النموذج الذي تضعه الهيئة وخلال المواعيد التي يحددها مجلس إدارة الهيئة. وفي جميع الأحوال،لا يمارس أى ممن تقدم أعماله إلا بعد الحصول على موافقة الهيئة،وتكون موافقة الهيئة لمدة ثلاث سنوات قابلة للتجديد بالنسبة للمديرين التنفيذيين المشار إليهم بهذه المادة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,173,0,'62e09b73c7abd6ec07d3c1ca039144a4','3d02f6c0052809c2937ba865a8f62e22',replace($m208$على الشركة أن تخطر الهيئة بموعد ومكان انعقاد الجمعية العامة وجدول أعمالها قبل موعد الانعقاد بثلاثين يوما،على أن يرفق بالإخطار جميع المستندات التي تقدم للمساهمين أو من في حكمهم عن أعمال الشركة. وتلتزم الشركة بإدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية العامة العادية للشركة،وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة في حالة عدم حضور ممثل عن الهيئة. وعليها كذلك أن تقدم إلى الهيئة صورة من محضر اجتماع الجمعية العامة في موعد أقصاه ثلاثون يوما من تاريخ انعقاد الجمعية لاعتماده.<<CR>>
تنظيم ممارسة النشاط$m208$,'<<CR>>',chr(13))),
('law',155,2024,174,0,'ef9cafa0465c8e8aab2e3d928ea08970','08f9b7185887d0c94486971f76915b85',replace($m208$تلتزم الشركة بتكوين المخصصات الفنية اللازمة لمقابلة التزاماتها قبل حملة الوثائق والمستفيدين منها من خلال تقرير يعده خبير اكتوارى مسجل بالهيئة، وذلك على الوجه الآتي:ً أولا -بالنسبة لتأمينات الأشخاص وعمليات تكوين الأموال: 1- الاحتياطى الحسابي،يتمثل فى الفرق بين القيمة الحالية لمبلغ التأمين المتوقع الذي تلتزم الشركة بسداده إلى المؤمن له من ناحية والقيمة الحالية للأقساط المستقبلية التي يتعين سدادها للشركة من ناحية أخرى وخلال فترة سريان الوثيقة وسداد المؤمن له للأقساط المستحقة عليه أولاً بأول. ويتم تقدير الاحتياطى الحسابي آخر المدة بمعرفة الخبير الاكتواري لمقابلة التزامات الشركة قِبل حملة الوثائق فى نهاية السنة المالية وفقًا للأسس الفنية التي يعتمدها مجلس إدارة الهيئة. 2- مخصص المطالبات تحت التسوية بقيمة المطالبات التى لم يتم تسويتها حتى تاريخ إعداد القوائم المالية. 3- مخصص مطالبات عن الحوادث التي وقعت ولم يبلغ عنها حتى تاريخ إعداد القوائم المالية بالنسبة لبعض أنواع تأمينات الأشخاص وعمليات تكوين الأموال وذلك وفقًا لما تحدده الهيئة. ويتعين أن تكون هذه المخصصات كافية لمقابلة حقوق حملة الوثائق،وإذا ما رأت الهيئة خلال فحص هذه المخصصات عدم كفايتها،يتعين على الشركة اتخاذ الإجراءات اللازمة لاستكمالها وفقًا للقواعد التي يحددها مجلس إدارة الهيئة في هذا الشأن. وعلى الشركة المنصوص عليها فى هذا البند أن تقدر قيمة التعهدات القائمة على الشركة لفرعى تأمينات الأشخاص وعمليات تكوين الأموال اللذين تزاولهما مرة على الأقل سنويا بواسطة أحد الخبراء الاكتواريين. ويتناول هذا التقدير جميع عمليات التأمين التي أبرمتها الشركة في جمهورية مصر العربية وفى الخارج كل على حدة.<<CR>>
ويجب إجراء هذا التقدير كلما أرادت الشركة تحديد نسب الأرباح التي توزع على المساهمين أو حملة الوثائق. ويجوز للهيئة إذا رأت ضرورة لذلك بعد موافقة مجلس إدارتها،أن تطلب إجراء هذا التقدير فى أى وقت قبل انقضاء المدة المشار إليها. ويحدد مجلس إدارة الهيئة البيانات التى يجب أن يشتمل عليها تقرير الخبير الاكتوارى وكذا الإجراءات الواجب اتخاذها في هذا الشأن. ثانيا -بالنسبة لتأمينات الممتلكات والمسئوليات: 1- مخصص الأخطار السارية: يتم تكوينه لمقابلة التزامات الشركة عن عمليات التأمين المصدرة من جملة اكتتابات الشركة وما زالت سارية بعد انتهاء السنة المالية. 2- مخصص التعويضات تحت التسوية عن الحوادث التى تم الإبلاغ عنها حتى تاريخ إعداد القوائم المالية. 3- مخصص لمقابلة الحوادث التي وقعت ولم يبلغ عنها حتى تاريخ إعداد القوائم المالية. 4- مخصص للتقلبات العكسية،هو ما يقابل أخطار التقلبات فى التعويضات المستقبلية التي قد تهدد استقرار الشركة ويتم تجنيبه فى السنوات التى تنخفض فيها معدلات الخسائر الفعلية عن المقدرة لمواجهة مخاطر ارتفاع معدلات الخسائر في السنوات التالية،ويصدر قرار من مجلس إدارة الهيئة بأسس تكوين واستخدام ذلك المخصص والحالات التي يستخدم فيها بالنسبة لكل فرع من فروع تأمينات الممتلكات والمسئوليات. وفي جميع الأحوال،يتم اعتماد تلك المخصصات من خبير اكتوارى للشركة يتم اختياره من بين المقيدين بالسجل المعد لذلك بالهيئة وفقًا للمعايير والضوابط الصادرة عن مجلس إدارة الهيئة،وفى حالة إذا ما لم يعبر تقرير الخبير الاكتوارى عن حقيقة الوضع المالي للشركة فإن للهيئة أن تطلب إعادة الفحص المنصوص عليه بعاليه بمعرفة خبير اكتوارى آخر على نفقة الشركة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,175,0,'c496e37e03148c8c0b8aa79fae1f82da','46b660f9d3bb927f916b88001e304266',replace($m208$على كل شركة تأمين وشركة إعادة تأمين أن تخصص فى جمهورية مصر العربية أموالاً تعادل قيمتها قيمة المخصصات الفنية المنصوص عليها فى المادة (174) من هذا القانون،وذلك عن العمليات التى تكتتب فيها فى جمهورية مصر العربية، وذلك وفقًا للضوابط والقواعد الصادرة عن مجلس إدارة الهيئة فى هذا الشأن. ولا يجوز الحجز على هذه الأموال إلا بعد الرجوع على الأموال الأخرى للشركة. ويصدر قرار عن مجلس إدارة الهيئة بتحديد قواعد وضوابط ونسب استثمار هذه الأموال وكذلك طرق تقييمها،وتتقيد الشركة فى سياستها الاستثمارية بتلك القواعد والضوابط والنسب التى تصدر عن مجلس إدارة الهيئة. وعلى كل شركة أن تقدم إلى الهيئة بيانات عن أموالها المخصصة فى المواعيد التى يصدرها مجلس إدارة الهيئة. وللهيئة أن تتخذ ما تراه مناسبا فى أى وقت للتحقق من قيام الشركة بتنفيذ أحكام هذه المادة. وعلى الشركة أن تخطر الهيئة بكل التصرفات أو الأحكام النهائية التى ترد على الأموال الواجب تخصيصها والتى من شأنها إنشاء حق من الحقوق العينية العقارية أو نقله أو تغييره أو زواله وذلك قبل شهرها بطريق التسجيل أو القيد.$m208$,'<<CR>>',chr(13))),
('law',155,2024,178,0,'239fbcf56d4b7d6cede4710bcfb95b4b','c218043e34dcba734ef16106b16cd62a',replace($m208$يكون لحملة الوثائق وللمستفيدين منها التى تبرمها الشركة وتنفذها فى جمهورية مصر العربية امتياز على الأموال المخصصة طبقًا للمادتين (174، 175) من هذا القانون يأتى فى المرتبة بعد الامتياز المقرر فى الفقرة )أ( من المادة (1141) من القانون المدنى،وتؤشر الجهة المختصة بالشهر والتوثيق،بناء على طلب الهيئة، بهذا الامتياز على هامش كل تسجيل أو قيد خاص بهذه الأموال على أن تخطر الهيئة بكل تأشير يتم.$m208$,'<<CR>>',chr(13))),
('law',155,2024,179,0,'a453a233314232252676f06e3d9bc282','80d0bb0f6ff8691f3b48e7cdd1bfc080',replace($m208$على كل شركة تأمين أن تمسك السجلات الآتية لكل فرع من فروع التأمين:<<CR>>
1- سجل إصدار الوثائق. 2- سجل التعديلات على الوثائق. 3- سجل التعويضات. 4- سجل شكاوى العملاء. 5- سجل الوسطاء. 6- سجل الاتفاقيات. 7- سجل الاستثمارات بما يشمله من أموال مخصصة وحرة. أما شركة إعادة التأمين فيكون لديها السجلات المشار إليها بالبنود (3، 5، 6، 7) من هذه المادة. وتحدد الهيئة الحد الأدنى من البيانات الواجب قيدها فى تلك السجلات. ويجوز لمجلس إدارة الهيئة أن يضيف سجلات أخرى.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',155,2024,182,0,'adefc93926e0d943428f4a898d813aef','fc8e3442bf1c5f38ababc993ca3d0d30',replace($m208$تتولى الهيئة الإشراف والرقابة على شركات التأمين وإعادة التأمين وفقًا لأساليب تقييم وإدارة المخاطر وقواعد الملاءة المالية الواردة بأحكام هذا القانون وما يصدر عن مجلس إدارة الهيئة من قرارات وبما يتفق وطبيعة نشاط كل منها.<<CR>>
ويلتزم الكيان بتقديم التقارير التى تطلبها الهيئة عن هيكل الملكية والإدارة وكفاية رأس المال وسياسات إدارة المخاطر والعمليات التى يقوم بها الكيان مع جهات خارجية والضمانات المقدمة على مستوى الكيان والمسئوليات القانونية المترتبة عليها وآليات الرقابة الداخلية وعمليات إدارة المخاطر.$m208$,'<<CR>>',chr(13))),
('law',155,2024,183,0,'463331ab0488976a122a3673fc74dfc9','850efc51b70a5a7b9e073428b81487ff',replace($m208$تلتزم الشركة بأن تحتفظ فى كل وقت بالمجموعة الدفترية التى تمكن من إعداد قوائمها المالية وفقًا لمعايير المحاسبة المصرية،كما تلتزم الشركة بالاحتفاظ بالسجلات والمستندات والمكاتبات والوسائط الإلكترونية بما يتفق مع القوانين واللوائح السارية. ويتعين على الشركة إعداد القوائم المالية وفقًا لمعايير المحاسبة المصرية، ويصدر مجلس إدارة الهيئة مواعيد إعدادها وعرضها،مرفقًا بها تقرير مراقب الحسابات على الجمعية العامة للشركة وغيرها من قواعد إعداد القوائم المالية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,184,0,'11e5d36a4883a521bc30a0b949e3e1ab','98af0d05b6201ca676b8d13bd00944fb',replace($m208$يتولى مراجعة حسابات الشركة مراقب حسابات أو أكثر من بين المقيدين بالسجل المعد لهذا الغرض بالهيئة وفقًا لمعايير المراجعة المصرية. ويلتزم مراقب الحسابات بأن يفصح ضمن تقريره المعد بشأن مراجعة حسابات الشركة عن الآتى: مدى كفاية المخصصات وفقًا لسياسة تكوين المخصصات المعتمدة من مجلس إدارة الشركة،مع الالتزام بالمعايير الصادرة عن الهيئة فى هذا الشأن،وذلك فيما عدا المخصصات التى يجب أن تعتمد من الخبير الاكتوارى. إذا ما كانت هناك أية مخالفات للقانون أو التعليمات الرقابية. مدى كفاية نظم الرقابة الداخلية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,186,0,'6f143735c3ac883885cc4c6bd8a0c392','7571929659b0e70303995f6d8248bd44',replace($m208$على الشركة أن تقدم للهيئة كل سنة مالية البيانات والحسابات اللازمة، وذلك فى الموعد الذى يحدده مجلس إدارة الهيئة،وعلى الأخص منها: ) أ ( ملخص اتفاقيات إعادة التأمين. )ب( بيان بأموال الشركة المخصصة الواجب الاحتفاظ بها فى جمهورية مصر العربية وفقًا لأحكام هذا القانون مؤيد بالمستندات التى تطلبها الهيئة. وتعد هذه البيانات طبقًا للنماذج التى تصدرها الهيئة وتشمل جميع العمليات التى تقوم بها الشركة فى جمهورية مصر العربية وفى الخارج كل على حدة. ويجب أن تكون هذه البيانات التى تقدم طبقًا لأحكام هذا القانون موقعة من الممثل القانونى للشركة ومن مديرها المالى. ويجب أن يرفق بهذه البيانات تقرير عن أعمال الشركة فى جمهورية مصر العربية عن تلك السنة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,187,0,'f8bcd954198eb5fd56394ab996cb4d14','6273a873d4c289d006c2a3c5711cf6b5',replace($m208$على الشركة إخطار الهيئة بالقوائم المالية السنوية وتقرير مراقب الحسابات قبل شهر من التاريخ المحدد لانعقاد الجمعية العامة للشركة،وللهيئة فحص القوائم والتقارير المشار إليها وإبلاغ الشركة بملاحظاتها،حال وجودها،وطلب إعادة النظر فيها بما يتفق ونتائج الفحص،فإذا لم تستجب الشركة لذلك التزمت بعرضها على الجمعية العامة ونشر القوائم المالية وتقرير مراقب الحسابات بإحدى الصحف الرسمية واسعة الانتشار،وعلى كل من الموقع الإلكترونى للشركة والهيئة أن يرفق بهما ملاحظات الهيئة والتعديلات التى طلبتها. وتلتزم تلك الشركات بنشر ملخص القوائم المالية السنوية والإيضاحات المتممة لها وتقرير مراقب الحسابات بشأنها على الموقع الإلكترونى للشركة وكذا الموقع الإلكترونى الذى تخصصه الهيئة للنشر وفقًا للنموذج الذى تعده الهيئة لهذا الغرض.$m208$,'<<CR>>',chr(13))),
('law',155,2024,188,0,'bb64dd12e444d0a0980ab9e9e37ad26e','291f03f1ac40516f43f7d96ead7b6ba9',replace($m208$تعد من التكاليف واجبة الخصم عند تحديد صافى الدخل الخاضع للضريبة وفقًا لأحكام قانون الضريبة على الدخل الديون التى يقرر مجلس إدارة الشركة إعدامها وتزيد على المخصصات المشار إليها بالمادة (174) من هذا القانون،وذلك بعد اتخاذ الإجراءات الجادة لاستيفائها وفقًا للضوابط والإجراءات التى يضعها مجلس إدارة الهيئة،على أن يصدر بها تقرير من مراقب الحسابات.<<CR>>
فحص أعمال الشركات$m208$,'<<CR>>',chr(13))),
('law',155,2024,189,0,'ba47181a0380a626171b8eae02980ef0','c7cc5bcecb15230b96d75c75101c14e7',replace($m208$تتولى الهيئة إجراء فحص دورى لشركة التأمين وإعادة التأمين للتأكد من سلامة المركز المالى ومراعاة أحكام القانون والأسس الفنية لمزاولة عمليات التأمين وإعادة التأمين. ويجوز للهيئة أن تفحص أعمال الشركة فحصا شاملاً أو جزئيا إذا قام لديها من الأسباب ما يحملها على الاعتقاد بأن حقوق حملة الوثائق معرضة للضياع أو أن الشركة معرضة لعدم القدرة على الوفاء بالتزاماتها أو أن ممارستها قد ثبت إضرارها بسوق التأمين أو أنها خالفت أحكام هذا القانون. كما يجوز إجراء هذا الفحص إذا طلبه عدد من المساهمين يمثل عشرة بالمائة من رأس المال المصدر والمدفوع على الأقل للشركة أو عدد لا يقل عن خمسمائة من حملة وثائق تأمينات الأشخاص وعمليات تكوين الأموال يكون قد مضى على إصدارها مدة لا تقل عن ثلاث سنوات. وعلى الشركة أن تقدم للهيئة أية معلومات أو بيانات أو مستندات تطلبها أثناء قيامها بهذا الفحص. ويتم الفحص وفقًا للأوضاع والإجراءات التى يحددها مجلس إدارة الهيئة. التأمين الطبى المتخصص طويل وقصير الأجل وما يرتبط بهما من خدمات$m208$,'<<CR>>',chr(13))),
('law',155,2024,190,0,'3b467b780059e8e785283bde51b31ee3','cbae8dfbb17a024f00fd8d747b6ec3f4',replace($m208$تتولى الهيئة الإشراف والرقابة على كل من شركات التأمين الطبى المتخصصة طويل وقصير الأجل وشركات إدارة برامج الرعاية الصحية وفقًا لأساليب تقييم وإدارة المخاطر وقواعد الملاءة المالية والسيولة الصادرة عن مجلس إدارة الهيئة وبما يتفق وطبيعة نشاط كل منها. ويصدر مجلس إدارة الهيئة القواعد والضوابط والإجراءات المنظمة لقواعد الفحص واختبارات الملاءة المالية وكذا النماذج والعقود الواجب اعتمادها من الهيئة قبل العمل بها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,191,0,'613ed6ccfae8970e0e4e881b99a56de4','3ba7266e2bfa930560c0c956d52df0c3',replace($m208$فيما لم يرد به نص خاص،تخضع شركات التأمين الطبى المتخصصة طويل وقصير الأجل الواردة فى هذا الباب لذات الأحكام المقررة بالنسبة لشركات التأمين المرخص لها بالعمل فى الفروع الواردة بالمادة (2) من هذا القانون،وبما لا يخل بطبيعة الأنشطة التى تزاولها تلك الشركات. التأمين التكافلى وإعادة التأمين التكافلي$m208$,'<<CR>>',chr(13))),
('law',155,2024,192,0,'4e4c192089224248e38d13f3704495a1','cd5cf1a6693454cb4f8626bc16a79c23',replace($m208$تلتزم الشركة التى ترغب فى الترخيص لها بمزاولة التأمين التكافلى أو إعادة التأمين التكافلى فى مصر بالعمل وفقًا للقواعد والمعايير والضوابط الرقابية التى يضعها مجلس إدارة الهيئة. وتلتزم تلك الشركات بإسناد أعمالها إلى شركات إعادة تأمين تكافلى،وفى حالة عدم توفر طاقة استيعابية كافية لدى تلك الشركات أو عدم وجود تغطية للخطر المراد إعادة تأمينه يجوز لشركة التأمين التكافلى بعد اعتماد الهيئة التعامل مع شركات إعادة تأمين تقليدية،وفى هذه الحالة تخضع اتفاقيات إعادة التأمين لموافقة لجنة الرقابة الشرعية المنصوص عليها فى المادة (193) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,193,0,'4c9f208a9d3f2a3de9c6a81eb51a348d','6f7818fdf52ef00229870b3f2b714b13',replace($m208$تلتزم شركة التأمين التكافلى أو إعادة التأمين التكافلى بتشكيل لجنة تسمى "لجنة الرقابة الشرعية" من ثلاثة أعضاء على الأقل من بين المقيدين بالسجل المعد لهذا الغرض بالهيئة يتم تعيينهم لمدة ثلاث سنوات قابلة للتجديد. ويصدر قرار من مجلس إدارة الهيئة بتحديد شروط وقواعد القيد وإعادة القيد والشطب بالسجل المشار إليه،كما يحدد القرار بعد موافقة الأزهر الشريف متطلبات تشكيل هذه اللجان. وتكون مهام تلك اللجنة مراقبة جميع معاملات الشركة والإشراف عليها وإبداء الرأى فى مدى توافقها مع أحكام الشريعة الإسلامية ومبادئها ومراقبة الفصل التام بين حساب المساهمين وحساب المشتركين،فضلاً عن مراعاة أحكام الشريعة ومبادئها فى التوظيفات المالية بالنسبة للمشتركين والمساهمين على حد سواء.$m208$,'<<CR>>',chr(13))),
('law',155,2024,194,0,'8eedf8caae4523ac5a327bf6721da656','47d799dad3ca0ef3cf541f0f9611033b',replace($m208$تلتزم شركة التأمين التكافلى التى تعمل بنموذج المضاربة بما يلى: 1- توزيع الفائض التأمينى على المشتركين بما لا يقل عن ) (%50 وذلك وفقًا لآليات التوزيع الواردة بالنظام الأساسى للشركة بعد أخذ رأى لجنة الرقابة الشرعية. 2- تجنيب الفائض التأمينى الخاص بالمشتركين فى حساب خاص،ويراعى فيه توزيع الجزء الذى لم تتمكن الشركة من توزيعه على المشتركين فى أوجه الخير أو التبرع الذى تحدده الشركة وفقًا للضوابط والقواعد التى يصدربها قرار عن مجلس إدارة الهيئة. 3- مراعاة الإعلان المسبق بمنتجات تلك الشركات عن أسس ومعايير التكافل وأبرزها نسب توزيعات الفائض وآلياته على المشتركين. 4- عدم الإخلال بالمخصصات الفنية الواجب على الشركة الاحتفاظ بها وفقًا لأحكام المادة (174) من هذا القانون،وعلى الشركة تكوين احتياطى لتغطية عجز حساب التكافل.$m208$,'<<CR>>',chr(13))),
('law',155,2024,195,0,'a83f8ae5d8f523ceade09c2b62ca7774','073d95961f3751b6f96cddf07cef143b',replace($m208$فى حالة وجود عجز فى حساب التكافل يتعين على مساهمى الشركة تقديم قرض حسن لهذا الحساب،ويعتبر الالتزام بتقديم القرض المشار إليه التزاما شاملاً حده الأقصى ) (%50 من مجموع حقوق المساهمين فى الشركة،ويكون استرداد هذا القرض من الفائض أو الفوائض التى قد تتحقق فى الفترات اللاحقة،وفى حالة عدم تقديم المساهمين لهذا القرض خلال ثلاثين يوما من تاريخ إنذار الشركة بمعرفة الهيئة يتم العرض على مجلس إدارة الهيئة لاتخاذ أى من التدابير الواردة بأحكام المادة (201) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,196,0,'9f40c9f86a376d12f33e1d0319468a91','53b4466a30ac2d8858d84aa485436586',replace($m208$مع مراعاة ما هو وارد بنص المادة (194) من هذا القانون،تتولى الشركة إدارة حساب التكافل وأعمال الاستثمار المرتبطة بالاشتراكات على أساس نموذج الوكالة أو المضاربة أو كليهما معا،وذلك وفقًا لما يحدده النظام الأساسى للشركة وما تضعه الهيئة من ضوابط فى هذا الخصوص.$m208$,'<<CR>>',chr(13))),
('law',155,2024,197,0,'93cf9def867e728a155150b821fb3cb9','84ad2c1c3af409afffd1ccabd460ef65',replace($m208$لا يجوز تحويل وثائق التأمين التكافلى إلا إلى شركة تأمين تكافلى أخرى تمارس نفس نوع وفروع التأمين التكافلى. ولا يجوز دمج شركة التأمين التكافلى إلا بشركة تأمين تكافلى أخرى تمارس نوع التأمين ذاته. ويجوز لكل من شركات التأمين التجارى تعديل نظامها الأساسى للعمل وفقًا لصيغة التأمين التكافلى،كما يجوز لشركات التأمين التكافلى تعديل نظامها الأساسى للعمل وفقًا لصيغة التأمين التجارى،على أن تقدم طلبا بذلك إلى الهيئة حسب النموذج الذى تعتمده،على أن يتضمن خطة توضح الإجراءات التى ستتبعها الشركة الراغبة فى التعديل لتوفيق أوضاعها وفقًا للضوابط والإجراءات الصادرة عن مجلس إدارة الهيئة،بشرط ألا تتجاوز فترة الخطة مدة سنتين من تاريخ موافقة الهيئة عليها وتكون قابلة للتمديد لمدة أخرى بقرار من الهيئة إذا اقتضت الضرورة ذلك. وفيما عدا ما تقدم من نصوص فى هذا الفصل،تخضع شركة التأمين التكافلى وإعادة التأمين التكافلى لسائر الأحكام الواردة فى هذا القانون بشأن شركة التأمين وإعادة التأمين وذلك فى كل ما لم يرد بشأنه نص خاص. ) الفصل الرابع ( صندوق ضمان حملة الوثائق$m208$,'<<CR>>',chr(13))),
('law',155,2024,199,0,'8f110fc99b489d42f650b314c3927a9f','c298af054bb087b8d39ff078e37b662f',replace($m208$يجوز لشركات التأمين المقيدة بسجلات الهيئة أن تصدر بعض وثائق التأمين النمطية التى يصدر بتحديدها قرار من مجلس إدارة الهيئة،وذلك إلكترونيا من خلال نظم معلومات الشركات وإتاحة طباعة الوثيقة بواسطة المؤمن له مباشرة أو تسويقها وتوزيعها بواسطة إحدى الجهات التى يحددها مجلس إدارة الهيئة. وعلى الشركة الحصول على موافقة مسبقة من الهيئة بذلك،وأن تلتزم بالضوابط التى تصدر عن الهيئة بشأنها. كما يضع مجلس إدارة الهيئة اشتراطات وضوابط تراخيص السماح لتلك الشركات بإصدار الوثائق إلكترونيا وتراخيص إنشاء المواقع الإلكترونية والاستفادة من خدمات الحوسبة السحابية أو تقديم أى من الخدمات الإلكترونية.$m208$,'<<CR>>',chr(13))),
('law',155,2024,200,0,'90c2ed3e14b549766d0c6fbb707bdf7b','f9d73c6f9fedf071d2039813f6b23a32',replace($m208$مع عدم الإخلال بحكم المادة (67) من هذا القانون،يجب على جميع الأشخاص الاعتبارية المخاطبة بأحكام هذا القانون أن تنشئ لها موقعا إلكترونيا مرخصا من الهيئة يحتوى على الإفصاح والشفافية الكافية للمتعاملين معها عن أحكامها،وخاصة الغرض من إنشائها ونوع وصيغة التأمين الذى تزاوله وأهم القرارات الصادرة عن إدارتها وذلك وفقًا للضوابط التى يضعها مجلس إدارة الهيئة. ) الفصل السادس ( الإجراءات والتدابير الرقابية$m208$,'<<CR>>',chr(13))),
('law',155,2024,201,0,'d83d2a9bb6c448ae6e0a752bca1d3ff6','df577b674bc287651b7fc10e12cabec4',replace($m208$يجوز لمجلس إدارة الهيئة تحقيقًا لاستقرار السوق،أو حماية لحقوق المتعاملين مع الشركة من حملة الوثائق والمستفيدين منها،أو فى حالة تعرض الشركة لمشكلات مالية تؤثر على مركزها المالى،إلزام الشركة بتعزيز ملاءتها المالية وفقًا لجدول زمنى محدد،وعلى الشركة الالتزام بقرار مجلس إدارة الهيئة الصادر فى هذا الخصوص وإلا جاز لمجلس إدارة الهيئة اتخاذ تدبير أو أكثر من التدابير الآتية: 1- دعوة مجلس إدارة الشركة إلى الانعقاد للنظر فى أمر المخالفات المنسوبة إلى الشركة واتخاذ اللازم نحو إزالتها ويحضر اجتماع مجلس الإدارة فى هذه الحالة ممثل أو أكثر عن الهيئة.<<CR>>
2- تعيين عضو مراقب فى مجلس إدارة الشركة للمدة التى يحددها مجلس إدارة الهيئة ويكون له المشاركة فى مناقشات المجلس وإبداء الرأى فيما يعرض من موضوعات دون أن يكون له صوت معدود. 3- تجنيب الفائض القابل للتوزيع على المساهمين أو جزء منه لدعم المركز المالى للشركة. 4- إلزام الشركة بإعادة هيكلة نشاط أو أكثر من أنشطتها. 5- تقييد قبولها عمليات جديدة أو تجديدها عمليات قائمة أو كليهما معا لمدة محددة بالنسبة لكل أو بعض فروع التأمين المرخص لها بمزاولتها. 6- تنحية واحد أو أكثر من القائمين على الإدارة التنفيذية بالشركة. 7- إلزام الشركة بزيادة رأسمالها المدفوع بالقدر الذى تراه الهيئة لتدعيم قدرتها على الوفاء بالتزاماتها. 8- عزل عضو أو أكثر من أعضاء مجلس الإدارة وتعيين مفوض لإدارة الشركة بصفة مؤقتة لحين تعيين مجلس إدارة جديد بالأداة المقررة قانونًا. 9- تحويل وثائقها بما لها من حقوق وما عليها من التزامات لشركة تأمين أخرى. 10- إدماج الشركة فى شركة تأمين أخرى. 11- إلغاء ترخيص الشركة المتعثرة. ) الفصل السابع ( إنهاء النشاط تحويل الوثائق ووقف العمل وإلغاء الترخيص تحويل الوثائق$m208$,'<<CR>>',chr(13))),
('law',155,2024,202,0,'6396b16480c3682b59cb6559da2ca378','378c894b9824eea66c76d05be99a1699',replace($m208$يجب على الشركة إذا رأت تحويل وثائقها مع الحقوق والالتزامات المترتبة عليها عن كل أو بعض العمليات التى تزاولها إلى شركة أخرى أو أكثر تزاول فرعا أو فروع التأمين ذاتها،أن تقدم طلبا إلى الهيئة بالشروط والأوضاع التى يقررها مجلس إدارة الهيئة.<<CR>>
ويقدم طلب التحويل إلى الهيئة مرفقًا به جميع الوثائق والمستندات الخاصة باتفاق التحويل للموافقة عليه من حيث المبدأ،وتتولى الهيئة نشر الطلب على نفقة الشركة فى صحيفة يومية واسعة الانتشار وعلى كل من الموقع الإلكترونى للشركات ذات الصلة وكذا الموقع الإلكترونى للهيئة،وذلك خلال ثلاثين يوما من تاريخ تقديمه على النموذج الذى تعده الهيئة لهذا الغرض وفقًا للإجراءات التى يحددها مجلس إدارة الهيئة. ويجب أن يتضمن هذا الطلب دعوة حملة الوثائق والمستفيدين منها وغيرهم من أصحاب الشأن إلى تقديم ملاحظاتهم على التحويل إلى الهيئة فى ميعاد غايته ثلاثة أشهر من تاريخ النشر،على أن يبين فى الطلب الملاحظات والأسباب التى استند إليها. ويصدر قرار عن مجلس إدارة الهيئة بتحويل وثائق الشركة مع الالتزامات المترتبة عليها،مع مراعاة مصلحة أصحاب الحقوق،وعلى الأخص حملة الوثائق التى أبرمتها الشركة،والمستفيدون منها،والدائنون. وينشر هذا القرار على الموقع الإلكترونى للشركات المعنية وكذا الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض،ويحتج به قبل المؤمن لهم والمستفيدين من الوثائق التى أبرمتها الشركة وكذلك قبل دائنيها. وفى هذه الحالة تنتقل أموال الشركة إلى الشركة التى حولت إليها الوثائق،وذلك مع مراعاة الأحكام المتعلقة بنقل الملكية والنزول عن الأموال. ويسرى حكم هذه المادة على حالتى دمج وتقسيم الشركات. وقف العمل$m208$,'<<CR>>',chr(13))),
('law',155,2024,203,0,'95ee89fe8a24408a505663e97c044e94','608d95917aae701d3fea34811afc1cd1',replace($m208$على كل شركة مرخص لها وفقًا لأحكام هذا القانون إذا قررت وقف عملياتها فى فرع أو أكثر من فروع التأمين وترغب فى تحرير أموالها كلها أو بعضها أن تقدم إلى الهيئة طلبا بذلك،ويكون تقديم هذا الطلب والبت فيه وفقًا للقواعد والإجراءات التى يصدرها مجلس إدارة الهيئة. إلغاء الترخيص$m208$,'<<CR>>',chr(13))),
('law',155,2024,204,0,'b929b02e1937fbb9e7eea75a38909a7d','f11d1d5ba0f9876bae05c5652e43e0c3',replace($m208$يجوز للهيئة إلغاء الترخيص بمزاولة النشاط كليا أو جزئيا فى أى من الأحوال الآتية:<<CR>>
1- إذا كانت الشركة قد تحصلت على الترخيص بصورة تخالف القانون.<<CR>>
2- إذا دأبت الشركة على مخالفة أحكام هذا القانون أو القرارات المنفذة لها. 3- إذا ثبت للهيئة أن الشركة غير قادرة على الوفاء بالتزاماتها. 4- إذا ثبت للهيئة أن الشركة تهمل باستمرار فى تنفيذ المطالبات المستحقة التى تقدم إليها أو تتكرر منها المنازعة دون وجه حق فى مطالبات جدية. 5- إذا نقص رأس المال المدفوع عن الحد الأدنى المقرر فى المادة (162) من هذا القانون ولم تقم الشركة باستكماله رغم مطالبتها بذلك. 6- إذا لم تحتفظ الشركة فى جمهورية مصر العربية بالأموال الواجب تخصيصها طبقًا لحكم المادة (175) من هذا القانون أو إذا لم تقم باستكمالها خلال سنة من تاريخ مطالبتها بذلك. 7- إذا تكرر امتناع الشركة عن تقديم دفاترها ومستنداتها للمراجعة أو الفحص الذى تقوم به الهيئة أو مراقبو الحسابات أو رفضت إعطاء الكشوف والبيانات الواجب تقديمها طبقًا للقانون رغم مطالبتها كتابة أكثر من مرة على مدى ثلاثة أشهر. 8- إذا صدر قرار بالموافقة على تحويل وثائق الشركة مع الالتزامات المترتبة عليها إلى شركة أخرى عن كل العمليات التى زاولتها فى جمهورية مصر العربية طبقًا لحكم المادة (202) من هذا القانون. 9- إذا توقفت الشركة عن مزاولة نشاطها فى جمهورية مصر العربية وحررت أموالها طبقًا للمادة (203) من هذا القانون. 10- إذا صدر حكم بإشهار إفلاس الشركة. 11- إذا خالفت الشركة شرطًا من شروط الترخيص لها بمزاولة النشاط ولم تقم بتصحيح المخالفة على الرغم من مطالبتها بذلك خلال فترة يحددها مجلس إدارة الهيئة. ولا يصدر قرار إلغاء الترخيص بمزاولة النشاط إلا بعد إخطار الشركة بكتاب مسجل مصحوبا بعلم الوصول لتقدم أوجه دفاعها كتابة خلال ثلاثين يوما من تاريخ الإخطار،ويتم إلغاء الترخيص بمزاولة النشاط كليا أو جزئيا بقرار من مجلس إدارة الهيئة وينشر على الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض. ولا ينسحب أثر إلغاء الترخيص بمزاولة النشاط جزئيا إلا إلى العمليات المنصوص عليها فى القرار الصادر به.<<CR>>
وفى جميع الأحوال،لا يجوز للشركة التى صدر فى شأنها قرار إلغاء الترخيص بمزاولة النشاط كليا أن تتصرف فى أموالها والضمانات المقدمة منها إلا بعد اتباع الإجراءات الصادرة عن مجلس إدارة الهيئة نفاذًا لأحكام المادة (203) من هذا القانون، ويترتب على القرار الصادر بإلغاء الترخيص بمزاولة النشاط وقف الشركة عن مباشرة النشاط فى فروع التأمين المنصوص عليها فيه. ويجوز لرئيس مجلس إدارة الهيئة أن يسمح للشركة بمباشرة العمليات القائمة وقت إلغاء الترخيص بمزاولة النشاط بالشروط التى يعينها لذلك،كما يجوز له أن يقرر تصفية أعمال الشركة. وتجرى التصفية طبقا للقواعد التى يقررها مجلس إدارة الهيئة بما يضمن الوفاء بالتزامات الشركة وذلك تحت إشراف لجنة من ثلاثة أعضاء يعينهم رئيس المجلس. ) الفصل الثامن ( أحكام ختامية$m208$,'<<CR>>',chr(13))),
('law',155,2024,206,0,'c8f523abd1c5a62ae60599a16b6f0ad4','aa71a987e444d46b47d57ee3bb0b8380',replace($m208$لا يجوز للأشخاص الطبيعيين والاعتباريين التعاقد على أى عمليات تأمين مباشرة تتعلق بممتلكاتهم أو بمسئولياتهم داخل جمهورية مصر العربية إلا لدى شركات تأمين خاضعة لأحكام هذا القانون. ومع ذلك يجوز للهيئة فى الحالات التى لا يتسنى إبرامها بالداخل،الترخيص بإجراء التأمين لدى غير هذه الشركات،وذلك وفقًا للقواعد التى يضعها مجلس إدارة الهيئة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,208,0,'cb273ea1a140e38b4a969f7856b0d62e','122b4ef56c2d9cf28fad49f6f4b58a1a',replace($m208$تؤدى شركات التأمين وشركات إدارة برامج الرعاية الصحية رسما سنويا للهيئة بما لا يجاوز ثلاثة أمثال الحد الأدنى لرءوس أموالها المنصوص عليها فى هذا القانون، مقابل مراجعة أسس تسعير منتجاتها التأمينية للتأكد من توافقها مع المعايير الفنية والاكتوارية المعمول بها،وجمع وترتيب وتصنيف البيانات والمعلومات وتحليلها وإتاحتها لتنمية النشاط،وفحص ما يرد تجاه الجهات المرخص لها وحملة الوثائق ومستفيدى برامج الرعاية الصحية وفقًا لأحكام هذا القانون. ويحدد مجلس إدارة الهيئة الرسم المشار إليه بما لا يجاوز النسب التالى بيانها من جملة الأقساط المباشرة التى تستحق للشركة على حملة الوثائق عن السنة المالية المنقضية،وذلك على النحو التالى: 1- اثنان ونصف فى الألف بالنسبة لعمليات التأمين المنصوص عليها فى البند أولاً من المادة (2) من هذا القانون. 2- ستة فى الألف بالنسبة لعمليات التأمين المنصوص عليها فى البند ثانيا من المادة (2) من هذا القانون. 3- أربعة فى الألف بالنسبة لشركات التأمين الطبى المتخصصة. 4- اثنان ونصف فى الألف من مقابل إدارة برامج الرعاية الصحية بالنسبة لشركات إدارة الرعاية الصحية وذلك عن جميع تعاقداتها. ويسدد الرسم المشار إليه وفقًا لطرق السداد المقررة قانونًا،ولا يجوز لتلك الجهات اقتضاء هذا الرسم من حملة الوثائق أو من المؤمن لهم أو المشتركين،بحسب الأحوال،بما يجاوز الفئات المشار إليها بتلك المادة. وتلتزم تلك الجهات بسداد هذه الرسوم خلال ثلاثين يوما من تاريخ اعتماد قوائمها المالية أو انقضاء أربعة أشهر من تاريخ انتهاء السنة المالية،وفى حالة التأخير فى السداد تستحق للهيئة غرامة تأخير تحسب على أساس سعر الخصم المعلن من البنك المركزى المصرى فى اليوم التالى لانقضاء الأشهر الأربعة المشار إليها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,209,0,'d8b3d85ed5870ed571c6aa17848977aa','eb3852996f9f568c499c486de6bf2c16',replace($m208$تلتزم الجهات الخاضعة لأحكام هذا القانون بإبلاغ الهيئة بكل ما يصدر من شروط ونماذج وثائق التأمين لكل فروع التأمين،وكذلك كل تعديل يطرأ عليها، ولا يجوز أن يعمل بهذه الشروط والنماذج إلا بعد اعتمادها من الهيئة. كما تلتزم شركات تأمينات الأشخاص وتكوين الأموال بإبلاغ الهيئة بالأسعار والتقرير الاكتوارى والأسس الفنية المستخدمة فى حساباته لمراجعتها،ويعتبر انقضاء ثلاثين يوما على إبلاغ الهيئة،بعد استيفاء جميع المستندات دون ممانعتها بمثابة قرار بالاعتماد. وتقوم الهيئة بمراجعة شروط الوثائق وأسس التسعير المعمول بها لدى جميع الشركات بصفة دورية فى ضوء الممارسات الفعلية بما يضمن توافر الشروط الخاصة بالسعر العادل،وتلتزم الشركات بالتعديلات التى تراها الهيئة فى هذا الشأن.$m208$,'<<CR>>',chr(13))),
('law',155,2024,210,0,'a19299558aea392543e91e74a9e8f23f','6f729513fdee19d16b0a6fcc9ee15c03',replace($m208$لا يجوز نشر أى بيان من البيانات الواجب تقديمها وفقًا لأحكام هذا القانون إلا إذا كانت مطابقة للبيانات التى قدمت للهيئة. ويجوز نشر مستخرجات من هذه البيانات مطابقة تماما لمشتملات البيانات الأصلية المقدمة.$m208$,'<<CR>>',chr(13))),
('law',155,2024,211,0,'c46306964f9f8a190114b57c45472f19','824ccc7c1ff8a71c310f6e62d3622a1a',replace($m208$يجوز للهيئة السماح لكل ذى مصلحة بالاطلاع على الأوراق والبيانات التى تقدم طبقًا للقانون،أو الحصول على صور أو شهادات أو مستخرجات منها أو من القرارات الصادرة من الهيئة أو من السجلات المنصوص عليها فى هذا القانون عدا الأسس الفنية لأسعار عمليات التأمين،وذلك بعد سداد الرسم المقرر. ويجب على شركات التأمين أن تطلع حاملى وثائقها على البيانات المتعلقة بوثائقهم أو أن تسلمهم نسخة منها،بناء على طلبهم،وذلك بعد سداد الرسم المقرر. ويحدد الجدول المرفق بهذا القانون قيمة الرسوم التى تؤدى طبقًا لهذه المادة، وتسدد وفقًا لطرق السداد المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',155,2024,213,0,'ed1888a602a6cf46d9e8b5b4f7f3f3c7','ee969e27452981657b49b943beaa5f04',replace($m208$يعتبر جميع الأشخاص الطبيعيين والاعتباريين المسجلين بالسجلات المعدة بالهيئة وفقًا للقوانين القائمة وقت العمل بهذا القانون مرخصا لهم فى مزاولة العمل طبقًا لأحكام هذا القانون،وذلك فى كل ما لم يرد به أحكام خاصة يتعين الالتزام بها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,214,0,'3154baa4b220478c6f75660bee3014fa','050b805d4b7dd4bf82b0f4f8fdb1b853',replace($m208$تشكل لجنة أو أكثر لنظر التظلمات التى يقدمها أصحاب الشأن من القرارات الإدارية الصادرة تطبيقًا لأحكام هذا القانون،ويصدر بتشكيل كل لجنة قرار من مجلس إدارة الهيئة،وتكون برئاسة أحد نواب رئيس مجلس الدولة وعضوية اثنين من مستشارى مجلس الدولة يختارهما رئيس المجلس،وممثل عن الهيئة يختاره رئيسها،وعضو من ذوى الخبرة يختاره مجلس إدارة الهيئة،ويكون للمتظلم الحضور أمام اللجنة بنفسه أو من يمثله. ويكون التظلم من القرار أمام هذه اللجنة خلال ثلاثين يوما من تاريخ صدور القرار أو انتهاء الأجل الخاص بصدوره،على أن تصدر اللجنة قرارها فى التظلم فى ميعاد لا يجاوز ثلاثين يوما من تاريخ استيفاء المستندات والبيانات المطلوبة، ويكون قرارها نهائيا ونافذًا وملزما لأطرافه. ولا تقبل الدعوى التى ترفع إلى المحكمة المختصة إلا بعد اللجوء إلى اللجنة المشار إليها والبت فى التظلم.<<CR>>
ويترتب على تقديم التظلم إلى اللجنة وقف المدد المقررة قانونًا لسقوط أو تقادم الحقوق أو لرفع الدعوى،وذلك حتى انقضاء ميعاد البت فى التظلم. ويشمل قرار تشكيل اللجنة اختصاصاتها ومكافآت أعضائها وإجراءات النظر فى التظلم والبت فيه ومواعيد تلك الإجراءات. ويلتزم المتظلم بسداد رسم للتظلم يصدر بتحديد ضوابطه قرار من رئيس مجلس إدارة الهيئة بما لا يجاوز مبلغ عشرين ألف جنيه،ويرد هذا الرسم إلى المتظلم حال إلغاء القرار خلال ثلاثين يوما على الأكثر من تاريخ صدور الإلغاء. ) الفصل الثاني ( العقوبات$m208$,'<<CR>>',chr(13))),
('law',155,2024,215,0,'f845ffd0ad6107e9e439a12bd4a5311d','0943baede96e642b06661926d2b70a9c',replace($m208$مع عدم الإخلال بأى عقوبة أشد منصوص عليها فى أى قانون آخر،يعاقب بالحبس وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على خمسمائة ألف جنيه أو ما حققه المخالف من نفع مؤثم أيهما أكبر،أو بإحدى هاتين العقوبتين: 1- كل من زاول نشاطًا من أنشطة التأمين أو إعادة التأمين أو أيا من المهن أو الأنشطة المرتبطة بها بغير ترخيص من الهيئة أو القيد فى السجل المعد لذلك أو بالمخالفة لأحكام هذا القانون. 2- كل من باشر عملاً من أعمال الصناديق التأمينية الخاصة قبل تسجيله بالسجل المعد لذلك بالهيئة أو بعد شطبه من السجل. 3- كل من أقر أو أخفى متعمدا بقصد الغش فى البيانات أو المحاضر أو فى المستندات التى تقدم إلى الهيئة أو التى تصل إلى علم الجمهور. 4- كل من تعمد مخالفة المعايير أو القواعد المهنية الصادرة عن مجلس إدارة الهيئة،ومن بينها معايير الخبرة الاكتوارية. 5- كل مسئول بشركة تأمين أو إعادة تأمين تعمد عدم تنفيذ الالتزامات الواردة بوثائق التأمين. وفى جميع الأحوال،تضبط المبالغ محل الجريمة ويحكم بمصادرتها،فإن لم تضبط حكم بغرامة إضافية تعادل قيمتها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,216,0,'1621f7ab705bdd033a9e39472a253ce2','a4cfe56397bd2cf781dbf8c52f09f2f6',replace($m208$يعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه كل من: 1- تعمد عرقلة أعمال موظفى الهيئة فى الإشراف والرقابة. 2- مثل فى جمهورية مصر العربية هيئات أو شركات تأمين أو إعادة تأمين مصرية أو أجنبية أو توسط لديها دون ترخيص بذلك من الهيئة. 3- امتنع عن تقديم السجلات والمستندات لمندوبى الهيئة الذين لهم حق الاطلاع عليها.<<CR>>
4- تأخر دون مبرر تقبله الهيئة فى تقديم البيانات أو التقارير الواجب تقديمها فى المواعيد المحددة بهذا القانون أو القرارات الصادرة عن الهيئة تنفيذًا له. ويحكم فى البندين (3، 4) من هذه المادة فضلاً عن الغرامة،بإلزام المحكوم عليه بتقديم السجلات أو المستندات أو البيانات. وفى حالة العود،يعاقب على مخالفة البنود السابقة بالحبس مدة لا تقل عن ثلاثة أشهر وتضاعف الغرامة بحديها الأدنى والأقصى المنصوص عليها فى الفقرة الأولى من هذه المادة،أو بإحدى هاتين العقوبتين.$m208$,'<<CR>>',chr(13))),
('law',155,2024,217,0,'d0ca635c158827c61f4853b5dc6b9e86','101052dc54d29924d0bc38ad15fc4ba6',replace($m208$يعاقب بغرامة لا تقل عن مليون جنيه ولا تزيد على مليونى جنيه أو ما حققه المخالف من نفع مؤثم أيهما أكبر كل من أفشى سرا اتصل به أو اطلع عليه بحكم عمله تطبيقًا لأحكام هذا القانون. ويعاقب بذات العقوبة: 1- كل عضو من أعضاء مجلس إدارة أحد الصناديق الخاصة أو المديرين أو الموظفين بها امتنع دون وجه حق عن تسليم الأموال والمستندات والسجلات إلى السلطة المختصة بذلك. 2- كل عضو من أعضاء مجلس إدارة أحد الصناديق الخاصة امتنع،دون وجه حق،عن صرف الالتزامات المستحقة للأعضاء أو المستفيدين وفقًا لأحكام النظام الأساسى للصندوق أو إذا حصل لنفسه أو لأى من الأعضاء على مزية أو مكافأة من الصندوق بالمخالفة لأحكام النظام الأساسى،وتقضى المحكمة برد قيمة ما حصل عليه من الصندوق. 3- كل من خالف أحكام المادتين ) / 101، 90 فقرة ثالثة( من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,218,0,'c8e047c5fbf516d8aa12711d3c524393','e3c793bc53315c4b631579f834a3808b',replace($m208$يعاقب كل من يخالف الشروط أو النماذج المعتمدة من الهيئة وفقًا لأحكام المادة (209) من هذا القانون،وكذا كل من يخالف الأسعار فى حالة تأمينات الأشخاص،بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز عشرين مليون جنيه أو ما حققه من نفع مؤثم، أيهما أكبر،للواقعة موضوع المخالفة. وتضاعف العقوبة بحديها فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',155,2024,219,0,'d6a5ffba8e750fe4914a051bea85cefd','f58294454773e4b9053ca9042b5a7e85',replace($m208$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر،يعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مليون جنيه كل من خالف أحكام المواد ) /46، 43 فقرة أخيرة (147، 139، 49، 47،من هذا القانون. ويعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على خمسين ألف جنيه كل من خالف حكم المادة (42) من هذا القانون. كما يعاقب بغرامة لا تقل عن ألف جنيه ولا تزيد على خمسة آلاف جنيه كل من خالف حكم المادة (51) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',155,2024,220,0,'c690483827dc3d2571ff1aa2098d5899','55cf460cd7f3e5f1c42bae7d9d7e7c63',replace($m208$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر يعاقب بالحبس مدة لا تقل عن سنتين وبغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مليون جنيه أو ضعف ما حققه من نفع،أو بإحدى هاتين العقوبتين،كل من حقق نفعا لنفسه أو زوجه أو أولاده نتيجة لإثباته فى تقاريره وقائع غير صحيحة عن عمد، أو أخل بقواعد ومعايير الممارسة المهنية إخلالاً متعمدا أو جسيما،أو تعمد إغفال وقائع تؤثر تأثيرا جوهريا فى نتائج هذه التقارير. وتكون العقوبة الحبس والغرامة التى لا تقل عن عشرة آلاف جنيه ولا تزيد على خمسمائة ألف جنيه أو ضعف ما حققه من نفع،أو بإحدى هاتين العقوبتين إذا ارتكبت الأفعال المنصوص عليها بالفقرة الأولى من هذه المادة بناء على إهمال.$m208$,'<<CR>>',chr(13))),
('law',155,2024,221,0,'e55f9110ae5b6afd5530e1c6c24cbb42','f7315016156bdca1a3010bc352b6ceb5',replace($m208$يعاقب بغرامة قدرها ألفا جنيه عن كل يوم من أيام تأخير شركة التأمين فى تسليم القوائم المالية وفقًا للقواعد الواردة بهذا القانون وما يصدر عن الهيئة من قرارات بشأنها. كما يعاقب بغرامة خمسمائة جنيه عن كل يوم من أيام تأخير صناديق التأمين الخاصة أو غيرها من الجهات الخاضعة لأحكام هذا القانون فى تسليم القوائم المالية وفقًا للقواعد الواردة بهذا القانون وما يصدر عن الهيئة من قرارات بشأنها.$m208$,'<<CR>>',chr(13))),
('law',155,2024,222,0,'9adb6af60d7f0c768017b2d57041418a','fffe83d0e4476fdac64674661cd6369f',replace($m208$يعاقب المسئول عن الإدارة الفعلية للشركة،بالعقوبات المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون،متى ثبت علمه بها وكانت المخالفة قد وقعت بسبب إخلاله بواجباته الوظيفية. ويكون الشخص الاعتبارى مسئولاً بالتضامن معه عن الوفاء بما يحكم به من عقوبات مالية وتعويضات إذا كانت الجريمة قد ارتكبت من أحد العاملين به باسمه نيابة عنه.$m208$,'<<CR>>',chr(13))),
('law',155,2024,223,0,'f7cd76e8b1b2782311154a15f544b673','298979a70e41013dc1c6b24c659dfb9e',replace($m208$يجوز فضلاً عن العقوبات المقررة للجرائم المنصوص عليها فى المواد السابقة، الحكم على من قضى عليه بإحدى هذه العقوبات،بالحرمان من مزاولة النشاط الذى وقعت الجريمة بمناسبته،وذلك لمدة لا تزيد على ثلاث سنوات،ويكون الحكم بذلك وجوبيا فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',155,2024,224,0,'16038f71b38207be156ed9cf233e08f4','a265dcbf246bf3186c25b32b13a7226a',replace($m208$تسرى أحكام المادة السادسة عشرة من قانون تنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية رقم 10 لسنة 2009 على الجرائم التى ترتكب بالمخالفة لأحكام هذا القانون والقرارات الصادرة نفاذًا له.<<CR>>
جدول الرسوم الملحق بالقانون الرسم الإجراءات المقرر جنيه - 1 يحصل مبلغ 100 جنيه من المؤمن لهم نظير اطلاعهم على بيانات وثائقهم، أو حصولهم على نسخة إضافية منها بناء على طلبهم. 2- تكون رسوم الاطلاع واستخراج الصور أو الشهادات أو المستخرجات بالهيئة كما يلى: ) أ ( الاطلاع على الأوراق والبيانات: 50 عن كل شركة من الشركات الخاضعة للقانون أو اتحاد............................... )ب( طلب صورة أو شهادات أو مستخرجات من الأوراق والبيانات الواجب تقديمها طبقًا للقانون أو من القرارات الصادرة تنفيذًا له عن الصفحة الواحدة.................. )ج( طلب شهادات أو مستخرجات من السجلات المنصوص عليها فى القانون: عن كل شركة من الشركات الخاضعة للقانون....................................... عن كل خبير أو وسيط من الخبراء أو الوسطاء المنصوص عليهم فى المواد )، 60 (71، 67، 64 من هذا القانون،وذلك بالنسبة لكل شهادة أو مستخرج............. 50 - 3 طلب الترخيص بإجراء السحب بالنسبة لعمليات التأمين على الحياة وتكوين الأموال.<<CR>>
4- النشر على الموقع الإلكترونى الذى تحدده الهيئة: 150 ) أ ( قرار تسجيل شركة التأمين. )ب( قرار تعديل بيانات التسجيل. )ج( القرار الصادر بتحويل وثائق الشركة والتزاماتها إلى شركة أخرى. )د ( ما يحدده مجلس إدارة الهيئة من قرارات أخرى واجبة النشر.<<CR>>
ولمجلس إدارة الهيئة تعديل الرسوم المقررة فى هذا الجدول بما لا يجاوز عشر أمثالها.<<CR>>
طبعت بالهيئة العامة لشئون المطابع الأميرية رئيس مجلس الإدارة   رقم الإيداع بدار الكتب 65 لسنة 2024 559 - 2024/7/15 - 2024/25032$m208$,'<<CR>>',chr(13))),
('law',14,2025,1,0,'ff515785f8bc881f4215dfb2422d6780','3b43ee02bbf18825c14d35bbea865c6b',replace($m208$يقصد فى تطبيق أحكام هذا القانون بالكلمات والمصطلحات الآتية المعانى المبينة قرين كل منها:<<CR>>
1- العامل:كل شخص طبيعى يعمل لقاء أجر لدى صاحب عمل تحت إدارته أو إشرافه.<<CR>>
2- المتدرج:كل من التحق لدى صاحب عمل بقصد تعلم مهنة أو صنعة أو حرفة لقاء أجر.<<CR>>
3- صاحب العمل:كل شخص طبيعى أو اعتبارى يستخدم عاملاً أو أكثر لقاء أجر.<<CR>>
4- الأجر:كل ما يحصل عليه العامل لقاء عمله نقدا كان أو عينًا، ويشمل الآتى: الأجر الأساسى:الأجر المنصوص عليه فى عقد العمل،وما يطرأ عليه من علاوات. الأجر المتغير:باقى ما يحصل عليه العامل من عناصر الأجر،وعلى الأخص: ) أ( العمولة أو النسبة المئوية:مبلغ من المال يدفع للعامل مقابل ما يقوم بإنتاجه،أو بيعه،أو تحصيله طوال قيامه بالعمل المقرر له هذه النسبة. )ب( العلاوات:مبلغ مالى أو نسبة من الأجر الأساسى تُمنح للعامل لمواجهة ظروف اقتصادية أو اجتماعية أو فنية ما لم تضم إلى الأجر الأساسى. )ج( المنح:ما يعطى للعامل زيادة على أجره،متى كانت مقررة فى عقود العمل الفردية،أو الجماعية،أو الأنظمة الأساسية للعمل،أو ما جرت العادة بمنحه.<<CR>>
)د( المكافأة:كل ما يصرف للعامل نقدا كان أو عينًا نظير إجادة،أو تميز، أو كفاءة فى أداء العمل المكلف به. )ه( البدلات:ما يعطى للعامل لقاء ظروف أو مخاطر معينة،يتعرض لها فى أداء عمله. )و( نصيب العامل فى الأرباح:ما يصرف للعامل من صافى الأرباح المحققة وفقًا للقوانين المنظمة لها. )ز( الوهبة:المقابل الذى يحصل عليه العامل من غير صاحب العمل إذا جرت العادة بدفعها،وكانت لها قواعد تسمح بتحديدها وفقًا للائحة المنشأة أو العرف السائد. )ح( مقابل الخدمة:المقابل النقدى الذى قد يدفعه العملاء فى المنشآت السياحية والفندقية،وغيرها من المنشآت الأخرى،ويصدر قرار من الوزير المختص بالاتفاق مع الوزراء المعنيين والمنظمة النقابية المعنية ومنظمات أصحاب الأعمال بكيفية توزيعها على العاملين. )ط( المزايا العينية:ما يلتزم به صاحب العمل من مزايا غير نقدية لا تستلزمها مقتضيات العمل.<<CR>>
5- الأجر التأمينى:أجر الاشتراك الوارد بقانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم 148 لسنة 2019<<CR>>
6- العمل المؤقت:العمل الذى يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط وتقتضى طبيعة إنجازه مدة محددة،أو ينصب على عمل بذاته، وينتهى بانتهائه.<<CR>>
7- العمل العرضى:العمل الذى لا يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط ولا يستغرق إنجازه أكثر من ستة أشهر.<<CR>>
8- العمل الموسمى:العمل الذى يتم فى مواسم دورية متعارف عليها.<<CR>>
9- العامل غير المنتظم:كل من يقوم بأداء عمل غير دائم بطبيعته مقابل أجر أيا كانت صورته،أو يعمل فى مهنة أو حرفة لا ينظمها قانون خاص،مثل الباعة الجائلين،وموزعى الصحف،وغيرهم.<<CR>>
10- العامل فى القطاع غير الرسمى:كل من يقوم بأداء عمل داخل المنشأة أو خارجها بشكل غير رسمى أو مستتر. 11- السخرة:كل عمل أو خدمة تفرض عنوة على أى شخص تحت التهديد بإنزال عقوبة أو إيذاء،ولم يتطوع هذا الشخص بأدائها بمحض اختياره.<<CR>>
12- الليل:الفترة ما بين غروب الشمس وشروقها.<<CR>>
13- التوجيه المهنى:مساعدة الفرد فى اختيار المهنة أو المسار المهنى الأكثر ملاءمة لقدراته واستعداده وميوله فى ضوء الدراسات المستمرة لسوق العمل والمهن المطلوبة ومقوماتها.<<CR>>
14- التدريب:عملية تُمكن الفرد من اكتساب وتنمية المعارف والمهارات الفنية وسلوكيات المهنة اللازمة لإعداده للعمل المناسب.<<CR>>
15- التلمذة الصناعية:شكل من أشكال التعلم أو تنمية المهارات داخل العمل أو خارجه،يمكن الفرد من اكتساب المهارات والمعارف والجدارات اللازمة للعمل فى مهنة أو صنعة أو حرفة من خلال تدريب منظم مقابل أجر.<<CR>>
16- مجالس المهارات القطاعية:كيانات قطاعية تعزز التعاون بين الحكومة والقطاع الخاص تنشأ لضمان استيفاء منظومة التعليم الفنى والتقنى والتدريب المهنى لاحتياجات القطاع الاقتصادى من العمالة الفنية الماهرة.<<CR>>
17- وكالات التشغيل الخاصة:شركات متخصصة فى اختيار العمال، أو تشغيلهم لدى الغير بالشروط التى أوجبها هذا القانون.<<CR>>
18- الوكلاء المفوضون:كل شخص أنابه أو فوضه صاحب العمل فى إدارة المنشأة،أو شاغلو الوظائف الرئيسية العليا بها الذين يمارسون بعض أو كل سلطات صاحب العمل.<<CR>>
19- المفاوضة الجماعية:الحوار الذى يجرى بين صاحب عمل أو منظمة أصحاب أعمال أو أكثر من جهة،وبين منظمة نقابية عمالية،أو أكثر من جهة أخرى بغرض التوافق لتحقيق مصالح الطرفين.<<CR>>
20- المنازعة الجماعية:كل نزاع ينشأ بين صاحب عمل أو مجموعة أصحاب أعمال أو منظماتهم،وبين جميع عمال المنشأة أو فريق منهم أو منظماتهم النقابية المعنية بشأن شروط العمل أو ظروفه أو التشغيل.<<CR>>
21- الشركاء الاجتماعيون:أطراف العملية الإنتاجية )الحكومة،ومنظمات أصحاب الأعمال،والمنظمات النقابية العمالية(.<<CR>>
22- المفوض العمالى:أحد العاملين بالمنشأة يتفق العاملون بها على تفويضه بموجب سند رسمى لتمثيلهم أمام صاحب العمل فى حالة عدم وجود منظمة نقابية عمالية بها.<<CR>>
23- اتفاقية العمل الجماعية:اتفاق مكتوب ينظم شروط وظروف العمل وأحكام التشغيل،ويبرم بين منظمة أو أكثر من المنظمات النقابية العمالية وبين صاحب عمل أو مجموعة من أصحاب الأعمال أو منظمة أو أكثر من منظماتهم.<<CR>>
24- التوفيق:وسيلة يلجأ إليها أحد طرفى منازعة العمل الجماعية طالبا تدخل الجهة الإدارية المختصة بعد تعثر المفاوضة الجماعية بينهما.<<CR>>
25- الوساطة:وسيلة ودية لفض منازعات العمل الجماعية،يتفق بموجبها طرفا النزاع على إسناد مهمة اقتراح التسوية إلى شخص ثالث حيادى يدعى )وسيط النزاع(،يشتركان فى اختياره من القائمة المعدة لذلك.<<CR>>
26- التحكيم:وسيلة اتفاقية لإنهاء النزاع الجماعى القائم بعد فشل وسائل التسوية الودية ويتولى القيام به محكم أو أكثر يتم اختيارهم من القائمة المعدة لذلك.<<CR>>
27- شرط التحكيم:اتفاق مكتوب بين طرفى علاقة العمل على تسوية ما قد ينشأ بينهما من نزاع بشأن هذه العلاقة بواسطة التحكيم.<<CR>>
28- مشارطة التحكيم:اتفاق مكتوب بين طرفى علاقة العمل بعد نشوء النزاع.<<CR>>
29- الإضراب عن العمل:اتفاق جميع العمال أو فريق منهم على التوقف عن أداء أعمالهم بمقر العمل للمطالبة بما يرونه محققًا لمصالحهم المهنية والاقتصادية والاجتماعية،بعد تعذر التسوية الودية،فى حدود الضوابط والإجراءات المقررة قانونًا.<<CR>>
30- إصابة العمل والأمراض المزمنة:التعريفات الواردة لها فى قانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم 148 لسنة 2019<<CR>>
31- التحرش:كل فعل أو سلوك فى مكان العمل أو بمناسبته يشكل تعرضا للغير بإتيان أمور أو إيحاءات أو تلميحات جنسية أو إباحية سواء بالإشارة أو بالقول أو بالفعل بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية أو اللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.<<CR>>
32- التنمر:كل فعل أو سلوك فى مكان العمل أو بمناسبته سواء بالقول أو باستعراض القوة أو السيطرة على الغير أو استغلال ضعفه أو لحالة يعتقد مرتكب ذلك الفعل أو السلوك أنها تسيء للغير كالجنس أو العرق أو الدين أو الأوصاف البدنية أو الحالة الصحية أو العقلية أو المستوى الاجتماعى بقصد تخويفه أو وضعه موضع السخرية أو الحط من شأنه أو إقصائه من محيطه الاجتماعى.بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية واللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.<<CR>>
33- المنشأة:كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون الخاص أيا كان نوعها أو تبعيتها،وذلك مع مراعاة ما نصت عليه المادة (243) من هذا القانون.<<CR>>
34- موقع العمل:هو المكان الذى يمارس فيه العامل العمل المكلف به، أو يحتمل تواجده فيه بسببه.<<CR>>
35- المهنة أو الحرفة:كل عمل يتطلب أداؤه مهارة خاصة أو خبرة محددة، ولا ينظم مزاولته قانون خاص.<<CR>>
36- الوزير المختص:الوزير المعنى بشئون العمل.<<CR>>
37- الوزارة المختصة:الوزارة المعنية بشئون العمل.<<CR>>
38- الجهة الإدارية المختصة:الوزارة المعنية بشئون العمل ومديرياتها وإداراتها التابعة لها على مستوى الجمهورية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,2,0,'2b20a3753d46e07cc1b79df9dc977f99','85052cefa4c7b34a7bbcdd4ea0710fd6',replace($m208$فى تطبيق أحكام هذا القانون تعتبر السنة (365) يوما،والشهر ثلاثون يوما ما لم يتم الاتفاق على خلاف ذلك.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,3,0,'f16f5de45eb5b895e124a44a2da3b8fb','4e9bfba2689529a686257148428fb600',replace($m208$يعتبر هذا القانون هو القانون العام الذى يحكم علاقات العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,4,0,'ad82085b270ed7a556d890dcd4b9e516','b4d34df674e2a04a7617c4d6391aef68',replace($m208$يحظر تشغيل العامل سخرة أو جبرا،كما يحظر التحرش أو التنمر أو ممارسة أى عنف لفظى أو جسدى أو نفسى على العامل،وتحدد لائحة تنظيم العمل والجزاءات بالمنشأة الجزاءات التأديبية المقررة لها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,5,0,'14568d92e13f0b7da7ff563bf3745a8e','d0f5d7c915c44cdb9a5a9bb29acde26d',replace($m208$يحظر كل عمل أو سلوك أو إجراء يكون من شأنه إحداث تمييز أو تفرقة بين الأشخاص فى التدريب،أو الإعلان عن الوظائف أو شغلها،أو شروط أو ظروف العمل أو الحقوق والواجبات الناشئة عن عقد العمل،بسبب الدين أو العقيدة أو الجنس أو الأصل أو العرق أو اللون أو اللغة أو الإعاقة أو المستوى الاجتماعى أو الانتماء السياسى أو النقابى أو الجغرافى أو أى سبب آخر يترتب عليه الإخلال بمبدأ المساواة وتكافؤ الفرص.<<CR>>
ولا يعتبر تمييزا محظورا كل ميزة أو أفضلية أو منفعة أو حماية تقرر بموجب أحكام هذا القانون والقرارات واللوائح المنفذة له للمرأة أو للطفل أو للأشخاص ذوى الإعاقة والأقزام،كلما كانت مقررة بالقدر اللازم لتحقيق الهدف الذى تقررت من أجله، وتعمل الوزارة المختصة على وضع السياسات والخطط اللازمة لدمجهم فى سوق العمل وتوفير الحماية اللازمة لهم فى بيئة العمل وذلك بالتنسيق مع الوزارة المختصة بالتضامن الاجتماعى والمجالس القومية المتخصصة المعنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,6,0,'2db3029682df2cee8c87116396eab171','06ba3f51cb46fa67412e1b6956d239c7',replace($m208$يقع باطلاً كل شرط أو اتفاق يخالف أحكام هذا القانون،ولو كان سابقًا على العمل به،إذا تضمن انتقاصا من حقوق العامل المقررة فيه،أو إبراء من حقوق العامل الناشئة عن عقد العمل خلال مدة سريانه،أو خلال ثلاثة أشهر من تاريخ انتهائه. ويستمر العمل بأية مزايا أو شروط أفضل تكون مقررة،أو تقرر فى عقود العمل الفردية،أو الجماعية أو الأنظمة الأساسية،أو غيرها من لوائح المنشأة، أو بمقتضى العرف. كما يسرى ذلك فى حالة تغيير الكيان القانونى للمنشأة،أو انتقال ملكيتها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,7,0,'a4b4bb3a7b17db4533edc1ea5f278218','76e1c220606d6e88e69cea48a3782311',replace($m208$تعفى من الرسوم والمصاريف القضائية فى جميع مراحل التقاضى الدعاوى الناشئة عن المنازعات المتعلقة بأحكام هذا القانون،التى يرفعها العاملون والمتدرجون، وعمال التلمذة الصناعية،أو المستحقون عن هؤلاء،وللمحكمة فى جميع الأحوال أن تشمل حكمها بالنفاذ المعجل وبلا كفالة،ولها فى حالة رفض الدعوى أن تحكم على رافعها بالمصروفات كلها أو بعضها. وتعفى الفئات المشار إليها فى الفقرة الأولى من هذه المادة من ضريبة الدمغة على كل الشهادات والصور التى تعطى لهم،والشكاوى،والطلبات التى تقدم منهم، تطبيقًا لأحكام هذا القانون.<<CR>>
ومع مراعاة حكم المادة (185) من هذا القانون لا يشترط بالنسبة لتلك الفئات توقيع محام على صحيفة افتتاح الدعوى،أو صحيفة الطلبات الموضوعية أو طلبات استصدار الأوامر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,8,0,'6f1a14b27d0c04be7f013bff5acc5e5b','147f8c6f2c4f0984e9d4ff04d5976984',replace($m208$يكون للمبالغ المستحقة للعامل،أو المستحقين عنه،والناشئة عن علاقة عمل امتياز على جميع أموال المدين من منقول وعقار،وتستوفى هذه المبالغ قبل المصروفات القضائية،والمبالغ المستحقة للخزانة العامة،ومصروفات الحفظ والترميم وأية مرتبة امتياز مقررة أو تقرر وفقًا لأى قانون آخر. وتعتبر اشتراكات التأمين الاجتماعى جزءا من حقوق العمال التى تستوفى وتؤدى للهيئة المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,9,0,'0b272646eabb423c5c873a11b2c40e89','9cc2b3366a93723d331088cf645c3651',replace($m208$لا يمنع من الوفاء بجميع الالتزامات الناشئة طبقًا لهذا القانون،حل المنشأة، أو تصفيتها،أو إغلاقها،أو إفلاسها. ويجب أن يحدد القرار أو الحكم الصادر بأى من ذلك،أجلاً للوفاء بحقوق العاملين،وتتولى الجهة الإدارية المختصة متابعة الوفاء بتلك الحقوق،ويكون لها أن تنوب عن ذوى الشأن فى اتخاذ الإجراءات اللازمة للوفاء بها فى الأجل المحدد. ويصدر الوزير المختص قرارا بتحديد ضوابط وإجراءات ومواعيد الوفاء بحقوق العمال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,11,0,'4146f2c933e68475c2e51661bb20889e','7ff0a73b46789e83cc7c6a1b324c2366',replace($m208$لا يترتب على إدماج المنشأة،أو تقسيمها،أو انتقالها بالإرث أو الوصية أو الهبة أو البيع ولو كان بالمزاد العلني،أو النزول،أو الإيجار،أو غير ذلك من التصرفات إنهاء عقود استخدام عمال المنشأة،ويكون الخلف مسئولاً بالتضامن مع أصحاب الأعمال السابقين عن تنفيذ جميع الالتزامات الناشئة عن هذه العقود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,12,0,'da2ee629047f655fcd3ed63d6c80adeb','4fa19f7a57a96f535468df7b398c6ced',replace($m208$يستحق العاملون الذين تسرى فى شأنهم أحكام هذا القانون علاوة سنوية دورية فى تاريخ استحقاقها لا تقل عن ) (%3 من الأجر التأميني،وتستحق تلك العلاوة بانقضاء سنة من تاريخ التعيين،أو من تاريخ استحقاق العلاوة الدورية السابقة. وفى حالة تعرض المنشأة لظروف اقتصادية يتعذر معها صرف العلاوة الدورية المشار إليها،يعرض الأمر على المجلس القومى للأجور للبت فى تخفيضها أو الإعفاء منها وذلك خلال ثلاثين يوما من تاريخ عرض الأمر عليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,13,0,'c3149102d52175648e67aaddd43a680a','0a82b9896cc1271aeb519279f33d6760',replace($m208$يصدر الوزير المختص قرارا بتحديد اختصاص الجهة الإدارية المختصة فى تطبيق أحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,15,0,'e1b387b85f456392aa3f9ec9c87195d6','d53a3bbb2f76363a131e321d6f19b1ed',replace($m208$يكون تحصيل الرسوم ومقابل الخدمات المنصوص عليها فى هذا القانون،وفقًا لأحكام قانون تنظيم استخدام وسائل الدفع غير النقدى الصادر بالقانون رقم 18 لسنة 2019$m208$,'<<CR>>',chr(13))),
('law',14,2025,16,0,'2f9d6f7ec44d797e3c05b4b94eda6d18','89c73efe0a46b05e3c9cac94b796c556',replace($m208$تسرى أحكام هذا الباب على جميع مراكز التدريب الخاضعة لأحكام هذا القانون، وعلى الفئات الآتية:<<CR>>
1- الراغبين فى التدريب.<<CR>>
2- الأشخاص ذوو الإعاقة والأقزام،والفئات الأولى بالرعاية.<<CR>>
3- المتدرجين.<<CR>>
4- الراغبين فى التأهيل الأعلى أو المستمر.<<CR>>
5- عمال التلمذة الصناعية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,17,0,'f207e7ca2dc3cb26d1af7dac39f31b9f','0a3b4eb407a5466b3b3dcd78876f7069',replace($m208$تتولى الجهة الإدارية المختصة القيام بالتوجيه المهنى لراغبى التدريب لمساعدتهم فى اختيار المهن التى يرغبون التدرب عليها وفقًا لقدراتهم. كما تتولى بالتنسيق مع الوزارات والجهات المعنية،وبالتشاور مع ممثلى منظمات أصحاب الأعمال والعمال الأكثر تمثيلاً،إعداد التصنيف المهنى الوطنى للمهن والحرف والوظائف فى سوق العمل،وتحديد متطلباتها وتوصيفها،والمهارات والجدارات اللازمة لها،والعمل على تحديثها وفقًا لمعايير الجودة العالمية،وبما يتوافق مع التغيرات التكنولوجية الحديثة وتغير المناخ. ويصدر الوزير المختص قرارا بالقواعد والإجراءات المنظمة لذلك،والجهات والفئات المستفيدة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,18,0,'7f7fd6e629e8402a624200ffb283f5f0','f64fbe54825fd678355fea064b9c2f3a',replace($m208$ينشأ مجلس يسمى "المجلس الأعلى لتنمية مهارات الموارد البشرية "،ويكون مقره الرئيسى مدينة القاهرة،برئاسة الوزير المختص،ويضم فى عضويته ما يلى: ممثلين عن وزارات ) الصحة،التخطيط والتنمية الاقتصادية والتعاون الدولى، التربية والتعليم والتعليم الفنى التعليم العالى والبحث العلمى،الصناعة،الاستثمار والتجارة الخارجية،الاتصالات وتكنولوجيا المعلومات،التضامن الاجتماعى،قطاع الأعمال العام،التنمية المحلية،الإسكان والمرافق والمجتمعات العمرانية،السياحة والآثار (،يرشحهم الوزراء المعنيون. رئيس الجهاز المركزى للتنظيم والإدارة أو من ينيبه. رئيس المجلس القومى للأشخاص ذوى الإعاقة أو من ينيبه. سبعة أعضاء يمثلون منظمات أصحاب الأعمال الأكثر تمثيلاً من حيث العضوية، ترشحهم منظماتهم. سبعة أعضاء يمثلون المنظمات النقابية العمالية،ترشحهم منظماتهم الأكثر تمثيلاً للعمال.على أن يراعى عند الترشيح تمثيل جميع مستويات المنظمات النقابية العمالية ما لم يكن ذلك متعذرا. وللمجلس أن يستعين بمن يراه من ذوى الخبرة من الفئات التى يرى لزوما تمثيلها،دون أن يكون لهم صوت معدود فى المداولات. ويتولى المجلس وضع السياسات العامة لتنمية مهارات الموارد البشرية، وسياسات التدريب والتأهيل،وسياسات تدريب وتأهيل الأشخاص ذوى الإعاقة والأقزام والفئات الأولى بالرعاية بما يتفق مع السياسة العامة للدولة. كما يتولى وضع الخطط اللازمة لربط التعليم والتدريب باحتياجات سوق العمل الحالى ووظائف المستقبل،والمهارات اللازمة لها. ويصدر بتشكيل المجلس واختصاصاته الأخرى ونظام العمل به وأمانته التنفيذية قرار من رئيس مجلس الوزراء،فى موعد لا يتجاوز ستة أشهر من تاريخ العمل بهذا القانون،على أن يجتمع المجلس مرة على الأقل كل ثلاثة أشهر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,19,0,'d1a221e9b940c5b46aa6734fd661e4b6','0b2bf5853ee2efad2b845eb3272b0311',replace($m208$يجوز للمجلس أن يشكل فى نطاق أى محافظة أو منطقة جغرافية مجلسا تنفيذيا لتنمية مهارات الموارد البشرية،ويحدد بقرار من المجلس رئيس وأعضاء المجلس التنفيذى،على أن يضم فى عضويته ممثلين عن منظمات أصحاب العمل والمنظمات النقابية العمالية المعنية بالتساوى فيما بينهما،كما يضم فى عضويته ممثلى الوزارات والجهات المعنية،ويتولى متابعة تنفيذ الخطط والقرارات،والتوصيات الصادرة عن المجلس الأعلى لتنمية مهارات الموارد البشرية والتنسيق مع الجهات المحلية المختصة بتنمية مهارات الموارد البشرية وتحسين كفاءتها من خلال التدريب المهنى والتدريب المستمر. ويحدد قرار التشكيل الاختصاصات الأخرى للمجلس،ونظام العمل به.$m208$,'<<CR>>',chr(13))),
('law',14,2025,20,0,'d0ba8d58addfaef840a3365f1297fa34','53ced6ebf7b714c983913a8193f8379e',replace($m208$يمارس صندوق تمويل التدريب والتأهيل نشاطه على المستوى القومى وفقًا لاحتياجات سوق العمل وبما يتماشى مع احتياجات منظمات أصحاب الأعمال القطاعية المنشأة بقانون،ويختص بتقديم الخدمات الآتية:<<CR>>
1- تمويل عمليات تنمية مهارات الموارد البشرية والتدريب المهنى والتقنى من خلال إنشاء وتطوير مراكز التدريب،وإعداد وتنفيذ برامج التدريب،وأدلة المهارات والجدارات اللازمة.<<CR>>
2- تمويل المشروعات التنموية التى تستهدف تنمية مهارات الموارد البشرية، وربط مخرجات التعليم والتدريب باحتياجات سوق العمل الحالى والمستقبلى والتنسيق مع مجالس المهارات القطاعية.<<CR>>
3- وضع الشروط والقواعد التنفيذية لضبط عمليات التمويل. 4- متابعة وتقييم تنفيذ جميع الأعمال الممولة منه.<<CR>>
ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص وعضوية ممثلى المنظمات النقابية العمالية ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،وممثلى الوزارات والجهات المختصة،وتحديد اختصاصاته الأخرى ونظام العمل به،والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية،وفروعه فى المحافظات ولائحة نظامه الأساسى،ونظام تحصيل موارده،والنظام المحاسبى الواجب اتباعه. ولمجلس إدارة الصندوق أن يستخدم وسائل القانون الخاص فى تحقيق أهدافه ومباشرة اختصاصاته.$m208$,'<<CR>>',chr(13))),
('law',14,2025,21,0,'c2e52d99772c5b80e0d74a9c2604bca0','df8fe8fa579eec6d135d7fa210f0c620',replace($m208$تتكون موارد الصندوق المشار إليه فى المادة 20 من هذا القانون من:<<CR>>
1- نسبة ) %0,25 ربع فى المائة( من الحد الأدنى للأجر التأمينى بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص،والتى يعمل بها ثلاثون عاملاً فأكثر،بحد أدنى عشرة جنيهات،وبحد أقصى ثلاثون جنيها عن كل عامل، تتحملها وتلتزم المنشأة بسدادها سنويا مقابل الخدمات المنصوص عليها فى المادة (20) من هذا القانون. ويحدد بقرار من الوزير المختص قواعد وشروط الإعفاء الكلى من النسبة المشار إليها،وذلك فى حالة قيام تلك المنشآت بتدريب العاملين لديها وفقًا لمقتضياتها، أو اللوائح المعتمدة بتلك المنشآت.<<CR>>
2- الإعانات والتبرعات والهبات التى يقبلها مجلس إدارة الصندوق طبقًا للقواعد التى تحددها لائحة النظام الأساسى وفقًا للقوانين المعمول بها فى هذا الشأن.<<CR>>
3- عائد استثمار أموال الصندوق. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المعتمدة لدى البنك المركزى،ويعد الصندوق سنويا القوائم الدالة على المركز المالي،وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات ويرحل فائض أمواله من سنة إلى أخرى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,22,0,'338a06acd50889816d5a1bb32e16c0ea','e114bb65791925583d8e1ebe066c0399',replace($m208$لا يجوز لأية جهة مزاولة عمليات التدريب،إلا إذا كانت متخذة شكل شركة من شركات المساهمة،أو التوصية بالأسهم،أو ذات المسئولية المحدودة أو الشخص الواحد. ويستثنى من أحكام الفقرة الأولى من هذه المادة: 1- منظمات أصحاب الأعمال والمنظمات النقابية العمالية،والجمعيات والمؤسسات الأهلية المنشأة وفقًا للقانون المنظم لها،التى تزاول عمليات التدريب.<<CR>>
2- جهات التدريب التى تنشئها وحدات الجهاز الإدارى للدولة،والهيئات العامة، ووحدات الإدارة المحلية لتدريب موظفيها وموظفى الجهات ذات الصلة بها.<<CR>>
3- المنشآت التى تتولى تدريب عمالها.<<CR>>
4- الكيانات التى تزاول عمليات تأهيل وتدريب الأشخاص ذوى الإعاقة والأقزام،والفئات الأولى بالرعاية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,23,0,'4a22d38925f3f3d440ebe3aaeb4dc89a','9016dc8d2ceecc37842831aa28fa85ca',replace($m208$يشترط لمزاولة عمليات التدريب الحصول على ترخيص بذلك من الوزارة المختصة باستثناء الجهات المنصوص عليها فى البندين (2، 3) من المادة (22) من هذا القانون. ويصدر الوزير المختص قرارا بتحديد شروط وإجراءات منح الترخيص، ومدته،وتجديده،وحالات إلغائه،ورسومه بما لا يزيد على مائة ألف جنيه، وحالات الإعفاء منها. كما يحدد القرار قواعد،وإجراءات إنشاء،واعتماد مراكز التدريب الخاضعة لأحكام هذا القانون. وتلتزم الوزارة المختصة بإمساك سجل ورقى أو إلكترونى لقيد الجهات التى يتم الترخيص لها بمزاولة عمليات التدريب،وإخطار المجلس الأعلى لتنمية الموارد والمهارات البشرية بما يتم قيده فى هذا السجل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,24,0,'dbe16ddbc49e8b30568fdc44a98a12d5','daa0ed31cbd550d8b7f2f3a796069161',replace($m208$تلتزم الجهات المشار إليها فى المادة (22) من هذا القانون فيما عدا البندين (2، 3) بإخطار الوزارة المختصة بالبرامج التدريبية التى تقدمها لاعتمادها،على أن تتضمن ما يأتي: الشروط التى يجب توافرها فى المتدربين للالتحاق بالبرامج. مدى كفاية العمليات التدريبية من حيث موضوعات،ومجالات التدريب،وعدد الساعات المخصصة لها. مستويات وتخصصات المدربين. مستوى المهارة التى يكتسبها المتدرب بعد الانتهاء من البرنامج. ويصدر الوزير المختص قرارا بتحديد إجراءات ومواعيد الإخطار والاعتماد بعد التنسيق مع الهيئة المصرية لضمان الجودة والاعتماد فى التعليم الفنى والتقنى والتدريب المهنى )إتقان( المنشأة بالقانون رقم 160 لسنة. 2022$m208$,'<<CR>>',chr(13))),
('law',14,2025,25,0,'64c1761850e7eb612b00a1520248aabe','367621e7226f9f392c3580dde06c90ee',replace($m208$يشترط فى المدربين الذين يزاولون أعمال التدريب أن يرخص لهم بذلك من الوزارة المختصة بناء على طلبهم أو طلب إحدى الجهات المشار إليها فى المادة 22 من هذا القانون. ويصدر الوزير المختص قرارا بتحديد شروط وقواعد،وإجراءات منح الترخيص،والرسوم المستحقة عنه بما لا يجاوز خمسة آلاف جنيه،وحالات إيقافه أو إلغائه. على أن يستثنى من ذلك المدربون التابعون للجهات المنصوص عليها فى البندين (2، 3) من المادة (22) من هذا القانون،إذا اقتصر عملهم بالتدريب داخل هذه الجهات دون غيرها. وتلتزم الوزارة المختصة بإعداد سجل ورقى أو إلكترونى لقيد المدربين المرخص لهم،ويتم التأشير فيه حال إيقاف أو إلغاء الترخيص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,27,0,'6e1c5766478d81385e28601ec8edceda','90227f0963645e9d1afd62ea7fb45207',replace($m208$يلتزم كل من يرغب فى مزاولة مهنة أو حرفة من التى يصدر بتحديدها قرار من الوزير المختص،أن يتقدم بطلب إلى الجهة الإدارية المختصة للحصول على ترخيص بمزاولتها. ويحدد القرار شروط وقواعد،وإجراءات منح الترخيص،والرسوم المقررة عنه بما لا يجاوز خمسمائة جنيه،وحالات الإعفاء منها. ولا يجوز تشغيل العامل إلا إذا كان حاصلاً على هذا الترخيص. وعلى طالب الترخيص أن يرفق بطلبه شهادة تفيد مستوى مهارته،ويصدر الوزير المختص بالتشاور مع المنظمة النقابية العمالية المعنية ومنظمة أصحاب الأعمال المعنية قرارا بتحديد جميع البيانات التى يجب إثباتها فى تلك الشهادة، والأحكام الخاصة بقياس مستوى المهارة والجهات التى تتولى تحديد هذا المستوى، وكيفية إجرائه،وشروط التقدم له،والمكان الذى يجرى فيه لكل حرفة أو مهنة ودرجات المهارة التى تقدرها طبقًا لنتائج الاختبارات،والرسم المقرر عنها بما لا يجاوز خمسمائة جنيه وحالات الإعفاء من هذا الرسم. ويستثنى من الحصول على هذه الشهادة خريجو المدارس الفنية المتوسطة، وفوق المتوسطة والمعاهد العليا،والجامعات،الذين يعملون فى مجال تخصصهم.$m208$,'<<CR>>',chr(13))),
('law',14,2025,28,0,'b71e099beb3d91f4dc7c1c6d4fc97277','cc412aa0fb25f750d38df861a35cc85e',replace($m208$يشترط فى المتدرج ألا يقل سنه عن أربعة عشر عاما،ويصدر الوزير المختص قرارا بالقواعد والإجراءات المنظمة للتدرج المهنى لدى صاحب العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,29,0,'82406f8204a49d11109d9bda058edca2','39a0cd005419afa483d7f1616e4bba89',replace($m208$يجب أن يكون اتفاق التدرج مكتوبا،وتحدد فيه على الأخص مدة تعلم المهنة أو الصنعة أو الحرفة،ومراحلها المتتابعة والمكافأة التى يحصل عليها المتدرج فى كل مرحلة بصورة تصاعدية،على ألا تقل فى المرحلة الأخيرة عن الحد الأدنى للأجر المحدد لفئة العمال فى المهنة،أو الصنعة أو الحرفة التى يتدرج فيها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,32,0,'dfdaf65474a04b82404a3ab145581424','5517696ee46fa4962440f93bec85a784',replace($m208$ينشأ مجلس يسمى "المجلس الأعلى لتخطيط وتشغيل القوى العاملة فى الداخل والخارج" برئاسة الوزير المختص،ويضم ممثلين للوزارات والجهات المختصة، وعددا متساويا من ممثلى كل من منظمات أصحاب الأعمال المعنية الأكثر تمثيلاً، ترشحهم منظماتهم وممثلى المنظمات النقابية العمالية المعنية،على أن يراعى تمثيل جميع مستويات المنظمات النقابية العمالية ما لم يكن ذلك متعذرا.<<CR>>
ويتولى المجلس رسم السياسة العامة لتشغيل العمالة فى الداخل والخارج، ووضع النظم والقواعد،والإجراءات اللازمة لهذا التشغيل من واقع احتياجات أسواق العمل فى الداخل والخارج،والاستعداد لوظائف المستقبل،بما يتفق مع السياسة العامة للدولة. ويصدر بتشكيل المجلس،واختصاصاته،ونظام العمل به قرار من رئيس مجلس الوزراء فى مدة أقصاها ستة أشهر من تاريخ العمل بهذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,33,0,'5737d62c49e732e41eff71ba41dec105','53efaffacd29483f51f7fb7d42096075',replace($m208$مع عدم الإخلال بأحكام قانون حقوق الأشخاص ذوى الإعاقة الصادر بالقانون رقم 10 لسنة، 2018 على كل قادر على العمل،وراغب فيه أن يتقدم بطلب لقيد اسمه بالجهة الإدارية المختصة مع بيان سنه ومهنته ومؤهلاته وخبراته السابقة، وعلى هذه الجهة قيد تلك الطلبات بسجلات ورقية أو إلكترونية وإعطاء الطالب شهادة تفيد القيد دون مقابل،وتحدد البيانات التى يجب أن تتضمنها الشهادة المشار إليها بقرار من الوزير المختص. ولا يجوز تشغيل العامل إلا إذا كان حاصلاً على الشهادة المشار إليها فى الفقرة الأولى من هذه المادة،واستثناء من ذلك لصاحب العمل أن يعين من غير الحاصلين عليها بشرط قيد اسم العامل بالجهة الإدارية المختصة خلال ثلاثين يوما من تاريخ تسلمه العمل. ويجوز لصاحب العمل أن يستوفى احتياجاته الوظيفية والمهنية والحرفية بالنسبة للوظائف والأعمال التى خلت أو أنشئت لديه ممن ترشحهم الجهة الإدارية المختصة التى يقع فى دائرتها محل عمله من المسجلين لديها مراعية أسبقية القيد.$m208$,'<<CR>>',chr(13))),
('law',14,2025,34,0,'88daeb9d27462d88b60af78c26b1302d','ea10774d461f397a408a0b6c38572f5d',replace($m208$إذا كان الراغب فى العمل يمارس حرفة أو مهنة من التى يصدر بتحديدها قرار من الوزير المختص وفقًا لنص المادة (27) من هذا القانون،وجب عليه أن يرفق بطلب القيد شهادة قياس مستوى مهارته وترخيص مزاولتها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,35,0,'64850b3878b8c95e158f585b19f059b0','c3316d76ba571f184e20f034fa71ce84',replace($m208$مع عدم الإخلال بأحكام قانون حقوق الأشخاص ذوى الإعاقة المشار إليه تلتزم المنشآت القائمة وقت تطبيق هذا القانون،وتلك التى تنشأ مستقبلاً أن تعيد إلى الجهة الإدارية المختصة شهادة قيد العامل الصادرة عنها خلال خمسة وأربعين يوما من تاريخ استلام العمل بعد استيفاء البيانات المدونة بها،وعليها تدوين رقم شهادة القيد، وتاريخها أمام اسم العامل فى سجل قيد العمال بالمنشأة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,36,0,'34b6b99bb8b094c8c99d4e680ea10a55','c60e15bf4fb090ed0e36bc092391a40c',replace($m208$تلتزم المنشآت الخاضعة لأحكام هذا القانون بأن ترسل إلى الجهة الإدارية المختصة خلال ثلاثين يوما من تاريخ بدء العمل بالمنشأة،بيانًا مفصلاً بعدد العمال طبقًا لمؤهلاتهم،ومهنهم،وفئات أعمارهم،وجنسياتهم،ونوعهم،والأجور التى يتقاضونها. وعلى هذه المنشآت أن ترسل إلى تلك الجهة خلال شهر يناير من كل عام البيانات الآتية:<<CR>>
1- ما طرأ من تعديلات على البيانات الواردة فى الفقرة الأولى من هذه المادة.<<CR>>
2- عدد الوظائف الشاغرة بسبب الإحلال أو التوسعات الجديدة،والوظائف التى تم إلغاؤها.<<CR>>
3- بيان بتقدير الاحتياجات المتوقعة حسب الحالة التعليمية والمهنية خلال العام التالي. وذلك كله وفقًا للنماذج التى تعدها الوزارة المختصة. وعلى الجهة الإدارية المختصة موافاة الهيئة القومية للتأمين الاجتماعى بنسخة من البيانات المشار إليها بالفقرة الثانية من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,37,0,'0ec5c1fc6e8d59f480ff0f930899e4be','c30a93b54c776382a7efaf15b1ce8eb0',replace($m208$تلتزم المنشآت المشار إليها فى المادة (35) من هذا القانون بإمساك سجل ورقى أو إلكترونى لقيد أسماء الأشخاص ذوى الإعاقة والأقزام الحاصلين على شهادات التأهيل أو بطاقة إثبات الإعاقة والخدمات المتكاملة،بحسب الأحوال،الذين ألحقوا<<CR>>
بالعمل لديها،يشتمل على البيانات الواردة فى شهادات التأهيل أو بطاقة إثبات الإعاقة والخدمات المتكاملة بحسب الأحوال،ويجب تقديم هذا السجل إلى الجهة الإدارية المختصة كلما طلب منها ذلك. ويجب إخطار تلك الجهة ببيان يتضمن العدد الإجمالى للعاملين،وعدد الوظائف التى يشغلها الأشخاص ذوو الإعاقة والأقزام،والأجر الذى يتقاضاه كل منهم،وذلك وفقًا للنموذج والموعد اللذين يصدر بتحديدهما قرار من الوزير المختص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,38,0,'9124c53f2bf9ff003da1b87e4d66c87f','3ff6c7751253586ea322e11087c4bd08',replace($m208$تلتزم جميع المنشآت الخاضعة لأحكام هذا القانون بموافاة الوزارة المختصة ورقيا أو إلكترونيا بالبيانات أو المعلومات اللازمة لإنشاء أو تحديث قواعد بيانات العمالة،ونظام معلومات سوق العمل خلال ثلاثين يوما من تاريخ طلبها. كما يجب على أصحاب الأعمال أو من يمثلونهم بذل العناية الواجبة للتعاون مع الجهة الإدارية المختصة لاستيفاء استمارات جمع البيانات أو المعلومات ورقيا أو إلكترونيا. وعلى الوزارة المختصة القيام بجمع البيانات اللازمة عن سوق العمل وإجراء الدراسات والأبحاث الميدانية منفردة أو بالتنسيق مع الجهات المختصة،وعليها أن تصدر تقارير دورية قطاعية أو جغرافية عن احتياجات سوق العمل الحالى والمستقبلى من المهن والمهارات،ورصد أية تغيرات تطرأ عليه. ) الفصل الثانى ( التشغيل فى الداخل والخارج$m208$,'<<CR>>',chr(13))),
('law',14,2025,39,0,'7177f24204ef38f575ec1965e308894a','9d2d89c2bc81426d9961b101e036c8a5',replace($m208$يستثنى من تطبيق أحكام هذا الفصل ما يأتي:<<CR>>
1- الأعمال العرضية وما فى حكمها.<<CR>>
2- الوظائف الرئيسية التى يعتبر شاغلوها وكلاء مفوضين عن صاحب العمل. وللوزير المختص أن يصدر قرارا بسريان أحكام هذا الفصل على كل،أو بعض الأعمال والوظائف والفئات المشار إليها فى البندين (1، 2) من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,40,0,'4bbcbdfec62f79abb785dfbcf1f565b1','3ab4e20de9d21ea1a275ffb5a7818f73',replace($m208$مع عدم الإخلال بالاتفاقيات الدولية المتعلقة بالتشغيل،تكون مزاولة عمليات إلحاق المصريين للعمل بالداخل أو الخارج عن طريق الوزارة المختصة،أو الجهات الآتية:<<CR>>
1- الوزارات والهيئات العامة بالنسبة للعاملين لديها.<<CR>>
2- شركات القطاع العام وقطاع الأعمال العام والقطاع الخاص المصرية للعاملين لديها فيما تبرمه من تعاقدات مع الجهات الأجنبية فى حدود أعمالها، وطبيعة نشاطها.<<CR>>
3- وكالات التشغيل الخاصة التى تتخذ شكل الشركة المساهمة،أو التوصية بالأسهم،أو ذات المسئولية المحدودة أو الشخص الواحد المرخص لها بذلك من الوزارة المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,41,0,'cbcdcbfd3f6e4dc6553a6c995f04a23d','1846e84e3a254e88ed06f81972106516',replace($m208$مع عدم الإخلال بالشروط التى يوجبها قانون شركات المساهمة وشركات شخص ركات ال دودة وش سئولية المح شركات ذات الم هم وال ية بالأس التوص الواحد الصادر بالقانون رقم 159 لسنة 1981 يلزم للحصول على الترخيص المشار إليه فى البند (3) من المادة (40) من هذا القانون،توافر الشروط المقررة لذلك، وعلى الأخص:<<CR>>
1- أن يكون المؤسسون وأعضاء مجلس الإدارة والمديرون المختصون بعمليات التشغيل لم يسبق الحكم على أى منهم بعقوبة جناية،أو بعقوبة مقيدة للحرية فى جنحة مخلة بالشرف أو الأمانة أو الآداب العامة،ما لم يكن قد رد إليه اعتباره.<<CR>>
2- ألا يقل رأسمال الشركة المصدر أو المدفوع،بحسب الأحوال،عن مائتين وخمسين ألف جنيه وأن يكون مملوكًا بأكمله للمصريين إذا كانت الشركة تزاول عمليات التشغيل بالداخل،وألا يقل عن خمسمائة ألف جنيه إذا كانت تزاول عمليات تشغيل المصريين بالخارج أو بالداخل والخارج معا،وأن تكون الأغلبية المطلقة للمؤسسين وأعضاء مجلس الإدارة من المصريين الذين يمتلكون فى مجموعهم )(%51 على الأقل من رأسمالها.<<CR>>
3- أن تقدم الشركة تأمينًا لا يقل عن مليون جنيه إما نقدا أو بخطاب ضمان غير مشروط وغير قابل للإلغاء صادر من أحد البنوك المسجلة لدى البنك المركزى، لصالح الوزارة المختصة،وأن يكون ساريا طوال مدة سريان الترخيص وذلك لضمان التزام المرخص له بالتزاماته،ويتعين استكمال قيمة التأمين بمقدار ما لم تقم بأدائه من غرامات أو تعويضات حكم بها عليها،أو مبالغ تقاضتها دون وجه حق، طبقًا لأحكام هذا القانون،وذلك خلال خمسة عشر يوما من تاريخ إخطار الشركة المرخص لها بكتاب موصى عليه بعلم الوصول بوجوب استكمال التأمين. ويكون الترخيص لمدة سنة قابلة للتجديد وفقًا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص،وذلك مقابل أداء الرسم الذى يحدده الوزير المختص لمنح الترخيص أو تجديده بما لا يجاوز عشرة آلاف جنيه،وللوزير المختص إضافة شروط أخرى للحصول على الترخيص،وله وقف إصدار تراخيص جديدة إذا اقتضت المصلحة العامة ذلك فى ضوء متغيرات سوق العمل الفعلية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,42,0,'994f598bea6f19d28cbb9a805265b56e','90689bbaf26bfe031f7361de4da72a1e',replace($m208$يصدر الوزير المختص قرارا يتضمن التزامات الشركات المرخص لها بالتشغيل والشروط الواجب توافرها فى مقر الشركة وإدارتها،وتنظيم إجراءات العمل فى هذا النشاط والسجلات اللازمة لمباشرة عملها والتى يتعين إمساكها،وقواعد القيد فيها، والرقابة والتفتيش عليها،والشروط الواجب توافرها فى الإعلانات التى تنشر عن فرص العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,43,0,'1c805b82bc9dfc1ddd8e8b1e31c2fb23','c01f00fb98a258d0c508f1a375e5661e',replace($m208$يحظر على الجهات المشار إليها فى المادة (40) من هذا القانون تقاضى أى مبالغ مالية من العامل بطريقة مباشرة أو غير مباشرة نظير إلحاقه بالعمل،ولها أن تتقاضى مقابل ذلك من صاحب العمل. واستثناء من أحكام الفقرة الأولى من هذه المادة يجوز للشركات المشار إليها فى البند (3) من المادة (40) من هذا القانون أن تتقاضى مبلغًا لا يجاوز ) (%1 من أجر العامل الذى يتم إلحاقه بالعمل،وذلك عن السنة الأولى فقط كمصروفات إدارية، ويحظر تقاضى أى مبالغ أخرى من العامل تحت أى مسمى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,44,0,'42c14f51cac6f26d1995f4c06199e252','9a94df0f1db1de45f2f8655d4be163c3',replace($m208$يلغى الترخيص المشار إليه بالبند (3) من المادة (40) من هذا القانون بقرار من الوزير المختص فى الحالات الآتية:<<CR>>
1- فقد الشركة شرطًا من شروط الترخيص.<<CR>>
2- حصول الشركة على الترخيص أو تجديده بناء على ما قدمته من بيانات غير صحيحة.<<CR>>
3- ثبوت ممارسة الشركة لنشاطها خارج المقر المرخص لها ممارسة النشاط فيه.<<CR>>
4- تشغيل العامل دون تحرير عقد عمل مكتوب،أو ما يقوم مقامه لدى بعض الدول،أو عدم اعتماد العقد من الجهة الإدارية المختصة.<<CR>>
5- عدم إمساك السجلات الخاصة بتسجيل بيانات العمالة أو تسجيل المبالغ التى يتم تحصيلها منهم،والتى يصدر بتحديدها قرار من الوزير المختص.<<CR>>
6- قيام الشركة بالإعلان عن وظائف غير حقيقية أو تجاوز الشركة حدود التعاقد مع أصحاب الأعمال.<<CR>>
7- تقاضى الشركة أى مبالغ من العامل نظير تشغيله بالمخالفة لأحكام هذا القانون. ويجوز للوزير المختص إيقاف نشاط الشركة مؤقتًا فى أى من الحالات المبينة فى الفقرة الأولى من هذه المادة لحين الفصل فى مدى ثبوت تلك الحالات،أو زوال تلك المخالفات. ولا يخل إلغاء الترخيص فى أى من الحالات المبينة فى هذه المادة بالمسئولية الجنائية أو المدنية أو التأديبية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,45,0,'ab975b346fcd7693d33d303e4ce97bde','93298c45a08b174673de30f513862bba',replace($m208$مع مراعاة حكم المادة (40) من هذا القانون،لا يجوز للمنشآت تشغيل عمال عن طريق متعهد أو مقاول توريد عمال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,46,0,'dfc4e40864de4846f20809b68d714043','22655d0f73acccad1bce5b906fda970e',replace($m208$مع عدم الإخلال بأحكام قانون تنظيم ممارسة العمل الأهلى الصادر بالقانون رقم 149 لسنة 2019 يجوز للوزير المختص،وفقًا لاحتياجات سوق العمل الترخيص للجمعيات والمؤسسات الأهلية بإنشاء مكاتب لتشغيل المتعطلين بالداخل. وعلى تلك المكاتب مراعاة الأحكام الواردة فى هذا الفصل من القانون والقرارات الوزارية الصادرة بشأنه. ويصدر الوزير المختص قرارا بتنظيم أعمال تلك المكاتب،وشروط منح الترخيص وحالات إلغائه والرسوم المقررة عليه بما لا يجاوز خمسة آلاف جنيه. وتعفى تلك المكاتب من الشكل القانونى للشركات،كما تعفى من تقديم التأمين أو خطاب الضمان.$m208$,'<<CR>>',chr(13))),
('law',14,2025,47,0,'7b0c1ff0b36b14a62298dbd6ef1f9098','5a50ce173528d0cfb35816f98c04a69f',replace($m208$لصاحب العمل الإعلان عن الوظائف الشاغرة بمختلف وسائل الإعلام، أو أن يعهد إلى وكالات التشغيل الخاصة لشغل تلك الوظائف. وعلى صاحب العمل أو وكالة التشغيل إخطار الجهة الإدارية المختصة ورقيا أو إلكترونيا بالإعلان،وتقديم بيان بالوظائف التى تم شغلها وفقًا له.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,48,0,'49e3fbcd0b3b33b3911e23eb8dcd5c11','95933f26bccfffa8bebf25070277ab85',replace($m208$تلتزم الجهات المشار إليها فى المادة (40) من هذا القانون عدا البند (1) منها، بأن تقدم إلى الوزارة المختصة خلال خمسة أيام عمل فعلية صورة طبق الأصل من الطلب الوارد إليها بشأن توفير فرص العمل بالخارج وشروطها،موثقة من السلطات المختصة،كما تقدم نسخة من الاتفاقيات وعقود العمل المبرمة،متضمنة تحديد العمل والأجر المحدد له وشروط وظروف أدائه والتزامات العامل. ويكون للوزارة المختصة خلال خمسة عشر يو ما على الأكثر من تاريخ إخطارها بالاتفاقيات والطلبات والعقود المستوفاة الاعتراض عليها فى حالة عدم مناسبة الأجر، أو مخالفتها للنظام العام والآداب العامة.<<CR>>
فإذا انقضت المدة المشار إليها دون اعتراض من الوزارة اعتبرت الاتفاقيات والطلبات والعقود موافقًا عليها. ويصدر الوزير المختص قرارا بإجراءات وأسلوب ووسيلة إخطار تلك الجهات بشأن اعتراض الوزارة المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,50,0,'f45fa7a2b9bada63717840f77845efaf','7606b6311e6905724afff4a80ff7d941',replace($m208$للمنظمات الدولية أن تزاول عمليات إلحاق العمالة المصرية ممن يتمتعون بخبرات وكفاءات خاصة للعمل خارج البلاد،إذا كان التعاقد مع جهات حكومية، أو هيئات عامة عربية أو أجنبية بعد أخذ موافقة الجهات المعنية. وعليها أن تقدم إلى الوزارة المختصة بيانًا بفرص العمل التى تم توفيرها بهذه الجهات وعقود العمل المبرمة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,52,0,'b127999e81ee45f093bd5262996c71d1','adf81daa0e203cc41eac994b91f99a82',replace($m208$لا يجوز ممارسة عمليات إلحاق المصريين بالداخل والخارج إلكترونيا من خلال مواقع أو صفحات أو منصات إلكترونية إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة،ويستثنى من ذلك وكالات التشغيل المشار إليها فى البند (3) من المادة (40) ويصدر الوزير المختص بالتشاور مع الوزير المعنى بشئون الاتصالات قرارا بقواعد منح هذا الترخيص،ومدته بما لا يجاوز سنة،والرسوم المقررة عليه بما لا يقل عن ألف جنيه ولا يزيد على عشرة آلاف جنيه،وضوابط وقواعد التشغيل، والتقارير التى تقدمها عن نتائج أعمالها،وآليات التنسيق معها.<<CR>>
) الفصل الثالث ( تشغيل النساء$m208$,'<<CR>>',chr(13))),
('law',14,2025,53,0,'8877a65896108d3dda3e37fad8787685','aa23ccdb7be6c422503764563704967f',replace($m208$مع عدم الإخلال بأحكام المواد التالية،تسرى على النساء العاملات جميع الأحكام المنظمة لتشغيل العمال،دون تمييز. ويستحق جميع العاملين من الذكور والإناث أجرا متساويا عن العمل ذى القيمة المتساوية،ويشمل ذلك كل صور الأجر وعناصره من مزايا نقدية أو عينية أو علاوات أو حوافز أو بدلات أو غيرها. ويصدر الوزير المختص،بعد أخذ رأى كل من المجلس القومى للمرأة والمجلس القومى للطفولة والأمومة،قرارا بتحديد الأحوال أو الأعمال التى لا يجوز تشغيل النساء فيها،بهدف توفير التدابير اللازمة لحماية الأمومة،أو مواجهة مخاطر السلامة والصحة المهنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,54,0,'b9bb16957faffdd23cafa29e84d880fa','ea53ad2415ccc9b72edf846e7ac1ec9a',replace($m208$للعاملة الحق فى إجازة وضع لمدة أربعة أشهر تشمل المدة التى تسبق الوضع والتى تليه،على ألا تقل مدة هذه الإجازة بعد الوضع عن خمسة وأربعين يوما، بشرط أن تقدم شهادة طبية مبينًا بها التاريخ الذى يرجح حصول الوضع فيه، وتكون هذه الإجازة مدفوعة الأجر،وفى جميع الأحوال لا تستحق العاملة هذه الإجازة لأكثر من ثلاث مرات طوال مدة خدمتها. ويخصم من الأجر الذى يلتزم به صاحب العمل،ما يلتزم بأدائه من تعويض عن الأجر وفقًا لحكم المادة (77) من قانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم 148 لسنة 2019 وتخفض ساعات العمل اليومية للمرأة الحامل ساعة على الأقل اعتبارا من الشهر السادس من الحمل،ولا يجوز إلزامها بساعات عمل إضافية طوال مدة الحمل وحتى نهاية ستة أشهر من تاريخ الوضع.$m208$,'<<CR>>',chr(13))),
('law',14,2025,55,0,'f4a6a9b23e4d18942a0ff7210d7b7ca3','224bf1cfae02cbb564253adc64c71faf',replace($m208$للعاملة بعد انتهاء إجازة الوضع المبينة بالمادة (54) من هذا القانون الحق فى العودة إلى وظيفتها أو وظيفة مماثلة لها دون الإخلال بأية مزايا كانت مقررة لوظيفتها الأصلية. ويحظر فصل العاملة أو إنهاء خدمتها أثناء إجازة الوضع. كما يحظر فصلها أو إنهاء خدمتها عقب عودتها من هذه الإجازة،ما لم يثبت صاحب العمل أن الفصل أو إنهاء الخدمة لسبب مشروع. ومع ذلك،يكون لصاحب العمل حرمان العاملة من التعويض عن أجرها عن مدة الإجازة المشار إليها أو استرداد ما تم أداؤه منه إذا ثبت اشتغالها خلال الإجازة لدى الغير،وذلك مع عدم الإخلال بالمساءلة التأديبية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,56,0,'dd2023f8154946ed539a4a06bbe18680','96eb4b6a381f6add8e860f8d5d434dee',replace($m208$يكون للعاملة التى ترضع طفلها خلال السنتين التاليتين لتاريخ الوضع، فضلاً عن فترة الراحة المقررة،الحق فى فترتين أخريين للرضاعة لا تقل كل منهما عن نصف ساعة،وللعاملة الحق فى ضم هاتين الفترتين. وتحسب هاتان الفترتان الإضافيتان من ساعات العمل ولا يترتب على ذلك أى تخفيض فى الأجر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,57,0,'ca2628dd57099df9d92de8ea7b14ab33','9cc9cf71c503a11ffdc7ade48ae24edf',replace($m208$مع مراعاة حكم الفقرة الثانية من المادة (72) من قانون الطفل الصادر بالقانون رقم 12 لسنة، 1996 يكون للعاملة فى المنشأة التى تستخدم خمسين عاملاً فأكثر الحق فى الحصول على إجازة دون أجر لمدة لا تجاوز سنتين،وذلك لرعاية طفلها، ولا تستحق هذه الإجازة لأكثر من ثلاث مرات طوال مدة خدمتها شريطة أن يكون قد مر على وجودها فى المنشأة سنة على الأقل،وعلى ألا تقل المدة بين الإجازة الأولى والثانية عن سنتين.$m208$,'<<CR>>',chr(13))),
('law',14,2025,58,0,'ecea0ae645453de125209c8595ee2f52','4d1ad1e54c834cf6a774a0ba4a8915a6',replace($m208$للعاملة أن تنهى عقد العمل بسبب زواجها،أو حملها،أو إنجابها،على أن تخطر صاحب العمل كتابة برغبتها فى ذلك خلال ثلاثة أشهر من تاريخ إبرام عقد الزواج،أو ثبوت الحمل،أو من تاريخ الوضع بحسب الأحوال،مع مراعاة ألا يؤثر ذلك على الحقوق المقررة لها وفقًا لأحكام هذا القانون أو لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,59,0,'46de7482880b348e73f161d7366379cb','a6654c46e16abc9b19ce987ebbddb1d6',replace($m208$يجب على صاحب العمل فى حالة تشغيله عاملة أو أكثر أن يعلق فى أماكن العمل أو تجمع العمال نسخة من نظام تشغيل النساء. ويجب أن يتضمن ذلك النظام إجراءات وضوابط وقواعد ومواعيد ساعات العمل المرن أو العمل عن بعد للمرأة التى ترعى أطفالاً ذوى إعاقة أو أقزام.$m208$,'<<CR>>',chr(13))),
('law',14,2025,60,0,'55e9d7a52df2ebd4c8d5bbce0df3bdb9','a720b23b1a15e1faa9c5a844f10d163d',replace($m208$مع عدم الإخلال بأحكام قانون الطفل المشار إليه على صاحب العمل الذى يستخدم مائة عاملة فأكثر فى مكان واحد أن ينشئ دا را للحضانة،أو يعهد إلى دار للحضانة برعاية أطفال العاملات. وتلتزم المنشآت التى تقع فى منطقة واحدة وتستخدم كل منها أقل من مائة عاملة،أن تشترك فى تنفيذ الالتزام المنصوص عليه فى الفقرة الأولى من هذه المادة. واستثناء من ذلك،لصاحب العمل أن يتحمل تكاليف رعاية الأطفال بدار الحضانة. وذلك كله بالضوابط والأوضاع التى يصدر بها قرار من الوزير المختص بعد التنسيق مع الوزير المعنى بشئون التضامن الاجتماعى والمجلس القومى للطفولة والأمومة. ) الفصل الرابع ( أحكام تشغيل وتدريب الأطفال$m208$,'<<CR>>',chr(13))),
('law',14,2025,61,0,'04f97c2fee204cc1703988846b0e3f01','163c63aeb9080ff5748ac771ddad6e48',replace($m208$تسرى على هذا الفصل أحكام قانون الطفل المشار إليه فيما لم يرد بشأنه نص خاص. ويعتبر طفلاً فى تطبيق أحكام هذا القانون،كل من لم يبلغ ثمانى عشرة سنة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,62,0,'3cea6b746669f772ca2c3b21e9068005','d9d3ec8353f1df35d16aa3a0a1d7e1e2',replace($m208$يحظر تشغيل الأطفال قبل بلوغهم خمس عشرة سنة،ومع ذلك يجوز تدريبهم متى بلغت سنهم أربع عشرة سنة بما لا يعوقهم عن مواصلة التعليم. ويلتزم كل صاحب عمل يدرب طفلاً دون سن الخامسة عشرة بمنحه بطاقة تثبت أنه يتدرب لديه،وتلصق عليها صورة الطفل،وتُعتمد من الجهة الإدارية المختصة، وتختم بخاتمها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,63,0,'8983d496c0a6b3280f0122883fdcbc0e','deb4a61fb2cbe59f80d1c4c982a3f700',replace($m208$يكون تشغيل أو تدريب الأطفال،وتحديد الظروف والأحوال والقواعد والإجراءات التى يتم فيها ذلك،وفقًا للقرار الصادر من الوزير المختص بالتنسيق مع المجلس القومى للطفولة والأمومة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,64,0,'eb3b52b4a87b03e3e747631afde80ad9','24df9c456f8343caee478e3a8b7d78f4',replace($m208$يحظر تشغيل أو تدريب الأطفال فى الأعمال،والمهن،والصناعات التى من شأنها أن تعرض صحتهم البدنية أو النفسية أو سلامتهم أو أخلاقهم للخطر،أو تعوقهم عن مواصلة التعليم كما يحظر تشغيلهم أو تدريبهم فى أى عمل غير مشروع،أو أية أعمال تعتبر من صور أسوأ أشكال عمل الأطفال وفقًا للاتفاقيات والمواثيق والمعاهدات الدولية التى صدقت عليها جمهورية مصر العربية. ويصدر الوزير المختص بالتنسيق مع المجلس القومى للطفولة والأمومة قرارا بتحديد تلك الأعمال والمهن والصناعات طبقًا لمراحل السن المختلفة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,65,0,'d993bd2e3af3206b3f5c22c7c3fe414e','10305283ef6559e268c3048bcb4414b5',replace($m208$يحظر تشغيل الطفل أكثر من ست ساعات يوميا،ويجب أن تتخلل ساعات العمل فترة أو أكثر لتناول الطعام والراحة لا تقل فى مجموعها عن ساعة واحدة، وتحدد هذه الفترة أو الفترات بحيث لا يعمل الطفل أكثر من أربع ساعات متصلة، ويحظر تشغيل الطفل ساعات عمل إضافية أو تشغيله فى أيام الراحة الأسبوعية والعطلات الرسمية. وفى جميع الأحوال،يحظر تشغيل الطفل فيما بين الساعة السابعة مساء والسابعة صباحا.$m208$,'<<CR>>',chr(13))),
('law',14,2025,66,0,'2cf7b3bca351690b50635d7c9f7723e1','23e97741b44ed68f21c5ec229c964ed6',replace($m208$على صاحب العمل الذى يقوم بتشغيل طفل أو أكثر مراعاة الآتى: 1- تعليق نسخة تحتوى على الأحكام التى يتضمنها هذا الفصل فى مكان ظاهر بمحل العمل.<<CR>>
2- تحرير كشف موضح به ساعات العمل وفترات الراحة معتمد من الجهة الإدارية المختصة.<<CR>>
3- إبلاغ الجهة الإدارية المختصة بأسماء الأطفال العاملين لديه،والأعمال المكلفين بها،وأسماء الأشخاص المنوط بهم مراقبة أعمالهم.<<CR>>
4- توفير سكن منفصل للأطفال عن غيرهم من البالغين،وفقًا للضوابط والأحكام التى يصدر بها قرار من الوزير المختص،ويحظر فى جميع الأحوال مبيت الطفل في مكان العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,68,0,'85df08d49408f09742a388d702642030','a5eca3bb4f5944b773d233b5fc485953',replace($m208$يحظر على الأبوين أو متولى أمر الطفل،بحسب الأحوال،تشغيل الطفل بالمخالفة لأحكام هذا القانون،والقرارات التنفيذية الصادرة له.<<CR>>
) الفصل الخامس ( تنظيم عمل الأجانب$m208$,'<<CR>>',chr(13))),
('law',14,2025,70,0,'3d4c811bb1b409024ebe280d77e5ab54','b3f675a54746cb7ecb25ec268528f893',replace($m208$يخضع عمل الأجانب فى جميع منشآت القطاع الخاص،ووحدات القطاع العام، وقطاع الأعمال العام،والهيئات العامة والإدارة المحلية،والجهاز الإدارى للدولة للأحكام الواردة فى هذا الفصل،وذلك مع مراعاة شرط المعاملة بالمثل. ويحدد الوزير المختص النسبة القصوى لتشغيل الأجانب فى تلك المنشآت والجهات،وحالات الاستثناء من تلك النسبة،والمهن والحرف التى يحظر على الأجانب الاشتغال بها. ويجوز للوزير المختص إعفاء الأجانب من شرط المعاملة بالمثل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,71,0,'345a7428b6206f80d769c394e57f149a','4db8795b46c220738bd87f5d4871ad62',replace($m208$لا يجوز للأجنبى العمل داخل البلاد إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة وأن يكون مصرحا له بدخول البلاد والإقامة بها بقصد العمل، ولا يجوز لأصحاب الأعمال تشغيل الأجانب إلا بعد الحصول على هذا الترخيص. ويصدر الوزير المختص قرارا بشروط الحصول على الترخيص المشار إليه، وإجراءاته،والبيانات التى يتضمنها،وإجراءات تجديده،والرسم الذى يحصل عنه ورسوم الإعفاء من شروط الاستقدام،بما لا يقل عن خمسة آلاف جنيه،ولا يزيد على مائة وخمسين ألف جنيه،ويحدد حالات إلغاء الترخيص قبل انتهاء مدته، وحالات إعفاء الأجانب من شرط الحصول عليه،وحالات الإعفاء من شرط الاستقدام وبما يتماشى مع احتياجات سوق العمل. ويلتزم كل من يستخدم أجنبيا أعفى من شرط الحصول على الترخيص بأن يخطر الجهة الإدارية المختصة بذلك خلال سبعة أيام من مزاولة الأجنبى للعمل،وعند انتهاء خدمته لديه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,72,0,'fc85319855f1e05288fa952e0ec65f96','13faf8705e9349a35ccdc296a3830eec',replace($m208$يلتزم صاحب العمل بإبلاغ الجهة الإدارية والسلطات المختصة عن غياب العامل الأجنبى عن العمل لمدة خمسة عشر يوما متصلة دون مسوغ قانونى يجيز ذلك، ويصدر الوزير المختص قرارا بالضوابط والشروط والإجراءات المنظمة لذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,73,0,'332027e41f64a4c3a77699c442730b5c','7d4d99eb8a3d2c07a0d95fea0bdcbef1',replace($m208$مع عدم الإخلال بأحكام قانون الاستثمار الصادر بالقانون رقم 72 لسنة، 2017 يجوز للوزير المختص بالاتفاق مع الوزير المعنى بشئون الاستثمار،وضع القواعد والضوابط اللازمة للترخيص بالعمل للأجانب المخاطبين بأحكام قانون الاستثمار المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,74,0,'313a6dd9c7fa11b60351695e38b8e1e2','1c024834878d5d8e7b390f80656790ae',replace($m208$يلتزم صاحب العمل الذى يعمل لديه الأجنبى بإعادته إلى الدولة التى تم استقدامه منها على نفقة صاحب العمل الخاصة حال انتهاء علاقة العمل،ما لم ينص عقد العمل على خلاف ذلك. ويصدر الوزير المختص قرارا بالحالات والمواعيد والإجراءات المنظمة لذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,75,0,'3dc52227b67efa9da1063972dc26374d','45d98ebc3ee030a8c23ffec959921981',replace($m208$تهدف أحكام هذا الباب إلى تنظيم ودعم وتشغيل العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى على المستوى القومى،ومساعدتهم فى الحصول على فرص العمل اللائقة لهم،وتنمية مهاراتهم بما يتناسب مع احتياجات سوق العمل فى الداخل والخارج،وحمايتهم أثناء العمل،وتقديم الدعم اللازم أثناء فترات التعطل. وتسرى على العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى،الذين يعملون لدى أصحاب الأعمال،جميع الحقوق والواجبات الواردة فى هذا القانون. ويصدر الوزير المختص قرارا بالقواعد والأحكام المنظمة لشروط وظروف عمل تلك الفئات،وطرق الحصول على حقوقهم والقيام بواجباتهم،بما يتوافق مع طبيعة وفترات عملهم.$m208$,'<<CR>>',chr(13))),
('law',14,2025,77,0,'a256ebcae6f674c8730a40b08e6f9f51','a8407654d0f92eade5afe25d001e4fd1',replace($m208$تلتزم الجهة الإدارية المختصة بحصر وقيد العمالة غير المنتظمة،وفقًا لتصنيفها وفئاتها،فى السجلات الورقية أو الإلكترونية المعدة لذلك. كما تلتزم بإعداد قواعد بيانات قومية لفئات العمالة غير المنتظمة،وربطها بأجهزة ووزارات الدولة بالتنسيق مع الجهات المعنية،وعلى الأخص الجهاز المركزى للتعبئة العامة والإحصاء،والهيئة القومية للتأمين الاجتماعي. ويصدر الوزير المختص قرارا بالقواعد والإجراءات اللازمة لذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,78,0,'c85fac20db5a329194c6bfb847f03c8a','29be95f047d0a40fc6b5e08c5fed16e2',replace($m208$ينشأ صندوق لحماية وتشغيل العمالة غير المنتظمة يسمى "صندوق إعانات الطوارئ والخدمات الاجتماعية والصحية للعمالة غير المنتظمة"،تكون له الشخصية الاعتبارية العامة،ويتبع الوزير المختص،ويكون مقره الرئيسى محافظة القاهرة، وله أن ينشئ فروعا فى المحافظات. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق،برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال المعنية بالتساوى فيما بينهما،وممثلى الوزارات والجهات المعنية، ويحدد القرار اختصاصات المجلس،والنظام الأساسى للصندوق،والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية،والنظام المحاسبى الواجب اتباعه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,79,0,'e2e386ae0b3045081492356f24f168bd','d4a998e4642b4a26a23a3a705cc04922',replace($m208$يختص الصندوق بما يأتي:<<CR>>
1- صرف إعانات الطوارئ للعمالة غير المنتظمة فى حالات الأزمات الاقتصادية العامة أو الكوارث أو الأوبئة أو حالات التوقف المؤقت عن العمل.<<CR>>
2- تقديم الخدمات الاجتماعية والصحية لفئات العمالة غير المنتظمة.<<CR>>
3- دعم النفقات العلاجية والخدمات الطبية.<<CR>>
4- المساهمة فى سداد اشتراكات التأمين الاجتماعى للعمالة غير المنتظمة بالاتفاق مع وزير المالية ووزير التضامن الاجتماعى،والهيئة القومية للتأمين الاجتماعي،وفى حدود موارد الصندوق.<<CR>>
5- دعم وتطوير وتعزيز عمليات التشغيل اللازمة للعمالة غير المنتظمة.<<CR>>
6- تدريب العمالة غير المنتظمة المخاطبين بأحكام هذا القانون وتنمية مهاراتهم الفنية والمهنية فى مجالات العمل المختلفة بالتنسيق مع الوزارة المختصة.<<CR>>
7- المساهمة فى توفير أدوات العمل اللازمة لبعض فئات العمالة غير المنتظمة للقيام بأعمالهم.<<CR>>
8- المساهمة فى توفير سبل الانتقال والإعاشة والإقامة بمواقع العمل النائية.<<CR>>
9- المشاركة فى دعم الالتزام باشتراطات السلامة والصحة المهنية اللازمة وتأمين بيئة العمل.<<CR>>
10- تقديم البرامج الثقافية والرياضية،وإقامة المسابقات اللازمة لتنمية مهارات العمالة غير المنتظمة،فنيا وثقافيا،ورياضيا،وإعداد برامج الرحلات الترفيهية، والمصايف طبقًا للموارد المتاحة.<<CR>>
11- المساهمة فى تمويل عمليات حصر العمالة غير المنتظمة على المستوى القومى أو إعداد قواعد بياناتها.<<CR>>
12- إطلاق الحملات التوعوية إعلاميا للتعريف بحقوق العمالة غير المنتظمة وحقوقهم التأمينية والاجتماعية وغيرها.<<CR>>
13- إنشاء المنصات الإلكترونية اللازمة لتقديم خدمات الصندوق الرقمية.<<CR>>
14- إقامة مشروعات تنموية تستهدف الارتقاء بأوضاع العمالة غير المنتظمة، أو دمج العاملين فى القطاع غير الرسمى بالقطاع الرسمى على المستوى القومى، سواء منفردا أو بالتعاون مع الجهات والمنظمات الدولية أو الإقليمية المتخصصة بعد موافقة الجهات الوطنية المعنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,80,0,'0f2526e39e12b05f706fc418be160112','058fd633fa078d898fb6b57cdd60961c',replace($m208$يصدر الوزير المختص بالتشاور مع الوزراء المعنيين اللوائح المالية والإدارية للصندوق،ونظام تحصيل موارده،ولائحة الخدمات التى يقدمها،وقيمة الإعانات المالية الطارئة وضوابط استحقاقها،ومدتها،وحالات وقفها،والمستندات اللازمة لإثباتها،وطريقة وآليات صرفها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,82,0,'059d0e84591b462dcb59575a820788e4','873c7f5985aa81737755b0216a21d99e',replace($m208$تتكون موارد الصندوق مما يأتي:<<CR>>
1- نسبة لا تقل عن ) (%1 ولا تزيد على ) (%3 من قيمة الأجور الفعلية للعمالة غير المنتظمة فى قطاع المقاولات والتشييد والبناء،فإذا تعذر الوقوف على قيمة الأجور الفعلية تقدر قيمة الأجور حكما بنسبة لا تزيد على ) (%20 من قيمة العملية فى المقاولات العامة،ولا تزيد على ) (%45 فى عمليات الخدمات والمصنعية.<<CR>>
2- نسبة لا تقل عن ) (%1 ولا تزيد على ) (%3 من قيمة الأجور الفعلية للعمالة غير المنتظمة فى قطاع المناجم والمحاجر وما فى حكمها،فإذا تعذر الوقوف على قيمة الأجور الفعلية تقدر قيمة الأجور حكما بنسبة لا تزيد على ) (%15 من قيمة العملية.<<CR>>
3- اشتراك قيد لفئات العمالة غير المنتظمة الأخرى،لا يقل عن 20 جنيها ولا يزيد على 200 جنيه شهريا.<<CR>>
4- نسبة ) (%0,5 نصف فى المائة من قيمة مبيعات المنتجات الزراعية التى تشتريها الدولة.<<CR>>
5- مبلغ 100 جنيه عن كل طلب توثيق أو طلب صحة توقيع أو صحة نفاذ عقود بيع الأراضى الزراعية.<<CR>>
6- مبلغ لا يجاوز 50 جنيها عن كل رخصة قيادة مهنية تصدر لأول مرة أو عند تجديدها.<<CR>>
7- كافة أموال حسابات العمالة غير المنتظمة بمديريات العمل،وعوائد الأصول والودائع الخاصة بها.<<CR>>
8- التبرعات والهبات العينية والنقدية التى يوافق عليها مجلس الإدارة،وبما لا يخالف القوانين واللوائح المعمول بها.<<CR>>
9- عائد الخدمات التى يقدمها الصندوق بمقابل رمزى ) إن وجدت (.<<CR>>
10- عائد استثمار أموال الصندوق. ويصدر بتحديد فئات الرسوم والاشتراكات المشار إليها فى هذه المادة، وبما لا يزيد على الحد الأقصى المقرر،ومواعيد الوفاء بها،قرار من رئيس مجلس إدارة الصندوق.$m208$,'<<CR>>',chr(13))),
('law',14,2025,83,0,'08421d53c172dbb60f91b2c673c8c85f','7c1d76992cd9685fe3fbfb7431cba24b',replace($m208$يكون للصندوق حساب خاص لدى أحد البنوك التجارية المسجلة لدى البنك المركزى المصرى وموازنة مستقلة،تعد على نمط موازنات الهيئات العامة الاقتصادية،ويعد الصندوق سنويا القوائم الدالة على المركز المالى وفقًا لنظام المحاسبة المالية،وتبدأ السنة المالية للصندوق مع السنة المالية للدولة،وتنتهى بانتهائها،وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات،ويرحل فائض أمواله من سنة مالية إلى أخرى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,84,0,'7d2c024528ba5f867bb045f24034ed48','f762e9e67d52a24b1bea49aacb8c6db6',replace($m208$تعد أموال الصندوق أموالاً عامة،وبصفة خاصة فيما يتعلق بتطبيق أحكام قانون العقوبات.وللصندوق الحق فى اتخاذ إجراءات التنفيذ المباشر والحجز الإدارى وفقًا لأحكام القانون رقم 308 لسنة 1955 فى شأن الحجز الإدارى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,88,0,'51fa083bbee0ba160f3beaaaba49db5d','cc7ff92fbf4f607987e1bf3ecc2bc0a4',replace($m208$يعتبر عقد العمل غير محدد المدة منذ إبرامه فى الحالات الآتية:<<CR>>
1- إذا كان غير مكتوب.<<CR>>
2- إذا لم ينص العقد على مدته.<<CR>>
3- إذا كان مبرما لمدة محددة واستمر الطرفان فى تنفيذه بعد انتهاء هذه المدة دون اتفاق مكتوب بينهما.$m208$,'<<CR>>',chr(13))),
('law',14,2025,89,0,'8eeba73f1f26a33eeef71e346ea16a08','14904ead719316047d8e5d576e782c82',replace($m208$يلتزم صاحب العمل بتحرير عقد العمل كتابة باللغة العربية من أربع نسخ، يحتفظ صاحب العمل بنسخة،وتسلم نسخة للعامل،وتودع الثالثة بمكتب التأمين الاجتماعى المختص،والنسخة الرابعة بالجهة الإدارية المختصة. وإذا كان العامل أجنبيا ولا يجيد اللغة العربية يجوز أن يحرر عقد العمل باللغة العربية ولغة العامل،وفى حالة الاختلاف فى التفسير يعمل بعقد العمل المحرر باللغة العربية. ويجب أن يتضمن العقد على الأخص البيانات الآتية:<<CR>>
1- تاريخ بداية العقد.<<CR>>
2- اسم صاحب العمل وعنوان محل العمل.<<CR>>
3- اسم العامل ومؤهله،ومهنته،أو حرفته ورقمه التأميني،ومحل إقامته، وما يلزم لإثبات شخصيته.<<CR>>
4- طبيعة ونوع العمل محل العقد.<<CR>>
5- الأجر المتفق عليه،وطريقة وموعد أدائه،وسائر المزايا النقدية والعينية المتفق عليها. وإذا لم يوجد عقد مكتوب فيكون لكل من العامل وصاحب العمل الحق فى إثبات علاقة العمل،ومدته،وجميع الحقوق المترتبة عليها بطرق الإثبات كافة. ويعطى صاحب العمل للعامل إيصالاً بما يكون قد أودعه لديه من أوراق وشهادات.$m208$,'<<CR>>',chr(13))),
('law',14,2025,91,0,'6c8323ba6b7d708556e0f23650c52f6f','ca5c5c8cc3173df23495a8cae3a8525c',replace($m208$لا يجوز لصاحب العمل أن يخرج على الشروط المتفق عليها فى عقد العمل الفردى،أو اتفاقية العمل الجماعية،أو أن يكلف العامل بعمل غير المتفق عليه، إلا إذا دعت الضرورة إلى ذلك،منعا لوقوع حادث،أو لإصلاح ما نشأ عنه، أو فى حالة القوة القاهرة،على أن يكون ذلك بصفة مؤقتة،وله أن يكلف العامل بعمل غير المتفق عليه،إذا كان لا يختلف عنه اختلافًا جوهريا. وفى جميع الأحوال،لا يجوز المساس بحقوق العامل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,92,0,'1a300fee4801ef81923ca0d6e90e855c','fe9c96255cee1dbc63539981a1ea5f9b',replace($m208$على صاحب العمل أن ينشئ ملفًا ورقيا أو إلكترونيا لكل عامل يتضمن اسمه، ومهنته،ودرجة مهارته عند التحاقه بالعمل،ومحل إقامته،وحالته الاجتماعية، وتاريخ بداية خدمته،وأجره،وبيان ما يطرأ عليه من تطورات والجزاءات التى وقعت عليه،وبيان ما حصل عليه من إجازات،وأن يدرج أو يودع فى الملف صورة من عقد العمل،ومحاضر التحقيق إن وجدت،وتقارير رؤسائه عن عمله وفقًا لما تقرره لائحة المنشأة،وأية أوراق أخرى تتعلق بخدمة العامل وما يفيد التأمين عليه لدى الهيئة القومية للتأمين الاجتماعي،والكشف الطبى الابتدائى،ولا يجوز الاطلاع على هذه البيانات إلا لمن رخص له قانونًا بذلك،وأن يقدم هذا الملف إلى الجهة الإدارية المختصة أو المحكمة العمالية المختصة حسب الأحوال عند طلبه. وعليه أن يحتفظ بملف العامل ورقيا أو إلكترونيا لمدة خمس سنوات على الأقل تبدأ من تاريخ انتهاء علاقة العمل،وفى جميع الأحوال يجب الاحتفاظ بالملف عند وجود نزاع قضائى لحين الفصل فى الدعوى بحكم بات.$m208$,'<<CR>>',chr(13))),
('law',14,2025,93,0,'b345ee8dc1840317fc93e88ac3e2e2f8','c0d120ec0cdfa87ba184b2a31870932b',replace($m208$يلتزم صاحب العمل،بنقل العامل من الجهة التى تم التعاقد معه فيها إلى مكان العمل،كما يلتزم بإعادته إلى تلك الجهة خلال ثلاثة أيام من تاريخ انتهاء عقد العمل لأحد الأسباب المبينة فى هذا القانون،ولو كان خلال فترة الاختبار،إلا إذا رفض العامل كتابة العودة خلال المدة المشار إليها.<<CR>>
فإذا لم يقم صاحب العمل بذلك وجب على الجهة الإدارية المختصة،بناء على طلب العامل،إعادته إلى الجهة التى تم التعاقد معه فيها على نفقتها،ولهذه الجهة استرداد ما أنفقته بطريق الحجز الإدارى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,94,0,'b09640a36544fdb39fd40c7915a0273f','fed7790121e8cec4558ea1255acea267',replace($m208$إذا عهد صاحب العمل إلى صاحب عمل آخر بتأدية عمل من أعماله،أو جزء منها،وذلك فى منطقة عمل واحدة وجب على الأخير أن يسوى بين عماله،وعمال صاحب العمل الأصلى فى جميع الحقوق،ويكون الأخير متضامنًا معه فى الوفاء بجميع الالتزامات التى تفرضها أحكام هذا القانون. وفى جميع الأحوال،لا يجوز المساس بحقوق العامل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,96,0,'94e6380bf5a9052457f2c627eb6fd580','6303dc5628cd69e2004b4d591861e777',replace($m208$يعتبر نمطًا جديدا من أنماط العمل كل عمل يقوم به العامل بطريقة غير تقليدية، أيا كان شكل أداء العمل،أو طريقة تنفيذه،ويقدم لصالح صاحب العمل وتحت إدارته أو إشرافه،مقابل أجر أيا كانت صورته،ويعتبر نمطًا من أنماط العمل الجديدة على الأخص ما يأتي:<<CR>>
1- العمل عن بعد،وهو أداء العمل فى مكان يختلف عن المقر التقليدى للمنشأة، ويتم تنفيذه من خلال الوسائل التكنولوجية.<<CR>>
2- العمل بعض الوقت أو جزء منه،وهو العمل الذى يتم خلال ساعات عمل أقل من ساعات العمل الكاملة للعمل المماثل.<<CR>>
3- العمل المرن،وهو أداء العمل بنفس عدد ساعات العمل المطلوبة من العامل، فى أوقات غير متصلة يتم الاتفاق عليها بين طرفى علاقة العمل،أو بتغيير فى مواعيد ساعات العمل أو عددها أو مكان العمل.<<CR>>
4- تقاسم العمل،وهو العمل الذى يقوم بإنجازه أكثر من شخص ويتقاسمون فيه الأدوار أو الأوقات،كما يتقاسمون الأجر،وفقًا لما يتم الاتفاق عليه.<<CR>>
5- أى صور أخرى للعمل يصدر بتحديدها قرار من الوزير المختص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,97,0,'3a947c915c1d8a4cbc53df2857bd3721','62292f24c2ef8e55d0a6fc8415d72737',replace($m208$تسرى على علاقات العمل فى أنماط العمل الجديدة ما يسرى على علاقات العمل التقليدية،وذلك مع مراعاة طبيعة كل عمل وطريقة أدائه. كما يسرى على العاملين فى تلك الأنماط جميع الحقوق والواجبات التى تسرى على العاملين فى الأنماط التقليدية للعمل،وعلى الأخص الحماية الاجتماعية والضمان الاجتماعي،والحد الأدنى للأجر وطريقة حسابه،وضمان الحصول عليه،وإتاحة التدريب المهنى وبرامج تنمية المهارات،والحق فى المفاوضة الجماعية،والحرية النقابية وفقًا لأحكام قانون المنظمات النقابية العمالية وحماية حق التنظيم النقابى الصادر بالقانون رقم 213 لسنة 2017$m208$,'<<CR>>',chr(13))),
('law',14,2025,99,0,'16f31a9a091d9050b8f8a1212c168656','1c14b56a46377a6fbdae37433190ef37',replace($m208$يجب أن تكون علاقة العمل فى أنماط العمل الجديدة واضحة ومحددة فى عقد عمل مكتوب ورقيا أو إلكترونيا،ويجوز للعامل إثبات علاقة العمل بكافة طرق الإثبات.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,100,0,'02e6a9d34249ff7cdf6a5c91311832d0','760d30600bde80354926a786f51d15f1',replace($m208$يصدر الوزير المختص بالتشاور مع المنظمات النقابية العمالية ومنظمات أصحاب الأعمال القرارات اللازمة لتنظيم أنماط العمل الجديدة،وتحديد صورها والنماذج الاسترشادية لعقود ولوائح العمل،وطرق إثبات علاقة العمل،وآليات حصول الطرفين على حقوقهم،وذلك فى موعد لا يتجاوز ستة أشهر من تاريخ إصدار هذا القانون. ) الفصل الثالث ( الأجور$m208$,'<<CR>>',chr(13))),
('law',14,2025,101,0,'371709777e56d7b8b4ad3fb7f5dcdd69','53cfc54921c1cbe79bcba563d011af80',replace($m208$يشكل المجلس القومى للأجور برئاسة الوزير المعنى بشئون التخطيط والتنمية الاقتصادية والتعاون الدولى،وعضوية كل من: الوزير المختص،أو من ينيبه. الوزير المعنى بشئون التضامن الاجتماعي،أو من ينيبه. الوزير المعنى بشئون المالية،أو من ينيبه. الوزير المعنى بشئون الصناعة،أو من ينيبه. الوزير المعنى بشئون قطاع الأعمال العام،أو من ينيبه. الوزير المعنى بشئون التموين والتجارة الداخلية،أو من ينيبه. رئيس المجلس القومى للمرأة،أو من ينيبه. رئيس الجهاز المركزى للتعبئة العامة والإحصاء. الرئيس التنفيذى للهيئة العامة للاستثمار والمناطق الحرة. رئيس مجلس إدارة الهيئة القومية للتأمين الاجتماعي. رئيس الجهاز المركزى للتنظيم والإدارة،أو من ينيبه. رئيس المجلس القومى للأشخاص ذوى الإعاقة،أو من ينيبه. ستة أعضاء يمثلون منظمات أصحاب الأعمال،يتم اختيارهم من المنظمات الأكثر تمثيلاً،من حيث العضوية.<<CR>>
ستة أعضاء يمثلون المنظمات النقابية العمالية المعنية الأكثر تمثيلاً للعمال، ترشحهم منظماتهم،على أن يراعى تمثيل جميع مستويات المنظمات النقابية المعنية ما لم يكن ذلك متعذرا. ويجوز للمجلس الاستعانة بعدد كاف من الخبراء والمختصين أو الشخصيات العامة،وفقًا للموضوعات المطروحة على جدول الأعمال،دون أن يكون لهم صوت معدود فى المداولات.$m208$,'<<CR>>',chr(13))),
('law',14,2025,102,0,'8428173edf50af4038a179bcbda485dd','80245544cc8333121c92c51e4a4a8c8f',replace($m208$يختص المجلس المشار إليه فى المادة (101) من هذا القانون على وجه الخصوص بالآتي:<<CR>>
1- وضع الحد الأدنى لأجور العاملين فى كل القطاعات على المستوى القومى، بمراعاة احتياجات العمال وعائلاتهم وتكاليف المعيشة وتغيراتها،وتحقيق التوازن بين طرفى علاقة العمل،وضمان زيادة معدلات الإنتاج.<<CR>>
2- وضع الحد الأدنى للعلاوة الدورية السنوية،بما لا يقل عن النسبة المقررة فى المادة (12) من هذا القانون،والقواعد المنظمة لصرفها وفقًا لأحكام هذا القانون.<<CR>>
3- النظر فى طلبات أصحاب الأعمال للتخفيض أو الإعفاء من صرف العلاوة الدورية لظروف اقتصادية طارئة.<<CR>>
4- وضع المعايير والضوابط التى على أساسها يتم قبول أو رفض طلبات التخفيض أو الإعفاء من صرف العلاوة الدورية السنوية.<<CR>>
5- إخطار الوزارات المعنية بقبول أو رفض الطلبات المقدمة من ذوى الشأن بالتخفيض أو الإعفاء من صرف العلاوة الدورية السنوية. ويصدر رئيس مجلس الوزراء قرارا بتحديد نظام العمل بالمجلس،واختصاصاته الأخرى،فى موعد أقصاه ستة أشهر من تاريخ العمل بهذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,106,0,'20cd4c5503ab678e1144d2ee96ef8d72','d851d6ceecd1c18035485cf183d3a1dd',replace($m208$مع عدم الإخلال بالاختصاص المقرر لمحاكم مجلس الدولة،لكل ذى مصلحة الطعن على القرارات الصادرة عن المجلس القومى للأجور فى طلبات أصحاب الأعمال بالتخفيض أو الإعفاء من صرف العلاوة الدورية السنوية أمام المحكمة العمالية،وذلك خلال ثلاثين يوما من التاريخ المقرر لصرف العلاوة أو الإخطار بالقرار المطعون فيه،بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,107,0,'f432411e21f26d7baca3ea235243ed00','a7082f7f0147666eb7b7b3a052f0d3bc',replace($m208$يحدد الأجر وفقًا لعقد العمل الفردى،أو اتفاقية العمل الجماعية،أو لائحة المنشأة المعتمدة،فإذا لم يحدد بأى من هذه الطرق استحق العامل أجر المثل إن وجد،وإلا قدر الأجر طبقًا لعرف المهنة فى الجهة التى يؤدى فيها العمل،فإن لم يوجد عرف تولى قاضى الأمور الوقتية بالمحكمة العمالية المختصة تقدير الأجر وفقًا لمقتضيات العدالة،مع مراعاة أحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,108,0,'2f08e11a4b6adf049d08e60fd0beddeb','63b926fc1f85540299b6332172a83ede',replace($m208$تؤدى الأجور وغيرها من المبالغ المستحقة للعامل فى أحد أيام العمل وفى مكانه بالعملة المتداولة قانونًا،أو فى حساب العامل البنكى،مع مراعاة الأحكام التالية:<<CR>>
1- العمال المعينون بأجر شهرى تؤدى أجورهم مرة على الأقل فى الشهر.<<CR>>
2- إذا كان الأجر بالإنتاج أو بالعمولة واستلزم العمل مدة تزيد على أسبوعين، وجب أن يحصل العامل كل أسبوع على دفعة تحت الحساب تتناسب مع ما أتمه من العمل،وأن يؤدى له باقى أجره خلال الأسبوع التالى لتسليم ما كلف به.<<CR>>
3- فى غير ما ذكر فى البندين (1، 2) من هذه المادة تؤدى للعمال أجورهم مرة كل أسبوع على الأكثر ما لم يتفق على غير ذلك.<<CR>>
4- إذا انتهت علاقة العمل لأى سبب يؤدى صاحب العمل للعامل أجره وجميع المبالغ المستحقة له فى مدة لا تجاوز سبعة أيام من تاريخ مطالبة العامل بهذه المستحقات. وفى جميع الأحوال،يجب ألا يقل ما يحصل عليه العامل عن الحد الأدنى للأجور،ويحظر احتجاز أجر العامل أو جزء منه دون سند قانوني.$m208$,'<<CR>>',chr(13))),
('law',14,2025,109,0,'2e48ff362840b94fe7751906946da8c9','b6e6fe1eb0b90a0ac375a3c9423555f6',replace($m208$يكون حساب متوسط الأجر اليومى لعمال الإنتاج،أو العمال الذين يتقاضون أجورا أساسية مضافًا إليها عمولة أو نسبة مئوية على أساس متوسط ما تقاضاه العامل عن أيام العمل الفعلية فى السنة الميلادية السابقة،أو عن المدة التى اشتغلها إن قلت عن ذلك مقسوما على عدد أيام العمل الفعلية عن ذات الفترة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,110,0,'f63578e84dae81f6b2db0f93ea6d3021','eb44d154dce5f0a5353e0304efd220b5',replace($m208$يحظر على صاحب العمل أن ينقل العامل من فئة عمال الأجر الشهرى إلى فئة عمال اليومية،أو بالأجر الأسبوعى،أو بالساعة،أو بالإنتاج،إلا بعد موافقته، ويكون للعامل فى هذه الحالة جميع الحقوق التى اكتسبها فى المدة التى قضاها بالأجر الشهري.$m208$,'<<CR>>',chr(13))),
('law',14,2025,111,0,'7c835794a53522b889941cc9ae2a4b8d','479ffca6efb01305d3c076bfca49e1a6',replace($m208$إذا حضر العامل إلى مقر عمله فى الوقت المحدد للعمل،وكان مستعدا لمباشرة عمله،وحالت دون ذلك أسباب ترجع إلى صاحب العمل،اعتبر كأنه أدى عمله فعلاً واستحق أجره كاملاً،أما إذا حضر وحالت بينه وبين مباشرة عمله أسباب قهرية خارجة عن إرادة صاحب العمل استحق نصف أجره.$m208$,'<<CR>>',chr(13))),
('law',14,2025,113,0,'b1bfa239ef500cdd49df905f4f8f5bac','602f8b98b79b74c4757f07e7f09be952',replace($m208$لا يجوز لصاحب العمل أن يقتطع من أجر العامل أكثر من عشرة بالمائة، وفاء لما يكون قد أقرضه من مال أثناء سريان العقد،أو أن يتقاضى أية فائدة عن هذه القروض،ويسرى هذا الحكم على الأجور المدفوعة مقدما.$m208$,'<<CR>>',chr(13))),
('law',14,2025,114,0,'b91dbb84bb433412769168389bc2fa7b','ac58fa5888f4b62ebf753fbbed110c16',replace($m208$مع عدم الإخلال بأحكام قانون تنظيم بعض أوضاع وإجراءات التقاضى فى مسائل الأحوال الشخصية الصادر بالقانون رقم 1 لسنة، 2000 لا يجوز فى جميع الأحوال الاستقطاع أو الحجز،أو النزول عن الأجر المستحق للعامل لأداء أى دين إلا فى حدود خمسة وعشرين بالمائة من هذا الأجر،ويجوز رفع نسبة الخصم إلى خمسين بالمائة فى حالة دين النفقة. وعند التزاحم يقدم دين النفقة ثم ما يكون مطلوبا لصاحب العمل بسبب ما أتلفه العامل من أدوات أو مهمات أو استردادا لما صرف إليه بغير وجه حق أو ما وقع على العامل من جزاءات. ويشترط لصحة النزول عن الأجر فى حدود النسبة المقررة بهذه المادة أن تصدر به موافقة مكتوبة من العامل. وتحسب النسبة المشار إليها فى الفقرة الأولى من هذه المادة بعد استقطاع ضريبة الدخل على الأجر،وقيمة الاشتراكات والمبالغ المستحقة وفقًا لقانون التأمينات الاجتماعية والمعاشات المشار إليه،وما يكون صاحب العمل قد أقرضه للعامل فى حدود النسبة المنصوص عليها فى المادة (113) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,115,0,'5e7287d895a7bfe326688906620e678d','c648ad9b0462914517135c4e85d81052',replace($m208$لا تبرأ ذمة صاحب العمل من الأجر إلا إذا وقع العامل بما يفيد استلام الأجر فى السجل المعد لذلك،أو فى كشوف الأجور،أو إتمام تحويل أجره ومستحقاته إلى حسابه بأحد البنوك،ويلتزم صاحب العمل بإعطاء العامل بيانًا بمفردات أجره.$m208$,'<<CR>>',chr(13))),
('law',14,2025,116,0,'798575d4bfb5889038a5cf5f3ffa1da9','b2fd24cba1998dbbe181ab17f27f55ed',replace($m208$مع مراعاة حكم المادة (115) من هذا القانون،يسلم صاحب العمل إلى عماله من الأطفال أجورهم أو مكافآتهم أو غير ذلك مما يستحقونه قانونًا.ويكون هذا التسليم مبرئًا لذميه.<<CR>>
) الفصل الرابع ( ساعات العمل وفترات الراحة$m208$,'<<CR>>',chr(13))),
('law',14,2025,117,0,'91a7bdd8328c7cb96662f3cfe625f854','a674118bf089590fcc1efe0c91b44ca2',replace($m208$مع عدم الإخلال بأحكام القانون رقم 133 لسنة 1961 فى شأن تنظيم تشغيل العمال فى المنشآت الصناعية،لا يجوز تشغيل العامل تشغيلاً فعليا أكثر من ثمانى ساعات فى اليوم،أو ثمان وأربعين ساعة فى الأسبوع،ولا تدخل فيها الفترات المخصصة لتناول الطعام والراحة. ويجوز بقرار من الوزير المختص تخفيض الحد الأقصى لساعات العمل لبعض فئات العمال،أو فى بعض الصناعات أو الأعمال التى يحددها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,120,0,'c0e2b59f65b0e8ee426768264adf900b','43fc5aea07de5abbfe3cfb61af7682e2',replace($m208$يجب تنظيم العمل بالمنشأة بحيث يحصل كل عامل على راحة أسبوعية لا تقل عن أربع وعشرين ساعة كاملة بعد ستة أيام عمل متصلة على الأكثر،وفى جميع الأحوال تكون الراحة الأسبوعية مدفوعة الأجر.<<CR>>
واستثناء من الحكم الوارد فى الفقرة الأولى من هذه المادة،يجوز فى الأماكن البعيدة عن العمران،وفى الأعمال التى تتطلب طبيعة العمل،أو ظروف التشغيل فيها استمرار العمل تجميع الراحات الأسبوعية المستحقة للعامل عن مدة لا تجاوز ثمانية أسابيع،وتحدد لائحة تنظيم العمل والجزاءات قواعد الحصول على الراحات الأسبوعية المجمعة،وتضع المنشآت التى يقل عدد عمالها عن عشرة عمال قواعد تنظيم الراحات الأسبوعية المجمعة بها وفقًا للقرارات التى تصدرها المنشأة. ويراعى فى حساب مدة الراحات الأسبوعية المجمعة أن تبدأ من ساعة وصول العمال إلى أقرب موقع به مواصلات وتنتهى ساعة العودة إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,121,0,'f17c5df9af61cb253a2f213ce429941d','f85d900a061f0e687d177763e8504321',replace($m208$يجوز لصاحب العمل عدم التقيد بالأحكام الواردة بالمواد )، 119، 118، 117 (120 من هذا القانون،إذا كان التشغيل بقصد مواجهة ضرورات عمل غير عادية، أو ظروف استثنائية،ويشترط فى هذه الحالات إبلاغ الجهة الإدارية المختصة فى خلال سبعة أيام من وقوع ظروف العمل غير العادية أو الظروف الاستثنائية بمبررات التشغيل الإضافى والمدة اللازمة لإتمام العمل. وفى هذه الحالة يستحق العامل بالإضافة إلى أجره عن ساعات العمل الأصلية، أجرا عن ساعات التشغيل الإضافية حسبما يتم الاتفاق عليه فى عقد العمل الفردى أو الجماعى،بحيث لا يقل عن الأجر الذى يستحقه العامل مضافًا إليه ) (%35 عن ساعة العمل النهارية،و ) (%70 عن ساعة العمل الليلية تحسب على أساس أجر ساعة عمله الأصلية،فإذا وقع التشغيل فى يوم الراحة استحق العامل مثل أجره تعويضا عن هذا اليوم،ويمنحه صاحب العمل يوما آخر عوضا عنه خلال الأسبوع التالي. وفى جميع الأحوال،لا يجوز أن تزيد ساعات وجود العامل بالمنشأة على اثنتى عشرة ساعة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,122,0,'70b817e45a04b6de8f220c75913f73c7','af4691bf06fcbec6e340f57a1ec74e8b',replace($m208$على صاحب العمل أن يضع بالمداخل الرئيسية التى يستعملها العمال،أو فى مكان ظاهر بالمنشأة جدولاً ببيان يوم الراحة الأسبوعية،وساعات العمل،وفترات الراحة المقررة لكل العاملين،وما يطرأ على هذا الجدول من تعديل مع إخطار الجهة الإدارية المختصة بصورة من هذا الجدول،أو ما يطرأ عليه من تعديل خلال سبعة أيام من تنفيذه على الأكثر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,123,0,'42840031ad24e86a737d841923238ce3','5cf4c2891a2de5081409b9b9e8c799ec',replace($m208$لا تسرى أحكام المواد ) / 120، 119، 118، 117 فقرة ثانية( من هذا القانون على الفئات الآتية:<<CR>>
1- الوكلاء المفوضين عن صاحب العمل.<<CR>>
2- العمال المشتغلين بالأعمال التجهيزية والتكميلية التى يتعين إنجازها قبل أو بعد انتهاء العمل.<<CR>>
3- العمال المخصصين للحراسة والنظافة. ويحدد الحد الأقصى لساعات العمل الفعلية والإضافية للأعمال المشار إليها فى البندين (2، 3) من الفقرة الأولى من هذه المادة بقرار من الوزير المختص، ويستحق العمال فى هذه الحالة أجرا إضافيا طبقًا لنص المادة (121) من هذا القانون. ) الفصل الخامس ( الإجازات$m208$,'<<CR>>',chr(13))),
('law',14,2025,124,0,'b0c632904608a3e73c4c9e17abe21374','78135af79a1d9dcf37b03112b00c7449',replace($m208$يستحق العامل إجازة سنوية بأجر،لا يدخل فى حسابها أيام عطلات الأعياد والمناسبات الرسمية والراحة الأسبوعية،وذلك على الوجه الآتى:<<CR>>
1- خمسة عشر يوما فى السنة الأولى.<<CR>>
2- واحد وعشرون يوما اعتبارا من السنة الثانية.<<CR>>
3- ثلاثون يوما لمن أمضى عشر سنوات كاملة لدى صاحب عمل أو أكثر، أو لمن تجاوزت سنه خمسين عاما.<<CR>>
4- خمسة وأربعون يوما للأشخاص ذوى الإعاقة والأقزام. وإذا قلت مدة خدمة العامل عن سنة تكون إجازته بنسبة المدة التى قضاها في العمل بشرط أن يكون قد أمضى ستة أشهر على الأقل فى خدمة صاحب العمل. وفى جميع الأحوال،تزاد مدة الإجازة السنوية بمقدار سبعة أيام للعمال الذين يعملون فى الأعمال الخطرة،أو المضرة بالصحة،أو فى المناطق النائية،والتى يصدر بتحديدها قرار من الوزير المختص بعد أخذ رأى الجهات المعنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,125,0,'0f15d1eb21fcee834e12889edf4a624a','0ead5bb4667f372be0061c2430b0e4f0',replace($m208$يحدد صاحب العمل مواعيد الإجازة السنوية حسب مقتضيات العمل وظروفه، ولا يجوز قطعها إلا لأسباب قوية تقتضيها مصلحة العمل. ولا يجوز للعامل النزول عن إجازته،ويلتزم بالقيام بالإجازة فى التاريخ، والمدة التى حددها صاحب العمل وتم إخطاره بها،وإذا رفض العامل كتابة القيام بالإجازة سقط حقه فى اقتضاء مقابلها. وفى جميع الأحوال،يجب أن يحصل العامل على إجازة سنوية مدتها خمسة عشر يوما،منها ستة أيام متصلة على الأقل،ويلتزم صاحب العمل بتسوية رصيد الإجازات،أو الأجر المقابل له كل ثلاث سنوات على الأكثر،فإذا انتهت علاقة العمل قبل استنفاد العامل رصيد إجازته السنوية استحق الأجر المقابل لهذا الرصيد. ولا يجوز تجزئة الإجازة أو ضمها أو تأجيلها بالنسبة للأطفال والأشخاص ذوى الإعاقة والأقزام.$m208$,'<<CR>>',chr(13))),
('law',14,2025,126,0,'89a9f2d4f1e7804056a04fdfa9912002','db3fc774ee1785199cfd4ad8589b25ca',replace($m208$للعامل الحق فى تحديد موعد إجازته السنوية إذا كان متقدما لأداء الامتحان فى إحدى مراحل التعليم بشرط أن يخطر صاحب العمل قبل قيامه بالإجازة بخمسة عشر يوما على الأقل. وللعامل الحق فى الحصول على إجازة دراسية بأجر عن أيام الامتحان الفعلية لا تحتسب من رصيد إجازاته السنوية،ويشترط لذلك:<<CR>>
1- إخطار صاحب العمل قبل القيام بالإجازة بعشرة أيام على الأقل.<<CR>>
2- إثبات ما يفيد دخوله الامتحان فعليا.$m208$,'<<CR>>',chr(13))),
('law',14,2025,129,0,'a4a7213c30223c4b4ef7ba11a06ee53d','bfa536154c2a2d7ae85c592005ccef28',replace($m208$للعامل الحق فى إجازة بأجر فى العطلات والأعياد والمناسبات التى يصدر بتحديدها قرار من الوزير المختص،وتسرى بالنسبة للأعياد الدينية لغير المسلمين أحكام قرار مجلس الوزراء الصادر فى هذا الشأن. ولصاحب العمل تشغيل العامل فى هذه الأيام،إذا اقتضت ظروف العمل ذلك، ويستحق العامل فى هذه الحالة بالإضافة إلى أجره عن هذا اليوم مثلى هذا الأجر أو أن يمنح العامل يوما آخر عوضا عنه بناء على طلب كتابى من العامل يودع بالملف الخاص به.$m208$,'<<CR>>',chr(13))),
('law',14,2025,131,0,'51e4426bb06655ef3b7b56f9b94c4fc8','fa9ba29da040a6813adce6073546ac5b',replace($m208$للعامل الذى يثبت مرضه،أو إصابته على نحو يحول بينه وبين أداء عمله الحق فى إجازة مرضية تحددها الجهة الطبية المختصة،ويستحق العامل خلالها تعويضا عن الأجر،تحدد نسبته ومدته،وفقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ويكون للعامل الذى يثبت مرضه فى المنشآت الصناعية التى يسرى فى شأنها قانون تيسير منح تراخيص المنشآت الصناعية الصادر بالقانون رقم 15 لسنة، 2017 الحق فى إجازة مرضية كل ثلاث سنوات تقضى فى الخدمة على أساس ثلاثة أشهر بأجر،<<CR>>
ثم ستة أشهر بأجر يعادل ) (%85 من أجره،ثم ثلاثة أشهر بأجر يعادل ) (%75 من أجره، وذلك إذا قررت الجهة الطبية المختصة احتمال شفائه. ويخصم من الأجر الذى يلتزم به صاحب العمل،ما يلتزم بأدائه نظام التأمين الاجتماعى من تعويض عن الأجر. وللعامل أن يستفيد من متجمد إجازاته السنوية إلى جانب ما يستحقه من إجازة مرضية،كما له أن يطلب تحويل الإجازة المرضية إلى إجازة سنوية،إذا كان له رصيد يسمح بذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,133,0,'d80b751ed9eedf8cc555b0818c747f7d','aa20df37bc25a905627cb9cbd32d6224',replace($m208$تثبت عدم اللياقة للخدمة صحيا وفقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ) الفصل السادس ( واجبات العمال ومساءلتهم$m208$,'<<CR>>',chr(13))),
('law',14,2025,134,0,'071a3e61e0c65bfa711a7e9a1df21868','24831166844c2b6126cd1736295b7c96',replace($m208$يجب على العامل ما يأتي:<<CR>>
1- أن يؤدى بنفسه الواجبات المنوطة به بدقة وأمانة،وذلك وفقًا لما هو محدد بالقانون ولوائح العمل،وعقود العمل الفردية والجماعية،وأن ينجزها فى الوقت المحدد،وأن يبذل فيها عناية الشخص المعتاد.<<CR>>
2- أن ينفذ أوامر وتعليمات صاحب العمل الخاصة بتنفيذ الواجبات التى تدخل فى نطاق العمل المنوط به،إذا لم يكن فى هذه الأوامر والتعليمات ما يخالف العقد أو القانون أو اللوائح أو الآداب العامة،ولم يكن فى تنفيذها ما يعرض للخطر.<<CR>>
3- أن يحافظ على مواعيد العمل،وأن يتبع الإجراءات المقررة فى حالة التغيب عن العمل،أو مخالفة مواعيده.<<CR>>
4- أن يحافظ على ما يسلمه إليه صاحب العمل من أدوات أو أجهزة أو مستندات أو أى أشياء أخرى،وأن يقوم بجميع الأعمال اللازمة لسلامتها،ويلتزم بأن يبذل فى ذلك عناية الشخص المعتاد.<<CR>>
5- أن يحسن معاملة عملاء صاحب العمل.<<CR>>
6- أن يحترم رؤساءه وزملاءه فى العمل،وأن يتعاون معهم بما يحقق مصلحة المنشأة التي يعمل بها.<<CR>>
7- أن يحافظ على كرامة العمل،وأن يتبع السلوك القويم.<<CR>>
8- أن يراعى النظم الموضوعة للمحافظة على سلامة المنشأة وأمنها.<<CR>>
9- أن يحافظ على أسرار العمل،فلا يفشى المعلومات المتعلقة بالعمل متى كانت سرية بطبيعتها،أو وفقًا للتعليمات الكتابية الصادرة عن صاحب العمل.<<CR>>
10- أن يخطر جهة العمل بالبيانات الصحيحة المتعلقة بمحل إقامته وحالته الاجتماعية وموقفه من أداء الخدمة العسكرية،والبيانات الأخرى التى تتطلب القوانين أو النظم إدراجها فى السجل الخاص به،وبكل تغيير يطرأ على بيان من البيانات السابقة فى المواعيد المحددة لذلك.<<CR>>
11- أن يتبع النظم التى يضعها صاحب العمل لتنمية وتطوير مهاراته وخبراته مهنيا وثقافيا،أو لتأهيله للقيام بعمل يتفق،أو يتناسب مع عمله والتطور التقنى داخل المنشأة،وذلك بالاشتراك مع المنظمة النقابية العمالية المعنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,135,0,'4559a163a37968a6d10f66a5be2f7121','01b6e714d51a4ccbde13a024af857d08',replace($m208$مع عدم الإخلال بأحكام القانون رقم 137 لسنة 1958 فى شأن الاحتياطات الصحية للوقاية من الأمراض المعدية بالإقليم المصرى،ومع مراعاة أحكام المادتين )132 و (138 من هذا القانون يلتزم العامل بالخضوع للاختبارات الطبية عن تعاطى المواد المخدرة أو الأمراض المعدية حينما يطلب منه صاحب العمل ذلك وعلى نفقته،ويتم الاختبار الطبى بالهيئة العامة للتأمين الصحى أو المعامل المركزية بوزارة الصحة.<<CR>>
وتتم الاختبارات الطبية عن تعاطى المواد المخدرة والتظلم منها وفقًا للتنظيم والإجراءات والضمانات التى يصدر بها قرار من الوزير المختص،على أن يكون من بينها إجراء فحص لذات العينة فى ذات يوم سحبها،وفى حالة اختلاف نتيجتى الفحص يتم إجراء تحليل توكيدى لدى أى من الجهتين المشار إليهما فى الفقرة الأولى من هذه المادة. فإذا تأكدت إيجابية العينة يتم إحالة العامل للمحكمة العمالية المختصة لإعمال شئونها. وفى جميع الأحوال،يلتزم صاحب العمل باتباع السرية فى إجراء الكشف الطبى وعدم الإفصاح عن الوضع الصحى للعامل بناء على هذه الاختبارات.$m208$,'<<CR>>',chr(13))),
('law',14,2025,136,0,'a6d7859d5d9a283b2ed9a99d4c62fd1c','9bf58aed071fdec972c95a365a945a8f',replace($m208$يحظر على العامل أن يقوم بنفسه،أو بواسطة غيره بالأعمال الآتية:<<CR>>
1- الاحتفاظ لنفسه بأى ورقة أو مستند خاص بالعمل أو أى بيانات إلكترونية أو أى من وسائل التأمين الإلكترونية الخاصة بالعمل سواء بنفسه،أو بتمكين الغير من الحصول على أى منها أو على أية معلومات تخص العمل.<<CR>>
2- العمل لدى الغير سواء بأجر،أو دون أجر إذا كان فى قيامه بهذا العمل ما يخل بحسن أدائه لعمله أو يمكن الغير،أو يساعده على التعرف على أسرار المنشأة، أو منافسة صاحب العمل.<<CR>>
3- ممارسة نشاط مماثل للنشاط الذى يمارسه صاحب العمل أثناء قيام علاقة العمل أو الاشتراك فى نشاط من هذا القبيل،سواء بصفته شريكًا،أو عاملاً.<<CR>>
4- الاقتراض من عملاء صاحب العمل،أو ممن يمارسون نشاطًا مماثلاً للنشاط الذى يمارسه صاحب العمل،ولا يسرى هذا الحظر على الاقتراض من البنوك أو غيرها من الجهات المرخص لها بذلك.<<CR>>
5- طلب أو قبول هدايا،أو مكافآت،أو عمولات،أو مبالغ،أو أشياء أخرى بأية صفة كانت بمناسبة قيامه بواجباته بغير موافقة صاحب العمل.<<CR>>
6- جمع تبرعات نقدية أو عينية،أو توزيع منشورات،أو جمع توقيعات، أو تنظيم اجتماعات داخل مكان العمل دون موافقة صاحب العمل كتابة،مع مراعاة ما تقضى به أحكام قانون المنظمات النقابية العمالية وحماية حق التنظيم النقابى المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,137,0,'f7380473deb8dba26765b1ef416bf4ab','b9d2f8839903ac98c585ecb30668d485',replace($m208$على كل صاحب عمل يستخدم عشرة عمال فأكثر أن يعد لائحة بقواعد تنظيم العمل وفقًا لطبيعة النشاط،على أن تتضمن على الأخص نظم الترقى،والنقل، والأجور،والمخالفات التى تمثل خروجا على مقتضى الواجب الوظيفى،والجزاءات التأديبية،خلال ستين يوما من بداية عمل المنشأة أو تاريخ توافر هذا النصاب، أو نفاذ هذا القانون،بحسب الأحوال،وعليه تسليم الجهة الإدارية المختصة نسخة من اللائحة لمراجعتها والتصديق عليها وعلى الجهة الإدارية المختصة استطلاع رأى المنظمة النقابية العمالية المختصة والتى يتعين عليها إبداء رأيها إلى الجهة الإدارية المختصة فى موعد لا يتجاوز خمسة عشر يوما من تاريخ تسلمها للائحة وإلا اعتبر ذلك بمثابة موافقة على اللائحة،فإذا لم تقم الجهة الإدارية المختصة بالتصديق، أو الاعتراض على اللائحة خلال ثلاثين يوما من تاريخ استلامها اعتبرت اللائحة نافذة. وعلى صاحب العمل أن يعلق هذه اللائحة فى مكان ظاهر بالمنشأة وفروعها ومواقع عملها. وللوزير المختص أن يصدر قرارا بالقواعد العامة لهذه اللائحة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,138,0,'396c8bc059c36b80544654b9f98e2831','ed1bfcf859c8932312b5f81b450e0738',replace($m208$يشترط فى الفعل الذى تجوز مساءلة العامل عنه تأديبيا أن يكون ذا صلة بالعمل، وتحدد لائحة الجزاءات المخالفات والجزاءات المقررة لها،وفقًا لما هو منصوص عليه فى المادة (139) من هذا القانون وبما يحقق تناسب الجزاء مع المخالفة. ولا يجوز توقيع جزاء تأديبى على العامل بعد مضى ثلاثين يوما من تاريخ الانتهاء من التحقيق فى المخالفة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,139,0,'b6ab80a84b3a67a73eb6b34a36838440','cab96fff4da15f6a44e20864c7a18698',replace($m208$الجزاءات التأديبية التى يجوز توقيعها على العامل وفقًا للوائح تنظيم العمل والجزاءات فى المنشأة هي:<<CR>>
1- الإنذار الكتابي.<<CR>>
2- الخصم من الأجر الأساسي.<<CR>>
3- تأجيل موعد استحقاق العلاوة السنوية لمدة لا تجاوز ثلاثة أشهر.<<CR>>
4- الحرمان من جزء من العلاوة السنوية،بما لا يجاوز نصفها.<<CR>>
5- تأجيل الترقية عند استحقاقها لمدة لا تزيد على سنة.<<CR>>
6- خفض الأجر الأساسى بمقدار علاوة على الأكثر.<<CR>>
7- الخفض إلى وظيفة فى الدرجة الأدنى مباشرة،دون تخفيض الأجر.<<CR>>
8- الفصل من الخدمة وفقًا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,140,0,'f6aa3b9ed7b18fcca3a718d1efdd23d0','a30aea53e478f41841d5702029a01313',replace($m208$لا يجوز لصاحب العمل توقيع أكثر من جزاء عن المخالفة الواحدة،كما لا يجوز له الجمع بين اقتطاع جزء من أجر العامل تطبيقًا لحكم المادة (139) من هذا القانون وبين أى جزاء مالي،إذا زاد ما يجب اقتطاعه على أجر خمسة أيام فى الشهر الواحد.$m208$,'<<CR>>',chr(13))),
('law',14,2025,141,0,'d4a6bd441c2eb7c1189cc048f070df73','08b8a0ffb4e83c0a8b3a314ab78dd52c',replace($m208$لا يجوز توقيع جزاء على العامل إلا بعد إبلاغه كتابة بما نسب إليه وسماع أقواله، وتحقيق دفاعه وإثبات ذلك فى محضر يودع فى ملفه الخاص،على أن يبدأ التحقيق خلال سبعة أيام على الأكثر من تاريخ اكتشاف المخالفة ولا يتجاوز ثلاثة أشهر من تاريخ بداية التحقيق ويجوز أن تزاد ثلاثة أشهر أخرى إذا تكشف أثناء التحقيق وقائع أو مستندات جديدة،وللمنظمة النقابية التى يتبعها العامل أن تندب ممثلاً عنها لحضور التحقيق. ويجوز فى المخالفات التى يعاقب عليها بالإنذار،أو الخصم من الأجر الأساسى الذى لا يزيد مقداره على أجر يوم واحد،أن يكون التحقيق شفاهة،على أن يثبت مضمونه في القرار الذى يصدر بتوقيع الجزاء. وفى جميع الحالات،يشترط أن يكون القرار الصادر بتوقيع الجزاء مسببا.$m208$,'<<CR>>',chr(13))),
('law',14,2025,145,0,'08aeaf02e47889d7582c1124159ad1bf','3a5583ec34d372fff02d7bc8a2f1a4be',replace($m208$لصاحب العمل أن يوقف العامل عن عمله مؤقتًا بموجب قرار مكتوب لمدة لا تزيد على ستين يوما مع صرف أجره كاملاً،وذلك فى الحالات الآتية:<<CR>>
1- إذا أحيل العامل للتحقيق بسبب مخالفة ارتكبها داخل مقر العمل،واقتضت مصلحة التحقيق ذلك.<<CR>>
2- إذا أتُهم العامل بارتكاب جناية أو جنحة مخلة بالشرف أو الأمانة أو الآداب العامة،أو أى جنحة أخرى داخل محل العمل.<<CR>>
3- إذا طلب صاحب العمل من المحكمة العمالية المختصة فصل العامل من الخدمة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,146,0,'1406837be3e9a085635e7a7ec2ce9f23','7ce1a55382794bc7fab0b5e73ec47f50',replace($m208$للعامل التظلم من قرار وقفه عن العمل الصادر وفقًا للبندين (1، 2) من المادة (145) من هذا القانون بموجب عريضة تقدم لقاضى الأمور الوقتية بالمحكمة العمالية المختصة، رار صدور الق ه ب اره،أو علم اريخ إخط ن ت ام م ة أي لال ثلاث ك خ وذل المتظلم منه. وعلى القاضى الفصل فى هذا التظلم فى اليوم التالى لتقديمه على الأكثر،فإذا قضى بعدم صحة القرار الصادر بالوقف،قضى بعودته للعمل مرة أخرى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,147,0,'ba1c74a3c3056a3533a35d684f1456ed','c76a15061bbcb5bb83e3dfbe27fa8ff7',replace($m208$لصاحب العمل أن يطلب من قاضى الأمور الوقتية بالمحكمة العمالية المختصة مد فترة الإيقاف عن العمل لمدة أو لمدد أخرى مع صرف نصف أجر العامل وذلك قبل انتهاء مدة الإيقاف بعشرة أيام. وعلى قاضى الأمور الوقتية البت فى هذا الطلب قبل انتهاء فترة الإيقاف،فإذا لم يصدر قراره خلال هذه المدة ولم يعد العامل إلى عمله،يستمر إيقاف العامل مع صرف الأجر كاملاً لحين البت فى الطلب فإذا قضى برفض الطلب يعاد لعمله فور انتهاء مدة إيقافه الأخيرة. فإذا كان الوقف لأحد الأسباب الواردة بالبند (2) من المادة (145) من هذا القانون،ورأت السلطة المختصة بالاتهام حفظ التحقيق،أو إصدار أمر بأن لا وجه لإقامة الدعوى الجنائية،أو قدم العامل للمحاكمة الجنائية وقضى ببراءته،وجبت إعادته إلى عمله مع صرف ما لم يصرف له من مستحقات عن فترة الإيقاف،وإلا اعتبر عدم إعادته للعمل فصلاً تعسفيا.$m208$,'<<CR>>',chr(13))),
('law',14,2025,148,0,'ba16985b202969d0581697c6f84b57ae','79307ba6b4344cff0479f8144ea4fcf5',replace($m208$يكون الاختصاص بتوقيع جزاء الفصل من العمل للمحكمة العمالية المختصة، ويكون توقيع باقى الجزاءات التأديبية لصاحب العمل،أو من يفوضه لذلك، ويكون لمدير المنشأة توقيع جزائى الإنذار الكتابى،والخصم من الأجر لمدة لا تجاوز ثلاثة أيام.<<CR>>
وفى جميع الأحوال،لا يجوز فصل العامل إلا إذا ارتكب خطأ جسيما، ويعتبر من قبيل الخطأ الجسيم الحالات الآتية:<<CR>>
1- إذا ثبت انتحال العامل شخصية غير صحيحة أو قدم مستندات مزورة.<<CR>>
2- إذا ثبت ارتكاب العامل لخطأ نشأت عنه أضرار جسيمة لصاحب العمل، بشرط أن يبلغ صاحب العمل الجهات المختصة بالواقعة،أو الحادث خلال أربع وعشرين ساعة من وقت علمه بوقوعه.<<CR>>
3- إذا ثبت تكرار عدم مراعاة العامل التعليمات اللازم اتباعها لسلامة العمال، أو المنشأة،بشرط أن تكون هذه التعليمات مكتوبة،ومعلنة فى مكان ظاهر، رغم التنبيه عليه كتابة بمراعاة ذلك.<<CR>>
4- إذا ثبت أن العامل أفشى أسرار المنشأة التى يعمل بها،وأدى ذلك إلى إحداث أضرار جسيمة بالمنشأة.<<CR>>
5- إذا ثبت قيام العامل بمنافسة صاحب العمل فى ذات نشاطه.<<CR>>
6- إذا ثبت وجود العامل فى حالة سكر بين أو متأثرا بما تعاطاه من مادة مخدرة أثناء ساعات العمل.<<CR>>
7- إذا ثبت اعتداء العامل على صاحب العمل،أو المدير العام،وكذلك إذا وقع منه اعتداء جسيم على أحد رؤسائه أثناء العمل،أو بسببه. وفى جميع الأحوال،لا يجوز الفصل من الخدمة إلا وفقًا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,149,0,'d90e4b52fd62d33a9929ee10727e06c6','0fbdfc843ef8a53befe90673ea6eb792',replace($m208$مع عدم الإخلال بحق التقاضي،إذا نشأ نزاع فردى بين صاحب العمل والعامل بشأن تطبيق أحكام هذا القانون،أو أى من القوانين ذات الصلة كان لأى منهما خلال عشرة أيام من تاريخ نشوء النزاع أن يطلب تسويته وديا بمعرفة لجنة تشكل على النحو الآتي:<<CR>>
1- مدير مديرية العمل،أو من ينيبه )رئيسا(.<<CR>>
2- العامل،أو من يمثله )عضوا(.<<CR>>
3- صاحب العمل،أو من يمثله )عضوا(. ولرئيس اللجنة أن يستعين بذوى الخبرة حسب الموضوع المعروض.<<CR>>
ويجب أن تنتهى اللجنة من أعمالها خلال واحد وعشرين يوما من تاريخ تقديم الطلب،فإذا تمت التسوية الودية،يثبت رئيس اللجنة ذلك فى محضر يوقعه طرفا النزاع،ويلحق بمحضر الجلسة التى تم فيها،ويحال إلى قاضى الأمور الوقتية بالمحكمة العمالية المختصة،ويكون قابلاً للتنفيذ بالأمر الذى يصدره وينتهى به النزاع فى حدود ما تمت التسوية الودية فيه. ويصدر الوزير المختص قرارا بنظام عمل اللجنة والنماذج والسجلات التى تستعين بها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,150,0,'54e6632d2f1b84d3d8c0ed73e2bce9ac','6260f797dcbd1823a2421692f9a1a898',replace($m208$إذا لم تتم تسوية النزاع وديا يحرر رئيس اللجنة محضرا بما تم،ويوقع منه ومن طرفى النزاع،ويثبت ما تم من أعمال وما تلقته اللجنة من مستندات ورأيها فى موضوع النزاع،ويحال إلى المحكمة العمالية المختصة بناء على طلب أى من طرفيه، ويحدد قلم كتاب المحكمة جلسة لنظر النزاع فى مدة لا تجاوز عشرين يوما من تاريخ ورود الطلب،وعليه إعلان طرفى النزاع بها. فإذا كان موضوع النزاع يتعلق بفصل العامل،وجب على المحكمة أن تفصل فى هذا الطلب بصفة مستعجلة خلال ثلاثة أشهر من تاريخ أول جلسة،فإذا رأت من ظاهر الأوراق صحة طلب العامل،ألزمت صاحب العمل أن يؤدى إلى العامل ما يعادل أجره من تاريخ الفصل،وبحد أقصى ستة أشهر،ويكون قرارها نهائيا. وتخصم المبالغ التى استوفاها العامل نفاذًا لقرار المحكمة من مبلغ التعويض الذى يحكم به أو أى مبالغ أخرى مستحقة له قبل صاحب العمل،مع مراعاة نص المادة (143) من هذا القانون. فإذا كان فصل العامل بسبب النشاط النقابي،قضت المحكمة بإعادته إلى عمله إذا طلب ذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,151,0,'a77e3a4b8379cf41a7119326e2f60c6a','0ed53b2d85325ce2a8205df34d17d626',replace($m208$إذا تسبب العامل بخطئه،أو بمناسبة عمله فى فقد،أو إتلاف مهمات،أو آلات أو خامات،أو منتجات أو غيرها،يملكها صاحب العمل،أو كانت فى عهدته التزم بأداء قيمة ما فقد،أو أتلف.<<CR>>
ولصاحب العمل بعد إجراء التحقيق وإخطار العامل أن يبدأ باقتطاع المبلغ المشار إليه من أجره،على ألا يزيد ما يقتطع لهذا الغرض على أجر خمسة أيام فى الشهر الواحد. ويجوز للعامل أن يتظلم أمام المحكمة العمالية المختصة من تقدير صاحب العمل وفقًا للمدد والإجراءات المحددة فى هذا القانون. فإذا لم يقض لصاحب العمل بالمبلغ الذى قدره،للإتلاف أو قضى له بأقل منه، وجب عليه رد ما اقتطع دون وجه حق خلال سبعة أيام من تاريخ صدور الحكم. ولا يجوز لصاحب العمل أن يستوفى مستحقاته بطريق الاقتطاع وفقًا لحكم هذه المادة،فيما زاد على أجر شهرين.$m208$,'<<CR>>',chr(13))),
('law',14,2025,153,0,'a3edb452f68d5ba045df0ba5bfda91a0','40ae014c4a7b1a03960f4fd20cde7848',replace($m208$يجب على صاحب العمل أن يمسك سجلاً ورقيا أو إلكترونيا لقيد الجزاءات المالية الموقعة على العمال،مع بيان سبب توقيعها واسم العامل ومقدار أجره، وأن يفرد لحصيلتها حسابا خاصا للصرف على عمال المنشأة فى الأغراض الاجتماعية والثقافية والرياضية،ولا يجوز صرف هذه المبالغ للوفاء بالالتزامات المنصوص عليها فى المادة (272) من هذا القانون وتوزع حصيلة تلك الأموال عند تصفية المنشأة بالتساوى على العمال الموجودين بها وقت التصفية. ) الفصل السابع ( انتهاء علاقة العمل الفردية$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,154,0,'2052196598134897e794bb746abf0d79','872305f35d2f698bfba30d46d67d5b1a',replace($m208$مع عدم الإخلال بما نصت عليه المواد (87، 88، 95) من هذا القانون، ينتهى عقد العمل محدد المدة بانقضاء مدته.<<CR>>
فإذا أبرم العقد أو جدد لمدة تزيد على خمس سنوات،جاز للعامل إنهاؤه دون تعويض عند انقضاء خمس سنوات،وذلك بعد إخطار صاحب العمل قبل الإنهاء بثلاثة أشهر. وتسرى أحكام الفقرة الثانية من هذه المادة على حالات إنهاء العامل للعقد بعد انقضاء المدة المذكورة. فإذا كان الإنهاء من جانب صاحب العمل استحق العامل مكافأة تعادل أجر شهر عن كل سنة من سنوات الخدمة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,155,0,'0e9fae9adf78a4483123c7c6ca777eab','1da43ee3cb92f70e3fb8f04965445e67',replace($m208$إذا أبرم عقد العمل لإنجاز عمل معين،انتهى العقد بإنجاز هذا العمل،ويجوز تجديده باتفاق صريح بين طرفيه،وذلك لعمل أو أعمال أخرى مماثلة. فإذا انتهى العقد المبرم لإنجاز عمل معين واستمر طرفاه فى تنفيذه،اعتبر ذلك تجديدا منهما لهذا العقد،أو أعمال أخرى مماثلة. فإذا استغرق إنجاز العمل الأصلي،أو الأعمال التى جدد لها لأكثر من خمس سنوات،لا يجوز للعامل إنهاء العقد قبل تمام إنجاز هذه الأعمال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,156,0,'b8cd1d5a1d5e38699fbc2d52b41031cf','ee89cb63f8a70a3bdbd97918c6bfd80d',replace($m208$مع عدم الإخلال بأحكام المادة (165) من هذا القانون إذا كان عقد العمل غير محدد المدة،جاز لأى من طرفيه إنهاؤه بشرط أن يخطر الطرف الآخر كتابة قبل الإنهاء بثلاثة أشهر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,157,0,'a3e3730d5474d498292ee3b2c3fd9640','44116cdfd2f4a8697c0bed50d532cdd0',replace($m208$مع عدم الإخلال بحكم المادة (235) من هذا القانون،ومع مراعاة أحكام المواد من ) 158 إلى (175 من هذا القانون،لا يجوز لأصحاب الأعمال والعمال إنهاء عقد العمل غير محدد المدة،إلا بمبرر مشروع وكاف. ويراعى فى جميع الأحوال،أن يتم الإنهاء فى وقت مناسب لظروف العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,160,0,'aad498fd6a9a40470753dd3531e06747','03d83749fb9328dd163e6d323bc6a3f4',replace($m208$يظل عقد العمل قائما طوال مهلة الإخطار،ويلتزم طرفاه بتنفيذ جميع الالتزامات الناشئة عنه وينتهى العقد بانقضاء هذه المهلة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,162,0,'3ccbaec52cc42d8196c85b1e06cbdb80','ae0a3a89da024b98309d906e649608a0',replace($m208$إذا كان الإخطار بالإنهاء من جانب صاحب العمل،يحق للعامل أن يتغيب يوما كاملاً فى الأسبوع أو ثمانى ساعات أثناء الأسبوع،وذلك للبحث عن عمل آخر مع استحقاقه لأجره عن يوم أو ساعات الغياب. ويكون للعامل تحديد يوم الغياب،أو ساعاته،بشرط أن يخطر صاحب العمل بذلك فى اليوم السابق للغياب على الأقل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,164,0,'07c2b15fcd9af06238ed1deeff165d9f','896caf91fbdecbef676ff324490f56d3',replace($m208$إذا أنهى صاحب العمل عقد العمل غير محدد المدة دون إخطار أو قبل انقضاء مهلة الإخطار،يلتزم بأن يؤدى للعامل مبلغًا يعادل أجره عن مدة المهلة،أو الجزء الباقى منها. وفى هذه الحالة تحسب مدة المهلة،أو الجزء الباقى منها ضمن مدة خدمة العامل،ويستمر صاحب العمل فى تحمل الأعباء،والالتزامات المترتبة على ذلك،أما إذا كان الإنهاء صادرا من جانب العامل فإن العقد ينتهى من وقت تركه العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,165,0,'111d0c7cb6c5d49c4e058512734ddb58','59e97c0e04cdb6c13ef500a8792a40c4',replace($m208$إذا أنهى صاحب العمل العقد غير محدد المدة لسبب غير مشروع،كان للعامل الحق فى تعويض عما أصابه من ضرر بسبب هذا الإنهاء بما لا يقل عن أجر شهرين عن كل سنة من سنوات الخدمة،ولا يخل ذلك بحق العامل فى المطالبة بباقى حقوقه المقررة قانونًا. ويعتبر من الأسباب غير المشروعة ما يأتي:<<CR>>
1- انتساب العامل إلى منظمة نقابية،أو مشاركته فى نشاط نقابى فى نطاق هذا القانون.<<CR>>
2- ممارسة صفة المفوض العمالي،أو سبق ممارسة هذه الصفة، أو السعى إلى ذلك.<<CR>>
3- تقديم شكوى،أو إقامة دعوى ضد صاحب العمل،أو المشاركة فى ذلك، تظلما من إخلاله بالقوانين،أو اللوائح،أو عقود العمل.<<CR>>
4- توقيع الحجز على مستحقات العامل تحت يد صاحب العمل.<<CR>>
5- استخدام العامل لحقه فى الإجازات الممنوحة له طبقًا لأحكام هذا القانون.<<CR>>
6- اللون،أو الجنس،أو الحالة الاجتماعية،أو المسئوليات العائلية، أو الحمل أو الدين أو الرأى السياسي.$m208$,'<<CR>>',chr(13))),
('law',14,2025,166,0,'1242312cff457bd1ebc87306e5d7d5aa','4e5249141675a1242a497d118cbf9da2',replace($m208$يعتبر العامل مستقيلاً من العمل إذا تغيب بدون مبرر مشروع أكثر من عشرين يوما متقطعة خلال السنة الواحدة،أو أكثر من عشرة أيام متتالية،على أن يسبق ذلك إنذار بخطاب موصى عليه بعلم الوصول من صاحب العمل،أو من يمثله،للعامل بعد غيابه عشرة أيام فى الحالة الأولى،وخمسة أيام فى الحالة الثانية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,167,0,'ff7f5d65f167a2a5dc474366d1338c76','58a3b1d828a76be91f2aa4d23d66f961',replace($m208$للعامل أن يقدم استقالته كتابة لصاحب العمل بشرط أن تكون موقعة من العامل أو من وكيله الخاص،ومعتمدة من الجهة الإدارية المختصة. ولا تنتهى خدمة العامل إلا بالقرار الصادر بقبول الاستقالة،وعلى العامل أن يستمر فى العمل إلى أن تبت جهة عمله فى الاستقالة خلال عشرة أيام من تاريخ تقديمها،وإلا اعتبرت مقبولة بفوات هذه المدة،وللعامل المستقيل أو وكيله الخاص العدول عن الاستقالة خلال عشرة أيام من تاريخ إخطاره بقبول صاحب العمل الاستقالة على أن يكون هذا العدول مكتوبا ومعتمدا من الجهة الإدارية المختصة، وفى هذه الحالة تعتبر الاستقالة كأن لم تكن.$m208$,'<<CR>>',chr(13))),
('law',14,2025,169,0,'ff0acb51b5e88a5498899e19afc3ddb5','e9ce1ee3b0da42138aaed301baca526d',replace($m208$ينتهى عقد العمل بوفاة العامل حقيقة،أو حكما،طبقًا للقواعد القانونية المقررة، ولا ينتهى عقد العمل بوفاة صاحب العمل،إلا إذا كان قد أبرم لاعتبارات تتعلق بشخص صاحب العمل،أو بنشاطه الذى ينقطع بوفاته.<<CR>>
فإذا توفى العامل وهو فى الخدمة،يصرف صاحب العمل لأسرته ما يعادل أجر شهرين طبقًا لآخر أجر تقاضاه لمواجهة نفقات الجنازة،تصرف للأرمل،فإذا لم يوجد صرفت لأرشد الأولاد،أو إلى أى شخص يثبت قيامه بتحمل نفقات الجنازة، وذلك بحد أدنى ألف جنيه. كما تصرف منحة تعادل أجر العامل عن الشهر الذى توفى فيه والشهرين التاليين له،وذلك بالإضافة إلى الأجر المستحق عن أيام العمل خلال شهر الوفاة،تصرف طبقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ويلتزم صاحب العمل بنفقات تجهيز ونقل الجثمان إلى الجهة التى استقدم العامل منها،أو الجهة التى تطلب أسرته نقله إليها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,170,0,'1600ecba1264798fac721d4bd3dee099','bfefdcddf188aa3150483cdea8197a58',replace($m208$مع عدم الإخلال بأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه، ينتهى عقد العمل بعجز العامل عن تأدية عمله عجزا كليا،أيا كان سبب هذا العجز. فإذا كان عجز العامل عجزا جزئيا،فلا تنتهى علاقة العمل بهذا العجز،إلا إذا ثبت عدم وجود عمل آخر،لدى صاحب العمل،يستطيع العامل أن يقوم به على وجه مرض. وإذا ثبت وجود هذا العمل الآخر،كان على صاحب العمل بناء على طلب العامل كتابة،أن ينقله إلى ذلك العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,172,0,'cfc70e6e47f76237288550c213b14912','2924f87492a3a2ebc3f460bd7d81ddba',replace($m208$يستحق العامل عن مدة عمله بعد سن الستين،مكافأة بواقع أجر نصف شهر عن كل سنة من السنوات الخمس الأولى من الخدمة،وأجر شهر عن كل سنة من السنوات التالية لها،وذلك إذا لم تكن له حقوق عن هذه المدة،وفقًا لأحكام تأمين الشيخوخة،والعجز،والوفاة المنصوص عليها فى قانون التأمينات الاجتماعية والمعاشات المشار إليه. وتستحق هذه المكافأة عن سنوات الخدمة السابقة على سن الثامنة عشرة، وذلك للمتدرج والعامل عند بلوغ هذه السن. وتحسب المكافأة على أساس آخر أجر كان يتقاضاه العامل،أو المتدرج حسب الأحوال. وتصرف المكافأة فى حالة استحقاقها للوفاة وفقًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,173,0,'d0ca2f1385d2a0b7906af909e24b6b62','2197aeb8bdfaddc35715624f53c5833d',replace($m208$يحظر على صاحب العمل إنهاء عقد العامل لمرض العامل،إلا إذا استنفد إجازاته المرضية،وما تبقى من متجمد إجازاته السنوية المستحقة له،وذلك مع عدم الإخلال بأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. وعلى صاحب العمل أن يخطر العامل برغبته فى إنهاء العقد قبل مضى خمسة عشر يوما من تاريخ استنفاد العامل لإجازاته. فإذا شفى العامل قبل تمام الإخطار،امتنع على صاحب العمل إنهاء العقد لمرض العامل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,174,0,'17154397bc3e9bc3555287904fd4a012','88129a14ceb88ed3e009d2f421fe6273',replace($m208$لصاحب العمل أن ينهى عقد العمل ولو كان محدد المدة،أو مبرما لإنجاز عمل معين إذا حكم نهائيا على العامل بعقوبة جناية أو بعقوبة مقيدة للحرية فى جريمة ماسة بالشرف أو الأمانة،وذلك ما لم تأمر المحكمة بوقف تنفيذ العقوبة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,175,0,'b66a1cb4eaefb7b698d5abb77d4b3739','65fc7285786f844618e19ad6da68fbd0',replace($m208$يلتزم صاحب العمل بأن يمكن العامل من الاطلاع على تدرجه الوظيفى وعناصر أجره،وأن يعطى العامل بناء على طلبه ودون مقابل شهادة تحدد خبرته وكفاءته المهنية،وذلك أثناء سريان العقد،أو عند انتهائه.<<CR>>
ويلتزم صاحب العمل بمنح العامل عند انتهاء علاقة العمل شهادة يبين فيها تاريخ التحاقه بالعمل،وتاريخ انتهائه،ونوع العمل الذى كان يؤديه،والمزايا التى كان يحصل عليها،ويجوز بناء على طلب العامل،أن تتضمن تلك الشهادة مقدار الأجر الذى كان يتقاضاه،وسبب انتهاء علاقة العمل،وذلك خلال خمسة عشر يوما من تاريخ طلبها. كما يلتزم بأن يرد للعامل عند انتهاء علاقة العمل ما يكون قد أودعه لديه من أوراق،أو شهادات،أو أدوات،وما يفيد إخلاء طرفه،فور طلبهم.$m208$,'<<CR>>',chr(13))),
('law',14,2025,177,0,'e310b09b1f4a51853e0c50a748902032','d8802d17f7f8d56f8c81701d10c2488f',replace($m208$تختص المحكمة العمالية المشار إليها فى المادة (176) من هذا القانون، دون غيرها،بنظر النزاعات الناشئة عن تطبيق أحكام القوانين واللوائح المنظمة لعلاقات العمل كافة،وكذلك الدعاوى المتعلقة بحقوق العمال التأمينية والمنتفعين عنهم، والمنظمات النقابية العمالية وتشكيلاتها،وذلك دون الإخلال باختصاصات محاكم مجلس الدولة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,179,0,'b07b875a858415cdfb9627668f2ddd66','541647abe1aad88cea16acd703d060ae',replace($m208$تعين الجمعية العمومية للمحكمة الابتدائية فى بداية كل عام قضائى قاضيا بدرجة رئيس محكمة من الفئة )أ( ليحكم بصفة مؤقتة مع عدم المساس بأصل الحق فى المسائل المستعجلة التى يخشى عليها من فوات الوقت،وإصدار الأوامر على عرائض،والأوامر الوقتية،وأوامر الأداء فى تلك المسائل أيا كانت قيمة الحق محل الطلب الذى تختص به المحاكم العمالية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,183,0,'a6fd2894d24e8c7c5995cafb44d8344f','697341dca0a3b5989558ba1308a0d6bf',replace($m208$تختص المحكمة العمالية بالفصل فى منازعات التنفيذ الوقتية والموضوعية فى الأحكام والأوامر الصادرة عنها،أو تلك التى تصدر وفقًا للمادة (179) من هذا القانون،ويطعن فى الأحكام الصادرة عنها أمام الدوائر الاستئنافية المتخصصة. ويختص رؤساء الدوائر بالمحكمة العمالية بإصدار القرارات والأوامر المتعلقة بالتنفيذ. ويكون الاختصاص بالفصل فى التظلمات من هذه القرارات والأوامر أمام المحكمة ذاتها،على ألا يكون من بين أعضائها من أصدر القرار،أو الأمر المتظلم منه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,184,0,'300577e2acf68b2828a5c6df12de7122','463818965b379e6cf3c344db867bc3e4',replace($m208$ينشأ فى دائرة اختصاص المحكمة العمالية قلم كتاب خاص بالمحكمة،وإدارة خاصة لتنفيذ الأحكام،والقرارات الصادرة عنها،أو عن دوائرها الاستئنافية. ويصدر رئيس المحكمة الابتدائية المختصة قرارا بتنظيم العمل بها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,185,0,'3e79547866bceca055d41dfe34679248','088a5c80f94fc3745e3a72ecba289d8d',replace($m208$ينشأ فى مقر كل محكمة ابتدائية،وكذا بكل مقر آخر تنعقد فيه المحكمة العمالية، مكتب للمساعدة القانونية العمالية يناط به كل ما من شأنه معاونة المتقاضين فى إقامة دعواهم العمالية على الوجه القانونى الصحيح،وتكون سائر خدمات هذا المكتب للمتقاضين اختيارية،ودون مقابل. ويصدر وزير العدل قرارا بتشكيل هذه المكاتب،وتحديد مقراتها،وما يلزم لحسن سير العمل فيها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,186,0,'1fa24a88abfcd7c59f1150cd0bb1c1ff','f9d6c0d05bb2756dd69817ebab011478',replace($m208$تشكل بمحكمة النقض دائرة أو أكثر تختص دون غيرها،بالفصل فى الطعون بالنقض فى الأحكام الصادرة عن المحاكم العمالية. كما تنشأ بمحكمة النقض دائرة أو أكثر لفحص تلك الطعون،فإذا رأت أن الطعن غير جائز أو غير مقبول للأسباب الواردة فى المادة (263) من قانون المرافعات المدنية والتجارية الصادر بالقانون رقم 13 لسنة، 1968 أمرت بعدم قبوله بقرار مسبب وإذا رأت أن الطعن جدير بالنظر،أحالته إلى الدائرة المختصة.<<CR>>
وتشكل الدوائر الواردة فى الفقرة الثانية من هذه المادة من ثلاثة من قضاة المحكمة بدرجة نائب رئيس على الأقل،ويعرض الطعن على تلك الدوائر فور إيداع نيابة النقض مذكرة برأيها. وفى جميع الأحوال،لا يجوز الطعن فى القرار الصادر عن دائرة فحص الطعون بأى طريق. واستثناء من أحكام الفقرة الثانية من المادة (269) من قانون المرافعات المدنية والتجارية المشار إليه،وإذا قضت محكمة النقض بنقض الحكم المطعون فيه حكمت فى موضوع الدعوى ولو كان الطعن لأول مرة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,189,0,'722793fa95f81817a0299bf9f2f159f5','204c3e1592d2c07cdc5afe0e2e0f074a',replace($m208$يختص المجلس الأعلى للتشاور الاجتماعى بما يأتي:<<CR>>
1- رسم السياسات القومية للتشاور الثلاثى والحوار الاجتماعى،وخلق بيئة عمل محفزة على التشاور والتعاون وتبادل المعلومات بين أطراف العمل الثلاثة،بما يتفق مع السياسة العامة للدولة.<<CR>>
2- إبداء الرأى فى مشروعات القوانين المتعلقة بالعمل،والحماية الاجتماعية، والمنظمات النقابية العمالية،والعلاقات الصناعية والقوانين ذات الصلة.<<CR>>
3- إبداء الرأى فى اتفاقيات العمل الدولية والعربية قبل التصديق عليها،وإعداد دراسات تحليل الفجوة التشريعية والتنفيذية اللازمة لها.<<CR>>
4- اقتراح الحلول المناسبة لتفادى منازعات العمل الجماعية على المستوى القومى،وعلى الأخص فى الأزمات الاقتصادية التى تؤدى إلى توقف بعض المشروعات عن العمل كليا أو جزئيا.<<CR>>
5- اتخاذ الوسائل المناسبة لتعزيز الثقة والتفاهم بين طرفى علاقة العمل على جميع المستويات.<<CR>>
6- اقتراح الوسائل والإجراءات اللازمة لدعم المشروعات القومية والاقتصادية التى تهدف إلى خلق فرص العمل.<<CR>>
7- إعداد الدراسات والأبحاث اللازمة فى اقتصاديات العمل،ومنها العلاقات الصناعية والمهنية والتدريب المهنى،ودعم تنافسية الاقتصاد الوطني.<<CR>>
8- النظر فى المقترحات أو الموضوعات التى تناقش فى مؤتمر العمل الدولى، أو مجلس إدارة منظمة العمل الدولية،أو الهيئات الإشرافية للمنظمة،والموضوعات التى تتضمنها التقارير المقدمة إلى مكتب العمل الدولى،أو المسائل التى تتناولها المؤتمرات الثلاثية الأخرى الإقليمية والدولية.<<CR>>
9- التشاور حول مسودة تقارير الحكومة الدورية المتعلقة باتفاقيات العمل الدولية.<<CR>>
10- إبداء الرأى فى الموضوعات التى تعرض عليه من الوزارة المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,190,0,'5464328ed66593802c484a0a91fe8114','dbbc07f7a49e07059abbd79b4debc931',replace($m208$يشكل المجلس بقرار من رئيس مجلس الوزراء برئاسة الوزير المختص،ويضم فى عضويته ممثلين عن الوزارات والجهات المعنية،وممثلى منظمات أصحاب الأعمال المعنية والمنظمات النقابية العمالية المعنية،ترشحهم منظماتهم بالتساوى فيما بينهما،على أن يراعى عند الترشيح تمثيل جميع مستويات المنظمات النقابية المعنية وتمثيل المرأة بما لا يقل عن الثلث لكل من الأطراف الثلاث،ما لم يتعذر ذلك.<<CR>>
ويحضر اجتماعات المجلس ممثلون عن المجلس القومى للمرأة والمجلس القومى للأشخاص ذوى الإعاقة،والمجلس القومى للأمومة والطفولة والمجلس القومى لحقوق الإنسان،وذلك دون أن يكون لهم صوت معدود فى المداولات. وللمجلس دعوة من يراه من ذوى الخبرة والمتخصصين لحضور جلساته،وفقًا للموضوعات المطروحة دون أن يكون لهم صوت معدود فى المداولات. ويحدد القرار نظام العمل به،واختصاصاته الأخرى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,191,0,'387ca1c33d8b54bfce3d6f953cb722a6','a7fc05a0204fc2f39b71cd65ac053893',replace($m208$دورة انعقاد المجلس أربع سنوات،تبدأ من اليوم التالى لصدور قرار رئيس مجلس الوزراء الصادر بالتشكيل،ويعاد تشكيله خلال الستين يوما الأخيرة على الأقل قبل انتهاء دورته. وإذا خلا محل أحد الأعضاء خلال مدة الدورة لأى سبب من الأسباب،تلتزم الجهة التى خلا محل ممثلها بترشيح ممثل آخر لها لاستكمال مدته.$m208$,'<<CR>>',chr(13))),
('law',14,2025,192,0,'0f11ef2a46d9b1ae27370b59bc78584f','2fcb91b834d9db9da659b3ac86aac69c',replace($m208$للمجلس أن ينشئ فروعا له فى المحافظات للقيام بمهامه على مستوى المحافظة برئاسة مدير مديرية العمل،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال المعنية بالتساوى فيما بينهم،كما له أن يشكل لجانًا نوعية من بين أعضائه أو من غيرهم للقيام بالمهام التى يوكلها إليهم،على أن يراعى فى ذلك التمثيل الثلاثى للمجلس. كما له أن ينشئ وحدات متخصصة للقيام بالأبحاث والدراسات اللازمة لأعماله منفردا أو بالتعاون مع المراكز البحثية المعتمدة ومراكز الأبحاث بالجامعات. ويصدر المجلس اللوائح المالية والإدارية اللازمة لتنظيم عمل فروعه،ولجانه النوعية،ووحداته البحثية المتخصصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,193,0,'89cbe32c7c9a175f08b04ebf0e18346e','1004b48e11eb441e639defde119a5d75',replace($m208$يجوز للمجلس قبول الهبات والمنح والتبرعات بعد العرض على مجلس إدارته وموافقة ثلثى أعضائه على الأقل،ووفقًا للقواعد والإجراءات المقررة قانونًا.<<CR>>
ويكون للمجلس حساب خاص ضمن حساب الخزانة الموحد لدى البنك المركزى، وله أن يفتح حسابا لدى أحد البنوك المسجلة لدى البنك المركزى بعد موافقة وزير المالية،ويرحل فائض أمواله من سنة مالية إلى أخرى،وله أن يستثمر أمواله استثمارا أمنًا،ويخضع حسابه لرقابة الجهاز المركزى للمحاسبات. ) الفصل الثانى ( المفاوضة الجماعية$m208$,'<<CR>>',chr(13))),
('law',14,2025,194,0,'f90ff698e02aaacd61c16c8c9d63f4ba','c18c5fffe7e35d4792c7d06809d406d5',replace($m208$تجرى المفاوضة الجماعية بحرية وطواعية فى إطار من التوازن بين مصالح طرفيها من أجل:<<CR>>
1- تحسين شروط وظروف العمل،وأحكام التشغيل.<<CR>>
2- التعاون بين طرفى علاقة العمل لتحقيق التنمية الاجتماعية لعمال المنشأة.<<CR>>
3- تسوية المنازعات الجماعية بين العمال وأصحاب الأعمال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,196,0,'711cdb0a3402998ca0a4537a591e414d','1b07badabf9bc02bee37efe16bf1d184',replace($m208$إذا أثير نزاع عمل جماعى وجب على طرفيه الدخول فى مفاوضة جماعية لتسويته وديا. ويلتزم طرفا المفاوضة الجماعية بتقديم ما يطلب منهما من بيانات ومعلومات ومستندات تتعلق بموضوع النزاع،والسير فى إجراءات المفاوضة. فإذا رفض أحد الطرفين البدء فى إجراءات المفاوضة الجماعية جاز للطرف الآخر أن يطلب من الجهة الإدارية المختصة تحريك إجراءات التفاوض بدعوة منظمة أصحاب الأعمال أو المنظمة النقابية العمالية المعنية أو المفوض العمالي، بحسب الأحوال،للتدخل وإقناع الطرف الرافض بالعدول عن موقفه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,197,0,'f17bd949b50292d27f5b17d7d03aa32b','17d5346aabfd853e1a2206b145a26267',replace($m208$إذا أسفرت المفاوضة الجماعية عن اتفاق الطرفين يدون اتفاقهما فى اتفاقية عمل جماعية طبقًا للشروط والقواعد المحددة فى هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,198,0,'b922758f066ef5f9dfd572bd7e1aed59','b2a7cb9c85c4b3e6ab12d2ebebf5ffc2',replace($m208$يحظر على طرفى علاقة العمل أثناء المفاوضة اتخاذ إجراءات،أو إصدار قرارات تتعلق بالموضوعات محل التفاوض،إلا فى حالة الضرورة والاستعجال ويشترط أن يكون الإجراء أو القرار فى هذه الحالة مؤقتًا. ) الفصل الثالث ( اتفاقيات العمل الجماعية$m208$,'<<CR>>',chr(13))),
('law',14,2025,199,0,'e54578dcff588099e6768bf44ee73cd4','5f9e177de9e476c1a5c9c02cc919f0d4',replace($m208$مع عدم الإخلال بأحكام قانون المنظمات النقابية العمالية وحماية حق التنظيم النقابى المشار إليه،يكون إبرام الاتفاقية الجماعية لمدة لا تزيد على ثلاث سنوات، أو للمدة اللازمة لتنفيذ مشروع معين،فإذا زادت المدة فى الحالة الأخيرة على ثلاث سنوات تعين على طرفى الاتفاقية التفاوض لتجديدها أو لتعديل شروطها فى ضوء ما يستجد من ظروف اقتصادية،أو اجتماعية،وتتبع فى شأن التجديد أحكام المادة (202) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,200,0,'53a64e9634a80bd22797aad5c5983885','b41b7ea27da3a872218bdb27b55ef136',replace($m208$يقع باطلاً كل نص يرد فى اتفاقية العمل الجماعية ويكون مخالفًا لأحكام هذا القانون،أو القوانين ذات الصلة. وفى حالة تعارض نص فى عقد العمل الفردى مع نص فى الاتفاقية،يسرى الحكم الذى يحقق فائدة كبرى للعامل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,202,0,'a55a01d85232bc44e88b730c3c46cdd5','2c4ec7f1c76d11dfaea231dd55227af0',replace($m208$يتعين على طرفى اتفاقية العمل الجماعية سلوك طريق المفاوضة الجماعية لتجديدها قبل انتهاء مدتها بثلاثة أشهر،فإذا انقضت المدة الأخيرة دون الاتفاق على التجديد امتد العمل بالاتفاقية مدة ثلاثة أشهر ويستمر التفاوض لتجديدها،فإذا انقضى شهران دون التوصل إلى اتفاق كان لأى من طرفى الاتفاقية عرض الأمر على الجهة الإدارية المختصة لاتخاذ ما يلزم نحو اتباع إجراءات الوساطة وفقًا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,203,0,'0a91fc8b89a37e6405d17fb6b07971c2','5a91309c660ab0c7ac6c6613c4a46e97',replace($m208$تكون اتفاقية العمل الجماعية نافذة وملزمة لطرفيها بعد التوقيع عليها،ويتعين إيداعها لدى الجهة الإدارية المختصة لقيدها خلال ثلاثين يوما من تاريخ التوقيع عليها فى سجل ورقى أو إلكترونى يعد لهذا الغرض،ويجوز للجهة الإدارية المختصة الاعتراض عليها إذا توافرت حالة من الحالات المنصوص عليها فى المادة (200) من هذا القانون،وإخطار طرفى الاتفاقية بالاعتراض وأسبابه،وذلك بكتاب موصى عليه ومصحوبا بعلم الوصول. فإذا انقضت المدة المذكورة،ولم تقم الجهة الإدارية المختصة بالاعتراض، وجب عليها إجراء القيد وفقًا للأحكام السابقة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,204,0,'c4c14351acd5585d378f1562ab8cd1c3','d629e89d79bb788096c0073e26b1aad2',replace($m208$إذا رفضت الجهة الإدارية المختصة قيد الاتفاقية وفق أحكام المادة (203) من هذا القانون،جاز لأى من طرفى الاتفاقية اللجوء إلى قاضى الأمور المستعجلة بالمحكمة العمالية المختصة التى يقع بدائرتها محل العمل،وفقًا للإجراءات المعتادة لرفع الدعوى،وذلك خلال ثلاثين يوما من تاريخ الإخطار بالاعتراض،فإذا قضت بقيد الاتفاقية وجب على الجهة الإدارية المختصة إجراء القيد فى السجل الخاص بذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,207,0,'79beaec1d3f5a9d721317242144e7d30','414253b8188aa87e4d82f7d2cd8a4905',replace($m208$تلتزم الجهة الإدارية المختصة بالتأشير على هامش السجل المشار إليه فى المادة (203) من هذا القانون بما يطرأ على اتفاقية العمل الجماعية من تجديد،أو انضمام، أو تعديل خلال خمسة عشر يوما من تاريخ حصوله.$m208$,'<<CR>>',chr(13))),
('law',14,2025,209,0,'0792eaae7f249d779058fdba8620f41c','9b68029456a8d00c7ca4baf96370500a',replace($m208$إذا طرأت ظروف استثنائية غير متوقعة وترتب على حدوثها أن تنفيذ أحد الطرفين للاتفاقية،أو لحكم من أحكامها أصبح مرهقًا،وجب على الطرفين سلوك طريق المفاوضة الجماعية لمناقشة هذه الظروف،والوصول إلى اتفاق يحقق التوازن بين مصلحتيهما. فإذا لم يصل الطرفان إلى اتفاق وجب عليهما عرض الأمر على الجهة الإدارية المختصة لاتخاذ ما يلزم نحو اتباع إجراءات التوفيق،أو الوساطة والتحكيم وفقًا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,211,0,'49bb91376e45512530e0fa5355bdecb3','903e72c524efcd6bdff599219db8343b',replace($m208$للمنظمة النقابية العمالية،ولمنظمة أصحاب الأعمال التى تكون طرفًا فى الاتفاقية الجماعية أن ترفع لمصلحة أى عضو من أعضائها جميع الدعاوى الناشئة عن الإخلال بأحكام الاتفاقية. وللعضو الذى رفعت الدعوى من المنظمة لمصلحته أن يتدخل فيها،كما يجوز له رفع هذه الدعوى ابتداء مستقلاً عنها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,215,0,'990deb78a1022de6f55041cb1f63227c','345287bffa6181dba55cb3a968603873',replace($m208$تحدد الجهة الإدارية المختصة جلسة للتوفيق فى النزاع فى موعد لا يتجاوز خمسة أيام من تاريخ تقديم الطلب إليها،ويخطر به طرفا النزاع قبل الموعد المحدد بثلاثة أيام على الأقل. ويصدر الوزير المختص قرارا بإجراءات وقواعد التوفيق.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,216,0,'73d95607564c98dc1070b40a932663fa','e4782f5b66569d428a0114e7933dffb2',replace($m208$إذا اتفق طرفا النزاع على تسويته وديا وفقًا لأحكام هذا الفرع،يحرر الاتفاق ويوقع عليه منهما فى اتفاقية عمل جماعية،وتتخذ بشأنه الإجراءات الواردة فى هذا القانون،وتكون ملزمة لهما.$m208$,'<<CR>>',chr(13))),
('law',14,2025,217,0,'b609ace97e36c9574285e089f591f020','e18cbc8ccace16cb1a289ecec1cb13f7',replace($m208$مع مراعاة أحكام قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة، 1994 إذا لم تتم تسوية النزاع خلال واحد وعشرين يوما من تاريخ بدء التوفيق،جاز للطرفين اللجوء إلى الجهة الإدارية المختصة لاتخاذ إجراءات إحالة النزاع إلى مركز الوساطة والتحكيم المنصوص عليه فى المادة (218) من هذا القانون. الفرع الثالث مركز الوساطة والتحكيم$m208$,'<<CR>>',chr(13))),
('law',14,2025,218,0,'f54fcae0b37e87910d9ade62f7068a63','f785439c90b5f222c2f3af73300a2079',replace($m208$ينشأ بالوزارة المختصة مركز يسمى "مركز الوساطة والتحكيم"،تكون له الشخصية الاعتبارية،ويتبع الوزير المختص،ويتكون من قسمين قسم الوساطة، وقسم التحكيم. ويكون له رئيس تنفيذى يصدر بتعيينه وتحديد معاملته المالية قرار من رئيس مجلس الوزراء بناء على ترشيح من الوزير المختص،وذلك لمدة ثلاث سنوات قابلة للتجديد.<<CR>>
ويصدر رئيس مجلس الوزراء قرارا بتحديد الهيكل الإدارى والمالى لمركز الوساطة والتحكيم ونظام العمل به والرسوم المقررة على خدماته بما لا يجاوز خمسين ألف جنيه،وحالات الإعفاء منها. ويلتزم مركز الوساطة والتحكيم بنصوص هذا القانون وجميع القرارات واللوائح الصادرة تنفيذًا له والضمانات والمبادئ الأساسية للتقاضى فى قانون المرافعات المدنية والتجارية،وتسرى فى ما لم يرد فى شأنه نص خاص فى هذا القانون ولوائح مركز الوساطة والتحكيم أحكام قانون التحكيم فى المواد المدنية والتجارية المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,219,0,'75ce3e5f1ffd8076b98731cc7331c580','6fe7f1e017b08e8d33c3c21c485bc41f',replace($m208$يعد مركز الوساطة والتحكيم قائمة من الوسطاء وقائمة من المحكمين الذين تنطبق عليهم الشروط الواردة فى هذا القانون،ويؤدى كل منهم أمام رئيس المركز القسم الآتى ":أقسم باالله العظيم أن أؤدى مهمتى بالذمة والأمانة والصدق وألا أفشى سرا من أسرار العمل التى أطلع عليها بحكم مهمتى".$m208$,'<<CR>>',chr(13))),
('law',14,2025,220,0,'460264a502c3edcce713cf7e999d39cb','b91e59c351f376a487b96a8dc2960fc5',replace($m208$استثناء من أحكام المادتين (221، 226) من هذا القانون،يجوز لمركز الوساطة والتحكيم الاستعانة بأعضاء من الجهات والهيئات القضائية بعد موافقة مجالسهم الخاصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,221,0,'b5a88e16da0498873eabc631f5c075f3','f851ca63ac5a7a5f5196bee4e4b0769a',replace($m208$يشترط فيمن يقيد بقائمة الوسطاء الشروط الآتية:<<CR>>
1- أن يكون حاصلاً على مؤهل عالٍ.<<CR>>
2- أن يكون محمود السيرة،وحسن السمعة.<<CR>>
3- ألا يكون قد سبق إدانته فى جناية أو جنحة مخلة بالشرف أو الأمانة، ما لم يكن قد رد إليه اعتباره.<<CR>>
4- ألا يكون من العاملين بالجهاز الإدارى للدولة.<<CR>>
5- ألا يكون قد سبق فصله بالطريق التأديبي.<<CR>>
6- قضاء مدة التدريب الأولى على أعمال الوساطة ومجالاتها بالمركز. 7- اجتياز الاختبار الذى يعقده مركز الوساطة والتحكيم بدرجة لا تقل عن سبعين بالمائة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,224,0,'d31a9c0e527c4e78ffd14de5c128467e','0190f72c5d9711e2b5d443acac5d7582',replace($m208$مع عدم الإخلال بحكم المادة (223) من هذا القانون،يحق لطرفى النزاع أو أحدهما خلال خمسة عشر يوما أن يطلب من مركز الوساطة والتحكيم استبدال وسيط النزاع لمرة واحدة،فإذا رفض الطرف الآخر استبداله تعين على مركز الوساطة والتحكيم الفصل فى هذا الطلب فى موعد لا يجاوز يومين،فإذا تم اختيار وسيط جديد تحسب مدة أعماله من تاريخ تسلمه للمهمة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,225,0,'9f982c51d2de78632fff022277618ba4','8a608cb72077efc63325c5290706ad1e',replace($m208$على الوسيط أن يبذل مساعيه للتقريب بين وجهات نظر طرفى النزاع، فإذا لم يتمكن من تحقيق ذلك كان عليه أن يقدم للطرفين كتابة ما يقترحه من توصيات لحل النزاع. فإذا قبل الطرفان التوصيات التى قدمها الوسيط يتم إثبات ذلك فى اتفاق يوقعه الطرفان والوسيط ويصبح هذا الاتفاق ملزما للطرفين فى حدود ما تم الاتفاق عليه، ويثبت ذلك بالسجل الورقى أو الإلكترونى المعد لهذا الشأن. وإذا لم يقبل الطرفان هذه التوصيات أو بعضها يعرض الوسيط عليهما اللجوء إلى التحكيم،فإذا وافقا أحيل النزاع إلى قسم التحكيم بالمركز.<<CR>>
وفى جميع الأحوال،على وسيط النزاع أن يقدم خلال خمسة أيام من تاريخ انتهاء مهمته تقريرا لقسم الوساطة،يتضمن ملخصا للنزاع والأوراق،والمستندات المقدمة من طرفيه،والتوصيات،وما تم قبوله من الطرفين،وما تم رفضه وأسباب الرفض.$m208$,'<<CR>>',chr(13))),
('law',14,2025,226,0,'2e3eae2b76893256711e9bf8626a8578','ca6c3953919fa6b3ea7ee607cc2dd6b1',replace($m208$يشترط فيمن يقيد بقائمة المحكمين،الشروط الآتية:<<CR>>
1- أن يكون حاصلاً على إجازة الحقوق من إحدى الجامعات المصرية، أو ما يعادلها.<<CR>>
2- أن يكون محمود السيرة،وحسن السمعة.<<CR>>
3- ألا يكون قد سبق إدانته فى جناية،أو جنحة مخلة بالشرف أو الأمانة، ما لم يكن قد رد إليه اعتباره.<<CR>>
4- ألا يكون من العاملين بالجهاز الإدارى للدولة.<<CR>>
5- ألا يكون قد سبق فصله بالطريق التأديبي.<<CR>>
6- قضاء مدة التدريب الأولى لمركز الوساطة والتحكيم على أعمال التحكيم،ومجالاته.<<CR>>
7- اجتياز الاختبار الذى يعقد من مركز الوساطة والتحكيم بدرجة لا تقل عن خمسة وسبعين بالمائة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,227,0,'69984f1b9c9bc82bb43cbc649045ac48','30d54dcba2b4a0fbbd72a6d1ac246982',replace($m208$تشكل هيئة التحكيم باتفاق الطرفين من محكم واحد أو أكثر،بشرط أن يكون العدد فرديا،لنظر النزاع القائم،وذلك فى موعد غايته خمسة عشر يوما من تاريخ إحالة النزاع لقسم التحكيم. وإذا لم يتفق طرفا التحكيم على اختيار المحكمين خلال المدة المشار إليها فى الفقرة الأولى من هذه المادة يتولى المركز اختيار المحكمين وفقًا للوائح المنظمة لعمل المركز.$m208$,'<<CR>>',chr(13))),
('law',14,2025,229,0,'fbd8aeefd457876f7f514e9a62db320f','9495318b717cc3ce431c02e983a96b55',replace($m208$يتعين على المحكم أو المحكمين عند الفصل فى النزاع المعروض مراعاة التشريعات المعمول بها داخل الدولة،والاتفاقيات الدولية المصدق عليها، ومبادئ القانون الطبيعى،والعرف والعدالة الاجتماعية،وفقًا للحالة الاقتصادية والاجتماعية السائدة فى منطقة المنشأة،ويصدر الحكم بأغلبية الآراء فى حالة تعدد المحكمين. ويتعين على المحكم،أو المحكمين الفصل فى النزاع المعروض خلال ثلاثين يوما من تاريخ إحالة النزاع. ويعتبر حكم التحكيم نهائيا،ويكون قابلاً للتنفيذ بعد وضع الصيغة التنفيذية عليه من المحكمة العمالية المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,230,0,'e409cb13e64e0ff1dfcd2734a85e8625','d67cb0813b1e8914c4a6de5d3e6aa256',replace($m208$تشكل بقسم التحكيم دائرة عليا أو أكثر،لإعادة النظر،مكونة من خمسة محكمين من المقيدين بقائمتها للطعن فى الأحكام المشار إليها فى المادة (229) من هذا القانون. وإذا تضمن شرط أو مشارطة التحكيم أن يكون على درجتين،يحال النزاع إلى تلك الدائرة خلال خمسة عشر يوما من تاريخ صدور حكم أول درجة،ويتعين عليها الفصل فى النزاع خلال خمسة وأربعين يوما من تاريخ الإحالة إليها. ) الفصل الخامس ( الإضراب والإغلاق$m208$,'<<CR>>',chr(13))),
('law',14,2025,231,0,'7a719c9557e013f625d9b1ff82fea9ee','b3b445ec05d916b6c8eb2437f47fa26e',replace($m208$للعمال حق الإضراب عن العمل للمطالبة بما يرونه محققًا لمصالحهم المهنية والاقتصادية والاجتماعية،وذلك بعد استنفاد طرق التسوية الودية للمنازعات المنصوص عليها فى هذا القانون،ويكون إعلانه،وتنظيمه من خلال المنظمة النقابية العمالية المعنية،أو المفوض العمالى فى حدود الضوابط والإجراءات المقررة فى هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,233,0,'b27d6d7aab6d555611b11a6dd112a644','1cce3e2041ef5e0f5a420bf45a8d76d2',replace($m208$يحظر على العمال الدعوة إلى الإضراب،أو إعلانه بقصد تعديل اتفاقية عمل جماعية أثناء مدة سريانها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,234,0,'667ed0eb2d6733fcd5299d46218ffe7c','b2700dfbac8639f7bf37932f68e934e7',replace($m208$يحظر الإضراب أو الدعوة إليه أو إعلانه بالمنشآت الحيوية التى تقدم خدمات أساسية للمواطنين والتى يترتب على توقف العمل فيها الإخلال بالأمن القومى. ويحظر الدعوة للإضراب أو إعلانه فى الظروف الاستثنائية. ويصدر رئيس مجلس الوزراء قرارا بتحديد المنشآت الحيوية والخدمات الأساسية التى تقدمها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,237,0,'5737191634a522bbf7f642c68060e6e0','31fcc5bc22cb4912ebaf403fc29c5424',replace($m208$فى تطبيق أحكام المادة (236) من هذا القانون،يجب على صاحب العمل أن يتقدم بطلب إغلاق المنشأة،أو تقليص حجمها،أو نشاطها إلى لجنة تشكل لهذا الغرض،ويجب أن يتضمن الطلب الأسباب،والأوضاع،والشروط والإجراءات، التى يستند إليها فى ذلك،وأعداد،وفئات العمال الذين سيتم الاستغناء عنهم.<<CR>>
وعلى اللجنة أن تصدر قرارها مسببا خلال خمسة وأربعين يوما على الأكثر من تاريخ تقديم الطلب إليها،فإذا كان القرار صادرا بقبول الطلب وجب أن يحدد موعد تنفيذه. فإذا لم تصدر اللجنة قرارها خلال المدة المشار إليها،اعتبر ذلك موافقة ضمنية على الإغلاق بالأوضاع والشروط والإجراءات التى تقدم بها صاحب العمل. ولصاحب الشأن أن يتظلم من قرار اللجنة أمام لجنة أخرى تشكل لهذا الغرض، ويترتب على قبول التظلم وقف تنفيذ قرار اللجنة. ويصدر رئيس مجلس الوزراء قرارا بتشكيل كل من اللجنتين المشار إليهما فى هذه المادة،وتحديد اختصاصاتهما،والجهات التى تمثل فيهما،والإجراءات التى تتبع أمامهما،ومواعيد،وإجراءات التظلم،على أن يتضمن تشكيلهما ممثلاً عن المنظمة النقابية العمالية المعنية،وممثلاً عن منظمة أصحاب الأعمال المعنية ترشحه كل منهما.$m208$,'<<CR>>',chr(13))),
('law',14,2025,238,0,'c989e166d999b3e43b0fc75b9cbdd9ad','980bb3888d97bf397e6e5f90b8206f03',replace($m208$يخطر صاحب العمل العمال،والمنظمة النقابية العمالية المعنية بالطلب المقدم منه،وبالقرار الصادر بالإغلاق الكلى،أو الجزئى للمنشأة،أو بتقليص حجمها، أو نشاطها.ويكون تنفيذ ذلك القرار اعتبارا من التاريخ الذى تحدده اللجنة التى نظرت الطلب،أو التظلم على حسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,239,0,'731c4a9555e957ad29249e60def7d3e2','0ff097e5b68bd3372f0032c9fcd8d55f',replace($m208$فى حالة الإغلاق الجزئى أو تقليص حجم المنشأة أو نشاطها،إذا لم تتضمن الاتفاقية الجماعية السارية فى المنشأة المعايير الموضوعية لاختيار من سيتم الاستغناء عنهم من العمال،يتعين على صاحب العمل أن يتشاور فى هذا الشأن مع المنظمة النقابية العمالية المعنية،وذلك بعد صدور القرار وقبل التنفيذ. وتعتبر الأقدمية،والأعباء العائلية،والسن،والقدرات والمهارات المهنية للعمال من المعايير التى يمكن الاسترشاد بها فى هذا الشأن. ويصدر الوزير المختص قرارا بالمعايير الموضوعية لاختيار من سيتم الاستغناء عنهم من العمال،وذلك بالتشاور مع منظمات العمال وأصحاب الأعمال.$m208$,'<<CR>>',chr(13))),
('law',14,2025,240,0,'87d9474915b0330ef904143e87a4707f','9a9751adf79d55a80a3dbd3f251689ab',replace($m208$يحظر على صاحب العمل التقدم بطلب الإغلاق الكلى أو الجزئى للمنشأة، أو تقليص حجمها أو نشاطها أثناء مراحل تسوية منازعات العمل الجماعية،كما يحظر عليه أن يتقدم بهذا الطلب بسبب أو أثناء إضراب العمال عن العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,241,0,'d6402e076531fb13ad86c5bb179e02ce','0e04e0611c71e498da2ebbc95745020e',replace($m208$مع عدم الإخلال بحكم المادة (238) من هذا القانون،فى الحالات التى يحق فيها لصاحب العمل إنهاء عقد العمل لأسباب اقتصادية يجوز له بدلاً من استخدام هذا الحق أن يعدل من شروط العقد بصفة مؤقتة،وله على الأخص أن يكلف العامل بعمل غير متفق عليه،ولو كان يختلف عن عمله الأصلى كما له أن يخفض أجر العامل بما لا يقل عن الحد الأدنى للأجور. فإذا قام صاحب العمل بتعديل شروط العقد وفقًا للفقرة الأولى من هذه المادة جاز للعامل أن ينهى عقد العمل دون أن يلتزم بالإخطار،ويعتبر الإنهاء فى هذه الحالة إنهاء مبررا من جانب صاحب العمل والعامل. وفى جميع الأحوال،يستحق العامل مكافأة تعادل أجر شهر عن كل سنة من السنوات الخمس الأولى من سنوات الخدمة وشهر ونصف الشهر عن كل سنة تجاوز ذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,243,0,'eb7f47edd669a6ea45441378c8439887','c10cf661cf3bbcb29145e36d4eaec945',replace($m208$يقصد فى تطبيق أحكام هذا الكتاب بالمنشأة كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون العام أو الخاص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,244,0,'347807a47244c23678c12e3d96dac114','3a28b915b8aed9a55a1761bc951ea86d',replace($m208$تسرى أحكام هذا الكتاب على جميع مواقع العمل،والمنشآت وفروعها أيا كان نوعها،أو تبعيتها،سواء كانت برية أو بحرية أو جوية. كما تسرى أيضا على المسطحات المائية بجميع أنواعها ووسائل النقل المختلفة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,246,0,'c99b3e8beb704ee1388e6a95228b9227','1737c91750be3c60571a4be218b8c969',replace($m208$تلتزم المنشأة،وفروعها،بتوفير وسائل السلامة والصحة المهنية،وتأمين بيئة العمل فى أماكن العمل،وفقًا لمعايير التعرض والحدود العتبية،وبما يكفل الوقاية من المخاطر الفيزيائية الناجمة عما يلى:<<CR>>
1- الوطأة الحرارية والبرودة.<<CR>>
2- الضوضاء والاهتزازات.<<CR>>
3- شدة الاستضاءة.<<CR>>
4- الإشعاعات الضارة والخطرة ) مؤينة -غير مؤينة(.<<CR>>
5- تغيرات الضغط الجوى.<<CR>>
6- مخاطر الانفجار.$m208$,'<<CR>>',chr(13))),
('law',14,2025,247,0,'54dc0f1fdcc44123a06c2e7c0c82729e','33b24049ecd2aa269a41bf3500dce17a',replace($m208$تلتزم المنشأة،وفروعها باتخاذ الاحتياطات والتدابير اللازمة لتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل،بما يكفل الوقاية من المخاطر الهندسية )ميكانيكية -كهربائية -تشييد وبناء -المواءمة(،وعلى الأخص ما يأتي:<<CR>>
1- كل خطر ينشأ عن معدات وأدوات رفع وجر،ووسائل الانتقال،والتداول، ونقل الحركة.<<CR>>
2- كل خطر ينشأ عن أعمال التشييد والبناء،والحفر،ومخاطر الانهيار،والسقوط.<<CR>>
3- كل خطر ينشأ عن الكهرباء )الديناميكية والاستاتيكية(.<<CR>>
4- كل خطر ينشأ عن عدم مراعاة التناسب بين البنية الجسدية للعامل والمعدات والآلات،وبين مكان العمل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,248,0,'be51d782137098d1875cf35fe20066fc','399494c6c64067b8d6ec7ef52782bdf5',replace($m208$تلتزم المنشأة وفروعها باتخاذ وسائل وطرق وقاية العمال من خطر الإصابة بالبكتيريا والفيروسات والفطريات،والطفيليات،وسائر المخاطر البيولوجية متى كانت طبيعة العمل تُعرض العمال لظروف الإصابة بها،وعلى الأخص ما يأتي:<<CR>>
1- مخالطة الآدميين المرضى،والقيام بخدماتهم من رعاية وتحاليل،وفحوص طبية ومعملية،وعمليات جراحية.<<CR>>
2- التعامل مع الحيوانات،ومنتجاتها،ومخلفاتها.<<CR>>
3- وحدات تداول،ونقل وتخزين،ومعالجة المخلفات الطبية،والبيطرية الخطرة.<<CR>>
4- وحدات استقبال،وتخزين،ومعالجة التصريفات بأنواعها المختلفة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,249,0,'28525d9faa7671ae3b18428b66272849','eed076eb3aa3dd8819b4687f97086b6b',replace($m208$تلتزم المنشأة،وفروعها بتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل فى أماكن العمل بما يكفل الوقاية من المخاطر الكيميائية الناتجة عن التعامل مع المواد الكيميائية الصلبة والسائلة والغازية،مع مراعاة ما يأتي:<<CR>>
1- عدم تجاوز أقصى تركيز مسموح به للتعامل فى المواد الكيميائية،والمواد المسببة للسرطان التى يتعرض لها العمال.<<CR>>
2- عدم تجاوز مخزون المواد الكيميائية الخطرة كميات العتبة لكل منها.<<CR>>
3- توفير الاحتياطات اللازمة لوقاية المنشأة،والعمال عند تداول ونقل وتخزين،واستخدام المواد الكيميائية الخطرة،والتخلص من مخلفاتها.<<CR>>
4- الاحتفاظ بسجل ورقى أو إلكترونى لحصر المواد الكيميائية الخطرة المتداولة متضمنًا جميع البيانات الخاصة بكل مادة،ويسجل لرصد ملوثات بيئة العمل التى يتعرض لها العمال،ويسجل المواد والمخلفات الخطرة وفقًا لقانون تنظيم إدارة المخلفات الصادر بالقانون رقم 202 لسنة 2020<<CR>>
5- وضع بطاقات تعريف جميع المواد الكيميائية المتداولة فى العمل موضحا بها الاسم العلمى والتجارى،وتركيبها الكيميائي،ودرجة خطورتها واحتياطات السلامة وإجراءات الطوارئ المتعلقة بها،وعلى المنشأة أن تحصل على البيانات المذكورة فى هذه المواد من مصنعها،أو موردها عند التوريد.<<CR>>
6- تدريب العمال على طرق التعامل مع المواد الكيميائية الخطرة،والمواد المسببة للسرطان وتعريفهم بمخاطرها،وبطرق الأمان،والوقاية من هذه المخاطر.<<CR>>
7- معايير التعرض والحدود العتبية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,251,0,'19c906614bd4af0bd81e640d3b1aba45','71df10eedea4766f6df6435c4a8b89ec',replace($m208$تلتزم المنشأة،وفروعها باتخاذ الاحتياطات والاشتراطات اللازمة للوقاية من مخاطر الحريق،طبقًا لما تحدده الجهة المختصة بوزارة الداخلية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,253,0,'0504f69ae0b006b0c50a9a4782f6daaa','be864af196924360d2a6a711c98414a3',replace($m208$تلتزم المنشأة وفروعها بإجراء تقييم وتحليل للمخاطر،والكوارث الصناعية والطبيعية المتوقعة والكوارث الناتجة عن التشغيل وإعداد خطط طوارئ لحماية المنشأة والعمال والمترددين عليها عند وقوع الحوادث والكوارث،على أن يتم اختبار فاعلية هذه الخطط،وإجراء تجارب عملية عليها للتأكد من كفاءتها،وتدريب العمال لمواجهة متطلباتها،وتصحيحها إذا لزم الأمر. ويجوز للمنشأة الاسترشاد برأى خبير استشارى،أو مراكز استشارية فى مجال السلامة والصحة المهنية وتأمين بيئة العمل عند إعداد خطط الطوارئ. كما تلتزم المنشأة بإبلاغ الجهة الإدارية المختصة بخطط الطوارئ، وبأى تعديلات تطرأ عليها،وكذلك فى حالة تخزين مواد خطرة أو استخدامها. وفى حالة التنبؤ بوقوع حادث أو خطر فى مكان العمل قد يؤدى إلى تهديد وشيك وخطير على صحة العمال أو حياتهم،يجوز للعامل مغادرة مكان العمل إلى مكان آمن داخل المنشأة أو موقع العمل أو خارجه إذا لزم الأمر،دون إذن،وعليهم إخطار المشرف المباشر بأية أخطار يتعرضون لها،ولا يترتب على هذا الانسحاب أى عواقب أو مساءلة تأديبية. وتلتزم المنشأة بضمان عدم عودة العمال إلى بيئة العمل غير الآمنة إلى أن يتم إزالة الخطر. وفى حالة امتناع المنشأة عن تنفيذ ما توجبه أحكام هذه المادة،والقرارات المنفذة لها فى المواعيد التى تحددها الجهة الإدارية المختصة،وترتب على ذلك وجود خطر داهم على صحة العاملين أو المترددين أو سلامتهم،على الجهة الإدارية المختصة أن تأمر بإغلاق المنشأة كليا أو جزئيا،أو إيقاف معدة أو آلة أو أكثر حتى زوال أسباب الخطر،وينفذ القرار الصادر بالإغلاق أو الإيقاف بالطرق الإدارية مع عدم الإخلال بحق العاملين فى تقاضى أجورهم خلال فترة الإغلاق أو الإيقاف الجزئى أو الكلى. وللجهة الإدارية المختصة أن تقوم بإزالة أسباب الخطر بطريق التنفيذ المباشر على نفقة المنشأة بالتنسيق مع الجهات المعنية.$m208$,'<<CR>>',chr(13))),
('law',14,2025,254,0,'784e1227e8fa2ac6847730f106176deb','aeef37da1e2f5f5ec1019db2a97d4822',replace($m208$تلتزم المنشآت وفروعها بتوفير بيئة عمل آمنة،وغير عدائية،خالية من التحرش والتنمر والعنف،وتوفير الوسائل الكفيلة بالوقاية منهم. ويصدر الوزير المختص قرارا بتحديد نماذج لمدونة السلوك الوظيفي، والقواعد والإجراءات اللازمة لتقديم الشكاوى وسبل تسويتها واتخاذ الإجراءات اللازمة فى شأنها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,255,0,'35b1d04715fb0dfd9cbdfe2ddaa52f40','aba908436810078fb17dd912fd62aa17',replace($m208$يصدر الوزير المختص قرارا بقواعد ومعايير وبيان حدود الأمان فى أماكن العمل،والاشتراطات،والاحتياطات اللازمة لدرء المخاطر المبينة بهذا الباب، وذلك بالتنسيق مع الجهات المختصة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,256,0,'f7ec23a1ded6903732d3b0f8b4b28fb7','1cd2a44b5a9285458ec387af1b6c1db9',replace($m208$مع مراعاة الأحكام الواردة فى الكتاب الخامس من هذا القانون،تلتزم الجهة الإدارية المختصة بما يأتي:<<CR>>
1- تشكيل جهاز متخصص يسمى )جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل(،من أعضاء تتوافر فيهم المؤهلات العلمية والعملية فى مجالات الطب البشرى،والبيطرى،والصيدلة،والهندسة والعلوم،والبيئة وإدارة المخلفات للتفتيش على المنشآت ومراقبة تنفيذ أحكام السلامة والصحة المهنية وتأمين بيئة العمل على أن يكون التفتيش على فترات دورية مناسبة.<<CR>>
2- تنظيم برامج تدريبية متخصصة ونوعية لرفع كفاءة ومستوى أداء أعضاء جهاز التفتيش المشار إليه فى البند (1) من هذه المادة،وتزويدهم بالخبرات الفنية والتطورات الحديثة بما يضمن أفضل مستويات السلامة والصحة المهنية وتأمين بيئة العمل.<<CR>>
3- تزويد جهاز التفتيش المشار إليه بأجهزة ومعدات القياس،وجميع الإمكانيات اللازمة لأداء مهمته. ويكون التفتيش على المنشآت المتعلق عملها بالأمن القومى،والتى تحدد بقرار من رئيس مجلس الوزراء،بمعرفة الجهة التى يحددها هذا القرار.$m208$,'<<CR>>',chr(13))),
('law',14,2025,257,0,'ec13aa947510b5cbeda4cdc6a76555fb','b9d58bddd4350bfb9ad6d6f93b7cd4e7',replace($m208$على أعضاء جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل فى سبيل أداء عملهم:<<CR>>
1- إجراء الفحوص الطبية والمعملية اللازمة على العمال بالمنشآت للتأكد من ملاءمة ظروف العمل.<<CR>>
2- أخذ عينات من المواد المستعملة أو المتداولة فى العمليات الصناعية، وأنشطة العمل المختلفة والتى قد يكون لها تأثير ضار على سلامة وصحة العمال أو بيئة العمل،بغرض تحليلها والتعرف على الآثار الناتجة عن استخدامها وتداولها، وإخطار المنشأة بذلك لاتخاذ ما يلزم فى هذا الشأن.<<CR>>
3- استخدام المعدات والأجهزة وآلات التصوير وغيرها أثناء التفتيش لتحليل أسباب الحوادث.<<CR>>
4- الاطلاع على خطط الطوارئ،وتحليل المخاطر الخاصة بالمنشأة.<<CR>>
5- الاطلاع على نتائج التقارير الفنية والإدارية التى ترد للمنشأة عن أنواع الحوادث الجسيمة وأسبابها.<<CR>>
6- الاطلاع على كميات المخزون من المواد الخطرة التى قد تهدد المنشأة. وعلى الجهة الإدارية المختصة بناء على تقرير جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل الأمر بإغلاق المنشأة كليا أو جزئيا،أو إيقاف آلة،أو أكثر، وذلك فى حالة وجود خطر داهم يهدد سلامة المنشأة،أو صحة العمال والمترددين، أو سلامة بيئة العمل حتى زوال أسباب الخطر،مع عدم الإخلال بحق العاملين فى تقاضي أجورهم.<<CR>>
وللجهة الإدارية المختصة بناء على قرار الإغلاق أن تقوم بإزالة أسباب الخطر بطريق التنفيذ المباشر على نفقة المنشأة. وينفذ القرار الصادر بالإغلاق أو الإيقاف بالطرق الإدارية. وتصدر الجهة الإدارية المختصة الأمر بإلغاء الإغلاق،أو الإيقاف فور زوال أسباب الخطر.$m208$,'<<CR>>',chr(13))),
('law',14,2025,258,0,'21e464a9c2b2633246b7f3c8ecf02d01','cd61e21f0eb985a4631998a18b266de6',replace($m208$مع مراعاة حكم المادة (242) من هذا القانون،يكون لمفتشى السلامة والصحة المهنية وتأمين بيئة العمل حق التفتيش على المنشآت للتحقق من توافر اشتراطات السلامة والصحة المهنية وتأمين بيئة العمل تطبيقًا لأحكام هذا القانون،والقرارات المنفذة له.$m208$,'<<CR>>',chr(13))),
('law',14,2025,259,0,'10e7d9dcb410f1e924b8b6e33e09123c','17fdaad3ce74cbf88df7766815c3810d',replace($m208$يصدر الوزير المختص القرارات اللازمة بتحديد المنشآت،وفروعها، التى تلتزم بإنشاء أجهزة وظيفية للسلامة والصحة المهنية وتأمين بيئة العمل، واللجان المختصة بذلك. وتختص اللجان المشار إليها بالفقرة الأولى من هذه المادة ببحث ظروف العمل وأسباب حوادث وإصابات العمل وغيرها،ووضع القواعد،والاحتياطات الكفيلة بمنعها،وتكون قرارات هذه اللجان ملزمة للمنشأة وفروعها. ويجب أن يشمل التدريب العاملين بالجهاز الوظيفى للسلامة والصحة المهنية وتأمين بيئة العمل وأعضاء اللجان المختصة بذلك،والمسئولين عن الإدارة،والإنتاج بمستوياتهم كافة بما يتفق ومسئوليتهم،وطبيعة عملهم.$m208$,'<<CR>>',chr(13))),
('law',14,2025,260,0,'74da7317c496770b0b6ff2a7d6fddebd','cf11373121628ffb3978e33782b2ddfd',replace($m208$تلتزم كل منشأة يعمل بها ثلاثون عاملاً فأكثر،بموافاة الجهة الإدارية المختصة بإحصائية نصف سنوية ببيانات حقيقية عن الأمراض العادية،والمزمنة، والحوادث الجسيمة،والإصابات،وذلك خلال النصف الأول من شهرى يوليو، ويناير على الأكثر. كما تلتزم المنشآت الخاضعة لأحكام هذا الكتاب،بإخطار الجهة الإدارية المختصة بكل حادث جسيم يقع بالمنشأة،أو عند ظهور أعراض مرض مهني، وذلك خلال أربع وعشرين ساعة من وقوعه،ويصدر الوزير المختص قرارا بالنماذج التى تستخدم لهذا الغرض. وتلتزم جميع المنشآت الخاضعة لأحكام هذا الكتاب بموافاة الوزارة المختصة إلكترونيا على المنصة الإلكترونية المعدة لذلك بكافة البيانات والتقارير والإحصائيات اللازمة والتى يصدر بتحديدها قرار من الوزير المختص،ويحدد القرار البيانات الأساسية المطلوبة لذلك.$m208$,'<<CR>>',chr(13))),
('law',14,2025,261,0,'db7b3dc39cbaef4f50d5b6b695a1d59a','74d0d010f44c938cd16a04a367ec1116',replace($m208$تتولى الوزارة المختصة،والمركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المشار إليه فى المادة (263) من هذا القانون،والجهات التى يرخص لها،التدريب الأساسى،والمتقدم،والنوعى،والتخصصى للأخصائيين والفنيين،وأعضاء اللجان فى مجال السلامة والصحة المهنية. ويصدر الوزير المختص قرارا بقواعد منح التراخيص،ونظم التدريب فى الحالات السابقة فى مجال التدريب الأساسى،وتدريب السلامة والصحة المهنية والتدريب النوعي،والتخصصى،للكليات والمعاهد،والجمعيات الأهلية والشركات والمؤسسات المتخصصة،على أن يتضمن شروط منح الترخيص وإجراءاته،ومدته، والرسم المقرر عنه،بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,262,0,'03aad2a45fcb6f67aa027eba3858d9b9','5d9fddbcdffc38b455c404970e2c32c2',replace($m208$يشترط لمزاولة أعمال الخبرة والاستشارات فى مجال السلامة والصحة المهنية وتأمين بيئة العمل الحصول على الترخيص اللازم من الوزارة المختصة.<<CR>>
ويصدر الوزير المختص قرارا بتحديد شروط وقواعد،وإجراءات منح الترخيص،ومدته،وقيده فى السجل الورقى أو الإلكترونى المعد لهذا الغرض، والرسوم المقررة عنه بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$m208$,'<<CR>>',chr(13))),
('law',14,2025,263,0,'539a2bd82b74b4d49869fb4ba9f2704e','e0f1b8cf4040bc351b40f63e70263981',replace($m208$يختص المركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المعاد تنظيمه بقرار رئيس الجمهورية رقم 333 لسنة 2003 بالاشتراك مع الوزارة المختصة،بإعداد الخطط المركزية للبحوث والدراسات فى مجالات السلامة والصحة المهنية وتأمين بيئة العمل طبقًا لنتائج التحليل الإحصائى لإصابات العمل بالمنشآت، ويتابع تنفيذها بالتنسيق مع الأجهزة المعنية فى الوزارة المختصة،وذلك وفقًا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,264,0,'2aed490a92104d96c6dabd50076e948f','e13146e5dd5ddb1721dac72323bf92cc',replace($m208$ينشأ مجلس يسمى "المجلس الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل"، برئاسة الوزير المختص،وعضوية ممثلين عن الوزارات والجهات المختصة،وعدد متساو من ممثلى كل من منظمات أصحاب الأعمال المعنية الأكثر تمثيلاً ترشحهم منظماتهم،وممثلى المنظمات النقابية العمالية المعنية الأكثر تمثيلاً ترشحهم منظماتهم، على أن يراعى عند الترشيح تمثيل كافة مستويات المنظمات النقابية المعنية ما لم يتعذر ذلك،وعدد من ذوى الخبرة. ويتولى المجلس رسم السياسة العامة فى هذه المجالات واقتراح ما يلزم فى شأن تنفيذها بما يتفق مع السياسة العامة للدولة. ويصدر بتشكيل المجلس،واختصاصاته،ونظام العمل به قرار من رئيس مجلس الوزراء.$m208$,'<<CR>>',chr(13))),
('law',14,2025,265,0,'18563456a0f17cc909f1a85aacd19b13','21f132c5d096cdbe7d8480571031924e',replace($m208$يشكل فى نطاق كل محافظة لجنة فرعية للمجلس الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل،برئاسة المحافظ المختص،وتضم فى عضويتها ممثلين عن الوزارات والجهات المختصة،وممثلى المنظمات النقابية العمالية المعنية ترشحهم منظماتهم ما لم يتعذر ذلك،ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،وعدد من ذوى الخبرة. ويصدر بتشكيلها،وتحديد اختصاصاتها،ونظام العمل بها قرار من الوزير المختص.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',14,2025,266,0,'66a5f8623346fe22ead2fcb179f7fd60','25ffbfd68b9c7c60e2bf936c5538d9d8',replace($m208$مع عدم الإخلال بأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه، تلتزم المنشأة وفروعها بإجراء ما يأتي:<<CR>>
1- الكشف الطبى الابتدائى على العامل قبل التحاقه بالعمل للتأكد من سلامته، ولياقته الصحية طبقًا لنوع واحتياجات العمل الذى يسند إليه.<<CR>>
2- كشف القدرات للتأكد من لياقة العامل من ناحية قدراته الجسمانية والعقلية والنفسية بما يناسب احتياجات العمل. وتجرى هذه الفحوص طبقًا للأحكام المنظمة للتأمين الصحى،ويصدر الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة قرارا بتحديد مستويات اللياقة والسلامة الصحية والقدرات العقلية والنفسية التى تتم على أساسها هذه الفحوص.$m208$,'<<CR>>',chr(13))),
('law',14,2025,267,0,'6e43f3e15b59770b9e6fc10564c3e259','5d167314e022bdcb117f43de34d5f042',replace($m208$تلتزم المنشأة وفروعها بما يأتي:<<CR>>
1- تدريب العامل على الأسس السليمة لأداء مهنته.<<CR>>
2- إحاطة العامل قبل مزاولة العمل بمخاطر مهنته،وإلزامه باستخدام وسائل الوقاية المقررة لها مع توفير أدوات الوقاية الشخصية المناسبة وتدريبه على استخدامها. ولا يجوز للمنشأة أن تحمل العامل أية نفقات أو تقتطع من أجره أى مبالغ لقاء توفير وسائل الحماية اللازمة له.$m208$,'<<CR>>',chr(13))),
('law',14,2025,269,0,'5f67ceb33fb262f19ab12dca38cf3e93','c44eb980a79fd045fb534467943d67fd',replace($m208$تلتزم المنشأة وفروعها بإجراء ما يأتي:<<CR>>
1- التفتيش الدورى اليومى فى كل وردية عمل على أماكن العمل وخاصة الخطرة منها لاكتشاف المخاطر المهنية،والعمل على الوقاية منها،وإعداد سجل ورقى أو إلكترونى لهذا الغرض.<<CR>>
2- فحص شكوى العامل المرضية،ومعرفة علاقتها بنوع العمل بمعرفة طبيب المنشأة،إن وجد.<<CR>>
3- التنسيق مع الهيئة العامة للتأمين الصحى لإجراء الفحص الطبى الدورى لجميع عمال المنشأة للمحافظة على لياقتهم الصحية والنفسية والعقلية، وسلامتهم بصفة مستمرة واكتشاف ما يظهر من أمراض مهنية فى مراحلها الأولى ولإجراء الفحص عند انتهاء الخدمة،وذلك كله طبقًا لأنظمة التأمين الصحى المقررة فى هذا الشأن.$m208$,'<<CR>>',chr(13))),
('law',14,2025,270,0,'f466b7d2ee1f1fc6feacf035ee6cf055','2c45d072fd3935f257025c2c0cf2a2cc',replace($m208$تلتزم المنشأة بأن توفر لعمالها وسائل الإسعاف الأولية. وإذا زاد عدد عمال المنشأة فى مكان واحد أو بلد واحد أو فى دائرة نصف قطرها خمسة عشر كيلو مترا على خمسين عاملاً،تلتزم المنشأة بأن تستخدم ممرضا مؤهلاً أو أكثر الأعمال التمريض أو الإسعاف بكل وردية عمل بها،وأن تعهد إلى طبيب لعيادتهم فى المكان الذى تعده لهذا الغرض،وأن تقدم لهم الأدوية اللازمة للعلاج،وذلك كله بالمجان.<<CR>>
وإذا عولج العامل فى الحالتين المنصوص عليهما فى الفقرتين الأولى والثانية من هذه المادة بمستشفى حكومى أو خيرى،وجب على المنشأة أن تؤدى إلى إدارة المستشفى نفقات العلاج،والأدوية،والإقامة. ويتبع فى تحديد نفقات العلاج،والأدوية،والإقامة المنصوص عليها فى الفقرات السابقة الطرق والأوضاع التى يصدر بها قرار من الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,271,0,'60d60abde23a384b02e15da0de0941c0','61fdb9d2708a402c5d36dd78b073067d',replace($m208$يلتزم من يستخدم عمالاً فى أماكن لا تصل إليها وسائل المواصلات العادية أن يوفر لهم وسائل الانتقال المناسبة على نفقته الخاصة. وعلى من يستخدم عمالاً فى المناطق البعيدة عن العمران أن يوفر لهم التغذية المناسبة،والمساكن الملائمة مع مراعاة تخصيص بعضها للعمال المتزوجين على نفقته الخاصة. ويصدر الوزير المختص بالاتفاق مع الوزراء المعنيين،ومع منظمات أصحاب الأعمال والعمال القرارات اللازمة لتحديد المناطق البعيدة عن العمران،واشتراطات ومواصفات المساكن،وتعيين أصناف الطعام والكميات التى تقدم منها لكل عامل، وما يؤديه صاحب العمل مقابلاً لها. ويجوز بالنسبة لنظام الوجبات الغذائية الواردة فى الفقرة الثالثة من هذه المادة الأخذ بنظام توافق عليه إدارة المنشأة والمنظمة النقابية العمالية أو المفوض العمالى فى حالة عدم وجودها،بشرط أن يعتمد من الجهة الإدارية المختصة،ويحظر الاستعاضة عن تقديم تلك الوجبات كلها أو بعضها بمقابل نقدى.$m208$,'<<CR>>',chr(13))),
('law',14,2025,272,0,'cc6530f07aabe9144517de7d7a6fbcb8','180bd1e007218af86253a779f4e0a7e0',replace($m208$تلتزم المنشأة التى يبلغ عدد عمالها خمسين عاملاً فأكثر بتقديم الخدمات الاجتماعية والثقافية اللازمة لعمالها،وذلك بالاشتراك مع المنظمة النقابية العمالية، دون تحميل العامل أى التزامات،ويصدر الوزير المختص بالتشاور مع منظمات أصحاب الأعمال والعمال القرارات المشار إليها بتحديد الحد الأدنى لهذه الخدمات.$m208$,'<<CR>>',chr(13))),
('law',14,2025,273,0,'d9fbcdf3f8e2de37eec5ef2548e50cca','37607c19239937fa556a4bbade7c0cce',replace($m208$يتمتع صندوق الخدمات الاجتماعية والصحية والثقافية بالشخصية الاعتبارية، ويهدف إلى تقديم الخدمات اللازمة للنهوض بالمستوى الاجتماعى والصحى والثقافى للعاملين بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،ترشحهم منظماتهم،وممثلى الوزارات والجهات المعنية ويحدد القرار اختصاصات المجلس والنظام الأساسى للصندوق والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية، والنظام المحاسبى الواجب إتباعه. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المسجلة لدى البنك المركزى المصرى،وموازنة مستقلة،ويعد الصندوق سنويا القوائم الدالة على المركز المالى وفقًا لنظام المحاسبة المالية،وتبدأ السنة المالية للصندوق مع السنة المالية للدولة،وتنتهى بانتهائها وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات، ويرحل فائض أمواله من سنة إلى أخرى. وتلتزم المنشآت المشار إليها بالفقرة الأولى من هذه المادة والتى يبلغ عدد عمالها عشرون عاملاً فأكثر بسداد اشتراك سنوى لا يقل عن ثمانية جنيهات ولا يجاوز ستة عشر جنيها عن كل عامل سنويا لتمويل هذا الصندوق،ويصدر بتحديد قيمة الاشتراك السنوى قرار من الوزير المختص،بعد العرض على مجلس إدارة الصندوق،ويحق للمنشأة حال تقديمها للخدمات الواردة بالمادة 274 من هذا القانون،أو تقديمها لميزة أفضل للعاملين لديها خصم قيمة تلك الخدمات أو الميزة أو خصم ) (%70 من المبلغ المستحق عليها للصندوق سنويا،أيهما أقل.$m208$,'<<CR>>',chr(13))),
('law',14,2025,274,0,'6e848eb41f78ab5334ff662933a83537','313c00dd2788a797551f6c7a52d2e869',replace($m208$يلتزم الصندوق المشار إليه فى المادة (273) من هذا القانون بتقديم الخدمات الآتية:<<CR>>
1- دعم النفقات العلاجية طبقًا لما تحدده اللائحة المالية والإدارية للصندوق والتى تحدد أنواع الخدمات الطبية والمنتفعين بها واللجان المختصة بتقرير العلاج والجهات التى تتولى تنفيذ الخدمات الصحية.<<CR>>
2- تدعيم مكتبات المنشآت بالكتب.<<CR>>
3- عقد الندوات الثقافية أو تمويلها.<<CR>>
4- دعم تكاليف تنظيم انتخابات المنظمات النقابية العمالية.<<CR>>
5- إعداد برامج محو الأمية بالتعاون مع الجهات المختصة.<<CR>>
6- تدعيم الأنشطة الرياضية بالمنشأة.<<CR>>
7- إقامة المسابقات اللازمة لتنمية مهارات العاملين فنيا وثقافيا ورياضيا.<<CR>>
8- إعداد برامج الرحلات الترفيهية،والمصايف طبقًا لإمكانيات العمال.<<CR>>
9- دعم الأنشطة النقابية العمالية.<<CR>>
10- مشاركة العمال وأصحاب العمل فى توفير بيئة عمل آمنة خالية من العنف والتحرش والتنمر من خلال إقامة الندوات التوعوية وتمويل المشروعات التنموية التى تستهدف ذلك متى توافرت الموارد. وللوزير المختص بالاتفاق مع مجلس إدارة الصندوق إضافة خدمات أخرى على أن تكون فى ذات مجال عمل الصندوق. ويصدر رئيس مجلس الوزراء قرارا باللائحة المالية والإدارية للصندوق، وصلاحيات وضوابط الصرف والرقابة عليها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,275,0,'6730e5e92b6c31055b60f989f292714b','ef9c0be014333af2ea065cb5b816308d',replace($m208$يكون للعاملين القائمين على تنفيذ أحكام هذا القانون،والقرارات الصادرة تنفيذًا له،الذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع الوزير المختص، صفة مأمورى الضبط القضائى بالنسبة للجرائم التى تقع فى دوائر اختصاصهم، وتكون متعلقة بأعمال وظائفهم.<<CR>>
ويؤدى كل منهم أمام الوزير المختص قبل مباشرة عمله القسم الآتى ":أقسم باالله العظيم أن أؤدى مهمتى بالذمة والأمانة والصدق وألا أفشى سرا من أسرار العمل التى أطلع عليها بحكم وظيفتى".$m208$,'<<CR>>',chr(13))),
('law',14,2025,276,0,'0a66378312bca8152d3470858aaa2f7f','a860ad5b20902067b4149d20e60a1ced',replace($m208$يحمل كل من له صفة الضبطية القضائية،بطاقة تثبت هذه الصفة،وله حق دخول جميع أماكن العمل وتفتيشها للتحقق من تطبيق أحكام هذا القانون،والقرارات المنفذة له،وفحص الدفاتر والأوراق المتعلقة بذلك،وطلب المستندات والبيانات اللازمة من أصحاب الأعمال أو من ينوب عنهم. ويحدد الوزير المختص بقرار منه قواعد وإجراءات التكليف بتفتيش أماكن العمل ليلاً وفى غير أوقات العمل الرسمية للقائمين به والمكافآت التى تستحق لهم.$m208$,'<<CR>>',chr(13))),
('law',14,2025,278,0,'22f299770076b2e036a21e93de052f76','88a42ee38587dce4814662f9b796549a',replace($m208$على أصحاب الأعمال أو من ينوب عنهم الاستجابة لطلبات الحضور التى توجه إليهم من العاملين المشار إليهم فى المادة (275) من هذا القانون،وذلك فى المواعيد التي يحددونها.$m208$,'<<CR>>',chr(13))),
('law',14,2025,281,0,'ea607d9c86dfd5547193dc650ae419a3','02561f5f4d73dc3f139dfdc1e2039b03',replace($m208$يعاقب كل من يخالف أحكام المادتين (4، 5) من هذا القانون بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على خمسين ألف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,282,0,'d045345b60679636d7dd1d2e2ca3d3f1','8d054ac2b936b97e5ded58a38cabeec6',replace($m208$يعاقب كل من يخالف أحكام المادتين )/82 البندين 1 و/273)، (2 فقرة رابعة( من هذا القانون،والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن ألف جنيه ولا تزيد على عشرة آلاف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها فى الفقرة الأولى من هذه المادة، كل من يخالف أحكام المادة )/21 بند (1 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,283,0,'2c343be50a49062d926775a1a38af6e5','8c6e04753f59fadebdf80ef7687e411e',replace($m208$يعاقب كل من يخالف أحكام المواد ) 37 فقرة أولى /48،فقرة أولى (153، من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن ألفى جنيه ولا تزيد على عشرة آلاف جنيه،وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة،كل من يخالف حكم المادة 137 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,284,0,'54fd4c0e68c029346b6a3fa847f3d938','718e68de2613a716ead3c8f6a29a2134',replace($m208$يعاقب كل من يخالف أحكام المادة (26) من هذا القانون والقرارات الوزارية المنفذة لها بغرامة لا تقل عن ألف جنيه ولا تزيد على عشرة آلاف جنيه، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,285,0,'2510dffce4d83804b472cccf8ab1b8ec','6dfeca37353b84fdcda081c4123058f6',replace($m208$يعاقب كل من يخالف أحكام المادة (23) من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه،وللمحكمة عند الحكم بالإدانة أن تقضى بإغلاق المنشأة،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,286,0,'5cf93bd1cd9b7d29a53bc78b0dbbca0f','c13478221d8b371dc18b988f5e6374dc',replace($m208$يعاقب كل من يخالف أحكام المادة السابعة من مواد إصدار هذا القانون والمواد (24، 25، 36، 46، 51، 52، 68) من هذا القانون،والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن ألف جنيه ولا تزيد على عشرين ألف جنيه، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة،كل من يخالف أحكام المواد (38، 122، 175) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,287,0,'dfca7d8151aadd5ca25ef99d295e494f','0a2b44a8ffe7226d8f91013c37e35d41',replace($m208$يعاقب كل من يخالف أحكام المواد (45، 104، 108) من هذا القانون، بغرامة لا تقل عن ألفى جنيه ولا تزيد على عشرين ألف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,288,0,'9b82365bfaa690e99b01516747105cf6','0ce572caaf630e2469777d3f19749d66',replace($m208$يعاقب كل من يخالف أحكام المواد )، 119، 118، 117، 60، 53، 27 /135، 132، 124، 123 فقرة ثانية /254،فقرة أولى( من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن خمسمائة جنيه ولا تزيد على خمسة آلاف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة، وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة، كل من يخالف أحكام المواد )، 89، 59، 58، 57، 56، 55، 54، 29، 12، 116، 115، 114، 113، 112، 111، 110، 94، 93، 92، 91، 90 /138، 131، 129، 128، 126، 125، 121، 120 فقرة ثانية، 156، (173، 164، 162، 159 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,289,0,'7b3c4c2e577ac7bebd593f833fab6a70','22c70a83e1a814e23c980a2ac0c711ed',replace($m208$يعاقب صاحب العمل أو من يمثله عن المنشأة إذا خالف أى من أحكام المواد )، 63 (66، 64 من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن ألفى جنيه ولا تزيد على عشرة آلاف جنيه،وفى كل الأحوال تتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وفى حالة العود تضاعف الغرامة ويحكم بغلق المنشأة لمدة لا تجاوز الستة أشهر. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة،كل من يخالف أحكام المادتين (62، 65) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,290,0,'9842192c96087de78f7a3bcbfd48a39c','1c1acfa346de6d7cc77749b3a3e01f66',replace($m208$يعاقب كل من يخالف أحكام المادتين (33، 37) من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن خمسمائة جنيه ولا تزيد على ألف جنيه، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة،كل من يخالف أحكام المادتين (35، 205) من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,291,0,'4fde01037f2ed536bab79cd715dcc026','857b9b430e84c76f8f46d2da4e4d19ca',replace($m208$يعاقب بالحبس وبغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه،أو بإحدى هاتين العقوبتين،كل من ارتكب إحدى الجرائم الآتية:<<CR>>
1- مزاولة عمليات إلحاق العمالة للعمل داخل البلاد أو خارجها من غير الجهات المحددة فى المادة (40) من هذا القانون دون الحصول على الترخيص المنصوص عليه فى المادة (41) من هذا القانون،أو بترخيص صادر بناء على بيانات غير صحيحة.<<CR>>
2- تقاضى مبالغ دون وجه حق من أجر العامل أو من مستحقاته عن عمله فى الداخل،أو الخارج.<<CR>>
3- تقديم بيانات غير صحيحة عن اتفاقيات أو عقود إلحاق للعمل بالخارج، أو أجورهم أو شروط وظروف عملهم،أو عقود عمل وهمية بالمخالفة للواقع. وفى جميع الأحوال،يحكم برد المبالغ التى تم تقاضيها أو الحصول عليها دون وجه حق،وللمحكمة أن تقضى فى حالات الإدانة بإغلاق المنشأة،ويكون الإغلاق وجوبيا فى حالة الإدانة بإحدى الجرائم المشار إليها فى البند (1) من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',14,2025,292,0,'d04c4cd8fa40c4ad774542433d40e310','2b54fff11641a45276b943efcef4196c',replace($m208$يعاقب كل من يخالف أحكام المادة (42) من هذا القانون،والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على مائة ألف جنيه، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,293,0,'91abf9ef99d135605f00a558e51af067','0f663d6f12f7e609cd8e5477793562bb',replace($m208$يعاقب كل من يخالف أحكام المواد (70، 71، 72، 74) من هذا القانون، والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة، وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,294,0,'a2a94370c8d00127f5d58ad383163fac','d9882b7c6c6335bf01bd409f408bf09d',replace($m208$يعاقب كل من يخالف أحكام المواد )، 145، 144، 143، 142، 141، 140 / 151 فقرة ثانية (198، 152،من هذا القانون،بغرامة لا تقل عن ألف جنيه ولا تزيد على عشرين ألف جنيه،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,295,0,'e34d5f992526367bf59b9402c3ab06e5','04e17bc3d70e98926c5f108dca7975d4',replace($m208$يعاقب كل من يخالف أحكام المواد (236، 237، 239) من هذا القانون والقرارات الوزارية المنفذة لها،بغرامة لا تقل عن ثلاثة آلاف جنيه ولا تزيد على عشرة آلاف جنيه،وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة، وتضاعف الغرامة فى حالة العود.<<CR>>
كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة، كل من يخالف أحكام المواد )/241، 240، 238، 172، 170، 169 فقرة ثالثة( من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,296,0,'ec8f368c59eae5625b9c87c14fc5e8e3','53391694be15ceac5b0711681b150521',replace($m208$يعاقب كل من يخالف أحكام المواد )، 261، 260، 259، 255، 254، 245 (272، 271، 270، 266، 262 من هذا القانون،والقرارات الوزارية المنفذة لها بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز مائة ألف جنيه،وتضاعف الغرامة فى حالة العود. كما يعاقب بذات العقوبة المشار إليها بالفقرة الأولى من هذه المادة كل من يخالف أحكام المواد )، 267، 253، 252، 251، 250، 249، 248، 247، 246 (269، 268 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',14,2025,297,0,'7afdc0063c2beb17987b6f53da247c34','38003b3cf7991e0ac0555515ecb2a20a',replace($m208$يعاقب صاحب العمل أو من يمثله عن المنشأة إذا خالف أحكام المادتين )، 277 (278 من هذا القانون،بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه،وتضاعف الغرامة فى حالة العود.$m208$,'<<CR>>',chr(13))),
('law',14,2025,298,0,'ec4c249fb4c89188e70512de58ba4ef0','c0488e4827aff244047a2e9759865fd7',replace($m208$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى بالعقوبة ذاتها المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون إذا ثبت علمه بها وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم فى وقوع الجريمة. ويكون الشخص الاعتبارى مسئولاً بالتضامن عن الوفاء بما يحكم به من عقوبات مالية وتعويضات.$m208$,'<<CR>>',chr(13))),
('law',164,2025,6,0,'d9eec8af65a6ca7d5250ff42b59670e7','9f1d1f07b503b8b99db0b2f5285de686',replace($m208$تزاد القيمة الإيجارية المحددة وفقاً للمادتين (4 ، 5) من هذا القانون سنويًا بصفة دورية بنسبة (15%) .$m208$,'<<CR>>',chr(13))),
('law',174,2025,1,0,'409b598168e71bfa8d262619d17b86f6','50a0663947636c749aab48c27ce3d246',replace($m208$تتولى النيابة العامة التحقيق ،وتحريك ،ومباشرة الدعوى الجنائية ،ولا تتخذ هذه الإجراءات من غيرها إلا في الأحوال المحددة في القانون.
ولا يجوز ترك الدعوى الجنائية ،أو وقفها ،أو تعطيل سيرها إلا في الأحوال المحددة في القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,2,0,'a193a3fb735ede6d9fe5c0470944d721','2926d69656c5faa10d513908d98d24b3',replace($m208$يتولى النائب العام بنفسه أو بواسطة أحد أعضاء النيابة العامة مباشرة الدعوى الجنائية على النحو المبين بالقانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,3,0,'74b85a450319089df3bb2689d93213f2','406388ab2bcd033d9bdf1d353bf942e9',replace($m208$لا يجوز رفع الدعوى الجنائية أو اتخاذ أي إجراء من إجراءات التحقيق فيها إلا بناء على شكوى شفهية أو كتابية من المجني عليه أو من وكيله الخاص ،إلى النيابة العامة أو إلى أحد مأموري الضبط القضائي في الجرائم المنصوص عليها في المواد 308 ،307 ،306 ،303 ،293 ،292 ،279 ،277 ،274 ،185 من قانون العقوبات ،وكذلك في الأحوال الأخرى التي ينص عليها القانون.
ولا تقبل الشكوى بعد تسعين يوما من يوم علم المجني عليه بالجريمة وبمرتكبها ما لم ينص القانون على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,5,0,'51ae89606a4ecb87b57d508b43639fd6','ded291a8fcf20974fec0d2620f668867',replace($m208$تقدم الشكوى ممن له الولاية على المجني عليه إذا لم يبلغ خمس عشرة سنة كاملة ،أو كان مصابا باضطراب نفسي أو عقلي.
وإذا كانت الجريمة واقعة على المال ،تقبل الشكوى كذلك من الوصي أو القيم.
وتسري جميع الأحكام الخاصة بالشكوى على الحالات المشار إليها بالفقرتين الأولى والثانية من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,6,-1,'8f2a7d03ffdd304314698e7bd107e0ef','d4cb06f89da8f0cc8ac2757d4c7af676',replace($m208$ينشر هذا القانون في الجريدة الرسمية، ويعمل به اعتبارا من الأول من أكتوبر التالي لتاريخ نشره.

يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوانينها.

صدر برئاسة الجمهورية فى 21 جمادى الأولى سنة 1447 هـ (الموافق 12 نوفمبر سنة 2025 م).

عبد الفتاح السيسى$m208$,'<<CR>>',chr(13))),
('law',174,2025,6,0,'84c7c59220dd0c40e607df4902c5a836','49109c2a271729aeaecfdb704eb09537',replace($m208$تقوم النيابة العامة مقام المجنى عليه إذا لم يكن له من يمثله أو إذا تعارضت مصلحته مع مصلحة من يمثله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,7,0,'c669a41fd71b28ca2ea56f443e961aee','02d4af9555875a7f637fb4ccf5681e08',replace($m208$ينقضي الحق في الشكوى بموت المجني عليه ،وإذا حدث الموت بعد تقديم الشكوى فلا يؤثر على سير الدعوى الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,8,0,'6ca2ce26828af538bab6c9f524d37517','e400f2de18330a9175f480b5e96c9f80',replace($m208$لا يجوز رفع الدعوى الجنائية أو اتخاذ أي إجراء من إجراءات التحقيق فيها إلا بناء على طلب كتابي من وزير العدل في الجرائم المنصوص عليها في المادتين  182 ،181 من قانون العقوبات ،وكذلك في الأحوال الأخرى التي ينص عليها القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,9,0,'956d44f17074004d2713d2bd7c70937b','a80a46497f4791d018ebe9a72215e6dd',replace($m208$لا يجوز رفع الدعوى الجنائية في الجرائم المنصوص عليها في المادة 116 مكررا )أ( من قانون العقوبات ،إلا من النائب العام أو محامٍ عام على الأقل.
وفيما عدا الجرائم المشار إليها في المادة  123 من قانون العقوبات ،لا يجوز رفع الدعوى الجنائية ضد موظف عام أو مستخدم عام أو أحد رجال الضبط لجنحة وقعت منه أثناء تأدية وظيفته أو بسببها إلا من رئيس نيابة على الأقل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,10,0,'074edd1c6d01885de2b6875e5c42af3d','773efc8f99bff3249872db9ba197a5b1',replace($m208$لا يجوز رفع الدعوى الجنائية أو اتخاذ أي إجراء من إجراءات التحقيق فيها إلا بناء على طلب كتابي من الهيئة أو رئيس المصلحة المجني عليها في الجرائم المنصوص عليها في المادة  184 من قانون العقوبات.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,11,0,'0bdf311d9a57b01ebf80e9d16e9dbd64','b3e1c73cfbed4a4202bb4d7ecb7166c1',replace($m208$في جميع الأحوال التي يشترط فيها القانون لرفع الدعوى الجنائية تقديم شكوى أو طلب أو الحصول على إذن من المجني عليه أو غيره ،لا يجوز اتخاذ إجراءات التحقيق فيها إلا بعد تقديم هذه الشكوى أو الطلب أو الحصول على هذا الإذن.
واستثناء من حكم الفقرة الأولى من هذه المادة يجوز اتخاذ إجراءات التحقيق في الدعوى الجنائية دون حاجة إلى تقديم شكوى أو طلب أو الحصول على إذن، في الجرائم المنصوص عليها في المواد  308 ،307 ،306 ،303 ،185 من قانون العقوبات إذا كان المجني عليه فيها موظفًا عاما أو شخصا ذا صفة نيابية عامة أو مكلفًا بخدمة عامة وكان ارتكاب الجريمة بسبب أداء الوظيفة أو النيابة أو الخدمة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,12,0,'dd32e0d58fc0a9cf8cf36391e7e0b4e7','760d2e63f7d7e258c1794b29ab334aed',replace($m208$يجوز لمن قدم الشكوى أو الطلب في الأحوال المشار إليها في هذا الفصل، وللمجني عليه في الجرائم المنصوص عليها في المواد ،307 ،306 ،303 ،185 308 من قانون العقوبات إذا كان موظفًا عاما أو شخصا ذا صفة نيابية عامة أو مكلفًـا بخدمة عامة وكان ارتكاب الجريمة بسبب أداء الوظيفة أو النيابة أو الخدمة العامة، أن يتنازل عن الشكوى أو الطلب في أي حالة تكون عليها الدعوى ولو بعد صيرورة الحكم باتًا ،ويترتب على التنازل انقضاء الدعوى الجنائية ،وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا تم التنازل أثناء تنفيذها.
وفي حالة تعدد المجني عليهم لا يعتبر التنازل صحيحا إلا إذا صدر من جميع من قدموا الشكوى.
ويعد التنازل بالنسبة لأحد المتهمين تنازلاً للباقين.
وإذا مات الشاكي لا ينتقل حقه في التنازل إلى ورثته ،إلا في دعوى الزنا يجوز لأىِ من أولاد الزوج الشاكي من الزوج المشكو منه أن يتنازل عن الشكوى ويترتب على التنازل انقضاء الدعوى الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,13,0,'1af659a577106491698d3030ad50b638','724a6e3604da972e37184163e3e21679',replace($m208$إذا رأت محكمة جنايات أول درجة في دعوى مرفوعة أمامها أن هناك متهمين غير من أقيمت الدعوى عليهم أو وقائع أخرى غير المسندة فيها إليهم ،أو أن هناك جناية أو جنحة مرتبطة بالتهمة المعروضة عليها ،يجوز لها أن تقيم الدعوى الجنائية على هؤلاء الأشخاص أو بالنسبة لهذه الوقائع وتُحيلها إلى النيابة العامة لتحقيقها والتصرف فيها طبقًا للباب الثالث من الكتاب الأول من هذا القانون.
ويجوز للمحكمة أن تندب أحد أعضائها للقيام بإجراءات التحقيق ،وفي هذه الحالة تسري على العضو المنتدب جميع الأحكام الخاصة بقاضي التحقيق.
وإذا صدر قرار في نهاية التحقيق بإحالة الدعوى إلى المحكمة ،وجب إحالتها إلى محكمة أخرى ،ولا يجوز أن يشترك في الحكم فيها أحد القضاة الذين قرروا إقامة الدعوى.
وإذا كانت المحكمة لم تفصل في الدعوى الأصلية وكانت مرتبطة مع الدعوى المقامة منها ارتباطًا لا يقبل التجزئة ،وجب إحالة الدعوى كلها إلى محكمة أخرى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,14,0,'0662efc450d8e83f21fcf2fd8a13a0a5','10220ac242b22d234a9ea8d8fff81f75',replace($m208$يجوز لمحكمة الجنايات المستأنفة ،وللدائرة الجنائية بمحكمة النقض عند نظر الموضوع ،إقامة الدعوى الجنائية ،طبقا لما هو مقرر بالمادة  13 من هذا القانون.
وإذا طعن في الحكم الذي يصدر في الدعوى المقامة منها ،فلا يجوز أن يشترك في نظرها أحد القضاة الذين قرروا إقامتها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,15,0,'0cb62de0ea87eba965f7718193aad49b','0086296cb47566571fab8a1fd83b54fa',replace($m208$يجوز لمحكمة الجنايات بدرجتيها أو محكمة النقض إذا وقعت أفعال من شأنها الإخلال بأوامرها ،أو بالاحترام الواجب لها ،أو التأثير في قضائها ،أو في الشهود، وكان ذلك بصدد طلب أو دعوى منظورة أمامها أن تقيم الدعوى الجنائية على المتهم طبقًا للمادة  13 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,16,0,'3e7efbcd067dc7fe54dd19c5c4160b6a','e8263cc7afadf2bf17c075cb2ff809f5',replace($m208$تنقضي الدعوى الجنائية بموت المتهم ،أو بمضي المدة ،أو بصدور حكم بات فيها ،أو بالعفو الشامل ،أو بالصلح أو التصالح أو بالأسباب الأخرى التي ينص عليها القانون.
ولا يمنع موت المتهم أثناء نظر الدعوى من الحكم بالمصادرة في الحالة المنصوص عليها في الفقرة الثانية من المادة  30 من قانون العقوبات.
ولا يحول انقضاء الدعوى الجنائية بعد رفعها لأي سبب دون الحكم بالرد في الأحوال المنصوص عليها فى القانون ،أو القضاء بأية عقوبات مالية منصوص عليها في البابين الثالث والرابع من الكتاب الثاني من قانون العقوبات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,17,0,'e4bb1e6a3975b64cca5434561fee34a2','651415378b563e1faf086a4cba93ea8d',replace($m208$تنقضى الدعوى الجنائية فى مواد الجنايات بمضى عشر سنين من يوم وقوع الجريمة ،وفى مواد الجنح بمضى ثلاث سنين ،وفى مواد المخالفات بمضى سنة ،ما لم ينص القانون على خلاف ذلك.
واستثناء من حكم الفقرة الأولى من هذه المادة لا تنقضى بمضى المدة الدعوى الجنائية الناشئة عن الجرائم المنصوص عليها فى المواد ،127 ،126 ،117 161 مكررا 309 ،282 ،281 ،280 ،مكررا 309 ،مكررا )أ( والجرائم المنصوص عليها فى الباب الأول والقسم الأول من الباب الثانى من الكتاب الثانى من قانون العقوبات.
ومع عدم الإخلال بأحكام الفقرتين الأولى والثانية من هذه المادة لا تبدأ مدة انقضاء الدعوى الجنائية فى الجرائم المنصوص عليها فى البابين الثالث والرابع من الكتاب الثانى من قانون العقوبات ،والتى تقع من موظف عام إلا من تاريخ انتهاء الخدمة أو زوال الصفة ما لم يبدأ التحقيق فيها قبل ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,19,0,'20a3514f7b93022fdfdd89f9da899a2a','7d2c2490ef0cbcaaa6fe1e162a200aee',replace($m208$تنقطع المدة التي تنقضي بها الدعوى الجنائية بإجراءات التحقيق أو الاتهام والمحاكمة ،وكذلك بالأمر الجنائي ،أو بإجراءات الاستدلال إذا اتخذت في مواجهة المتهم ،أو إذا أخطر بها بوجه رسمي ،وتسري المدة من جديد ابتداء من يوم الانقطاع.
وإذا تعددت الإجراءات التي تقطع المدة فإن سريان المدة من جديد يبدأ من تاريخ آخر إجراء.
وإذا تعدد المتهمون فإن انقطاع المدة بالنسبة لأحدهم يترتب عليه انقطاعها بالنسبة للباقين ولو لم تكن قد اتخذت ضدهم إجراءات قاطعة للمدة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,20,0,'ad1baee9917cb6d06405e8bf3e4ed7ab','81f4b2b008a5944bc0cca0c7c0c95bdc',replace($m208$يجوز للمتهم أو وكيله الخاص التصالح في المخالفات وكذلك في الجنح التي لا يعاقب عليها وجوبا بغير الغرامة أو التي يعاقب عليها جواز يا بالحبس الذي لا يزيد حده الأقصى على ستة أشهر.
وعلى محرر المحضر أو النيابة العامة بحسب الأحوال أن يعرض التصالح على المتهم أو وكيله الخاص ويثبت ذلك في المحضر.
وعلى المتهم الذي يرغب في التصالح أن يدفع قبل رفع الدعوى الجنائية مبلغًـا يعادل ثلث الحد الأقصى للغرامة المقرر للجريمة ،ويكون الدفع إلى خزانة المحكمة أو النيابة العامة أو إلى من يرخص له في ذلك من وزير العدل.
ولا يسقط حق المتهم في التصالح برفع الدعوى الجنائية إلى المحكمة المختصة إذا دفع ثلثي الحد الأقصى للغرامة المقرر للجريمة أو قيمة الحد الأدنى المقرر لها أيهما أكثر ،وذلك قبل صدور حكم في الموضوع.
وتنقضي الدعوى الجنائية بدفع مبلغ التصالح ،ولا يكون لهذا الانقضاء أثر على الدعوى المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,21,0,'9dd9858efe29aedaa20c829056d37d35','dbd02962115dbc71426de7c8931c8558',replace($m208$يجوز للمجني عليه أو وكيله الخاص ،ولورثة المجنى عليه أو وكيلهم الخاص، إثبات الصلح مع المتهم أمام النيابة العامة أو المحكمة بحسب الأحوال ،وذلك في الجنح والمخالفات المنصوص عليها في المواد ) /238 الفقرتين الأولى والثانية(/241 ، )الفقرتين الأولى والثانية() /242 ،الفقرات الأولى والثانية والثالثة() /244 ،الفقرتين الأولى والثانية( 321 ،265 ،مكررا 323 ،323 ،مكررا 323 ،مكررا "أولاً"324 ، ـى ـرتين الأولـ ـررا) /361 ،360 ،358 ،354 ،342 ،341 ،340 ،336 ،الفقـ مكـ ـود ،(9 ،7 ،6 ـد ) /378 ،(9 البنـ ـة() /377 ،373 ،371 ،370 ،369 ،البنـ والثانيـ ) /379 البند  (4 من قانون العقوبات ،وفي الأحوال الأخرى التي ينص عليها القانون.
ويجوز للمتهم أو وكيله الخاص إثبات الصلح المشار إليه في الفقرة الأولى من هذه المادة.
ويجوز الصلح في أية حالة كانت عليها الدعوى ،وبعد صيرورة الحكم باتًا.
ويترتب على الصلح انقضاء الدعوى الجنائية ولو كانت مرفوعة بطريق الادعاء المباشر ،وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا حصل الصلح قبل أو أثناء تنفيذها، ولا أثر للصلح على حقوق المضرور من الجريمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,22,0,'00bca2873b609422ad7c1a0ccd5b6ab4','8027a0c80bfdf8c10bca13b0444858e8',replace($m208$مع عدم الإخلال باختصاصات رئيس الجمهورية في العفو عن العقوبة أو تخفيفها ،يجوز لورثة المجني عليه أو وكيلهم الخاص إثبات الصلح في أية حالة كانت عليها الدعوى إلى أن يصدر فيها حكم بات في الجرائم المنصوص عليها في المواد ) /234 ،233 ،230 الفقرتين الأولى والثانية() /236 ،235 ،الفقرة الأولى( من قانون العقوبات ،ويترتب على الصلح في هذه الحالة تخفيف العقوبة وفقًـا لحكم المادة  17 من قانون العقوبات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,23,0,'702a5b5d13baabdf174a89d9e825b96b','3712b876068bddcf2c743f8c112d600a',replace($m208$يجوز التصالح في الجرائم المنصوص عليها في الباب الرابع من الكتاب الثاني من قانون العقوبات ويكون التصالح بموجب تسوية بمعرفة لجنة من الخبراء يصدر بتشكيلها قرار من رئيس مجلس الوزراء ويحرر محضر يوقعه أطرافه يعرض على مجلس الوزراء لاعتماده ولا يكون التصالح نافذًا إلا بهذا الاعتماد ويعد اعتماد مجلس الوزراء توثيقًا له دون رسوم ويكون لمحضر التصالح في هذه الحالة قوة السند التنفيذي ،ويتولى مجلس الوزراء إخطار النائب العام سواء كانت الدعوى ما زالت قيد التحقيق أو المحاكمة ويترتب عليه انقضاء الدعوى الجنائية عن الواقعة محل التصالح بجميع أوصافها وتأمر النيابة العامة بوقف تنفيذ العقوبات المحكوم بها على المتهمين في الواقعة إذا تم التصالح قبل صيرورة الحكم باتًا ،فإذا تم التصالح بعد صيرورة الحكم باتًا وكان المحكوم عليه محبوسا نفاذًا لهذا الحكم جاز له أو لوكيله الخاص أن يتقدم إلى النائب العام بطلب لوقف التنفيذ مشفوعا بالمستندات المؤيدة له ،ويرفع النائب العام الطلب إلى محكمة النقض مشفوعا بهذه المستندات ومذكرة برأي النيابة العامة وذلك خلال عشرة أيام من تاريخ تقديمه ،ويعرض على إحدى الدوائر الجنائية بالمحكمة منعقدة في غرفة المشورة لنظره لتأمر بقرار مسبب بوقف تنفيذ العقوبات نهائيا إذا تحققت من إتمام التصالح واستيفائه جميع الشروط والإجراءات المنصوص عليها في هذه المادة ويكون الفصل في الطلب خلال خمسة عشر يوما من تاريخ عرضه وبعد سماع أقوال النيابة العامة والمحكوم عليه.
وفي جميع الأحوال ،يمتد أثر التصالح إلى جميع المتهمين أو المحكوم عليهم دون المساس بمسئوليتهم التأديبية ويقدم طلب التصالح من المتهم أو المحكوم عليه أو وكيلهما الخاص ،ويجوز للأخير اتخاذ جميع الإجراءات المتعلقة بإعادة إجراءات المحاكمة في غيبة المحكوم عليه في الأحكام الصادرة غيابيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,24,0,'2eac5a09f317cee95ed6fe9fd5a116a0','b18cdf44d5f0a1f24ca8494d9ea9aca7',replace($m208$يتولى مأمور الضبط القضائي البحث عن الجرائم ومرتكبيها ،وجمع الاستدلالات التي تلزم للتحقيق والدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,25,0,'3dbc438d1fdb470fda3e8db297aa72bc','5c5f98a46e29626331fadb5d0fe2a7b2',replace($m208$مأمورو الضبط القضائي تابعون للنائب العام وخاضعون لإشرافه فيما يتعلق بأعمال وظائف الضبط القضائى.
ويجوز للنائب العام أن يطلب إلى الجهة المختصة النظر في أمر كل من تقع منه مخالفة لواجباته ،أو تقصير في عمله ،وله أن يطلب إحالته إلى المحاكمة التأديبية، وهذا كله لا يمنع من رفع الدعوى الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,26,0,'0f9f754a9a08d5ee6ecf3b9e37a127d4','c3e088de4d6e4ef5f26e7ef11e73d5df',replace($m208$يكون من مأموري الضبط القضائي في دوائر اختصاصهم: .1 أعضاء النيابة العامة ومعاونوها.
.2 ضباط الشرطة وضباط الشرف وأمناؤها والمساعدون ومراقبو ومندوبو الشرطة وضباط الصف ومعاونو الأمن.
.3 العمد ،ومشايخ البلاد ،ومشايخ الخفراء.
.4 نظار ووكلاء محطات السكك الحديدية الحكومية.
ولمديري الأمن ،ومفتشي قطاع التفتيش والرقابة بوزارة الداخلية أن يؤدوا الأعمال التي يقوم بها مأمورو الضبط القضائي في دوائر اختصاصهم.
ويكون من مأموري الضبط القضائي في جميع أنحاء الجمهورية: .1 مدير ،وضباط ،وأمناء ،ومساعدو ،ومراقبو ومندوبو الشرطة ،وضباط الصف ومعاونو الأمن بقطاع الأمن الوطني بوزارة الداخلية وفروعه ومكاتبه على مستوى الجمهورية.
.2 مديرو ،وضباط ،وأمناء ،ومساعدو ،ومراقبو ،ومندوبو الشرطة ،وضباط الصف ومعانو الأمن بقطاع الأمن العام بوزارة الداخلية ،وفي إدارات وشعب البحث بوزارة الداخلية.
.3 ضباط قطاع الحماية المجتمعية بوزارة الداخلية.
.4 مدير الإدارة العامة لشرطة النقل والمواصلات ،وضباط هذه الإدارة.
.5 قائد وضباط إدارة هجانة الشرطة.
.6 مفتشو وزارة السياحة.
ويجوز بقرار من وزير العدل بالاتفاق مع الوزير المختص تخويل بعض شاغلى الوظائف العامة صفة مأموري الضبط القضائي بالنسبة إلى الجرائم التي تقع في دائرة اختصاصهم وتكون متعلقة بأعمال وظائفهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,27,0,'04fe4743d6b613cc1cd7cb8da0ba6358','6ab5e46fac65fa55a89817b19873ce45',replace($m208$يجب على مأموري الضبط القضائي أن يتلقوا البلاغات والشكاوى التي ترد إليهم بشأن الجرائم ،وأن يرسلوها فورا إلى النيابة العامة ،ويجب عليهم وعلى مرءوسيهم أن يحصلوا على جميع الإيضاحات ،ويجروا المعاينات اللازمة لتسهيل تحقيق الوقائع التي تبلغ إليهم ،أو التي يعلنون بها بأية كيفية كانت ،وعليهم أن يتخذوا جميع الوسائل التحفظية اللازمة للمحافظة على أدلة الجريمة.
ويجب أن تثبت جميع الإجراءات التي يقوم بها مأمورو الضبط القضائي في محاضر موقع عليها منهم يبين بها وقت اتخاذ الإجراء ومكان حصوله ،ويجب أن تشمل تلك المحاضر أيضا على توقيع الشهود والخبراء الذين سمعوا ،وترسل المحاضر إلى النيابة العامة مع الأوراق والأشياء المضبوطة.
ويجب على مأموري الضبط القضائي إثبات بيانات الرقم القومي للمتهم فور تحديد هويته ،وإرفاق مستخرج من هذه البيانات بالمحضر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,28,0,'d6769a58d4692900afa66ba856b1ce05','0abb1184f231969e95f88e4b05ddf3f0',replace($m208$يجب على مأموري الضبط القضائي ومرءوسيهم ورجال السلطة العامة أن يبرزوا ما يثبت شخصياتهم وصفاتهم عند مباشرة أي عمل أو إجراء منصوص عليه قانونًا ،ولا يترتب على مخالفة هذا الواجب بطلان العمل أو الإجراء وذلك دون إخلال بتوقيع الجزاء التأديبي.
ويعد رجل السلطة العامة في تطبيق أحكام هذا القانون كل من هو منوط به قانونًا المحافظة على النظام والأمن والآداب العامة ،وحماية الأرواح والأعراض والأموال وعلى الأخص منع الجرائم وضبطها ،وتنفيذ ما تفرضه عليه القوانين واللوائح من واجبات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,29,0,'fa8cb9f8df43980266914a39690caa1e','0438a01360c64e1c4667fb0e44478251',replace($m208$يجوز لكل من علم بوقوع جريمة من الجرائم التي تُرفع من النيابة العامة بغير شكوى ،أن يبلغ النيابة العامة أو أحد مأموري الضبط القضائي بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,30,0,'54e4ded0bdcf669589a09d502470fddd','2dee59667eefb716072ebdef71d27f4f',replace($m208$يجب على كل من علم من الموظفين العموميين أو المكلفين بخدمة عامة أثناء تأدية أعمالهم أو بسببها بوقوع جريمة من الجرائم التي تُرفع من النيابة العامة بغير شكوى ،أن يبلغ فورا النيابة العامة أو أقرب مأمور ضبط قضائي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,31,0,'24b3bed284d5a71c33c66d59363f40d1','7a031f9e0312571f0fd067a15ddf02c5',replace($m208$يجوز لكل من يدعي حصول ضرر له من الجريمة أن يقيم نفسه مدعيا بحقوق مدنية في الشكوى التي يقدمها إلى النيابة العامة أو أحد مأموري الضبط القضائي، وفي هذه الحالة الأخيرة يقوم المأمور بتحويل الشكوى إلى النيابة العامة مع المحضر الذي يحرره.
ويجوز لمدعى الضرر أن يتقدم بطلب كتابى إلى النيابة العامة في أي مرحلة يثبت فيها هذا الادعاء.
ويجب على النيابة العامة عند إحالة الدعوى إلى قاضي التحقيق أن تحيل معها الشكوى أو الطلب المشار إليهما.
ولا يعتبر الشاكي مدعيا بحقوق مدنية إلا إذا صرح بذلك في شكواه أو في ورقة مقدمة منه بعد ذلك إلى النيابة العامة ،أو إذا طلب في إحداهما تعويضا ما.$m208$,'<<CR>>',chr(13))),
('law',174,2025,32,0,'e11645227a8b7ef7e8a5c0a563abab5d','02339c6b4403abe06521da02b6771113',replace($m208$يجوز لمأموري الضبط القضائي أثناء جمع الاستدلالات سماع أقوال من يكون لديهم معلومات عن الوقائع الجنائية ومرتكبيها وسؤال المتهم عن ذلك ،ولهم أن يستعينوا بالأطباء وغيرهم من أهل الخبرة ويطلبوا رأيهم شفهيا أو بالكتابة.
ولا يجوز لهم تحليف الشهود أو الخبراء اليمين إلا إذا خيف ألا يستطاع فيما بعد سماع الشهادة بيمين.$m208$,'<<CR>>',chr(13))),
('law',174,2025,33,0,'ab3ae5d850f5e050554e553ca2f9fb07','1d90c090a53ebfa988f9efed242abc0c',replace($m208$تكون الجريمة متلبسا بها حال ارتكابها أو عقب ارتكابها ببرهة يسيرة.
وتعتبر الجريمة متلبسا بها إذا تبع المجني عليه مرتكبها أو تبعته العامة مع الصياح إثر وقوعها ،أو إذا وجد مرتكبها بعد وقوعها بوقت قريب حاملاً آلات أو أسلحة أو أمتعة أو أوراقا أو أشياء أخرى يستدل منها على أنه فاعل أو شريك فيها، أو إذا وجدت به في هذا الوقت آثار أو علامات تفيد ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,34,0,'e53ac4db9b889e674661dec9409a397b','2a2f960cc46f6343f2fc0ae8a983e7de',replace($m208$يجب على مأمور الضبط القضائي في حالة التلبس بجناية أو جنحة أن ينتقل فورا إلى محل الواقعة ،ويعاين الآثار المادية للجريمة ،ويحافظ عليها ،ويثبت حالة الأماكن والأشخاص ،وكل ما يفيد في كشف الحقيقة ،ويسمع أقوال من كان حاضرا ،أو من يمكن الحصول منه على إيضاحات في شأن الواقعة ومرتكبها.
ويجب عليه أن يخطر النيابة العامة فورا بانتقاله ،وعليها بمجرد إخطارها بجناية متلبس بها الانتقال فورا إلى محل الواقعة متى اقتضى الأمر ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,35,0,'072a98d2cfbf6db8c88f652166a251a6','7ba1badd0987c329a207008fbf8649ca',replace($m208$يجوز لمأمور الضبط القضائي عند انتقاله في حالة التلبس بالجرائم أن يمنع الحاضرين من مبارحة محل الواقعة أو الابتعاد عنه حتى يتم تحرير المحضر ،وله أن يستدعي في الحال من يمكن الحصول منه على إيضاحات في شأن الواقعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,36,0,'bc8753e45c1111242e321f91d39f9e88','f183e123092010e12b3a166b30a744c3',replace($m208$إذا خالف أحد الحاضرين أمر مأمور الضبط القضائي وفقًا للمادة  35 من هذا القانون ،أو امتنع أحد ممن دعاهم عن الحضور ،يذكر ذلك في المحضر ،وللنيابة العامة أن تصدر أمرا جنائيا بتغريم المخالف بغرامة لا تقل عن خمسمائة جنيه ولا تزيد على ألف جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,37,0,'33bfcebb69d8311660d23f4982acd54b','20f91fb6a41ba5f88001eb65b9ac3b2e',replace($m208$فيما عدا حالة التلبس ،لا يجوز القبض على أحد ،أو تفتيشه ،أو حبسه ،أو تقييد حريته بأي قيد إلا بأمر قضائي مسبب يستلزمه التحقيق.
وكل من يقبض عليه أو يحبس أو تُقيد حريته ،تجب معاملته بما يحفظ عليه كرامته ،ولا يجوز تعذيبه ولا ترهيبه ولا إكراهه ولا إيذاؤه بدنيا أو معنويا.
وللمتهم حق الصمت ،وكل قول يثبت أنه صدر من محتجز تحت وطأة شيء مما تقدم ،أو التهديد بشيء منه ،يهدر ولا يعول عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,38,0,'a8ec0c7417da48c1b46d2fc28be562ba','0a68e5b71617a04789f9f8bf89a36fee',replace($m208$لا يجوز حجز أو تقييد حرية أي شخص إلا في أحد مراكز الإصلاح والتأهيل أو أماكن الاحتجاز المخصصة لذلك ،ولا يجوز لمدير مركز الإصلاح والتأهيل أو القائم على أماكن الاحتجاز قبول أي شخص فيها إلا بمقتضى حكم أو أمر قضائي مسبب موقع عليه من السلطة المختصة ،ولا يجوز أن يبقيه فيها بعد المدة المحددة بالحكم أو بالأمر القضائى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,39,0,'315cbdd322e1b9f12ef9a4242ca50917','d168df49cb039bd5afda09ae76ee704a',replace($m208$يجوز لمأمور الضبط القضائي في أحوال التلبس بالجنايات أو بالجنح التي يعاقب عليها بالحبس لمدة تزيد على ثلاثة أشهر أن يأمر بالقبض على المتهم الحاضر الذي توجد دلائل كافية على اتهامه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,40,0,'0e833bb6d4634ba8ada87ee47de65bd5','22f9f47056323bf829a11753a78e1451',replace($m208$إذا لم يكن المتهم حاضرا في الأحوال المبينة في المادة  39 من هذا القانون جاز لمأمور الضبط القضائي أن يصدر أمرا بضبطه وإحضاره ،ويثبت ذلك في المحضر.
وفي غير الأحوال المبينة في المادة  39 المشار إليها ،إذا وجدت قرائن كافية على اتهام شخص بارتكاب جناية أو جنحة سرقة أو نصب أو تعدٍ شديد ومقاومة لرجال السلطة العامة بالقوة والعنف ،جاز لمأمور الضبط القضائي أن يتخذ الإجراءات التحفظية المناسبة ،وأن يطلب فورا من النيابة العامة أن تصدر أمرا بالقبض عليه.
وفي جميع الأحوال ،تنفذ أوامر الضبط والإحضار والإجراءات التحفظية بواسطة أحد معاوني التنفيذ أو بواسطة رجال السلطة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,41,0,'175bb4abfcec4095401538042d25775b','bfbdb9ace611bd419162f25ba5e4a69c',replace($m208$يجب على مأمور الضبط القضائي أن يبلغ فورا المتهم المضبوط بسبب تقييد حريته ،وبالتهم المنسوبة إليه ،وأن يسمع أقواله ،وأن يحيطه بحقوقه كتابة ،وأن يمكنه من الاتصال بذويه وبمحاميه.
وإذا لم يأت المتهم بما ينفي التهمة عنه ،يرسله مأمور الضبط القضائي خلال أربع وعشرين ساعة من وقت تقييد حريته إلى سلطة التحقيق المختصة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,43,0,'92b5281ff4be5a8285376c1df2b33a00','3d1caa02fbe9eb42aa7fd46f7e2862d5',replace($m208$لرجال السلطة العامة ،في أحوال التلبس بالجنايات ،والجنح التي يجوز الحكم فيها بالحبس مدة تزيد على ثلاثة أشهر أن يحضروا المتهم ويسلموه إلى أقرب مأمور ضبط قضائي.
ولهم ذلك أيضا في الجرائم الأخرى المتلبس بها إذا لم يمكن لهم التثبت من شخصية المتهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,44,0,'11fdbb41f126d1125b908923b357748d','22f600164600aad8118893ea3ac623ff',replace($m208$فيما عدا الأحوال المنصوص عليها في الفقرة الثانية من المادة  11 من هذا القانون ،إذا كانت الجريمة المتلبس بها مما يتوقف رفع الدعوى الجنائية عنها على شكوى فلا يجوز القبض على المتهم إلا إذا صرح بالشكوى من يملك تقديمها ،ويجوز في هذه الحالة أن تكون الشكوى لمن يكون حاضرا من رجال السلطة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,45,0,'89474393e1c8ab9673cf3b1649e8c192','1c8b799a744f3d3ca871e16d283d70f5',replace($m208$يجوز للنائب العام ولأعضاء النيابة العامة ولرؤساء محاكم الاستئناف والمحاكم الابتدائية دخول مراكز الإصلاح والتأهيل أو أماكن الاحتجاز المخصصة لإيداع المحبوسين الكائنة في دوائر اختصاصهم ،وذلك للتأكد من عدم وجود محبوس بصفة غير قانونية ،ومن أن أوامر التحقيق وأحكام وقرارات المحاكم يجرى تنفيذها على الوجه المبين بها وطبقًا للأحكام المقررة قانونًا ،ولهم أن يطلعوا على الدفاتر ،وعلى أوامر التنفيذ ،والقبض ،والحبس ،وأن يأخذوا صورا منها ،وأن يتصلوا بأي نزيل ،ويسمعوا منه أي شكوى ،ويجب أن تقدم لهم كل مساعدة للحصول على المعلومات التي يطلبونها.
ويكون لقضاة التحقيق فيما يباشرونه من تحقيقات السلطات المبينة بالفقرة الأولى من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,46,0,'73fc627288593c18bfefa31ccb39c0c1','84eb80375f18968ec980c91182bab1c7',replace($m208$يجوز لكل نزيل في أحد مراكز الإصلاح والتأهيل أو الأماكن المشار إليها في المادة  38 من هذا القانون أن يقدم في أي وقت للقائم على إدارته شكوى كتابة أو شفاهة ،ويطلب منه تبليغها للنيابة العامة ،وعلى الأخير قبولها وتبليغها في الحال بعد إثباتها في سجل يعد لذلك.
ويجوز لكل من علم بوجود محتجز أو نزيل بصفة غير قانونية أو في محل غير مخصص للحبس أن يخطِر أحد أعضاء النيابة العامة وعليه بمجرد إخطاره أن ينتقل فورا إلى المحل الموجود به النزيل وأن يقوم بإجراء التحقيق وأن يأمر بالإفراج عن النزيل الموجود بصفة غير قانونية وعليه أن يحرر محضرا بذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,47,0,'de76bc94369cc0ebb2020232553f2bf7','e97509ef4e02337345186c59b4e1b99f',replace($m208$للمنازل حرمة لا يجوز دخولها ،ولا تفتيشها ،ولا مراقبتها أو التنصت عليها ،إلا بأمر قضائي مسبب يحدد المكان والتوقيت ،والغرض منه ،ويجب تنبيه من في المنزل عند دخوله أو تفتيشه ،وإطلاعه على الأمر الصادر في هذا الشأن ،وذلك كُله على النحو المبين في القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,48,0,'2ef709f819c3c4c0b37a7c3fcd2e00e2','dff5faf55491721deef3b19f34e72856',replace($m208$استثناء من حكم المادة  47 من هذا القانون لرجال السلطة العامة دخول المنازل وغيرها من المحال المسكونة في حالات الاستغاثة أو الخطر الناجم عن الحريق أو الغرق أو ما شابه ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,49,0,'09771a9b333e1166d76bf1fdab7e8570','bfbebe007305b934f3f5ef0fea565d5f',replace($m208$يجوز لمأمور الضبط القضائي تفتيش المتهم في الأحوال التي يجوز فيها قانونًـا القبض عليه.
وإذا كان المتهم أنثى وجب أن يكون تفتيشها بمعرفة أنثى يندبها مأمور الضبط القضائي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,50,0,'2cbd2e176fe5ffc275242ce13e6e0e4c','1f91f6ffbf069c0e7149c30a03c50c11',replace($m208$إذا قامت أثناء تفتيش منزل المتهم قرائن قوية على أن المتهم أو أي شخص موجود في المنزل يخفى معه شيئًا يفيد في كشف الحقيقة ،يجوز لمأمور الضبط القضائي أن يتخذ الإجراءات التحفظية المناسبة ،وأن يبلغ النيابة العامة فورا لاتخاذ ما تراه مناسبا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,51,0,'3356bc06f0d76eb9cfa33caf190bc278','fd4fe4aa42242bfaf654ebd82e13306f',replace($m208$لا يجوز التفتيش إلا للبحث عن الأشياء الخاصة بالجريمة الجاري جمع الاستدلالات أو حصول التحقيق بشأنها.
ومع ذلك إذا ظهر عرضا أثناء التفتيش وجود أشياء تعد حيازتها جريمة ،أو تفيد في كشف الحقيقة في جريمة أخرى ،يجوز لمأمور الضبط القضائي أن يضبطها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,52,0,'74774a48222617580942a2122662ef2c','48fe3592f7ded2ca1100bbf67ae4409d',replace($m208$لا يجوز لمأمور الضبط القضائي فض أي أوراق مختومة أو مغلفة بأية طريقة أخرى موجودة في منزل المتهم.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,53,0,'51e2a30ffe9ad687f741536f7cc76310','8f584af94e2cff8cf881b22b2bf1cd5d',replace($m208$يجوز لمأمور الضبط القضائي أن يضع الأختام على الأماكن التي بها آثار أو أشياء تفيد في كشف الحقيقة ،وله أن يقيم حراسا عليها.
ويجب عليه إخطار النيابة العامة فورا بذلك ،وعلى النيابة العامة إذا ما رأت ضرورة ذلك الإجراء أن ترفعه خلال أسبوع إلى القاضي الجزئي لإقراره أو إنهائه.
ولكل ذي شأن أن يتظلم للقاضي الجزئي من الأمر الذي أصدره بعريضة يقدمها إلى النيابة العامة ،وعليها رفع التظلم إلى القاضي الجزئي خلال مدة لا تزيد على أسبوع.$m208$,'<<CR>>',chr(13))),
('law',174,2025,54,0,'210ab101ab4f2ec704f61243a5fc3c00','d445984e3c58dbdb14332198cdcc33db',replace($m208$يجوز لمأمور الضبط القضائي أن يضبط الأشياء والأوراق التي يحتمل أن تكون قد استعملت في ارتكاب الجريمة ،أو نتجت عن ارتكابها ،أو وقعت عليها ،وكل ما يفيد في كشف الحقيقة.
وتوصف هذه الأشياء والأوراق وتعرض على المتهم ،ويطلب منه إبداء ملاحظاته عليها ،ويحرر بذلك محضر يوقعه المتهم ،أو يذكر فيه امتناعه عن التوقيع.$m208$,'<<CR>>',chr(13))),
('law',174,2025,55,0,'5f66e9bb5b4a70673c6144c8a5c3c137','601822fe416cc0d2433c93ad234bc906',replace($m208$توضع الأشياء والأوراق المضبوطة وفقًا للمادة  54 من هذا القانون في حرز مغلق ،ويختم عليها ،ويكتب على شريط داخل الختم تاريخ المحضر المحرر بضبطها، ويشار إلى الواقعة التى حصل الضبط من أجلها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,56,0,'beec8677ea583c24ca908808759e7815','9ce8ac29dfdbd74ca7e7d86aad512ec7',replace($m208$لا يجوز فض الأختام الموضوعة طبقا للمادتين  55 ،53 من هذا القانون إلا بحضور المتهم أو وكيله ومن ضبطت عنده هذه الأشياء أو الأوراق ،أو بعد دعوتهم لذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,57,0,'2e267018f129f82abc608270a61991e6','1d78a903012b10284c8cc61f23201f3b',replace($m208$يعاقب بالعقوبات المقررة في المادة  310 من قانون العقوبات كل من يكون قد وصل إلى علمه بسبب التفتيش معلومات عن الأشياء والأوراق المضبوطة ،وأفضى بها إلى أي شخص غير ذي صفة أو انتفع بها بأية طريقة كانت.$m208$,'<<CR>>',chr(13))),
('law',174,2025,58,0,'9f9a02d1571f986802ddfdc6911d8019','5853fdaeacfbe59c0779c7c0998fea33',replace($m208$لمن ضبطت عنده الأوراق وكان له مصلحة عاجلة فيها ،تعطى له صورة منها مصدق عليها من مأمور الضبط القضائي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,59,0,'369c044ad39aa38a3c3e17b9a7f740a5','3180075f59b402875884b7a67c02d37b',replace($m208$يجوز لمأموري الضبط القضائي في حالة قيامهم بواجباتهم أن يستعينوا مباشرة بالقوة الجبرية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,60,0,'21516d2ba4bb1927067fe3dc17e95792','bad0b9f8c2a7401bc1aa830da0c2b792',replace($m208$إذا رأت النيابة العامة قبل البدء في إجراءات التحقيق أن لا محل للسير في الدعوى تأمر بحفظ الأوراق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,61,0,'64d395a69887941435cd05aba89b5096','70c9db87308ff7970e861deadfe60580',replace($m208$يجب على النيابة العامة إذا أصدرت أمرا بالحفظ أن تعلنه إلى المجني عليه والمدعى بالحقوق المدنية ،فإذا مات أحدهما يعلن الورثة جملة في محل إقامته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,62,0,'15358bcad96244afc8a8399601cc405b','e249990a8c72f1008f390c44618b6a4b',replace($m208$إذا رأت النيابة العامة في مواد الجنح أن الدعوى صالحة لرفعها بناء على الاستدلالات التي جمعت تكلف المتهم بالحضور مباشرة أمام المحكمة المختصة.
ويجوز في مواد الجنح التي يعينها وزير العدل بقرار منه بعد موافقة وزير الداخلية إعلان ورقة التكليف بالحضور بواسطة رجال السلطة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,63,0,'f03308c502a9f5559e05e6321f8d30cb','ca5d647c5535e9333f79d475773de56c',replace($m208$يجب على النيابة العامة أن تجري تحقيقًا في الجنايات ،ولها أن تجريه في الجنح أو غيرها إذا رأت محلاً لذلك.
ويجري التحقيق طبقًا للأحكام المنصوص عليها في هذا الباب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,64,0,'e4d5e01fd5e1dc24603b5a8cae07864c','5549a0643c23f605f9da29566dc8ca18',replace($m208$يجوز تكليف أحد معاوني النيابة العامة بتحقيق قضية بأكملها.
كما يجوز لعضو النيابة العامة من درجة مساعد نيابة عامة على الأقل أن يندب أحد مأموري الضبط القضائي للقيام بعمل معين أو أكثر من أعمال التحقيق عدا استجواب المتهم.
ويكون لمأمور الضبط القضائي المندوب في حدود ندبه كل السلطات المخولة لمن ندبه ،وله أن يجري أي عمل آخر من أعمال التحقيق وأن يستجوب المتهم في الأحوال التي يخشى فيها فوات الوقت متى كان متصلاً بالعمل المندوب له ولازما في كشف الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,65,0,'5b136ae4b1e5ec3687c0908a281e868e','e1f556cc2c707c0272910befbf40a95f',replace($m208$يجوز لعضو النيابة العامة أن يطلب من نيابة أخرى خارج دائرة اختصاصه إجراء بعض التحقيقات في القضية ،على أن يبين المسائل المطلوب تحقيقها والإجراءات المطلوب اتخاذها ،ولهذه النيابة أن تجري أي عمل آخر من أعمال التحقيق وأن تستجوب المتهم ،في الأحوال التي ترى فيها لزوما لذلك ،متى كان ذلك متصلاً بالعمل المطلوب منها إجراؤه ولازما في كشف الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,66,0,'9f013e818876144cb1d2cb813f068460','e5f552fc2fa0fb9466b4b8c2dac940b8',replace($m208$يجرى التحقيق باللغة العربية ،ويسمع عضو النيابة العامة أقوال الخصوم والشهود الذين يجهلون اللغة العربية بواسطة مترجم بعد أن يحلف يمينًـا بأن يؤدي مهمته بالصدق والأمانة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,67,0,'c6d7887206e235bea386fa5f975a82c9','3ea639f526981d33c136bc7dcafa3ca6',replace($m208$يستصحب عضو النيابة العامة في التحقيق أحد كُتاب النيابة العامة لكتابة أو تحرير المحاضر اللازمة ،ويجوز له عند الضرورة أن يكلف غيره بذلك بعد تحليفه اليمين ،ويوقع عضو النيابة والكاتب كل صفحة من هذه المحاضر.
وتَحفظ النيابة العامة المحاضر مع باقي الأوراق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,68,0,'42cb80aa778d51fad2110c0fe1e9700d','5ecf462bc422c8656aa7419b47545f5e',replace($m208$في غير الأحوال التي تصدر فيها النيابة العامة أو سلطة التحقيق المختصة بيانات رسمية ،تعتبر إجراءات التحقيق ذاتها والنتائج التي تسفر عنها من الأسرار ،ويجب على أعضاء النيابة العامة وأعوانهم من كُتاب وخبراء وغيرهم ممن يتصلون بالتحقيق أو يحضرونه بسبب وظيفتهم أو مهنتهم عدم إفشائها ،ويعاقب من يخالف ذلك منهم بالعقوبة المقررة في المادة  310 من قانون العقوبات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,69,0,'51ebf1e85b10bbcd6e7c22e6286053a5','6f28813f08ee59d7cfb07686852a3e30',replace($m208$يجوز لمن لحقه ضرر من الجريمة أن يدعي بحقوق مدنية أثناء التحقيق في الدعوى ،وتفصل النيابة العامة في قبوله بهذه الصفة في التحقيق خلال ثلاثة أيام من تقديم هذا الادعاء.
ويجوز لمن رفض طلبه الطعن في قرار الرفض أمام محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،خلال ثلاثة أيام تسري من تاريخ إعلانه بالقرار.$m208$,'<<CR>>',chr(13))),
('law',174,2025,70,0,'77fd3a5aa30f7341f37ef2f47a584383','8dbfd4767178cf96fb517ecd0f4f86d7',replace($m208$يجوز للمتهم وللمجني عليه وللمدعي بالحقوق المدنية وللمسئول عنها ولوكلائهم أن يحضروا جميع إجراءات التحقيق ،ويجوز لعضو النيابة العامة أن يجري التحقيق في غيبتهم متى رأى ضرورة ذلك لإظهار الحقيقة ،وفور انتهاء تلك الضرورة يمكنهم من الاطلاع على التحقيق ،وله في حالة الاستعجال أن يباشر بعض إجراءات التحقيق في غيبة الخصوم ،ولهؤلاء الحق في الاطلاع على الأوراق المثبتة لهذه الإجراءات.
ويحق للخصوم اصطحاب وكلائهم في التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,71,0,'24c4e0aec9f7730b16494c0522c8e90d','603a1f4cf44221cd8a9e5c3563b7a869',replace($m208$يخطر الخصوم باليوم الذي يباشر فيه عضو النيابة العامة إجراءات التحقيق ،ومكانها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,72,0,'b8b0649ebab55bc1e0a4b916607a1dc4','c15f2683c474b419d69832bfc45630f8',replace($m208$يجب على كل من المجني عليه والمدعي بالحقوق المدنية والمسئول عنها أن يعين له موطنًا مختارا في المكان الكائن فيه مقر النيابة التي يجري فيها التحقيق، أو أن يعين رقم هاتف محمول أو بريدا إلكترونيا لإعلانه عليه.
ويجب على المتهم عقب مثوله في أي إجراء تتخذه سلطة التحقيق أن يعين له موطنًا مختارا ،أو رقم هاتف محمول أو بريدا إلكترونيا لإعلانه عليه.
وإذا لم يعين أي من الأشخاص المنصوص عليهم في الفقرتين الأولى والثانية من هذه المادة البيانات المبينة بهما ،أو كان هذا البيان ناقصا أو غير صحيح أو طرأ عليه تغيير ولم يخطر بها ،يكون إعلانه في قلم الكتاب صحيحا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,73,0,'725c8b1d4272a1e8695f7e97bf5a6638','c6667cb92da2660d40b7904bbe5b3251',replace($m208$يجوز للخصوم ولوكلائهم أن يقدموا إلى عضو النيابة العامة الدفوع والطلبات والملاحظات التي يرون تقديمها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,74,0,'3c821a5210bd307972c590adc09931e5','a96f9f4c7933af5b925c0d4b0836873a',replace($m208$يجوز للمتهم وللمجني عليه وللمدعي بالحقوق المدنية وللمسئول عنها ولوكلائهم أن يحصلوا على نفقتهم أثناء التحقيق على صور من الأوراق أيا كان نوعها ،إلا إذا اقتضت مصلحة التحقيق غير ذلك.
وفي جميع الأحوال لهم أن يحصلوا على صور الأوراق أيا كان نوعها عقب انتهاء التحقيقات إذا كان التحقيق حاصلاً بغير حضورهم بناء على قرار صادر بذلك أو كانت مصلحة التحقيق اقتضت ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,75,0,'30fddd335cb30918cf19f651a32b3460','01d0a67987bbd6fedc76a045d2279f53',replace($m208$ينتقل عضو النيابة العامة إلى أي مكان ليثبت حالة الأشخاص والأماكن والأشياء المتعلقة بالجريمة وكل ما يلزم إثبات حالته كلما اقتضت مصلحة التحقيق ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,76,0,'1d7f3cb6d0f9b97ff28401a0999498cb','f5d28322de9216548a6ae77f9b185e7a',replace($m208$تفتيش المنازل وملحقاتها عمل من أعمال التحقيق ،ولا يكون إلا بأمر مسبب من عضو النيابة العامة بناء على اتهام موجه إلى شخص مقيم في المنزل المراد تفتيشه بارتكاب جناية أو جنحة أو باشتراكه في ارتكابها.
ولعضو النيابة العامة أن يفتش أي مكان في حيازة المتهم ويضبط ما فيه من الأوراق والأشياء ،وكل ما يحتمل أنه استُعمل فى ارتكاب الجريمة أو نتج عنها أو وقعت عليه ،وكل ما يفيد فى كشف الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,77,0,'57df4175abb0a1e729142f7d6c150d1f','4f1579c8e5e5476f68b2af78ef980a83',replace($m208$يحصل التفتيش بحضور المتهم أو من ينيبه عنه إن أمكن ذلك ،وإذا حصل التفتيش في منزل غير المتهم يدعى صاحبه للحضور بنفسه أو بواسطة من ينيبه عنه إن أمكن ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,78,0,'f05e145a437f2fe1504937e7b69d47d8','82569bb59507f6b91d92ae038dbf171e',replace($m208$مع مراعاة حكم الفقرة الثانية من المادة  49 من هذا القانون ،يجوز لعضو النيابة العامة أن يفتش المتهم أو يندب لذلك أحد مأموري الضبط القضائي بناء على أمر مسبب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,79,0,'43fd85bb46e7ba757bb226699e277339','1740b1718ea9e85c24d38076c510a621',replace($m208$لا يجوز للنيابة العامة تفتيش غير المتهم أو غير منزله إلا إذا اتضحت دلائل قوية أنه حائز لأشياء تتعلق بالجريمة وتفيد في كشف الحقيقة.
ويشترط لاتخاذ هذا الإجراء الحصول مقدما على إذن من القاضي الجزئي، ويصدر القاضي هذا الإذن بعد الاطلاع على الأوراق والتحقيقات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,80,0,'aaf05531056d260c332e4a39e57bb0fa','f27464b458d49266f4d05f3667996db3',replace($m208$يجوز لعضو النيابة العامة ،بعد الحصول على إذن من القاضي الجزئي ،أن يصدر أمرا بضبط جميع الخطابات ،والرسائل ،والبرقيات ،والجرائد والمطبوعات ،والطرود، وأن يأمر بمراقبة الاتصالات السلكية واللاسلكية ،وحسابات مواقع وتطبيقات التواصل الاجتماعي ومحتوياتها المختلفة غير المتاحة للكافة ،والبريد الإلكتروني ،والرسائل النصية أو المسموعة أو المصورة على الهواتف أو الأجهزة أو أية وسيلة تقنية أخرى، وضبط الوسائط الحاوية لها أو إجراء تسجيلات لأحاديث جرت في مكان خاص متى كان لذلك فائدة في ظهور الحقيقة في جناية أو جنحة معاقب عليها بالحبس لمدة تزيد على ثلاثة أشهر.
ويجب أن يكون الأمر بالضبط أو الاطلاع أو المراقبة أو التسجيل لمدة لا تزيد على ثلاثين يوما.
ويصدر القاضي الإذن المشار إليه مسببا بعد اطلاعه على الأوراق والتحقيقات، ويجوز له أن يجدده لمدة أو لمدد أخرى مماثلة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,81,0,'b9af07c1308a0fb49a20db756825e0d7','d561e403687e2934e663d2a4edf31c88',replace($m208$يجوز للقاضي الجزئي بناء على طلب النيابة العامة في حالة قيام دلائل قوية على أن مرتكب إحدى الجرائم المنصوص عليها في المواد  166 مكررا 308 ،مكررا من قانون العقوبات ،والبند 2 /من المادة  76 من قانون تنظيم الاتصالات الصادر بالقانون رقم  10 لسنة  2003 قد استعان في ارتكابها بهاتف معين ثابت أو محمول ،أو أي موقع إلكتروني ،أو أي وسيلة تقنية أخرى ،أن يصدر أمرا مسببا بناء على تقرير فني وشكوى المجني عليه في الجريمة المذكورة بوضع هذه الوسيلة أو ذلك الجهاز تحت المراقبة لمدة لا تزيد على ثلاثين يوما قابلة للتجديد لمدة أو مدد أخرى مماثلة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,82,0,'863d5d934e7823b044b24d62deee6667','ec6bf7557b1a841dc41fe8cf9c395286',replace($m208$لا يجوز لعضو النيابة العامة أن يضبط لدى المدافع عن المتهم أو الخبير الاستشاري الأوراق والمستندات التي سلمها المتهم لأيهما لأداء المهمة التي عهد إليه بها ولا المراسلات أو تسجيل الاتصالات المتبادلة بينهما في القضية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,83,0,'aacb77ec0e25a2e726e603b71491845e','da541212eaf01890723400ea75d34762',replace($m208$يجوز لعضو النيابة العامة أن يطلع على الخطابات ،والرسائل ،والأوراق، والتسجيلات المضبوطة ،على أن يتم ذلك بحضور المتهم والحائز لها أو المرسلة إليه، إن أمكن ،وتدون ملاحظاتهم عليها.
ويجوز له حسب ما يظهر من الفحص أن يأمر بضم تلك المضبوطات إلى ملف الدعوى أو بردها إلى من كان حائزا لها أو من كانت مرسلة إليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,84,0,'81fff1db72441848c2ea0e4a25da09c5','86354518606c4c591750e27f199781d9',replace($m208$الأشياء التي تضبط يتبع نحوها حكم المادة  55 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,85,0,'e3c4bf8919eb83ab742c09c6868c4902','0ecbe7ec4b85002d0c8841a2e1f92321',replace($m208$يجوز لعضو النيابة العامة أن يأمر الحائز لشيء يرى ضبطه أو الاطلاع عليه بتقديمه ،ويسري على من يخالف ذلك حكم المادة  285 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,86,0,'3f81865abb922b22741309aa0e60977b','356e48e01903bafa3b9002fec09881f9',replace($m208$تبلغ الخطابات والرسائل التلغرافية المضبوطة إلى المتهم أو المرسلة إليه، أو تعطى إليه صورة منها في أقرب وقت ،ما لم تقتضِ مصلحة التحقيق غير ذلك.
ويجوز لكل شخص يدعي حقًا في الأشياء المضبوطة أن يطلب إلى عضو النيابة العامة تسليمها إليه ،وله في حالة الرفض أن يتظلم أمام محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،وأن يطلب سماع أقواله أمامها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,87,0,'e65c4d3f8baf6b3780ac6c030795f426','7709813cf2f622bde400288ada3965c4',replace($m208$يجوز لعضو النيابة العامة أن يسمع شهادة من يرى لزوم سماعه من الشهود عن الوقائع التي تثبت أو تؤدي إلى ثبوت الجريمة ،وظروفها وإسنادها إلى المتهم أو براءته منها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,88,0,'39c904a3228f1658863e0f9d5c461f34','952af7b7cbd87a48e48b957ec9b1abcc',replace($m208$يسمع عضو النيابة العامة شهادة الشهود الذين يطلب الخصوم سماعهم ،ويكون تكليفهم بالحضور بواسطة المحضرين أو أفراد السلطة العامة ،أو بإعلانهم عن طريق الهاتف المحمول أو البريد الإلكتروني المثبت ببيانات الرقم القومي بحسب الأحوال.
ويجوز له أن يسمع شهادة أي شاهد يحضر من تلقاء نفسه ،وفى هذه الحالة يثبِت ذلك في المحضر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,89,0,'40bcdf524cb2d72f25159eef748cbb2b','e77117b5701be376a8fb436065c49dc6',replace($m208$يسمع عضو النيابة العامة كل شاهد على انفراد ،وله أن يواجه الشهود بعضهم ببعض وبالمتهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,90,0,'37ec198688dad5843f04d55a27b6a134','8e065919060ec81d2ed26a9fa4437bb6',replace($m208$يجب على عضو النيابة العامة أن يتثبت من شخصية كل شاهد ،وبيان اسمه ،ولقبه، وسنه ،ومهنته ،وسكنه ،ورقمه القومي أو رقم وثيقة سفره ،وموطنه إن كان أجنبيا ،وعلاقته بالمتهم أو المجني عليه أو المدعي بالحقوق المدنية أو المسئول عنها ويتثبت من شخصيته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,91,0,'0a8e4d28f004b4ba29a2f06120501625','822ed41bee69b37fc38ef3e7e4a9d341',replace($m208$يجب على الشاهد الذي أتم الخامسة عشرة من عمره أن يحلف قبل أداء الشهادة اليمين الآتية" :أقسم باالله العظيم أن أشهد بالحق" ،ويكون الحلف على حسب الأوضاع الخاصة بديانته إن طلب ذلك ،ويجوز سماع من لم يتم السن المذكورة على سبيل الاستدلال بغير يمين ،وتدون هذه البيانات وشهادات الشهود ،وإجراءات سماعهم في المحضر بغير كشط أو تحشير ،ولا يعتمد أي تصحيح أو شطب أو تخريج إلا إذا صدق عليه عضو النيابة العامة والكاتب والشاهد.$m208$,'<<CR>>',chr(13))),
('law',174,2025,92,0,'7706afaf7c0594c265c4077515be27c1','8ee20ca84eb0151830702428571f18f8',replace($m208$يضع كل من عضو النيابة العامة والكاتب توقيعه على الشهادة أو أي ملاحظة في أدائها ،وكذلك الشاهد بعد تلاوتها عليه وإقراره بأنه متمسك بها ،فإن امتنع عن وضع توقيعه أو ختمه أو بصمته أو لم يستطع أُثبت ذلك في المحضر ،مع ذكر الأسباب التي يبديها.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,93,0,'0a19d8bef93816a9da5e8a59ff0ac068','29b45e34eb965a60a2b9bc75efeaeac9',replace($m208$عند الانتهاء من سماع أقوال الشاهد ،يجوز للخصوم إبداء ملاحظاتهم عليها ولهم أن يطلبوا من عضو النيابة العامة سماع أقوال الشاهد عن نقاط أخرى يبينونها.
ويجوز لعضو النيابة العامة دائما أن يرفض توجيه أي سؤال للشاهد يكون غير متعلق بالدعوى أو يكون في صيغته مساس بالغير ،وعليه أن يمنع عن الشاهد كل كلام بالتصريح أو بالتلميح ،وكل إشارة مما ينبني عليه اضطراب أفكاره أو تخويفه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,94,0,'34c55817cf3d2986c25116e8d4166395','713869be5621922c57676f0d5772a12d',replace($m208$تسرى على الشهود أحكام المواد  289 ،288 ،287 ،286 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,95,0,'ceb7fe09f88941fbd221d72d58216996','606b93113fdac01a932dd9a8da84b3ab',replace($m208$يجب على كل من دعي للحضور أمام النيابة العامة لتأدية شهادة أن يحضر بناء على الطلب المحرر له ،وإلا جاز للنيابة العامة أن تصدر أمرا جنائيا بتغريمه مبلغًـا لا يجاوز خمسمائة جنيه.
ويجوز لعضو النيابة العامة أن يصدر أمرا بتكليف الشاهد بالحضور مرة أخرى على نفقته ،أو أن يصدر أمرا مسببا بضبطه وإحضاره.
وإذا حضر الشاهد بعد تكليفه بالحضور مرة أخرى أو من تلقاء نفسه وطلب إعفاءه من الغرامة أو قدم طلبا بذلك كتابةً إذا لم يستطع الحضور بنفسه ،يجوز للنيابة العامة إعفاؤه من الغرامة إذا أبدى عذرا مقبولاً.$m208$,'<<CR>>',chr(13))),
('law',174,2025,96,0,'fe81ba64608f7f62219bef09beef048d','7402576407c283fd2b8a817a10c4279e',replace($m208$إذا امتنع الشاهد عن حلف اليمين أو أداء الشهادة جاز للنيابة العامة أن تصدر أمرا جنائيا بتغريمه مبلغًا لا يجاوز ألفي جنيه ،ويجوز إعفاؤه من الغرامة أو بعضها إذا عدل عن امتناعه قبل انتهاء التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,97,0,'fbc052b0b58f7b5f5b36a4e629990bbf','765b81722031e56f07114bef2e6d0da6',replace($m208$إذا كان الشاهد مريضا أو لديه ما يمنعه من الحضور تسمع شهادته في محل وجوده ،فإذا انتقل عضو النيابة العامة لسماع شهادته وتبين له عدم صحة العذر ،يحكم عليه من القاضي الجزئي بالجهة التي طلب حضور الشاهد فيها بناء على طلب النيابة العامة بالحبس مدة لا تزيد على شهر أو بالغرامة التي لا تجاوز ألفي جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,98,0,'e6613f71a413d076bcf981b93efe4c63','65873eba5480ab94373377bdbc58ff6d',replace($m208$يقدر عضو النيابة العامة بناء على طلب الشهود ،المصاريف والتعويضات التي يستحقونها بسبب حضورهم لأداء الشهادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,99,0,'5f45eada812a781606b490873c774b1d','0c949907afe1c91601e97707f597e6e2',replace($m208$إذا اقتضى التحقيق الاستعانة بخبير وجب على عضو النيابة العامة أن يصدر أمرا بندبه يفصلُ فيه المهمة التي يكلف بها ،ويحلف الخبير اليمين أمام عضو النيابة العامة بأن يؤدي عمله بالأمانة والصدق ما لم يكن من فئات الخبراء الذين سبق أن أدوا اليمين قبل مزاولة أعمال الخبرة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,100,0,'56d3b9226869a92a4c632586b9b9d6cf','e9ea02d6e33b0011a0212868d50ce16f',replace($m208$يحدد عضو النيابة العامة للخبير ميعادا لتقديم التقرير ،وله أن يستبدل به خبيرا آخر إذا لم يقدم التقرير في الميعاد المحدد.$m208$,'<<CR>>',chr(13))),
('law',174,2025,101,0,'bd7152569f1bcc9238b1a6cf88509161','49d15635d645bce0df1cbd935bc7ce65',replace($m208$يجوز لعضو النيابة العامة أن يحضر وقت مباشرة الخبير مهمته ،ويجوز للخبير أن يؤدي مهمته بغير حضور الخصوم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,102,0,'09d79ff5a335ecc039ba3cb241b625b2','759730bc68758bdb20c83c69664fd0c3',replace($m208$يجوز للخصوم أن يستعينوا بخبير استشاري ،ولهم أن يطلبوا تمكينه من الاطلاع على الأوراق وسائر ما سبق تقديمه للخبير المنتدب من قبل النيابة العامة ،على ألا يترتب على ذلك تأخير السير في الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,103,0,'eed5fd03b8f54513ad8dd0a7b535a0e2','788456b64ab3f20db9cfab422cfc91e2',replace($m208$يجوز للخصوم رد الخبير إذا وجدت أسباب قوية تدعو لذلك ،ويقدم طلب الرد مبينًا فيه أسبابه إلى عضو النيابة العامة للفصل فيه خلال ثلاثة أيام من يوم تقديمه.
ويترتب على تقديم طلب الرد عدم استمرار الخبير في عمله من تاريخ إخطاره بذلك ،وفى حالة الاستعجال يجوز لعضو النيابة العامة أن يأمر باستمرار الخبير في عمله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,104,0,'1886a2ee335f9560270549b39437a4c7','561ded23efd7cb0c00f0b2f2c1bbe4a0',replace($m208$يجب على عضو النيابة العامة عند حضور المتهم لأول مرة في التحقيق أن يدون جميع البيانات الخاصة بإثبات شخصيته ،ويحيطه بحقوقه كتابة وبالتهمة المنسوبة إليه، ويثبت في المحضر ما قد يبديه في شأنها من أقوال ،وأن يمكنه من الاتصال بذويه ومحاميه وذلك بعد تنبيهه إلى أن من حقه الصمت ،وذلك كُله مع مراعاة توفير المساعدة اللازمة للأشخاص ذوي الإعاقة والمسنين وفقًا للإجراءات المقررة قانونًا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,105,0,'f03f7496c795d639ef9ec0dced7fd921','4af63f41f9e34df77d5351c1436ef999',replace($m208$لا يجوز لعضو النيابة العامة أن يستجوب المتهم أو يواجهه بغيره من المتهمين أو الشهود إلا في حضور محاميه ،فإن لم يكن للمتهم محام ،أو لم يحضر محاميه ،بعد دعوته ،وجب على المحقق من تلقاء نفسه أن يندب له محاميا.
ويجوز لعضو النيابة العامة في الأحوال التي يخشى فيها على حياة المتهم متى كان لازما في كشف الحقيقة الانتقال لاستجوابه ،وذلك بعدما يطلب من نقابة المحامين الفرعية ندب أحد المحامين لحضور الاستجواب على وجه السرعة بالطريقة التي يتفق عليها بين النيابة العامة والنقابة العامة للمحامين ،فإذا لم يحضر المحامي في الموعد المحدد يتم استجواب المتهم ،ويحق للمحامي الموكل أو المنتدب حضور الاستجواب إذا حضر قبل انتهائه والاطلاع على ما تم من إجراءات الاستجواب في غيبته.
وعلى المتهم أن يقرر اسم محاميه في محضر التحقيق أو في القلم الجنائي للنيابة التي يجرى التحقيق في دائرتها أو للقائم على إدارة المكان المحبوس فيه ،كما يجوز لمحاميه أن يتولى هذا التقرير.
وللمحامي أن يثبت في المحضر ما يعن له من دفوع أو طلبات أو ملاحظات.
ويصدر المحقق بعد التصرف النهائي في التحقيق بناء على طلب المحامي المنتدب أمرا بتقدير أتعابه ،وذلك استرشادا بجدول تقدير الأتعاب الذي يصدر به قرار من وزير العدل بعد أخذ رأي مجلس النقابة العامة للمحامين ،وتأخذ هذه الأتعاب حكم الرسوم القضائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,106,0,'2fafd4c50a616a31a0dc1e2f87b9b59b','86f99e15911885aea0c497849be9e619',replace($m208$يجب أن يمكن محامي المتهم من الاطلاع على التحقيق قبل الاستجواب أو المواجهة بمدة كافية ما لم يقرر عضو النيابة العامة غير ذلك.
وفي جميع الأحوال ،لا يجوز الفصل بين المتهم ومحاميه الحاضر معه أثناء التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,108,0,'d5166770923c2e82322efde6e9569742','1a57e8c935fd26e388e3751ef85d2e0d',replace($m208$يجب أن يشمل كل أمر اسم المتهم ولقبه ومهنته ومحل إقامته ورقمه القومي أو رقم وثيقة سفره وموطنه إن كان أجنبيا ،والتهمة المنسوبة إليه ،وتاريخ الأمر وتوقيع عضو النيابة العامة والختم الرسمي ،ويشمل الأمر بحضوره على ميعاد معين.
ويجب أن يشمل أمر القبض أو أمر الضبط والإحضار تكليف رجال السلطة العامة بالقبض على المتهم وإحضاره أمام عضو النيابة العامة إذا رفض الحضور طوعا في الحال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,109,0,'b68b83f779cba6e69e231c069c8b307e','7e896a6a2c98723e83f2c9d55271e2b6',replace($m208$مع مراعاة حكم الفقرتين الثانية والثالثة من المادة  72 من هذا القانون، تعلن الأوامر إلى المتهم بواسطة المحضرين أو رجال السلطة العامة ،وتسلم له صورة منها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,110,0,'231bcb5f17e65c7fb51c46d755b36ccb','ef5d0d59b2c84b90ecf627fac01123ac',replace($m208$إذا لم يحضر المتهم بعد الأمر بحضوره دون عذر مقبول ،أو إذا خيف هربه، أو إذا لم يكن له محل إقامة معروف في مصر ،أو إذا كانت الجريمة في حالة تلبس جاز لعضو النيابة العامة أن يصدر أمرا مسببا بضبطه وإحضاره.$m208$,'<<CR>>',chr(13))),
('law',174,2025,111,0,'7c18939c055fefd18a332f213913d813','3ec6614811f877b444ffd1dab51cdc4a',replace($m208$تكون الأوامر التي يصدرها عضو النيابة العامة نافذة في جميع الأراضي المصرية.
ولا يجوز تنفيذ أوامر القبض والضبط والإحضار بعد مضي ستة أشهر من تاريخ صدورها ما لم يقرر عضو النيابة العامة مدها لمدة أخرى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,112,0,'4111ba7cdb7f5bda61503792c63e24ef','655a97fdf64227a55b832894477b812a',replace($m208$يجب على عضو النيابة العامة أن يستجوب المتهم المقبوض عليه فورا ،وإذا تعذر ذلك يودع أحد مراكز الإصلاح والتأهيل أو أماكن الاحتجاز إلى حين استجوابه، ويجب ألا تزيد مدة إيداعه على أربع وعشرين ساعة ،فإذا انتهت هذه المدة وجب على القائم على إدارة مركز الإصلاح والتأهيل أو أماكن الاحتجاز إرساله إلى النيابة العامة لاستجوابه في الحال وإلا أمرت بإخلاء سبيله.
واستثناء من حكم الفقرة الأولى من هذه المادة ،للنيابة العامة إذا تعذر استجواب المتهم بجريمة يجوز فيها الحبس الاحتياطي لعدم حضور محاميه الموكل أو المنتدب، أن تأمر بإيداعه أحد مراكز الإصلاح والتأهيل أو أماكن الاحتجاز إلى حين استجوابه بحضور محام ،ويسري في شأن حالات ودواعي الأمر بإيداع المتهم ،وإجراءاته، ومدته ،ومدها ،واستئنافه ذات القواعد المقررة بالنسبة إلى الحبس الاحتياطي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,113,0,'7525c8c93b6573df631ef2a9bfe3dff6','ad3bc74344b1da4dab4312b962c6dc41',replace($m208$إذا تبين بعد استجواب المتهم أن الأدلة كافية ،وكانت الواقعة جناية أو جنحة معاقبا عليها بالحبس مدة لا تقل عن سنة ،جاز لعضو النيابة العامة من درجة وكيل نيابة على الأقل بعد سماع دفاع المتهم أن يصدر أمرا مسببا بحبس المتهم احتياطيا وذلك لمدة أقصاها أربعة أيام تالية للقبض على المتهم أو تسليمه للنيابة العامة إذا كان مقبوضا عليه من قبل ،وذلك إذا توافرت إحدى الحالات أو الدواعي الآتية: 1- إذا كانت الجريمة في حالة تلبس ويجب تنفيذ الحكم فيها فور صدوره.
2- الخشية من هروب المتهم.
3- خشية الإضرار بمصلحة التحقيق سواء بالتأثير على المجني عليه أو الشهود، أو العبث في الأدلة أو القرائن المادية ،أو بإجراء اتفاقات مع باقي الجناة لتغيير الحقيقة أو طمس معالمها.
4- توقي الإخلال الجسيم بالأمن والنظام العام الذي قد يترتب على جسامة الجريمة.
وفى جميع الأحوال ،يجوز حبس المتهم احتياطيا إذا لم يكن له محل إقامة ثابت ومعروف في مصر وكانت الجريمة جناية أو جنحة معاقبا عليها بالحبس.$m208$,'<<CR>>',chr(13))),
('law',174,2025,114,0,'e0b4f3314129c0e26c1b5d11508df8af','319124eb06b330a5e280fb1511239002',replace($m208$يجوز لعضو النيابة العامة في الأحوال المنصوص عليها بالمادة  113 من هذا القانون ،وكذلك في الجنح الأخرى المعاقب عليها بالحبس أن يصدر بدلا من الحبس الاحتياطي أمرا مسببا بأحد التدابير الآتية: 1- إلزام المتهم بعدم مبارحة مسكنه أو موطنه.
2- إلزام المتهم بأن يقدم نفسه لمقر الشرطة في أوقات محددة.
3- حظر ارتياد المتهم أماكن محددة.
4- إلزام المتهم بعدم مغادرة نطاق جغرافي محدد إلا بعد الحصول على إذن من النيابة العامة.
5- إلزام المتهم بالامتناع عن استقبال أو مقابلة أشخاص معينين أو الاتصال بهم بأي شكل من الأشكال.
6- منع المتهم مؤقتا من حيازة أو إحراز الأسلحة النارية وذخيرتها ،وتسليمها لقسم أو مركز الشرطة الذي يقع في دائرته محل إقامته.
7- استخدام الوسائل التقنية في تتبع المتهم حال توافر ظروف العمل بها، ويصدر بها قرار من وزير العدل بالتنسيق مع وزيري الداخلية والاتصالات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,115,0,'3910ad1cf2904d69c6d1a5e2c9d3d2c5','78b3e62df84cb133400947dde7af5c1f',replace($m208$إذا خالف المتهم التدبير المقرر له وفقًا للمادة  114 من هذا القانون يجوز لعضو النيابة العامة أن يستبدل بالتدبير الحبس الاحتياطي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,116,0,'4aff22d87ecdbcd1023bb25de53ede54','776f5b184829dd86e405fa74dbc2e218',replace($m208$يجب أن يشتمل أمر الحبس فضلاً عن البيانات المشار إليها بالمادة  108 من هذا القانون ،بيان الجريمة المسندة إلى المتهم والعقوبة المقررة لها ،والأسباب التي بني عليها الأمر ،وتكليف القائم على إدارة مركز الإصلاح والتأهيل أو أماكن الاحتجاز بقبول المتهم ووضعه فيه.
ويسري حكم هذه المادة على الأوامر التي تصدر بمد الحبس الاحتياطي ،وفقًـا لأحكام هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,117,0,'7123f6336b7228fc122be44c51ee4aa0','6c9136296474890127dce05e27a29bef',replace($m208$يكون لأعضاء النيابة العامة من درجة رئيس نيابة على الأقل في تحقيق الجنايات المنصوص عليها في الأبواب الأول والثاني والثاني مكررا والثالث والرابع من الكتاب الثاني من قانون العقوبات ،بالإضافة إلى الاختصاصات المقررة للنيابة العامة ،سلطة إصدار أمر مسبب لمدة لا تزيد على ثلاثين يوما ،بضبط الخطابات والرسائل والبرقيات والجرائد والمطبوعات والطرود ،وبمراقبة الاتصالات السلكية واللاسلكية، وحسابات مواقع التواصل الاجتماعي ومحتوياتها المختلفة غير المتاحة للجميع ،والبريد الإلكتروني ،والرسائل النصية أو المسموعة أو المصورة على الهواتف والأجهزة وأي وسيلة تقنية أخرى ،وضبط الوسائط الحاوية لها ،أو إجراء تسجيلات لأحاديث جرت في مكان خاص متى كان لذلك فائدة في ظهور الحقيقة.
ويجوز تجديد الأمر المشار إليه في الفقرة الأولى من هذه المادة مدة أو مددا أخرى مماثلة.
كما يكون لهؤلاء الأعضاء في تحقيق الجنايات المشار إليه في الفقرة الأولى من هذه المادة عدا الجنايات المنصوص عليها في الباب الثالث من الكتاب الثاني من قانون العقوبات ،سلطة القاضي الجزئي فيما يتعلق بمدة الحبس الاحتياطي.
ويكون لهم فضلاً عن ذلك سلطة محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،المنصوص عليها في المادة  123 من هذا القانون ،عند تحقيق الجرائم المنصوص عليها في الباب الأول والقسم الأول من الباب الثاني من الكتاب الثاني من قانون العقوبات بشرط ألا تزيد مدة الحبس في كل مرة على خمسة عشر يوما.$m208$,'<<CR>>',chr(13))),
('law',174,2025,118,0,'645752d05175b0229ddd060c3265c39e','236ff4588a29070c86355b803948b241',replace($m208$يجب عند إيداع المتهم فى أحد مراكز الإصلاح والتأهيل أو أماكن الاحتجاز أن تسلم إلى القائم على إدارته صورة من أمر الحبس بعد توقيعه على الأصل بالاستلام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,119,0,'037d596dffc967c31a280400d68b5fa7','518ce5169041cea4b923b343bcf135aa',replace($m208$لا يجوز للقائم على إدارة مركز الإصلاح والتأهيل أو أماكن الاحتجاز أن يسمح لأحد من رجال السلطة العامة أو مأموري الضبط القضائي بأن يتصل بنفسه أو بواسطة غيره بالمحبوس احتياطيا داخل ذلك المركز أو المكان إلا بإذن كتابي من النيابة العامة ،وعليه أن يدون في الدفتر المعد لذلك اسم الشخص الذي سمح له ووقت المقابلة وتاريخ ومضمون الإذن ،ويقع باطلا كل إجراء يخالف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,120,0,'02f0fd463bfd766bb0a6d3644176eb36','9b9185b5274c57e5804f092b126f85c2',replace($m208$يجوز لعضو النيابة العامة في كل الأحوال أن يأمر بعدم اتصال المتهم المحبوس احتياطيا بغيره من المحبوسين ومنع الزيارة عنه ،وذلك دون الإخلال بحق المتهم في الاتصال دائما بالمدافع عنه دون حضور أحد.$m208$,'<<CR>>',chr(13))),
('law',174,2025,121,0,'6db0908ce42b1abb4c4b020a94940dad','7c0376c5baaa289722796e18a40b83dc',replace($m208$إذا رأت النيابة العامة مد مدة الحبس الاحتياطي ،وجب عليها قبل انتهاء مدة الأربعة أيام المشار إليها بالمادة  113 من هذا القانون ،أن تعرض الأوراق على القاضي الجزئي ليصدر أمرا مسببا ،بعد سماع أقوال النيابة العامة والمتهم إما بالإفراج عن المتهم أو بمد مدة الحبس الاحتياطي لمدة أو مدد متعاقبة بحيث لا تزيد كل منها على خمسة عشر يوما ولا يزيد مجموعها على خمسة وأربعين يوما.
وفي مواد الجنح يجب الإفراج حتما عن المتهم المقبوض عليه بعد مرور ثمانية أيام من تاريخ استجوابه إذا كان له محل إقامة معروف في مصر وكان الحد الأقصى للعقوبة المقررة قانونًا لا يتجاوز سنة واحدة ولم يكن عائدا وسبق الحكم عليه بالحبس أكثر من سنة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,122,0,'a32699694517b4e1c7693cd1c9e34010','9006156d4eb4d500ddd3dadd8ba77bb0',replace($m208$يكون الأمر الصادر من النيابة العامة بأحد التدابير المنصوص عليها في المادة  114 من هذا القانون نافذ المفعول لمدة الأيام العشرة التالية لبدء تنفيذه.
ومع عدم الإخلال بما ورد بشأنه نص خاص في هذا القانون ،يتبع بشأن هذه التدابير ذات الأحكام المقررة للحبس الاحتياطي ،ويسري في شأن مد مدة التدابير أو الحد الأقصى لها أو استئنافها ذات القواعد المقررة بالنسبة إلى الحبس الاحتياطي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,123,0,'344da9e1462b64a281a021ff86035a77','fbf20ead0b17e68a99b22f140644258b',replace($m208$إذا لم ينته التحقيق ورأى عضو النيابة العامة مد مدة الحبس الاحتياطي أو التدبير لما يزيد على ما هو مقرر في المادتين  122 ،121 من هذا القانون ،وفي الأحوال المنصوص عليها بالفقرة الثالثة من المادة  117 من هذا القانون ،وجب عليه قبل انتهاء مدة الحبس الاحتياطي أو التدبير عرض الأوراق على محكمة الجنح المستأنفة منعقدة في غرفة المشورة لتصدر أمرا مسببا بعد سماع أقوال النيابة العامة والمتهم بمد مدة الحبس أو التدبير لمدد متعاقبة لا تزيد كل منها على خمسة وأربعين يوما إذا اقتضت مصلحة التحقيق ذلك أو بالإفراج عن المتهم أو بإنهاء التدبير بحسب الأحوال.
ومع ذلك يتعين عرض الأمر على النائب العام كلما انقضى تسعون يوما على حبس المتهم بجناية احتياطيا أو مده وذلك لاتخاذ الإجراءات التي يراها كفيلة للانتهاء من التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,124,0,'dea2b4f682019c707c5814ac9bd63a00','34e3c9a48c1e6d52442dbb442ea469a8',replace($m208$لا يجوز أن تزيد مدة الحبس الاحتياطي أو التدبير على ثلاثة أشهر في مواد الجنح ما لم يكن المتهم قد أعلن بإحالته إلى المحكمة المختصة قبل انتهاء هذه المدة، ويجب على النيابة العامة في هذه الحالة أن تعرض أمر الحبس أو التدبير خلال خمسة أيام على الأكثر من تاريخ الإعلان بالإحالة إلى المحكمة المختصة وفقًا لأحكام الفقرة الأولى من المادة  132 من هذا القانون لإعمال مقتضى هذه الأحكام ،وإلا وجب الإفراج عن المتهم أو إنهاء التدبير بحسب الأحوال.
فإذا كانت التهمة المنسوبة إليه جناية فلا يجوز أن تزيد مدة الحبس الاحتياطي أو التدبير على خمسة أشهر إلا بعد الحصول قبل انقضائها على أمر من المحكمة المختصة بمد الحبس أو التدبير مدة لا تزيد على خمسة وأربعين يوما قابلة للتجديد لمدة أو لمدد أخرى مماثلة وإلا وجب الإفراج عن المتهم أو إنهاء التدبير بحسب الأحوال.
وفي جميع الأحوال ،لا يجوز أن تجاوز مدة الحبس الاحتياطي في مرحلة التحقيق الابتدائي وسائر مراحل الدعوى الجنائية ثلث الحد الأقصى للعقوبة السالبة للحرية ،بحيث لا تجاوز أربعة أشهر في الجنح واثني عشر شهرا في الجنايات، وثمانية عشر شهرا إذا كانت العقوبة المقررة للجريمة هي السجن المؤبد أو الإعدام، ويجوز لمحكمة الجنايات المستأنفة ولمحكمة النقض إذا كان الحكم صادرا بالإعدام أو السجن المؤبد أن تأمر بحبس المتهم احتياطيا لمدة خمسة وأربعين يوما قابلة للتجديد لمدد أخرى بما لا يجاوز سنتين.$m208$,'<<CR>>',chr(13))),
('law',174,2025,125,0,'ecde2fdf26d45a784143dd3e9ee441ac','af8e132ca1b26d04dc10e0bdba6352a8',replace($m208$يجوز للنيابة العامة أن تأمر بالإفراج المؤقت عن المتهم المحبوس احتياطيا أو بإنهاء التدبير في كل وقت سواء من تلقاء نفسها أو بناء على طلب المتهم ،بكفالة أو دون كفالة ،شريطة أن يتعهد بحضوره متى طلب منه بمعرفة النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,126,0,'fc03d51704d14b21b366a75ca10bdbff','fe14d99a68d02c633e1ed876a02d2bf2',replace($m208$في غير الأحوال التي يكون فيها الإفراج واجبا ،لا يفرج عن المتهم بضمان أو بغير ضمان إلا بعد أن يعين له موطنًا مختارا أو رقم هاتف محمول أو بريدا إلكترونيا على النحو المبين بالفقرة الثانية من المادة  72 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,127,0,'b039a4f2b6b2a33d2ac5002cf119c129','a013b6adec1fe3bb00244a1984b23ad9',replace($m208$يجوز تعليق الإفراج المؤقت أو إنهاء التدبير في غير الأحوال التي يكون فيها واجبا حتما على المتهم تقديم كفالة.
ويقدر عضو النيابة العامة أو القاضي الجزئي أو محكمة الجنح المستأنفة منعقدة في غرفة المشورة حسب الأحوال مبلغ الكفالة.
ويخصص نصف مبلغ الكفالة ليكون جزاء لتخلف المتهم عن الحضور في أي إجراء من إجراءات التحقيق والدعوى والتقدم لتنفيذ الحكم والقيام بجميع الواجبات الأخرى التي تفرض عليه ،ويخصص النصف الآخر لدفع ما يأتي بترتيبه: أولاً :المصاريف التي صرفتها الحكومة.
ثانيا :العقوبات المالية التي قد يحكم بها على المتهم.
وإذا قدرت الكفالة بغير تخصيص ،اعتبرت ضمانًا لقيام المتهم بواجب الحضور وعدم التهرب من التنفيذ والواجبات الأخرى التي تفرض عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,128,0,'de29ef2603a7a9dd26ac0cc6c5649da3','540a2bdd75bd2980221e02f5bd28604a',replace($m208$يدفع مبلغ الكفالة من المتهم أو من غيره ويكون ذلك بإيداع المبلغ المقدر في خزانة المحكمة نقدا أو سندات حكومية أو مضمونة من الحكومة أو بموجب شيك بنكي مقبول الدفع ،أو خطاب ضمان بنكي ،أو بإحدى وسائل الدفع غير النقدي المنصوص عليها بقانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم  18 لسنة 2019 ويجوز أن يقبل من أي شخص مليء التعهد بدفع المبلغ المقدر للكفالة أو خطاب ضمان بنكي إذا أخل المتهم بشرط من شروط الإفراج ،ويؤخذ عليه التعهد بذلك في محضر التحقيق أو بتقرير في قلم الكتاب ،ويكون للمحضر أو التقرير قوة السند التنفيذي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,129,0,'e59838efa24d88e3f6ca09c4591d1dc8','b90b62b0d4c095c63bdd28258f7a3cc2',replace($m208$إذا لم يقم المتهم بغير عذر مقبول بتنفيذ أحد الالتزامات المفروضة عليه يصبح الجزء الأول من الكفالة ملكًا للحكومة بقرار مسبب من السلطة المختصة بالتحقيق أو المحاكمة.
ويرد الجزء الثاني إذا صدر في الدعوى قرار بأن لا وجه لإقامتها أو حكم بالبراءة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,130,0,'d768427672dcddcb19f18c5d3e6dd7e4','e8090e5d542637229059733670238c67',replace($m208$إذا كانت حالة المتهم لا تسمح بتقديم كفالة يجوز إلزامه بأن يقدم نفسه لمقر الشرطة المختص في الأوقات التي تحدد له في أمر الإفراج مع مراعاة ظروفه الخاصة.
كما يجوز أن يطلب منه اختيار مكان للإقامة فيه غير المكان الذي وقعت فيه الجريمة أو أن يحظر عليه ارتياد مكان معين.$m208$,'<<CR>>',chr(13))),
('law',174,2025,131,0,'04c1e84bfde806556c40dfb5f3eede41','5f70f1de2e26ace965d1eca2efaf06cc',replace($m208$الأمر الصادر بالإفراج لا يمنع عضو النيابة العامة من إصدار أمر جديد بالقبض على المتهم أو بحبسه احتياطيا إذا قويت الأدلة ضده ،أو أخل بالواجبات المفروضة عليه ،أو وجدت ظروف تستدعي اتخاذ هذا الإجراء ،وذلك مع عدم الإخلال بأحكام المادتين  124 ،123 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,132,0,'3254feb23e2ede53769be7bbb0f3ee73','d56630d0142db1e6640003d1a112e68c',replace($m208$إذا أحيل المتهم إلى المحكمة يكون الإفراج عنه إن كان محبوسا أو حبسه إن كان مفرجا عنه أو إنهاء التدبير أو الأمر به من اختصاص المحكمة المحال إليها.
وفي حالة الإحالة إلى محكمة جنايات أول درجة يكون الأمر في غير دور الانعقاد من اختصاص محكمة الجنح المستأنفة منعقدة في غرفة المشورة.
وفي حالة الحكم بعدم الاختصاص تكون محكمة الجنح المستأنفة منعقدة في غرفة المشورة هي المختصة بالنظر في طلب الإفراج أو الحبس أو إنهاء التدابير أو الأمر به إلى أن ترفع الدعوى إلى المحكمة المختصة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,133,0,'ea81b77c439fb71aa29b1a07bf3e26f4','bd4ecc60b59e8062c52939a03c411286',replace($m208$لا يقبل من المجني عليه أو من المدعي بالحقوق المدنية طلب حبس المتهم أو الأمر بأحد التدابير له ولا تسمع منه أقوال في المناقشات المتعلقة بالإفراج عنه أو بإنهاء التدبير.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,134,0,'b62af92b463ac9126e2098cad419424b','a408fddb5b69788405367b34da122fca',replace($m208$يجوز للقاضي الجزئي أو محكمة الجنح المستأنفة أو المحكمة المختصة تقدير كفالة للإفراج عن المتهم كلما طلبت النيابة العامة الأمر بمد مدة الحبس الاحتياطي، وتراعى في ذلك أحكام المواد  131 ،130 ،129 ،128 ،127 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,135,0,'8df42c50fe03f1a9b53013dc7e7201d4','1502a42941075ab60949d0cdc92bf6af',replace($m208$يجوز الأمر برد الأشياء المضبوطة ،ولو قبل صدور الحكم في الدعوى، ما لم تكن لازمة للسير في الدعوى أو محلاً للمصادرة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,136,0,'78459fefae188bfc15ce39db263a4c2d','a0f6b3cfe7cdf7aab97c7dcdf5758542',replace($m208$يصدر الأمر بالرد من النيابة العامة أو قاضي التحقيق أو محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،ولمحكمة الموضوع وحدها أن تأمر بالرد أثناء نظر الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,137,0,'d25d311aa72266e5ec1d13db62891a51','f40583bafb449f4b2d9aa4450ed4e7a1',replace($m208$يكون رد الأشياء المضبوطة إلى من كانت في حيازته وقت ضبطها ،أما الأشياء التي وقعت عليها الجريمة أو المتحصلة منها فيكون ردها إلى من فقد حيازتها بالجريمة ،ما لم يكن لمن ضبطت معه الحق قانونًا في حبسها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,138,0,'aa27f8b0e30ec38d8add54e77d9c4f75','584ade805a75f985c3469138dfcc7299',replace($m208$لا يمنع الأمر بالرد ذوي الشأن من المطالبة أمام المحاكم المدنية بما لهم من حقوق ،وإذا كان الأمر بالرد قد صدر من المحكمة بناء على طلب أي من المتهم أو المدعى بالحقوق المدنية في مواجهة الآخر فلا يجوز المطالبة به أمام المحاكم المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,139,0,'f40251938874f39ea1963535781f9909','12d02381c6d3affb67a00d5319e0e5eb',replace($m208$يجوز الأمر بالرد ولو من غير طلب.
ولا يجوز للنيابة العامة أو قاضي التحقيق الأمر بالرد عند المنازعة ،ويرفع الأمر في هذه الحالة أو في حالة وجود شك فيمن له الحق في تسلم الشيء إلى محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،بناء على طلب ذوي الشأن لتأمر بما تراه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,140,0,'2f4ff4ca8879b35b026b2ace7ae41f60','b5052468dda4129ef1849b09ba9c661c',replace($m208$يجب عند صدور أمر بالحفظ أو بأن لا وجه لإقامة الدعوى أن يفصل في كيفية التصرف في الأشياء المضبوطة وكذلك الحال عند الحكم في الدعوى إذا حصلت المطالبة بالرد أمام المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,141,0,'b84102e0e0bbb1668b6e90cf2a005399','9d32e88aab9877e995500dc3aeedb923',replace($m208$يجوز لمحكمة الموضوع أو محكمة الجنح المستأنفة منعقدة في غرفة المشورة أن تحيل الأمر في شأن الرد إلى المحكمة المدنية إذا رأت موجبا لذلك ،وفي هذه الحالة يجوز وضع الأشياء المضبوطة تحت الحراسة أو اتخاذ إجراءات تحفظية أخرى نحوها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,142,0,'41c06b16a148e3a9714c4869192bc49e','34ef5db4d13c76ba45590f671b932f7a',replace($m208$إذا كان الشيء المضبوط مما يتلف بمرور الزمن أو يستلزم حفظه نفقات تستغرق قيمته أو لم يطلبه صاحبه خلال ستة أشهر من تاريخ انتهاء الدعوى ،يجوز للنيابة العامة أن تأمر ببيعه بإحدى الطرق المقررة بقانون تنظيم التعاقدات التي تبرمها الجهات العامة الصادر بالقانون رقم  182 لسنة  2018 متى سمحت بذلك مقتضيات الدعوى ،ويكون لصاحبه الحق في أن يطالب بالثمن الذي بيع به بعد خصم النفقات والمصروفات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,143,0,'144b82e082ce1fa89ea833cf8e220a0c','a6e948014b382a58db33c6647b31df76',replace($m208$في الأحوال التي تقوم فيها أدلة كافية من التحقيق على جدية الاتهام في أي من الجرائم المنصوص عليها في الباب الرابع من الكتاب الثاني من قانون العقوبات، وغيرها من الجرائم التي تقع على الأموال المملوكة للدولة أو الهيئات والمؤسسات العامة والوحدات التابعة لها أو غيرها من الأشخاص الاعتبارية العامة ،وكذا في الجرائم التي يوجب القانون فيها على المحكمة أن تقضي من تلقاء نفسها برد المبالغ أو قيمة الأشياء محل الجريمة أو تعويض الجهة المجني عليها ،وقدرت فيها النيابة العامة أن الأمر يقتضي اتخاذ تدابير تحفظية على أموال المتهم ،بما في ذلك منعه من التصرف فيها أو إدارتها ،وجب عليها أن تعرض الأمر على المحكمة الجنائية المختصة طالبة الحكم بذلك ضمانًا لتنفيذ ما عسى أن يقضي به من غرامة أو رد أو تعويض.
وللنائب العام عند الضرورة أو في حالة الاستعجال أن يأمر مؤقتًا بمنع المتهم من التصرف في أمواله أو إداراتها ،ويجب أن يشتمل أمر المنع من الإدارة على تعيين من يدير الأموال المتحفظ عليها ،وعلى النائب العام في جميع الأحوال أن يعرض أمر المنع على المحكمة الجنائية المختصة خلال سبعة أيام على الأكثر من تاريخ صدوره، بطلب الحكم بالمنع من التصرف أو الإدارة وإلا اعتبر الأمر كأن لم يكن.$m208$,'<<CR>>',chr(13))),
('law',174,2025,144,0,'d1b5c14340e3fa0144470290c546fceb','c67cce5491885a4aef2ec5674c284263',replace($m208$تصدر المحكمة الجنائية حكمها خلال مدة لا تجاوز خمسة عشر يوما من تاريخ عرض أمر المنع المشار إليه بالفقرة الأولى من المادة  143 من هذا القانون عليها وبعد سماع أقوال ذوي الشأن ،وتفصل المحكمة في مدى استمرار العمل بالأمر الوقتي المشار إليه بالفقرة الثانية من المادة  143 من هذا القانون كلما رأت وجها لتأجيل نظره.
ويجب أن يشتمل الحكم على الأسباب التي بني عليها ،وأن يشمل المنع من الإدارة تعيين من يدير الأموال المتحفظ عليها بعد أخذ رأي النيابة العامة.
ويجوز للمحكمة بناء على طلب النيابة العامة أن تشمل في حكمها أي مال لزوج المتهم أو أولاده القصر أو ورثته إذا توافرت أدلة كافية على أنه متحصل من الجريمة موضوع التحقيق وآل إليهم من المتهم ،وذلك بعد إدخالهم في الطلب.
وعلى من يعين للإدارة أن يتسلم الأموال المتحفظ عليها ،ويبادر إلى جردها بحضور ذوي الشأن ،وممثل للنيابة العامة ،أو خبير تندبه المحكمة ،ويلتزم من يعين للإدارة بالمحافظة على الأموال وحسن إدارتها ،وردها مع غلتها المقبوضة طبقًـا للأحكام المقررة في القانون المدني بشأن الوكالة في أعمال الإدارة والوديعة والحراسة ،وذلك على النحو الذي يصدر بتنظيمه قرار من النائب العام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,145,0,'e5c266480946cfe7e76bbadc0873097f','c49a7193c13c7255e3db0f530d25481b',replace($m208$لكل من صدر ضده حكم بالمنع من التصرف أو الإدارة أن يتظلم منه أمام المحكمة الجنائية المختصة بعد انقضاء ثلاثة أشهر من تاريخ الحكم ،فإذا رفض تظلمه فله أن يتقدم بتظلم جديد كلما انقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم.
كما يجوز لمن صدر ضده حكم بالمنع من التصرف أو الإدارة ولكل ذي شأن أن يتظلم من إجراءات تنفيذه.
ويحصل التظلم بتقرير في قلم كتاب المحكمة الجنائية المختصة ،وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم يعلن بها المتظلم وكل ذي شأن ،وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز خمسة عشر يوما من تاريخ التقرير به.
ويجوز للمحكمة المختصة أثناء نظر الدعوى من تلقاء نفسها أو بناء على طلب النيابة العامة أو ذوي الشأن أن تحكم بإنهاء المنع من التصرف أو الإدارة المقضي به أو تعديل نطاقه أو إجراءات تنفيذه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,146,0,'1c01c78b7dbd850da6a0f55b3d710b19','0a5a9596af858bca64ce5d771c827bd1',replace($m208$يجب أن يبين الأمر الصادر بالتصرف في الدعوى الجنائية أو الحكم الصادر فيها ما يتبع في شأن التدابير التحفظية المشار إليها في المادة  143 من هذا القانون.
وفي جميع الأحوال ،ينتهي المنع من التصرف أو الإدارة بصدور قرار بأن لا وجه لإقامة الدعوى الجنائية أو بصدور حكم نهائي فيها بالبراءة ،أو بتمام تنفيذ العقوبات المالية والتعويضات المقضي بهما.
ولا يحتج عند تنفيذ الحكم الصادر بالغرامة أو برد المبالغ أو قيمة الأشياء محل الجريمة أو بتعويض الجهة المجني عليها بحسب الأحوال بأي تصرف يصدر بالمخالفة للأمر أو الحكم المشار إليهما في المادتين  144 ،143 من هذا القانون من تاريخ قيد أي منهما في سجل خاص يصدر بتنظيمه قرار من وزير العدل ،ويكون لكل ذي شأن حق الاطلاع على هذا السجل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,147,0,'dfe98130bb9fa60d4bd1d28eaba15818','41dfc53b6804948a9540c91ebd918456',replace($m208$يجوز للمحكمة عند الحكم برد المبالغ أو قيمة الأشياء محل الجرائم المشار إليها في المادة  143 من هذا القانون أو بتعويض الجهة المجني عليها فيها أن تقضي بناء على طلب النيابة العامة أو المدعي بالحقوق المدنية بحسب الأحوال ،وبعد سماع أقوال ذوي الشأن بتنفيذ هذا الحكم في أموال زوج المتهم وأولاده القصر ،إذا ثبت أنها آلت إليهم من المتهم ،وأنها متحصلة من الجريمة المحكوم فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,148,0,'919c039bd3f4e2c4ca4b992d2572c4b9','5d0b4b9e34cb2598d06be0dbed1a2ae7',replace($m208$لا يحول انقضاء الدعوى الجنائية بالموت قبل أو بعد إحالتها إلى المحكمة دون قضائها بالرد في الجرائم المنصوص عليها في المواد ) /113 ،112 فقرة أولى وثانية ورابعة( 113 ،مكررا )فقرة أولى( 115 ،114 ،من قانون العقوبات.
وعلى المحكمة أن تأمر بالرد في مواجهة الورثة والموصى لهم ،وكل من أفاد فائدة جدية من الجريمة ليكون الحكم بالرد نافذًا في أموال كل منهم بقدر ما استفاد.
ويجب أن تندب المحكمة محاميا للدفاع عمن وجه إليهم طلب الرد إذا لم ينيبوا من يتولى الدفاع عنهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,149,0,'19f151e29d18d4983027cf2a37a3cc73','9411eb789374d8fc70045e6a2b2901f5',replace($m208$يجوز للنائب العام أو من يفوضه من تلقاء نفسه أو بناء على طلب ذوي الشأن، ولقاضي التحقيق المختص ،عند وجود أدلة كافية على جدية الاتهام في جناية أو جنحة معاقب عليها بالحبس أن يصدر أمرا مسببا بمنع المتهم من السفر خارج البلاد أو بوضع اسمه على قوائم ترقب الوصول لمدة سنة قابلة للتجديد لمدة أو لمدد أخرى مماثلة ،لأمر تستلزمه ضرورات التحقيقات أو حسن سير إجراءات المحاكمة ،وضمان تنفيذ ما عسى أن يقضى به من عقوبات.
ويجوز للنائب العام أو من يفوضه من تلقاء نفسه أو بناء على طلب كل ذي شأن أن يصدر أمرا مسببا بالإدراج على قوائم الممنوعين من السفر أو ترقب الوصول للمحكوم عليهم المطلوب التنفيذ عليهم ،والمتهمين والمحكوم عليهم ممن تطلب الجهات القضائية الأجنبية المختصة تسليمهم أو محاكمتهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,150,0,'0935424450da831cb4e2e8e68a98a311','f157a4ed7acf2b74cda7c6269e86e917',replace($m208$يجوز للممنوع من السفر ،وللمدرج على قوائم ترقب الوصول أو وكيله أن يتظلم من هذا الأمر أمام المحكمة الجنائية المختصة منعقدة في غرفة المشورة ،خلال خمسة عشر يوما من تاريخ علمه به.
ولا يجوز إعادة التظلم من أمر المنع أو الإدراج قبل مضي ثلاثة أشهر من تاريخ رفض التظلم السابق عليه.
ويحصل التظلم بتقرير يودع قلم كتاب المحكمة الجنائية المختصة ،وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم يعلن بها المتظلم والنيابة العامة ،وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز خمسة عشر يوما من تاريخ التقرير به ،بحكم مسبب بعد سماع أقوال المتظلم أو وكيله والنيابة العامة ،ولها في سبيل ذلك أن تتخذ ما تراه من إجراءات أو تحقيقات ترى لزومها في هذا الشأن.$m208$,'<<CR>>',chr(13))),
('law',174,2025,151,0,'974a5aad084612a1c207a05e44a7f70c','41be1607480e694560a16b24785374c3',replace($m208$يجوز لسلطة التحقيق مصدرة الأمر ابتداء في كل وقت العدول عن الأمر الصادر منها ،كما يجوز لها التعديل فيه برفع اسمه من على قوائم المنع من السفر أو ترقب الوصول لمدة محددة إذا دعت الضرورة لذلك.
وللنائب العام للاعتبارات التي يقدرها ومن بينها الظروف الصحية منح أي من المدرجة أسماؤهم على قوائم الممنوعين من السفر بناء على طلبه أو وكيله أو أحد أقاربه حتى الدرجة الرابعة تصريحا للسفر إلى دولة أو دول معينة لمدة محددة ،إذا قدم الضمانات الكفيلة بالعودة إلى البلاد عند انتهاء مدة التصريح.
وفي جميع الأحوال ،ينتهي المنع من السفر بصدور قرار بأن لا وجه لإقامة الدعوى الجنائية أو بصدور حكم نهائي فيها بالبراءة أيهما أقرب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,152,0,'f02bda67d3413257268661fc14c41668','3940f26b6355d84dca4cc30aba09a3c9',replace($m208$إذا رأت النيابة العامة بعد التحقيق أنه لا وجه لإقامة الدعوى تصدر أمرا بذلك، سا لسبب آخر ،ولا يكون صدور وتأمر بالإفراج عن المتهم المحبوس ما لم يكن محبو الأمر بأن لا وجه لإقامة الدعوى في الجنايات إلا من المحامي العام أو من يقوم مقامه.
ويجب أن يكون الأمر مكتوبا ،وأن يشتمل على الأسباب التي بني عليها.
ويبين بالأمر اسم المتهم ،ولقبه ،وسنه ،ومحل ميلاده ،وسكنه ،ومهنته ،ورقمه القومي أو رقم وثيقة سفره ،وموطنه إن كان أجنبيا ،والواقعة المنسوبة إليه ووصفها القانوني.
ويعلن الأمر للمتهم وللمجني عليه وللمدعي بالحقوق المدنية ،وإذا كان أيهم قد توفى يكون الإعلان لورثته جملة دون ذكر أسمائهم في آخر موطن كان لمورثهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,153,0,'e580f7366538d1536824820f3af0482d','ef89df4ea8ad87246a6a5db922d5bc94',replace($m208$يجوز للنائب العام أن يلغي الأمر المشار إليه في المادة  152 من هذا القانون في مدة الثلاثة أشهر التالية لصدوره ،ما لم يكن قد صدر قرار من محكمة جنايات أول درجة أو من محكمة الجنح المستأنفة منعقدة في غرفة المشورة بحسب الأحوال برفض الطعن المرفوع في هذا الأمر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,154,0,'5ad4c6e8d7f267facccead0b62350cf0','0f28a85cd5862c74f86d195c6f4bfc6b',replace($m208$إذا رأت النيابة العامة أن الواقعة جنحة ،وأن الأدلة على المتهم كافية رفعت الدعوى إلى المحكمة الجزئية المختصة بنظرها ،ما لم تكن الجريمة من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس.
ويكون تكليف المتهم بالحضور أمام المحكمة الجزئية المختصة ،مع مراعاة حكم المادة  62 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,155,0,'2c708e52cee79c9ac418e55f6f9db2f4','a8ec0acef7cc5a1f49fe21bd79ee83f4',replace($m208$يجب على النيابة العامة عند صدور القرار بإحالة الدعوى إلى المحكمة الجزئية أن تقوم بإرسال جميع الأوراق إلى قلم كتاب المحكمة خلال ثلاثة أيام ،وبإعلان الخصوم بالحضور أمام المحكمة في أقرب جلسة في المواعيد المقررة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,156,0,'bd5ca9ee8896bb31dba67269dd75f3ad','9cf04390aefb4e610b35b59ff14538c2',replace($m208$إذا رأت النيابة العامة أن الواقعة جناية أو من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس ،وأن الأدلة كافية ترفع الدعوى إلى محكمة جنايات أول درجة ،وتعلن المتهم بأمر إحالتها ،وترسل الأوراق إليها فورا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,157,0,'061401e7e90524375e60b0bc7e703385','677d9dfc813cbf921e8ed6ad9b46cbb0',replace($m208$يكون رفع الدعوى في مواد الجنايات بإحالتها من المحامي العام أو من يقوم مقامه إلى محكمة جنايات أول درجة بتقرير اتهام تبين فيه بيانات المتهم ،ورقمه القومي ،والجريمة المسندة إليه بأركانها المكونة لها ،وجميع الظروف المشددة أو المخففة للعقوبة ،ومواد القانون المراد تطبيقها ،وترفق به قائمة بمضمون أقوال الشهود وأدلة الإثبات الأخرى ،ويندب المحامي العام من تلقاء نفسه محاميا لكل متهم بجناية صدر أمر بإحالته إلى محكمة جنايات أول درجة إذا لم يكن قد وكل محاميا للدفاع عنه ،وتعلن النيابة العامة الخصوم بالأمر الصادر بالإحالة إلى محكمة جنايات أول درجة خلال العشرة أيام التالية لصدوره.$m208$,'<<CR>>',chr(13))),
('law',174,2025,158,0,'3d5bea8fd0967eedb8e3570e12f4fbb6','f609274331881ba48da8e39d32b4e088',replace($m208$يرسل ملف القضية المحالة إلى قلم كتاب محكمة الاستئناف فورا ،وإذا طلب محامي المتهم أجلاً للاطلاع عليه يحدد له رئيس المحكمة ميعادا لا يجاوز عشرة أيام يبقى خلالها ملف القضية في قلم الكتاب ،حتى يتسنى له الاطلاع عليه من غير أن ينقل من هذا القلم.
ويجب على الخصوم أن يعلنوا شهودهم الذين لم تدرج أسماؤهم في القائمة المشار إليها في المادة  157 من هذا القانون على يد محضر ،بالحضور بالجلسة المحددة لنظر الدعوى ،وذلك مع تحمل نفقات الإعلان ،وإيداع مصاريف انتقال الشهود.$m208$,'<<CR>>',chr(13))),
('law',174,2025,159,0,'3d26bb2874759f768bd8005cccea738e','4f67dbd54040e637853d10823fc07f1d',replace($m208$إذا شمل التحقيق أكثر من جريمة واحدة من اختصاص محاكم من درجة واحدة، وكانت مرتبطة تحال جميعا بأمر إحالة واحد إلى المحكمة المختصة مكانيا بإحداها، فإذا كانت الجرائم من اختصاص محاكم من درجات مختلفة تحال إلى المحكمة الأعلى درجة.
وفي أحوال الارتباط التي يجب فيها رفع الدعوى عن جميع الجرائم أمام محكمة واحدة ،إذا كانت بعض الجرائم من اختصاص محاكم عادية ،وبعضها من اختصاص محاكم خاصة يكون رفع الدعوى بجميع الجرائم أمام المحاكم العادية ،ما لم ينص القانون على غير ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,160,0,'1cb0b8aa682ab43140b3f65cd69e583c','5e5ed88b018e301b999f568dab3c5905',replace($m208$مع مراعاة أحكام المادة  132 من هذا القانون ،يفصل عضو النيابة العامة المختص في القرار أو الأمر الصادر بالإحالة إلى المحكمة الجزئية أو محكمة جنايات أول درجة في استمرار حبس المتهم احتياطيا أو الإفراج عنه أو في القبض عليه إذا لم يكن قد قبض عليه أو كان قد أفرج عنه ،ما لم يكن قد أعلن بقرار أو أمر الإحالة ،فإذا قبض عليه تعين عرضه خلال ثمانٍ وأربعين ساعة على المحكمة المختصة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,161,0,'3b1e7c4b1ef79d87d8e57932a4b0702c','00cb3148e1c7481f5c9356a934fedbc3',replace($m208$إذا حدث بعد صدور الأمر بالإحالة ما يستوجب إجراء تحقيقات تكميلية فعلى النيابة العامة أن تقوم بإجرائها ،وتقدم المحضر إلى المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,162,0,'a85b6c23e87df3fdbcc9db38e189af35','f4fde9df13f66a94aad94de0cfbadfe9',replace($m208$يجوز للنائب العام أو المحامي العام في الأحوال المبينة في الفقرة الأولى من المادة  118 مكررا )أ( من قانون العقوبات أن يحيل الدعوى إلى محاكم الجنح لتقضي فيها وفقًا لأحكام المادة المذكورة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,163,0,'850310ced1ac149fdcc86382b17d3236','780d27255469d4bd748c61ee991fe7e4',replace($m208$الأمر الصادر من النيابة العامة بأن لا وجه لإقامة الدعوى يمنع من العودة إلى التحقيق ،إلا إذا ظهرت أدلة جديدة قبل انتهاء المدة المقررة لانقضاء الدعوى الجنائية.
ويعد من الأدلة الجديدة شهادة الشهود والمحاضر والأوراق التي تحمل أدلة أخرى لم تعرض على النيابة العامة ،ويكون من شأنها تقوية الأدلة التي وجدت غير كافية أو زيادة الإيضاح المؤدي إلى ظهور الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,164,0,'5775105ee744bd7c48bbb1f442b0063d','3bc68fdf8403c65a6953a18c706ecfc1',replace($m208$يجوز للمتهم وللمدعي بالحقوق المدنية استئناف الأمر الصادر من النيابة العامة بأن لا وجه لإقامة الدعوى ،ما لم يكن صادرا في تهمة موجهة ضد موظف أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها، ما لم تكن من الجرائم المنصوص عليها في المادة  123 من قانون العقوبات.
ويحصل الاستئناف بتقرير في قلم الكتاب في ميعاد عشرة أيام من تاريخ الإعلان بالأمر.
ويرفع الاستئناف إلى محكمة جنايات أول درجة منعقدة في غرفة المشورة في مواد الجنايات ،وإلى محكمة الجنح المستأنفة منعقدة في غرفة المشورة في مواد الجنح.
وعلى غرفة المشورة عند إلغاء الأمر بأن لا وجه لإقامة الدعوى أن تعيد القضية إلى النيابة العامة معينة الجريمة المرتكبة ونص القانون المنطبق عليها وأقوال شهود الإثبات ومضمون أدلة الإثبات الأخرى ،وذلك لإحالتها إلى المحكمة المختصة.
وتكون القرارات الصادرة من غرفة المشورة وفقًا لأحكام هذا الفصل نهائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,165,0,'3bcdde20f7feb93390f4f25abb658d39','366f22741fc08330990f735ef2d31939',replace($m208$يجوز لجميع الخصوم أن يستأنفوا الأوامر المتعلقة بمسائل الاختصاص ولا يوقف الاستئناف سير التحقيق ولا يترتب على القضاء بعدم الاختصاص بطلان إجراءات التحقيق.
ويكون ميعاد استئناف تلك الأوامر عشرة أيام من تاريخ إعلان الخصوم بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,166,0,'c3527c281319e2691dc004dc3c0a9e06','3ab6953ebbb0e0b61ceb3648f0a6f7d5',replace($m208$يجوز للمتهم أن يستأنف الأمر الصادر بحبسه احتياطيا أو بمد مدة الحبس، وللنيابة العامة إذا استلزمت ضرورة التحقيق أن تستأنف الأمر الصادر بالإفراج المؤقت عن المتهم المحبوس احتياطيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,167,0,'f4a767df5196e021e53eaf2876413403','4a36da2739cd9d52f6f2770bd93c18bd',replace($m208$يكون استئناف الأوامر الصادرة وفقًـا لأحكام هذا الفصل بتقرير يودع قلم كتاب المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,168,0,'94e5f8b744737cf42dc5143b131def0b','9136ebe8742cd7fa4a5433c449a4daea',replace($m208$يكون ميعاد استئناف النيابة العامة لأمر الإفراج المؤقت أربعا وعشرين ساعة من تاريخ صدوره ،ويجب الفصل في الاستئناف خلال ثمانٍ وأربعين ساعة من تاريخ رفعه.
ويكون استئناف المتهم لأمر الحبس أو مد مدته في أي وقت ،فإذا صدر قرار برفض استئنافه جاز له أن يتقدم باستئناف جديد على ذات القرار كلما انقضت مدة ثلاثين يوما من تاريخ صدور قرار رفض الاستئناف.$m208$,'<<CR>>',chr(13))),
('law',174,2025,169,0,'bad7879867333bf7438bdfe71c1b3a87','6554afb5495b2b524ab1762420d8fb97',replace($m208$يرفع الاستئناف أمام محكمة الجنح المستأنفة منعقدة في غرفة المشورة إذا كان الأمر المستأنف صادرا من القاضي الجزئي بالحبس الاحتياطي أو بمده أو بالإفراج، فإذا كان الأمر صادرا من تلك المحكمة ،يرفع الاستئناف إلى محكمة جنايات أول درجة منعقدة في غرفة المشورة ،وإذا كان صادرا من محكمة جنايات أول درجة يرفع الاستئناف إلى محكمة الجنايات المستأنفة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,170,0,'3b7c38bebb9867353a7a4abe6390c90f','d1d09bab55b7bf94682ae4f9b368446b',replace($m208$في غير الحالات المشار إليها في المواد من  164 إلى  169 من هذا القانون، يرفع الاستئناف أمام محكمة الجنح المستأنفة منعقدة في غرفة المشورة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,171,0,'882408c05d9e36c0149ef8283455440e','c9f16094ffa5c0bec6d9beba23ff21ac',replace($m208$يتعين الفصل في استئناف أوامر الحبس الاحتياطي أو مده أو الإفراج المؤقت، خلال ثمان وأربعين ساعة من تاريخ رفع الاستئناف ،وإلا وجب الإفراج عن المتهم إذا كان الاستئناف على قرار الإفراج المؤقت.
وتخصص دائرة أو أكثر من دوائر المحكمة الابتدائية أو محكمة الجنايات بدرجتيها لنظر استئناف أوامر الحبس الاحتياطي أو الإفراج المؤقت المشار إليهما في هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,172,0,'92edeee41cb57ae17b14d8ea42ec19a9','7d6b87ffab96aa0689132baf470a2c85',replace($m208$ينفذ الأمر الصادر بالإفراج المؤقت عن المتهم المحبوس احتياطيا ما لم تستأنفه النيابة العامة في الميعاد المنصوص عليه في المادة  168 من هذا القانون.
ويجوز للمحكمة المختصة بنظر الاستئناف ،أن تأمر بمد حبس المتهم طبقًـا لما هو مقرر في المادتين  124 ،123 من هذا القانون.
وإذا لم يفصل في الاستئناف خلال ثلاثة أيام من تاريخ التقرير به وجب تنفيذ الأمر بالإفراج فورا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,173,0,'6c56c01a3ee14e662e0ea0300ed8d004','1403764fd0f96f7be7448938f334fded',replace($m208$إذا رفض الاستئناف المرفوع من المدعي بالحقوق المدنية عن الأمر الصادر بأن لا وجه لإقامة الدعوى جاز للجهة المرفوع إليها الاستئناف أن تحكم عليه لصالح المتهم بالتعويضات الناشئة عن رفع الاستئناف إذا كان لذلك محل.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,174,0,'604ddbf1f6973370a7a55c9e8630478a','330dfbeccaeb69d1093682c5d7cc266f',replace($m208$إذا رأت النيابة العامة في مواد الجنايات أو الجنح أن تحقيق الدعوى بمعرفة قاضي التحقيق أكثر ملاءمة بالنظر إلى ظروفها الخاصة ،جاز لها في أية حالة كانت عليها الدعوى أن تطلب من رئيس المحكمة الابتدائية المختصة ندب أحد قضاتها لمباشرة هذا التحقيق ،ويكون الندب بقرار من الجمعية العامة للمحكمة أو من تفوضه في ذلك في بداية كل عام قضائي ،وفي هذه الحالة يكون القاضي المندوب هو المختص دون غيره بإجراء التحقيق من وقت مباشرته له.
ويجوز للمتهم أو للمدعي بالحقوق المدنية إذا لم تكن الدعوى موجهة ضد موظف عام أو مستخدم عام أو أحد رجال الضبط بجريمة وقعت منه أثناء تأديته لوظيفته أو بسببها أن يطلب من رئيس المحكمة الابتدائية إصدار قرار بهذا الندب.
وتصدر الجمعية العامة للمحكمة أو من تفوضه قرار الندب إذا تحققت الأسباب المبينة بالفقرة الأولى من هذه المادة بعد سماع أقوال النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,175,0,'5cc9df845ed073b8c5b1b9b4c414103c','1dc50bec43a336750294ba09141dfa99',replace($m208$يجوز لوزير العدل أن يطلب من محكمة الاستئناف ندب قاض لتحقيق جريمة معينة أو جرائم من نوع معين ،ويكون الندب بقرار من الجمعية العامة للمحكمة أو من تفوضه في ذلك في بداية كل عام قضائي ،وفي هذه الحالة يكون القاضي المندوب هو المختص دون غيره بإجراء التحقيق من وقت مباشرته له.$m208$,'<<CR>>',chr(13))),
('law',174,2025,176,0,'619663612627b40e3939d365310a5cc0','a5c1abad635ffba12c64612cdc5f7c89',replace($m208$يجب على قاضي التحقيق المندوب وفقًا لأحكام المادتين  175 ،174 من هذا القانون أن ينتهي من التحقيق خلال مدة لا تجاوز ستة أشهر من وقت مباشرته ،إلا إذا حال دون ذلك ضرورات يستلزمها التحقيق ،فإذا استلزم التحقيق تجاوز هذه المدة وجب علي قاضى التحقيق المندوب العرض على الجمعية العامة أو من تفوضه في إصدار قرار الندب ،بحسب الأحوال ،لتجديده مدة لا تجاوز ستة أشهر ،وإذا لم يستلزم التحقيق تجاوز هذه المدة أو خالف قاضي التحقيق المندوب إجراءات عرض الدعوى، ندبت الجمعية العامة أو من تفوضه قاضيا آخر لاستكمال التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,177,0,'101ed0d3234b1a625fdf4f5d12e9b1e8','a6b297a4784d1722ae9b3a43b85e30b3',replace($m208$لا يجوز لقاضي التحقيق مباشرة التحقيق في جريمة معينة أو جرائم من نوع معين ،إلا بناء على طلب من النيابة العامة أو بناء على إحالتها إليه من الجهات الأخرى المنصوص عليها في القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,178,0,'747ffc53a616eef29537499dad8bb0fd','5a85491202b445a4249e12a9726ad2de',replace($m208$مع عدم الإخلال بما ورد في شأنه نص خاص في هذا الفصل ،يباشر قاضي التحقيق اختصاصه طبقًا للأحكام المقررة في شأن التحقيق بمعرفة النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,179,0,'b8e5b10a56f4a5f6de739254f47b7c43','6efcd2b75105da39afc6620edfd9eadd',replace($m208$مع عدم الإخلال بأحكام المادة  176 من هذا القانون ،إذا أحيلت الدعوى إلى قاضي التحقيق كان مختصا دون غيره بتحقيقها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,180,0,'c293b6652f5db5adad0553f254990d91','898002d526ba29802deae711ff9dbd01',replace($m208$يجوز لقاضي التحقيق أن يندب أحد أعضاء النيابة العامة أو أحد مأموري الضبط القضائي للقيام بعمل معين أو أكثر من أعمال التحقيق عدا استجواب المتهم.
ويكون للمندوب في حدود ندبه كل السلطة التي لقاضي التحقيق.
وله إذا كانت هناك حاجة لاتخاذ إجراء من الإجراءات خارج دائرة اختصاصه أن يطلب من قاضي محكمة الجهة أو أحد أعضاء النيابة العامة أو يكلف أحد مأموري الضبط القضائي بها.
ولقاضي محكمة الجهة المندوب أن يكلف بذلك عند الضرورة أحد أعضاء النيابة العامة أو أحد مأموري الضبط القضائي طبقًا للفقرة الأولى من هذه المادة.
ويجب على قاضي التحقيق أن ينتقل بنفسه للقيام بهذا الإجراء كلما اقتضت مصلحة التحقيق ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,181,0,'71e45cd136775ae7a8f09eb768090fe7','dbab42461ea7a6c15a2c3af4a8ec821f',replace($m208$يجب على قاضي التحقيق في جميع الأحوال التي يندب فيها غيره لإجراء بعض أعمال التحقيقات أن يبين المسائل المطلوب تحقيقها ،والإجراءات المطلوب اتخاذها.
وللمندوب أن يجري أي عمل آخر من أعمال التحقيق أو أن يستجوب المتهم في الأحوال التي يخشى فيها فوات الوقت متى كان ذلك متصلا بالعمل المندوب له ولازما في كشف الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,182,0,'3aadfd1efd8861f409443dbcc44293b9','9b9d616d405dd6f3e9c3e77ba66e0f52',replace($m208$يكون لقاضي التحقيق عند مباشرة التحقيق السلطات المخولة للقاضي الجزئي الواردة في هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,183,0,'9375a61198aabb48fbaf075fc5afc812','493c4c568dc1468a7c236852e53628e1',replace($m208$يكون لقاضي التحقيق ذات الاختصاصات المقررة للمحكمة فيما يتعلق بنظام الجلسة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,184,0,'100a60abd673a760989e6d54027e6698','7856eab0d6763fce321d3bd752537ba5',replace($m208$تقوم النيابة العامة بإعلان الشهود الذين يقرر قاضى التحقيق سماعهم على النحو المبين بالمادة  88 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,185,0,'55dcc742b693bb3202ec80ca333d75d3','0d7c387ae195b7e7e79db55b24db9384',replace($m208$يجب على كل من دعي للحضور أمام قاضي التحقيق لتأدية شهادة أن يحضر بناء على الطلب المحرر إليه ،وإلا جاز للقاضي الحكم عليه بعد سماع أقوال النيابة العامة بدفع غرامة لا تجاوز خمسمائة جنيه ،ويجوز له أن يصدر أمرا بتكليفه بالحضور مرة أخرى بمصاريف من طرفه ،أو أن يصدر أمرا مسببا بضبطه وإحضاره.$m208$,'<<CR>>',chr(13))),
('law',174,2025,186,0,'fbe50e6d11f5b95eb91af1e0f2d66219','314be7b1f432a9a764744893d4312359',replace($m208$إذا حضر الشاهد أمام القاضي بعد تكليفه بالحضور مرة أخرى أو من تلقاء نفسه وأبدى أعذارا مقبولة ،جاز إعفاؤه من الغرامة بعد سماع أقوال النيابة العامة ،كما يجوز إعفاؤه بناء على طلب يقدم منه إذا لم يستطع الحضور بنفسه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,188,0,'0ca8275977936594ed4d42cd0bc7d870','0f8b3bbc2ecb54085f78735527b619c9',replace($m208$إذا كان الشاهد مريضا أو لديه ما يمنعه من الحضور تسمع شهادته في محل وجوده ،فإذا انتقل القاضي لسماع شهادته ،وتبين له عدم صحة العذر جاز له أن يحكم عليه بالحبس مدة لا تزيد على شهر أو بغرامة لا تجاوز ألفى جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,189,0,'27d31460950c00a5bca57d9d851aeb6f','72767cc4c909c30a7daece23b3b5b1e8',replace($m208$يجوز الطعن في الأحكام الصادرة على الشهود من قاضي التحقيق ،طبقًا للمواد 188 ،187 ،185 من هذا القانون أمام المحكمة المختصة بنظر القضية المحكوم فيها على الشهود بتلك الأحكام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,190,0,'38f89ebdab8b46eae82d6b3fcd7a6f0c','124cd10b9a5b782d7dc540eaed6d31ba',replace($m208$يجوز للنيابة العامة الاطلاع في أي وقت على الأوراق ،لتقف على ما جرى في التحقيق ،على ألا يترتب على ذلك تأخير السير فيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,191,0,'5534eb4f08f0a7ba6806260fab5682b9','3f670b803bffb0508eb03f7eb017f01c',replace($m208$يجوز للنيابة العامة وباقي الخصوم أن يقدموا إلى قاضي التحقيق الدفوع والطلبات والملاحظات التي يرون تقديمها أثناء التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,192,0,'38adf59397cf2ef0167a492f7732d58a','d35b437e2403a52fb194c04a36ebd34f',replace($m208$يفصل قاضي التحقيق خلال أربع وعشرين ساعة في الدفوع والطلبات والملاحظات المقدمة إليه ،ويبين الأسباب التي يستند إليها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,193,0,'0aca0f35aa387b4e26bf5896108185f4','0b4930029886278304028b4657c1346a',replace($m208$إذا لم تكن أوامر قاضي التحقيق صدرت في مواجهة الخصوم تبلغ إلى النيابة العامة ،وعليها أن تعلنهم بها خلال أربع وعشرين ساعة من تاريخ صدورها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,194,0,'355e06e34d5ee3b7de24decf83fdc139','63a22159df1b6ea35008c98527a75017',replace($m208$مع مراعاة حكم الفقرة الثانية من المادة  112 من هذا القانون ،يجب على قاضي التحقيق أن يستجوب فورا المتهم المقبوض عليه ،وإذا تعذر ذلك يودع في أحد مراكز الإصلاح والتأهيل أو أماكن الاحتجاز إلى حين استجوابه ،ويجب ألا تزيد مدة إيداعه على أربع وعشرين ساعة فإذا مضت هذه المدة وجب على القائم على إدارة تلك الأماكن أو هذه المراكز تسليمه إلى النيابة العامة ،وعليها أن تطلب في الحال من قاضي التحقيق استجوابه ،وعند الاقتضاء تطلب ذلك من القاضي الجزئي أو رئيس المحكمة ،أو أي قاض آخر يعينه رئيس المحكمة وإلا أمرت بإخلاء سبيله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,195,0,'b940803026bacab64fb4f505f4d62962','23672b863a5e01b20699b8e345d39f8c',replace($m208$إذا قبض على المتهم خارج دائرة المحكمة التي يجرى التحقيق فيها يرسل إلى النيابة العامة بالجهة التي قبض عليه فيها ،وعلى النيابة العامة أن تتحقق من جميع البيانات الخاصة بشخصه ،وتحيطه علما بالواقعة المنسوبة إليه ،وتدون أقواله في شأنها ،وترسله خلال أربع وعشرين ساعة إلى قاضي التحقيق المختص.
وإذا اعترض المتهم على نقله أو كانت حالته الصحية لا تسمح بالنقل يخطر قاضي التحقيق بذلك ،وعليه أن يصدر أمره فورا بالإجراء الواجب اتباعه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,196,0,'19ff8a7c15079f83dd11441c8b3e8de3','ed2c8eb48e95e07236436ee3d45a439a',replace($m208$يجب على قاضي التحقيق قبل أن يصدر أمرا بالحبس أو التدبير أن يسمع أقوال النيابة العامة ودفاع المتهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,197,0,'219e8fecbbf44004d538844072b42167','3e19841f20bda18ba83bc3fd44302100',replace($m208$يجوز للنيابة العامة أن تطلب من قاضي التحقيق في أي وقت حبس المتهم احتياطيا أو إخضاعه لأحد التدابير المنصوص عليها في المادة  114 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,198,0,'30899b59ef6c220134b1b87c7bcf17fe','33b44a0350d007eaf1dbb3b85b645643',replace($m208$مع مراعاة حكم الفقرة الثانية من المادة  121 من هذا القانون ،ينتهي الحبس الاحتياطي أو التدبير حتما بمضي خمسة عشر يوما ،ومع ذلك يجوز لقاضي التحقيق بعد سماع أقوال النيابة العامة والمتهم أن يصدر أمرا بمد الحبس أو التدبير لمدد متعاقبة بحيث لا تزيد كل منها على خمسة عشر يوما ولا يزيد مجموعها على خمسة وأربعين يوما.
فإذا لم ينته التحقيق ،ورأى قاضي التحقيق مد الحبس الاحتياطي أو التدبير زيادة على ما هو مقرر في الفقرة الأولى من هذه المادة تعين الالتزام بأحكام المادتين ،123 124 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,199,0,'07d876db985d789eeeb537db7007bb30','c4a8b3c22b2bb2e7fbd1c6a190be0f04',replace($m208$يجوز لقاضي التحقيق في كل وقت سواء من تلقاء نفسه أو بناء على طلب المتهم أن يأمر بعد سماع أقوال النيابة العامة بالإفراج عن المتهم أو بإنهاء التدبير إذا كان هو الذي أمر بالحبس الاحتياطي أو بالتدبير أو طلب منه ذلك.
فإذا كان الأمر بالحبس الاحتياطي أو التدبير صادرا من محكمة الجنايات أو الجنح المستأنفة منعقدة في غرفة المشورة بناء على استئناف النيابة العامة للأمر بالإفراج السابق صدوره من قاضي التحقيق ،فلا يجوز صدور أمر بالإفراج خلال المدة التي صدر بها الأمر بالحبس أو بإنهاء التدبير إلا من أي منهما ،بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,200,0,'7d56b4ba3ce152a7ced19441d16b368d','16968a4c7219d5f1cc61dcb7c662d517',replace($m208$يرسل قاضي التحقيق الأوراق إلى النيابة العامة بعد انتهاء التحقيق ،وعليها أن تقدم له طلباتها كتابة خلال ثلاثة أيام إذا كان المتهم محبوسا أو خاضعا لأحد التدابير، وعشرة أيام إذا كان مفرجا عنه.
وعلى قاضي التحقيق أن يخطر باقي الخصوم لإبداء ما لديهم من أقوال خلال ثلاثة أيام من تاريخ إخطارهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,201,0,'abef58340f80cc6beaff4448245d73ff','e88c051a929a734bed5ea71b5cb34009',replace($m208$إذا رأى قاضي التحقيق أنه لا وجه لإقامة الدعوى الجنائية ،يصدر أمرا مكتوبا بذلك ،ويفرج عن المتهم المحبوس ما لم يكن محبوسا لسبب آخر ،أو بإنهاء التدبير.
ولا يجوز له أن يصدر الأمر بأن لا وجه لإقامة الدعوى الجنائية لعدم الأهمية إلا بناء على طلب النيابة العامة.
ويجب أن يشتمل الأمر على الأسباب التي بني عليها.
ويعلن الأمر للنيابة العامة ،وللمتهم ،وللمجني عليه وللمدعي بالحقوق المدنية، وإذا كان أحدهم قد توفى يكون الإعلان لورثته جملة ،دون ذكر أسمائهم ،وذلك في آخر موطن كان لمورثهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,202,0,'d16ec64a01bda70900d3252df0f2ebc7','52180889ac148b3d2aeaa62d16085b0a',replace($m208$إذا رأى قاضي التحقيق أن الواقعة جنحة ،وأن الأدلة على المتهم كافية يأمر بإحالتها إلى المحكمة الجزئية المختصة بنظرها ،ما لم تكن الجريمة من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس ،فيحيلها إلى محكمة جنايات أول درجة فإذا تبين لقاضي التحقيق أن الواقعة مخالفة يحيلها للنيابة العامة لاتخاذ شئونها فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,203,0,'e8fc0f7f5c93492e4799f5018ce82cc8','1d8e9d84d736f7be5c600fb806722fd6',replace($m208$يتعين على النيابة العامة عند صدور القرار بإحالة الدعوى إلى المحكمة الجزئية المختصة أن تقوم بإرسال جميع الأوراق إلى قلم كتاب المحكمة خلال ثلاثة أيام، وبإعلان الخصوم بالحضور أمام المحكمة في أقرب جلسة وفي المواعيد المقررة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,204,0,'1ba236b896ef4f1de085b0c112062d8c','3e2ed7e98e0ca27018a25d83ff21cf5d',replace($m208$إذا رأى قاضي التحقيق أن الواقعة جناية أو من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس ،وأن الأدلة على المتهم كافية يحيل الدعوى إلى محكمة جنايات أول درجة ،ويكلف النيابة العامة بإرسال الأوراق إليها فورا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,205,0,'c72b3af6d44580616b66149d3ba629c4','56fca768a62f6ae5f3c2616468fa8b31',replace($m208$تسري في شأن الأوامر التي تصدر من قاضي التحقيق الأحكام المنصوص عليها في المواد  157 ،152 ،116 ،108 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,206,0,'9893349045eed87f24a565db7b549a83','72c215d30fb3c0892d8e7e36ca23e773',replace($m208$لا تجوز العودة إلى التحقيق طبقًا لحكم المادة  163 من هذا القانون إلا بناء على طلب النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,207,0,'e9b5b597c76e8332d6f1cfab1f7b277e','a6bd4184cbdff257f2cd50a95bf48802',replace($m208$يجوز للنيابة العامة أن تستأنف ولو لمصلحة المتهم جميع الأوامر التي يصدرها قاضي التحقيق سواء من تلقاء نفسه أو بناء على طلب الخصوم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,209,0,'9711bf8420a4fa444238fe39fbfc41e4','b13d45e193743fa2c12672f9a4c8c622',replace($m208$يجوز للمتهم وللمدعي بالحقوق المدنية استئناف الأوامر الصادرة من قاضي التحقيق بأن لا وجه لإقامة الدعوى ،إلا إذا كان الأمر صادرا في تهمة موجهة ضد موظف عام أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها ،ما لم تكن من الجرائم المنصوص عليها في المادة  123 من قانون العقوبات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,210,0,'9b320203274e83a3ef02b25676bba5d1','f318cb2b2ac23a43a600a04e361b3829',replace($m208$يجوز لجميع الخصوم أن يستأنفوا الأوامر المتعلقة بمسائل الاختصاص ،ولا يوقف الاستئناف سير التحقيق ،ولا يترتب على القضاء بعدم الاختصاص بطلان إجراءات التحقيق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,211,0,'db3e1773774926438ec6098a5a6ba727','80f712694cbecf6fe08cf44e02d9d39f',replace($m208$يكون ميعاد استئناف الأوامر المشار إليها في هذا الفصل ،عشرة أيام من تاريخ إعلان النيابة العامة وباقي الخصوم بها ،عدا الحالات المشار إليها في المادة  208 من هذا القانون فيكون ميعاد استئنافها على النحو المقرر بالمادة  168 من هذا القانون.
ويحصل الاستئناف بتقرير في قلم الكتاب ويتبع في شأن إجراءاته ونظره والفصل فيه القواعد والأحكام المنصوص عليها بالمواد الخاصة باستئناف الأوامر الصادرة من النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,212,0,'7345a9e1344927a0d440464335e67d61','8f47db12d8a944ee2a5f87ca2d946883',replace($m208$تحكم المحكمة الجزئية في كل واقعة تعد بمقتضى القانون جنحة عدا الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد.$m208$,'<<CR>>',chr(13))),
('law',174,2025,213,0,'fc3ae4ac7239a4c37d3c422560ab432b','37e99e25a124e56f890a00d4e7340ca5',replace($m208$تحكم محكمة الجنايات في كل واقعة تعد بمقتضى القانون جناية وفي الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس، وفى غيرها من الجرائم الأخرى التي ينص القانون على اختصاصها بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,214,0,'86bf76f9f5ff6aad0b050e0427742323','82f15d91b8533215f3a1f03fd45a3831',replace($m208$يحدد الاختصاص بالمكان الذي وقعت فيه الجريمة ،أو الذي يقيم فيه المتهم، أو الذي يقبض عليه فيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,215,0,'1215004d996cceec51b0c3a62f226b30','75dca04372a68d618269c45c4c9eaf90',replace($m208$في حالة الشروع تعتبر الجريمة وقعت في كل محل وقع فيه عمل من أعمال البدء في التنفيذ.
وفي الجرائم المستمرة يعتبر مكانًا للجريمة كل محل تقوم فيه حالة الاستمرار.
وفي جرائم الاعتياد والجرائم المتتابعة يعتبر مكاًنا للجريمة كل محل يقع فيه أحد الأفعال الداخلة فيها.
وإذا وقعت في الخارج جريمة من الجرائم التي تسري عليها أحكام القانون المصري ولم يكن لمرتكبها محل إقامة في مصر ولم يضبط فيها ،ترفع عليه الدعوى في الجنايات أمام محكمة جنايات أول درجة بدائرة محكمة استئناف القاهرة وفي الجنح أمام محكمة عابدين الجزئية.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,216,0,'2a7400a565919cee2c342202d2c88c46','3e57a1cace5ad137d5a9fd8dcfe650bd',replace($m208$يجوز رفع الدعوى المدنية ،مهما بلغت قيمتها ،بتعويض الضرر الناشئ عن الجريمة أمام المحاكم الجنائية لنظرها مع الدعوى الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,217,0,'5b424d9a923fd78e4c161c591a1e357a','f4d15f826cd71b475ab99b723131c951',replace($m208$تختص المحكمة الجنائية بالفصل في جميع المسائل التي يتوقف عليها الحكم في الدعوى الجنائية المرفوعة أمامها ،ما لم ينص القانون على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,218,0,'0f7a9332b158c6f0ce694ab9b9d3f9aa','27fee46531423416034500a91f28ba35',replace($m208$إذا كان الحكم في الدعوى الجنائية يتوقف على نتيجة الفصل في دعوى جنائية أخرى ،وجب وقف الدعوى الجنائية الأولى حتى يتم الفصل في الأُخرى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,219,0,'5039f8e2ba9a8c5a834ae1def27d7de5','f26d9f7825d9591ef8a98c83d10a70fb',replace($m208$إذا كان الحكم في الدعوى الجنائية يتوقف على الفصل في مسألة من مسائل الأحوال الشخصية جاز للمحكمة الجنائية أن توقف الدعوى وتحدد للمتهم أو المجنى عليه أو المدعي بالحقوق المدنية بحسب الأحوال أجلاً لرفع المسألة المذكورة إلى الجهة ذات الاختصاص.
ولا يمنع وقف الدعوى من اتخاذ الإجراءات ،أو التحقيقات الضرورية، أو المستعجلة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,220,0,'6f8bd8bd8b39b4966a10df7eb088a8c7','9019650c7b03bfcf1b8cf4865703419f',replace($m208$إذا انقضى الأجل المشار إليه في المادة  219 من هذا القانون ولم ترفع الدعوى إلى الجهة ذات الاختصاص ،يجوز للمحكمة أن تصرف النظر عن وقف الدعوى وتفصل فيها.
كما يجوز لها أن تحدد للخصم أجلاً آخر إذا رأت أن هناك أسبابا مقبولة تبرر ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,221,0,'3ccb343e2ebc3eaa7f36df194918e4ab','a543b95fd6c63d916b2615a70718a881',replace($m208$تتبع المحاكم الجنائية في المسائل غير الجنائية التي تفصل فيها تبعا للدعوى الجنائية طرق الإثبات المقررة في القانون الخاص بتلك المسائل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,222,0,'6544be3d92cc0b6012eda7ab37e368a5','f5ae522676866d24ed4f9712a64e5db2',replace($m208$إذا قدمت دعوى عن جريمة واحدة أو عدة جرائم مرتبطة إلى جهتين من جهات التحقيق أو الحكم تابعتين لمحكمة ابتدائية واحدة وقررت كل منهما نهائيا اختصاصها أو عدم اختصاصها وكان الاختصاص منحصرا فيهما ،يرفع طلب تحديد الجهة التي تفصل فيها إلى دائرة الجنح المستأنفة بالمحكمة الابتدائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,223,0,'33228e83d74830e9decd3f0320a0fe17','09aedfd0d3d49aaed99f9079408ac3b4',replace($m208$إذا صدر حكمان بالاختصاص ،أو بعدم الاختصاص من جهتين تابعتين لمحكمتين ابتدائيتين أو من محكمتين ابتدائيتين أو من محكمتين من محاكم الجنايات بدرجتيهما يرفع طلب تحديد المحكمة المختصة إلى محكمة النقض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,224,0,'8cb780f05bd4ba775810f4fcbc9eb50a','da008fa07f4b077e7c46d5a60a926445',replace($m208$يجوز لكل من الخصوم في الدعوى تقديم طلب تحديد المحكمة التي تفصل فيها بعريضة مشفوعة بالأوراق المؤيدة لهذا الطلب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,225,0,'9c3e590a75e1bf40bebc9b57321dfed2','bc2503474deaa5257c5f539355cb019d',replace($m208$تأمر المحكمة بعد اطلاعها على الطلب بإيداع الأوراق في قلم الكتاب.
ويجب على قلم الكتاب إعلان باقي الخصوم بإيداع الأوراق ليطلعوا عليها، ويقدموا مذكرة بأقوالهم في مدة العشرة الأيام التالية لإعلانهم بالإيداع ،ويترتب على أمر الإيداع وقف السير في الدعوى المقدم بشأنها الطلب ،ما لم تر المحكمة غير ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,226,0,'65dc941572296f7fa46f883f56014f30','2ce6adf9e037a9553563f8632c8f3224',replace($m208$تحدد محكمة النقض أو المحكمة الابتدائية بعد الاطلاع على الأوراق المحكمة ضا في شأن الإجراءات والأحكام أو الجهة التي تتولى السير في الدعوى ،وتفصل أي التي تكون قد صدرت من المحاكم الأخرى التي قضت بإلغاء اختصاصها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,227,0,'44aeb3e0894acce5494bcdee4bc8ddc1','41d6673a30d0e236eb29ab2c67d13f57',replace($m208$إذا رفض الطلب يجوز الحكم على الطالب إذا كان من غير النيابة العامة بغرامة لا تتجاوز خمسمائة جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,228,0,'3a1269c1771736701000cbea84bb2c50','c38327b1fbe039d6b88277aeadb44c0c',replace($m208$تحال الدعوى إلى محكمة الجنح بناء على تكليف المتهم مباشرة بالحضور من قِبل أحد أعضاء النيابة العامة أو من المدعي بالحقوق المدنية ،أو أمر يصدر من قاضي التحقيق أو محكمة الجنح المستأنفة منعقدة في غرفة المشورة.
ويجوز الاستغناء عن تكليف المتهم بالحضور إذا حضر الجلسة ووجهت إليه التهمة من النيابة العامة وقبل المحاكمة ،ومع ذلك لا يجوز للمدعي بالحقوق المدنية أن يرفع الدعوى إلى المحكمة بتكليف خصمه مباشرة بالحضور أمامها إذا صدر أمر من قاضي التحقيق أو النيابة العامة بأن لا وجه لإقامة الدعوى الجنائية ولم يستأنف المدعي بالحقوق المدنية هذا الأمر في الميعاد أو استأنفه فأيدته محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،أو إذا كانت الدعوى موجهة ضد موظف أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها ما لم تكن من الجرائم المشار إليها في المادة  123 من قانون العقوبات.
وفي جميع الأحوال ،لا يجوز رفع أو تحريك الدعاوى لوقف أو مصادرة الأعمال الفنية والأدبية والفكرية أو ضد مبدعيها إلا عن طريق النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,229,0,'b023e3605bf258e254a6410d711b81aa','093b4f6bd7cb99683a1d024bfeaa3ef6',replace($m208$يكون تكليف الخصوم بالحضور أمام المحكمة قبل انعقاد الجلسة بسبعة أيام كاملة على الأقل في الجنح غير مواعيد المسافة المنصوص عليها بقانون المرافعات المدنية والتجارية ،وذلك بناء على طلب النيابة العامة أو المدعي بالحقوق المدنية.
وتذكر في ورقة التكليف بالحضور بيانات المتهم ،ورقمه القومي أو رقم وثيقة سفره وموطنه إذا كان أجنبيا ،والتهمة ،ومواد القانون التي تنص على العقوبة.
ويجوز في حالة التلبس ،وفي الحالات التي يكون فيها المتهم محبوسا احتياطيا في إحدى الجنح ،أن يكون التكليف بالحضور بغير ميعاد ،فإذا حضر المتهم وطلب إعطاءه ميعادا لتحضير دفاعه تأذن له المحكمة بالميعاد المقرر بالفقرة الأولى من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,230,0,'a192b4db00470cc0de5302993233358a','d2f890f02e8f150ec223c612864e3296',replace($m208$تعلن ورقة التكليف بالحضور على النحو المنصوص عليه بالفقرتين الأولى والثانية من المادة  72 من هذا القانون أو لشخص المعلن إليه أو في موطنه المثبت ببطاقة رقمه القومي.
وإذا لم يجد المحضر الشخص المطلوب إعلانه في موطنه كان عليه أن يسلم الورقة إلى من يقرر أنه وكيله أو أنه يعمل في خدمته أو أنه من القاطنين معه من الأزواج والأقارب والأصهار.
وإذا لم يكن للمتهم محل إقامة ثابت يسلم الإعلان للسلطة الإدارية التابع لها آخر محل معلوم له ،ويعتبر المكان الذي وقعت فيه الجريمة آخر محل إقامة للمتهم ما لم يثبت خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,231,0,'d88cdf8ab592f0b6477a9fd205b4bd7c','37eb909697771d247fa0ade95d948c89',replace($m208$إذا لم يتمكن المحضر من تسليم الورقة طبقًا للمادة  230 من هذا القانون، أو امتنع من وجده من المذكورين في الفقرة الثانية من تلك المادة عن التوقيع على الأصل بالاستلام أو عن استلام الصورة ،وجب على المحضر خلال أربع وعشرين ساعة أن يوجه إلى المعلن إليه رسالة نصية على الهاتف المحمول المثبت ببيانات رقمه القومي تشمل جميع بيانات الإعلان ،ويرفق بملف القضية تقرير من مركز الإعلانات المنصوص عليه في المادة  232 من هذا القانون باستلام الرسالة، ومستخرج مطبوع لنص رسالة الإعلان.
وفي الأحوال التي يثبت فيها من تقرير مركز الإعلان تعذر استلام الرسالة ،أو إذا لم يوجد هاتف محمول مثبت ببيانات الرقم القومي للمعلن إليه ،أو إذا تعذر الإعلان من خلال المركز المشار إليه لأي سبب من الأسباب ،وجب على المحضر أن يسلم أصل الإعلان خلال أربع وعشرين ساعة إلى مأمور القسم أو المركز أو العمدة أو شيخ البلد الذي يقع موطن المعلن إليه في دائرته ،بحسب الأحوال ،وذلك بعد توقيعه على الأصل بالاستلام.
ويجب على المحضر خلال أربع وعشرين ساعة أن يوجه إلى المعلن إليه في موطنه الأصلي كتابا مسجلاً ،مرفقًا به صورة أخرى من الورقة ،يخبره فيه بأن الصورة سلمت إلى جهة الإدارة.
كما يجب على المحضر أن يحرر محضرا بالإجراءات التي اتبعها يرفق به صورة من الإعلان يودع بالقضية ،ويعتبر الإعلان منتجا لآثاره من وقت إرفاق تقرير استلام الرسالة أو من وقت تسليم الصورة إلى من سلمت إليه قانونًا بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,232,0,'f13b0762c2f754edb29bdd2e69ea9ac5','8b25e057f591ef161174d274da552c3d',replace($m208$ينشأ بدائرة كل محكمة جزئية مركز للإعلانات الهاتفية يتبع وزارة العدل يختص بالاستعلام من قطاع الأحوال المدنية عن الرقم القومي للمتهم ورقم الهاتف المحمول المثبت به ،وفقًا للنظم والقواعد المعمول بها في قطاع الأحوال المدنية وبما لا يتعارض مع مقتضيات الأمن القومي وسرية قواعد البيانات القومية ،وإرسال الإعلانات الهاتفية والإلكترونية وإعداد تقرير بما يفيد استلام تلك الرسائل.
ويقدر القاضي المختص الرسم المستحق على الإعلان الهاتفي وفقًا لحكم المادة 16 من القانون رقم  90 لسنة  1944 بشأن الرسوم القضائية ورسوم التوثيق في المواد المدنية ،على أن يلزم بأدائه من يحكم عليه بالمصاريف الجنائية.
ويخصص الرسم المشار إليه بالفقرة الثانية من هذه المادة للإنفاق على تطوير مراكز الإعلان وإعداد قواعد البيانات اللازمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,233,0,'374a41d0315f5a093f94e09637ba2233','e961ebfcb28f225e68567c778534dcb2',replace($m208$يجب أن تشتمل الأوراق التي يقوم المحضرون بإعلانها على البيانات الآتية: -تاريخ اليوم والشهر والسنة والساعة التي حصل فيها الإعلان.
-بيان القضية المعلن بشأنها ،وموضوعها ،وصفة المعلن إليه فيها.
-اسم المحضر والمحكمة التي يعمل بها.
-اسم المعلن إليه ،ولقبه ،ومهنته أو وظيفته ،وموطنه فإن لم يكن موطنه معلوما وقت الإعلان فآخر موطن كان له.
-تاريخ ومكان انعقاد الإجراء المعلن بشأنه.
-اسم وصفة من سلمت إليه صورة الورقة ،وتوقيعه على الأصل بالاستلام.
-توقيع المحضر باسمه الثلاثي على كل من الأصل والصورة توقيعا مقروءا.
ويصدر قرار من وزير العدل ،بالتنسيق مع الوزير المختص بتحديد آلية إثبات تسلسل الإعلانات الهاتفية والإلكترونية ،وكيفية التحقق من وصولها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,234,0,'f5f09d11af3e70518d49aa0198bff9e6','b168c772191f81c31570e90da895fbba',replace($m208$يكون إعلان النزيل بتسليم الأوراق المطلوب إعلانها إليه بشخصه ،وتفهيمه ما تضمنته في حضور مدير مركز الإصلاح والتأهيل العمومي أو مدير مركز الإصلاح الجغرافي أو من يقوم مقامهما ،وإذا أبدى النزيل رغبة في إرسال صورة الإعلان إلى شخص معين وجب إرسالها إليه بكتاب موصى عليه ،وإثبات هذه الإجراءات في سجل خاص يعد لهذا الغرض.
ويكون إعلان المحبوسين بالسجون العسكرية بتسليم الأوراق المطلوب إعلانها إليه بشخصه ،وتفهيمه ما تضمنته بمعرفة هيئة التنظيم والإدارة بالقوات المسلحة ،وإذا أبدى النزيل رغبة في إرسال صورة الإعلان إلى شخص معين وجب إرسالها إليه بكتاب موصى عليه ،وإثبات هذه الإجراءات في سجل خاص يعد لهذا الغرض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,235,0,'a023749bb5b698fbab07d66c2f3ac3c6','1ac5f0d34372ba03ed3dd05701f4a202',replace($m208$يجوز للخصوم أن يطلعوا على أوراق الدعوى بمجرد إعلانهم بالحضور أمام المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,236,0,'ebde7089e94c63dd81ba4e8a6f61282c','e7080b1672a96640c3fa9c6268ae5444',replace($m208$يجب على المتهم في جنحة أن يحضر بشخصه ،أو بمحام عنه موكَـل، وإذا لم يكن له محام في الجنح التي يجوز الحبس فيها وجب على المحكمة أن تندب له محاميا للدفاع عنه ،وذلك مع عدم الإخلال بما للمحكمة من الحق في أن تأمر بحضوره شخصيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,237,0,'5832e30541b59e8fcb8d465dbc43fbbd','2613f3fc8934db3a39f33cef8f5aef19',replace($m208$إذا لم يحضر الخصم المكلف بالحضور حسب القانون في اليوم المبين بورقة التكليف بالحضور بشخصه ،أو لم يحضر وكيل عنه جاز الحكم في غيبته بعد الاطلاع على الأوراق ،إلاّ إذا كانت ورقة التكليف بالحضور قد سلمت لشخصه أو على النحو المنصوص عليه بالفقرتين الأولى والثانية من المادة  72 من هذا القانون ،وتبين للمحكمة أنه لا مبرر لعدم حضوره ،يعتبر الحكم حضوريا.
ويجوز للمحكمة بدلاً من الحكم غيابيا أن تؤجل الدعوى إلى جلسة تالية وتأمر بإعادة إعلان الخصم في موطنه ،مع تنبيهه إلى أنه إذا تخلف هو أو وكيله عن الحضور في هذه الجلسة يعتبر الحكم حضوريا ،فإذا لم يحضر هو أو وكيله دون مبرر تقبله المحكمة يعتبر الحكم حضوريا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,238,0,'d0ae799a204f9d74dcb9e952536580ee','d45417b157c605c907e3af6a4790fd06',replace($m208$يعتبر الحكم حضوريا بالنسبة إلى كل من يحضر من الخصوم عند النداء على الدعوى ولو غادر الجلسة بعد ذلك ،أو إذا حضر أيا من الجلسات ثم تخلف هو أو وكيله عن الحضور في الجلسات التي تؤجل إليها الدعوى دون أن يقدم عذرا تقبله المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,239,0,'8f4a5ebf76a2d6d566984278a4211dd2','9070ebd1f0c45ada6a012a0b5923b8db',replace($m208$إذا رفعت الدعوى على عدة أشخاص عن واقعة واحدة وحضر بعضهم وتخلف البعض الآخر رغم تكليفهم بالحضور حسب القانون تؤجل المحكمة الدعوى إلى جلسة تالية وتأمر بإعادة إعلان من تخلف في موطنه مع تنبيههم إلى أنهم إذا تخلفوا عن الحضور في هذه الجلسة يعتبر الحكم حضوريا بالنسبة لهم ،فإذا لم يحضروا وتبين للمحكمة أن لا مبرر لعدم حضورهم يعتبر الحكم حضوريا بالنسبة لهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,240,0,'347fbdfcb70df14a114eb3be6c14efda','4f91373a589f2cb79944dd7136ad0b1d',replace($m208$في الأحوال المنصوص عليها في المواد  239 ،238 ،237 من هذا القانون التي يعتبر فيها الحكم حضوريا يجب على المحكمة أن تحقق الدعوى أمامها كما لو كان الخصم حاضرا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,242,0,'1b1ce464bc5710fb3eccd98354cd971f','ba2698c3da5f03ee8445fd8d2c59c0fc',replace($m208$ضبط الجلسة وإدارتها منوطان برئيسها ،وله في سبيل ذلك أن يخرج من قاعة الجلسة من يخل بنظامها ،فإن لم يمتثل وتمادى ،يجوز للمحكمة أن تحكم على الفور بحبسه أربعا وعشرين ساعة أو بتغريمه خمسمائة جنيه ويكون حكمها بذلك غير جائز استئنافه ،فإذا كان الإخلال قد وقع ممن يؤدي وظيفة في المحكمة كان لها أن توقع عليه أثناء انعقاد الجلسة ما للسلطة المختصة توقيعه من الجزاءات التأديبية.
ويجوز للمحكمة إلى ما قبل انتهاء الجلسة أن ترجع عن الحكم أو القرار الذي تصدره بناء على الفقرة الأولى من هذه المادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,243,0,'68cc4a0c62a2b61fbd34b00a63f091e3','4421eba9c382c2dc11527698c8b4e89c',replace($m208$إذا وقعت جنحة أو مخالفة في الجلسة يجوز للمحكمة أن تقيم الدعوى على المتهم في الحال ،وتحكم فيها بعد سماع أقوال النيابة العامة ودفاع المتهم.
ولا يتوقف رفع الدعوى في هذه الحالة على شكوى أو طلب إذا كانت الجريمة من الجرائم المنصوص عليها في المواد  10 ،8 ،3 من هذا القانون ،أما إذا وقعت جناية يصدر رئيس المحكمة أمرا بإحالة المتهم إلى النيابة العامة دون إخلال بحكم المادة  15 من هذا القانون.
وفي جميع الأحوال ،يحرر رئيس المحكمة محضرا ويأمر بالقبض على المتهم إذا اقتضى الحال ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,244,0,'5194275d9a98cd9d7fe64fa6c2e00a1c','667e0735ad90946e46d25a6f1f275d7c',replace($m208$مع عدم الإخلال بالضمانات المقررة في قانون المحاماة وتعديلاته ،إذا وقع من المحامي أثناء قيامه بواجبه في الجلسة وبسببه ما يجوز اعتباره إخلالاً بنظام الجلسة، أو ما يستدعي مؤاخذته جنائيا يحرر رئيس الجلسة ،مذكرة بما حدث.
وللمحكمة إحالة المذكرة إلى النيابة العامة لإجراء التحقيق إذا كان ما وقع منه يستدعي مؤاخذته جنائيا ،وإلى رئيس المحكمة إذا كان ما وقع منه يستدعي مؤاخذته تأديبيا ،وتخطر النقابة الفرعية المختصة بذلك.
وفي جميع الأحوال لا يجوز أن يكون رئيس الجلسة التي وقع فيها الحادث أو أحد أعضائها عضوا في الهيئة التي تنظر الدعوى.
وذلك كُله مع عدم الإخلال بحالة التلبس.$m208$,'<<CR>>',chr(13))),
('law',174,2025,245,0,'472672a2a1dcb1a0a0a8d2983811966c','a594a1e9a7b11d6189db9d7698fb7a49',replace($m208$الجرائم التي تقع في الجلسة ولم تُقم المحكمة الدعوى فيها حال انعقادها ،يكون نظرها وفقا للقواعد العادية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,246,0,'446bb17b487be51d4216639287e0e196','77ab41b9d539b281ca131a6160f7feab',replace($m208$يمتنع على القاضي أن يشترك في نظر الدعوى إذا كانت الجريمة قد وقعت عليه شخصيا ،أو إذا كان قد قام في الدعوى بعمل مأمور الضبط القضائي ،أو بوظيفة النيابة العامة ،أو المدافع عن أحد من الخصوم ،أو أدى فيها شهادة ،أو باشر عملاً من أعمال أهل الخبرة.
كما يمتنع عليه أن يشترك في الحكم إذا كان قد قام في الدعوى بعمل من أعمال التحقيق أو الإحالة أو كان قد أصدر فيها قرارا بالمنع من التصرف أو المنع من السفر أو الوضع على قوائم ترقب السفر والوصول ،أو أن يشترك في الحكم في الطعن إذا كان الحكم المطعون فيه صادرا منه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,247,0,'5b3be35c4a536a0ac84188938f75457c','d12e9b7fd980676e9a79f8becf7c5321',replace($m208$يجوز للخصوم رد القضاة عن الحكم في الحالات الواردة في المادة  246 من هذا القانون ،وفي سائر حالات الرد المبينة في قانون المرافعات في المواد المدنية والتجارية.
ولا يجوز رد أعضاء النيابة العامة ولا مأموري الضبط القضائي.
ويعتبر المجني عليه فيما يتعلق بطلب الرد بمثابة خصم في الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,248,0,'1fd411fc21b36ea58ff06d16c3658057','5b9274a557b1db97441c9a7776a64ccb',replace($m208$يتعين على القاضي إذا قام سبب من أسباب الرد أن يصرح للمحكمة لتفصل في أمر تنحيه في غرفة المشورة ،وعلى القاضي الجزئي أن يطرح الأمر على رئيس المحكمة ،ويجب عليه عرض الأمر على محكمة الجنح المستأنفة منعقدة في غرفة المشورة للفصل فيه وذلك للإذن له بالتنحي.
وفيما عدا أحوال الرد المقررة بالقانون ،يجوز للقاضي إذا قامت لديه أسباب يستشعر منها الحرج من نظر الدعوى أن يعرض أمر تنحيه على المحكمة ،أو على رئيس المحكمة بحسب الأحوال للفصل فيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,249,0,'3d63c0d376889a814dbbc12c34bb82ae','6dd6152d9fe35f7daee34e6c417ca7b3',replace($m208$يتبع في نظر طلب الرد والحكم فيه القواعد المنصوص عليها في قانون المرافعات المدنية والتجارية.
ويكون الرد لمرة واحدة طوال فترة المحاكمة متى كان ذلك من نفس الشخص ولذات السبب.
ولا يجوز تقديم طلب الرد في قلم الكتاب ،إلا بعد سداد كفالة مقدارها عشرة آلاف جنيه ،وتتعدد الكفالة بتعدد طلبات الرد.
ويجب الحكم بمصادرة الكفالة في حالة رفض طلب الرد.
ويجوز للمحكمة التي تنظر طلب الرد أن تحكم على طالب الرد بغرامة لا تجاوز عشرة آلاف جنيه ،إذا تبين لها أن طلب الرد كان بسوء نية أو كان الغرض منه تعطيل الفصل في الدعوى.
وتحدد الجمعية العمومية في بداية كل عام قضائي دائرة أو أكثر في محاكم الاستئناف، لنظر طلبات الرد على أن تفصل في الطلب خلال أسبوعين من تاريخ عرضه عليها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,250,0,'bab496a8ed4f9bde6e60ee60da1d045e','251cdafc880d15efb252c1bf0d13b9ae',replace($m208$يجوز لمن لحقه ضرر شخصي مباشر من الفعل المسبب للجريمة ،محقق الوقوع ،حالاً أو مستقبلاً ،أن يدعي بحقوق مدنية أمام المحكمة التي تنظر الدعوى الجنائية في أي حالة كانت عليها حتى صدور القرار بإقفال باب المرافعة ،ولا يقبل منه ذلك أمام المحكمة الاستئنافية.
ويكون الادعاء بالحقوق المدنية وإدخال المسئول عنها أمام المحكمة بإعلان على يد محضر ،أو بطلب في الجلسة إذا كان الخصم حاضرا ،وإلا وجب تأجيل الدعوى وتكليف الطالب بإعلانه بطلباته.
فإذا كان قد سبق قبول المدعي بالحقوق المدنية بهذه الصفة ،فإن إحالة الدعوى الجنائية إلى المحكمة تشمل الدعوى المدنية.
ولا يجوز أن يترتب على تدخل المدعي بالحقوق المدنية تأخير الفصل في الدعوى الجنائية ،وإلا حكمت المحكمة بعدم قبول تدخله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,251,0,'8b7142ca8b4475c6852590b32adc2172','c2ef7894525676cd2f52ba348c476f98',replace($m208$إذا كان من لحقه ضرر من الجريمة فاقد الأهلية ولم يكن له من يمثله قانونًا ،جاز للمحكمة المرفوعة أمامها الدعوى الجنائية بناء على طلب النيابة العامة أن تحدد له وكيلا ليدعي بالحقوق المدنية بالنيابة عنه ،ولا يترتب على ذلك في أية حال إلزامه بالمصاريف القضائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,252,0,'184c276e10a67ecec149b63738d630a2','cd2014a1919961c790565151dd9fde84',replace($m208$ترفع الدعوى المدنية بتعويض الضرر على المتهم بالجريمة إذا كان بالغًا واحد وعشرين عاما ،وعلى من يمثله إذا لم يبلغها أو إذا بلغها وكان فاقد الأهلية ،فإن لم يكن له من يمثله ،وجب على المحكمة أن تحدد من يمثله طبقًـا للمادة 251 من هذا القانون.
ويجوز رفع الدعوى المدنية أيضا على المسئولين عن الحقوق المدنية عن فعل المتهم.
وللنيابة العامة أن تدخل المسئولين عن الحقوق المدنية ،ولو لم يكن في الدعوى مدعٍ بحقوق مدنية ،للحكم عليهم بالمصاريف المستحقة للحكومة.
ولا يجوز أمام المحاكم الجنائية أن ترفع دعوى الضمان ،ولا أن يدخل في الدعوى غير المدعى عليهم بالحقوق المدنية والمسئول عن الحقوق المدنية والمؤمن لديه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,253,0,'f999da3e6482df6b514d6a2940e9e776','b49c1c336abe8c7bad005610bf30ee94',replace($m208$يجوز للمسئول عن الحقوق المدنية أن يتدخل من تلقاء نفسه في الدعوى الجنائية في أية حالة كانت عليها.
وللنيابة العامة والمدعي بالحقوق المدنية المعارضة في قبول تدخله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,254,0,'8363e9126596952490f422989ae4c635','6307946ff7a7a5a5dfd09cc7e275e5a5',replace($m208$يجب على كل من المجني عليه والمدعي بالحقوق المدنية والمسئول عنها أن يعين له موطنًا مختارا في البلدة الكائن فيها مقر المحكمة التي يجري فيها التحقيق ،أو أن يعين رقم هاتف محمول أو بريدا إلكترونيا لإعلانه عليه ،ويكون ذلك بتقرير في قلم الكتاب.
وإذا لم يعين أي من الأشخاص المشار إليهم في الفقرة الأولى من هذه المادة البيانات على النحو المبين بها ،أو كان البيان ناقصا أو غير صحيح ،أو طرأ تغيير على ما عينه من بيانات ولم يخطر بها ،يكون الإعلان في قلم الكتاب صحيحا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,255,0,'32af38d3225f1349063c3162d2e3832f','310afb2d8a4ca50f3df4c7f90b28e4fb',replace($m208$لا يقبل الادعاء بالحقوق المدنية إلا بعد أداء الرسوم القضائية وإيداع الأمانة التي تقدرها النيابة العامة أو قاضي التحقيق أو المحكمة التي تنظر الدعوى الجنائية ،على ذمة أتعاب ومصاريف الخبراء والشهود وغيرهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,256,0,'74c68a91db927838ac224291d1a9afa9','ea2d563847e6dcfa2e2c2473ea426a8e',replace($m208$يجوز لكل من المتهم والمسئول عن الحقوق المدنية والنيابة العامة أن يعارض في الجلسة في قبول المدعي بالحقوق المدنية إذا كانت الدعوى المدنية غير جائزة أو غير مقبولة ،وتفصل المحكمة في المعارضة بعد سماع أقوال الخصوم.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,257,0,'ec3610925b724d49db2340ad521f2a87','01166199e89ed9e94a61926e57c48d46',replace($m208$لا يمنع القرار الصادر من النيابة العامة أو قاضي التحقيق بعدم قبول المدعي بالحقوق المدنية من الادعاء مدنيا بعد ذلك أمام المحكمة الجنائية ،أو من رفع دعواه أمام المحكمة المدنية.
ولا يترتب على القرار الصادر من المحكمة بقبول الدعوى المدنية بطلان الإجراءات التي لم يشترك فيها المدعي بالحقوق المدنية قبل ذلك.
والقرار الصادر من النيابة العامة أو قاضي التحقيق بقبول المدعي بالحقوق المدنية لا يلزم المحكمة المرفوعة أمامها الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,258,0,'2a53b147bd829a6dc706c710ba0a15cb','df2954fd964b349af7f29a9d47babe77',replace($m208$يجوز رفع الدعوى المدنية قبل المؤمن لديه لتعويض الضرر الناشئ عن الجريمة أمام المحكمة التي تنظر الدعوى الجنائية.
وتسري على المؤمن لديه جميع الأحكام الخاصة بالمسئول عن الحقوق المدنية المنصوص عليها في هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,259,0,'ec4f8f13f7058d3b8a16686e7e5b475a','3ed1a46866ba9934194a59a931390c98',replace($m208$تنقضي الدعوى المدنية بمضي المدة المقررة في القانون المدني ،ومع ذلك لا تنقضي بالتقادم الدعوى المدنية الناشئة عن الجرائم المنصوص عليها في الفقرة الثانية من المادة  17 من هذا القانون.
وإذا انقضت الدعوى الجنائية بعد رفعها لسبب من الأسباب الخاصة بها فلا تأثير لذلك في سير الدعوى المدنية المرفوعة معها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,260,0,'bab06d98270166d908e3269fd9dfa1e0','95a50a80f9321fc23fad56cc4fe4e5a6',replace($m208$يجوز للمدعي بالحقوق المدنية أن يترك دعواه في أية حالة كانت عليها الدعوى، ويلزم بدفع المصاريف السابقة على ذلك ،مع عدم الإخلال بحق المتهم في التعويضات إن كان لها وجه.
ولا يكون لهذا الترك تأثير على الدعوى الجنائية ،ومع ذلك إذا كانت الدعوى قد رفعت بطريق الادعاء المباشر فإنه يجب في حالتي ترك الدعوى المدنية واعتبار المدعي بالحقوق المدنية تاركًا دعواه ،الحكم بترك الدعوى الجنائية ما لم تطلب النيابة العامة الفصل فيها.
ويترتب على الحكم بترك الدعوى الجنائية سقوط حق المدعي نفسه في الادعاء مدنيا عن ذات الفعل أمام المحكمة الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,261,0,'7a070431cc490fad654476538831a752','c3072d41ab76f9e58c8a419362099cea',replace($m208$يعتبر تركًا للدعوى عدم حضور المدعي أمام المحكمة بغير عذر مقبول بعد إعلانه لشخصه أو عدم إرساله وكيلا عنه وكذلك عدم إبدائه طلبات بالجلسة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,263,0,'53b44f44550548cbc9d6130c4252ff0d','f432e55a20638e97c02f4489a13e9708',replace($m208$يترتب على ترك المدعي بالحقوق المدنية دعواه أو عدم قبوله مدعيا بحقوق مدنية استبعاد المسئول عن الحقوق المدنية من الدعوى إذا كان دخوله فيها بناء على طلب المدعي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,264,0,'785bf32a3a92f04e9eaf6e8126b81f6d','dc37edc35d2c4a64bf9dd0e56cb95bb2',replace($m208$إذا رفع من ناله ضرر من الجريمة دعواه بطلب التعويض إلى المحكمة المدنية، ثم رفعت الدعوى الجنائية ،جاز له إذا ترك دعواه أمام المحكمة المدنية أن يرفعها إلى المحكمة الجنائية مع الدعوى الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,265,0,'be2f03f0ded4941e4180029743223837','b70e3f1db29ad9b49ff33f1c148cd513',replace($m208$إذا رفعت الدعوى المدنية أمام المحاكم المدنية ،يجب وقف الفصل فيها حتى يحكم نهائيا في الدعوى الجنائية المقامة قبل رفعها ،أو في أثناء السير فيها.
على أنه إذا أوقف الفصل في الدعوى الجنائية لجنون المتهم ،يفصل في الدعوى المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,266,0,'514f05a4d3c44430901d063dff502da3','e3860a5bf21d468b3103e6fb87e07ecd',replace($m208$يتبع في الفصل في الدعوى المدنية التي ترفع أمام المحاكم الجنائية الإجراءات المقررة بهذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,267,0,'f3d4b5af3923e3124ef4f2de4fe60df0','bd2b70f8e0221dbe9bc9b02e6bc6b881',replace($m208$يجوز للمتهم أن يطالب المدعي بالحقوق المدنية أمام المحكمة الجنائية بتعويض الضرر الذي لحقه بسبب رفع الدعوى المدنية عليه إن كان لذلك وجه ،وله كذلك أن يقيم عليه لذات السبب الدعوى المباشرة أمام ذات المحكمة بتهمة البلاغ الكاذب إن كان لذلك وجه ،وذلك بتكليفه مباشرة بالحضور أمامها ،ويجوز الاستغناء عن هذا التكليف إذا حضر المدعي بالحقوق المدنية الجلسة ووجه إليه المتهم التهمة وقبل المحاكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,268,0,'1876c80609b0c26e58a68ed74f0e6f3b','ec56fdf61efb6f8c04dbf1b348ec5b9e',replace($m208$يجب أن تكون الجلسة علنية ،ويجوز للمحكمة مع ذلك مراعاة للنظام العام أو محافظة على الآداب أن تأمر بسماع الدعوى كلها أو بعضها في جلسة سرية ،أو تمنع فئات معينة من الحضور فيها.
ولا يجوز نقل وقائع الجلسات أو بثها بأي طريقة كانت إلا بموافقة كتابية من رئيس الدائرة بعد أخذ رأي النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,269,0,'6e71eb24bb205e0c03361a1e85b094ac','622da78fcc71cfb98566df76ea52973c',replace($m208$يجب أن يحضر أحد أعضاء النيابة العامة جلسات المحاكم الجنائية ،وعلى المحكمة أن تسمع أقواله وتفصل في طلباته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,270,0,'64d11bde32e36c6b803d5d7afb7df9ca','a16a2519588c8b6a4aca7f98fb799fb7',replace($m208$يحضر المتهم الجلسة بغير قيود ولا أغلال ،وتجرى عليه الملاحظة اللازمة.
ولا يجوز إبعاده عن الجلسة أثناء نظر الدعوى إلا إذا وقع منه تشويش يستدعي ذلك ،وفي هذه الحالة تستمر الإجراءات إلى أن يمكن السير فيها بحضوره ،وعلى المحكمة أن تطلعه على ما تم في غيبته من الإجراءات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,271,0,'26cd4fd8be58fa755e566872ea7b1a91','429a5b251f730f238bce1a089d988819',replace($m208$يبدأ التحقيق في الجلسة بالمناداة على الخصوم والشهود ،ويسأل المتهم عن اسمه ولقبه وسنه ومهنته ومحل إقامته ومولده ،وتتلى التهمة الموجهة إليه بأمر الإحالة أو بورقة التكليف بالحضور على حسب الأحوال ،ثم تقدم النيابة والمدعي بالحقوق المدنية إن وجد طلباتهما.
وبعد ذلك يسأل المتهم عما إذا كان معترفًا بارتكاب الفعل المسند إليه ،فإن اعترف جاز للمحكمة الاكتفاء باعترافه والحكم عليه بغير سماع الشهود ،وإلا تسمع شهادة شهود الإثبات ،ويكون توجيه الأسئلة للشهود من النيابة العامة أولاً ،ثم من المجني عليه ،ثم من المدعي بالحقوق المدنية ،ثم من المتهم ،ثم من المسئول عن الحقوق المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,272,0,'79cc3d42d937472d48aa20066726a924','dedacdc934c79f4cd5dc14da24ea732c',replace($m208$بعد سماع شهادة شهود الإثبات يسمع شهود النفي ويسألون بمعرفة المتهم أولاً، ثم بمعرفة المسئول عن الحقوق المدنية ،ثم بمعرفة النيابة العامة ،ثم بمعرفة المجني عليه ،ثم بمعرفة المدعي بالحقوق المدنية وللمتهم والمسئول عن الحقوق المدنية أن يوجها للشهود المذكورين أسئلة مرة ثانية لإيضاح الوقائع التي أدوا الشهادة عنها في أجوبتهم عن الأسئلة التي وجهت إليهم.
ويجوز لكل من الخصوم أن يطلب إعادة سماع الشهود المذكورين لإيضاح أو تحقيق الوقائع التي أدوا شهادتهم عنها ،أو أن يطلب سماع شهود غيرهم لهذا الغرض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,273,0,'5c08670bf67088881086e5a750f9ec84','9988160c83332afcda1eaeee6c5ea128',replace($m208$يجوز للمحكمة في أية حالة كانت عليها الدعوى أن توجه للشهود أي سؤال ترى لزومه لظهور الحقيقة ،أو تأذن للخصوم بذلك.
ويجب عليها منع توجيه أسئلة للشاهد إذا كانت غير متعلقة بالدعوى ،أو غير جائزة القبول ،ويجب عليها أن تمنع عن الشاهد كل كلام بالتصريح أو التلميح وكل إشارة مما ينبني عليه اضطراب أفكاره أو تخويفه.
ويجوز لها أن تمتنع عن سماع شهادة شهود عن وقائع ترى أنها واضحة وضوحا كافيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,274,0,'a3c8107a3bdafd53371e08be2c1b247d','67f87de2c4fb077981dd5fa4ec4f10b1',replace($m208$لا يجوز استجواب المتهم إلا إذا قبل ذلك.
وإذا ظهر أثناء المرافعة والمناقشة بعض وقائع يرى لزوم تقديم إيضاحات عنها من المتهم لظهور الحقيقة ،يلفته القاضي إليها ويرخص له بتقديم تلك الإيضاحات.
وإذا امتنع المتهم عن الإجابة ،أو إذا كانت أقواله في الجلسة مخالفة لأقواله في محضر جمع الاستدلالات أو التحقيق ،جاز للمحكمة أن تأمر بتلاوة أقواله الأولى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,275,0,'dcec53a5408387d0f257df9312b46fa9','77e9e920cfc7e666cc7d3684cade9f5e',replace($m208$بعد سماع شهادة شهود الإثبات وشهود النفي ،يجوز للنيابة العامة وللمتهم ولكل من باقي الخصوم في الدعوى أن يتكلموا.
وفي جميع الأحوال ،يكون المتهم آخر من يتكلم.
ويجوز للمحكمة أن تمنع المتهم أو محاميه من الاسترسال في المرافعة إذا خرج عن موضوع الدعوى أو كرر أقواله بعد التنبيه عليه.
وبعد ذلك تصدر المحكمة قرارها بإقفال باب المرافعة ،ثم تصدر حكمها بعد المداولة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,276,0,'bab51c56c3782c3c1f627ece5f01a587','7ed9a628330c27069bcaeff91b4dd276',replace($m208$يجب أن يحرر محضر بما يجري في جلسة المحاكمة ،ويوقع على كل صفحة منه رئيس المحكمة وكاتبها في اليوم التالي على الأكثر.
ويشتمل هذا المحضر على تاريخ الجلسة ،ويبين به إذا ما كانت علنية أو سرية، وأسماء القضاة والكاتب وعضو النيابة العامة الحاضر بالجلسة وأسماء الخصوم والمدافعين عنهم وشهادة الشهود وأقوال الخصوم ،ويشار فيه إلى الأوراق التي تليت وسائر الإجراءات التي تمت ،وتدون به الطلبات التي قدمت أثناء نظر الدعوى، وما قضي به في المسائل الفرعية ،ومنطوق الأحكام الصادرة ،وغير ذلك مما يجري في الجلسة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,277,0,'c730c9a0d6bbe836352e581a8ea6d163','c6db339beac00d2fd0985fca6ea0d18c',replace($m208$يحكم على وجه السرعة في القضايا الخاصة بالطفل والمرأة والمسنين وذوي الإعاقة والجرائم المنصوص عليها في الأبواب الأول والثاني والثاني مكررا والثالث والرابع والرابع عشر من الكتاب الثاني من قانون العقوبات والجرائم المنصوص عليها في المواد  308 ،307 ،306 ،303 ،302 من قانون العقوبات إذا وقعت بواسطة الصحف والقانون رقم  394 لسنة  1954 في شأن الأسلحة والذخائر.
ويكون تكليف المتهم بالحضور أمام المحكمة في القضايا المبينة بالفقرة الأولى من هذه المادة قبل انعقاد الجلسة بيوم كامل في مواد الجنح وثلاثة أيام كاملة في مواد الجنايات غير مواعيد المسافة المنصوص عليها بقانون المرافعات المدنية والتجارية.
ويجوز أن يكون الإعلان بواسطة أحد المحضرين أو أحد رجال السلطة العامة.
وتنظر القضية في جلسة تعقد في خلال أسبوعين من يوم إحالتها إلى المحكمة المختصة ،وإذا كانت القضية محالة إلى محكمة جنايات أول درجة يقوم رئيس محكمة الاستئناف المختصة بتحديد جلسة في الميعاد المذكور.$m208$,'<<CR>>',chr(13))),
('law',174,2025,278,0,'52edf77f41704f408b74d7c9b33f79b2','ad122b1d93b09af404ddadc76a8f5d1e',replace($m208$يعلن الشاهد لشخصه أو في محل إقامته بالطرق المقررة في هذا القانون ،أو عن طريق الهاتف المحمول أو البريد الإلكتروني المثبت ببيانات رقمه القومي.
ويعلن طلب حضور الشاهد بناء على طلب الخصوم بواسطة أحد المحضرين أو أحد رجال السلطة العامة ،أو بالوسائل الأخرى المنصوص عليها بالفقرة الأولى من هذه المادة ،قبل الجلسة بأربع وعشرين ساعة مع مراعاة مواعيد المسافة المنصوص عليها بقانون المرافعات المدنية والتجارية ،إلا في حال التلبس بالجريمة ،فإنه يجوز طلب حضوره في أي وقت ولو شفهيا بواسطة أحد مأموري الضبط القضائي أو أحد رجال السلطة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,279,0,'d1ff6cc3aa9425bbd02cab396268a19c','f8386d54a76647ed6bfa7d38604af150',replace($m208$ينادى على الشهود بأسمائهم ،وبعد الإجابة منهم يبقون في الغرفة المخصصة لهم، ولا يخرجون منها إلا بالتوالي لتأدية الشهادة أمام المحكمة ،ومن تسمع شهادته منهم يبقى في قاعة الجلسة إلى حين إقفال باب المرافعة ،ما لم ترخص له المحكمة بالخروج ،ويجوز عند الاقتضاء أن يبعد شاهد أثناء سماع شاهد آخر ،وتسوغ مواجهة الشهود بعضهم بعضا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,280,0,'2516c23f4f8294860d1f59fa6359ac88','ef2f319ba9d3ccb0b2b2b7c6ca07c3ea',replace($m208$إذا تخلف الشاهد عن الحضور أمام المحكمة بعد تكليفه به ،جاز الحكم عليه بعد سماع أقوال النيابة العامة بدفع غرامة لا تجاوز خمسمائة جنيه في الجنايات والجنح.
ويجوز للمحكمة إذا رأت أن شهادته ضرورية أن تؤجل الدعوى لإعادة تكليفه بالحضور ،ولها أن تصدر أمرا مسببا بالقبض عليه أو ضبطه وإحضاره.$m208$,'<<CR>>',chr(13))),
('law',174,2025,281,0,'a64c2eb4683d8eac2029bd2b3ae72556','2b4f5ca324052208ba24a014a87fedec',replace($m208$إذا حضر الشاهد بعد تكليفه بالحضور مرة أخرى أو من تلقاء نفسه وأبدى أعذارا مقبولة ،جاز إعفاؤه من الغرامة بعد سماع أقوال النيابة العامة.
وإذا لم يحضر الشاهد في المرة الأخرى ،جاز الحكم عليه بغرامة لا تجاوز ألفى جنيه ،وللمحكمة أن تصدر أمرا مسببا بالقبض عليه أو ضبطه وإحضاره في نفس الجلسة ،أو في جلسة أخرى تؤجل إليها الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,282,0,'42b2e67cbaef0f3a5b6d46381e55c1bd','e069f9807b9939ea251a72a215cb5be1',replace($m208$يجوز للمحكمة إذا اعتذر الشاهد بأعذار مقبولة عن عدم إمكانه الحضور أن تنتقل إليه وتسمع شهادته بعد إخطار النيابة العامة وباقي الخصوم ،وللخصوم أن يحضروا بأنفسهم أو بواسطة وكلائهم وأن يوجهوا للشاهد الأسئلة التي يرون لزوم توجيهها إليه.
وإذا انتقلت المحكمة إلى الشاهد وتبين لها عدم صحة العذر جاز لها أن تحكم عليه بالحبس مدة لا تجاوز ثلاثة شهور وبغرامة لا تجاوز ألفى جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,283,0,'fb94c71662dea6b684e30325dcd803bd','3af2f71691eee68972ebab300942a5ea',replace($m208$إذا لم يحضر الشاهد أمام المحكمة حتى صدور الحكم في الدعوى ،جاز له الطعن في حكم الغرامة أمام المحكمة التي أصدرته ،في هيئة مغايرة ،إذا حال دون حضوره لإبداء شهادته عذر قهري.
ويجوز للشهود الطعن في الأحكام الصادرة بالحبس أو الغرامة أمام المحكمة التي أصدرته ،في هيئة مغايرة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,284,0,'c4b8f8743cfa20724c95d67dc212cddb','d9f310ed22afc829ee89bece2eb7b7c5',replace($m208$يجب على الشاهد الذي بلغ خمس عشرة سنة أن يحلف قبل أداء الشهادة اليمين الآتية" :أقسم باالله العظيم أن أشهد بالحق" ،ويكون الحلف على حسب الأوضاع الخاصة بديانته إن طلب ذلك.
ويجوز سماع الشهود الذين لم يبلغوا خمس عشرة سنة كاملة دون حلف يمين على سبيل الاستدلال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,285,0,'3ba70a1db9e3e89fcc96d21e3ffe3970','c5869fd60b674cf3a0912482a5a5dd14',replace($m208$إذا امتنع الشاهد عن أداء اليمين أو عن الإجابة في غير الأحوال التي يجيز له القانون فيها ذلك ،حكم عليه في مواد الجنايات والجنح بغرامة لا تجاوز ألفى جنيه.
وإذا عدل الشاهد عن امتناعه قبل إقفال باب المرافعة يعفى من العقوبة المحكوم بها عليه كلها أو بعضها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,287,0,'d60958c97c1fc4020745a73ac75dd201','6a9b8cc491290f122d15a34ce9d19229',replace($m208$يجوز أن يمتنع عن أداء الشهادة ضد المتهم أصوله وفروعه وأقاربه وأصهاره إلى الدرجة الثانية وزوجه ولو بعد انقضاء رابطة الزوجية ،وذلك ما لم تكن الجريمة قد وقعت على الشاهد أو على أحد أقاربه أو أصهاره الأقربين ،أو إذا كان هو المبلغ عنها ،أو إذا لم تكن هناك أدلة إثبات أخرى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,288,0,'8625bcf1acaab95c8bc0cbcd09daa933','3d64d9f0dc6b1e611303c68ec68140a8',replace($m208$تسري أمام المحاكم الجنائية القواعد المقررة في قانون الإثبات في المواد المدنية والتجارية لمنع الشاهد عن أداء الشهادة أو لإعفائه من أدائها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,290,0,'15395be66190261e4b5cd21fe1f227f3','75eca57b1cc6fa36a045b3c3ff7403f3',replace($m208$يجوز للمحكمة أن تقرر تلاوة الشهادة التي أبديت في التحقيق الابتدائي أو في محضر جمع الاستدلالات أو أمام الخبير إذا تعذر سماع الشاهد لأي سبب من الأسباب ،فإذا تمسك الدفاع بسماع أقوال شاهد الإثبات ،ولم تر المحكمة ضرورة لذلك كان عليها أن تُضمن حكمها سبب الرفض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,291,0,'f94c325fb874cdb79488fff8ecfb855c','1c1be43087d00f6ccd615182fc684be7',replace($m208$إذا قرر الشاهد أنه لم يعد يذكر واقعة من الوقائع يجوز أن يتلى من شهادته التي أقرها في التحقيق أو من أقواله في محضر جمع الاستدلالات ،الجزء الخاص بهذه الواقعة.
وكذلك الحال إذا تعارضت شهادة الشاهد التي أداها في الجلسة مع شهادته أو أقواله السابقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,292,0,'117e39424508c0c488caf326691826f0','2bc4f95638015952f5860ed9bd834344',replace($m208$يجوز للمحكمة أن تأمر ،ولو من تلقاء نفسها أثناء نظر الدعوى ،بتقديم أي دليل تراه لازما لظهور الحقيقة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,293,0,'ae0f87f8a4da282120f3b97c6050a937','f1272e9abe5edd26db73f1c6f0ba651a',replace($m208$يجوز للمحكمة سواء من تلقاء نفسها أو بناء على طلب الخصوم أن تعين خبيرا واحدا أو أكثر في الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,294,0,'b37174dc5f336bc3e77bc22f8b462ee9','ecebd9df52ae77627bc824db4d064b5a',replace($m208$يجوز للمحكمة من تلقاء نفسها ،أو بناء على طلب الخصوم ،أن تأمر بإعلان الخبراء ليقدموا إيضاحات بالجلسة عن التقارير المقدمة منهم في التحقيق الابتدائي أو أمام المحكمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,295,0,'c7b547a534c9c4184993045dc7ec1df0','351fe84e07d6ec787867e7702eee07cb',replace($m208$إذا تعذر تحقيق دليل أمام المحكمة ،جاز لها أن تندب أحد أعضائها أو قاضيا آخر لتحقيقه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,296,0,'ac621224a331357ebed8f5d38ab1ab11','1c054c569586f6fed432975742a49e9f',replace($m208$يجوز للنيابة العامة ولجميع الخصوم ،في أية حالة كانت عليها الدعوى، أن يطعنوا بالتزوير في أية ورقة من أوراق القضية مقدمة فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,297,0,'b0b75ce2c70620349f56f7e84f488ee2','eb4f50498900632362acb46cd8eb97de',replace($m208$يحصل الطعن بتقرير في قلم كتاب المحكمة المنظورة أمامها الدعوى ،ويقدم الطعن من الخصم نفسه أو وكيله إذا أرفق بطعنه توكيلاً خاصا بالادعاء بالتزوير، أو إقرارا كتابيا موثقًا من الخصم مبينًا فيه الأوراق المطعون فيها.
ويجب أن يعلن مدعي التزوير خصمه في الثمانية الأيام التالية للتقرير بمذكرة تحدد فيها الورقة المطعون فيها بالتزوير والأدلة على تزويرها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,298,0,'50c47cfaf1d1c0ec8653bff2b0fcd06c','d1be5ee50e8daa6c7c1395a7371d4419',replace($m208$إذا رأت المحكمة المنظور أمامها الدعوى وجها للسير في تحقيق الادعاء بالتزوير ،وكان الفصل في الدعوى المنظورة أمامها يتوقف على الورقة المطعون فيها ،تحقق المحكمة الواقعة بنفسها ،ومع ذلك يجوز لها إذا تعذر عليها ذلك أن تحيل الأوراق إلى النيابة العامة ،وفي هذه الحالة توقف الدعوى إلى أن يفصل في الادعاء بالتزوير.
وإذا تبين للمحكمة أن الورقة المطعون فيها مزورة تفصل في الدعوى وتحيل الواقعة للنيابة العامة لاتخاذ شئونها فيها.
وفي حالة عدم وجود تزوير تقضي المحكمة بإلزام مدعي التزوير بغرامة لا تجاوز عشرة آلاف جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,299,0,'5577701ab8295d3da5ddee2678fb94ae','3e5334ae06b4361e505a3643510b952c',replace($m208$كل من ادعى بسوء نية تزوير محرر مقدم أمام إحدى المحاكم وحكم نهائيا بعدم صحة هذا الادعاء ،يتعين على المحكمة مصدرة الحكم النهائي بعدم صحة الادعاء بالتزوير أن تحيل الواقعة للنيابة العامة لاتخاذ شئونها حيالها.
ويعاقب المدعي بتزوير المحرر بالعقوبة المقررة في الفقرة الثانية من المادة 303 من قانون العقوبات.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,300,0,'c3fbf28514d8a30f132d29ae1adc5d1c','30732df40e5f948f3a54f8f50df0328b',replace($m208$إذا حكم بتزوير ورقة رسمية كلها أو بعضها ،تأمر المحكمة التي حكمت بالتزوير بإلغائها أو تصحيحها حسب الأحوال ،ويحرر بذلك محضر يؤشر على الورقة بمقتضاه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,301,0,'2c9a575f46bdd131c127005fecfa98eb','0708e59d4fc369ba0777a6e615a3108a',replace($m208$لا تتقيد المحكمة بما هو مدون في التحقيق الابتدائي ،أو في محاضر جمع الاستدلالات ،ما لم ينص القانون على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,302,0,'03945c4ec97388ca7b5e99d9a3fd049e','4b074e6bde8f042d4e25be792131a89d',replace($m208$تعتبر المحاضر المحررة في مواد المخالفات حجة بالنسبة للوقائع التي يثبتها مأمور الضبط القضائي إلى أن يثبت ما ينفيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,303,0,'227974c076c97e7592d4c800dfe9df26','0dc74042badd2d25962a23303a814b83',replace($m208$يحكم القاضي في الدعوى حسب العقيدة التي تكونت لديه بكامل حريته ولا يجوز له أن يبني حكمه على أي دليل لم يطرح أمامه في الجلسة ،وكل قول يثبت أنه صدر من أحد المتهمين أو الشهود تحت وطأة الإكراه أو التهديد به يهدر ولا يعول عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,304,0,'8b0c69fdc445e282df159c64713f2a9b','39022781fa0a2c5141bc040972bddbb9',replace($m208$يصدر الحكم في الجلسة العلنية ولو كانت الدعوى نظرت في جلسة سرية ،ويجب إثباته في محضر الجلسة ،ويوقع عليه رئيس المحكمة والكاتب.
ويجوز للمحكمة أن تأمر باتخاذ الوسائل اللازمة لمنع المتهم من مغادرة قاعة الجلسة قبل النطق بالحكم أو لضمان حضوره في الجلسة التي يؤجل لها الحكم، ولو كان ذلك بإصدار أمر مسبب بحبسه إذا كانت الواقعة مما يجوز فيها الحبس الاحتياطي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,305,0,'d4fa3390285cc4c55d42f20ade2bdc25','32f63c40674ba5113b33f24b1eb042d3',replace($m208$إذا كانت الواقعة غير ثابتة أو كان القانون لا يعاقب عليها ،تحكم المحكمة ببراءة المتهم ويفرج عنه إن كان محبوسا من أجل هذه الواقعة وحدها.
أما إذا كانت الواقعة ثابتة وتكون فعلا معاقبا عليه ،تقضي المحكمة بالعقوبة المقررة في القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,306,0,'95bd4599ed407d6fbd04c5885229016d','55e064be278efcc13e5c23ce4242e41a',replace($m208$إذا تبين للمحكمة الجزئية أن الواقعة جناية أو أنها جنحة من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد تحكم بعدم اختصاصها وتحيلها إلى النيابة العامة لاتخاذ ما يلزم فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,307,0,'8828b2c564df3ff5aff633159701622a','779478325bcbd52fe01d4450e8de5151',replace($m208$لا تجوز معاقبة المتهم عن واقعة غير التي وردت بأمر الإحالة أو طلب التكليف بالحضور ،كما لا يجوز الحكم على غير المتهم المقامة عليه الدعوى.
وإذا تبين للمحكمة أن المتهم المعروض ليس هو مرتكب الواقعة وأن المتهم الحقيقي معروف ،فلها أن تحيل الأوراق للنيابة العامة لاتخاذ شئونها نحو المتهم الحقيقي دون العرض عليها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,308,0,'cd7d8164a25296990ae69aea267ab7df','8b134f7dcdb6ef2b0fde100f35fa2e98',replace($m208$يجوز للمحكمة أن تغير في حكمها الوصف القانوني للفعل المسند للمتهم ،ولها تعديل التهمة بإضافة الظروف المشددة التي تثبت من التحقيق أو من المرافعة في الجلسة ،ولو كانت لم تذكر بأمر الإحالة أو بالتكليف بالحضور.
ولها أيضا إصلاح كل خطأ مادي وتدارك كل سهو في عبارة الاتهام مما يكون في أمر الإحالة ،أو في طلب التكليف بالحضور.
ويجب على المحكمة أن تنبه المتهم إلى هذا التغيير ،وأن تمنحه أجلاً لتحضير دفاعه بناء على الوصف أو التعديل الجديد إذا طلب ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,309,0,'a4dd125738dd5a39449355a0b81804f0','cdd59eaa35885ef69595f3f8a2a1a90c',replace($m208$كل حكم يصدر في موضوع الدعوى الجنائية يجب أن يفصل في التعويضات التي يطلبها المدعي بالحقوق المدنية أو المتهم ،وكذلك في الدعوى المباشرة التي يقيمها المتهم على المدعي بالحقوق المدنية طبقًا للمادة  267 من هذا القانون.
ومع ذلك إذ رأت المحكمة أن الفصل في التعويضات يستلزم إجراء تحقيق خاص ينبني عليه إرجاء الفصل في الدعوى الجنائية ،فعندئذ تحيل المحكمة الدعوى المدنية إلى المحكمة المختصة بلا مصروفات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,310,0,'d3955d89e69c3b7e20c2c9be0ebadd4c','fdfb4aee4215071fec86e740b65d5f4d',replace($m208$يجب أن يشتمل الحكم على الأسباب التي بني عليها ،وكل حكم بالإدانة يجب أن يشتمل على بيانات المحكوم عليه بما فيها الرقم القومي وبيان الواقعة المستوجبة للعقوبة والظروف التي وقعت فيها ،وأن يشير إلى نص القانون الذي حكم بموجبه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,311,0,'3245a5942f18b648c733e0f8a2a576ce','d02760955dfc622534bc69732cdc77d5',replace($m208$يجب على المحكمة أن تفصل في الطلبات التي تقدم لها من الخصوم ،وتبين الأسباب التي تستند إليها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,312,0,'939d4eb8f71b65138c4e501eb3d86cd6','b5c6c037b6ab13b950489703a6a4f65e',replace($m208$يحرر الحكم بأسبابه كاملاً خلال ثمانية أيام من تاريخ صدوره قدر الإمكان، ويوقع عليه رئيس المحكمة وكاتبها ،وإذا حصل مانع للرئيس يوقعه أحد القضاة الذين اشتركوا معه في إصداره ،وإذا كان الحكم صادرا من المحكمة الجزئية وكان القاضي الذي أصدره قد وضع أسبابه بنفسه سواء بخطه أو بإحدى الوسائل الإلكترونية ،يجوز لرئيس المحكمة الابتدائية أن يوقع بنفسه على نسخة الحكم الأصلية أو يندب أحد القضاة للتوقيع عليها بناء على تلك الأسباب.
فإذا لم يكن القاضي قد كتب الأسباب بنفسه يبطل الحكم لخلوه من الأسباب.
ولا يجوز تأخير توقيع الحكم عن الثمانية الأيام المقررة إلا لأسباب قوية ،وعلى كل حال يبطل الحكم إذا مضى ثلاثون يوما دون حصول التوقيع ما لم يكن صادرا بالبراءة ،وعلى قلم كتاب المحكمة التي أصدرت الحكم أن يعطي صاحب الشأن بناء على طلبه شهادة بعدم توقيع الحكم في الميعاد المذكور.$m208$,'<<CR>>',chr(13))),
('law',174,2025,313,0,'b5d8c2e46c7dc2da445f372e7366860a','514a3773e238c2cb90fe6ff7b039632c',replace($m208$تلتزم النيابة العامة بنشر كل حكم بات ببراءة من سبق حبسه احتياطيا ،وكذلك كل أمر صادر بأن لا وجه لإقامة الدعوى الجنائية قبله في جريدتين يوميتين واسعتي الانتشار على نفقة الحكومة ،ويكون النشر في الحالتين بناء على طلب النيابة العامة أو المتهم أو أحد ورثته وبموافقة النيابة العامة في حالة صدور أمر بأن لا وجه لإقامة الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,315,0,'21129b76be504454d324b2e828dfa8c5','53362c7eadbe62ce1e6cd59815ce1674',replace($m208$إذا حكم في الاستئناف بتأييد الحكم الابتدائي ،جاز إلزام المتهم المستأنف بكل مصاريف الاستئناف أو بعضها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,316,0,'49967c4d32afb0fc68f2eb9fea48190d','2898d3ae89aed2d7a55d78e8e6ceb72d',replace($m208$يجوز لمحكمة النقض أن تحكم بمصاريف الطعن كلها أو بعضها على المتهم المحكوم عليه إذا لم يقبل طلبه أو إذا رفض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,317,0,'da8c5c987008c8880ebc8b78628fc5b3','eb875549aa1f3d9d121f01641a20665d',replace($m208$إذا حكم على عدة متهمين بحكم واحد لجريمة واحدة ،فاعلين كانوا أو شركاء، فالمصاريف التي يحكم بها تحصل منهم بالتساوي ،ما لم يقض الحكم بتوزيعها بينهم على خلاف ذلك ،أو إلزامهم بها متضامنين.$m208$,'<<CR>>',chr(13))),
('law',174,2025,318,0,'54c91e5884ef2abb5bf2b846b391b5d9','37a7d1492093d3921ac916a2f1132926',replace($m208$إذا لم يحكم على المتهم بكل المصاريف وجب أن يحدد في الحكم مقدار ما يحكم به عليه منها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,319,0,'350f0e8b0b1001ca4687491e19055df4','788517e4dd809e94c1309937eedd7c7b',replace($m208$يكون المدعي بالحقوق المدنية ملزما بأداء مصاريف الدعوى للدولة ،ويتبع في تقدير المصاريف وكيفية تحصيلها ما هو وارد في قانون الرسوم القضائية ولوائحه وقراراته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,320,0,'851f56b0bacd74b22a61e5b4791a6ad6','7bb606dc05f17d229b58daf00dee7fef',replace($m208$إذا حكم بإدانة المتهم في الجريمة وجب الحكم عليه للمدعي بالحقوق المدنية بالمصاريف التي تحملها ،وللمحكمة مع ذلك أن تخفض مقدارها إذا رأت أن بعض هذه المصاريف كان غير لازم.
وإذا لم يحكم للمدعي بالحقوق المدنية بتعويضات تكون عليه المصاريف التي استلزمها دخوله في الدعوى ،أما إذا قضي له ببعض التعويضات التي طلبها يجوز تقدير هذه المصاريف على نسبة تبين في الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,321,0,'40f2c2984f21978d0af789931ab5e8bf','8196206d2abba4df78e07fe9e5e68fa8',replace($m208$يعامل المسئول عن الحقوق المدنية معاملة المتهم فيما يختص بمصاريف الدعوى المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,322,0,'25ccfdf73d668358ec2dca779a52bc6c','f7c9ebdc67661228b2065cb5bb053cb7',replace($m208$إذا حكم على المتهم بمصاريف الدعوى الجنائية كلها أو بعضها وجب إلزام المسئول عن الحقوق المدنية معه بما حكم به ،وفي هذه الحالة تحصل المصاريف المحكوم بها من كل منهما بالتضامن.$m208$,'<<CR>>',chr(13))),
('law',174,2025,323,0,'1b11330964abfa5107aa83a98bb6becc','5eae51167e193549d9680398220d3360',replace($m208$يجوز للنيابة العامة في مواد الجنح التي لا يوجب القانون الحكم فيها بعقوبة الحبس ،إذا رأت أن الجريمة بحسب ظروفها تكفي فيها عقوبة الغرامة فضلاً عن العقوبات التكميلية والتضمينات وما يجب رده والمصاريف ،أن تطلب من قاضي المحكمة الجزئية التي من اختصاصها نظر الدعوى توقيع العقوبة على المتهم بأمر جنائى يصدره بناء على محضر جمع الاستدلالات أو أدلة الإثبات الأخرى بغير إجراء تحقيق أو سماع مرافعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,324,0,'b28cf1db24bbb5d152922a56ad42d329','98d9aafc9622b30d6146d5bc097339a0',replace($m208$يجوز للقاضي من تلقاء نفسه عند نظر إحدى الجنح المبينة في المادة 323 من هذا القانون أن يصدر فيها أمرا جنائيا ،وذلك إذا تغيب المتهم عن الحضور رغم إعلانه ،ولم تكن النيابة العامة قد طلبت توقيع أقصى عقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,325,0,'fad8199885100725bd7fc334bd11a8c7','6b2589d4659e5aa47c09044f152ff00b',replace($m208$لا يقضى في الأمر الجنائي بغير الغرامة والعقوبات التكميلية والتضمينات وما يجب رده والمصاريف ،ويجوز أن يقضى فيه بالبراءة أو برفض الدعوى المدنية أو بوقف تنفيذ العقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,326,0,'421df10dd6e8d5f7048e243aa530da8e','f4e5edc2807d1d6410613e6857d3bbb1',replace($m208$يرفض القاضي إصدار الأمر إذا رأى: )أولاً( إنه لا يمكن الفصل في الدعوى بحالتها التي هي عليها أو دون تحقيق أو مرافعة.
)ثانيا( أن الواقعة نظرا لسوابق المتهم أو لأي سبب آخر تستوجب توقيع عقوبة أشد من الغرامة التي يجوز صدور الأمر بها.
ويصدر القاضي قراره بالرفض بتأشير على الطلب الكتابي المقدم له ولا يجوز الطعن في هذا القرار.
ويترتب على قرار الرفض إعادة الأوراق للنيابة العامة لاتخاذ ما يلزم فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,327,0,'5654d2bb976d7bb5ef2aa1bfaeb1ab61','76df10003048dd0040889f1d0c9f86f3',replace($m208$يجوز لكل عضو نيابة عامة من درجة وكيل نيابة على الأقل بالمحكمة التي من اختصاصها نظر الدعوى أن يصدر الأمر الجنائي في الجنح التي لا يوجب القانون الحكم فيها بالحبس أو الغرامة التي يزيد حدها الأدنى على عشرين ألف جنيه فضلاً عن العقوبات التكميلية والتضمينات وما يجب رده والمصاريف.
ولا يجوز أن يؤمر بغير الغرامة التي لا يزيد حدها الأقصى على عشرين ألف جنيه والعقوبات التكميلية والتضمينات وما يجب رده والمصاريف ،ويكون إصدار الأمر الجنائي وجوبيا في المخالفات وفي الجنح المعاقب عليها بالغرامة وحدها التي لا يزيد حدها الأقصى على خمسة آلاف جنيه ،والتي لا يرى حفظها.
وللمحامي العام ولرئيس النيابة ،حسب الأحوال ،خلال خمسة عشر يوما من تاريخ صدور الأمر الجنائي ،أن يأمر بتعديله أو بإلغائه وحفظ الأوراق والتقرير في الدعوى بأن لا وجه لإقامتها أو رفعها إلى المحكمة المختصة والسير في الدعوى الجنائية بالطرق العادية ،ولا يجوز إعلان الأمر للخصوم قبل انقضاء هذه المدة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,328,0,'d21042b71acf076663f238a91fd8e2ea','cd8c3cedd6f4e6cb0dd1b33e9aa3cddf',replace($m208$يجب أن يعين في الأمر فضلاً عما قضى به اسم المتهم كاملاً ،ورقمه القومي أو رقم وثيقة سفره ،وموطنه إن كان أجنبيا ،والواقعة التي عوقب من أجلها ،ومادة القانون التي طبقت.
ويعلن الأمر على النموذج الذي يقرره وزير العدل إلى المتهم والمدعي بالحقوق المدنية ،ويجوز أن يكون الإعلان بواسطة أحد رجال السلطة العامة ،كما يجوز الإعلان عن طريق الهاتف المحمول أو البريد الإلكتروني المثبت ببيانات الرقم القومى بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,329,0,'be75e924e68357b9bb82954b9f6fd94b','0bb8bffb809f2eeb9b00d4f02bb1aad5',replace($m208$للنيابة العامة أن تعلن عدم قبولها الأمر الجنائي الصادر من القاضي ،ولباقي الخصوم أن يعلنوا عدم قبولهم للأمر الصادر من القاضي أو من النيابة العامة ،ويكون ذلك بتقرير بقلم كتّاب محكمة الجنح المستأنفة فيما يتعلق بالأمر الصادر من القاضي طبقًا للمادة  324 من هذا القانون ،وبتقرير بقلم كتّاب محكمة الجنح في غير هذه الحالات ،وذلك كله خلال عشرة أيام من تاريخ صدور الأمر بالنسبة للنيابة العامة، ومن تاريخ إعلانه بالنسبة لباقي الخصوم.
وللنائب العام أن يعلن عدم قبوله الأمر الصادر من القاضي في ميعاد ثلاثين يوما من وقت صدور الأمر ،وله أن يقرر عدم القبول في قلم كتاب محكمة الجنح المستأنفة المختصة.
ويترتب على هذا التقرير سقوط الأمر واعتباره كأن لم يكن.
ويحدد الكاتب وقت تقديم التقرير اليوم الذي تنظر فيه الدعوى أمام المحكمة، مع مراعاة المواعيد المقررة في المادة  229 من هذا القانون ،ويخطر الخصوم أو وكلاؤهم بتاريخ الجلسة المحددة ويعد هذا الإخطار بمثابة إعلان بميعادها، ويكلف باقي الخصوم والشهود بالحضور في الميعاد المحدد.
أما إذا لم يحصل اعتراض على الأمر بالطريقة المتقدمة يصبح نهائيا واجب التنفيذ.
ولا يكون لما قضى به الأمر في موضوع الدعوى الجنائية حجية أمام المحاكم المدنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,330,0,'6d6df62bd9776ab613b971095f5946f6','d2f177e804e6e8e0f3e7a0f72efb5262',replace($m208$إذا حضر الخصم الذي لم يقبل الأمر الجنائي في الجلسة المحددة تنظر الدعوى في مواجهته وفقًا للإجراءات العادية.
أما إذا لم يحضر تعود للأمر قوته ويصبح نهائيا واجب التنفيذ.
وفي جميع الأحوال ،لا يجوز أن يضار المعترض باعتراضه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,331,0,'13e982701a8b29e8276189178126662a','026c3c2a9d5eed9179a4bb131c33e984',replace($m208$إذا تعدد المتهمون وصدر ضدهم أمر جنائي وقرروا عدم قبوله وحضر بعضهم في اليوم المحدد لنظر الدعوى ولم يحضر البعض الآخر تنظر الدعوى بالطرق المعتادة بالنسبة لمن حضر ويصبح الأمر نهائيا واجب التنفيذ بالنسبة لمن لم يحضر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,332,0,'58a562a51af2f44d07e2d248ac50bfeb','721ea3a554ac285cc71bca4f71be3556',replace($m208$إذا ادعى المتهم عند التنفيذ عليه أن حقه في عدم قبول الأمر الجنائى لا يزال قائما لعدم إعلانه بالأمر أو لغير ذلك من الأسباب ،أو أن مانعا قهريا منعه من الحضور في الجلسة المحددة لنظر الدعوى ،أو إذا حصل إشكال آخر في التنفيذ ،يقدم الإشكال إلى القاضي المختص ليفصل فيه بغير مرافعة ،إلا إذا رأى عدم إمكان الفصل فيه بحالته أو دون تحقيق أو مرافعة ،يحدد يوم لينظر في الإشكال وفقًـا للإجراءات العادية ،ويكلف المتهم وباقي الخصوم بالحضور في اليوم المذكور ،فإذا قبل الإشكال تجرى المحاكمة وفقًا للمادة  330 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,334,0,'202217b65d61a750c25060acb9901cc2','27c3a19b60e75438c13d9bf0158e7146',replace($m208$إذا كان البطلان راجعا لعدم مراعاة أحكام القانون المتعلقة بتشكيل المحكمة أو بولايتها بالحكم في الدعوى أو باختصاصها من حيث نوع الجريمة المعروضة عليها أو بالحرية الشخصية أو حرمة المسكن أو حرية الحياة الخاصة أو بغير ذلك مما هو متعلق بالنظام العام جاز التمسك به في أية حالة كانت عليها الدعوى ،وتقضي به المحكمة ولو بغير طلب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,335,0,'8bab5638c06a85e939ee8dd42d2554e2','cef461fa0f9ee00f456362c5b9ff324a',replace($m208$في غير الأحوال المشار إليها في المادة  334 من هذا القانون ،يسقط الحق في الدفع ببطلان الإجراءات الخاصة بجمع الاستدلالات أو التحقيق الابتدائي أو التحقيق بالجلسة في الجنح والجنايات إذا كان للمتهم محام وحصل الإجراء بحضوره دون اعتراض منه.
أما في مواد المخالفات فيعتبر الإجراء صحيحا إذا لم يعترض عليه المتهم.
وكذلك يسقط حق الدفع بالبطلان بالنسبة للنيابة العامة إذا لم تتمسك به في حينه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,336,0,'462ca3debeee63078c5d1e0c295faf3f','dc7d609684f15f79765a337324db67db',replace($m208$إذا حضر المتهم في الجلسة بنفسه أو بواسطة وكيل عنه ،فليس له أن يتمسك ببطلان ورقة التكليف بالحضور ،وإنما له أن يطلب تصحيح التكليف أو استيفاء أي نقص فيه وإعطاءه ميعادا لتحضير دفاعه قبل البدء في نظر الدعوى ،وعلى المحكمة إجابته إلى طلبه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,338,0,'45a61f485fecf57a0fed554e3f3f92f7','239765d28ac46760d25811384bedc0ea',replace($m208$إذا تقرر بطلان أي إجراء ،فإنه يتناول جميع الآثار التي تترتب عليه مباشرة، ولزم إعادته متى أمكن ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,339,0,'37ad9927947d2927c1f67554bb248424','47eb3c08933dfbbf8c04dea650de98ff',replace($m208$إذا وقع خطأ مادي في حكم أو في أمر صادر من جهات التحقيق أو المحاكمة ولم يكن يترتب عليه البطلان ،تتولى الجهة التي أصدرت الحكم أو الأمر تصحيح الخطأ من تلقاء نفسها أو بناء على طلب أحد الخصوم وذلك بعد تكليفهم بالحضور.
ويقضى بالتصحيح في غرفة المشورة بعد سماع أقوال الخصوم ،ويؤشر بالأمر الذي يصدر على هامش الحكم أو الأمر.
ويتبع هذا الإجراء في تصحيح اسم المتهم ولقبه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,340,0,'6b3822e06897668ea3e49c6328fc8fb8','6b1c3babd9ba335a5ac04810f0053d20',replace($m208$إذا استلزم التحقيق في جناية أو جنحة معاقب عليها بالحبس مدة لا تقل عن سنة فحص حالة الاضطراب النفسي أو العقلي للمتهم ،ومدى تأثيرها على إدراكه واختياره، تعين عرض الأوراق والمتهم بناء على طلب النيابة العامة أو قاضي التحقيق بحسب الأحوال على القاضي الجزئي ،للأمر بإيداع المتهم تحت الملاحظة في إحدى منشآت الصحة النفسية الحكومية ،والتي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية ،لمدة أو مدد لا يزيد مجموعها عن خمسة وأربعين يوما ،وتكليف المجلس الإقليمي للصحة النفسية المختص بانتداب لجنة ثلاثية من الأطباء النفسيين المقيدين لديه لفحصه ،وإعداد تقرير طبي يتضمن تقييما لحالته النفسية والمرضية وقت ارتكاب الجريمة ،ووقت إجراء التقييم والخطة العلاجية المقترحة ،حال ثبوت إصابته باضطراب نفسي أو عقلي.
ويجوز للمحكمة مد مدة الإيداع تحت الملاحظة لمدة أو مدد أخرى بناء على طلب المجلس الإقليمي للصحة النفسية المختص على ألا يزيد مجموع مدة الإيداع في جميع الأحوال بالمنشأة على ثلاثة أشهر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,341,0,'80999dfd86415ce48ffcc84cfa2b3705','35e4a2066d53cb44ebc067031f720b80',replace($m208$يجوز للنيابة العامة والمتهم ولكل ذي شأن استئناف أمر الإيداع تحت الملاحظة المشار إليه في المادة  340 من هذا القانون أو قرار رفض إصداره أو مد مدته بموجب تقرير استئناف يودع لدى النيابة المختصة خلال ثمان وأربعين ساعة من تاريخ صدوره ،وينظر الاستئناف أمام محكمة الجنح المستأنفة منعقدة في غرفة المشورة ،وتفصل فيه خلال اثنتين وسبعين ساعة على الأكثر من تاريخ التقرير به، ويبدأ تنفيذ الأمر من تاريخ فوات المدة المقررة للاستئناف أو الفصل فيه من المحكمة.
ويعتبر أمر الإيداع المشار إليه بمثابة أمر حبس احتياطي يتعين خصم مدته من مدة العقوبة المقضي بها على المتهم إذا ثبتت سلامته من أي اضطراب نفسي أو عقلي ،وينتهي الأمر بقوة القانون بانتهاء مدته دون مده أو من اليوم التالي لإخطار النيابة المختصة أو قاضي التحقيق بحسب الأحوال بإعداد التقرير الطبي النفسي الخاص بالمتهم ،قبل انتهاء المدة المحددة للحجز ،ويتعين على النيابة المختصة أو قاضي التحقيق الأمر بإيداع المتهم مؤقتًا بإحدى منشآت الصحة النفسية الحكومية، والتي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية إذا ثبت إصابته باضطراب نفسي أو عقلي دون حضوره لحين التصرف في الأوراق ،أو حبسه احتياطيا أو مد حبسه احتياطيا وفقًا لأحكام الحبس الاحتياطي المنصوص عليها في هذا القانون أو الإفراج عنه إذا ثبت سلامته من أي اضطراب نفسي أو عقلي.
ويكون إصدار الأمر المشار إليه في المادة  340 من هذا القانون للمحكمة المنظورة أمامها الدعوى ،بعد سماع أقوال النيابة العامة والمدافع عن المتهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,342,0,'5771ef9a5b633d905c78436e7f8e18fc','1db50e5ea22863361735636afb9ab913',replace($m208$يجوز للنيابة العامة في الجنح المعاقب عليها بالغرامة وحدها أو الحبس الذي تقل مدته عن سنة واحدة ،وفي المخالفات ندب أحد الأطباء النفسيين المقيدين بسجلات المجلس الإقليمي للصحة النفسية لفحص المتهم ،وتقرير ما إذا كانت حالته تستدعي الدخول الإلزامي لإحدى منشآت الصحة النفسية ،خلال مدة لا تزيد عن ثمان وأربعين ساعة ،فإذا ثبت إصابة المتهم باضطراب نفسي أو عقلي تأمر النيابة العامة بنقله إلى إحدى منشآت الصحة النفسية ،واتخاذ إجراءات دخوله وعلاجه إلزاما وفقًا للضوابط الواردة في قانون رعاية المريض النفسي الصادر بالقانون رقم  71 لسنة  ،2009 ويتم التصرف في الأوراق في ضوء ذلك.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,343,0,'92f1561ef9049e22151d4a6922ed030d','949be9cdf6166be984d60c4163c8710c',replace($m208$إذا ثبت من التقرير الطبي النفسي أن المتهم غير قادر على الدفاع عن نفسه، بسبب اضطراب نفسي أو عقلي ،طرأ بعد وقوع الجريمة ،يوقف رفع الدعوى عليه أو محاكمته حتى يعود إليه رشده.
ويجوز في هذه الحالة لمحكمة الجنح المستأنفة منعقدة في غرفة المشورة بناء على طلب النيابة العامة أو قاضي التحقيق بحسب الأحوال ،أو المحكمة المنظورة أمامها الدعوى ،إذا كانت الواقعة جناية أو جنحة عقوبتها الحبس مدة لا تقل عن سنة إصدار الأمر بإيداع المتهم في إحدى منشآت الصحة النفسية الحكومية ،والتي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية ،لتلقي العلاج والرعاية الطبية إلى أن يتقرر إخلاء سبيله ،وفي جميع الأحوال تخصم مدة الإيداع من مدة العقوبة التي يقضي بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,344,0,'09b5be30b311ee616fe851dad8c63b5c','6f9c97c4f9ebf4b23269bde6c4400c29',replace($m208$لا يحول إيقاف الدعوى الجنائية لإصابة المتهم باضطراب نفسي أو عقلي دون اتخاذ إجراءات التحقيق التي يرى أنها مستعجلة أو لازمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,345,0,'ecb79d18f74c4771fd9998532c969008','9139b7c04e3291c7519b4b1bd1c3d575',replace($m208$إذا ثبت من التقرير الطبي النفسي أن المتهم يعاني من اضطراب نفسي أو عقلي أدى إلى إنقاص إدراكه أو اختياره دون أن يفقده ،يجوز للمحكمة أن تقضي بقيام المحكوم عليه بتنفيذ العقوبة المقضي بها في إحدى منشآت الصحة النفسية الحكومية التي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية لتلقي العلاج والرعاية اللازمة.
وفي جميع الأحوال ،لا يجوز إيداع المتهم أو المحكوم عليه بمراكز الإصلاح والتأهيل العمومية أو مراكز الإصلاح الجغرافية متى ثبت إصابته باضطراب نفسي أو عقلي أفقده القدرة على الإدراك أو الاختيار أو نقص من هذه القدرة أو توافرت في شأنه إحدى حالات الدخول الإلزامي المنصوص عليها بقانون رعاية المريض النفسي المشار إليه حتى يبرأ منه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,346,0,'6a27699aa2e319923db0484501487def','f11300b49b7de1dfacf29156a6eb6dc6',replace($m208$إذا صدر أمر بأن لا وجه لإقامة الدعوى أو حكم ببراءة المتهم ،وكان ذلك بسبب اضطراب نفسي أو عقلي ،تأمر الجهة التي أصدرت الأمر أو الحكم إذا كانت الواقعة جناية أو جنحة عقوبتها الحبس مدة لا تقل عن سنة بإيداعه في إحدى منشآت الصحة النفسية الحكومية التي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية، ضا وفقًا لأحكام الدخول الإلزامي ويكون الإفراج عنه أو الأمر بمعاملته باعتباره مري أو نقله لأية جهة أخرى عند ثبوت استقرار حالته النفسية ،مع استمرار حاجته للرعاية أو تلقي العلاج أو الدعم النفسي من الجهة التي أصدرت الأمر أو الحكم ،بناء على توصية من اللجنة المشكلة بقرار من المجلس القومي للصحة النفسية لفحص المودعين، على أنه في الجنايات المعاقب عليها بعقوبة الإعدام والسجن المؤبد لا يجوز الإفراج عن المتهم إلا بعد صدور توصيتين على الأقل من اللجنة سالفة البيان يفصل بينهما مدة ثلاثة أشهر على الأقل.
واني عليهم الأطفال$m208$,'<<CR>>',chr(13))),
('law',174,2025,347,0,'0279c8f358a9eaf299f54f87989e15a9','e6b53a7310cc9ad3a4a5d1ec3b25c681',replace($m208$إذا وقعت على مجني عليه مصاب باضطراب نفسي أو عقلي جناية أو جنحة من جرائم الاعتداء على النفس ،جاز لسلطة التحقيق أن تصدر أمرا بإيداعه مؤقتًا في إحدى منشآت الصحة النفسية لتلقي العلاج والرعاية الطبية ،وفقا لأحكام الدخول الإلزامي المنصوص عليها بقانون رعاية المريض النفسي المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,348,0,'f5a2f4a6f526334300ddb14d70e3c8fb','2bbccb0aba4a319bbb0e8fc41d93ff52',replace($m208$يجوز لسلطة التحقيق المختصة عند سؤال المجني عليهم الأطفال في أي جريمة استدعاء أحد ذوي الطفل ،أو أحد الأخصائيين الاجتماعيين لحضور إجراءات التحقيق.
كما يجوز للمحقق تسجيل أقوال الطفل المجني عليه سمعيا وبصريا ،ويجوز أن يكون التسجيل سمعيا فقط ،بناء على طلب الطفل أو الشخص الذي يحضر من ذويه، ويحفظ هذا التسجيل بواسطة إحدى وسائط التخزين الرقمية تودع ملف القضية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,349,0,'c38517e9c4e2536c9d0c9ee34d3019bb','14b6175bc061faf420098494d365ea66',replace($m208$تشكل في كل محكمة استئناف محكمة أو أكثر لنظر قضايا الجنايات ،وتؤلف كل منها من ثلاثة من قضاتها برئاسة أحد نواب رئيس محكمة الاستئناف على الأقل.
وتخصص دائرة أو أكثر من دوائر محكمة الجنايات يكون رئيس كل منها بدرجة رئيس بمحكمة الاستئناف لنظر الجنايات المنصوص عليها في الأبواب الأول والثاني والثاني مكررا والثالث والرابع من الكتاب الثاني من قانون العقوبات ،والجرائم المرتبطة بتلك الجنايات ،ويفصل في هذه القضايا على وجه السرعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,350,0,'c88219bd5d083996688d09f20ee29c08','042992a7c795ff7037d60f5ba4cf43e9',replace($m208$تشكل في كل محكمة استئناف محكمة أو أكثر تستأنف أمامها الأحكام الصادرة من دوائر جنايات أول درجة ،وتؤلف كل منها من ثلاثة من قضاتها أحدهم على الأقل بدرجة رئيس محكمة استئناف ،وتكون رئاسة المحكمة لأقدمهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,351,0,'2224cb96b6570f8e41ce932614d3551d','171b5aa182f29c03061ed17a44cb110e',replace($m208$تحدد الجمعية العامة لكل محكمة من محاكم الاستئناف في كل سنة بناء على طلب رئيسها ،من يعهد إليه من قضاتها للعمل بمحاكم الجنايات بدرجتيها.
وإذا حصل مانع لأحد القضاة المعينين لدور من أدوار انعقاد محكمة الجنايات بدرجتيها يستبدل به آخر من القضاة يندبه رئيس محكمة الاستئناف من ذات الدرجة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,352,0,'3857a82d8beb91be370740be23921f23','96e2f44a661616f23ac09dbd6762cc6c',replace($m208$تنعقد محكمة الجنايات بدرجتيها في كل جهة بها محكمة ابتدائية ،وتشمل دائرة اختصاصها ما تشمله دائرة المحكمة الابتدائية ،ويجوز إذا اقتضت الحال أن تنعقد محكمة الجنايات في مكان آخر يعينه وزير العدل بناء على طلب رئيس محكمة الاستئناف.
ويجوز عند الضرورة بقرار من الجمعية العامة لمحكمة الاستئناف أو من تفوضه أن تشمل دائرة اختصاص محكمة الجنايات المستأنفة ما تشمله أكثر من دائرة لمحكمة ابتدائية ،ويبين القرار في هذه الحالة مكان انعقادها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,353,0,'b8a4844a646d5316194e4ed2163bfd9d','b934953e5261f2bc84dc9e02ebc46160',replace($m208$تنعقد محكمة الجنايات بدرجتيها كل شهر ما لم يصدر قرار من رئيس محكمة الاستئناف بخلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,356,0,'042776b13118278864c5344eab71f49b','30d8fce861fa322885a1052ecc2ffba7',replace($m208$يتبع في الدعاوى التي تنظرها محكمة الجنايات المستأنفة جميع الأحكام والأوضاع المقررة أمام محاكم جنايات أول درجة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,357,0,'03b0c274b64e47d4542c390de7cd4a37','da4c99b61e70c3dbbf1c6920309cf473',replace($m208$يكون تكليف المتهم والشهود بالحضور أمام محكمة جنايات أول درجة قبل الجلسة بعشرة أيام كاملة على الأقل.
وفي الأحوال التي يكون فيها استئناف الحكم من النيابة العامة ،يكون إعلان المتهم بالاستئناف والحضور أمام محكمة الجنايات المستأنفة قبل الجلسة بعشرة أيام كاملة على الأقل.
ولا تتصل المحكمة بالدعوى إلا بإعلان المتهم بأمر الإحالة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,358,0,'7a8736d35d3d413714565ff5bebd782d','900d8c1ff16d12210ca6a5fe1ad4c240',replace($m208$فيما عدا حالة العذر أو المانع الذي يثبت صحته ،يجب على المحامي سواء أكان موكلا من قبل المتهم أم كان منتدبا من قبل النيابة العامة أو قاضي التحقيق ،أو رئيس محكمة الجنايات بدرجتيها ،أن يدافع عن المتهم في الجلسة أو ينيب محاميا غيره ،وإلا حكم عليه من محكمة الجنايات بدرجتيها بغرامة لا تتجاوز ثلاثمائة جنيه مع عدم الإخلال بالمساءلة التأديبية إذا كان لذلك مقتض.
وللمحكمة إعفاؤه من الغرامة إذا ثبت لها أنه تعذر عليه أن يحضر في الجلسة بنفسه أو أن ينيب عنه غيره.$m208$,'<<CR>>',chr(13))),
('law',174,2025,359,0,'66cb7df67f721e05e52a96343b894f29','8e2a9cbdcc0a6638f0aa91c5e37454f4',replace($m208$في الأحوال التي يتعذر فيها على المتهم أن يوكل محاميا للدفاع عنه ،تقدر المحكمة للمحامي المنتدب من قبل النيابة العامة أو قاضي التحقيق أو رئيس محكمة الجنايات بدرجتيها ،بحسب الأحوال ،أتعابا على الخزانة العامة تحددها في حكمها الصادر في الدعوى.
ويجوز التظلم من هذا التقدير أمام المحكمة التي أصدرت الحكم بتقدير الأتعاب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,360,0,'8a1b0ca590a2c0de80569b663381650d','3fdee9e34e3f0a4ba11dd75d13f433f7',replace($m208$لا تقبل المرافعة أمام محكمة جنايات أول درجة إلا من المحامين المقبولين للمرافعة أمام المحاكم الابتدائية على الأقل ،كما لا تقبل المرافعة أمام محكمة الجنايات المستأنفة إلا من المحامين المقبولين للمرافعة أمام محاكم الاستئناف على الأقل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,361,0,'f706f8bf6dc885a1c93cecf2606d5174','33c48f9be867118bf319aebf2cb3b07a',replace($m208$يجب على رئيس محكمة الاستئناف عند وصول ملف القضية أن يحدد الدور الذي يجب أن تنظر فيه ،وأن يعد جدول قضايا كل دور من أدوار الانعقاد ،ويرسل صور ملفات القضايا إلى القضاة المعينين للدور الذي أحيلت إليه ،ويأمر بإعلان المتهم والشهود باليوم الذي يحدد لنظر القضية ،مع مراعاة حكم المادة  357 من هذا القانون إذا كان الاستئناف مرفوعا من النيابة العامة.
وإذا دعت أسباب جدية لتأجيل نظر القضية يجب أن يكون التأجيل ليوم معين سواء في ذات الدور أو في دور مقبل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,362,0,'2f2d505e26125e5d9febb222f111d49f','5abe5a88c742f99ef4482d148150224b',replace($m208$يجوز لكل من النيابة العامة والمتهم والمدعي بالحقوق المدنية والمسئول عنها أن يعارض في سماع شهادة الشهود الذين لم يسبق إعلانهم بأسمائهم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,363,0,'c03b823d6ada9092e81b5b13820457bb','69a6a7b9c5ebec69cb3657ea9de54177',replace($m208$مع مراعاة أحكام المادة  124 من هذا القانون ،لمحكمة الجنايات بدرجتيها في جميع الأحوال أن تأمر بالقبض على المتهم أو ضبطه وإحضاره ،ولها أن تأمر بحبسه احتياطيا ،وأن تفرج عنه بكفالة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,364,0,'3ce15a01813b79da3104bf436ec9a316','8705500ee862c2e0a581872c551fcbfd',replace($m208$تتبع أمام محكمة الجنايات بدرجتيها جميع الأحكام المقررة في الجنح ما لم ينص على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,365,0,'bab3e34d54f40de097573face9c353cb','ea85b635b2109531b59fb6bbf805aa2f',replace($m208$لا يجوز لمحكمة الجنايات بدرجتيها أن تصدر حكما بالإعدام إلا بإجماع آراء أعضائها ،ويجب عليها قبل أن تصدر هذا الحكم أن تأخذ رأي مفتي الجمهورية، ويجب إرسال أوراق القضية إليه ،ويتعين عليه في جميع الأحوال أن يرسل رأيه إلى المحكمة قبل جلسة النطق بالحكم بفترة كافية ،فإذا لم يصل رأيه إلى المحكمة قبل التاريخ المحدد للنطق بالحكم ،حكمت المحكمة في الدعوى.
وفي حالة خلو وظيفة المفتى أو غيابه أو قيام مانع لديه يندب وزير العدل بقرار منه من يقوم مقامه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,366,0,'bce8db8e0443fe254c9b790324bfece2','5eea15d207cfb6042b9b15f8195bd6b9',replace($m208$لا يجوز الطعن في أحكام محكمة الجنايات المستأنفة إلا بطريق النقض أو إعادة النظر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,367,0,'448bde6f4b22aa4b76adb34c7d761a88','2db2003d2b6128f297a48d6ffae528ea',replace($m208$إذا رأت محكمة جنايات أول درجة أن الواقعة كما هي مبينة في أمر الإحالة وقبل تحقيقها بالجلسة تعد جنحة ،فلها أن تحكم بعدم الاختصاص وتحيلها إلى المحكمة الجزئية.
أما إذا لم تر ذلك إلا بعد التحقيق تحكم فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,368,0,'923e6623831e11e24e1510a0f3a19116','995742236779a23a7bdbe67b13c839eb',replace($m208$لمحكمة جنايات أول درجة إذا أحيلت إليها جنحة مرتبطة بجناية ورأت قبل تحقيقها أن لا وجه لهذا الارتباط أن تفصل الجنحة وتحيلها إلى المحكمة الجزئية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,369,0,'066d305f704bccb3375f89b1a4d2f587','2c1261892c634cd11caf459a90cd00f5',replace($m208$إذا صدر أمر بإحالة متهم بجناية إلى محكمة جنايات أول درجة ولم يحضر هو أو وكيله الخاص يوم الجلسة بعد إعلانه قانونا بأمر الإحالة وبورقة التكليف بالحضور ،يكون للمحكمة أن تحكم في غيبته ،ويجوز لها أن تؤجل الدعوى وتأمر بإعادة تكليفه بالحضور.
ومع عدم الإخلال بسلطة المحكمة المنصوص عليها بالمادة  363 من هذا القانون ،يكون الحكم حضوريا إذا مثل المتهم أو وكيله الخاص بالجلسة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,370,0,'debb5f2d08d4984f8b1b07fc67dd5765','d6b019527c43195b82a246acff3f9da2',replace($m208$يتلى في الجلسة أمر الإحالة ثم الأوراق المثبتة لإعلان المتهم ،وتبدي النيابة العامة والمدعي بالحقوق المدنية إن وجد أقوالهما وطلباتهما ،وتسمع المحكمة الشهود إذا رأت ضرورة لذلك ثم تفصل في الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,371,0,'c3011d6a3a81f7aea136e3e8e21334f7','b54716c5f439efe9dd40e5061fc89070',replace($m208$إذا كان المتهم مقيما خارج مصر ،يعلن إليه أمر الإحالة وورقة التكليف بالحضور بمحل إقامته إن كان معلوما ،وذلك قبل الجلسة المحددة لنظر الدعوى بشهر على الأقل غير مواعيد المسافة ،فإذا لم يحضر بعد إعلانه يجوز الحكم في غيبته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,372,0,'f72cb401f30c26d987012a9ff6a09868','5bb63d07b8ce8b2163abe6c554dda18e',replace($m208$كل حكم يصدر بالإدانة في غيبة المتهم يستلزم حتما حرمانه من أن يتصرف في أمواله أو أن يديرها أو أن يرفع أية دعوى باسمه ،وكل تصرف أو التزام يتعهد به المحكوم عليه يكون باطلاً من نفسه ،وذلك كله مع عدم الإخلال بحقوق حسن النية من الغير.
وتحدد المحكمة الابتدائية الواقع في دائرتها أموال المحكوم عليه حارسا لإدارتها بناء على طلب النيابة العامة أو كل ذي مصلحة في ذلك ،وللمحكمة أن تلزم الحارس الذي تنصبه بتقديم كفالة ،ويكون تابعا لها في جميع ما يتعلق بالحراسة وتقديم الحساب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,373,0,'4d8488cb062653a7cc203ca8ccb22c3b','025fde5b786072a613ab9e44e13b294c',replace($m208$تنتهي الحراسة المشار إليها في المادة  372 من هذا القانون بصدور حكم حضوري في الدعوى أو بموت المتهم حقيقة أو حكما وفقًا لقانون الأحوال الشخصية، وبعد انتهاء الحراسة يقدم الحارس حسابا عن إدارته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,375,0,'c5ab51e0c968c85f2eb8533d8bf24d42','a8436f8f3b0fab80beaf019d908307b3',replace($m208$يجوز تنفيذ الحكم بالتضمينات من وقت صدوره ،ويجب على المدعي بالحقوق المدنية أن يقدم كفالة ،ما لم ينص الحكم على خلاف ذلك أو تقرر المحكمة الابتدائية إعفاءه منها.
وتنتهي الكفالة بمضي خمس سنوات من وقت صدور الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,376,0,'e83cf9a8199dc23d4b52a8b86e08e073','08f0f90da8616d71b254901ff831f2fd',replace($m208$لا يسقط الحكم الصادر غيابيا في جناية من محكمة الجنايات بدرجتيها بمضي المدة ،وإنما تسقط العقوبة المحكوم بها ،ويصبح الحكم نهائيا بسقوطها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,377,0,'8ca3df3f3ca59a2112af2e08e22b22cb','e600600dc1f4a7111acd7b8f31b13578',replace($m208$إذا حضر المحكوم عليه غيابيا من محكمة الجنايات بدرجتيها ،أو قبض عليه أو حضر وكيله الخاص وطلب إعادة المحاكمة قبل سقوط العقوبة بمضي المدة ،يحدد رئيس محكمة الاستئناف أقرب جلسة لإعادة نظر الدعوى ،فإذا تخلف المحكوم عليه غيابيا أو وكيله الخاص عن حضور الجلسة المحددة لإعادة نظر الدعوى ،اعتبر الحكم ضده قائما.
فإذا حضر المحكوم عليه غيابيا مرة أخرى قبل سقوط العقوبة بمضى المدة وطلب إعادة المحاكمة ،يحدد رئيس محكمة الاستئناف أقرب جلسة لإعادة نظر الدعوى ،فإذا تخلف المحكوم عليه أو وكيله الخاص عن الحضور فى الجلسة المحددة لإعادة نظر الدعوى أو فى جلسة تالية بغير عذر تندب له المحكمة محاميا للدفاع عنه وتفصل فى الدعوى بحكم لا يقبل إعادة المحاكمة ،ويجوز الطعن عليه بالاستئناف أو بالنقض ،بحسب الأحوال ،وفقًا لأحكام المادتين  403 ،366 من هذا القانون.
وفى جميع الأحوال ،يعرض المقبوض عليه محبوسا بالجلسة المحددة لإعادة نظر الدعوى ،وللمحكمة أن تأمر بالإفراج عنه أو استمرار حبسه احتياطيا حتى الانتهاء من نظر الدعوى ،ولا يجوز للمحكمة التشديد عما قضى به الحكم الغيابي.
وتختص بنظر إعادة الإجراءات في الأحكام الغيابية المحكمة التي أصدرت الحكم ،على أنه إذا أصدرت محكمة جنايات أول درجة حكما غيابيا بالإدانة ولو كان مشمولاً بالتضمينات ،وتم استئنافه ،وأصدرت محكمة الجنايات المستأنفة حكما غيابيا بتأييده أو تعديله ،تظل محكمة جنايات أول درجة مختصة بنظر إعادة الإجراءات فيه.
وإذا كان الحكم الغيابي السابق بالتضمينات قد نفذ تأمر المحكمة برد المبالغ المتحصلة كلها أو بعضها.
وإذا مات المحكوم عليه في غيبته يعاد الحكم في التضمينات في مواجهة الورثة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,378,0,'e7ea48ffd908543926bf15a68ccb82e7','4f0d18aa49f7a51643387d217314fb80',replace($m208$لا يترتب على غياب متهم تأخير الحكم في الدعوى بالنسبة لغيره من المتهمين معه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,379,0,'99cbe03dc4ab2d7fe2d3cc89f89c9bb1','d1b2ee2e9a30bc1971558b35c70a82fa',replace($m208$إذا غاب المتهم بجنحة مقدمة إلى محكمة جنايات أول درجة ،تتبع في شأنه الإجراءات المعمول بها أمام محكمة الجنح ،ويكون الحكم الصادر فيها قابلاً للمعارضة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,380,0,'d8fd577cd07fcbf663947d1e343eb4ec','0a487f7fb7f04f8025824c0ef3ee1c4a',replace($m208$تقبل المعارضة في الأحكام الغيابية الصادرة في الجنح ،وذلك من المتهم أو من المسئول عن الحقوق المدنية في خلال العشرة الأيام التالية لإعلانه بالحكم الغيابي خلاف ميعاد المسافة المنصوص عليه في قانون المرافعات المدنية والتجارية ،ويجوز أن يكون هذا الإعلان بملخص على نموذج يصدر به قرار من وزير العدل ،وفي جميع الأحوال لا يعتد بالإعلان لجهة الإدارة.
ومع ذلك إذا كان إعلان الحكم لم يحصل لشخص المتهم ،فإن ميعاد المعارضة بالنسبة إليه فيما يختص بالعقوبة المحكوم بها يبدأ من يوم علمه بحصول الإعلان، وتكون المعارضة جائزة حتى تنقضي الدعوى بمضي المدة.
ويجوز أن يكون إعلان الأحكام الغيابية والمعتبرة حضورية بواسطة أحد رجال السلطة العامة ،وذلك في الأحوال المنصوص عليها في الفقرة الأخيرة من المادة 62 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,381,0,'35e4f49d6ae494b9a94dad06174bd382','5abed20ca0042e1fb2da213229663b5b',replace($m208$تقبل المعارضة في الأحكام المعتبرة حضورية في الأحوال المشار إليها في المادتين  239 ،237 من هذا القانون إذا أثبت المحكوم عليه قيام عذر منعه من الحضور ،ولم يستطع تقديمه قبل الحكم ،وكان استئنافه غير جائز.
وفى جميع الأحوال لا تقبل المعارضة في الأحكام المعتبرة حضورية إذا أُعلن المتهم بورقة التكليف بالحضور وسلمت لشخصه ،أو إذا حضر عند النداء على الدعوى وغادر الجلسة بعد ذلك ،أو إذا حضر هو أو وكيله أيا من جلسات المحاكمة ثم تخلف عن حضور باقي الجلسات حتى تاريخ صدور الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,383,0,'efc5f0402c068f3bc7b8cde2e23b83f5','12ad5f3e7267b86c0aeadafa52b5c7a8',replace($m208$تحصل المعارضة بتقرير في قلم كتّاب المحكمة التي أصدرت الحكم يثبت فيه تاريخ الجلسة التي حددت لنظرها ،ويعتبر ذلك إعلانًا لها ولو كان التقرير من وكيل، ويجب على النيابة العامة تكليف باقي الخصوم في الدعوى بالحضور وإعلان الشهود للجلسة المذكورة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,384,0,'1d4ae2ffa45214223ba46b1629ed05cd','b89d3d780d5902704b7e64210d65c66a',replace($m208$يترتب على المعارضة إعادة نظر الدعوى بالنسبة إلى المعارض أمام المحكمة التي أصدرت الحكم ،ولا يجوز بأية حال أن يضار المعارض بناء على المعارضة المرفوعة منه.
ومع ذلك إذا لم يحضر المعارض أو وكيله في أي من الجلسات المحددة لنظر الدعوى تعتبر المعارضة كأن لم تكن ،ويجوز للمحكمة في هذه الحالة أن تحكم عليه بغرامة إجرائية لا تجاوز ألف جنيه ،ولها أن تأمر بالنفاذ المؤقت ولو مع حصول الاستئناف بالنسبة للتعويضات المحكوم بها ،وذلك حسب ما هو مقرر بالمادة  440 من هذا القانون.
ولا يجوز من المعارض المعارضة في الحكم الصادر في غيبته ،وللمحكمة في هذه الحالة أن تحكم عليه بغرامة إجرائية لا تقل عن خمسين جنيها ولا تزيد على مائتي جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,385,0,'23fb24d6633b606c2fcb35c89e86ff6b','1aac913d2ce7fd51aa9c7da07376c21b',replace($m208$لكل من المتهم والنيابة العامة أن يستأنف الأحكام الصادرة في الدعوى الجنائية من المحكمة الجزئية في مواد الجنح.
ولا يجوز استئناف الحكم الصادر في جنحة معاقب عليها بغرامة لا تجاوز خمسة آلاف جنيه فضلاً عن الرد والمصاريف ،إلا لمخالفة القانون أو خطأ في تطبيقه أو في تأويله أو لوقوع بطلان في الحكم أو في الإجراءات أثر في الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,386,0,'40c9b0aa2546824f973bdd25770f8fa5','3e176b90073a2266db707643553193a4',replace($m208$يجوز استئناف الأحكام الصادرة في الدعوى المدنية من المحكمة الجزئية في الجنح من المدعي بالحقوق المدنية ومن المسئول عنها أو المتهم فيما يختص بالحقوق المدنية وحدها إذا كانت التعويضات المطلوبة تزيد على النصاب الذي يحكم فيه القاضي الجزئي نهائيا.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,387,0,'37c41c8aebaf0e1e5097af99ab4c6397','ccbb427008b79c1c5c1d98286c278902',replace($m208$يجوز استئناف الحكم الصادر في الجرائم المرتبطة في حكم المادة  32 من قانون العقوبات ،ولو لم يكن الاستئناف جائزا للمستأنف إلا بالنسبة لبعض هذه الجرائم فقط.$m208$,'<<CR>>',chr(13))),
('law',174,2025,388,0,'9616c04cb58bee8d3ee1ae61b5ebfd01','a818673dbacf369349c92cb85fe4a34a',replace($m208$لا يجوز قبل أن يفصل في موضوع الدعوى استئناف الأحكام التحضيرية والتمهيدية الصادرة في مسائل فرعية ،ويترتب حتما على استئناف الحكم الصادر في الموضوع استئناف هذه الأحكام.
ويجوز استئناف جميع الأحكام الصادرة بعدم الاختصاص ،والأحكام الصادرة بالاختصاص إذا لم يكن للمحكمة ولاية الحكم في الدعوى.$m208$,'<<CR>>',chr(13))),
('law',174,2025,389,0,'667c7ca6a0e1c6c44479f98ddd44cad1','65a7caf63b5f45b48b64a45f4d6b642c',replace($m208$يحصل الاستئناف بتقرير في قلم كتاب المحكمة التي أصدرت الحكم خلال عشرة أيام من تاريخ النطق بالحكم الحضوري ،أو إعلان الحكم الغيابي ،أو من تاريخ الحكم الصادر في المعارضة في الحالات التي يجوز فيها ذلك.
وللنائب العام أن يستأنف خلال ثلاثين يوما من تاريخ الحكم ،وله أن يقرر بالاستئناف في قلم كتاب المحكمة المختصة بنظر الاستئناف.$m208$,'<<CR>>',chr(13))),
('law',174,2025,390,0,'4ca0d705b371e96bebb2f49ba330fa10','c3e7d48c5ec295d38d91683f4f6a4910',replace($m208$الأحكام الصادرة في غيبة المتهم والمعتبرة حضوريا طبقًا لأحكام المواد ،237 239 ،238 من هذا القانون يبدأ ميعاد استئنافها بالنسبة للمتهم من تاريخ إعلانه بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,391,0,'8baa2db09484dae1a464c4d273f627ea','35fa54d696c9303116abc5aa79155f49',replace($m208$يحدد قلم الكتّاب للمستأنف في تقرير الاستئناف تاريخ الجلسة التي حددت لنظره، ويعتبر ذلك إعلانًا لها ولو كان التقرير من وكيل ،ولا يكون هذا التاريخ قبل مضي ثلاثة أيام كاملة ،وتكلف النيابة العامة الخصوم الآخرين بالحضور.
وفي جميع الأحوال ،على المستأنف أن يتبع استئنافه ،حتى صدور الحكم فيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,392,0,'29d0599974d0ba0839703be8857dc789','1392a610e81907496eaa57fbaf4a67b9',replace($m208$إذا استأنف أحد الخصوم في مدة العشرة الأيام المقررة يمتد ميعاد الاستئناف لمن له حق الاستئناف من باقي الخصوم خمسة أيام من تاريخ انتهاء العشرة الأيام المذكورة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,393,0,'be8b4c4776601996148f26308fb5f6c7','1d6047f9b45c9e1b6374097cd034a271',replace($m208$يرفع الاستئناف للمحكمة الابتدائية الكائنة في دائرتها المحكمة التي أصدرت الحكم ،ويقدم خلال عشرين يوما على الأكثر إلى الدائرة المختصة بنظر الاستئناف في مواد الجنح.
وإذا كان المتهم محبوسا وجب على النيابة العامة نقله في الوقت المناسب إلى مركز الإصلاح والتأهيل بالجهة الموجودة بها المحكمة الابتدائية ،وينظر الاستئناف على وجه السرعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,394,0,'3785e3f970d1512c4e50a42a49e1524c','978fcbed0649534dc4bd92073634c883',replace($m208$يضع أحد أعضاء الدائرة المنوط بها الحكم في الاستئناف تقريرا موقعا عليه منه، ويجب أن يشمل هذا التقرير ملخص وقائع الدعوى وظروفها وأدلة الثبوت والنفي وجميع المسائل الفرعية التي رفعت والإجراءات التي تمت.
وبعد تلاوة هذا التقرير قبل إبداء رأي في الدعوى من واضع التقرير أو بقية الأعضاء ،تسمع أقوال المستأنف والأوجه المستند إليها في استئنافه ،ثم يتكلم بعد ذلك باقي الخصوم ،ويكون المتهم آخر من يتكلم.
ثم تصدر المحكمة حكمها بعد اطلاعها على الأوراق.$m208$,'<<CR>>',chr(13))),
('law',174,2025,395,0,'292f24e3b06f3374ed2b85d176fce882','5930a8d1636bd22340b16ffd1d9f5dda',replace($m208$يسقط الاستئناف المرفوع من المحكوم عليه بعقوبة مقيدة للحرية واجبة النفاذ إذا لم يتقدم للتنفيذ قبل الجلسة التي تنظر فيها الدعوى.
ومع ذلك فللمحكمة عند نظر الاستئناف أن تأمر بوقف تنفيذ العقوبة مؤقتًـا أو الإفراج عن المحكوم عليه بكفالة أو بغيرها ،وذلك إلى حين الفصل في الاستئناف.$m208$,'<<CR>>',chr(13))),
('law',174,2025,396,0,'786f8e22c7af19786e5b5cfc36d82c28','64c261b7c7ea2586d4bb91f9d0e60a2f',replace($m208$تسمع المحكمة الاستئنافية بنفسها ،أو بواسطة أحد القضاة تندبه لذلك الشهود الذين كان يجب سماعهم أمام محكمة أول درجة ،متى رأت ضرورة ذلك للفصل في الدعوى ،ولها أن تستوفى كل نقص آخر في إجراءات التحقيق.
وفي جميع الأحوال يجوز لها أن تأمر بما ترى لزومه من استيفاء تحقيق أو سماع شهود.
ولا يجوز تكليف أي شاهد بالحضور إلا إذا أمرت المحكمة بذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,397,0,'f5853b6a03344b7c943fc0d7138c5d7d','571a7426a1f1e8800a12a4451575b7e5',replace($m208$إذا تبين للمحكمة الاستئنافية أن الواقعة جناية ،أو أنها جنحة من الجنح التي تقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد ،تحكم بعدم الاختصاص وتحيل الدعوى إلى النيابة العامة لاتخاذ ما يلزم فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,398,0,'32c05baf7feed29b08281f8b0f79352e','d6fc4816d83a79c72f966cf769c5a156',replace($m208$إذا ألغي الحكم الصادر بالتعويضات ،وكان قد نفذ بها تنفيذًا مؤقتًـا ،ترد التعويضات بناء على حكم الإلغاء.$m208$,'<<CR>>',chr(13))),
('law',174,2025,399,0,'dc9f344ce8d70905bfa74cf2849f616f','25004c43bad7626c0a4e2e9b10f64173',replace($m208$إذا كان الاستئناف مرفوعا من النيابة العامة ،فللمحكمة أن تؤيد الحكم أو تلغيه أو تعدله سواء ضد المتهم أو لمصلحته.
ولا يجوز تشديد العقوبة المحكوم بها ولا إلغاء الحكم الصادر بالبراءة إلا بإجماع آراء قضاة المحكمة.
أما إذا كان الاستئناف مرفوعا من غير النيابة العامة فليس للمحكمة إلا أن تؤيد الحكم أو تعدله لمصلحة رافع الاستئناف ،ويجوز لها إذا قضت بسقوط الاستئناف أو بعدم قبوله أو بعدم جوازه أو برفضه أن تحكم على رافعه بغرامة لا تجاوز ألف جنيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,400,0,'818801826e7147f7661fa4a7291b793c','f1cc6173ce5f4cbc9b2b5dab469bb3df',replace($m208$يتبع في الأحكام الغيابية والمعارضة فيها أمام المحكمة الاستئنافية ما هو مقرر أمام محاكم أول درجة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,401,0,'e3e1d486e34a686b732cd66599780fd0','034edc04c4ddd04c5164387be7f0e04b',replace($m208$لا تقبل المعارضة في الأحكام الغيابية الصادرة من المحكمة الاستئنافية إلا إذا كان الاستئناف مقررا من النيابة العامة أو من المدعي بالحقوق المدنية ولم يحضر الخصم أو وكيله جلسة المحاكمة رغم إعلانه بالاستئناف ،وقدم الخصم عذرا تقبله المحكمة منعه من الحضور.
وفى جميع الأحوال لا تقبل المعارضة الاستئنافية إذا أُعلن الخصم بورقة التكليف بالحضور وسلمت لشخصه ،أو إذا حضر عند النداء على الدعوى وغادر الجلسة بعد ذلك ،أو إذا حضر هو أو وكيله أيا من جلسات المحاكمة ثم تخلف عن حضور باقي الجلسات حتى تاريخ صدور الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,402,0,'0b3ec597d7248ac31b18a56896ee58d7','19b0842bba12dfd32ebf3722608fb172',replace($m208$إذا حكمت محكمة أول درجة في الموضوع ،ورأت المحكمة الاستئنافية أن هناك بطلانًا في الإجراءات أو في الحكم ،تصحح البطلان وتحكم في الدعوى.
أما إذا حكمت بعدم الاختصاص أو بقبول دفع فرعي يترتب عليه منع السير في الدعوى ،وحكمت المحكمة الاستئنافية بإلغاء الحكم وباختصاص المحكمة أو برفض الدفع الفرعي وبنظر الدعوى ،يجب عليها أن تعيد القضية لمحكمة أول درجة للحكم في موضوعها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,403,0,'7731d2b9e5a71fe90016a584b5ac6d91','f77bf9fc2eb1ce69bc5879c82ecbc158',replace($m208$يجوز لكل من النيابة العامة والمتهم أن يستأنفا الأحكام الحضورية الصادرة من محكمة جنايات أول درجة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,404,0,'6cfecc44b51ea42f1d018170cddb3eeb','d2cd684cf07dc9b13fa26305d9c9e300',replace($m208$يجوز استئناف الأحكام الصادرة في الدعوى المدنية من محكمة جنايات أول درجة من المدعى بالحقوق المدنية أو المسئول عنها أو المتهم فيما يختص بالحقوق المدنية وحدها ،إذا كانت التعويضات المطلوبة تزيد على النصاب الذي تحكم فيه المحكمة الابتدائية نهائيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,406,0,'6acf37417ea174fc7ed4d8ab736b4f46','c67b5a616d4750bddcaec36cf379daa7',replace($m208$يتبع في نظر الاستئناف والفصل فيه جميع الأحكام المقررة للاستئناف في مواد الجنح ،ما لم ينص القانون على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,407,0,'c72cd15ada96ba60e5488f345de5028d','8257aaf6aa70683ea9c127316e1cae2b',replace($m208$يحصل الاستئناف بتقرير في قلم كتاب المحكمة التي أصدرت الحكم ،وذلك خلال أربعين يوما من تاريخ صدور الحكم.
فإذا كان مرفوعا من النيابة العامة يجب أن يكون التقرير موقعا من محام عام على الأقل.
وإذا كان الاستئناف مرفوعا من هيئة قضايا الدولة يجب أن يكون التقرير موقعا من مستشار بها على الأقل.
وللنائب العام أن يستأنف الحكم خلال ستين يوما من تاريخ صدوره ،وله أن يقرر بالاستئناف في قلم كتاب المحكمة المختصة بنظر الاستئناف.$m208$,'<<CR>>',chr(13))),
('law',174,2025,408,0,'9bada223c2d0efc015de584aa37c59f4','0b9c898a3610f142d577a4bc040ecc40',replace($m208$يرفع قلم الكتاب التقرير بالاستئناف وملف الدعوى فور انتهاء الميعاد المحدد لإيداع أسباب الحكم الصادر فيها إلى رئيس محكمة الاستئناف بعد إدراج الاستئناف في جدول يعد لذلك ،ويحدد رئيس المحكمة جلسة لنظره ،ويأمر بإعلان المتهم وإخطار باقي الخصوم بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,410,0,'fd208cf19a9d1549ab56e13b394b7cf4','4b3b1ebf77cd28775e30952f38aa632f',replace($m208$تسمع المحكمة أقوال المستأنف ،والأوجه التي يستند إليها في استئنافه ،وأوجه دفاعه ودفوعه ،كما تسمع باقي الخصوم ،على أن يكون المتهم آخر من يتكلم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,411,0,'f061e9501151039dd103e5ff3bd3c65a','709dd05c8bba7fb5313554b89a5abd0f',replace($m208$إذا كان الاستئناف مرفوعا من المحكوم عليه ،وتخلف هو أو وكيله الخاص عن الحضور في الجلسة المحددة لنظر الاستئناف ،أو في أي جلسة تالية ،تؤجل المحكمة نظر الاستئناف لمرة واحدة ،وإن تخلف هو أو وكيله الخاص عن الحضور تندب له المحكمة محاميا للدفاع عنه ،وتفصل في الاستئناف بحكم لا يقبل إعادة المحاكمة، ويسري في شأنه حكم المادة  366 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,412,0,'5b775df28beb13e89125c779cd55fc15','8245fb56aa1e65b3ef6ce98afd3b970d',replace($m208$إذا كان الحكم صادرا حضوريا بعقوبة الإعدام ،ولم يجر استئنافه خلال الميعاد المقرر قانونا ،وجب على النيابة العامة اتباع حكم المادة  46 من قانون حالات وإجراءات الطعن أمام محكمة النقض الصادر بالقانون رقم  57 لسنة .1959$m208$,'<<CR>>',chr(13))),
('law',174,2025,413,0,'eea069e6866b2ac1d80dfd2535bab8b8','086441c07acc57f9b7f4eda6cd5bf420',replace($m208$لا يترتب على استئناف الحكم الصادر من محكمة جنايات أول درجة وقف تنفيذ الحكم ،إلا إذا رأت محكمة الجنايات المستأنفة وقف التنفيذ أو إذا كان الحكم صادرا بالإعدام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,414,0,'31d0fc528e307c91efd36f01f6048661','537f4a49e384bd277022f4c37b7b2874',replace($m208$يجوز طلب إعادة النظر في الأحكام الباتة الصادرة بالعقوبة في مواد الجنايات والجنح في الأحوال الآتية: 1- إذا حكم على المتهم في جريمة قتل ،ثم وجد المدعى قتله حيا.
2- إذا صدر حكم على شخص من أجل واقعة ،ثم صدر حكم على شخص آخر من أجل الواقعة عينها ،وكان بين الحكمين تناقض بحيث يستنتج منه براءة أحد المحكوم عليهما.
3- إذا حكم على أحد الشهود أو الخبراء بالعقوبة لشهادة الزور وفقًـا لأحكام الباب السادس من الكتاب الثالث من قانون العقوبات ،أو إذا حكم بتزوير ورقة قدمت أثناء نظر الدعوى ،وكان للشهادة أو تقرير الخبير أو الورقة تأثير في الحكم.
4- إذا كان الحكم مبنيا على حكم صادر من محكمة مدنية أو من إحدى محاكم الأسرة وألغي هذا الحكم.
5- إذا حدثت أو ظهرت بعد الحكم وقائع ،أو إذا قدمت أوراق لم تكن معلومة وقت المحاكمة ،وكان من شأن هذه الوقائع أو الأوراق ثبوت براءة المحكوم عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,415,0,'c144d07a2a887082eade5083142323aa','d1a14feeb8bd500464a555a1c2d40de2',replace($m208$في الحالات المنصوص عليها في البنود (1 ،2 ،3 ،4) من المادة  414 من هذا القانون ،يكون لكل من النائب العام والمحكوم عليه أو وكيله الخاص أو من يمثله قانونًا إذا كان عديم الأهلية أو مفقودا أو أقاربه أو زوجه بعد موته حق طلب إعادة النظر.
وإذا كان الطالب غير النيابة العامة فعليه تقديم الطلب إلى النائب العام بعريضة يبين فيها الحكم المطلوب إعادة النظر فيه ،والوجه الذي يستند عليه ،ويشفعه بالمستندات المؤيدة له.
ويرفع النائب العام الطلب سواء كان مقدما منه أو من غيره مع التحقيقات التي يكون قد رأى إجراءها إلى محكمة النقض بتقرير يبين فيه رأيه والأسباب التي يستند عليها.
ويجب أن يرفع الطلب إلى المحكمة في الثلاثة الأشهر التالية لتقديمه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,416,0,'579798720f2dbfd203d4644c3cc04c9c','abd95e852289f6ecbb13044ee82c012b',replace($m208$في الحالة المنصوص عليها في البند (5) من المادة  414 من هذا القانون يكون حق طلب إعادة النظر للنائب العام وحده سواء من تلقاء نفسه أو بناء على طلب ذوى الشأن ،وإذا رأى له محلاً يرفعه مع التحقيقات التي يكون قد رأى لزومها إلى لجنة مشكلة من أحد قضاة محكمة النقض واثنين من قضاة محكمة الاستئناف تعين كلاً منهم الجمعية العامة بالمحكمة التابع لها ،ويجب أن يبين في الطلب الواقعة أو الورقة التي يستند عليها.
وتفصل اللجنة في الطلب بعد الاطلاع على الأوراق واستيفاء ما تراه من التحقيق ،وتأمر بإحالته إلى محكمة النقض إذا رأت قبوله.
ولا يقبل الطعن بأي وجه في القرار الصادر من النائب العام أو في الأمر الصادر من اللجنة المشار إليها بقبول الطلب أو عدم قبوله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,417,0,'e6cc212c608d3aa9689642f9d80a34dd','7d071e13c952eb0faa695590add7473d',replace($m208$لا يقبل النائب العام طلب إعادة النظر من المتهم أو من يحل محله في الحالات المنصوص عليها في البنود (1 ،2 ،3 ،4) من المادة  414 من هذا القانون إلا إذا أودع الطالب خزانة محكمة النقض كفالة مقدارها خمسة آلاف جنيه ،تخصص للوفاء بالغرامة المنصوص عليها بالمادة  422 من هذا القانون ،ما لم يكن قد أعفي من إيداعه بقرار من لجنة المساعدة القضائية بمحكمة النقض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,419,0,'a373027e3954ab2015192e87c5779104','39b252f606d82d9b97492c6953584742',replace($m208$تفصل محكمة النقض في الطلب بعد سماع أقوال النيابة العامة والخصوم ،وبعد إجراء ما تراه لازما من التحقيق بنفسها أو بواسطة من تندبه لذلك ،فإذا رأت قبول الطلب تحكم بإلغاء الحكم وتقضي ببراءة المتهم إذا كانت البراءة ظاهرة ،وإلا تُحِـلْ الدعوى إلى المحكمة التي أصدرت الحكم مشكلة من قضاة آخرين للفصل في موضوعها ما لم تر هي إجراء ذلك بنفسها.
ومع ذلك إذا كان من غير الممكن إعادة المحاكمة كما في حالة وفاة المحكوم عليه أو المصاب باضطراب نفسي أو عقلي أو انقضاء الدعوى الجنائية بمضي المدة، تنظر محكمة النقض موضوع الدعوى ،ولا تلغي من الحكم إلا ما يظهر لها خطؤه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,420,0,'957f5e52f5a7c38ac9cf3b6d5d7bfa83','b9643a8f9f81ea91035ea90e542484a5',replace($m208$إذا مات المحكوم عليه ولم يكن الطلب مقدما من أحد الأقارب أو الزوج ،تنظر المحكمة الدعوى في مواجهة من تحدده للدفاع عن سمعته ،ويكون بقدر الإمكان من الأقارب ،وفي هذه الحالة تحكم عند الاقتضاء بمحو ما يمس هذه السمعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,422,0,'2419dd7e7f2067d295b44ceead2e10ff','2cf33854b1a07293e5b494b32bb43ae2',replace($m208$يحكم على طالب إعادة النظر إذا كان غير النائب العام في الحالات المنصوص عليها في البنود (1 ،2 ،3 ،4) من المادة  414 من هذا القانون بغرامة لا تزيد على خمسة آلاف جنيه إذا لم يقبل طلبه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,423,0,'856ae47f44be21f70e6635656c552c9a','425ea4f2fabe15ac2bc8bca5b833b040',replace($m208$كل حكم صادر بالبراءة بناء على إعادة النظر يجب نشره على نفقة الدولة في الجريدة الرسمية بناء على طلب النيابة العامة وفي جريدتين يعينهما صاحب الشأن.$m208$,'<<CR>>',chr(13))),
('law',174,2025,424,0,'322ddab292b7cae5cd0d9584ae78de4b','5b034dea3ed0a887109005e88836fca0',replace($m208$يترتب على إلغاء الحكم بناء على إعادة النظر سقوط الحكم بالتعويضات، ووجوب رد ما نفذ به منها دون إخلال بقواعد سقوط الحق بمضي المدة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,425,0,'d20ca5a8b75923cdbbb4a600aa08e40b','1f243277c46f3542924c4704cade7879',replace($m208$إذا رفض طلب إعادة النظر ،فلا يجوز تجديده بناء على ذات الوقائع التي بني عليها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,426,0,'ce6d26939a03327b40176039d3de8307','907a85cc80f4249c07b0955747abbf93',replace($m208$الأحكام التي تصدر في موضوع الدعوى بناء على إعادة النظر من غير محكمة النقض ،يجوز الطعن فيها بجميع الطرق المقررة في القانون.
ولا يجوز أن يقضى على المتهم بأشد من العقوبة السابق الحكم بها عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,427,0,'fed5d8524d3f98830871ecaff36808d2','0bce58103a7b97b745d0dc6de1f85fb6',replace($m208$تنقضي الدعوى الجنائية بالنسبة للمتهم المرفوعة عليه والوقائع المسندة فيها إليه بصدور حكم بات فيها بالبراءة أو بالإدانة.
وإذا صدر حكم في موضوع الدعوى الجنائية فلا يجوز إعادة نظرها إلا بالطعن في هذا الحكم بالطرق المقررة في القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,428,0,'b13231111ca31f8d85a1a3dd62090cfb','dcb310e6c9a7b5bf7b8aa9fdd682b33d',replace($m208$لا يجوز الرجوع إلى الدعوى الجنائية بعد الحكم فيها بحكم بات بناء على ظهور أدلة جديدة أو ظروف جديدة أو بناء على تغيير الوصف القانوني للجريمة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,429,0,'18f84ad164ec9546b23ea72b1232185d','8263c3dee393f7d80a108b771e8a436c',replace($m208$يكون للحكم الجنائي الصادر من المحكمة الجنائية في موضوع الدعوى الجنائية بالبراءة أو بالإدانة قوة الشيء المحكوم به أمام المحاكم المدنية في الدعاوى التي لم يكن قد فصل فيها نهائيا فيما يتعلق بوقوع الجريمة وبوصفها القانوني ونسبتها إلى فاعلها ،ويكون للحكم بالبراءة هذه القوة سواء بني على انتفاء التهمة أو على عدم كفاية الأدلة ،ولا تكون له هذه القوة إذا كان مبنيا على أن الفعل لا يعاقب عليه القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,431,0,'8bb4ed7cf4e8fc013d65e2e7ebffa6a7','f1f791e92f7365e6669c2d328e820a6c',replace($m208$تكون للأحكام الصادرة من محاكم الأسرة في حدود اختصاصها قوة الشيء المحكوم به أمام المحاكم الجنائية في المسائل التي يتوقف عليها الفصل في الدعوى الجنائية.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,432,0,'88be7ad8b5a253dd69c5a249337454c7','b7fd3c8521fc891c0724ee9f97f0fcd6',replace($m208$لا يجوز توقيع العقوبات المقررة بالقانون لأية جريمة إلا بمقتضى حكم صادر من محكمة مختصة بذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,433,0,'7e3a96544742f0f8387c60c1ec3515a1','d44da8022469f3f503244bef7f286370',replace($m208$لا تنفذ الأحكام الصادرة من المحاكم الجنائية إلا متى صارت نهائية ،ما لم ينص القانون على خلاف ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,434,0,'0ddd994992a39ef3b36cd1b0b74ec637','cb77ab290449b7a9b507bc72da48a968',replace($m208$يكون تنفيذ الأحكام الصادرة في الدعوى الجنائية بناء على طلب النيابة العامة وفقًا لما هو مقرر بهذا القانون.
والأحكام الصادرة في الدعوى المدنية يكون تنفيذها بناء على طلب المدعي بالحقوق المدنية وفقًا لما هو مقرر بقانون المرافعات في المواد المدنية والتجارية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,436,0,'f08eeef31958ab7011553beaf3a7041b','db70730c8a87eac9b328104752e2ff42',replace($m208$الأحكام الصادرة بالغرامة والمصاريف تكون واجبة التنفيذ فورا ،ولو مع حصول استئنافها ،وكذلك الأحكام الصادرة بالحبس في سرقة أو على متهم عائد ،أو ليس له محل إقامة ثابت بمصر ،وكذلك الحال في الأحوال الأخرى إذا كان الحكم صادرا بالحبس ،إلا إذا قدم المتهم كفالة بأنه إذا لم يستأنف الحكم لا يفر من تنفيذه عند انقضاء مواعيد الاستئناف ،وأنه إذا استأنفه يحضر في الجلسة ولا يفر من تنفيذ الحكم الذي يصدر ،وكل حكم صادر بعقوبة الحبس في هذه الأحوال يعين فيه المبلغ الذي يجب تقديم الكفالة به.
وإذا كان المتهم محبوسا حبسا احتياطيا يجوز للمحكمة أن تأمر بتنفيذ الحكم تنفيذًا مؤقتًا.
وللمحكمة عند الحكم بالتعويضات للمدعي بالحقوق المدنية أن تأمر بالتنفيذ المؤقت ،ولو مع حصول الاستئناف على حسب المقرر بالمادة  440 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,437,0,'67ee11e503e80215195897b0ef840dfe','d511739a8e0fd8fd42ad673cce745b87',replace($m208$تنفذ العقوبات التبعية المقيدة للحرية المحكوم بها مع عقوبة الحبس إذا نفذت عقوبة الحبس ،طبقًا للمادة  436 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,438,0,'708189223098029e8b4aef5afd012c8c','1cd458bdc6e0b5d73068c69a38a77ea2',replace($m208$يفرج في الحال عن المتهم المحبوس احتياطيا ،إذا كان الحكم صادرا بالبراءة، أو بعقوبة أخرى لا يقتضي تنفيذها الحبس ،أو إذا أمر في الحكم بوقف تنفيذ العقوبة، أو إذا كان المتهم قد قضى في الحبس الاحتياطي مدة العقوبة المحكوم بها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,439,0,'ce669d8667be9779b7e286332d3ff1f7','7ff19ea5f348e5bb35d8a7767b6392bf',replace($m208$في غير الأحوال المنصوص عليها في هذا الباب ،يوقف التنفيذ أثناء الميعاد المقرر للاستئناف بالمادة  389 من هذا القانون وأثناء نظر الاستئناف الذي يرفع في المدة المذكورة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,440,0,'2911472e487f9b8b447d627964a91f8a','66e1d2a3a74423da3eeae872f32f18a8',replace($m208$يجوز تنفيذ الحكم الغيابي بالعقوبة إذا لم يعارض فيه المحكوم عليه في الميعاد المبين بالفقرة الأولى من المادة  380 من هذا القانون.
وللمحكمة عند الحكم بالتضمينات للمدعي بالحقوق المدنية أن تأمر بالتنفيذ المؤقت مع تقديم كفالة ولو مع حصول المعارضة أو الاستئناف بالنسبة لكل المبلغ المحكوم به أو بعضه ،ولها أن تعفي المحكوم له من الكفالة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,441,0,'12c62c52729dbe31f40cf47342fab20e','224fb0dc177b53aa16184c25cf00271d',replace($m208$يجوز للمحكمة عند الحكم غيابيا بالحبس مدة سنة فأكثر ،إذا لم يكن للمتهم محل إقامة معين بمصر ،أو إذا كان صادرا ضده أمر بالحبس الاحتياطي ،أن تأمر بناء على طلب النيابة العامة بالقبض عليه وحبسه.
ويحبس المتهم عند القبض عليه تنفيذًا لهذا الأمر حتى يحكم في المعارضة التي يرفعها ،أو ينقضي الميعاد المقرر لها ،ولا يجوز بأية حال أن يبقى في الحبس مدة تزيد على المدة المحكوم بها ،وذلك كله ما لم تر المحكمة المرفوعة إليها المعارضة الإفراج عنه قبل الفصل فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,442,0,'a550c343c952328f3f25b8ee5881bfeb','2d43181fac27f9d82d52b04424cd9bbe',replace($m208$مع مراعاة أحكام المادتين  36 مكررا 41 ،من القانون رقم  57 لسنة 1959 المشار إليه ،لا يترتب على الطعن بطريق النقض إيقاف التنفيذ إلا إذا كان الحكم صادرا بالإعدام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,443,0,'834cbf78de873bc0ffd5f1afeadbc849','ba82f6066814c9eb9380a4ed584a1f15',replace($m208$متى صار الحكم بالإعدام باتًا ،وجب على وزير العدل رفع أوراق الدعوى فورا إلى رئيس الجمهورية.
وينفذ الحكم إذا لم يصدر الأمر بالعفو أو بإبدال العقوبة خلال أربعة عشر يوما.$m208$,'<<CR>>',chr(13))),
('law',174,2025,444,0,'3fd78da8ba696cd7db691edc4b80de29','01e7836b55d0e258323ceb97523ab56b',replace($m208$يودع المحكوم عليه بالإعدام في مركز الإصلاح والتأهيل بناء على أمر تصدره النيابة العامة على النموذج الذي يقرره وزير العدل إلى أن ينفذ فيه الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,445,0,'52ffd91196b127d7e396135d2108c398','d906e239ea7208ba4a0b1947993f7768',replace($m208$يجوز لأقارب المحكوم عليه بالإعدام أن يقابلوه في اليوم السابق على اليوم المعين لتنفيذ الحكم ،على أن يكون ذلك بعيدا عن محل التنفيذ ،وعلى إدارة مركز الإصلاح إخطارهم بذلك.
وإذا كانت ديانة المحكوم عليه تفرض عليه الاعتراف أو غيره من الفروض الدينية قبل الموت ،وجب إجراء التسهيلات اللازمة لتمكين أحد رجال الدين من مقابلته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,446,0,'c92f62f0689f338b408ba42ba38ac600','76393bae0e8fbfeb2516ea66da4fdae3',replace($m208$تنفذ عقوبة الإعدام داخل مركز الإصلاح والتأهيل ،أو في مكان آخر مستور، بناء على طلب كتابي من النائب العام إلى مساعد الوزير لقطاع الحماية المجتمعية يبين فيه استيفاء الإجراءات المنصوص عليها في المادة  443 من هذا القانون.
ويجب على إدارة مراكز الإصلاح إخطار وزارة الداخلية والنائب العام باليوم المحدد للتنفيذ وساعته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,447,0,'fdcc9aa367e9895c653985557ede338d','6ac4c274844ef599a2e8abfa66511a8d',replace($m208$يجب أن يكون تنفيذ عقوبة الإعدام بحضور أحد أعضاء النيابة العامة ومندوب من قطاع الحماية المجتمعية ومندوب من وزارة الداخلية ومدير مركز الإصلاح والتأهيل وطبيب مركز الإصلاح وطبيب آخر تندبه النيابة العامة ،ولا يجوز لغير من ذكروا أن يحضروا التنفيذ إلا بإذن خاص من النيابة العامة ،ويجب دائما أن يؤذن للمدافع عن المحكوم عليه بالحضور.
ويجب أن يتلى من الحكم الصادر بالإعدام منطوقه والتهمة المحكوم من أجلها على المحكوم عليه ،وذلك في مكان التنفيذ بمسمع من الحاضرين ،وإذا رغب المحكوم عليه في إبداء أقوال حرر عضو النيابة العامة محضرا بها.
وعند تمام التنفيذ يحرر عضو النيابة العامة محضرا بذلك ،ويثبت فيه شهادة الطبيب بالوفاة وساعة حصولها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,448,0,'7aa14a35de24dd84353a4efb20a048d9','e36a1ca4853e27935afc3b2a4bb7d50f',replace($m208$لا يجوز تنفيذ عقوبة الإعدام في أيام الأعياد الرسمية أو الأعياد الخاصة بديانة المحكوم عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,449,0,'2ca92e6cae98ca17fc98bca3f3a18a9e','8ef51c58a43f79fdbd15ae9d7911e0e9',replace($m208$يوقف تنفيذ عقوبة الإعدام على المحكوم عليها الحبلى إلى ما بعد سنتين من وضعها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,450,0,'6f44dc334050ce6d9c05fc66ead5629b','b68ee90ae7708117fd0579e558514770',replace($m208$تسلم جثة المحكوم عليه بالإعدام إلى أهله إذا طلبوا ذلك ووافقت جهة الإدارة، ويجب أن يكون الدفن بغير احتفال ،فإذا لم يتقدم أحد منهم لاستلامها خلال أربع وعشرين ساعة أودعت أقرب مكان إلى مركز الإصلاح معد لحفظ الجثث ،فإذا لم يتقدم أحد منهم لتسلمها خلال سبعة أيام من تاريخ الإيداع سلمت إلى إحدى الجهات الجامعية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,451,0,'9a5eec8968f7689a96ddc84eaac54284','a7bfc82da08512cbbc3c1f17a012bfb6',replace($m208$تنفذ الأحكام الصادرة بالعقوبات المقيدة للحرية بمراكز الإصلاح والتأهيل المعدة لذلك بمقتضى أمر يصدر من النيابة العامة على النموذج الذي يقرره وزير العدل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,452,0,'dce79fc79192db92b081239517ecb984','8cfbffd55720b2d002b4a9aa0e508ef0',replace($m208$يجوز لكل محكوم عليه بالحبس البسيط لمدة لا تتجاوز ستة أشهر أن يطلب من النيابة العامة بدلاً من تنفيذ عقوبة الحبس عليه إلزامه بعمل للمنفعة العامة خارج مركز الإصلاح والتأهيل وفقا لما هو مقرر بالباب الخامس من هذا الكتاب ،وذلك ما لم ينص الحكم على حرمانه من ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,453,0,'e65c3ddc386114a5deba5f0f32354642','3978dc74d6b62e5fe099b8307903295f',replace($m208$يحسب اليوم الذي يبدأ فيه التنفيذ من مدة العقوبة ،ويفرج عن المحكوم عليه في اليوم التالي ليوم انتهاء العقوبة في الوقت المحدد للإفراج عن النزلاء.$m208$,'<<CR>>',chr(13))),
('law',174,2025,454,0,'f75871a155a5d1a6a4b96a9fa317abc7','40324a272f5ff9c3657bd0f589a8a483',replace($m208$إذا كانت مدة عقوبة الحبس المحكوم بها على المتهم أربعا وعشرين ساعة ينتهي تنفيذها في اليوم التالي للقبض عليه في الوقت المحدد للإفراج عن النزلاء.$m208$,'<<CR>>',chr(13))),
('law',174,2025,455,0,'658b733ce447413807e470b6b30cae2c','785297f97a30b40437e2ea0fe153c615',replace($m208$تبدأ مدة العقوبة المقيدة للحرية من يوم القبض على المحكوم عليه بناء على الحكم الواجب التنفيذ ،مع مراعاة نقصها بمقدار مدة الحبس الاحتياطي ومدة القبض ،والمدد الأخرى المنصوص قانونًا على خصمها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,456,0,'f5171cb2d174c9b4f85611422cdfe028','93264c856e457ac66fab7eb501991b3b',replace($m208$إذا حكم ببراءة المتهم من الجريمة التي حبس احتياطيا من أجلها ،وجب خصم مدة الحبس من المدة المحكوم بها في أية جريمة أخرى يكون قد ارتكبها أو حقق معه فيها في أثناء الحبس الاحتياطي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,457,0,'06358bce2f9f98488e0828852bd6ef75','9a0b0ef4c6650df1bcfd413ce031a7c3',replace($m208$يكون استنزال مدة الحبس الاحتياطي ومدة القبض عند تعدد العقوبات المقيدة للحرية المحكوم بها على المتهم من العقوبة الأخف أولاً.$m208$,'<<CR>>',chr(13))),
('law',174,2025,458,0,'a3dc0a7bd03948c7f2ecbaca3f90f6cc','b3ed898b62d93ee0df530f6131124dcd',replace($m208$إذا كانت المحكوم عليها بعقوبة مقيدة للحرية حبلى في الشهر السادس من الحمل، جاز تأجيل التنفيذ عليها حتى تضع حملها وتمضي مدة سنتين على الوضع.
فإذا رئي التنفيذ على المحكوم عليها أو ظهر في أثناء التنفيذ أنها حبلى ،وجبت معاملتها في مركز الإصلاح والتأهيل معاملة المحبوسين احتياطيا إلى أن تضع مولودها وتمضي أربعين يوما على الوضع.$m208$,'<<CR>>',chr(13))),
('law',174,2025,459,0,'d494c1998cff96d03d90cc9a546005ff','ea9b9cc5d023077e6d79e5ebd81d46ed',replace($m208$إذا كان المحكوم عليه بعقوبة مقيدة للحرية مصا با بمرض يهدد بذاته أو بسبب التنفيذ حياته بالخطر ،جاز تأجيل تنفيذ العقوبة عليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,460,0,'4d8a3e2f7ede6589a1c999b096facb2b','1ac2303c87b2e398c89683214ff08c7d',replace($m208$مع عدم الإخلال بحكم المادة  345 من هذا القانون ،إذا أصيب المحكوم عليه بعقوبة مقيدة للحرية قبل إيداعه وقبوله بمركز الإصلاح والتأهيل أو أثناء تنفيذ العقوبة باضطراب نفسي أو عقلي تندب النيابة العامة لجنة ثلاثية من الأطباء النفسيين المقيدين بسجلات المجلس القومي للصحة النفسية لإعداد تقرير طبي يتضمن تقييما لحالته النفسية والمرضية والخطة العلاجية المقترحة حال ثبوت إصابته باضطراب نفسي أو عقلي ،وتستنزل مدة الإيداع لإجراء التقييم الطبي من مدة العقوبة المقضي بها ،ويجب تأجيل تنفيذ العقوبة مؤقتًا حتى يبرأ ،مع توقيع الكشف الطبي النفسي عليه كل ستة أشهر لبيان إذا ما كان قد تماثل للشفاء من عدمه ،ويجوز للنيابة العامة أن تأمر بإيداعه لتلقي العلاج في إحدى منشآت الصحة النفسية الحكومية التي يصدر بتحديدها قرار من المجلس القومي للصحة النفسية ،وفي هذه الحالة تستنزل مدة الإيداع التي يقضيها المحكوم عليه من مدة العقوبة المحكوم بها ،وابتداء من التاريخ المحدد للانتهاء من تنفيذ العقوبة يعامل المحكوم عليه المودع باعتباره مريضا وفقًا لأحكام الدخول الإلزامي المنصوص عليها في قانون رعاية المريض النفسي المشار إليه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,461,0,'77d377694172552eadc6040520d9ba42','c2e21be75314f121c9c7a21b4dc34762',replace($m208$إذا كان محكوما على رجل وزوجته بالحبس لمدة لا تزيد على سنة ولو عن جرائم مختلفة ولم يكونا مسجونين من قبل ،جاز تأجيل تنفيذ العقوبة على أحدهما حتى يفرج عن الآخر ،وذلك إذا كانا يكفلان صغيرا لم يبلغ خمس عشرة سنة ،وكان لهما محل إقامة معروف بمصر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,462,0,'b89cce4bfe58b302fdd99c6c9f4ae3b8','b2dcee31c26d249860fbac5dadcaceca',replace($m208$للنيابة العامة في الأحوال التي يجوز فيها تأجيل تنفيذ العقوبة على المحكوم عليه أن تطلب منه تقديم كفالة بأنه لا يفر من التنفيذ عند زوال سبب التأجيل ،ويقدر مبلغ الكفالة في الأمر الصادر بالتأجيل.
ولها أيضا أن تشترط لتأجيل التنفيذ ما تراه من الاحتياطات الكفيلة بمنع المحكوم عليه من الهرب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,463,0,'9b164f24d99e3b24df0aefbd106d53de','7c0142e343a40c251e9a829f451ba073',replace($m208$لا يجوز في غير الأحوال المبينة في القانون إخلاء سبيل النزيل المحكوم عليه قبل أن يستوفي مدة العقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,464,0,'6905e42c2e320f2736fcd750d2be78f3','4f528ea1b7eb058bebfebf2937d7022e',replace($m208$يجب على النيابة العامة عند تسوية المبالغ المستحقة للدولة عن الغرامة وما يجب رده والتعويضات والمصاريف ،وقبل التنفيذ بها ،إعلان المحكوم عليه بمقدار هذه المبالغ ،ما لم تكن مقدرة في الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,465,0,'eab003b531c50ae4e25550651fb98027','f840157b5836f80702cfc27e803156bc',replace($m208$يجوز تحصيل المبالغ المستحقة للدولة بالطرق المقررة في قانون المرافعات المدنية والتجارية أو بالطرق الإدارية المقررة لتحصيل الأموال العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,466,0,'6babe17fe064ab1502de929ba1012ada','f908ab3cbf0651635af4e8a3030773d1',replace($m208$إذا لم يدفع المتهم المبالغ المستحقة للدولة ،تصدر النيابة العامة أمرا بالإلزام بعمل للمنفعة العامة وفقًا لأحكام الباب الخامس من هذا الكتاب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,467,0,'f022f44d49f0d3637b1fb5af36b6f010','567447edcecb75b34b4c5dcdaac15c50',replace($m208$إذا حكم بالغرامة وما يجب رده والتعويضات والمصاريف معا ،وكانت أموال المحكوم عليه لا تفي بذلك كله ،وجب توزيع ما يتحصل منها بين ذوي الحقوق على حسب الترتيب الآتي: )أولاً( المصاريف المستحقة للدولة.
)ثانيا( المبالغ المستحقة للمدعي المدني.
)ثالثًا( الغرامة وما تستحقه الحكومة من الرد والتعويض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,468,0,'f867551a12ae322ff87214043ba31d3d','ca9f6df5c5b841bb492e72b0a3616d23',replace($m208$إذا حبس شخص احتياطيا ،ولم يحكم عليه إلا بغرامة ،وجب أن ينقص منها عند التنفيذ خمسون جنيها عن كل يوم من أيام الحبس الاحتياطي .وإذا حكم عليه بالحبس وبالغرامة معا ،وكانت المدة التي قضاها في الحبس الاحتياطي تزيد على مدة الحبس المحكوم به ،وجب أن ينقص من الغرامة المبلغ المذكور عن كل يوم من أيام هذه الزيادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,469,0,'9c5f3997491e0bd15c3a75cff4b1f749','3d27738260111b44921e5da0375d4e60',replace($m208$يجوز لعضو النيابة العامة من درجة رئيس نيابة على الأقل في الجهة التي يجري التنفيذ فيها أن يمنح المتهم في الأحوال الاستثنائية ،بنا ء على طلبه ،أجلاً لدفع المبالغ المستحقة للدولة أو أن يأذن له بدفعها على أقساط ،بشرط ألا تزيد المدة على اثني عشر شهرا ،ولا يجوز الطعن في الأمر الذي يصدر بقبول الطلب أو رفضه.
وإذا تأخر المتهم عن دفع قسط حلت باقي الأقساط ،ويجوز لعضو النيابة العامة الرجوع في الأمر الصادر منه إذا وجد ما يدعو لذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,470,0,'5b3be38758d5526f93d3874d063fc56b','5b7755cd5ba39cce51f86fb0c2202ade',replace($m208$يجوز إلزام المحكوم عليه بعمل للمنفعة العامة لتحصيل المبالغ الناشئة عن الجريمة المقضي بها للدولة ضد مرتكب الجريمة ،وذلك بتشغيله في عمل للمنفعة العامة باعتبار يوم واحد عن كل خمسين جنيها أو أقل.
ولا يجوز في مواد المخالفات أن تزيد مدة هذا العمل على سبعة أيام للغرامة، وعلى سبعة أيام للمصاريف وما يجب رده والتعويضات.
وفي مواد الجنح والجنايات لا يجوز أن تزيد مدة هذا العمل على ثلاثة أشهر للغرامة ،وثلاثة أشهر للمصاريف وما يجب رده والتعويضات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,471,0,'040557bddf045a039c91b2dfb38294cc','769a4a1132d020d8e7fdf2ed7fb29c8b',replace($m208$لا يجوز التنفيذ بطريق الإلزام بعمل للمنفعة العامة على المحكوم عليهم الذين لم يبلغوا خمس عشرة سنة كاملة وقت ارتكاب الجريمة ،وكذلك المحكوم عليهم بعقوبة مع وقف التنفيذ.$m208$,'<<CR>>',chr(13))),
('law',174,2025,472,0,'f46c6cee654c8a8a3cfa559118f8e898','fea7e61686545b738009ac0209d86c77',replace($m208$تسري أحكام المواد  461 ،460 ،459 ،458 من هذا القانون على التنفيذ بطريق الإلزام بعمل للمنفعة العامة.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,473,0,'50d66fd546eb00d1729cbeac826fec2c','ac3a1693f7aa9222ae89676590af7a2d',replace($m208$يكون التنفيذ باعتبار مجموع المبالغ المحكوم بها إذا تعددت الأحكام وكانت كلها صادرة في مخالفات أو في جنح أو في جنايات ،وفي هذه الحالة لا يجوز أن تزيد مدة العمل للمنفعة العامة على ضعف الحد الأقصى في الجنح والجنايات ولا على واحد وعشرين يوما في المخالفات.
أما إذا كانت الجرائم مختلفة النوع فيراعى الحد الأقصى المقرر لكل منها.
وفي جميع الأحوال لا يجوز أن تزيد مدة العمل للمنفعة العامة على ستة أشهر للغرامات ،وستة أشهر للمصاريف وما يجب رده والتعويضات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,474,0,'cd609576f89c1b909e82f4fd5ed18649','8a937af56f08919d1ada54b3ec317c09',replace($m208$إذا كانت الجرائم المحكوم فيها مختلفة ،تُستنزل المبالغ المدفوعة أو التي تحصلت بطريق التنفيذ على ممتلكات المحكوم عليه أولاً من المبالغ المحكوم بها في الجنايات ثم في الجنح ثم في المخالفات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,475,0,'bef4c0a1fe3666ed96690dcfc02c8942','b372e9a66caa92718413d6fb86dcca02',replace($m208$يكون تنفيذ الإلزام بعمل للمنفعة العامة بأمر يصدر من النيابة العامة على النموذج المعد لهذا الغرض بعد إعلان المتهم طبقًا للمادة  464 من هذا القانون ،وبعد أن يكون قد أمضى جميع مدد العقوبات المقيدة للحرية المحكوم بها.
ويصدر بتحديد النموذج وأنواع الأعمال التي يجوز إلزام المحكوم عليه بالعمل فيها للمنفعة العامة والجهات الإدارية التي تتقرر بها هذه الأعمال ،قرار من النائب العام بالتنسيق مع الجهات المعنية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,476,0,'8d1b2271e56bf7de91b65af04e4fe548','41aeebedb6ae7374a798cb406e433fb3',replace($m208$ينتهي الإلزام بعمل للمنفعة العامة متى صار المبلغ الموازي للمدة التي قضاها المحكوم عليه في العمل للمنفعة العامة محسوبا على مقتضى ما هو مقرر في هذا الباب مساويا للمبلغ المطلوب أصلاً ،بعد استنزال ما يكون المحكوم عليه قد دفعه أو تحصل منه بالتنفيذ على ممتلكاته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,477,0,'0e38068cd8ed64c626ffab45742185b2','c4774c6eb43587bcdf68c8aa22373881',replace($m208$لا تبرأ ذمة المحكوم عليه من الغرامة والمصاريف وما يجب رده والتعويضات بتنفيذ الالتزام بعمل للمنفعة العامة ،إلا باعتبار خمسين جنيها عن كل يوم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,478,0,'86818e572778095e3be7a7d483302bd5','280c9a3ef4bd17330389fe17108f1c31',replace($m208$إذا لم يقم المحكوم عليه بتنفيذ الحكم الصادر بالتعويضات لغير الدولة بعد التنبيه عليه بالدفع ،يجوز لمحكمة الجنح التي يقع بدائرتها موطنه ،إذا ثبت لديها أنه قادر على الدفع ،وأمرته به فلم يمتثل ،أن تحكم بإلزامه بعمل للمنفعة العامة ،ولا يجوز أن تزيد مدة هذا التشغيل على ثلاثة أشهر ،ولا يخصم شيء من التعويض نظير هذا التشغيل في هذه الحالة ،وترفع الدعوى من المحكوم له بالطرق المعتادة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,479,0,'c523be53dcc5e9c64aa0d0b3065a011d','9d1abb1fe8f58a7ef5f4c08154c11d71',replace($m208$كل إشكال من المحكوم عليه في التنفيذ يرفع إلى محكمة الجنايات بدرجتيها إذا كان الحكم صادرا منها وإلى محكمة الجنح المستأنفة فيما عدا ذلك ،وينعقد الاختصاص في الحالين للمحكمة التي تختص محليا بنظر الدعوى المستشكل في تنفيذ الحكم الصادر فيها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,480,0,'83305eb4a9f93880f81b9eb1c6ac4f27','d0e124f9d4896d4dbe2e25e47c73a837',replace($m208$يقدم الإشكال إلى المحكمة بواسطة النيابة العامة على وجه السرعة ،ويعلن ذوو الشأن بالجلسة التي تحدد لنظره ،وتفصل المحكمة فيه في غرفة المشورة بعد سماع النيابة العامة وذوي الشأن .وللمحكمة أن تجري التحقيقات التي ترى لزومها ،ولها في كل الأحوال أن تأمر بوقف التنفيذ حتى يفصل في النزاع.
ويجوز للنيابة العامة عند الاقتضاء وقبل تقديم الإشكال إلى المحكمة أن توقف تنفيذ الحكم مؤقتا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,481,0,'237e5e4b2195e4d59641cafa770d98f1','5965da5e23d5159fb9cec4351d1726ac',replace($m208$مع عدم الإخلال بحق المحكمة في الأمر بحضور المستشكل شخصيا ،يجوز حضور وكيل عن المستشكل ،وفي جميع الأحوال يجوز للمحكمة أن تصدر قرارها في غيبة المستشكل.
ولا يجوز رد المحكمة التي تنظر الإشكال.
وإذا قدم المستشكل نفسه إشكالا آخر دون أسباب جدية تقضي المحكمة برفضه، ولها أن تغرم المستشكل مبلغًا مقداره خمسمائة جنيه.
ولا يعد الإشكال من الإجراءات التي يترتب عليها وقف أو قطع مدة سقوط العقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,482,0,'364ca9ce9b98f1517c4e44384dc02b95','ebfc6601fea69e0f878406fc75387029',replace($m208$إذا حصل نزاع في شخصية المحكوم عليه يفصل في ذلك النزاع بالكيفية والأوضاع المقررة في المادتين  481 ،480 من هذا القانون.
فإذا تبين للمحكمة أن المستشكل ليس هو المعني بالحكم تأمر بإخلاء سبيله وتحيل الأوراق إلى النيابة العامة لاتخاذ شئونها نحو المحكوم عليه الحقيقي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,483,0,'c1f19478c7830728c22d5cdd97e051e5','9ea0ae92b26ceb86f2dcbe323a4db72e',replace($m208$في حالة تنفيذ الأحكام المالية على أموال المحكوم عليه ،إذا قام نزاع من غير المتهم بشأن الأموال المطلوب التنفيذ عليها ،يرفع الأمر إلى المحكمة المدنية طبقًا لما هو مقرر في قانون المرافعات المدنية والتجارية.
ويستثنى من ذلك حالة إشكال الغير حسن النية في الحكم بمصادرة أمواله ،فتنظره المحكمة التي أصدرت الحكم المستشكل فيه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,485,0,'0fdfaff75d30c5cf7bc3155f8b79f8f9','875e0d02a06bc69098ab6f2fe4f92b85',replace($m208$تبدأ مدة سقوط العقوبة من وقت صيرورة الحكم باتًا ،إلا إذا كانت العقوبة محكوما بها غيابيا من محكمة الجنايات بدرجتيها في جناية فتبدأ المدة من يوم صدور الحكم.$m208$,'<<CR>>',chr(13))),
('law',174,2025,486,0,'560976bf48cf6608a86365deaffccb35','a960b48f0c46aab62b82ae789468d8a5',replace($m208$تنقطع مدة سقوط العقوبة بالقبض على المحكوم عليه بعقوبة مقيدة للحرية وبكل إجراء من إجراءات التنفيذ التي تتخذ في مواجهته أو تصل إلى علمه.
كما تنقطع المدة في غير مواد المخالفات إذا ارتكب المحكوم عليه خلالها جريمة من نوع الجريمة المحكوم عليه من أجلها أو مماثلة لها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,487,0,'79fdbcb3d29fc7f405f45f52a2973457','0e865971d4319606cc7113cae0a06a4c',replace($m208$يوقف سريان مدة سقوط العقوبة كل مانع يحول دون مباشرة التنفيذ سواء كان قانونيا أو ماديا ويعتبر وجود المحكوم عليه في الخارج مانعا يوقف سريان المدة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,488,0,'5be0281233a49d0292259119eefc2bb1','e5d51392fd2b20b7daa1d4a730f8bf39',replace($m208$تتبع الأحكام المقررة لمضي المدة في القانون المدني فيما يختص بالتعويضات وما يجب رده والمصاريف المحكوم بها .ومع ذلك فلا يجوز التنفيذ بطريق الإلزام بعمل للمنفعة العامة بعد مضي المدة المقررة لسقوط العقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,489,0,'0fa356acd106b07a2026dfc598ff189c','f126a36e86f70ed83c4f1708dcc6bcfd',replace($m208$مع مراعاة حكم الفقرة الثانية من المادة  148 من هذا القانون ،إذا مات المحكوم عليه بعد الحكم عليه بحكم بات ،تنفذ العقوبات المالية والتعويضات وما يجب رده والمصاريف في تركته.$m208$,'<<CR>>',chr(13))),
('law',174,2025,490,0,'399513334a26cf9f5e272fa4005790be','7f09b7157e5f33156b87ad4129a00d11',replace($m208$يجوز رد الاعتبار إلى كل محكوم عليه في جناية أو جنحة ،ويصدر الحكم بذلك من محكمة جنايات أول درجة التابع لها محل إقامة المحكوم عليه ،وذلك بناء على طلبه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,491,0,'7eff9668e01fc66b8cc811db67bebaf2','097f626d8d5b8ec90ffe007959e43919',replace($m208$يجب للحكم برد الاعتبار ما يأتي: )أولاً( أن تكون العقوبة قد نفذت تنفيذًا كاملاً ،أو صدر عنها عفو أو سقطت بمضي المدة.
)ثانيا( أن يكون قد انقضى من تاريخ تنفيذ العقوبة أو صدور العفو عنها مدة ست سنوات إذا كانت عقوبة جناية ،أو ثلاث سنوات إذا كانت عقوبة جنحة .وتضاعف هذه المدد في حالتي الحكم للعود وسقوط العقوبة بمضي المدة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,492,0,'6b7c21f59e6ebe4436d5cd46e8a189e1','fee7e386c0caab4a37987b70c1e56909',replace($m208$تبدأ المدة اللازمة لرد الاعتبار ،إذا كان المحكوم عليه قد وضع تحت مراقبة الشرطة بعد انقضاء العقوبة الأصلية ،من اليوم الذي تنتهي فيه مدة المراقبة.
وإذا كان قد أفرج عن المحكوم عليه تحت شرط ،فلا تبدأ هذه المدة إلا من التاريخ المقرر لانقضاء العقوبة أو من التاريخ الذي يصبح فيه الإفراج تحت شرط نهائيا.$m208$,'<<CR>>',chr(13))),
('law',174,2025,493,0,'8942ff4ae3b95bc5620a222b9e67d441','b36d396d61159598bcd0bd72ce1e9c78',replace($m208$يجب للحكم برد الاعتبار أن يوفي المحكوم عليه كل ما حكم به عليه من غرامة أو رد أو تعويض أو مصاريف .ويجوز للمحكمة أن تتجاوز عن هذا إذا أثبت المحكوم عليه أنه ليس بحال يستطيع معها الوفاء.
وإذا لم يوجد المحكوم له بالتعويضات أو الرد أو المصاريف ،أو امتنع عن قبولها ،وجب على المحكوم عليه أن يودعها طبقًا لما هو مقرر في قانون المرافعات في المواد المدنية والتجارية ،ويجوز له أن يستردها إذا مضت خمس سنوات ولم يطلبها المحكوم له.
وإذا كان المحكوم عليه قد صدر عليه الحكم بالتضامن ،يكفي أن يدفع مقدار ما يخصه شخصيا في الدين .وعند الاقتضاء تحدد المحكمة الحصة التي يجب عليه دفعها.$m208$,'<<CR>>',chr(13))),
('law',174,2025,494,0,'07336b1792f039d580d00920448a524f','2d629794f8196209dbf8bc135d721d43',replace($m208$في حالة الحكم في جريمة تفالس ،يجب على الطالب أن يثبت أنه قد حصل على حكم برد اعتباره التجاري.$m208$,'<<CR>>',chr(13))),
('law',174,2025,495,0,'8bf4338c03d09a11ebf9b7866fe845a3','8aed3381d36232d2556df55fa96ba908',replace($m208$إذا كان الطالب قد صدرت عليه عدة أحكام ،فلا يحكم برد اعتباره إلا إذا تحققت الشروط المنصوص عليها فى هذا الباب بالنسبة إلى كل حكم منها ،على أن يراعى في حساب المدة إسنادها إلى أحدث الأحكام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,496,0,'30097c10511746f2e92b6d7dd99540a1','c72d0c520099b357931155cddc3bcb33',replace($m208$يقدم طلب رد الاعتبار بعريضة إلى النيابة العامة ،ويجب أن يشتمل على البيانات اللازمة لتعيين شخصية الطالب ،وأن يبين فيها تاريخ الحكم الصادر عليه والأماكن التي أقام فيها منذ الإفراج عنه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,497,0,'0c378bc690783ba23099296772705f41','206c0ded9157d55170477d7677222519',replace($m208$تجري النيابة العامة تحقيقًا بشأن الطلب للاستيثاق من تاريخ إقامة الطالب في كل مكان نزله من وقت الحكم عليه ومدة تلك الإقامة ،وللوقوف على سلوكه ووسائل ارتزاقه ،وبوجه عام تتقصى كل ما تراه لازما من المعلومات وتضم التحقيق إلى الطلب وترفعه إلى المحكمة في الثلاثة الأشهر التالية لتقديمه بتقرير يدون فيه رأيها، وتبين الأسباب التي بني عليها ،ويرفق بالطلب: (1) صورة الحكم الصادر على الطالب.
(2) صحيفة الحالة الجنائية.
(3) تقرير عن سلوكه أثناء وجوده في مركز الإصلاح والتأهيل.$m208$,'<<CR>>',chr(13))),
('law',174,2025,498,0,'8bf5f51eda5fa4ecec7fc257287b8e75','96ac61ba953f974cacc671441e751ffb',replace($m208$تنظر المحكمة الطلب وتفصل فيه في غرفة المشورة ،ويجوز لها سماع أقوال النيابة العامة والطالب ،كما يجوز لها استيفاء كل ما تراه لازما من المعلومات.
ويكون إعلان الطالب بالحضور قبل الجلسة بثمانية أيام على الأقل.
ولا يقبل الطعن في الحكم إلا بطريق النقض لخطأ في تطبيق القانون أو في تأويله ،وتتبع في الطعن الأوضاع والمواعيد المقررة للطعن بطريق النقض في الأحكام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,499,0,'f507d8c0c507644a8a307e8e9eeddee1','e3644bd0184326bd593963b862b50745',replace($m208$تحكم المحكمة برد الاعتبار ،متى توافرت شروطه ،ورأت أن سلوك الطالب منذ صدور الحكم عليه يدعو إلى الثقة بتقويم نفسه.$m208$,'<<CR>>',chr(13))),
('law',174,2025,500,0,'12dfa118a8e0b9e86e8d5905a172839d','867a8cc1a7491fb8ccde492eca225b61',replace($m208$ترسل النيابة العامة صورة من حكم رد الاعتبار إلى المحكمة التي صدر منها الحكم بالعقوبة للتأشير به على هامشه ،وتأمر بأن يؤشر به في صحيفة الحالة الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,502,0,'083bfd32ef25e43d9633ca2878a63d9b','136ccd078b59f07899c0162dc49fab89',replace($m208$إذا رفض طلب رد الاعتبار بسبب راجع إلى سلوك المحكوم عليه ،فلا يجوز تجديده إلا بعد مضي سنتين من تاريخ الرفض ،أما في الأحوال الأخرى فيجوز تجديده متى توافرت الشروط اللازمة لرد الاعتبار.$m208$,'<<CR>>',chr(13))),
('law',174,2025,503,0,'39552bcf5c227e86d8899df01bd11e1f','fb1699ba33763cf58762bbb0dd256bde',replace($m208$يجوز إلغاء الحكم الصادر برد الاعتبار إذا ظهر أن المحكوم عليه صدرت ضده أحكام أخرى لم تكن المحكمة علمت بها ،أو إذا حكم عليه بعد رد الاعتبار في جريمة وقعت قبله.
ويصدر الحكم في هذه الحالة من المحكمة التي حكمت برد الاعتبار بناء على طلب النيابة العامة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,504,0,'ae4f421804346f689ab3ef5a1d6cc298','a81e97f84cb1a90d1676162e43479a2b',replace($m208$يرد الاعتبار بحكم القانون إذا لم يصدر خلال الآجال التالية على المحكوم عليه حكم بعقوبة في جناية أو جنحة مما يحفظ عنه بصحيفة الحالة الجنائية: )أولاً( بالنسبة إلى المحكوم عليه بعقوبة جناية أو بعقوبة جنحة في جريمة سرقة أو إخفاء أشياء مسروقة أو نصب أو خيانة أمانة أو تزوير أو شروع في هذه الجرائم وفي الجرائم المنصوص عليها في المواد  368 ،367 ،356 ،355 من قانون العقوبات متى مضى على تنفيذ العقوبة أو العفو عنها أو سقوطها بمضي المدة اثنتا عشرة سنة.
)ثانيا( بالنسبة إلى المحكوم عليه بعقوبة جنحة في غير الجرائم المشار إليها في هذه المادة متى مضى على تنفيذ العقوبة أو العفو عنها ست سنوات إلا إذا كان الحكم قد اعتبر المحكوم عليه عائدا أو كانت العقوبة قد سقطت بمضي المدة ،فتكون المدة اثنتي عشرة سنة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,505,0,'1d3194346d00ebff01ca617d230bfcaf','73edeed76b32dea3136fd243a868604e',replace($m208$إذا كان المحكوم عليه قد صدرت ضده عدة أحكام ،فلا يرد اعتباره إليه بحكم القانون إلا إذا تحققت بالنسبة لكل منها الشروط المنصوص عليها في المادة  504 من هذا القانون ،على أن يراعى في حساب المدة إسنادها إلى أحدث الأحكام.$m208$,'<<CR>>',chr(13))),
('law',174,2025,506,0,'55c039a3be19e51af9092e1f115059e5','43b646c88de752968aa905c0608d4ad2',replace($m208$يترتب على رد الاعتبار محو الحكم القاضي بالإدانة بالنسبة للمستقبل وزوال كل ما يترتب عليه من انعدام الأهلية والحرمان من الحقوق وسائر الآثار الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,507,0,'fce64d5e738c78b820a87bccfc289b98','12594beae8f3debd026588e49f4bb8fe',replace($m208$لا يجوز الاحتجاج برد الاعتبار على الغير فيما يتعلق بالحقوق التي تترتب لهم من الحكم بالإدانة ،وعلى الأخص فيما يتعلق بالرد والتعويضات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,508,0,'49251b14e1b75881ea8281b9ae76b6c4','d21f4adb49ddf58068d270006c19ff57',replace($m208$مع عدم الإخلال بأحكام الاتفاقيات متعددة الأطراف أو الثنائية النافذة التي تكون جمهورية مصر العربية طرفًا فيها ،ومع مراعاة مبدأ المعاملة بالمثل ،يعمل بأحكام هذا الكتاب في شأن التعاون القضائي الدولي في المسائل الجنائية ،وتسري القواعد العامة في كل ما لم يرد بشأنه نص خاص في هذا الكتاب وبما لا يتعارض مع أحكامه.
وتختص هيئة القضاء العسكري بالنظر في كافة طلبات التعاون القضائي الدولي التي تدخل في اختصاصها ولائيا ،وتتولى النيابة العسكرية ممارسة الاختصاصات المقررة للنيابة العامة وفقًا لأحكام هذا الكتاب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,509,0,'d83568bfb521c6d8e22b31e2e99689cf','b6cd9b32d47a38ee427747ed1071e991',replace($m208$للجهات القضائية المصرية التعاون مع نظيراتها الأجنبية في مكافحة وملاحقة الجرائم بشتى صورها من خلال طلبات المساعدة القضائية وتسليم المجرمين والأشياء واسترداد الأموال أو الأصول ونقل المحكوم عليهم وغير ذلك من صور التعاون القضائي الدولي في المسائل الجنائية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,510,0,'d92c1893a51b25931de25ef7ee47c6bb','49c8224dd36c96868093b4750b0a8df6',replace($m208$للجهات القضائية المصرية والأجنبية أن تطلب اتخاذ الإجراءات القانونية اللازمة لتعقب أو ضبط أو تجميد أو إدارة الأموال أو الأصول أو الأشياء موضوع الجريمة أو عائداتها أو الحجز عليها ،أو تنفيذ الأحكام الجنائية النهائية باسترداد أو مصادرة الأموال أو الأصول أو الأشياء المتحصلة من الجرائم أو عائداتها مع عدم الإخلال بحقوق الغير حسن النية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,511,0,'5791d89ecb789709c8c125f048e4afe0','a94b199a45e69482876c8340f7059973',replace($m208$ترسل طلبات التعاون القضائي الدولي في المسائل الجنائية الواردة من الجهات القضائية الأجنبية عبر الطريق الدبلوماسي إلى وزارة العدل متضمنة ملخص الواقعة، ونوع وموضوع الطلب المترجم إلى اللغة العربية.
ويجب أن يرفق بالطلب المستندات المؤيدة له.
وتتولى وزارة العدل التحقق من مدى توفر الشروط المبينة بالفقرة الأولى من هذه المادة ،ولها أن تتخذ أيا من الإجراءين الآتيين: أولاً :حفظ الطلب إذا تبين لها عدم توفر الشروط المشار إليها مع إخطار الجهة الطالبة بأسباب الحفظ عبر الطريق الدبلوماسي.
ثانيا :إحالة الطلبات المستوفاة للشروط المشار إليها إلى النيابة العامة لإعمال شئونها طبقًا لأحكام هذا الكتاب.$m208$,'<<CR>>',chr(13))),
('law',174,2025,512,0,'26bdc3b213437b0da188b716870e1cab','0bf463a976788ac1f230613c37313244',replace($m208$ترسل وزارة العدل طلبات التعاون القضائي الدولي في المسائل الجنائية التي توجه من النيابة العامة إلى الجهات القضائية الأجنبية عبر الطريق الدبلوماسي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,513,0,'ffa4994a1c79d105e5fa5b3dc86efe77','196e0a0e02f002d41044cd0be02c0a97',replace($m208$يجوز للنيابة العامة أن تصدر أمرا مسببا بالقبض على المطلوب تسليمه بناء على طلب الجهة القضائية الأجنبية ،ولوزارة الداخلية القبض على المطلوب تسليمه بناء على أمر قبض صادر من جهة قضائية أجنبية وفقًـا للقواعد المنظمة لعمل إدارة الشرطة الجنائية العربية والدولية )إنتربول القاهرة(.
ويعرض كل من يقبض عليه تنفيذًا لحكم الفقرة الأولى من هذه المادة على النيابة العامة خلال أربع وعشرين ساعة من وقت القبض عليه ،والتي تباشر معه إجراءات التحقيق في التهمة المنسوبة إليه والمبينة بالطلب وذلك بحضور محاميه ،مع إعمال حكم المادتين  112 ،105 من هذا القانون.
ويجوز لعضو النيابة العامة من درجة رئيس نيابة على الأقل أن يأمر بحبس المطلوب تسليمه احتياطيا لمدة أو مدد متعاقبة لا تجاوز كل منها خمسة عشر يوما، وبحيث لا تزيد المدة في مجموعها على ستين يوما لحين ورود طلب التسليم والفصل فيه ،ويخضع أمر الحبس وتسبيبه ومد مدده والطعن فيه للأحكام الواردة بهذا القانون.
وللنائب العام أو من يفوضه إدراج المطلوب تسليمه على قوائم الممنوعين من السفر أو وضع اسمه على قوائم ترقب الوصول وفقًا للإجراءات المنصوص عليها في هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,514,0,'bb7f9e6a4e2bf641894eddd6f3e7b2f0','420af03820ded866a471a08e89872566',replace($m208$لا يجوز تسليم الأشخاص في أي من الحالات الآتية: 1- إذا كان المطلوب تسليمه مصري الجنسية ،ويجوز للجهة القضائية الأجنبية تقديم طلب محاكمته مصحوبا بالتحقيقات التي أجرتها الدولة الطالبة والمستندات، ويتعين إخطار الجهة القضائية الأجنبية بما آلت إليه الدعوى الجنائية ،وموافاتها بنسخة من التصرف النهائي في فترة زمنية مناسبة.
2- إذا كانت الجريمة موضوع طلب التسليم غير معاقب عليها وفقًـا لأحكام القانون المصري.
3- إذا انعقد الاختصاص للجهات القضائية المصرية بالجريمة المطلوب التسليم من أجلها.
4- إذا كانت الجريمة موضوع الطلب جريمة سياسية أو جريمة مرتبطة بها.
5- إذا كانت الجريمة المطلوب التسليم من أجلها تنحصر في الإخلال بواجبات عسكرية.
6- إذا قُصد بطلب التسليم معاقبة شخص لأسباب تتعلق بانتمائه العرقي أو الديني أو لجنسيته أو لآرائه السياسية ،أو أن يكون من شأن توافر أي من هذه الأسباب الإضرار بمركز المطلوب تسليمه.
7- إذا صدر حكم بات بالبراءة أو الإدانة في الجريمة المطلوب التسليم من أجلها في جمهورية مصر العربية أو في دولة أخرى ،ونفذت العقوبة المحكوم بها.
8- إذا انقضت الدعوى الجنائية ،أو سقطت العقوبة المقضي بها بمضي المدة، وفقًا للقانون المصري أو قانون الدولة الطالبة النافذ عند تلقي طلب التسليم.
9- إذا صدر عفو شامل عن الجريمة محل طلب التسليم ،أو عفو عن العقوبة المقضي بها على الشخص المطلوب تسليمه ،أو عن المدة المتبقية منها ،أو أبدلت العقوبة أو خُففت إلى عقوبة أخرى لا تتوافر بشأنها الشروط المتطلبة للتسليم وفقًـا للقانون المصري أو قانون الدولة الطالبة.
10- إذا لم تتوافر ضمانات المحاكمة العادلة وحقوق الإنسان للمطلوب تسليمه في الدولة طالبة التسليم.
11- إذا توافرت إحدى حالات الحصانة المقررة بمقتضى الاتفاقيات الدولية النافذة في جمهورية مصر العربية أو وفقًا للمستقر عليه في الأعراف الدولية.
12- إذا تعارض طلب التسليم مع مقتضيات صون السيادة ،أو الأمن القومي، أو النظام العام.
13- إذا كان المطلوب تسليمه لاجئًا سياسيا.$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('law',174,2025,515,0,'783b14525f632c24692bec3230b8f53e','1386d1b8740041d552d7cebf77eee3ea',replace($m208$يصدر النائب العام أو من يفوضه قرارا مسببا في طلب التسليم ،ويجوز لكل من صدر قرار بتسليمه ،أن يطعن فيه أمام محكمة جنح مستأنف عابدين أو المحكمة العسكرية للجنح المستأنفة بالقاهرة بحسب الأحوال ،وذلك بتقرير بالطعن بقلم كتاب المحكمة خلال مدة لا تزيد على سبعة أيام من تاريخ إعلانه بالقرار ،وتحدد في التقرير جلسة لنظر الطعن والفصل فيه خلال مدة لا تزيد على سبعة أيام ،ويعتبر التقرير بالطعن إعلانًا بالجلسة المحددة ولو كان التقرير من وكيل ،ويفصل في الطعن بقرار مسبب لا يقبل الطعن فيه ،ولا ينفذ القرار الصادر بالتسليم إلا عقب الفصل في الطعن أو فوات مواعيده.$m208$,'<<CR>>',chr(13))),
('law',174,2025,516,0,'378dbfe3e57ebc17250065a496cfea92','a2ed4da25ac2c6cb1176d53e628f2b1f',replace($m208$يجوز للنيابة العامة أن تطلب من الجهة القضائية الأجنبية تسليم المتهم أو المحكوم عليه ،وفي حالة رفض التسليم لها أن تطلب محاكمته وفقًا لقانون الدولة المطلوب منها ،ويجوز للنيابة العامة أن تصدر أمرا مسببا بالقبض على المطلوب تسليمه ،وتعتبر مدة حبسه التي تمت بالخارج مدة حبس احتياطي في شأن تطبيق قواعد تنفيذ العقوبة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,517,0,'a5101d832b3ce8978d3d051cdb586a1a','ff51ac0409378c8b37dc64dba5f08873',replace($m208$يجوز للنائب العام ،أو من يفوضه ،بناء على طلب الجهة الطالبة ووفقًا للشروط التي يتم الاتفاق عليها ،أن يأذن بدخول أشياء تعد حيازتها جريمة أو متحصلة من جريمة أو أداة في ارتكابها إلى داخل البلاد أو عبورها إلى خارجها ،دون ضبطها، أو استبدالها كليا أو جزئيا ،وذلك تحت رقابة السلطات المصرية المختصة ،متى كان من شأن ذلك التعرف على وجهة تلك الأشياء أو ضبط الجناة ،وما بحوزتهم.
ولا يجوز إصدار الإذن المشار إليه في الفقرة الأولى من هذه المادة ،إذا كان من شأن تنفيذه الإضرار بالأمن أو سيادة الدولة أو النظام العام أو الآداب العامة أو يتعارض مع مقتضيات الأمن القومي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,518,0,'2bebd53e45f62a662745fef7fdd4c7b5','51025eb54d7e29b5ad4a99929ef9dde1',replace($m208$يشترط لإجابة طلب المساعدة القضائية المقدم من الجهة القضائية الأجنبية توافر الشروط الآتية: 1- أن يتعلق طلب المساعدة القضائية بجريمة معاقب عليها في الدولة الطالبة، وتدخل في اختصاص جهاتها القضائية ولو كانت جريمة مدرجة تحت وصف آخر.
2- أن تكون المساعدة القضائية مرتبطة بمباشرة إجراءات قضائية في دعوى جنائية منظورة أمام الجهة القضائية الأجنبية.
3- ألا يكون من شأن تنفيذ طلب المساعدة القضائية الإضرار بالأمن أو سيادة الدولة أو النظام العام أو الآداب العامة أو التعارض مع مقتضيات الأمن القومي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,519,0,'4911f621dd180a3a34d07161ee88f114','5f115ea7d8318c7f6c9943550c158a5a',replace($m208$يجوز للنيابة العامة رفض طلب المساعدة القضائية في الحالات الآتية: 1- إذا كانت الجريمة موضوع طلب المساعدة القضائية غير معاقب عليها وفقًـا لأحكام القانون المصري.
2- إذا كانت الجريمة موضوع طلب المساعدة القضائية جريمة سياسية أو جريمة مرتبطة بها.
3- إذا كانت الجريمة موضوع طلب المساعدة القضائية تنحصر في الإخلال بواجبات عسكرية.
4- إذا قُصد بطلب المساعدة القضائية معاقبة شخص لأسباب تتعلق بانتمائه العرقي أو الديني أو لجنسيته أو لآرائه السياسية ،أو أن يكون من شأن توافر أي من هذه الأسباب الإضرار بمركزه القانوني.
5- إذا انعقد الاختصاص للجهات القضائية المصرية بالجريمة المطلوب المساعدة القضائية من أجلها.
6- إذا تعارض تنفيذ طلب المساعدة القضائية مع مبدأ عدم جواز محاكمة الشخص عن ذات الجريمة أكثر من مرة.
7- إذا انقضت الدعوى الجنائية ،أو سقطت العقوبة المقضي بها بمضي المدة، وفقًا للقانون المصري أو قانون الدولة الطالبة النافذ عند تلقي طلب المساعدة القضائية.
8- إذا كان تنفيذ طلب المساعدة القضائية يخرج عن اختصاص الجهات القضائية المصرية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,520,0,'7fc37917c40fb90f4ab6365ee561b655','ba51b96286826f62246c9a7a70eae24a',replace($m208$يصدر النائب العام أو من يفوضه قرارا في طلب المساعدة القضائية المقدم من الجهات القضائية الأجنبية ،وفى حالة الموافقة ينفذ على وجه السرعة.$m208$,'<<CR>>',chr(13))),
('law',174,2025,521,0,'0a4368b321db4e18e30a51cb4a3628b0','6aabd4a7c15b11560aa6a10854e5d47a',replace($m208$استثناء من أحكام هذا الكتاب ،يجوز لرئيس الجمهورية بناء على عرض النائب العام وبعد موافقة مجلس الوزراء ،الموافقة على تسليم المتهمين ونقل المحكوم عليهم إلى دولهم ،وذلك لمحاكمتهم أو تنفيذ العقوبة المقضي بها عليهم بحسب الأحوال ،متى اقتضت مصلحة الدولة العليا ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,522,0,'557ceefcda8c7ac705f60aef40ce33d0','c1ba35995ec9c6efbcffbb6e897ae25c',replace($m208$مع عدم الإخلال بالاتفاقيات الدولية التي تكون جمهورية مصر العربية طرفًـا فيها ،يعمل بأحكام هذا الباب في شأن حماية المجني عليهم والشهود والمتهمين والمبلغين عند الاقتضاء.$m208$,'<<CR>>',chr(13))),
('law',174,2025,523,0,'ce9a0b8178518eee314afdd9c23ee904','3fef5edcdb9846fca779588036fef59d',replace($m208$يجوز للشاهد بناء على إذن النيابة العامة ،أو قاضي التحقيق المختص أن يتخذ من مقر الشرطة التابع له محل إقامته أو من مقر عمله عنوانًا له.$m208$,'<<CR>>',chr(13))),
('law',174,2025,524,0,'acdcca034447954bc9762af29336902a','2defb8d69fb65e78b50a6253cfe9e3d4',replace($m208$في الأحوال التي يكون فيها من شأن سماع أقوال أي إنسان تعريض حياته، أو سلامته ،أو أحد أفراد أسرته للخطر ،يجوز لمحكمة الموضوع أو للمحامي العام، أو قاضي التحقيق بناء على طلب هذا الشخص أو أحد مأموري الضبط القضائي الأمر بسماع أقواله مع ذكر بيانات لا تكشف عن هويته ،على أن ينشأ ملف فرعي للقضية يتضمن تحديدا لشخصيته وبياناته الحقيقية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,525,0,'37626d713c50a9010562013af7b610b4','2a8cf83b9e023d737cf5bd45c4cc563f',replace($m208$في الأحوال التي يكون فيها الكشف عن هوية الشخص لا غنى عنها لمباشرة حقوق الدفاع يجوز للمتهم أو وكيله الطعن على الأمر الصادر من المحامي العام أو قاضي التحقيق بإخفاء بياناته ،أمام محكمة جنايات أول درجة منعقدة في غرفة مشورة ،خلال عشرة أيام من تاريخ مواجهته بفحوى هذه الشهادة ،وتفصل المحكمة في الطعن بعد سماع ذوي الشأن بقرار نهائي مسبب ،وذلك دون إخلال بحق محكمة الموضوع في إلغاء هذا الأمر ،أو استدعاء هذا الشخص لسماع أقواله.$m208$,'<<CR>>',chr(13))),
('law',174,2025,526,0,'61d123a9c9c6f9782adcabc84094eaf8','956a258525a80196243a7cc2bb24f566',replace($m208$يجوز للمتهم أثناء المحاكمة أن يطلب مواجهة أو مناقشة الشخص الصادر أمر بإخفاء بياناته ،بما لا يكشف عن شخصيته ،وذلك كله وفقًـا لإجراءات التحقيق والمحاكمة عن بعد المنصوص عليها في هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,527,0,'ef67a879af2b87a8b159d54686b43248','693aaa61951cad7177ea2374157d24eb',replace($m208$مع عدم الإخلال بأي عقوبة أشد منصوص عليها في أي قانون آخر ،يعاقب كل من أدلى بأي بيانات عن الشخص الصادر أمر بإخفاء هويته بالحبس والغرامة التي لا تقل عن خمسين ألف جنيه ،أو بإحدى هاتين العقوبتين ،وتكون العقوبة السجن المشدد إذا ارتكبت الجريمة تنفيذًا لغرض إرهابي ،وفي جميع الأحوال تكون العقوبة الإعدام أو السجن المؤبد إذا نجم عن الفعل موت شخص.$m208$,'<<CR>>',chr(13))),
('law',174,2025,528,0,'366614575851759617c5425972ff437f','95d235ca1faf2e596c4a3fb19c0656a4',replace($m208$يستحق كل من حبس احتياطيا تعويضا في الحالات الآتية: 1- إذا كانت الواقعة محل الاتهام معاقبا عليها بالغرامة ،أو جنحة معاقبا عليها بالحبس مدة تقل عن سنة ،وكان للمتهم محل إقامة ثابت ومعلوم في جمهورية مصر العربية.
2- إذا صدر أمر نهائي بأن لا وجه لإقامة الدعوى الجنائية لعدم صحة الواقعة.
3- إذا صدر حكم بات ببراءته من جميع الاتهامات المنسوبة إليه مبنيا على أن الواقعة غير معاقب عليها ،أو غير صحيحة ،أو أي أسباب أخرى بخلاف حالات البطلان أو التشكك في صحة الاتهام أو أسباب الإباحة أو الإعفاء من العقاب، أو العفو ،أو امتناع المسئولية.
ويسري حكم البند (3) من الفقرة الأولى من هذه المادة في شأن استحقاق تعويض لمن نفذ عقوبة سالبة للحرية صدر حكم بات بإلغاء الحكم المنفذة بموجبه.
وفي جميع الأحوال تتحمل الخزانة العامة للدولة التعويضات المشار إليها في هذه المادة ،بشرط ألا يكون طالب التعويض تم حبسه احتياطيا ،أو نفذ عقوبة مقيدة للحرية على ذمة قضية أو قضايا أخرى عن فترة مماثلة أو تزيد على مدة الحبس الاحتياطي أو تنفيذ العقوبة محل طلب التعويض.$m208$,'<<CR>>',chr(13))),
('law',174,2025,529,0,'e2abd689237bc40c0c880a6fe0ad8d1a','83604aae89334d9aa3db6dab91bb2562',replace($m208$يرفع طلب التعويض المشار إليه بالمادة  528 من هذا القانون بالطرق المعتادة لرفع الدعاوى ،ويتبع في شأن إجراءاته والحكم فيه والطعن عليه القواعد المنصوص عليها في قانون المرافعات المدنية والتجارية.$m208$,'<<CR>>',chr(13))),
('law',174,2025,530,0,'3917fcc8b6c4fa06072dffa5bae78f01','93b9494dc21f0d4c01bdfdea2f9da06c',replace($m208$مع عدم الإخلال بالقواعد والمواعيد والمدد وغيرها من إجراءات التقاضي المنصوص عليها في هذا القانون ،تسري أحكام هذا الباب على إجراءات التحقيق والمحاكمة عن بعد باستخدام وسائل وتقنيات الاتصال الحديثة المسموعة والمرئية، وذلك كُله بما يضمن أحكام سرية التحقيقات والحضور والعلانية وشفوية المرافعة والمواجهة بين الخصوم الواردة في هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,531,0,'2691b99302533024d2c5e60f12394db0','39b2b36046ded4a681594da05fff736f',replace($m208$يجوز لجهة التحقيق أو المحاكمة المختصة بحسب الأحوال اتخاذ كل أو بعض إجراءات التحقيق أو المحاكمة عن بعد مع المتهمين ،والشهود ،والمجني عليهم، والخبراء ،والمدعين بالحقوق المدنية ،والمسئولين عنها ،المنصوص عليها في هذا القانون.
ويجوز لها اتخاذ تلك الإجراءات فيما يتعلق بالنظر في أمر الحبس الاحتياطي والتدابير ومدهما والإفراج المؤقت واستئناف أوامرها.
ولها بحسب الأحوال أن تقرر منع الكشف عن الشخصية الحقيقية للشهود بجميع وسائل وتقنيات الاتصال الحديثة المناسبة أثناء الإدلاء بأقوالهم ،وذلك كُله مع مراعاة حكم المادة  525 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,532,0,'1a60386739a0c24499623f4d09c94842','b309e694af16660084decd10a6048bbf',replace($m208$مع عدم الإخلال بأحكام قانون الطفل يجوز اتخاذ الإجراءات عن بعد مع الأطفال ،ولجهة التحقيق والمحاكمة المختصة إعفاء الطفل من الحضور أمامها، والاكتفاء بالاطلاع على تسجيلات تلك الإجراءات إذا رأت أن مصلحته تقتضي ذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,533,0,'4630ec2f7bfca2836f380d33cf5a3397','9e1c8a108eb615ae423a23710cf137eb',replace($m208$يتعين على جهة التحقيق أو المحاكمة المختصة بحسب الأحوال إعلان الخصوم بموعد ومكان انعقاد جلسة التحقيق أو المحاكمة التي ستتم عن بعد ،على أن يكون المكان تم تجهيزه وتهيئته لإجراءات التحقيق والمحاكمة عن بعد وفقًا لحكم المادة 537 من هذا القانون.$m208$,'<<CR>>',chr(13))),
('law',174,2025,534,0,'0ad2917cc9f08510d4215bbe2367f35d','95dc7cf64f283b0fb770dd2ee359b504',replace($m208$يكون لجهات التحقيق والمحاكمة المختصة أن تتخذ ما تراه مناسبا لتسجيل وحفظ جميع الإجراءات التي تتم من خلال وسائل وتقنيات الاتصال الحديثة عن بعد، وتفريغها في محاضر ،ولها أن تستعين بأحد الخبراء في ذلك ،وتودع ملف القضية.
ويضع كل من عضو النيابة العامة أو قاضي التحقيق أو رئيس الدائرة والكاتب توقيعه على كل ورقة دون الحاجة إلى توقيع أي من المتهمين أو الشهود أو الخبراء أو المترجمين أو أي توقيع آخر.$m208$,'<<CR>>',chr(13))),
('law',174,2025,536,0,'6ce859091a986d418b68a00835b9c0e3','89cfb5ccd44bee9bb3a9e8568329afe3',replace($m208$يحضر المتهم الجلسة بغير قيود ولا أغلال ،وتجري عليه الملاحظة اللازمة.
ولمحامي المتهم مقابلته ،والحضور معه في مكان تواجده ،وأثناء إجراءات التحقيق والمحاكمة عن بعد.
وفي جميع الأحوال ،لا يجوز الفصل بين المتهم ومحاميه أثناء اتخاذ تلك الإجراءات.$m208$,'<<CR>>',chr(13))),
('law',174,2025,537,0,'ae46750feb0969b27220444d7f30a6c0','2d6d4f6b05c6b5e24faa2fe5201f44c2',replace($m208$تقوم وزارة العدل بالتعاون والتنسيق مع وزارة الداخلية والجهات والوزارات المعنية ،بإعداد القاعات وأجهزة الاتصال المطلوبة لتنفيذ إجراءات التحقيق والمحاكمة عن بعد باستخدام وسائل وتقنيات الاتصال الحديثة في الجهات المختصة ،وفي المؤسسات العقابية ومراكز الإصلاح والتأهيل ،وغير ذلك من الإدارات ذات الصلة وتقديم المساعدة الفنية اللازمة لذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,539,0,'ded4331a09610700fe4959d20d5d3ff2','a57431a97dc4af090fea3db122e8e6ae',replace($m208$تُحسب جميع المدد المبينة في هذا القانون بالتقويم الميلادي.$m208$,'<<CR>>',chr(13))),
('law',174,2025,540,0,'f31f53688de32f99c48eefffbd498dbf','523a0130eb06fde195592d930e549be8',replace($m208$تلتزم نقابات المحامين الفرعية أو النقابة العامة إذا كانت النقابة الفرعية غير قائمة أو في حال وجود مانع بالتنسيق مع رئيس المحكمة الابتدائية المختصة في بداية كل عام قضائي وكلما اقتضت الحاجة لذلك بإعداد قوائم بعدد كاف من المحامين يتم تسجيلهم في سجل خاص ينشأ لهذا الغرض بالمحكمة الابتدائية المختصة ،يدون به جميع بياناتهم ويرسل رئيس المحكمة الابتدائية صورة رسمية منها إلى المحاكم والنيابات التي تقع في دائرة اختصاص المحكمة الابتدائية للندب من بينهم أمام جهات التحقيق أو المحاكمة بحسب الأحوال.$m208$,'<<CR>>',chr(13))),
('law',174,2025,542,0,'5e3ed630d277a436e8b9f15b0965c438','e759df3da2350c4be83ec222e27d389c',replace($m208$إذا وجدت صورة رسمية من الحكم ،فإنها تقوم مقام النسخة الأصلية.
وإذا كانت الصورة الرسمية من الحكم تحت يد شخص أو جهة ما ،تستصدر النيابة العامة أمرا من رئيس المحكمة التي أصدرت الحكم بتسليمها ،ولمن أخذت منه أن يطلب تسليمه صورة مطابقة بغير مصاريف.$m208$,'<<CR>>',chr(13))),
('law',174,2025,544,0,'cc9617a84136e58b016eaeb3da4f559b','c7e07ea91bfbb7a5aaa361c1906be166',replace($m208$إذا كانت القضية منظورة أمام محكمة النقض ولم يتيسر الحصول على صورة رسمية من الحكم ،تقضي المحكمة بإعادة المحاكمة متى كانت جميع الإجراءات المقررة للطعن قد استوفيت.$m208$,'<<CR>>',chr(13))),
('law',174,2025,545,0,'48a57693eb0e2349ce70feb5a6ac0ad0','5ab1c5904cc2201222e8abff746b364d',replace($m208$إذا فقدت أوراق التحقيق كلها أو بعضها قبل صدور قرار فيه ،يعاد التحقيق فيما فقدت أوراقه.
وإذا كانت القضية مرفوعة أمام المحكمة ،تتولى هي إجراء ما تراه من التحقيق، ولها إرسال الأوراق إلى النيابة العامة أو قاضي التحقيق بحسب الأحوال ،لإعادة التحقيق فيما فقدت أوراقه إذا رأت محلاً لذلك.$m208$,'<<CR>>',chr(13))),
('law',174,2025,546,0,'5b43018cf7216e061739407124f262fc','7632e82b52d7b93bff88444c62a3299e',replace($m208$إذا فقدت أوراق التحقيق كلها أو بعضها ،وكان الحكم موجودا والقضية منظورة أمام محكمة النقض ،فلا تعاد الإجراءات إلا إذا رأت المحكمة محلاً لذلك.$m208$,'<<CR>>',chr(13))),
('pm_decision',3973,2025,1,0,'c191f841aca58f2669260683ed549654','945b9f24a2486886fe0dff742459710a',replace($m208$في تطبيق أحكام هذا النظام ،يعمل بالتعاريف الواردة بالمادة (1) من قانون تنظيم<<CR>>
