('regulation',991,2005,59,0,'e633c1c0761e29203c812bb91ac21c90','6ffa92574c7b072c0c24c076275227e5',replace($m208$مع مراعاة أحكام المادتين السابعة من القانون رقم 91 لسنة 2005 والبند [1] من المادة (52) من القانون يُحسب متوسط حقوق الملكية وفقاً للمعادلة الآتية:
حقوق الملكية أول السنة المالية + حقوق الملكية آخر السنة المالية
2
ويُحسب متوسط القروض والسلفيات، فى تطبيق حكم المادة ذاتها، طبقاً للمعادلة الآتية:
رصيد القروض والسلفيات أول المدة + رصيد القروض والسلفيات آخر المدة
2
وذلك مع مراعاة استبعاد القروض الحسنة والقروض التى لها عوائد غير خاضعة للضريبة والقروض التى لها فترة سماح لسداد العوائد فقط لحين انتهاء هذه الفترة من القروض والسلفيات التى حصل عليها الشخص الاعتبارى عند مقارنة نسبة متوسط القروض والسلفيات إلى متوسط حقوق الملكية وفقاً لحكم هذه المادة.$m208$,'<<CR>>',chr(13))),
('regulation',286,2021,1,0,'693ed9a457b4f649de22a18417934b39','cec6cc45d7b14d8b19d4ee154e57f5fd',replace($m208$فى تطبيق أحكام هذه اللائحة ، يُقصد بالألفاظ والعبارات التالية المعنى المبين قرين كل منها :
الوزير : وزير المالية .
رئيس المصلحة : رئيس مصلحة الضرائب المصرية .
القانون : قانون الإجراءات الضريبية الموحد الصادر بالقانون رقم 206 لسنة 2020 .
المصلحة : مصلحة الضرائب المصرية .
المنطقة : المنطقة التى يقع فى دائرة اختصاصها مأمورية الضرائب المختصة .
المأمورية المختصة : مأمورية الضرائب التى يقع فى دائرتها مركز مزاولة نشاط الممول أو المكلف أو التى أصدرت البطاقة الضريبية أو شهادة التسجيل ، وإذا تعددت منشآت الممول أو المكلف وفروعها تكون المأمورية المختصة هى المأمورية التى يقع فى دائرتها المركز الرئيسى للنشاط من واقع السجل التجارى ، ويجوز لرئيس المصلحة بقرار منه تعيين مأمورية مختصة لأنشطة أو ممولين أو مكلفين محددين .
الإيصال الالكترونى : المحرر الإلكترونى الصادر من بائع السلعة أو مؤدى الخدمة للمستهلك للسلعة أو المستفيد من الخدمة وفقًا للضوابط والأحكام المحددة بهذه اللائحة .
مقدم الخدمة : الشخص الاعتبارى الحاصل على ترخيص تنفيذ النظام الإلكترونى ، ويتمثل دوره الأساسى كوسيط فى تلقى الفواتير الإلكترونية من مصدرها ، وإرسالها للمصلحة بعد التحقق من استيفائها الشروط الشكلية المقررة قانونًا .
نظام التكويد : نظام يُستخدم فى تصنيف السلع والخدمات ، يتم بموجبه تعيين كود مميز لكل سلعة أو خدمة ليستخدم فى إصدار الفاتورة أو الإيصال الإلكترونى ، ويصدر بتحديد نوع التكويد قرار من رئيس المصلحة .
الشخص المرتبط : كل شخص يرتبط بممول بعلاقة تؤثر فى تحديد وعاء الضريبة بشكل مباشر أو غير مباشر ، سواء من خلال الإدارة أو السيطرة أو الملكية ، وبوجه عام يكون الشخصان مرتبطين إذا كانت العلاقة بينهما تصل إلى حد إمكانية قيام أحد الشخصين أو قيام كلا الشخصين بالتصرف وفقًا لتوجيهات أو طلبات أو اقتراحات أو إرادة الشخص الآخر أو شخص ثالث .
ويُعامل الأشخاص التالى بيانهم بوصفهم أشخاصًا مرتبطين :
1 - الزوج والزوجة والأصول والفروع أو فيما بينهما أو بين بعضهم البعض .
2 - شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3 - شركة الأموال والشخص الذى يملك فيها بشكل مباشر أو غير مباشر ( 50 % ) على الأقل من حقوق التصويت أو الإدارة فى الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4 - أى شركتين أو أكثر يملك أو يحوز شخص آخر ( 50 % ) على الأقل من حقوق التصويت أو الإدارة فى الشركتين ، أو من حقوق توزيع الأرباح فى الشركتين ، أو من حقوق رأس المال فى الشركتين .
وعند تطبيق البنود ( 2 ) أو ( 3 ) أو ( 4 ) من الفقرة السابقة ، فإن الملكية أو الحيازة التى تنسب إلى شخص ما من قِبَل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
ولا يعتبر شخصين مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط فى تحديد وعاء الضريبة بشكل مباشر أو غير مباشر .$m208$,'<<CR>>',chr(13))),
('regulation',286,2021,16,0,'c0254e57cad432e4c4ecca5a56c52d24','bf36387f072f34e44d4ae70a8b384288',replace($m208$فى تطبيق أحكام المادة ( 13 ) من القانون ، يؤدى الممول مبلغا للمصلحة يعادل ( 1 % ) من قيمة المعاملات التى لم يفصح عنها فى إقراره السنوى لضريبة الدخل ، ولا يتجاوز عن تحصيل هذا المبلغ حتى ولو قام الممول بالإفصاح عن هذه المعاملات ضمن الملف المحلى أو الرئيسى .$m208$,'<<CR>>',chr(13)));
INSERT INTO m208_fix VALUES
('regulation',286,2021,39,0,'7744faf8f4709c264dd43d8a572be12d','d2f3159c867ba46f45096938029783e5',replace($m208$يسرى ترخيص مقدم الخدمة لمدة ثلاث سنوات من تاريخ الحصول عليه ، وفى حالة رغبة مقدم الخدمة تجديد ترخيصه لمدة أخرى يتعين عليه تقديم طلب للمصلحة قبل انتهاء مدة الترخيص بثلاثة أشهر على الأقل وبشرط سريان الضمان المالى واستيفاء كافة الشروط اللازمة للترخيص .
وعلى المصلحة اعتماد طلب التجديد خلال مدة الأشهر الثلاثة المشار إليها .
وفى حالة عدم رغبة مقدم الخدمة فى تجديد ترخيصه يتعين عليه تقديم طلب للمصلحة قبل انتهاء مدة الترخيص بثلاثة أشهر على الأقل .
ويجب على مقدم الخدمة حال رغبته فى إنهاء الترخيص قبل انتهاء مدته ، تقديم طلب للمصلحة قبل تاريخ إنهاء الترخيص بثلاثة أشهر وسداد نسبة ( 15 % ) من قيمة الضمان المالى الذى يصدر بتحديده قرار من الوزير .$m208$,'<<CR>>',chr(13))),
('regulation',286,2021,43,0,'293f355a191e50495b73a8841ed0b6ff','bffe909dadec47326932e79846916b2a',replace($m208$يجب عند إصدار الفاتورة الإلكترونية الالتزام بالضوابط الآتية :
1 - استخدام النسق الإلكترونى المعتمد من قِبل المصلحة للفاتورة ( إشعار الخصم / إشعار الإضافة ) .
2 - الالتزام بالأكواد الموحدة للسلع والخدمات والأنشطة ، والمعتمدة لدى المصلحة .
3 - الالتزام بتسجيل كود الفرع مصدر الفاتورة .
4 - الالتزام بإدراج رقم التسجيل للمشترى فى حال كونه ممولاً أو مُكلفًا أو الرقم القومى للمشترى طبقا للبند ( 5 ) من الفقرة الأولى من هذه المادة .
5 - استخدام الممول أو المُكلف شهادة التوقيع الإلكترونى للتوقيع على فواتيره إلكترونيا وإرسالها لمقدم الخدمة أو المصلحة حال كونها مقدما للخدمة ، فور تحريرها وذلك وفقا للمدة التى يصدر بها قرار من رئيس مصلحة الضرائب المصرية .
6 - تسليم الفواتير الإلكترونية فى صورة مرئية ومقروءة فى الحالات التى يكون فيها المشترى غير مسجل بنظام الفاتورة الإلكترونية ، ويحق للمشترى طلب نسخة مطبوعة من مُصدر الفاتورة .
ويجوز للمشترى رفض الفاتورة خلال المدة التى يصدر قرار من رئيس المصلحة بتحديدها وذلك من تاريخ إصدارها . كما يجوز للبائع إلغاء الفاتورة خلال المدة التى يصدر قرار من رئيس المصلحة بتحديدها من تاريخ إصدارها بعد موافقة المشترى على الإلغاء .
وتسرى جميع الضوابط السابقة على إشعارات الخصم وإشعارات الإضافة .$m208$,'<<CR>>',chr(13)));

DO $m208$
DECLARE
  v_expected int := 1202;
  v_total int; v_found int; v_todo int; v_done int; v_skipped int;
  v_art_before int; v_ver_before int; v_upd_art int; v_upd_ver int; v_bad int;
BEGIN
  SELECT count(*) INTO v_total FROM m208_fix;
  IF v_total <> v_expected THEN
    RAISE EXCEPTION '[208] تحميل البيانات ناقص: % من %', v_total, v_expected;
  END IF;

  CREATE TEMP TABLE m208_tgt ON COMMIT DROP AS
    SELECT a.id AS article_id, f.old_md5, f.new_md5, f.new_body, md5(a.body) AS cur_md5
    FROM m208_fix f
    JOIN laws l ON l.country_code = 'EG' AND l.kind = f.kind AND l.law_no = f.law_no AND l.law_year = f.law_year
    JOIN articles a ON a.law_id = l.id AND a.article_no = f.article_no AND a.article_suffix_order = f.suffix;
  SELECT count(*) INTO v_found FROM m208_tgt;
  SELECT count(*) INTO v_done FROM m208_tgt WHERE cur_md5 = new_md5;
  SELECT count(*) INTO v_todo FROM m208_tgt WHERE cur_md5 = old_md5 AND old_md5 <> new_md5;
  v_skipped := v_total - v_done - v_todo;

  SELECT count(*) INTO v_art_before FROM articles;
  SELECT count(*) INTO v_ver_before FROM article_versions;

  -- نسخة احتياطية قبل أى تعديل
  INSERT INTO migration_208_backup (article_id, version_id, old_body)
    SELECT a.id, NULL, a.body FROM m208_tgt t JOIN articles a ON a.id = t.article_id
    WHERE t.cur_md5 = t.old_md5 AND t.old_md5 <> t.new_md5
    ON CONFLICT DO NOTHING;
  INSERT INTO migration_208_backup (article_id, version_id, old_body)
    SELECT v.article_id, v.id, v.body FROM m208_tgt t JOIN article_versions v ON v.article_id = t.article_id
    WHERE md5(v.body) = t.old_md5 AND t.old_md5 <> t.new_md5
    ON CONFLICT DO NOTHING;

  UPDATE article_versions v SET body = t.new_body
    FROM m208_tgt t
    WHERE v.article_id = t.article_id AND md5(v.body) = t.old_md5 AND t.old_md5 <> t.new_md5;
  GET DIAGNOSTICS v_upd_ver = ROW_COUNT;
  UPDATE articles a SET body = t.new_body
    FROM m208_tgt t
    WHERE a.id = t.article_id AND md5(a.body) = t.old_md5 AND t.old_md5 <> t.new_md5;
  GET DIAGNOSTICS v_upd_art = ROW_COUNT;

  -- ختام 1: لا تغيّر فى عدد المواد/النسخ، وكل ما عُدِّل مطابق تماماً للنص المُختبَر
  IF (SELECT count(*) FROM articles) <> v_art_before OR (SELECT count(*) FROM article_versions) <> v_ver_before THEN
    RAISE EXCEPTION '[208] تغيّر عدد المواد أو النسخ';
  END IF;
  IF v_upd_art <> v_todo THEN
    RAISE EXCEPTION '[208] عدد المواد المعدلة % لا يطابق المتوقع %', v_upd_art, v_todo;
  END IF;
  SELECT count(*) INTO v_bad FROM m208_tgt t JOIN articles a ON a.id = t.article_id
   WHERE t.cur_md5 IN (t.old_md5, t.new_md5) AND md5(a.body) <> t.new_md5;
  IF v_bad <> 0 THEN
    RAISE EXCEPTION '[208] % مادة نصها بعد التعديل لا يطابق النص المُختبَر', v_bad;
  END IF;

  -- ختام 2: لا بقايا من العيوب فى المواد المعدلة
  SELECT count(*) INTO v_bad FROM m208_tgt t JOIN articles a ON a.id = t.article_id
   WHERE md5(a.body) = t.new_md5
     AND (a.body ~ '[٠-٩۰-۹٪یکھ]' OR a.body ~ '[-]' OR position(E'\f' in a.body) > 0
          OR a.body ~ 'الوقائع[ \t]+المصرية[ \t]*[–-][ \t]*العدد[^\n]*تابع');
  IF v_bad <> 0 THEN
    RAISE EXCEPTION '[208] % مادة فيها بقايا من العيوب المعالَجة', v_bad;
  END IF;

  RAISE NOTICE '[208] مواد مستهدفة: % | وُجدت: % | عُدِّلت الآن: % | معدَّلة سابقاً: % | نسخ عُدِّلت: % | تُخطّيت (نص مختلف أو غير موجودة): %',
    v_total, v_found, v_upd_art, v_done, v_upd_ver, v_skipped;
  IF v_skipped > 0 THEN
    RAISE WARNING '[208] % مادة تُخطّيت لأن نصها الحالى يختلف عن المتوقع أو لم توجد — راجعها يدوياً', v_skipped;
  END IF;
END
$m208$;
